-- ==========================================================================
__UAI_MODULES["agent/session"] = (function()
-- Sessions: the object the interface talks to, and the thread list behind it.
--
-- A session owns a conversation, an event stream and a busy flag. The loop is a
-- pure function over a session, so a subagent is just another session with a
-- smaller tool set and no interface attached -- which is why this module, not the
-- loop, is where threads and persistence live.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local fsx = env.require("runtime/fsx")
	local attachments = env.require("runtime/attachments")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local context = env.require("agent/context")
	local transcript = env.require("agent/transcript")
	local hooks = env.require("agent/hooks")
	local permissions = env.require("agent/permissions")
	local state = env.require("agent/state")
	local folderStore = env.require("runtime/conversation_folders")
	local accounting = env.require("agent/stats")
	local metadata = env.require("runtime/conversation_metadata")
	local draftStore = env.require("runtime/draft_store")
	local transcriptSearch = env.require("runtime/transcript_search")
	local workflow = env.require("runtime/script_workflow")

	local THREAD_DIR = "sessions"
	-- Disk history survives eviction. Unsaved/ephemeral threads stay in memory.
	local THREAD_LIMIT = 64
	local running, alive = 0, true
	local historyBusy = {}
	local function historyIO(id, operation, ...)
		historyBusy[id] = (historyBusy[id] or 0) + 1
		local ok, result, detail = pcall(operation, ...)
		local pending = historyBusy[id] - 1
		historyBusy[id] = pending > 0 and pending or nil
		if not ok then return false, tostring(result) end
		return result, detail
	end
	local function deleteHistory(id)
		return historyIO(id, fsx.delete, THREAD_DIR .. "/" .. id .. ".json")
	end

	-- How long a pasted message may be before it stops being a message. A long script
	-- pasted into the composer is reference material, not a request: sent whole it
	-- drowns the turn, and the model's only use for it is file_read anyway. Over this
	-- the body goes to pastes/ and the conversation carries a pointer -- the user's
	-- words plus "the code is in this file" -- which is the same information for a
	-- fraction of the context.
	local PASTE_CAP = attachments.INLINE_LIMIT

	local M = {
		threads = {},
		activeId = nil,
		listChanged = signal.new("threads"),
		-- Every event from every session, with the session it came from.
		--
		-- A per-session stream is what a panel showing one conversation wants, and it is
		-- what the transcript uses. It is the wrong shape for anything that has to answer
		-- a conversation nobody is looking at -- and the permission prompt is exactly
		-- that: it subscribed to the active session only, so a second conversation left
		-- running in the background raised a prompt into a stream with no listener and sat
		-- there until its own deadline denied every call it had asked for.
		anyEvent = signal.new("session:any"),
		usageChanged = accounting.changed,
	}

	-- Presentation reads recorded counters through the session boundary.
	function M.keyUsage(record, index) return accounting.keyUsage(record, index) end
	function M.conversationUsage(session) return accounting.conversationUsage(session) end

	-- Published for the composer's paste detection, so the two halves of the feature
	-- share one number rather than each keeping a copy that drifts.
	M.PASTE_CAP = PASTE_CAP
	local function markDirty(session)
		session.persistenceDirty = true
		session.persistenceRevision = (session.persistenceRevision or 0) + 1
	end

	local function placeNumber(value)
		local number = tonumber(value)
		return number and number == number and number >= 0 and number < 9007199254740991 and number == math.floor(number) and number or 0
	end

	local function gameFolderId(id) return "game:" .. string.format("%.0f", placeNumber(id)) end
	local function folderPlace(id)
		if type(id) ~= "string" then return nil end
		local raw = id:match("^game:(%d+)$")
		local number = raw and tonumber(raw)
		if number and gameFolderId(number) == id then return number end
		return nil
	end

	local function validDestination(id)
		return type(id) == "string" and (id == "universal" or folderPlace(id) ~= nil or folderStore.get(id) ~= nil)
	end

	local function folderFor(session)
		local place = env.require("runtime/place")
		local id = session.folderId or gameFolderId(session.placeId)
		local placeId = folderPlace(id)
		if placeId ~= nil then
			local current = placeId == place.id
			local label = current and place.label() or nil
			if not label then
				local newest = -1
				for _, candidate in pairs(M.threads) do
					if placeNumber(candidate.placeId) == placeId and type(candidate.placeName) == "string"
						and util.trim(candidate.placeName) ~= "" and (candidate.updatedAt or 0) > newest then
						label, newest = candidate.placeName, candidate.updatedAt or 0
					end
				end
				if not label and placeNumber(session.placeId) == placeId then label = session.placeName end
			end
			if type(label) ~= "string" or util.trim(label) == "" then label = placeId > 0 and ("Place " .. string.format("%.0f", placeId)) or "Unknown place" end
			return { id = id, kind = "game", placeId = placeId, label = label, current = current }
		end
		local folder = folderStore.get(id)
		if folder then folder.current = false; return folder end
		-- Deleted folders also cover archived conversations outside the 64 loaded
		-- threads. Their files need no rewrite, and an unreadable catalog cannot
		-- erase the original association merely because a conversation was saved.
		return { id = "universal", kind = "universal", label = "Universal", current = false }
	end

	local FILTER_OPTIONS = { "toolFilter", "toolGroups", "toolExclude" }
	local POLICY_OPTIONS = { "toolFilter", "toolGroups", "toolExclude", "maxTurns", "budgetSeconds", "unlimited", "stream" }
	local function validateOptions(opts)
		if opts == nil then opts = {} end
		if type(opts) ~= "table" then return nil, "session options must be a table" end
		if opts.id ~= nil and (type(opts.id) ~= "string" or #opts.id > 120 or not opts.id:match("^[%w_-]+$")) then
			return nil, "session id must contain 1-120 letters, digits, underscores or hyphens"
		end
		if opts.title ~= nil and type(opts.title) ~= "string" then return nil, "session title must be a string" end
		if opts.folderId ~= nil and not validDestination(opts.folderId) then return nil, "conversation folder does not exist" end
		for _, key in ipairs({ "ephemeral", "headless", "stream", "unlimited", "activate" }) do
			if opts[key] ~= nil and type(opts[key]) ~= "boolean" then return nil, key .. " must be a boolean" end
		end
		for _, key in ipairs({ "maxTurns", "budgetSeconds", "depth" }) do
			local value = opts[key]
			if value ~= nil then
				if type(value) ~= "number" or value ~= value or value == math.huge or value == -math.huge then
					return nil, key .. " must be a finite number"
				end
				if key == "depth" then
					if value < 0 or value ~= math.floor(value) then return nil, "depth must be a nonnegative integer" end
				elseif key == "maxTurns" then
					if value < 1 or value ~= math.floor(value) then return nil, "maxTurns must be a positive integer" end
				elseif value <= 0 then return nil, "budgetSeconds must be positive" end
			end
		end
		local options = util.copy(opts)
		for _, key in ipairs(FILTER_OPTIONS) do
			local filter = opts[key]
			if filter ~= nil then
				if type(filter) ~= "table" then return nil, key .. " must be a map of names to booleans" end
				local copied = {}
				for name, allowed in pairs(filter) do
					if type(name) ~= "string" or util.trim(name) == "" or type(allowed) ~= "boolean" then
						return nil, key .. " must be a map of names to booleans"
					end
					copied[name] = allowed
				end
				options[key] = copied
			end
		end
		return options
	end

	function M.create(opts)
		if not alive then return nil, "client is unloaded" end
		local checked, why = validateOptions(opts)
		if not checked then return nil, why end
		opts = checked
		local place = env.require("runtime/place")
		local session = {
			id = opts.id or util.uid("s"),
			title = opts.title or "New chat",
			ctx = context.new(),
			events = signal.new("session"),
			status = "Ready",
			busy = false,
			depth = opts.depth or 0,
			maxTurns = opts.maxTurns,
			toolFilter = opts.toolFilter,
			toolGroups = opts.toolGroups,
			-- Tools this conversation must not be offered at all -- not denied, absent.
			-- The registry's definitions() reads it; the field is opt-in so a session
			-- that wants everything (the main conversation) does not have to say so.
			toolExclude = opts.toolExclude,
			budgetSeconds = opts.budgetSeconds,
			-- Set by whoever created the session, and read by the loop in place of the
			-- global switch: a subagent carries its own budget, so lifting it is a
			-- decision the dispatcher takes per child rather than one a conversation
			-- inherits from a setting.
			unlimited = opts.unlimited == true,
			stream = opts.stream,
			headless = opts.headless == true,
			ephemeral = opts.ephemeral == true,
			-- Which place the conversation happened in. A client is loaded into one game
			-- at a time and the transcripts outlive the visit, so without this the list
			-- is a flat pile of titles with no way to tell last week's game from this
			-- one. Recorded at creation rather than read at display time, because by the
			-- time anyone reads it they are somewhere else.
			placeId = placeNumber(opts.placeId or place.id),
			placeName = opts.placeName or (placeNumber(opts.placeId or place.id) == place.id and place.label() or nil),
			folderId = opts.folderId or gameFolderId(opts.placeId or place.id),
			createdAt = clock.ms(),
			updatedAt = clock.ms(),
			turns = 0,
			metadata = metadata.restore(),
			viewReaders = {},
			toolEpoch = {},
			abortFlag = false,
			log = {},
			logBytes = 0,
			persistenceDirty = true,
			persistenceRevision = 0,
			-- The plan for this conversation's job. agent/state owns the shape of it;
			-- the list lives here so two conversations cannot overwrite each other's.
			todos = {},
		}
		local queue = env.require("agent/message_queue").new(session, function() if alive then M.listChanged:fire() end end)
		local unloaded = false
		local callbacks, runPrepared, startReady
		local function preparing() session.preparing = queue.preparing() and true or nil end
		local function validateFiles(files, needTools, aborted)
			if #files == 0 and not needTools then return true end
			local readable = false
			for _, tool in ipairs(env.require("agent/registry").definitions({ only = session.toolFilter,
				groups = session.toolGroups, exclude = session.toolExclude })) do
				if tool["function"].name == "file_read" then readable = true; break end
			end
			if not readable then return nil, "Enable the Files tools and file storage to send long inputs as files." end
			for _, file in ipairs(files) do
				local content, err = fsx.readUser(file.path)
				if not content or not env.require("runtime/attachment_identity").matches(file, content, aborted) then return nil, "attachment is missing or changed: " .. file.path .. ". " .. tostring(err or "Attach it again.") end
			end
			return true
		end
		local function takeReady(deadline)
			local access = config.accessProblem()
			if access then queue.hold(access); return nil end
			local head = queue.peek()
			if not head or head.state ~= "queued" or queue.held() then return nil end
			if head.needsValidation then
				local ok, valid, why = pcall(function()
					if #head.images > 0 and not env.require("net/bridge_connection").enabled() then return nil, "Connect the web bridge to resume these images" end
					return validateFiles(head.files, false, function() return not head.active or session.aborted() or deadline and clock.ms() >= deadline end)
				end)
				if not head.active or queue.peek() ~= head then return nil end
				if not ok or not valid then queue.hold(ok and why or "Unable to verify queued attachments"); return nil end
				head.needsValidation = false
			end
			if session.aborted() or deadline and clock.ms() >= deadline then return nil end
			access = config.accessProblem()
			if access then queue.hold(access); return nil end
			return queue.take()
		end

		session.transcript = transcript.new(session)
		session.appendLog = session.transcript.append
		function session.emit(kind, payload)
			if session.removed or not alive then return end
			markDirty(session)
			payload = util.copy(payload or {})
			if kind == "error" then payload.message = env.require("runtime/support").error(payload.message) end
			if kind == "tool:error" or kind == "tool:result" and payload.ok == false then
				payload.text = env.require("runtime/support").error(payload.text or payload.error)
			end
			if kind == "request:done" and payload.error then payload.error = env.require("runtime/support").error(payload.error) end
			payload.kind = kind
			payload.at = clock.ms()
			session.updatedAt = payload.at
			if kind == "status" then session.status = payload.text or session.status end
			if session.acceptingMessages and (kind == "error" or kind == "turn:end" and payload.failed) then
				session.turnFailure = payload.message or payload.text or "The current turn failed"
			end
			if kind == "request:start" then session.liveRequest, session.livePreview = payload, nil
			elseif kind == "assistant:preview" then session.livePreview = payload
			elseif kind == "request:done" then session.liveRequest = nil; if payload.error then session.livePreview = nil end
			elseif kind == "assistant:complete" or kind == "abort" or kind == "error" or kind == "cleared" or (kind == "status" and payload.text == "Ready") then
				session.liveRequest, session.livePreview = nil, nil
			end
			if not session.headless then
				local retained = session.appendLog(payload)
				payload.transcriptId = retained and retained.transcriptId or nil
			end
			local changedMetadata = metadata.observe(session.metadata, payload, next(session.viewReaders) ~= nil)
			hooks.run("onEvent", { session = session, event = payload })
			session.events:fire(payload)
			M.anyEvent:fire(session, payload)
			if changedMetadata then M.listChanged:fire() end
		end

		function session.aborted()
			return session.abortFlag == true or session.removed == true or not alive
		end

		function session.toolContext()
			-- A later send clears abortFlag. Old tool workers must not come back to
			-- life when that happens after a stopped or failed turn.
			local epoch = session.toolEpoch
			local cancelled = false
			local function aborted()
				cancelled = cancelled or session.toolEpoch ~= epoch or session.aborted()
				return cancelled
			end
			return {
				env = env,
				session = session,
				depth = session.depth,
				emit = function(kind, text)
					if not aborted() then session.emit(kind, type(text) == "table" and text or { text = text }) end
				end,
				progress = function(text)
					if not aborted() then session.emit("tool:progress", { text = tostring(text) }) end
				end,
				aborted = aborted,
			}
		end

		function session.queueSnapshot() return queue.snapshot() end
		function session.serialiseQueue() return queue.serialise() end
		function session.restoreQueue(saved)
			local ok, why = queue.restore(saved)
			if ok then markDirty(session) end
			return ok, why
		end
		function session.removeQueued(id)
			local ok, why = queue.remove(id)
			preparing()
			if ok then session.persist() end
			if ok then startReady() end
			return ok, why
		end
		function session.hasQueued() return queue.pending() > 0 end
		local function changeQueue(operation, ...)
			if not alive or session.removed or session.clearingMessages then return false, "Conversation is unavailable" end
			local ok, why = operation(...)
			if ok then session.persist(); startReady() end
			return ok, why
		end
		function session.editQueued(id, text, expected) return changeQueue(queue.edit, id, text, expected) end
		function session.moveQueued(id, direction, neighborId) return changeQueue(queue.move, id, direction, neighborId) end
		function session.clearQueued(ids) return changeQueue(queue.clearSelected, ids) end
		-- Called only after a complete assistant/tool exchange, never while its
		-- inference or native tools are running. A preparing head retains order.
		function session.consumeQueued(waitForPreparation, deadline)
			local count = 0
			while count < 16 and not session.aborted() and not queue.held() do
				local access = config.accessProblem()
				if access then queue.hold(access); break end
				if deadline and clock.ms() >= deadline then break end
				local head = queue.peek()
				if not head then break end
				if head.state == "preparing" then
					if not waitForPreparation then break end
					clock.wait(0.03)
				else
					local entry = takeReady(deadline)
					if not entry then break end
					if entry.onDone and callbacks then callbacks[#callbacks + 1] = { id = entry.id, fn = entry.onDone } end
					session.ctx.pushUser(entry.text, entry.images)
					session.emit("user", { text = entry.text, messageId = entry.id, queued = true })
					queue.consumed(entry)
					count = count + 1
				end
			end
			if count > 0 then session.persist() end
			return count
		end
		function session.resumeQueue()
			if not alive or session.removed then return false, "conversation no longer exists" end
			local access = config.accessProblem()
			if access then return false, access end
			if session.clearingMessages then return false, "conversation is being cleared" end
			if session.cancellingMessages then return false, "conversation is being stopped" end
			if session.busy then return false, "The current turn is still working" end
			if queue.pending() == 0 then return false, "No queued messages to resume" end
			if running >= 8 then return false, "Eight native session workers are already active; wait for a turn to finish" end
			queue.release()
			if not queue.peek() or queue.peek().state == "preparing" or session.busy then return true end
			return startReady()
		end

		-- A single worker owns context and tools. Further sends reserve a pending
		-- message and join that worker only at a safe response/tool boundary.
		function session.send(text, onDone, files, images, options)
			if not alive then return false, "client is unloaded" end
			local access = config.accessProblem()
			if access then return false, access end
			if session.removed then return false, "conversation no longer exists" end
			if session.clearingMessages then return false, "conversation is being cleared" end
			if session.cancellingMessages then return false, "conversation is being stopped" end
			if onDone ~= nil and type(onDone) ~= "function" then return false, "completion callback must be a function" end
			if options ~= nil and type(options) ~= "table" then return false, "invalid send options" end
			options = options or {}
			for key in pairs(options) do if key ~= "messageId" then return false, "unknown send option: " .. tostring(key) end end
			if options.messageId ~= nil and type(options.messageId) ~= "string" then return false, "invalid message id" end
			local id = options.messageId or util.uid("message")
			local receipt = queue.receipt(id)
			if receipt then return true, receipt end
			if session.busy and (not session.acceptingMessages or session.abortFlag) then return false, "Wait for the current operation to finish stopping" end
			if not session.busy and running >= 8 then return false, "Eight native session workers are already active; wait for a turn to finish" end
			text = tostring(text or "")
			if #text > attachments.MAX_BYTES then return false, "attachments support up to 10 MiB; split this input into smaller files" end
			local validated, imageError = env.require("runtime/images").validate(images, session.id)
			if not validated then return false, imageError end
			images = validated
			if #images > 0 and not env.require("net/bridge_connection").enabled() then return false, "Connect the web bridge to send these images" end
			local clean = util.trim(text)
			if clean == "" and #images > 0 then clean = "Please look at the attached " .. (#images == 1 and "image." or "images."); text = clean end
			if clean == "" then return false, "nothing to send" end
			files = files or {}
			if type(files) ~= "table" or not util.isArray(files) or #files > 32 then return false, "invalid attachment list" end
			local references = {}
			for _, file in ipairs(files) do
				if type(file) ~= "table" or type(file.path) ~= "string" or #file.path == 0 or #file.path > 1000
					or type(file.bytes) ~= "number" or file.bytes ~= file.bytes or file.bytes < 0 or file.bytes % 1 ~= 0
					or file.bytes > attachments.MAX_BYTES then return false, "invalid attachment reference" end
				if file.sha256 ~= nil and not env.require("runtime/attachment_identity").valid(file.sha256) then return false, "invalid attachment digest" end
				references[#references + 1] = { path = file.path, bytes = file.bytes, sha256 = file.sha256 }
			end
			files = references

			local title = util.ellipsis(clean, 42)
			local resumeHeld = not session.busy and queue.held()
			local entry, reserveError = queue.reserve(clean, files, images, onDone, id, session.busy or queue.pending() > 0, #text)
			if not entry then return false, reserveError end
			files = entry.files
			local function preparationAborted() return not alive or session.removed or not entry.active end
			preparing()
			-- This boundary also covers Quick Chat, bridge clients and host scripts.
			-- Never turn a failed upload into an enormous inference request.
			if #text > PASTE_CAP or #files > 0 then
				local ok, prepared, why = pcall(function()
					local valid, validationError = validateFiles(files, #text > PASTE_CAP, preparationAborted)
					if not valid then return nil, validationError end
					if #text <= PASTE_CAP then return clean end
					local saved, err = attachments.save(text, nil, preparationAborted)
					if not saved then return nil, err end
					if #entry.files >= 32 then return nil, "A message supports up to 32 file attachments" end
					entry.files[#entry.files + 1] = { path = saved.path, bytes = saved.bytes, sha256 = saved.sha256 }
					return attachments.reference(saved) .. "\n\nRead this file for the user's complete input, including any request at the end."
				end)
				if not entry.active then preparing(); return false, "message preparation was cancelled; your draft was kept" end
				if not ok or not prepared then
					local failure = ok and why or tostring(prepared)
					queue.reject(entry, failure); preparing(); startReady(); return false, failure
				end
				clean = prepared
			end
			access = config.accessProblem()
			if access then queue.reject(entry, access); preparing(); return false, access end
			local accepted, commitError = queue.commit(entry, clean)
			preparing()
			if not accepted then queue.reject(entry, commitError); preparing(); startReady(); return false, commitError end
			if session.title == "New chat" and not session.named then session.title = title end
			session.persist()
			if not session.busy and not queue.held() then startReady()
			elseif not session.busy and resumeHeld then session.resumeQueue() end
			return true, accepted
		end

		startReady = function()
			if not alive or session.removed or session.clearingMessages or session.busy or queue.held() then return false end
			local head = queue.peek()
			if not head or head.state ~= "queued" then return false end
			local started, why = runPrepared()
			if not started then queue.hold(why) end
			return started, why
		end

		runPrepared = function()
			if not alive or session.removed then return false, "conversation no longer exists" end
			local access = config.accessProblem()
			if access then return false, access end
			if session.busy then return false, "already working" end
			if running >= 8 then return false, "Eight native session workers are already active; wait for a turn to finish" end
			local head = queue.peek()
			if not head or head.state ~= "queued" or queue.held() then return false, "The first queued message is still being prepared" end
			running = running + 1
			session.busy = true
			session.acceptingMessages = true
			session.turnFailure = nil
			session.abortFlag = false
			session.toolEpoch = {}
			local completed = {}
			callbacks = completed
			-- The list is where "this one is still working" is visible while you are
			-- reading another conversation, so a busy flag that moves is a list change.
			M.listChanged:fire()

			task.spawn(function()
				local ok, reply = pcall(function()
					local entry = takeReady()
					if not entry then return nil end
					session.turns = session.turns + 1
					if entry.onDone then completed[#completed + 1] = { id = entry.id, fn = entry.onDone } end
					session.emit("user", { text = entry.text, messageId = entry.id, queued = entry.queued })
					queue.consumed(entry)
					return env.require("agent/loop").run(session, entry.text, entry.images)
				end)
				if not ok then session.abortFlag = true end
				if not ok then session.turnFailure = "The native agent stopped after an internal error" end
				-- A turn owns its background children through its terminal settlement,
				-- including limits and provider failures. Intermediate tools do not end
				-- that lifetime; normal completion has already collected their reports.
				local subagents = env.loadedModules and env.loadedModules["agent/subagent"]
				if subagents then
					local unfinished = #subagents.pending(session) > 0
					subagents.stopAll(session)
					if unfinished then session.toolEpoch = {} end
				end
				session.acceptingMessages = false
				if callbacks == completed then callbacks = nil end
				local finalStatus = not ok and "failed" or session.abortFlag and "cancelled" or session.turnFailure and "failed" or "succeeded"
				if queue.pending() > 0 and finalStatus ~= "succeeded" then queue.hold(finalStatus == "cancelled" and "Stopped before these follow-ups were applied" or session.turnFailure) end
				if session.removed or not alive then running = math.max(0, running - 1); session.busy = false; return end
				-- Only this conversation's prompts. It used to clear every pending
				-- request in the client, so one conversation finishing a turn silently
				-- denied whatever another was waiting on -- and a denied write is
				-- reported to that model as the user refusing it.
				permissions.denyAll(nil, session)
				-- Its questions too: a turn that ended still had an ask on screen, which
				-- the user could then answer for a conversation that had moved on.
				local asks = env.loadedModules and env.loadedModules["ui/panels/ask"]
				if asks then pcall(asks.sweep, session) end
				if not ok then
					log.error("session", "loop crashed", reply)
					session.emit("error", { message = "The native agent stopped after an internal error", fatal = true })
					reply = "The native agent stopped after an internal error. Your conversation is retained."
					session.emit("turn:end", { text = reply, failed = true })
					session.emit("status", { text = "Ready" })
				end
				M.persist(session)
				running = math.max(0, running - 1)
				session.busy = false
				M.listChanged:fire()
				for _, callback in ipairs(completed) do
					if not session.removed then pcall(callback.fn, reply, { messageId = callback.id,
						status = finalStatus }) end
				end
				-- Terminal-event sends belong to the next turn. Start only after this
				-- worker's cleanup and callbacks; a preparing head starts on commit.
				startReady()
			end)
			return true
		end

		function session.abort()
			if session.cancellingMessages or unloaded then return false end
			if not alive then unloaded = true end
			session.cancellingMessages = true
			session.toolEpoch = {}
			session.abortFlag = not alive or session.busy == true
			local wasPreparing = queue.preparing()
			queue.cancelPreparations("message preparation was cancelled; your draft was kept")
			preparing()
			if session.removed or not alive then
				-- Idle saved histories need no serialization on unload. Save pending
				-- follow-ups once before cancelling their in-memory callbacks.
				if not session.removed and session.persistenceDirty then session.persist() end
				queue.clear(session.removed and "conversation removed" or "client unloaded")
			else
				queue.hold("Stopped before these follow-ups were applied")
				session.persist()
			end
			local capture = env.loadedModules and env.loadedModules["runtime/remote_capture"]
			if capture then capture.revokeAgent(session.id) end
			local subagents = env.loadedModules and env.loadedModules["agent/subagent"]
			local stoppedChildren = subagents and subagents.stopAll(session) or 0
			local loops = env.loadedModules and env.loadedModules["runtime/chatloops"]
			local stoppedLoops = loops and loops.stop(nil, session) or 0
			if not session.busy then session.cancellingMessages = nil; return wasPreparing or stoppedLoops > 0 or stoppedChildren > 0 end
			session.abortFlag = true
			session.emit("status", { text = "Stopping" })
			permissions.denyAll("aborted", session)
			local asks = env.loadedModules and env.loadedModules["ui/panels/ask"]
			if asks then pcall(asks.sweep, session) end
			session.cancellingMessages = nil
			return true
		end

		-- Fold older turns into the summary now, on the user's command, without
		-- starting a turn. Reuses the busy interlock so a send cannot interleave with
		-- the mutation, and persists the trimmed conversation when it changes.
		function session.compact(onDone)
			local access = config.accessProblem()
			if access then return false, access end
			if session.busy or session.preparing then return false, "already working" end
			if session.removed then return false, "conversation no longer exists" end
			if not alive or running >= 8 then return false, "Eight native session workers are already active; wait for a turn to finish" end
			running = running + 1
			session.busy = true
			session.abortFlag = false
			session.emit("status", { text = "Compacting" })
			M.listChanged:fire()
			task.spawn(function()
				local ok, summary, reason = pcall(function()
					local note, before, after, why = env.require("agent/loop").compact(session)
					return note, why
				end)
				running = math.max(0, running - 1)
				session.busy = false
				if session.removed or not alive then return end
				session.emit("status", { text = "Ready" })
				if not ok then log.error("session", "manual compaction crashed", summary) end
				if ok and summary then M.persist(session) end
				M.listChanged:fire()
				if onDone then pcall(onDone, ok and summary ~= nil, ok and summary or nil, ok and reason or tostring(summary)) end
			end)
			return true
		end

		function session.clear()
			if session.busy then return false, "Stop this turn before clearing its conversation" end
			session.clearingMessages = true
			queue.clear("conversation cleared")
			session.preparing = nil
			attachments.clearUploads(session.id)
			local loops = env.loadedModules and env.loadedModules["runtime/chatloops"]
			if loops then loops.stop(nil, session) end
			local subagents = env.loadedModules and env.loadedModules["agent/subagent"]
			if subagents then subagents.stopAll(session) end
			session.ctx.clear()
			session.transcript.reset()
			session.viewState = nil
			session.turns = 0
			session.toolEpoch = {}
			session.abortFlag = false
			session.title = "New chat"
			session.workflow = nil
			-- The plan goes with the conversation it belonged to.
			state.clearTodos(session)
			session.emit("cleared", {})
			session.emit("status", { text = "Ready" })
			M.persist(session)
			session.clearingMessages = nil
		end

		-- A title the user typed wins over the one derived from the first message, and
		-- keeps winning: the derivation only ever fires while the title is still the
		-- placeholder.
		function session.rename(title)
			local clean = util.ellipsis(util.trim(title), 60)
			if clean == "" then return false, "a conversation needs a title" end
			session.title = clean
			session.named = true
			M.listChanged:fire()
			M.persist(session)
			return true
		end

		function session.setPinned(value)
			if session.removed then return false end
			session.metadata.pinned = value == true
			markDirty(session); M.listChanged:fire(); session.persist()
			return true
		end
		function session.markRead()
			if not metadata.read(session.metadata) then return false end
			markDirty(session); M.listChanged:fire()
			return true
		end
		function session.setViewed(owner, value)
			if owner == nil then return end
			session.viewReaders[owner] = value == true and true or nil
			if value then session.markRead() end
		end
		local saveDraftLater, cancelDraftSave = clock.debounce(function()
			if alive and not session.removed then session.persist() end
		end, 1.5)
		session.cancelDraftSave = cancelDraftSave
		local saveWorkflowLater, cancelWorkflowSave = clock.debounce(function()
			if alive and not session.removed then session.persist() end
		end, 0.5)
		session.cancelWorkflowSave = cancelWorkflowSave
		function session.setDraft(value)
			if session.removed or not alive then return false, "Conversation is unavailable" end
			local saved, why = draftStore.snapshot(value)
			if why then session.draftError = why; return false, why end
			local changedPresence = (session.draft ~= nil) ~= (saved ~= nil)
			session.draft, session.draftError = saved, nil
			markDirty(session); saveDraftLater()
			if changedPresence then M.listChanged:fire() end
			return true
		end
		function session.searchTranscript(query, options) return transcriptSearch.page(session.log, query, options) end
		function session.setWorkflow(value, options)
			if session.removed or not alive then return false, "Conversation is unavailable" end
			local validated, why = workflow.restore(value)
			if value ~= nil and not validated then return false, why or "Invalid script workflow" end
			session.workflow = validated
			session.emit("workflow:changed", { version = 1 })
			M.listChanged:fire()
			if options and options.deferSave == true then saveWorkflowLater()
			else cancelWorkflowSave(); session.persist() end
			return true
		end

		-- A title the agent chose for the thread, from what it turned out to be
		-- about. Deliberately not `rename`: naming the conversation stays the
		-- user's move, so a name they typed is refused outright and `named` is
		-- left alone -- another turn may refine the agent's own title, and the
		-- first-message fallback still belongs to the user, not to the agent.
		function session.renameByAgent(title)
			if session.named then return false, "the user named this conversation" end
			if session.headless then return false, "a subagent has no conversation title to set" end
			local clean = util.ellipsis(util.trim(tostring(title or "")), 60)
			if clean == "" then return false, "a title is required" end
			if clean == session.title then return true, clean end
			session.title = clean
			M.listChanged:fire()
			M.persist(session)
			return true, clean
		end

		-- Nothing about this conversation is written to disk. The composer's isolation
		-- toggle is what turns it on, for the same reason a worktree exists: somewhere
		-- to try something without it becoming part of the history.
		function session.setEphemeral(value)
			if session.removed or not alive then return false end
			session.ephemeral = value == true
			if session.ephemeral and fsx.enabled then
				deleteHistory(session.id)
			else
				M.persist(session)
			end
			M.listChanged:fire()
			return session.ephemeral
		end

		-- Mid-turn checkpoint. A turn used to reach disk only when it settled, so a
		-- host crash during a long tool run lost the prompt and every completed step.
		-- The loop calls this at step boundaries; M.persist still refuses headless,
		-- child, ephemeral and removed sessions, and a failed write never ends a turn.
		function session.persist()
			local ok, saved = pcall(M.persist, session)
			if not ok then log.warn("session", "checkpoint failed", saved) end
			return ok and saved or false
		end

		function session.stats()
			local stats = session.ctx.stats()
			stats.busy = session.busy
			stats.turns = session.turns
			stats.todos = state.todoCounts(session)
			return stats
		end

		return session
	end

	-- Threads ---------------------------------------------------------------

	function M.current()
		if not alive then return nil, "client is unloaded" end
		if M.activeId and M.threads[M.activeId] then return M.threads[M.activeId] end
		return M.newThread()
	end

	function M.newThread(opts)
		if opts ~= nil and type(opts) ~= "table" then return nil, "session options must be a table" end
		if opts and opts.id ~= nil and M.threads[opts.id] then return nil, "session id already exists" end
		local session, why = M.create(opts)
		if not session then return nil, why end
		if M.threads[session.id] then return nil, "session id already exists" end
		if historyBusy[session.id] then return nil, "session history is still being saved or removed; try again shortly" end
		if fsx.enabled and fsx.exists(THREAD_DIR .. "/" .. session.id .. ".json") then
			return nil, "session id already exists on disk but is not loaded; choose a different id"
		end
		M.threads[session.id] = session
		if not opts or opts.activate ~= false then M.activeId = session.id end
		M.trimThreads(session)
		M.listChanged:fire()
		return session
	end

	function M.get(id)
		if not alive or type(id) ~= "string" then return nil end
		local session = M.threads[id]
		return session and not session.removed and session or nil
	end

	-- Open a stable host identity without replacing a live worker or stealing the
	-- native view's selection. Options apply only when the conversation is created.
	function M.open(id, opts)
		if not alive then return nil, "client is unloaded" end
		if type(id) ~= "string" or #id > 120 or not id:match("^[%w_-]+$") then
			return nil, "session id must contain 1-120 letters, digits, underscores or hyphens"
		end
		local options, why = validateOptions(opts)
		if not options then return nil, why end
		local existing = M.get(id)
		if existing then
			if options.activate == true then M.switch(id) end
			return existing, false
		end
		options.id, options.activate = id, options.activate == true
		local session, createdWhy = M.newThread(options)
		if not session then return nil, createdWhy end
		return session, true
	end

	function M.switch(id)
		if not M.threads[id] then return false end
		M.activeId = id
		M.threads[id].markRead()
		M.listChanged:fire()
		return true
	end

	function M.list()
		local out = {}
		for _, session in pairs(M.threads) do out[#out + 1] = session end
		table.sort(out, function(a, b)
			local ap, bp = a.metadata and a.metadata.pinned == true, b.metadata and b.metadata.pinned == true
			if ap ~= bp then return ap end
			if a.updatedAt ~= b.updatedAt then return (a.updatedAt or 0) > (b.updatedAt or 0) end
			return a.id < b.id
		end)
		return out
	end

	-- The conversations currently running a turn, newest activity first.
	--
	-- Switching conversation does not stop the one you left -- its loop is on its own
	-- thread and keeps going -- so more than one can be working at a time, and the
	-- interface needs to be able to say which. Anything that reads "is the agent
	-- busy" from the active session alone is asking the wrong question.
	function M.busy()
		local out = {}
		for _, session in ipairs(M.list()) do
			if session.busy then out[#out + 1] = session end
		end
		return out
	end

	function M.busyCount()
		return #M.busy()
	end

	-- Folder organization never changes a conversation's recorded game or the
	-- runtime environment sent to the model. Empty destinations remain reachable.
	function M.groups()
		local place = env.require("runtime/place")
		local byId, order = {}, {}
		local function add(folder)
			if byId[folder.id] then return byId[folder.id] end
			folder.current = folder.current == true
			folder.sessions, folder.updatedAt = {}, 0
			byId[folder.id], order[#order + 1] = folder, folder
			return folder
		end
		add(folderFor({ folderId = gameFolderId(place.id) }))
		add(folderFor({ folderId = "universal" }))
		for _, folder in ipairs(folderStore.list()) do add(folder) end
		for _, session in ipairs(M.list()) do
			local group = add(folderFor(session))
			group.sessions[#group.sessions + 1] = session
			if (session.updatedAt or 0) > group.updatedAt then group.updatedAt = session.updatedAt or 0 end
		end
		table.sort(order, function(a, b)
			if a.current ~= b.current then return a.current end
			if a.updatedAt ~= b.updatedAt then return a.updatedAt > b.updatedAt end
			if tostring(a.label) ~= tostring(b.label) then return tostring(a.label) < tostring(b.label) end
			return a.id < b.id
		end)
		return order
	end

	function M.folders()
		local out = {}
		for _, group in ipairs(M.groups()) do
			out[#out + 1] = { id = group.id, label = group.label, kind = group.kind, current = group.current, placeId = group.placeId }
		end
		return out
	end

	function M.folderLabel(sessionOrId)
		local session = type(sessionOrId) == "table" and sessionOrId or M.get(sessionOrId)
		return session and folderFor(session).label or nil
	end

	function M.createFolder(name)
		if not alive then return nil, "client is unloaded" end
		local folder, why = folderStore.create(name)
		if folder then M.listChanged:fire() end
		return folder, why
	end

	function M.renameFolder(id, name)
		if not alive then return false, "client is unloaded" end
		local ok, why = folderStore.rename(id, name)
		if ok then M.listChanged:fire() end
		return ok, why
	end

	function M.removeFolder(id)
		if not alive then return false, "client is unloaded" end
		local ok, why = folderStore.remove(id)
		if not ok then return false, why end
		for _, session in pairs(M.threads) do
			if session.folderId == id then session.folderId = "universal" end
		end
		M.listChanged:fire()
		return true
	end

	function M.moveToFolder(sessionOrId, folderId)
		if not alive then return false, "client is unloaded" end
		local session = type(sessionOrId) == "table" and sessionOrId or M.get(sessionOrId)
		if not session or M.get(session.id) ~= session then return false, "conversation no longer exists" end
		if not validDestination(folderId) then return false, "conversation folder does not exist" end
		if session.folderId == folderId then return true end
		local previous = session.folderId
		session.folderId = folderId
		if fsx.enabled and not session.ephemeral and not session.headless and session.depth == 0 then
			local ok, why = M.persist(session)
			if not ok then session.folderId = previous; return false, why or "conversation could not be saved" end
		end
		M.listChanged:fire()
		return true
	end

	-- Title, then the transcript. A search that only matched titles would miss the
	-- conversation you remember by something that was said in it.
	function M.search(query)
		if util.trim(tostring(query or "")) == "" then return {} end
		local out = {}
		for _, session in ipairs(M.list()) do
			local hit = env.require("runtime/conversation_search").find(session, M.folderLabel(session), query)
			if hit then hit.session = session; out[#out + 1] = hit end
		end
		return out
	end

	function M.remove(id)
		local session = M.threads[id]
		if not session then return false end
		session.preparing, session.removed = nil, true
		session.cancelDraftSave()
		session.cancelWorkflowSave()
		attachments.clearUploads(id)
		session.abort(); session.events:clear()
		local subagents = env.loadedModules and env.loadedModules["agent/subagent"]
		if subagents then subagents.stopAll(session) end
		M.threads[id] = nil
		if fsx.enabled then deleteHistory(id) end
		local evidence = env.loadedModules and env.loadedModules["runtime/evidence"]
		if evidence then pcall(evidence.clear, session) end
		if M.activeId == id then
			local remaining = M.list()
			M.activeId = remaining[1] and remaining[1].id or nil
			if not M.activeId then M.newThread() end
		end
		M.listChanged:fire()
		return true
	end

	function M.trimThreads(protected)
		local ordered = M.list()
		local excess = #ordered - THREAD_LIMIT
		for index = #ordered, 1, -1 do
			if excess <= 0 then break end
			local victim = ordered[index]
			if victim ~= protected and not victim.busy and not victim.preparing and victim.id ~= M.activeId and fsx.enabled and M.persist(victim) then
				victim.removed = true; victim.cancelDraftSave(); victim.cancelWorkflowSave()
				victim.abort(); victim.events:clear(); M.threads[victim.id] = nil
				excess = excess - 1
				attachments.clearUploads(victim.id)
				local evidence = env.loadedModules and env.loadedModules["runtime/evidence"]
				if evidence then pcall(evidence.clear, victim) end
				local subagents = env.loadedModules and env.loadedModules["agent/subagent"]
				if subagents then subagents.stopAll(victim) end
			end
		end
	end

	-- Persistence is best-effort by design: a host with no filesystem simply keeps
	-- everything in memory for the session, and nothing above here cares.
	--
	-- The transcript goes in the file as well as the context. It did not, and the
	-- consequence was the one thing about restored conversations anybody would notice:
	-- the sidebar listed them, switching to one worked, and the panel showed the
	-- greeting card -- because the transcript is a pure function of `session.log` and
	-- `log` was the one field restore left empty. `ctx.serialise` is not a substitute:
	-- it keeps what the *model* needs to continue, which has no reasoning, no timings,
	-- no risk levels and no tool arguments.
	function M.persist(session)
		if not fsx.enabled or session.headless or session.removed then return false end
		if session.depth and session.depth > 0 then return false end
		if session.ephemeral then return false end
		markDirty(session)
		local savedPolicy = {}
		for _, key in ipairs(POLICY_OPTIONS) do savedPolicy[key] = session[key] end
		local policy, why = validateOptions(savedPolicy)
		if not policy then return false, "invalid session policy: " .. tostring(why) end
		policy.version = 1
		return env.require("agent/checkpoint").write(session, function()
			local snapshot = {
				id = session.id,
				title = session.title,
				named = session.named == true,
				placeId = session.placeId,
				placeName = session.placeName,
				folderId = session.folderId,
				updatedAt = session.updatedAt,
				createdAt = session.createdAt,
				turns = session.turns, opencodeSession = session.opencodeSession,
				policy = policy,
				queue = session.serialiseQueue(),
				metadata = metadata.snapshot(session.metadata),
				draft = draftStore.snapshot(session.draft),
				workflow = workflow.snapshot(session.workflow),
				todos = env.require("runtime/todo_snapshot").snapshot(session.todos),
				context = session.ctx.serialise(),
				transcript = session.transcript.snapshot(),
				transcriptState = session.transcript.metadata(),
			}
			return historyIO(session.id, function()
				local path = THREAD_DIR .. "/" .. session.id .. ".json"
				local ok, saved, reason = pcall(fsx.writeJson, path, snapshot)
				-- A host write may yield across no-save or removal. Keep this id
				-- reserved until the old snapshot has been removed again.
				if session.ephemeral or session.removed then
					local deleted, deleteWhy = deleteHistory(session.id)
					if not deleted and fsx.exists(path) then log.warn("session", "could not remove conversation history", deleteWhy) end
					return false, "Conversation history is no longer saved"
				end
				if not ok then return false, tostring(saved) end
				return saved, reason
			end)
		end, function()
			clock.delay(0, function() if alive and not session.removed then session.persist() end end)
		end)
	end

	function M.restore()
		if not fsx.enabled then return 0 end
		local restored, candidates = 0, {}
		local function timestamp(value)
			local number = tonumber(value)
			return number and number == number and number > 0 and number < math.huge and number or 0
		end
		local function readThread(entry)
			if entry.isDir or not entry.name:match("%.json$") then return nil end
			local raw = fsx.read(entry.path)
			local data = raw and #raw <= 12 * 1024 * 1024 and util.decode(raw)
			if type(data) ~= "table" or type(data.id) ~= "string" or #data.id > 120
				or not data.id:match("^[%w_-]+$") or entry.name ~= data.id .. ".json" then return nil end
			if data.policy ~= nil then
				local policy = data.policy
				if type(policy) ~= "table" or policy.version ~= 1 then
					log.warn("session", "skipped saved conversation with unsupported policy", data.id)
					return nil
				end
				local options = {}
				for _, key in ipairs(POLICY_OPTIONS) do options[key] = policy[key] end
				local validated, why = validateOptions(options)
				if not validated then
					log.warn("session", "skipped saved conversation with invalid policy", data.id .. ": " .. tostring(why))
					return nil
				end
				data.policy = validated
			end
			return data
		end
		-- Keep only candidate metadata while finding the newest files; a host listing
		-- is alphabetic, not ordered by conversation activity.
		for _, entry in ipairs(fsx.list(THREAD_DIR)) do
			local data = readThread(entry)
			if data and not M.threads[data.id] then
				candidates[#candidates + 1] = { entry = entry, id = data.id, updatedAt = timestamp(data.updatedAt), pinned = metadata.restore(data.metadata).pinned }
				table.sort(candidates, function(a, b)
					if a.pinned ~= b.pinned then return a.pinned end
					if a.updatedAt ~= b.updatedAt then return a.updatedAt > b.updatedAt end
					return a.id < b.id
				end)
				if #candidates > THREAD_LIMIT then table.remove(candidates) end
			end
		end
		local slots = math.max(0, THREAD_LIMIT - #M.list())
		for index = 1, math.min(slots, #candidates) do
			local candidate = candidates[index]
			local data = readThread(candidate.entry)
			if data and data.id == candidate.id and not M.threads[data.id] then
				local options = data.policy or {}
				options.id = data.id
				options.title = type(data.title) == "string" and util.ellipsis(data.title, 60) or nil
				options.placeId = placeNumber(data.placeId)
				options.placeName = type(data.placeName) == "string" and data.placeName or nil
				local session = M.create(options)
				if type(data.folderId) == "string" and #data.folderId <= 120 then
					session.folderId = data.folderId
				end
				session.named = data.named == true
				session.metadata = metadata.restore(data.metadata)
				session.draft = draftStore.restore(data.draft)
				session.workflow = workflow.restore(data.workflow)
				session.todos = env.require("runtime/todo_snapshot").restore(data.todos)
				session.createdAt = timestamp(data.createdAt)
				session.updatedAt = timestamp(data.updatedAt)
				session.turns = math.floor(timestamp(data.turns)); session.opencodeSession = data.opencodeSession
				local queueOk, queueError = session.restoreQueue(data.queue)
				if queueOk then
					session.ctx.restore(data.context)
					session.transcript.restore(data.transcript, session.ctx, data.transcriptState)
					session.persistenceDirty = false
					M.threads[session.id] = session
					restored = restored + 1
				else log.warn("session", "skipped saved conversation with invalid follow-ups", queueError) end
			end
		end
		if restored > 0 then
			local ordered = M.list()
			M.activeId = ordered[1] and ordered[1].id or nil
			log.info("session", util.pluralise(restored, "conversation") .. " restored")
			M.listChanged:fire()
		end
		return restored
	end

	M.limits = { threads = THREAD_LIMIT, folders = folderStore.limit, folderNameBytes = folderStore.nameBytes, workers = 8, events = transcript.limits.events,
		transcriptBytes = transcript.limits.bytes, transcriptBudgets = transcript.limits.budgets }
	function M.beginShutdown()
		if not alive then return end
		alive = false
		-- Close admission and invalidate every turn before any save can yield.
		for _, item in pairs(M.threads) do item.abortFlag = true; item.toolEpoch = {}; item.cancelDraftSave(); item.cancelWorkflowSave() end
	end
	env.require("runtime/dispose").add(function()
		M.beginShutdown()
		local slice = clock.ms()
		for _, item in pairs(M.threads) do
			local ok, why = pcall(item.abort)
			item.events:clear()
			if not ok then log.warn("session", "unload cleanup failed", why) end
			-- Many newly changed histories still need saving. Give Roblox a frame
			-- between batches; never close a native worker or wait for it to finish.
			if coroutine.running() and clock.since(slice) >= 8 then clock.wait(); slice = clock.ms() end
		end
		M.anyEvent:clear(); M.listChanged:clear()
	end, "native sessions")
	return M
end
end)()

-- ==========================================================================
-- agent/state
-- ==========================================================================
__UAI_MODULES["agent/state"] = (function()
-- Agent-owned state that outlives a single turn: the task list the model keeps,
-- and the memory it writes to.
--
-- Both are model-writable, which is the point -- a long task survives context
-- compaction because the plan is not in the transcript -- and both are bounded,
-- because a model given an unbounded store will fill it.
--
-- Memory is the client's, deliberately: a fact about the person using it is not a
-- fact about one conversation. A task list is the opposite -- it is the plan for
-- the job in front of it -- so it lives on the session, which is what lets two
-- conversations work at once. It did not, and one global list was the whole bug:
-- starting a second conversation replaced the first one's plan in the strip *and*
-- in the system prompt it was about to be sent, so a running turn resumed against
-- somebody else's steps.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local todoSnapshot = env.require("runtime/todo_snapshot")

	local MEMORY_LIMIT = 60
	local MEMORY_VALUE_CAP = 600
	local MEMORY_INDEX_CAP = 2048

	local M = {
		todosChanged = signal.new("todos"),
		memoryChanged = signal.new("memory"),
	}

	-- Todos -----------------------------------------------------------------


	-- Where a list lives when there is no session in scope. Nothing in the client
	-- reaches this any more; it exists so a caller that loses its session writes
	-- somewhere harmless rather than raising, and so a test can drive the store
	-- without building a session.
	local orphan = { todos = {} }

	local function holderFor(session)
		if type(session) ~= "table" then return orphan end
		session.todos = session.todos or {}
		return session
	end

	function M.todoList(session)
		return holderFor(session).todos
	end

	-- The whole list is replaced rather than patched. A model that edits one item
	-- at a time drifts out of sync with its own plan; handing back the full list
	-- every time keeps the transcript and the panel identical.
	function M.setTodos(items, session)
		local out = todoSnapshot.items(items)
		local holder = holderFor(session)
		holder.todos = out
		-- The session goes with the list, so a strip showing one conversation can
		-- ignore another conversation's plan instead of painting it.
		M.todosChanged:fire(out, holder ~= orphan and holder or nil)
		if holder.persist then holder.persist() end
		return out
	end

	function M.todoCounts(session)
		local list = M.todoList(session)
		local counts = { pending = 0, active = 0, done = 0, dropped = 0, total = #list }
		for _, item in ipairs(list) do
			counts[item.status] = (counts[item.status] or 0) + 1
		end
		return counts
	end

	function M.clearTodos(session)
		local holder = holderFor(session)
		holder.todos = {}
		M.todosChanged:fire({}, holder ~= orphan and holder or nil)
		if holder.persist and not holder.clearingMessages then holder.persist() end
	end

	-- Rendered into the system prompt each turn so the plan cannot be forgotten,
	-- and into the transcript panel for the user.
	function M.todoBlock(session)
		local list = M.todoList(session)
		if #list == 0 then return nil end
		local marks = { pending = "[ ]", active = "[>]", done = "[x]", dropped = "[-]" }
		local lines = {}
		for _, item in ipairs(list) do
			lines[#lines + 1] = string.format("%s %s", marks[item.status] or "[ ]", item.text)
		end
		return table.concat(lines, "\n")
	end

	-- Memory ----------------------------------------------------------------

	local function entries()
		local stored = config.get("memory.entries", {})
		if type(stored) ~= "table" then return {} end
		return stored
	end

	function M.memoryEnabled()
		return config.get("memory.enabled", true) ~= false
	end

	function M.normalizeMemoryKey(key)
		return (util.trim(key):gsub("%s+", "_"))
	end

	function M.resolveMemoryKey(key)
		local exact = util.trim(key)
		for _, entry in ipairs(entries()) do
			if entry.key == exact then return exact end
		end
		return M.normalizeMemoryKey(exact)
	end

	function M.remember(key, value)
		local cleanKey = M.normalizeMemoryKey(key)
		if cleanKey == "" then return false, "a memory needs a key" end
		if not M.memoryEnabled() then return false, "memory is disabled in settings" end
		local list = entries()
		local text = util.ellipsis(util.trim(value), MEMORY_VALUE_CAP)
		if text == "" then return false, "a memory needs a value" end

		local replaced = false
		for _, entry in ipairs(list) do
			if entry.key == cleanKey then
				entry.value = text
				entry.at = clock.ms()
				replaced = true
			end
		end
		if not replaced then
			if #list >= MEMORY_LIMIT then
				-- Oldest out. A model that keeps writing should lose its earliest
				-- notes rather than start failing.
				table.sort(list, function(a, b) return (a.at or 0) < (b.at or 0) end)
				table.remove(list, 1)
			end
			list[#list + 1] = { key = cleanKey, value = text, at = clock.ms() }
		end
		config.set("memory.entries", list)
		M.memoryChanged:fire(list)
		return true, (replaced and "updated " or "saved ") .. cleanKey
	end

	function M.recall(key)
		local cleanKey = M.resolveMemoryKey(key)
		for _, entry in ipairs(entries()) do
			if entry.key == cleanKey then return entry.value end
		end
		return nil
	end

	function M.forget(key)
		local cleanKey = M.resolveMemoryKey(key)
		local list = entries()
		local kept = {}
		local removed = 0
		for _, entry in ipairs(list) do
			if entry.key == cleanKey then
				removed = removed + 1
			else
				kept[#kept + 1] = entry
			end
		end
		config.set("memory.entries", kept)
		M.memoryChanged:fire(kept)
		return removed > 0
	end

	function M.memoryList()
		local list = {}
		for index, entry in ipairs(entries()) do list[index] = entry end
		table.sort(list, function(a, b) return tostring(a.key) < tostring(b.key) end)
		return list
	end

	function M.clearMemory()
		config.set("memory.entries", {})
		M.memoryChanged:fire({})
	end

	-- Discovery only: old workaround prose must not become standing instructions.
	-- Keep complete keys; omitted keys remain searchable through memory_read.
	function M.memoryIndex()
		if not M.memoryEnabled() then return nil end
		local list = M.memoryList()
		if #list == 0 then return nil end
		local lines, bytes, shown = {}, 0, 0
		for _, entry in ipairs(list) do
			local line = "- " .. util.encode(tostring(entry.key))
			if bytes + #line + 1 <= MEMORY_INDEX_CAP - 100 then
				lines[#lines + 1] = line
				bytes, shown = bytes + #line + 1, shown + 1
			end
		end
		if shown < #list then
			lines[#lines + 1] = string.format("%d more keys; use memory_read with query or paginate the full list.", #list - shown)
		end
		return table.concat(lines, "\n")
	end

	function M.memoryBlock()
		if not M.memoryEnabled() then return nil end
		local list = M.memoryList()
		if #list == 0 then return nil end
		local lines = {}
		for _, entry in ipairs(list) do
			lines[#lines + 1] = "- " .. entry.key .. ": " .. entry.value
		end
		return table.concat(lines, "\n")
	end

	return M
end
end)()

-- ==========================================================================
-- agent/stats
-- ==========================================================================
__UAI_MODULES["agent/stats"] = (function()
-- Activity history.
--
-- Everything the home card and the Usage panel show is counted here, from events
-- the client genuinely observed, and nothing is modelled or interpolated: a figure
-- either has a record behind it or it is absent. That is the whole contract of this
-- module, and it is why the counters are so plain.
--
-- Two things follow from it. Tokens are only ever counted from the moment this file
-- first exists -- `agent/usage` has always been in-memory, so there is no history to
-- recover and inventing one would be worse than a zero. Messages and conversations
-- *can* be recovered, because every persisted transcript carries the real timestamp
-- of every message in it, so the first run seeds those from disk and says so.
--
-- Buckets are local days and local hours, because "yesterday" and "11 AM" are the
-- user's, not UTC's. runtime/clock owns that conversion.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local fsx = env.require("runtime/fsx")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local dispose = env.require("runtime/dispose")
	local accounting = env.require("runtime/request_accounting")

	local FILE = "stats.json"
	-- Thirteen months of days. Past that the oldest is dropped, which is also the
	-- ceiling on how far back any window can reach -- stated here because the panel
	-- says "all" and that is what all means.
	local DAY_LIMIT = 400
	-- Ids of conversations already counted, so resuming one after a restart does not
	-- count it twice. Only twenty transcripts are ever kept on disk, so a window of
	-- sixty-four covers every conversation that could still be resumed.
	local SEEN_LIMIT = 64
	local TOOL_LIMIT = 120
	local SAVE_SECONDS = 2

	-- The comparison Claude Code's home card makes. 76,944 words in the first
	-- edition; at the four-characters-per-token estimate this client uses everywhere
	-- else that is a little under 100,000 tokens, which is the divisor. It is an
	-- estimate of the book, not of the count -- the token figure itself is measured.
	local BOOK = { title = "Harry Potter and the Philosopher's Stone", tokens = 100000 }

	local M = {
		changed = signal.new("stats"),
		loaded = false,
		observing = false,
		BOOK = BOOK,
		DAY_LIMIT = DAY_LIMIT,
	}

	local function blankTotals()
		return {
			sessions = 0, messages = 0, userMessages = 0, replies = 0,
			tokensIn = 0, tokensOut = 0, cached = 0, cacheCreated = 0, reasoning = 0, unpriced = 0,
			cost = 0, requests = 0, toolCalls = 0, toolErrors = 0, errors = 0,
		}
	end

	local function blank()
		return {
			version = 1,
			startedAt = clock.ms(),
			-- Nil until the first request is recorded, and the Usage panel prints it
			-- rather than implying the token columns cover the whole history.
			tokensFrom = nil,
			requestTrackingSince = clock.ms(),
			keyUsage = {},
			conversationUsage = {},
			seededAt = nil,
			days = {},
			hours = {},
			models = {},
			tools = {},
			seen = {},
			totals = blankTotals(),
		}
	end

	M.data = blank()

	local seenSet = {}

	local function rebuildSeen()
		seenSet = {}
		for _, id in ipairs(M.data.seen or {}) do seenSet[tostring(id)] = true end
	end

	-- Numbers come back from JSON as numbers, but a hand-edited or half-written file
	-- can hold anything, and one string in a counter would poison every sum.
	local function number(value)
		local parsed = tonumber(value)
		return parsed and parsed == parsed and parsed >= 0 and parsed < math.huge and parsed or 0
	end

	local function sanitiseCounters(source, template)
		local out = {}
		for key, fallback in pairs(template) do
			out[key] = number(util.get(source or {}, key, fallback))
		end
		return out
	end

	local DAY_TEMPLATE = {
		sessions = 0, messages = 0, userMessages = 0, replies = 0,
		tokensIn = 0, tokensOut = 0, cost = 0, requests = 0, unpriced = 0,
		toolCalls = 0, toolErrors = 0, errors = 0,
	}

	local function blankDay()
		return sanitiseCounters({}, DAY_TEMPLATE)
	end

	local function usageCounters(value)
		value = type(value) == "table" and value or {}
		local out = { estimated = value.estimated == true }
		for _, name in ipairs({ "requests", "tokensIn", "tokensOut" }) do
			local count = number(value[name])
			out[name] = count <= 9007199254740991 and count == math.floor(count) and count or 0
		end
		return out
	end

	local function addUsage(row, name, amount)
		amount = number(amount)
		if amount > 9007199254740991 or amount ~= math.floor(amount) then return end
		row[name] = math.min(9007199254740991, row[name] + amount)
	end

	local function validId(value)
		return type(value) == "string" and #value > 0 and #value <= 160 and not value:find("[%z\1-\31\127]")
	end

	function M.load()
		local stored = fsx.readJson(FILE, nil)
		M.data = blank()
		if type(stored) == "table" then
			M.data.startedAt = number(stored.startedAt) > 0 and number(stored.startedAt) or M.data.startedAt
			M.data.tokensFrom = tonumber(stored.tokensFrom)
			M.data.seededAt = tonumber(stored.seededAt)
			M.data.totals = sanitiseCounters(stored.totals, blankTotals())
			M.data.estimated = stored.estimated == true
			if number(stored.requestTrackingSince) > 0 and number(stored.requestTrackingSince) <= 9007199254740991 then
				M.data.requestTrackingSince = math.floor(number(stored.requestTrackingSince))
			end
			for providerId, provider in pairs(type(stored.keyUsage) == "table" and stored.keyUsage or {}) do
				if validId(providerId) and type(provider) == "table" then
					local entries = {}
					for keyId, value in pairs(provider) do
						if validId(keyId) and type(value) == "table" then entries[keyId] = usageCounters(value) end
					end
					M.data.keyUsage[providerId] = entries
				end
			end
			for id, value in pairs(type(stored.conversationUsage) == "table" and stored.conversationUsage or {}) do
				if validId(id) and type(value) == "table" then M.data.conversationUsage[id] = usageCounters(value) end
			end
			-- Lifetime metadata is persisted beside daily buckets. Reloading only
			-- the buckets discarded model first/last-use dates and hour totals.
			for hour, count in pairs(type(stored.hours) == "table" and stored.hours or {}) do
				local index = tonumber(hour)
				if index and index >= 0 and index <= 23 and index == math.floor(index) then
					M.data.hours[tostring(index)] = number(count)
				end
			end
			for id, entry in pairs(type(stored.models) == "table" and stored.models or {}) do
				if type(id) == "string" and type(entry) == "table" then
					M.data.models[id] = {
						requests = number(entry.requests), tokensIn = number(entry.tokensIn),
						tokensOut = number(entry.tokensOut), cost = number(entry.cost), unpriced = number(entry.unpriced),
						firstAt = number(entry.firstAt) > 0 and number(entry.firstAt) or nil,
						lastAt = number(entry.lastAt) > 0 and number(entry.lastAt) or nil,
					}
				end
			end
			if type(stored.days) == "table" then
				for key, record in pairs(stored.days) do
					if clock.dayNumberOfKey(key) and type(record) == "table" then
						local day = sanitiseCounters(record, DAY_TEMPLATE)
						day.hours = {}
						for hour, count in pairs(type(record.hours) == "table" and record.hours or {}) do
							local index = tonumber(hour)
							if index and index >= 0 and index <= 23 then
								day.hours[tostring(math.floor(index))] = number(count)
							end
						end
						day.models = {}
						for id, entry in pairs(type(record.models) == "table" and record.models or {}) do
							if type(id) == "string" and type(entry) == "table" then
								day.models[id] = {
									requests = number(entry.requests),
									tokensIn = number(entry.tokensIn),
									tokensOut = number(entry.tokensOut),
									cost = number(entry.cost),
									unpriced = number(entry.unpriced),
								}
							end
						end
						M.data.days[key] = day
					end
				end
			end
			if type(stored.tools) == "table" then
				for name, count in pairs(stored.tools) do
					if type(name) == "string" then M.data.tools[name] = number(count) end
				end
			end
			if type(stored.seen) == "table" then
				for _, id in ipairs(stored.seen) do
					if type(id) == "string" then M.data.seen[#M.data.seen + 1] = id end
				end
			end
		end
		rebuildSeen()
		M.loaded = true
		return M.data
	end

	function M.saveNow()
		if not fsx.enabled then return false, "no filesystem" end
		local ok, err = fsx.writeJson(FILE, M.data)
		if not ok then log.warn("stats", "could not persist activity history", err) end
		return ok, err
	end

	local flush = clock.debounce(function() M.saveNow() end, SAVE_SECONDS)

	function M.save()
		flush()
	end

	-- Recording ---------------------------------------------------------------

	-- Get-or-create for one local day, trimming the oldest when the window is full.
	-- The trim is by day number rather than by string order so a key from a future
	-- year cannot sort itself into the middle of the set.
	local function dayFor(ms)
		local key = clock.dayKey(ms)
		local record = M.data.days[key]
		if record then return record, key end
		record = blankDay()
		record.hours = {}
		record.models = {}
		M.data.days[key] = record

		local keys = {}
		for existing in pairs(M.data.days) do keys[#keys + 1] = existing end
		if #keys > DAY_LIMIT then
			table.sort(keys, function(a, b)
				return (clock.dayNumberOfKey(a) or 0) < (clock.dayNumberOfKey(b) or 0)
			end)
			for index = 1, #keys - DAY_LIMIT do M.data.days[keys[index]] = nil end
		end
		return record, key
	end

	local function bump(record, key, amount)
		record[key] = number(record[key]) + (amount or 1)
	end

	local function touchHour(day, ms)
		local hour = tostring(clock.hourOf(ms))
		day.hours[hour] = number(day.hours[hour]) + 1
		M.data.hours[hour] = number(M.data.hours[hour]) + 1
	end

	-- `quiet` seeds from disk without republishing per row: the first run would
	-- otherwise fire the signal a few thousand times before the interface exists.
	function M.recordMessage(role, at, quiet)
		local day = dayFor(at)
		bump(day, "messages")
		bump(M.data.totals, "messages")
		if role == "user" then
			bump(day, "userMessages")
			bump(M.data.totals, "userMessages")
		else
			bump(day, "replies")
			bump(M.data.totals, "replies")
		end
		touchHour(day, at)
		if not quiet then
			M.save()
			M.changed:fire(M.data)
		end
	end

	-- A conversation counts once, the first time something is actually said in it: a
	-- thread object exists from the moment a panel opens and counting those would
	-- report a session for every time the window was looked at.
	function M.recordSession(id, at, quiet)
		local key = tostring(id or "")
		if key ~= "" then
			if seenSet[key] then return false end
			seenSet[key] = true
			M.data.seen[#M.data.seen + 1] = key
			while #M.data.seen > SEEN_LIMIT do table.remove(M.data.seen, 1) end
		end
		local day = dayFor(at)
		bump(day, "sessions")
		bump(M.data.totals, "sessions")
		if not quiet then
			M.save()
			M.changed:fire(M.data)
		end
		return true
	end

	function M.counted(id)
		return seenSet[tostring(id or "")] == true
	end

	-- One inference request, after the fact, with whatever the provider reported.
	-- `delta` is what agent/usage measured for this request alone.
	function M.recordRequest(delta)
		delta = delta or {}
		local at = delta.at or clock.ms()
		local day = dayFor(at)
		local tokensIn = number(delta.prompt)
		local tokensOut = number(delta.completion)
		local cost = number(delta.cost)
		local unpriced = delta.costKnown == false and 1 or 0

		bump(day, "requests")
		bump(day, "tokensIn", tokensIn)
		bump(day, "tokensOut", tokensOut)
		bump(day, "cost", cost)
		bump(day, "unpriced", unpriced)
		bump(M.data.totals, "requests")
		bump(M.data.totals, "tokensIn", tokensIn)
		bump(M.data.totals, "tokensOut", tokensOut)
		bump(M.data.totals, "cached", number(delta.cached))
		bump(M.data.totals, "cacheCreated", number(delta.cacheCreated))
		bump(M.data.totals, "unpriced", unpriced)
		bump(M.data.totals, "reasoning", number(delta.reasoning))
		bump(M.data.totals, "cost", cost)
		if delta.estimated then M.data.estimated = true end
		if not M.data.tokensFrom then M.data.tokensFrom = at end

		local model = util.trim(tostring(delta.model or ""))
		if model ~= "" then
			local perDay = day.models[model]
			if not perDay then
				perDay = { requests = 0, tokensIn = 0, tokensOut = 0, cost = 0 }
				day.models[model] = perDay
			end
			bump(perDay, "requests")
			bump(perDay, "tokensIn", tokensIn)
			bump(perDay, "tokensOut", tokensOut)
			bump(perDay, "cost", cost)
			bump(perDay, "unpriced", unpriced)

			local lifetime = M.data.models[model]
			if not lifetime then
				lifetime = { requests = 0, tokensIn = 0, tokensOut = 0, cost = 0, firstAt = at }
				M.data.models[model] = lifetime
			end
			bump(lifetime, "requests")
			bump(lifetime, "tokensIn", tokensIn)
			bump(lifetime, "tokensOut", tokensOut)
			bump(lifetime, "cost", cost)
			bump(lifetime, "unpriced", unpriced)
			lifetime.lastAt = at
		end

		M.save()
		M.changed:fire(M.data)
	end

	local function usageRows(reference, create)
		if not M.loaded then M.load() end
		local rows = {}
		if validId(reference.conversationId) then
			local row = M.data.conversationUsage[reference.conversationId]
			if not row and create then row = usageCounters(); M.data.conversationUsage[reference.conversationId] = row end
			if row then rows[#rows + 1] = row end
		end
		if validId(reference.providerId) and validId(reference.keyId) then
			local provider = M.data.keyUsage[reference.providerId]
			if not provider and create then provider = {}; M.data.keyUsage[reference.providerId] = provider end
			local row = provider and provider[reference.keyId]
			if not row and create then row = usageCounters(); provider[reference.keyId] = row end
			if row then rows[#rows + 1] = row end
		end
		return rows
	end

	-- Counts the locally observed dispatch, including failures and retries. This
	-- stays separate from historical request totals based on successful usage.
	function M.recordDispatch(reference)
		local rows = usageRows(reference or {}, true)
		for _, row in ipairs(rows) do addUsage(row, "requests", 1) end
		if #rows > 0 then M.save(); M.changed:fire(M.data) end
	end

	function M.recordKeyTokens(delta)
		local rows = usageRows(delta.reference or {}, false)
		for _, row in ipairs(rows) do
			addUsage(row, "tokensIn", delta.prompt)
			addUsage(row, "tokensOut", delta.completion)
			if delta.estimated then row.estimated = true end
		end
		if #rows > 0 then M.save(); M.changed:fire(M.data) end
	end

	local function readUsage(value)
		local out = usageCounters(value)
		out.trackedSince = M.data.requestTrackingSince
		return out
	end

	function M.keyUsage(record, index)
		if not M.loaded then M.load() end
		local provider = type(record) == "table" and M.data.keyUsage[tostring(record.id or "")]
		local id = type(record) == "table" and type(record.keyIds) == "table" and record.keyIds[index]
		return readUsage(provider and id and provider[id])
	end

	function M.conversationUsage(session)
		if not M.loaded then M.load() end
		local id = accounting.conversationId(session)
		return readUsage(id and M.data.conversationUsage[id])
	end

	function M.recordTool(name, ok, at)
		local day = dayFor(at)
		bump(day, "toolCalls")
		bump(M.data.totals, "toolCalls")
		if not ok then
			bump(day, "toolErrors")
			bump(M.data.totals, "toolErrors")
		end
		local key = util.trim(tostring(name or ""))
		if key ~= "" then
			if M.data.tools[key] == nil and util.count(M.data.tools) >= TOOL_LIMIT then
				-- A tool list is bounded by the registry, so this only trips if a host
				-- registers its own; dropping the new name is better than growing
				-- without limit.
				key = nil
			end
			if key then M.data.tools[key] = number(M.data.tools[key]) + 1 end
		end
		M.save()
	end

	function M.recordError(at)
		local day = dayFor(at)
		bump(day, "errors")
		bump(M.data.totals, "errors")
		M.save()
	end

	-- Recovering what is already on disk ---------------------------------------

	-- A persisted transcript carries the real timestamp of every message in it, so
	-- the conversations and messages of a client that has been in use since before
	-- this file existed are real history rather than a guess, and are counted once.
	--
	-- Tokens are deliberately not seeded. Nothing on disk records them, and an
	-- estimate would be a number with no measurement behind it.
	function M.seedFromSessions(list)
		if M.data.seededAt then return 0 end
		local messages, conversations = 0, 0
		for _, session in ipairs(list or {}) do
			local first = nil
			for _, message in ipairs((session.ctx and session.ctx.messages) or {}) do
				local role = tostring(message.role or "")
				local body = util.trim(tostring(message.content or ""))
				-- An assistant turn with no prose is a tool-call round, not a reply.
				if role == "user" or (role == "assistant" and body ~= "") then
					local at = tonumber(message.at) or tonumber(session.createdAt) or clock.ms()
					M.recordMessage(role, at, true)
					messages = messages + 1
					if not first then first = at end
				end
			end
			if first and M.recordSession(session.id, first, true) then
				conversations = conversations + 1
			end
		end
		M.data.seededAt = clock.ms()
		if messages > 0 then
			log.info("stats", string.format("%s recovered from %s already on disk",
				util.pluralise(messages, "message"), util.pluralise(conversations, "conversation")))
		end
		M.saveNow()
		M.changed:fire(M.data)
		return messages
	end

	-- Observation --------------------------------------------------------------

	function M.observe()
		if M.observing then return function() end end
		M.observing = true
		local hooks = env.require("agent/hooks")
		local usage = env.require("agent/usage")

		-- Every session event passes through the hook bus, which is how this stays out
		-- of the loop and the session object entirely.
		local unhook = hooks.register("onEvent", function(payload)
			local event = payload and payload.event
			local session = payload and payload.session
			if type(event) ~= "table" then return end
			-- A subagent's requests and tokens are work the conversation asked for and
			-- are counted with it, but its messages are not messages anyone typed or
			-- read: counting those would inflate the card by however many helpers a
			-- turn happened to dispatch.
			local nested = session ~= nil
				and (session.headless == true or (tonumber(session.depth) or 0) > 0)
			local kind = event.kind
			local at = tonumber(event.at) or clock.ms()

			if kind == "user" then
				if nested then return end
				if session then M.recordSession(session.id, at) end
				M.recordMessage("user", at)
			elseif kind == "assistant:text" then
				if nested then return end
				if util.trim(tostring(event.text or "")) ~= "" then
					M.recordMessage("assistant", at)
				end
			elseif kind == "tool:result" then
				M.recordTool(event.name, event.ok ~= false, at)
			elseif kind == "tool:error" then
				M.recordTool(event.name, false, at)
			elseif kind == "error" then
				M.recordError(at)
			end
		end, { name = "stats", order = -1000 })

		local untoken = usage.recorded:connect(function(delta) M.recordRequest(delta) end)
		local undispatch = accounting.dispatched:connect(M.recordDispatch)
		local unkeytokens = accounting.tokens:connect(M.recordKeyTokens)

		dispose.add(unhook, "stats.events")
		dispose.add(untoken, "stats.usage")
		dispose.add(undispatch, "stats.dispatches")
		dispose.add(unkeytokens, "stats.keyUsage")
		-- The last few seconds of a session are the ones the debounce has not written
		-- yet, and an unload is exactly when they would be lost.
		dispose.add(function() M.saveNow() end, "stats.flush")
		return unhook
	end

	function M.init()
		if not M.loaded then M.load() end
		M.observe()
		local ok, err = pcall(function()
			M.seedFromSessions(env.require("agent/session").list())
		end)
		if not ok then log.warn("stats", "could not read history from disk", err) end
		return M
	end

	-- Reading ------------------------------------------------------------------

	local RANGES = { all = 0, ["30d"] = 30, ["7d"] = 7 }
	M.RANGES = { { value = "all", label = "All" }, { value = "30d", label = "30d" }, { value = "7d", label = "7d" } }

	local function dayIsActive(day)
		return number(day.messages) > 0 or number(day.requests) > 0 or number(day.sessions) > 0
	end

	-- A streak is consecutive active days ending today, or ending yesterday when
	-- today has not started yet -- otherwise every streak would read as broken until
	-- the first message of the morning.
	local function streaksOf(active, today, from)
		local current, cursor = 0, today
		if not active[cursor] then cursor = cursor - 1 end
		while active[cursor] and (from == nil or cursor >= from) do
			current = current + 1
			cursor = cursor - 1
		end

		local ordered = {}
		for value in pairs(active) do ordered[#ordered + 1] = value end
		table.sort(ordered)
		local longest, run = 0, 0
		for index, value in ipairs(ordered) do
			if index > 1 and value == ordered[index - 1] + 1 then
				run = run + 1
			else
				run = 1
			end
			if run > longest then longest = run end
		end
		return current, longest
	end

	-- Everything the home card shows for one range, aggregated from the day records
	-- so that "all" and "7d" are the same computation over a different span rather
	-- than two sources that can disagree.
	function M.window(range)
		if not RANGES[range] then range = "all" end
		local span = RANGES[range]
		local today = clock.dayNumber()
		local from = nil
		if span > 0 then from = today - (span - 1) end

		local out = {
			range = range,
			today = clock.keyFromDayNumber(today),
			fromKey = from and clock.keyFromDayNumber(from) or nil,
			activeDays = 0,
			sessions = 0, messages = 0, userMessages = 0, replies = 0,
			tokensIn = 0, tokensOut = 0, tokens = 0, cost = 0, unpriced = 0,
			requests = 0, toolCalls = 0, toolErrors = 0, errors = 0,
			estimated = M.data.estimated == true,
			hours = {},
			models = {},
			tokensFrom = M.data.tokensFrom,
			startedAt = M.data.startedAt,
		}
		local active, perModel = {}, {}

		for key, day in pairs(M.data.days) do
			local index = clock.dayNumberOfKey(key)
			if index and index <= today and (from == nil or index >= from) then
				out.sessions = out.sessions + number(day.sessions)
				out.messages = out.messages + number(day.messages)
				out.userMessages = out.userMessages + number(day.userMessages)
				out.replies = out.replies + number(day.replies)
				out.tokensIn = out.tokensIn + number(day.tokensIn)
				out.tokensOut = out.tokensOut + number(day.tokensOut)
				out.cost = out.cost + number(day.cost)
				out.unpriced = out.unpriced + number(day.unpriced)
				out.requests = out.requests + number(day.requests)
				out.toolCalls = out.toolCalls + number(day.toolCalls)
				out.toolErrors = out.toolErrors + number(day.toolErrors)
				out.errors = out.errors + number(day.errors)
				for hour, count in pairs(day.hours or {}) do
					out.hours[hour] = number(out.hours[hour]) + number(count)
				end
				for id, entry in pairs(day.models or {}) do
					local row = perModel[id]
					if not row then
						row = { id = id, requests = 0, tokensIn = 0, tokensOut = 0, cost = 0, unpriced = 0 }
						perModel[id] = row
					end
					row.requests = row.requests + number(entry.requests)
					row.tokensIn = row.tokensIn + number(entry.tokensIn)
					row.tokensOut = row.tokensOut + number(entry.tokensOut)
					row.cost = row.cost + number(entry.cost)
					row.unpriced = row.unpriced + number(entry.unpriced)
				end
				if dayIsActive(day) then
					active[index] = true
					out.activeDays = out.activeDays + 1
				end
			end
		end

		out.tokens = out.tokensIn + out.tokensOut
		out.currentStreak, out.longestStreak = streaksOf(active, today, from)

		local peakHour, peakCount = nil, 0
		for hour = 0, 23 do
			local count = number(out.hours[tostring(hour)])
			if count > peakCount then peakHour, peakCount = hour, count end
		end
		out.peakHour = peakHour
		out.peakHourCount = peakCount

		for _, row in pairs(perModel) do
			row.tokens = row.tokensIn + row.tokensOut
			local lifetime = M.data.models[row.id]
			row.firstAt = lifetime and lifetime.firstAt or nil
			row.lastAt = lifetime and lifetime.lastAt or nil
			out.models[#out.models + 1] = row
		end
		-- Tokens first, then requests: two models with one request each are ordered by
		-- which actually did the work.
		table.sort(out.models, function(a, b)
			if a.tokens ~= b.tokens then return a.tokens > b.tokens end
			if a.requests ~= b.requests then return a.requests > b.requests end
			return a.id < b.id
		end)
		for _, row in pairs(out.models) do
			row.share = out.tokens > 0 and (row.tokens / out.tokens)
				or (out.requests > 0 and (row.requests / out.requests) or 0)
		end
		out.topModel = out.models[1]
		return out
	end

	-- One column per week, seven rows per column, ending on the week that contains
	-- today. Every cell names the day it stands for, so a cell with no record is
	-- reported as a real day with nothing on it rather than as a gap.
	function M.heatmap(weeks)
		weeks = math.max(math.floor(tonumber(weeks) or 26), 1)
		local today = clock.dayNumber()
		-- Monday-based columns, so the last column is the current week.
		local weekday = clock.weekdayOfDayNumber(today)
		local lastMonday = today - (weekday - 1)
		local firstMonday = lastMonday - (weeks - 1) * 7

		local peak = 0
		local columns = {}
		for column = 1, weeks do
			local cells = {}
			for row = 1, 7 do
				local index = firstMonday + (column - 1) * 7 + (row - 1)
				local key = clock.keyFromDayNumber(index)
				local day = M.data.days[key]
				local value = day and (number(day.tokensIn) + number(day.tokensOut)) or 0
				local messages = day and number(day.messages) or 0
				if value > peak then peak = value end
				cells[row] = {
					key = key,
					day = index,
					future = index > today,
					tokens = value,
					messages = messages,
					sessions = day and number(day.sessions) or 0,
					requests = day and number(day.requests) or 0,
					active = day ~= nil and dayIsActive(day),
				}
			end
			columns[column] = cells
		end

		-- Four levels, so a quiet day still reads as activity next to a heavy one.
		for _, cells in ipairs(columns) do
			for _, cell in ipairs(cells) do
				cell.level = 0
				if cell.active then
					cell.level = 1
					if peak > 0 and cell.tokens > 0 then
						local share = cell.tokens / peak
						if share > 0.66 then
							cell.level = 4
						elseif share > 0.33 then
							cell.level = 3
						else
							cell.level = 2
						end
					end
				end
			end
		end
		return { columns = columns, weeks = weeks, peak = peak, fromKey = clock.keyFromDayNumber(firstMonday) }
	end

	-- The comparison the home card ends on. Absent below one whole book, because
	-- "0.4x a book" is a sentence nobody wants and a rounding away from claiming a
	-- book that was not written.
	function M.comparison(tokens)
		local value = number(tokens)
		if value < BOOK.tokens then return nil end
		local times = value / BOOK.tokens
		local rendered = string.format("%d", math.floor(times + 0.5))
		if times < 10 then rendered = string.format("%.1f", times) end
		return string.format("You've used ~%s\195\151 more tokens than %s.", rendered, BOOK.title)
	end

	function M.topTools(limit)
		local out = {}
		for name, count in pairs(M.data.tools) do
			out[#out + 1] = { name = name, count = number(count) }
		end
		table.sort(out, function(a, b)
			if a.count ~= b.count then return a.count > b.count end
			return a.name < b.name
		end)
		if limit and #out > limit then out = util.slice(out, 1, limit) end
		return out
	end

	function M.reset()
		M.data = blank()
		M.data.seededAt = clock.ms()
		rebuildSeen()
		M.saveNow()
		M.changed:fire(M.data)
	end

	return M
end
end)()

-- ==========================================================================
-- agent/stream
-- ==========================================================================
__UAI_MODULES["agent/stream"] = (function()
-- Transient previews from real transport frames; buffered replies bypass this.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local sse = env.require("net/sse")
	local text = env.require("runtime/code_text")
	local M = { previewBytes = 65536 }
	function M.new(session, model, aborted)
		local handle = { id = util.uid("stream") }
		-- Previews need prose only. The transport's authoritative assembler owns
		-- tool arguments and validates them; retaining them here duplicates source.
		local assembly, content, reasoning = sse.assembler({ toolCalls = false }), "", ""
		local closed, pending, last, generation = false, false, nil, 0
		local full = {}
		local function append(value, parts, channel)
			if full[channel] or #parts == 0 then return value end
			local joined = value .. table.concat(parts)
			if #joined > M.previewBytes then
				full[channel] = true
				return joined:sub(1, text.clamp(joined, M.previewBytes + 1) - 1)
			end
			return joined
		end
		local function flush()
			pending = false; generation = generation + 1
			if closed or aborted() then return end
			last = clock.ms()
			session.emit("assistant:preview", { streamId = handle.id, model = model,
				text = content, reasoning = reasoning, limited = full.content == true or full.reasoning == true,
				textLimited = full.content == true, reasoningLimited = full.reasoning == true })
		end
		function handle.feed(frame)
			if closed or aborted() then return end
			local chunk = type(frame) == "table" and frame or util.decode(frame)
			if type(chunk) == "table" and chunk.uaiPreviewLimited == true then
				full.content, full.reasoning = true, true
				flush(); return
			end
			if type(chunk) ~= "table" or chunk.error or not assembly.feedChunk(chunk) then return end
			if type(assembly.model) == "string" and util.trim(assembly.model) ~= "" then model = assembly.model end
			local priorContent, priorReasoning = content, reasoning
			local priorTextLimit, priorReasoningLimit = full.content, full.reasoning
			content, reasoning = append(content, assembly.content, "content"), append(reasoning, assembly.reasoning, "reasoning")
			assembly.content, assembly.reasoning = {}, {}
			if content == priorContent and reasoning == priorReasoning
				and full.content == priorTextLimit and full.reasoning == priorReasoningLimit then return end
			if not last or clock.ms() - last >= 100 then flush()
			elseif not pending then
				pending = true; local queued = generation
				clock.delay(0.1, function() if queued == generation then flush() end end)
			end
		end
		function handle.close() closed, pending, assembly = true, false, nil; generation = generation + 1 end
		return handle
	end
	return M
end
end)()

-- ==========================================================================
-- agent/subagent
-- ==========================================================================
__UAI_MODULES["agent/subagent"] = (function()
-- Subagent dispatch.
--
-- A subagent is a full session with a smaller tool set, its own context and no
-- interface. It exists to keep long or repetitive work out of the main
-- conversation: the parent pays for one paragraph of report instead of forty tool
-- results, and a search that goes nowhere costs the main context nothing.
--
-- Depth is capped because a subagent that can spawn subagents indefinitely is a
-- fork bomb with a token bill.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local signal = env.require("runtime/signal")
	local codeText = env.require("runtime/code_text")
	local prompt = env.require("agent/prompt")
	local session = env.require("agent/session")

	local M = {}
	local alive = true
	M.backgroundCount = 0

	-- Groups a subagent may be given. Anything that changes the world is absent
	-- from the read-only preset, which is the default: the point of a subagent is
	-- usually to go and find out, and a delegated write is hard for the user to
	-- attribute afterwards.
	M.PRESETS = {
		read = { instance = true, world = true, players = true, perf = true, meta = true, web = true, net = true, fs = true, skills = true },
		web = { web = true, net = true, skills = true },
		game = { instance = true, world = true, players = true, gui = true, remotes = true, meta = true, skills = true },
		full = nil,
	}

	-- The register.
	--
	-- `live` was a bare counter, which is enough to enforce a ceiling and nothing else:
	-- there was no way to ask what is running, what it was asked to do, or to stop one
	-- of them without stopping the whole turn. A dispatch is the longest-lived and least
	-- visible thing this client does -- minutes of work, its own context, its own tool
	-- calls, and a transcript card that scrolls away -- so each one gets a record here
	-- that outlives its card, and the interface reads this rather than the log.
	--
	-- Bounded, because a long session dispatches a lot: running records are never
	-- dropped, finished ones are kept newest-first up to the history limit.
	--
	-- Of those, only the newest few keep the session they ran on. A child's context is
	-- the expensive half of it -- every tool result it collected -- and holding two dozen
	-- of them for the life of the client would make delegation the largest thing in
	-- memory. So a record outlives its session: the newest are resumable, the rest keep
	-- their report and lose the context behind it.
	local HISTORY = 24
	local RESUMABLE = 6
	local ACTIVITY_LIMIT = 24
	local PREVIEW_BYTES = 4096

	M.records = {}
	M.changed = signal.new("subagents")

	local function announceChange()
		M.changed:fire(M.records)
	end

	local function isLive(record)
		return record.status == "running" or record.status == "queued"
	end

	local function awaitingCollection(record)
		if not record.background or isLive(record) or record.collectedRun == (record.runs or 0) then return false end
		local parent = record.parent
		if not parent then return record.parentEpoch == nil end
		return not parent.removed and parent.toolEpoch == record.parentEpoch and not parent.aborted()
	end

	-- Newest first, which is the order the register is held in, so the count runs from
	-- the most recent finished dispatch outward. It used to run from the oldest, which
	-- inverted both rules: the twenty-four kept were the oldest twenty-four, and the
	-- dispatch that had just reported back was the first one dropped.
	local function trimHistory()
		local protected = 0
		for _, record in ipairs(M.records) do if awaitingCollection(record) then protected = protected + 1 end end
		local finished, ordinary = 0, 0
		local ordinaryLimit = math.max(0, HISTORY - protected)
		local kept = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then
				kept[#kept + 1] = record
			else
				local awaiting = awaitingCollection(record)
				if awaiting or ordinary < ordinaryLimit then
					finished = finished + 1
					if not awaiting then ordinary = ordinary + 1 end
					if finished > RESUMABLE then
						-- Release expensive child context. An unread background report still
						-- needs its parent identity for collection and admission accounting.
						if record.disconnect then record.disconnect(); record.disconnect = nil end
						record.session = nil
						if not awaiting then record.parent = nil end
					end
					kept[#kept + 1] = record
				end
			end
		end
		M.records = kept
	end

	local function track(record)
		record.startedAt = clock.ms()
		record.status = "queued"
		record.calls = 0
		record.finishedCalls = 0
		record.tools = {}
		table.insert(M.records, 1, record)
		trimHistory()
		announceChange()
		return record
	end

	-- Newest first, running before finished: what a panel wants to draw in order.
	function M.list()
		local running, done = {}, {}
		for _, record in ipairs(M.records) do
			if isLive(record) then
				running[#running + 1] = record
			else
				done[#done + 1] = record
			end
		end
		local out = {}
		for _, record in ipairs(running) do out[#out + 1] = record end
		for _, record in ipairs(done) do out[#out + 1] = record end
		return out
	end

	function M.running()
		local out = {}
		for _, record in ipairs(M.records) do
			if isLive(record) then out[#out + 1] = record end
		end
		return out
	end

	-- The finished dispatches that still have their context, newest first: the ones a
	-- follow-up can be sent to.
	function M.resumable()
		local out = {}
		for _, record in ipairs(M.records) do
			if record.session and not isLive(record) then out[#out + 1] = record end
		end
		return out
	end

	function M.get(id)
		for _, record in ipairs(M.records) do
			if record.id == id then return record end
		end
		return nil
	end

	-- Finds the dispatch the model named.
	--
	-- The id is what the report hands back, so that is the exact match. A label prefix
	-- is accepted too: a model that has lost the id reaches for the task's first line
	-- instead, and refusing that spends a step teaching it nothing.
	function M.find(reference)
		local needle = util.trim(tostring(reference or ""))
		if needle == "" then return nil end
		local exact = M.get(needle)
		if exact then return exact end
		local lowered = needle:lower()
		for _, record in ipairs(M.records) do
			if tostring(record.label):lower():find(lowered, 1, true) then return record end
		end
		return nil
	end

	-- Stops one dispatch without stopping the turn that asked for it.
	--
	-- The child notices between steps, so this returns before it has actually stopped;
	-- the record says so until its loop unwinds. There is no way to kill a Luau thread,
	-- which is why the flag is the mechanism everywhere in this client.
	function M.stop(id)
		local record = M.get(id)
		if not record or not record.session then return false end
		if not isLive(record) then return false end
		-- Preserve the stop request in the record as well as the child session. The child
		-- may finish between the click and its next cooperative check, and the record must
		-- still report the user-requested stop rather than a normal completion.
		record.stopping = true
		record.stopRequested = true
		record.session.abortFlag = true
		record.session.abort()
		record.session.abortFlag = true
		announceChange()
		log.info("subagent", "stop requested for " .. tostring(record.label))
		return true
	end

	function M.stopAll(parent)
		local stopped = 0
		for _, record in ipairs(M.running()) do
			if (not parent or record.parent == parent) and M.stop(record.id) then stopped = stopped + 1 end
		end
		return stopped
	end

	-- Clear finished history after its owner has collected any background report.
	-- Live work and unread current-turn reports still belong to that conversation.
	function M.clearHistory()
		local kept = {}
		for _, record in ipairs(M.records) do
			if isLive(record) or awaitingCollection(record) then kept[#kept + 1] = record
			elseif record.disconnect then record.disconnect(); record.disconnect = nil end
		end
		M.records = kept
		announceChange()
		return true
	end

	function M.available(depth)
		local limit = config.get("agent.subagentDepth", 2)
		return (depth or 0) < limit
	end

	-- How long a subagent may run, and how long the tool that started it waits.
	--
	-- Both come from one number on purpose. They used to be independent: the child was
	-- given four minutes and the call that started it was bounded by the generic
	-- `agent.toolTimeout` of twenty-five seconds, so nearly every dispatch was reported
	-- to the model as "did not finish within 25s and was left running in the
	-- background" -- and it was, against a caller that had stopped listening. The
	-- report arrived a minute later with nowhere to go, and the model, asked what its
	-- subagents found, could only say it never heard back.
	--
	-- The slack covers one request. A child notices its own deadline between steps, so
	-- it returns a moment after the budget expires rather than exactly on it, and the
	-- tool has to still be there to take the answer.
	local SLACK_SECONDS = 60

	-- Whether a child runs with its clocks off. Read per run rather than captured, so
	-- flipping the switch applies to the next dispatch and to the next follow-up on a
	-- child that has already reported.
	function M.unlimited()
		return config.get("agent.subagentUnlimited", false) == true
	end

	function M.budgetSeconds()
		return math.max(tonumber(config.get("agent.subagentBudget", 240)) or 240, 15)
	end

	-- A day, and it is not a deadline in disguise: with the ceiling lifted there is no
	-- budget to derive a timeout from, and the honest bound on the call above is "as
	-- long as the child takes". A caller that gives up first is the failure this number
	-- exists to avoid -- the child cannot be killed, so it finishes into a void and the
	-- user pays for a report nobody collects.
	local FOREVER_SECONDS = 86400

	function M.toolTimeout()
		if M.unlimited() then return FOREVER_SECONDS end
		return M.budgetSeconds() + SLACK_SECONDS
	end

	-- Width, not just depth.
	--
	-- Several dispatch_agent calls in one step run at the same time, which is the
	-- point: three searches in parallel cost one step instead of three. What that
	-- leaves unbounded is the tree. `agent.toolConcurrency` caps one batch, so it caps
	-- a parallel dispatch from the main conversation -- but a subagent given the
	-- `full` preset dispatches its own batch under its own cap, and two levels of
	-- that multiply rather than add. This is the ceiling on live children anywhere,
	-- and the depth cap above is no substitute for it.
	M.live = 0

	function M.concurrencyLimit()
		local limit = tonumber(config.get("agent.subagentConcurrency", 12))
		if not limit or limit ~= limit then limit = 12 end
		return math.max(1, math.min(12, math.floor(limit)))
	end

	-- A dispatch over the ceiling waits for a slot instead of failing: the model has
	-- already paid for the step that asked, and a refusal would spend another one
	-- learning that it asked for too much at once.
	--
	-- The wait is bounded and comes out of the child's own budget, which is what keeps
	-- `toolTimeout` a valid bound on the call above it. Without that subtraction a
	-- queued child could finish after the tool that started it had given up, and a
	-- report nobody is left to collect is exactly the failure the budget and the
	-- timeout were tied together to prevent.
	--
	-- Returns the budget to run on, `nil` when there is no budget to run against, or
	-- `false` when the turn was stopped while queued. An unlimited child has nothing to
	-- subtract from, so its wait is capped by the ceiling alone.
	local QUEUE_CEILING = 45

	local function waitForSlot(budget, aborted)
		local ceiling = budget and math.min(QUEUE_CEILING, budget / 4) or QUEUE_CEILING
		local waited = 0
		while M.live >= M.concurrencyLimit() and waited < ceiling do
			if aborted and aborted() then return false end
			waited = waited + (clock.wait(0.2) or 0.2)
		end
		if waited <= 0 then return budget end
		log.info("subagent", string.format("queued %.1fs for a slot (%d live)", waited, M.live))
		if not budget then return nil end
		return math.max(budget - waited, 15)
	end

	-- The card in the transcript is titled with the task, so the first line of it is
	-- what the user reads to tell three concurrent subagents apart.
	local function labelFor(task)
		local first = tostring(task):match("^%s*([^\n]*)") or ""
		first = util.trim(first)
		if first == "" then first = "task" end
		return util.ellipsis(first, 64)
	end

	-- A parent must both finish its workers and read their reports. Uncollected
	-- reports remain addressable even after their expensive child context expires.
	function M.pending(parent)
		local out = {}
		local epoch = parent and parent.toolEpoch or nil
		for _, record in ipairs(M.records) do
			if record.background and record.parent == parent and record.parentEpoch == epoch
				and (isLive(record) or awaitingCollection(record)) then out[#out + 1] = record end
		end
		return out
	end

	function M.markCollected(record, parent, runs, runEpoch)
		if type(record) ~= "table" or M.get(record.id) ~= record or isLive(record)
			or record.parent ~= parent or record.parentEpoch ~= (parent and parent.toolEpoch or nil)
			or (runs ~= nil and runs ~= (record.runs or 0))
			or (runEpoch ~= nil and runEpoch ~= record.runEpoch) then return false end
		record.collectedRun = record.runs or 0
		trimHistory()
		announceChange()
		return true
	end

	function M.backgroundLimit()
		return math.min(24, M.concurrencyLimit() * 2)
	end

	-- The monitor keeps bounded display data, never another copy of the child's
	-- context. Parallel progress is matched by call id; an unscoped legacy update
	-- is usable only when exactly one call remains outstanding.
	local function activityFor(record, id)
		local only
		for _, item in ipairs(record.activity or {}) do
			if id ~= nil and item.id == id then return item end
			if not item.done then only = item end
		end
		local pending = (record.calls or 0) - (record.runCallBase or 0)
			- ((record.finishedCalls or 0) - (record.runFinishedBase or 0))
		if id == nil and pending == 1 then return only end
	end

	local function latestExcerpt(value)
		value = tostring(value or "")
		if #value <= PREVIEW_BYTES then return value, false end
		return "...\n" .. value:sub(codeText.clamp(value, #value - PREVIEW_BYTES + 5, true)), true
	end

	local function trimActivity(record)
		if #record.activity <= ACTIVITY_LIMIT then return end
		-- A slow parallel call remains observable as shorter calls finish around it.
		-- If every retained call is pending, the fixed cap still takes precedence.
		for index, item in ipairs(record.activity) do
			if item.done then table.remove(record.activity, index); return end
		end
		table.remove(record.activity, 1)
	end

	local function currentTool(record)
		record.currentTool = nil
		for index = #(record.activity or {}), 1, -1 do
			local item = record.activity[index]
			if not item.done then record.currentTool = item.name; return end
		end
	end

	local function finishActivity(record)
		record.currentTool, record.preview, record.request = nil, nil, nil
		for _, item in ipairs(record.activity or {}) do
			if not item.done then
				item.done, item.interrupted = true, true
			end
		end
	end

	-- Live view.
	--
	-- The transcript renders the parent's event stream and nothing else, so a subagent
	-- that wants to be watched has to speak through it. Every event carries the child's
	-- id, which keys the card, and the id of the tool call that started it, which tells
	-- the view what to nest the card under.
	--
	-- One subscription per child, made with it and kept for the rest of its life: a
	-- follow-up runs the same session again, and a second subscription would draw every
	-- row twice. Which conversation to narrate into is read off the record rather than
	-- captured here, for the same reason -- the turn asking a follow-up is a different
	-- tool call, sometimes in a different conversation, and the card has to appear under
	-- the row the user is looking at now.
	--
	-- Tool RESULTS are summarised to one line rather than forwarded: absorbing that
	-- volume is the entire point of a subagent, and the parent's log is bounded. What
	-- does go across is names, outcomes and timings, because that is the difference
	-- between watching work happen and watching a spinner.
	local function wire(record, child)
		local function announce(kind, payload)
			local parent = record.parent
			-- A stale child must not narrate into a different, still-live parent turn.
			-- An aborted turn moved the epoch too, but its child's final "stopped" still
			-- belongs on the card, so that one is allowed through.
			if not parent or parent.removed or (record.parentEpoch and parent.toolEpoch ~= record.parentEpoch and not parent.aborted()) then return end
			payload = payload or {}
			payload.id = record.id
			payload.call = record.callId
			payload.label = record.label
			parent.emit(kind, payload)
		end
		record.announce = announce

		-- Stop has to reach the child, from whichever conversation is waiting on it.
		-- Without this, aborting the turn left every dispatched subagent running out its
		-- full budget against a conversation that had already moved on -- billed,
		-- invisible and unstoppable.
		child.aborted = function()
			if not alive or not isLive(record) or child.abortFlag == true then return true end
			local parent = record.parent
			if parent and (parent.aborted() or parent.removed or parent.toolEpoch ~= record.parentEpoch) then child.abortFlag = true end
			return child.abortFlag == true
		end

		record.disconnect = child.events:connect(function(event)
			if not isLive(record) then return end
			if event.kind == "tool:call" then
				record.calls = (record.calls or 0) + 1
				record.currentTool = tostring(event.name)
				record.activity[#record.activity + 1] = {
					id = event.id, index = record.calls, name = util.ellipsis(tostring(event.name), 120),
					startedAt = event.at or clock.ms(),
				}
				trimActivity(record)
				-- Names only, and the last twelve of them: the register is read by a
				-- panel that lists every dispatch in the session, so it cannot hold
				-- their arguments as well.
				record.tools[#record.tools + 1] = tostring(event.name)
				if #record.tools > 12 then table.remove(record.tools, 1) end
				announceChange()
				announce("subagent:tool", {
					callId = event.id,
					name = event.name,
					risk = event.risk,
					-- Forwarded whole, and summarised by the view instead.
					--
					-- A child session is headless and therefore keeps no log of its own, so
					-- this event is the only record that the call ever happened. At 160
					-- characters, whitespace-collapsed, the Luau a subagent executed was
					-- unrecoverable -- and a subagent is exactly where the long-running code
					-- in this client gets run. Detailed activity has its own bounded
					-- transcript budget and cannot evict dialogue or dispatch summaries.
					arguments = tostring(event.arguments or ""),
					index = record.calls - (record.runCallBase or 0),
				})
			elseif event.kind == "tool:result" or event.kind == "tool:error" then
				local item = activityFor(record, event.id)
				record.finishedCalls = (record.finishedCalls or 0) + 1
				if item then
					item.done, item.ok, item.ms = true, event.kind == "tool:result" and event.ok ~= false, event.ms
					item.summary = util.ellipsis(tostring(event.text or event.error or ""), 1024)
				end
				currentTool(record)
				if record.calls - (record.runCallBase or 0) == record.finishedCalls - (record.runFinishedBase or 0) then
					record.statusText = "Preparing next step"
				end
				announceChange()
				announce("subagent:tool:done", {
					callId = event.id,
					finishedCalls = record.finishedCalls - (record.runFinishedBase or 0),
					name = event.name,
					ok = event.kind == "tool:result",
					ms = event.ms,
					summary = util.ellipsis(tostring(event.text or ""):gsub("%s+", " "), 140),
					-- The full result as well, for the row that can open. `summary` is what
					-- the collapsed line shows and stays short.
					text = tostring(event.text or ""),
				})
			elseif event.kind == "tool:progress" then
				local item = activityFor(record, event.id)
				if item and not item.done then
					item.progress = util.ellipsis(tostring(event.text or ""), 1024)
					announceChange()
				end
			elseif event.kind == "request:start" then
				record.preview = nil
				record.statusText = "Waiting for provider output"
				record.request = { provider = event.provider, model = event.model, attempt = event.attempt }
				record.provider, record.model = event.provider, event.model
				announceChange()
			elseif event.kind == "request:retry" then
				record.statusText = string.format("Retrying %s (attempt %s): %s", tostring(event.provider or "provider"),
					tostring(event.attempt or ""), util.ellipsis(tostring(event.reason or ""), 200))
				announceChange()
			elseif event.kind == "request:done" then
				record.request = nil
				if event.error then record.preview = nil end
				announceChange()
			elseif event.kind == "assistant:preview" then
				local text, textExcerpt = latestExcerpt(event.text)
				local reasoning, reasoningExcerpt = latestExcerpt(event.reasoning)
				record.preview = { text = text, reasoning = reasoning, textExcerpt = textExcerpt,
					reasoningExcerpt = reasoningExcerpt, limited = event.limited == true }
				announceChange()
			elseif event.kind == "assistant:complete" then
				record.preview = nil
				announceChange()
			elseif event.kind == "assistant:reasoning" then
				record.latestReasoning, record.reasoningExcerpt = latestExcerpt(event.text)
				if record.preview then record.preview.reasoning = "" end
				announceChange()
			elseif event.kind == "assistant:text" then
				if util.trim(tostring(event.text or "")) ~= "" then
					record.latestText, record.textExcerpt = latestExcerpt(event.text)
					if record.preview then record.preview.text = "" end
					announceChange()
					announce("subagent:text", { text = util.ellipsis(util.trim(event.text), 400) })
				end
			elseif event.kind == "status" then
				-- "Ready" is the child's own idle text and means nothing on a card that
				-- reports its finish separately. Dropping it here rather than in the
				-- view keeps one entry per turn out of the parent's bounded log.
				if tostring(event.text) ~= "Ready" then
					record.statusText = util.ellipsis(tostring(event.text), 1024)
					announceChange()
					announce("subagent:status", { text = tostring(event.text) })
				end
			elseif event.kind == "error" then
				record.statusText = util.ellipsis(tostring(event.message), 1024)
				record.preview, record.request = nil, nil
				announceChange()
				announce("subagent:status", { text = tostring(event.message), bad = true })
			elseif event.kind == "permission:ask" then
				-- Nothing is subscribed to a headless session, so a prompt raised
				-- inside a subagent has to surface on the parent's stream or it
				-- would sit unanswered until its own deadline.
				local parent = record.parent
				if parent then parent.emit("permission:ask", event) end
			end
		end)
	end

	-- Reserve this run before publishing it or scheduling its worker. In particular,
	-- Stop and a parent generation change after admission must survive until the
	-- worker starts; the worker never resets these flags or adopts a newer epoch.
	local function prepareRun(record, text, background)
		local child = record.session
		record.background = background == true
		record.parentEpoch = record.parent and record.parent.toolEpoch
		record.stopRequested, record.stopping, record.currentTool = nil, nil, nil
		record.status, record.startedAt = "queued", clock.ms()
		record.ms, record.messages, record.turnsUsed, record.report = nil, nil, nil, nil
		record.error, record.ok, record.aborted = nil, nil, nil
		record.collectedRun = nil
		record.preview, record.latestText, record.latestReasoning, record.request = nil, nil, nil, nil
		record.textExcerpt, record.reasoningExcerpt = nil, nil
		record.provider, record.model = nil, nil
		record.activity, record.currentTask, record.statusText = {}, text, "Waiting for a slot"
		record.runCallBase, record.runFinishedBase = record.calls or 0, record.finishedCalls or 0
		child.toolEpoch = {}
		record.runEpoch = child.toolEpoch
		child.abortFlag = false
	end

	-- Blocking and background entry points share the same slots, budgets, child
	-- loop, event forwarding and completion state.
	local function runChild(record, text, opts)
		opts = opts or {}
		local child = record.session
		local unlimited = M.unlimited()
		local announce = record.announce
		local requestedBudget
		if not unlimited then requestedBudget = opts.budgetSeconds or M.budgetSeconds() end
		local budget = waitForSlot(requestedBudget, child.aborted)
		if budget == false or child.aborted() or M.live >= M.concurrencyLimit() then
			M.stopAll(child)
			record.status = "stopped"
			record.stopping = nil
			record.ms = clock.since(record.startedAt)
			record.report = "Stopped before it started."
			record.ok, record.aborted = false, true
			finishActivity(record)
			trimHistory()
			announceChange()
			announce("subagent:done", { ms = record.ms, ok = false, aborted = true, text = record.report,
				calls = 0, finishedCalls = 0 })
			return nil, "the turn was stopped before this subagent started"
		end

		child.turns = child.turns + 1
		child.unlimited = unlimited
		child.budgetSeconds = budget
		if opts.turns then child.maxTurns = opts.turns end
		record.status = "running"
		record.statusText = "Starting"
		record.stopping = nil
		record.startedAt = clock.ms()
		record.budget = budget
		record.unlimited = unlimited
		record.turns = child.maxTurns
		record.runs = (record.runs or 0) + 1
		announceChange()

		announce("subagent:start", {
			startedAt = record.startedAt,
			task = util.ellipsis(text, 400),
			preset = record.preset,
			turns = unlimited and 0 or child.maxTurns,
			budget = budget,
			unlimited = unlimited,
			depth = record.depth,
			followUp = record.runs > 1,
		})

		-- Counted around the pcall rather than around the whole setup, so a raise
		-- anywhere inside cannot leak a slot and permanently narrow the ceiling.
		local started = clock.ms()
		M.live = M.live + 1
		local ok, reply = pcall(function() return env.require("agent/loop").run(child, text) end)
		M.live = math.max(M.live - 1, 0)
		M.stopAll(child)

		local elapsed = clock.since(started)
		if not ok then
			child.abortFlag = true
			log.warn("subagent", "failed", reply)
			local note = "the subagent failed: " .. util.ellipsis(tostring(reply), 200)
			record.status = "failed"
			record.stopping = nil
			record.ms = elapsed
			record.report = note
			record.error, record.ok = note, false
			finishActivity(record)
			trimHistory()
			announceChange()
			announce("subagent:done", { ms = elapsed, ok = false, text = note,
				calls = (record.calls or 0) - record.runCallBase,
				finishedCalls = (record.finishedCalls or 0) - record.runFinishedBase })
			return nil, note
		end

		local stats = child.ctx.stats()
		local aborted = record.stopRequested == true or child.aborted() == true
		log.info("subagent", string.format("finished in %s over %d messages%s",
			util.formatDuration(elapsed), stats.messages, aborted and " (stopped)" or ""))

		record.status = aborted and "stopped" or "done"
		record.ok, record.aborted = not aborted, aborted
		record.ms = elapsed
		record.messages = stats.messages
		record.turnsUsed = stats.turns
		record.report = tostring(reply)
		finishActivity(record)
		record.stopping = nil
		-- Now that this one has finished, it is the newest resumable record -- which is
		-- what pushes the oldest past the line and releases the context behind it.
		trimHistory()
		announceChange()

		announce("subagent:done", {
			ms = elapsed,
			calls = (record.calls or 0) - record.runCallBase,
			finishedCalls = (record.finishedCalls or 0) - record.runFinishedBase,
			ok = not aborted,
			aborted = aborted,
			messages = stats.messages,
			turns = stats.turns,
			resumable = record.session ~= nil and not aborted,
			text = util.ellipsis(tostring(reply), 600),
		})

		return {
			id = record.id,
			text = tostring(reply),
			ms = elapsed,
			messages = stats.messages,
			turns = stats.turns,
			aborted = aborted,
			resumable = record.session ~= nil,
		}
	end

	local function prepareDispatch(opts, background)
		if not alive then return nil, "the client is unloading" end
		if type(opts) ~= "table" then return nil, "dispatch options must be a table" end
		local preset = opts.preset or "read"
		if preset ~= "full" and M.PRESETS[preset] == nil then
			return nil, "unknown subagent preset; use read, web, game or full"
		end
		local parent = opts.parent
		local depth = (parent and parent.depth or 0) + 1

		if not M.available(depth - 1) then
			return nil, "subagent depth limit reached (" .. tostring(config.get("agent.subagentDepth", 2)) .. ")"
		end

		local task_text = util.trim(opts.task)
		if task_text == "" then return nil, "a subagent needs a task" end

		local turns = opts.turns or config.get("agent.subagentTurns", 14)

		-- Registered before the queue wait, so a dispatch parked waiting for a slot is
		-- visible as one rather than looking like nothing happened.
		local record = {
			id = util.uid("agent"),
			label = labelFor(task_text),
			task = task_text,
			preset = preset,
			depth = depth,
			-- The conversation currently waiting on this child, and the tool call inside
			-- it. Both move when a follow-up arrives from somewhere else, which is why
			-- they live on the record rather than in a closure.
			parent = parent,
			callId = opts.callId,
			parentId = parent and parent.id or nil,
			parentTitle = parent and parent.title or nil,
			turns = turns,
		}

		-- A child cannot ask, and a headless worker has no conversation of its own to
		-- name: both tools are absent from its catalogue rather than described and
		-- refused.
		local excluded = { ask_user = true, conversation_rename = true }
		if record.preset ~= "full" then
			-- Every preset can read relevant skills. This does not grant a
			-- restricted worker permission to change the user's standing playbooks.
			excluded.skills_write, excluded.skills_install, excluded.skills_delete = true, true, true
		end
		-- Groups contain both inspection and mutation tools. Capture an explicit
		-- read allowlist so this preset cannot inherit writes from those groups.
		local readTools
		if preset == "read" then
			readTools = {}
			for _, tool in ipairs(env.require("agent/registry").list()) do
				if tool.risk == "read" then readTools[tool.name] = true end
			end
		end
		readTools = env.require("agent/delegation_scope").intersect(readTools, parent, opts.requestToolNames)
		local child = session.create({
			title = "subagent",
			depth = depth,
			headless = true,
			maxTurns = turns,
			toolGroups = M.PRESETS[preset],
			toolFilter = readTools,
			-- A child has no user to ask, so the tool that asks is absent from its
			-- catalogue entirely rather than described-and-refused. The brief also
			-- says so, because a model that knows it cannot ask writes a complete
			-- report instead of stopping at a question.
			toolExclude = excluded,
			-- Keep the provider's stream setting: buffered HTTP can carry reasoning and
			-- usage metadata, while a compatible socket can also deliver live previews.
		})
		-- The record is what the Subagents panel reads, so it is kept whether or not
		-- there is a parent transcript to narrate into. The wiring below is therefore
		-- unconditional; only the forwarding inside it is not.
		record.session = child
		child.accountingParent = function() return record.parent end

		-- The brief replaces the main system prompt rather than appending to it, and it
		-- is a function so that every turn -- including a follow-up months of tool calls
		-- later -- is built against the environment and the switches in force then.
		-- Carrying it on the session, instead of swapping the prompt module's builder, is
		-- what makes two subagents dispatched in the same batch safe.
		child.systemPrompt = function(request)
			request = request or {}
			return prompt.subagent(task_text, {
				extra = (opts.extra or "") .. "\nNative workspace references are shared with the user. Respect this subagent's tool scope; never use a controller or generated script to bypass a denied native action.",
				unlimited = M.unlimited(),
				tools = request.tools,
				model = request.model,
				provider = request.provider,
				opencodeCompatibility = request.opencodeCompatibility,
				session = child,
			})
		end

		wire(record, child)
		prepareRun(record, task_text, background)
		return track(record), task_text
	end

	-- Existing callers can still request a blocking dispatch explicitly.
	function M.dispatch(opts)
		local record, text = prepareDispatch(opts, false)
		if not record then return nil, text end
		return runChild(record, text, opts)
	end

	-- A second turn on a subagent that has already reported back.
	--
	-- A dispatch used to be one shot: the child answered, its context went on the floor,
	-- and a parent that wanted one more fact had to describe the whole job again to a
	-- fresh subagent that would go and rediscover it. This continues the same
	-- conversation instead -- the child still has everything it found -- which is what
	-- makes a subagent that stopped at a limit worth talking to rather than worth
	-- replacing, and what lets the parent steer one instead of only reading it.
	local function prepareFollowUp(opts, background)
		if not alive then return nil, "the client is unloading" end
		local record = M.find(opts.id)
		if not record then
			local open = M.resumable()
			if #open == 0 then
				return nil, "no subagent is open for a follow-up. Dispatch one with dispatch_agent first."
			end
			local names = {}
			for _, candidate in ipairs(open) do
				names[#names + 1] = string.format("%s (%s)", candidate.id, candidate.label)
			end
			return nil, string.format("no subagent matches '%s'. Open for a follow-up: %s",
				tostring(opts.id), table.concat(names, "; "))
		end
		if isLive(record) then
			return nil, "that subagent is still working. Check its status before sending a follow-up."
		end
		if not record.session then
			return nil, "that subagent's context has already been released, so there is nothing to continue. Dispatch a new one with what you know."
		end

		local text = util.trim(opts.task)
		if text == "" then return nil, "a follow-up needs a message" end

		local parent = opts.parent or record.parent
		if parent ~= record.parent and awaitingCollection(record) then
			return nil, "that subagent's report must be collected by its current conversation before transferring it"
		end
		if background then
			local depth = (parent and parent.depth or 0) + 1
			if not M.available(depth - 1) then return nil, "subagent depth limit reached" end
			record.depth, record.session.depth = depth, depth
		end
		record.parent = parent
		record.session.toolFilter = env.require("agent/delegation_scope").intersect(record.session.toolFilter, parent, opts.requestToolNames)
		record.parentId, record.parentTitle = parent and parent.id or nil, parent and parent.title or nil
		record.callId = opts.callId
		prepareRun(record, text, background)
		announceChange()
		return record, text
	end

	function M.followUp(opts)
		local record, text = prepareFollowUp(opts, false)
		if not record then return nil, text end
		return runChild(record, text, { turns = opts.turns })
	end

	local function backgroundFailure(record, reason)
		local note = "the subagent failed: " .. util.ellipsis(tostring(reason), 200)
		if record.session then record.session.abortFlag = true; M.stopAll(record.session) end
		record.status, record.stopping = "failed", nil
		record.report, record.error, record.ok = note, note, false
		record.ms = clock.since(record.startedAt or clock.ms())
		finishActivity(record)
		trimHistory()
		announceChange()
		record.announce("subagent:done", { ms = record.ms, ok = false, text = note,
			calls = (record.calls or 0) - (record.runCallBase or 0),
			finishedCalls = (record.finishedCalls or 0) - (record.runFinishedBase or 0) })
	end

	local function startBackground(opts, prepare)
