	local M = {}
	local FIELD_CAP, EVENT_BYTES = 24000, 65536
	local BUDGETS = {
		conversation = { events = 512, bytes = 1048576 },
		lifecycle = { events = 128, bytes = 262144 },
		activity = { events = 256, bytes = 262144 },
	}
