-- agent/usage
-- ==========================================================================
__UAI_MODULES["agent/usage"] = (function()
-- Token and cost accounting.
--
-- Providers report usage inconsistently -- some only in a streamed final chunk,
-- some not at all -- so counts are taken from the response when present and
-- estimated when not, and an estimated figure is always labelled as one. Prices
-- are a convenience, not an invoice: the reviewed catalog uses per-million
-- text-token rates; provider-specific surcharges and discounts may differ.
return function(env)
	local util = env.require("runtime/util")
	local signal = env.require("runtime/signal")
	local pricing = env.require("agent/pricing")
	local function count(value)
		local number = tonumber(value)
		if not number or number ~= number or number < 0 or number > 9007199254740991 then return nil end
		return math.floor(number)
	end

	local M = {
		session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false },
		turn = { prompt = 0, completion = 0, total = 0, cost = 0 },
		changed = signal.new("usage"),
		-- One request, as it was measured, rather than the running totals `changed`
		-- carries. This is the only place in the client where a model id and the tokens
		-- it actually spent are in scope together, so anything keeping a per-model
		-- history has to hear about it here.
		recorded = signal.new("usage:recorded"),
	}

	function M.priceFor(model, record, promptTokens)
		return pricing.priceFor(model, record, promptTokens)
	end

	-- A byte-based heuristic, not a tokenizer. Code and Unicode vary by model;
	-- dispatch-time usage calibration corrects the observed request estimate.
	function M.estimateText(text)
		if type(text) ~= "string" then return 0 end
		return math.ceil(#text / 4)
	end

	function M.estimateMessages(messages)
		local total = 0
		for _, message in ipairs(messages or {}) do
			-- Per-message framing overhead, plus the role name.
			total = total + 4 + M.estimateText(message.content)
			-- Image costs depend on the model. Reserve a conservative estimate until
			-- provider usage calibrates the request; never count base64 as prose.
			total = total + #(message.images or {}) * 1600
			if type(message.content) == "table" then
				for _, block in ipairs(message.content) do
					if block.type == "text" then total = total + M.estimateText(block.text)
					elseif block.type == "image_url" or block.type == "image" then total = total + 1600 end
				end
			end
			local reasoning = message.reasoning_content or message.reasoning
			if reasoning then total = total + M.estimateText(reasoning) end
			-- Internal messages carry toolCalls; wire messages carry tool_calls, and
			-- the loop estimates over the wire form.
			for _, call in ipairs(message.toolCalls or message.tool_calls or {}) do
				local fn = call["function"] or {}
				local args = type(fn.arguments) == "table" and util.encode(fn.arguments) or fn.arguments
				total = total + 8 + M.estimateText(fn.name) + M.estimateText(args)
			end
		end
		return total
	end

	function M.startTurn()
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
	end

	-- `usage` is the provider block when it exists. `fallback` supplies estimates
	-- so a provider that reports nothing still moves the counters.
	function M.record(usage, model, fallback, record)
		usage = type(usage) == "table" and usage or {}
		local prompt = count(usage.prompt_tokens) or count(usage.input_tokens)
		local completion = count(usage.completion_tokens) or count(usage.output_tokens)
		local estimated = prompt == nil or completion == nil
		prompt = prompt or count(fallback and fallback.prompt) or 0
		completion = completion or count(fallback and fallback.completion) or 0

		local cached = count(util.get(usage or {}, "prompt_tokens_details.cached_tokens",
			util.get(usage or {}, "input_tokens_details.cached_tokens", 0))) or 0
		local created = count(util.get(usage or {}, "cache_creation_input_tokens",
			util.get(usage or {}, "prompt_tokens_details.cache_creation_tokens", 0))) or 0
		local reasoning = count(util.get(usage or {}, "completion_tokens_details.reasoning_tokens",
			util.get(usage or {}, "output_tokens_details.reasoning_tokens", 0))) or 0
		cached = math.min(cached, prompt)
		created = math.min(created, prompt - cached)
		reasoning = math.min(reasoning, completion)
		local pricedCost = pricing.costFor(model, record, prompt, completion, cached, created)
		local cost = pricedCost or 0

		if not (fallback and fallback.background) then
			M.turn.prompt = M.turn.prompt + prompt
			M.turn.completion = M.turn.completion + completion
			M.turn.total = M.turn.prompt + M.turn.completion
			M.turn.cost = M.turn.cost + cost
		end

		M.session.prompt = M.session.prompt + prompt
		M.session.completion = M.session.completion + completion
		M.session.total = M.session.prompt + M.session.completion
		M.session.cost = M.session.cost + cost
		M.session.requests = M.session.requests + 1
		if pricedCost == nil then M.session.unpriced = (M.session.unpriced or 0) + 1 end
		if estimated then M.session.estimated = true end

		M.session.cached = (M.session.cached or 0) + cached
		M.session.cacheCreated = (M.session.cacheCreated or 0) + created
		M.session.reasoning = (M.session.reasoning or 0) + reasoning

		local delta = {
			model = model,
			prompt = prompt,
			completion = completion,
			cost = cost,
			costKnown = pricedCost ~= nil,
			estimated = estimated,
			cached = tonumber(cached) or 0,
			cacheCreated = created,
			reasoning = tonumber(reasoning) or 0,
		}
		env.require("runtime/request_accounting").report(fallback and fallback.accounting, usage, { prompt = prompt, completion = completion })
		M.recorded:fire(delta)
		M.changed:fire(M.session, M.turn)
		return { prompt = prompt, completion = completion, cost = cost, costKnown = pricedCost ~= nil, estimated = estimated }
	end

	function M.reset()
		M.session = { prompt = 0, completion = 0, total = 0, cost = 0, requests = 0, estimated = false }
		M.turn = { prompt = 0, completion = 0, total = 0, cost = 0 }
		M.changed:fire(M.session, M.turn)
	end

	function M.formatCost(value)
		if value <= 0 then return "" end
		if value < 0.01 then return string.format("$%.4f", value) end
		return string.format("$%.3f", value)
	end

	function M.line()
		local parts = {
			util.formatNumber(M.session.total) .. " tokens",
			util.formatNumber(M.session.prompt) .. " in",
			util.formatNumber(M.session.completion) .. " out",
		}
		local cost = M.formatCost(M.session.cost)
		if cost ~= "" then parts[#parts + 1] = cost .. " est." end
		if (M.session.unpriced or 0) > 0 then parts[#parts + 1] = "some costs unknown" end
		return table.concat(parts, "  ")
	end

	return M
end
end)()

-- ==========================================================================
-- embedding/scope
-- ==========================================================================
__UAI_MODULES["embedding/scope"] = (function()
-- A host's tools, hooks and subscriptions share one explicit client lifetime.
return function(env)
	local util = env.require("runtime/util")
	local log = env.require("runtime/log")
	local dispose = env.require("runtime/dispose")
	local tools = env.require("agent/registry")
	local hooks = env.require("agent/hooks")
	local clock = env.require("runtime/clock")
	local M = {}
	local owners = setmetatable({}, { __mode = "k" })
	local TYPES = { object = true, array = true, string = true, number = true, integer = true, boolean = true, null = true }

	local function finite(value)
		return type(value) == "number" and value == value and math.abs(value) ~= math.huge
	end

	local function identifier(value)
		return type(value) == "string" and #value > 0 and #value <= 64 and value:match("^[%w_%-]+$") ~= nil
	end

	local function array(value, strings)
		if type(value) ~= "table" then return false end
		local count = 0
		for key, item in pairs(value) do
			if type(key) ~= "number" or key < 1 or key ~= math.floor(key) then return false end
			if strings and (type(item) ~= "string" or util.trim(item) == "") then return false end
			count = count + 1
		end
		return count == #value
	end

	-- Copy JSON-shaped data without metatables, cycles or arbitrary host objects.
	-- Bounds also keep a malformed schema from overflowing the Lua stack.
	local function copyData(value, ancestors, state, depth)
		local kind = type(value)
		if kind ~= "table" then
			if kind == "string" then
				state.bytes = state.bytes + #value
				if state.bytes > 262144 or not util.validUtf8(value) then error("parameters exceed 256 KiB or contain invalid UTF-8", 0) end
				return value
			end
			if kind == "boolean" or (kind == "number" and finite(value)) then return value end
			error("parameters must contain only finite JSON data", 0)
		end
		if depth > 32 or state.nodes >= 8192 then error("parameters exceed the schema size/depth limit", 0) end
		if ancestors[value] then error("parameters must not contain cycles", 0) end
		ancestors[value] = true
		local out = {}
		for key, child in pairs(value) do
			state.nodes = state.nodes + 1
			if state.nodes > 8192 then error("parameters exceed the schema size/depth limit", 0) end
			if type(key) ~= "string" and not (finite(key) and key >= 1 and key == math.floor(key)) then
				error("parameters contain an invalid table key", 0)
			end
			if type(key) == "string" then
				state.bytes = state.bytes + #key
				if state.bytes > 262144 or not util.validUtf8(key) then error("parameter names exceed the schema size limit or contain invalid UTF-8", 0) end
			end
			out[key] = copyData(child, ancestors, state, depth + 1)
		end
		ancestors[value] = nil
		return out
	end

	local function validateSchema(schema)
		if type(schema) ~= "table" then return false, "each parameter schema must be a table" end
		if schema.type ~= nil then
			if type(schema.type) == "table" then
				if not array(schema.type, true) or #schema.type == 0 then return false, "schema type must name supported JSON types" end
				for _, kind in ipairs(schema.type) do if not TYPES[kind] then return false, "unsupported schema type" end end
			elseif not TYPES[schema.type] then return false, "unsupported schema type" end
		end
		if schema.required ~= nil and not array(schema.required, true) then return false, "schema required must be an array of names" end
		if schema.enum ~= nil and not array(schema.enum) then return false, "schema enum must be an array" end
		for _, key in ipairs({ "minimum", "maximum", "minLength", "maxLength", "minItems", "maxItems" }) do
			if schema[key] ~= nil and not finite(schema[key]) then return false, "schema " .. key .. " must be a finite number" end
		end
		for _, key in ipairs({ "minLength", "maxLength", "minItems", "maxItems" }) do
			if schema[key] ~= nil and (schema[key] < 0 or schema[key] % 1 ~= 0) then return false, "schema " .. key .. " must be a nonnegative integer" end
		end
		for _, pair in ipairs({ { "minimum", "maximum" }, { "minLength", "maxLength" }, { "minItems", "maxItems" } }) do
			if schema[pair[1]] ~= nil and schema[pair[2]] ~= nil and schema[pair[1]] > schema[pair[2]] then return false, "schema minimum exceeds its maximum" end
		end
		if schema.properties ~= nil then
			if type(schema.properties) ~= "table" then return false, "schema properties must be a table" end
			if not util.isEmptyObject(schema.properties) then
				for key, child in pairs(schema.properties) do
					if type(key) ~= "string" then return false, "schema property names must be strings" end
					local ok, why = validateSchema(child)
					if not ok then return false, why end
				end
			end
		end
		if schema.items ~= nil then
			local ok, why = validateSchema(schema.items)
			if not ok then return false, why end
		end
		if schema.additionalProperties ~= nil and type(schema.additionalProperties) ~= "boolean" then
			local ok, why = validateSchema(schema.additionalProperties)
			if not ok then return false, why end
		end
		for _, key in ipairs({ "anyOf", "oneOf", "allOf" }) do
			if schema[key] ~= nil then
				if not array(schema[key]) or #schema[key] == 0 then return false, "schema " .. key .. " must be a nonempty schema array" end
				for _, child in ipairs(schema[key]) do
					local ok, why = validateSchema(child)
					if not ok then return false, why end
				end
			end
		end
		return true
	end

	local function definition(input)
		if type(input) ~= "table" then return nil, "tool definition must be a table" end
		if not identifier(input.name) then return nil, "tool name must use 1-64 letters, digits, underscores or hyphens" end
		if input.group ~= nil and not identifier(input.group) then return nil, "tool group must use 1-64 letters, digits, underscores or hyphens" end
		if input.risk ~= nil and input.risk ~= "read" and input.risk ~= "write" and input.risk ~= "danger" then return nil, "tool risk must be read, write or danger" end
		if type(input.description) ~= "string" or util.trim(input.description) == "" or #input.description > 16000 or not util.validUtf8(input.description) then
			return nil, "tool description must be nonempty UTF-8 text of at most 16,000 bytes"
		end
		if type(input.run) ~= "function" then return nil, "tool run must be a function" end
		if input.prepare ~= nil and type(input.prepare) ~= "function" then return nil, "tool prepare must be a function" end
		if input.timeout ~= nil and type(input.timeout) ~= "function" and not (finite(input.timeout) and input.timeout > 0) then return nil, "tool timeout must be a positive finite number or function" end
		if input.needs ~= nil and not array(input.needs, true) then return nil, "tool needs must be an array of capability names" end
		local parameters = input.parameters
		if parameters == nil then parameters = { type = "object", properties = {}, required = {} } end
		if type(parameters) ~= "table" or parameters.type ~= "object" then return nil, "tool parameters must be an object schema" end
		local copied, schema = pcall(copyData, parameters, {}, { nodes = 0, bytes = 0 }, 0)
		if not copied then return nil, tostring(schema) end
		local valid, why = validateSchema(schema)
		if not valid then return nil, why end
		local needs = {}
		for index, key in ipairs(input.needs or {}) do needs[index] = key end
		return {
			name = input.name, group = input.group or "misc", risk = input.risk or "write",
			description = input.description, parameters = schema, needs = needs,
			run = input.run, prepare = input.prepare, timeout = input.timeout,
		}
	end

	local function member(object, key)
		local ok, value = pcall(function() return object[key] end)
		if ok and type(value) == "function" then return value end
		return nil
	end

	function M.create(handle, id)
		if type(handle) ~= "table" or handle.alive ~= true then return nil, "client is unloaded" end
		if type(id) ~= "string" or util.trim(id) == "" or #id > 128 then return nil, "scope id must be a nonempty string of at most 128 bytes" end
		if not util.validUtf8(id) or id:find("[%z\1-\31\127]") then return nil, "scope id must use valid UTF-8 without control characters" end
		if dispose.draining then return nil, "client is unloading" end
		local owned = owners[handle]
		if not owned then owned = {}; owners[handle] = owned end
		if owned[id] then return nil, "scope id is already in use: " .. id end
		local scope = { id = id, alive = true }
		local entries, closed, removeFromClient = {}, false, nil
		owned[id] = scope

		local function active()
			return not closed and handle.alive == true and not dispose.draining
		end

		local function invoke(fn)
			local ok, err = pcall(fn)
			if not ok then log.warn("embedding", "scope " .. id .. " cleanup failed", err) end
		end

		function scope.give(fn)
			if type(fn) ~= "function" then return nil, "cleanup must be a function" end
			if not active() then invoke(fn); return nil, "scope is destroyed or client is unloaded" end
			local entry = { fn = fn }
			local function release()
				local cleanup = entry.fn
				if not cleanup then return false end
				entry.fn = nil
				for index, candidate in ipairs(entries) do
					if candidate == entry then table.remove(entries, index); break end
				end
				invoke(cleanup)
				return true
			end
			entry.release = release
			entries[#entries + 1] = entry
			return release
		end

		function scope.connect(signal, fn)
			if not active() then return nil, "scope is destroyed or client is unloaded" end
			if type(fn) ~= "function" then return nil, "signal callback must be a function" end
			local connect = member(signal, "Connect") or member(signal, "connect")
			if not connect then return nil, "signal must provide Connect or connect" end
			local callback = fn
			local ok, connection = pcall(connect, signal, function(...)
				if not active() or not callback then return end
				local called, err = pcall(callback, ...)
				if not called then log.warn("embedding", "scope " .. id .. " signal callback failed", err) end
			end)
			if not ok then callback = nil; return nil, tostring(connection) end
			local disconnect
			if type(connection) == "function" then disconnect = connection
			else
				local method = member(connection, "Disconnect") or member(connection, "disconnect")
				if method then disconnect = function() method(connection) end end
			end
			if not disconnect then callback = nil; return nil, "signal did not return an unsubscribe function or connection" end
			return scope.give(function() callback = nil; disconnect() end)
		end

		function scope.delay(seconds, fn, ...)
			if not active() then return nil, "scope is destroyed or client is unloaded" end
			if not finite(seconds) or seconds < 0 then return nil, "delay must be a finite nonnegative number" end
			if type(fn) ~= "function" then return nil, "delayed callback must be a function" end
			local callback, args = fn, { n = select("#", ...), ... }
			local release, why = scope.give(function() callback, args = nil, nil end)
			if not release then return nil, why end
			clock.delay(seconds, function()
				if not active() or not callback then return end
				local run, values = callback, args
				release()
