			local required = ua.headers({ attempt = attempt, timeout = spec.timeout, required = true })
			local names = {}
			for key in pairs(required) do names[key:lower()] = true end
			for key in pairs(headers) do
				if names[key:lower()] then headers[key] = nil end
			end
			for key, value in pairs(required) do headers[key] = value end
		end

		if isOpenRouter then
			-- Ensure OpenRouter attribution headers are always present for rankings and app stats
			if not headerMap.get(headers, "HTTP-Referer") then
				headers["HTTP-Referer"] = "https://github.com/Project-Ptolemy/ProjectUAI"
			end
			if not headerMap.get(headers, "X-Title") then
				headers["X-Title"] = "Project UAI"
			end
			if not headerMap.get(headers, "X-OpenRouter-Title") then
				headers["X-OpenRouter-Title"] = "Project UAI"
			end
			if not headerMap.get(headers, "X-OpenRouter-Categories") then
				headers["X-OpenRouter-Categories"] = "game,cli-agent"
			end
			if not headerMap.get(headers, "User-Agent") then
				headers["User-Agent"] = "ProjectUAI/1.0.0"
			end
			-- Suppress Claude Code / Stainless headers for OpenRouter
			for key in pairs(headers) do
				local name = key:lower()
				if name == "x-app" or name:match("^x%-stainless%-") then headers[key] = nil end
			end
		end

		if spec.body and not headerMap.get(headers, "Content-Type") then
			headers["Content-Type"] = "application/json"
		end
		return headers
	end

	-- Socket envelopes can carry the same required identity as HTTP requests.
	function M.headersFor(spec)
		return buildHeaders(spec, spec.attempt or 1)
	end

	-- What a transport hands back when it never got an answer varies: some set
	-- Success = false, some invent a status code. What they share is that nothing came
	-- off the wire -- no body and no headers -- and a real HTTP reply always carries at
	-- least one header. Reporting that as a status writes a number into the log no
	-- server ever sent, and the retry policy then reasons about a refusal nobody
	-- issued: the gateway had already accepted the request and billed the prompt.
	local function normalise(res, via)
		local headers = res.Headers or res.ResponseHeaders or {}
		if type(headers) ~= "table" then headers = {} end
		local body = res.Body or res.ResponseData or ""
		if type(body) ~= "string" then return nil, "malformed: transport body is not text", "response" end
		if #body > MAX_BODY then return nil, "response_limit: response exceeds 8 MiB", "response" end
		if body == "" and next(headers) == nil then
			local said = util.trim(tostring(res.StatusMessage or ""))
			return nil, said ~= "" and said or "the transport returned no response", "response"
		end
		return {
			status = tonumber(res.StatusCode or res.Status) or 0,
			body = body,
			headers = headers,
			message = res.StatusMessage,
			via = via,
		}
	end

	local function send(url, method, headers, body, timeout, profile, onDispatch)
		local options = { Url = url, Method = method, Headers = headers }
		if body and body ~= "" and method ~= "GET" and method ~= "HEAD" then
			options.Body = body
		end

		local request = profile and profile.request or caps.fn.request
		if request then
			-- Set only on this path: RequestAsync accepts a fixed set of keys. Not every
			-- executor honours it either, which is why an attempt that runs long is also
			-- recognised after the fact rather than only prevented here. Round up so
			-- elapsed setup time cannot turn a one-second probe into Timeout = 0;
			-- the outer deadline still bounds waiting and retains native ownership.
			if not profile or profile.useTimeout then
				if timeout and timeout > 0 then options.Timeout = math.max(1, math.ceil(timeout)) end
			end
			if profile and profile.omitEmptyHeaders and next(headers) == nil then options.Headers = nil end
			if onDispatch then pcall(onDispatch) end
			local ok, res = pcall(guard.run, request, options)
			if not ok then return nil, tostring(res), "transport" end
			if type(res) ~= "table" then return nil, "empty executor response", "response" end
			return normalise(res, profile and profile.name or "executor")
		end

		if caps.http == "none" then return nil, caps.reason("http"), "terminal" end
		if onDispatch then pcall(onDispatch) end
		local ok, res = pcall(guard.run, function() return env.hs:RequestAsync(options) end)
		if not ok then return nil, tostring(res), "transport" end
		if type(res) ~= "table" then return nil, "empty HttpService response", "response" end
		return normalise(res, "roblox")
	end

	-- One attempt. Returns res (with .ok), or nil, error, elapsed milliseconds and
	-- a fixed failure kind. Only a completed native throw is a transport failure;
	-- received/invalid responses and terminal waits cannot authorize alias fallback.
	function M.request(spec)
		local access = accessProblem(spec)
		if access then return nil, access, 0, "terminal" end
		local url = tostring(spec.url or "")
		if url == "" then return nil, "no url", nil, "terminal" end
		if tunnelRoute.reserved(url) then
			local problem = tunnelRoute.problem(url, spec.method, spec.headers)
			local bridge = env.require("net/bridge")
			local status = bridge.clineStatus()
			local endpoint = env.require("net/transport").endpoint("cowork")
			if not problem and (not bridge.online or not endpoint or not status.enabled or not status.available) then
				problem = status.message or "Start UAI Bridge, enable Cline in Tunnels and sign in before using this provider."
			end
			if problem then
				return { status = 599, ok = false, body = util.encode({ error = { message = problem } }),
					headers = { ["x-should-retry"] = "false" }, via = "web", terminal = true }, nil, 0, "terminal"
			end
			spec = util.copy(spec)
			spec.relay, spec.relayEndpoint = true, endpoint
		end
		-- Local discovery can select an executor function and option shape explicitly.
		-- Keep it local to this call; a delayed worker must use the same selection.
		local profile = spec.executorProfile
		if profile ~= nil then
			if type(profile) ~= "table" or type(profile.request) ~= "function" then
				return nil, "invalid executor transport profile", 0, "terminal"
			end
			profile = { request = profile.request, name = type(profile.name) == "string" and profile.name or "executor",
				useTimeout = profile.useTimeout ~= false, omitEmptyHeaders = profile.omitEmptyHeaders == true }
		end
		local method = (spec.method or "GET"):upper()
		local attempt = spec.attempt or 1
		local validHeaders, headerProblem = headerMap.validate(spec.headers)
		if not validHeaders then return nil, "malformed: " .. headerProblem, 0, "terminal" end
		local headers = buildHeaders(spec, attempt)
		validHeaders, headerProblem = headerMap.validate(headers)
		if not validHeaders then return nil, "malformed: " .. headerProblem, 0, "terminal" end
		local started = clock.ms()

		if aborted(spec) then return nil, "aborted", 0, "terminal" end
		local transport = spec.relay and env.require("net/transport")
		local relayEndpoint = transport and (spec.relayEndpoint or transport.endpoint())
		local relayUnlimited = relayEndpoint and transport.unlimited(spec, relayEndpoint)
		local deadline = budgets.at(spec.timeout, spec.deadlineMs, started)
		-- Capable local relays own the long provider connection. Their default
		-- inference waits have no overall deadline; native exchanges stay short.
		if relayUnlimited then
			deadline = math.huge
			for name in pairs(headers) do if name:lower() == "x-stainless-timeout" then headers[name] = nil end end
		end
		if deadline <= started then return nil, "deadline: request budget expired", 0, "terminal" end
		-- A relay waiter owns no native connection between status polls. Counting
		-- it here as well as its short nested requests used to exhaust all eight
		-- slots with only a few agents, taking the healthy bridge offline.
		local relayed = spec.relay == true
		local owner = spec.nativeOwner
		local lane = not relayed and mobileNativeLane(spec) or nil
		if owner ~= nil and (relayed or type(owner) ~= "table") then
			return nil, "invalid native HTTP owner", 0, "terminal"
		end
		if relayed then
			if relayWorkers >= MAX_RELAY_WORKERS then return nil, "capacity: local relay request limit reached", 0, "terminal" end
		else
			-- A short poll deadline ends its Lua wait, not the native request. Keep
			-- subsequent exchanges for that relay job behind the unfinished call.
			-- Otherwise an unlimited job can fill every slot with abandoned polls.
			while ((owner and owner.pending) or (lane and nativeLanes[lane]) or (spec.waitForSlot and workers >= MAX_WORKERS))
				and clock.ms() < deadline and not aborted(spec) and not accessProblem(spec) do clock.wait(0.05) end
			if aborted(spec) then return nil, "aborted", clock.since(started), "terminal" end
			access = accessProblem(spec)
			if access then return nil, access, clock.since(started), "terminal" end
			if owner and owner.pending then
				return nil, "capacity: previous native relay exchange is still running; this call was not dispatched", clock.since(started), "terminal"
			end
			if lane and nativeLanes[lane] then
				return nil, "capacity: previous mobile native HTTP exchange is still running; this call was not dispatched", clock.since(started), "terminal"
			end
			-- Bridge control and result polls may share a busy host. Wait for an
			-- actual slot within this call's short budget; never release a slot
			-- still owned by a native call whose outcome is unknown.
			if workers >= MAX_WORKERS or clock.ms() >= deadline then
				return nil, "capacity: native HTTP slots are busy; this call was not dispatched", clock.since(started), "terminal"
			end
		end
		local pending = { done = false, accepting = true }
		if owner then owner.pending = pending end
		if lane then nativeLanes[lane] = pending end
		if relayed then relayWorkers = relayWorkers + 1 else workers = workers + 1 end
		clock.spawn(function()
			local ok, response, problem, failureKind = pcall(function()
				-- Scheduling can outlive the caller. Recheck before dispatch while
				-- leaving the reserved slot owned until this worker actually settles.
				if not pending.accepting or aborted(spec) then return nil, "aborted", "terminal" end
				local access = accessProblem(spec)
				if access then return nil, access, "terminal" end
				local remaining = deadline - clock.ms()
				if remaining <= 0 then return nil, "deadline: request budget expired before dispatch", "terminal" end
				if spec.relay then
					local relaySpec = {}
					for key, value in pairs(spec) do relaySpec[key] = value end
					relaySpec.deadlineMs = deadline
					relaySpec.relayEndpoint = relayEndpoint
					relaySpec.relayUnlimited = relayUnlimited
					relaySpec.aborted = function() return not pending.accepting or aborted(spec) end
					return env.require("net/relay").request(relaySpec, headers, M.request)
				end
				return send(url, method, headers, spec.body, remaining / 1000, profile, spec.onDispatch)
			end)
			if relayed then relayWorkers = math.max(0, relayWorkers - 1) else workers = math.max(0, workers - 1) end
			if owner and owner.pending == pending then owner.pending = nil end
			if lane and nativeLanes[lane] == pending then nativeLanes[lane] = nil end
			if pending.accepting then
				-- A successful call normally returns nil for its error. An and/or
				-- fallback would turn that nil into a failure beside every HTTP 200.
				if ok then pending.res, pending.err, pending.failureKind = response, problem, failureKind
				else pending.err, pending.failureKind = "Native HTTP transport failed", "response" end
				pending.done = true
			end
		end)
		while not pending.done and not aborted(spec) and clock.ms() < deadline do clock.wait(0.05) end
		pending.accepting = false
		local res, err, failureKind = pending.res, pending.err, pending.failureKind
		if aborted(spec) then res, err, failureKind = nil, "aborted", "terminal"
		elseif not pending.done or clock.ms() > deadline then
			res, err, failureKind = nil, "deadline: transport outcome is unknown; automatic retry is disabled", "terminal"
		end
		if res and (type(res.body) ~= "string" or #res.body > MAX_BODY) then
			res, err, failureKind = nil, "response_limit: response exceeds its text budget", "response"
		end
		if err then err = log.redact(util.ellipsis(tostring(err), 1000)) end
		local elapsed = clock.since(started)

		-- `spec.silent` keeps a request out of the history and out of the log. The web
		-- bridge polls continuously for as long as it is enabled, and against a
		-- 60-entry ceiling that would evict the inference calls the Requests view
		-- exists to explain. A silent caller reports its own failures instead.
		local entry = {
			at = started,
			stamp = clock.stamp(),
			method = method,
			url = log.redact(url),
			tag = spec.tag or "http",
			ms = elapsed,
			status = res and res.status or 0,
			bytes = res and #tostring(res.body or "") or 0,
			via = res and res.via or (profile and profile.name) or (caps.fn.request and "executor" or "roblox"),
			identity = (urls.host(url) == "openrouter.ai" and "openrouter") or spec.identity or "claude",
			uaSent = ((spec.identity ~= "none") or urls.host(url) == "openrouter.ai") and caps.uaSupported or false,
			error = err,
			attempt = attempt,
			-- A refusal with an empty body cannot be diagnosed from a status code
			-- alone, and until now nothing about the response was kept at all. These
			-- four are what distinguish an API decision from an edge filter: a
			-- Cloudflare 403 carries `server` and `cf-ray` and usually `cf-mitigated`,
			-- and the API's own 403 carries a JSON body. Kept short -- this is what the
			-- Requests view shows, not an archive.
			response = not spec.silent and res and log.redact(util.ellipsis(util.truncate(res.body, 1600), 400)) or nil,
			server = res and M.header(res, "server") or nil,
			trace = res and (M.header(res, "cf-ray") or M.header(res, "x-request-id")) or nil,
			mitigated = res and M.header(res, "cf-mitigated") or nil,
		}
		if not spec.silent then record(entry) end

		if not res then
			-- How long it ran is the whole diagnosis: a transport that refuses fails at
			-- once, one that ran out of time fails slowly, and only the second is a
			-- deadline. The caller needs the number to tell them apart.
			if not spec.silent then
				log.warn("http", string.format("%s %s failed after %s", method, entry.url,
					util.formatDuration(elapsed)), err)
			end
			return nil, err or "request failed", elapsed, failureKind or "response"
		end

		res.ms = elapsed
		res.ok = res.status >= 200 and res.status < 300
		res.entry = entry
		if spec.silent then
			return res
		end
		if not res.ok then
			log.warn("http", string.format("%s %s -> %d", method, entry.url, res.status),
				util.ellipsis(res.body, 240))
		else
			log.debug("http", string.format("%s %s -> %d in %s", method, entry.url, res.status,
				util.formatDuration(elapsed)))
		end
		return res
	end

	-- Server delays and GMT dates share the same bounded, cancellable wait.
	local function retryDelay(res, attempt, opts)
		if res then
			local header = M.header(res, "retry-after")
			local seconds = retryAfter.seconds(header)
			if seconds then return math.min(seconds, 60), "retry-after" end
		end
		return clock.backoff(attempt, opts), "backoff"
	end

	-- Whether an attempt is worth repeating, and why -- the reason is reported to the
	-- transcript so a slow turn explains itself rather than just being slow. `info`
	-- carries what the response cannot: how long the attempt took, which is the only
	-- way to tell a refusal apart from a deadline when neither carries a body.
	--
	-- `info.skipStatus` is a caller's veto over the statuses it would rather handle
	-- itself: a provider with a key pool passes 429 so the transport does not sleep
	-- its way through a backoff on a key that rotation can replace at once.
	function M.shouldRetry(res, err, info)
		if (res and res.terminal) or terminal(err) then return false end
		if res and tostring(M.header(res, "x-should-retry")):lower() == "false" then
			return false, "provider requested no retry"
		end
		local elapsed = tonumber(info and info.elapsed) or 0
		local status = res and res.status or 0
		local body = tostring(res and res.body or "")

		-- The caller's veto is consulted first and answers completely: a status it
		-- named is not retried here, whatever the body says.
		if info and type(info.skipStatus) == "table" and info.skipStatus[status] then
			return false, "status " .. tostring(status) .. " (left to the caller)"
		end

		-- An attempt that ran this long and returned nothing hit a deadline, whatever
		-- status was attached to it -- most often none at all, because the transport gave
		-- up rather than the server answering. The next attempt re-sends the entire
		-- prompt to reach the same wall, and the gateway bills it on arrival, so the
		-- sequence ends here and says why instead of paying three times over.
		--
		-- Retry-After is the exception, and the only one: a server naming a moment to
		-- come back has told us the request will work later, which is precisely what a
		-- deadline cannot promise.
		local told = res and retryAfter.seconds(M.header(res, "retry-after"))
		if elapsed >= DEADLINE_FLOOR and util.trim(body) == "" and not told then
			return false, string.format("nothing returned after %s", util.formatDuration(elapsed))
		end

		-- The transport itself failed. Nothing was decided upstream, so try again.
		if err then return true, "transport error" end
		if not res then return true, "no response" end

		if RETRY_STATUS[status] then return true, "status " .. tostring(status) end
		if status >= 500 and status <= 599 then return true, "status " .. tostring(status) end

		-- A 403 from these gateways is usually an edge filter or an exhausted shared
		-- quota pool rather than a decision about this key: in the log that prompted
		-- this they arrive interleaved with 200s on the same endpoint, seconds apart.
		-- A genuine permission refusal explains itself in the body, so one that
		-- explains nothing gets another attempt and one that does is reported.
		if status == 403 then
			if util.trim(body) == "" then return true, "403 with no explanation" end
			if transient(body) then return true, "403, upstream busy" end
			return false
		end

		if res.ok then
			local payload = errorPayload(body)
			if payload then
				local detail = type(payload.error) == "table" and payload.error or payload
				local text = type(payload.error) == "string" and payload.error or tostring(detail.message or "")
				if transient(text) or transient(tostring(detail.code or "")) or transient(tostring(detail.type or "")) then
					return true, "error inside a 200"
				end
			end
			return false
		end

		if transient(body) then return true, "upstream busy" end
		return false
	end

	-- Retries the whole attempt sequence. `spec.attempts` caps it; `spec.onRetry`
	-- lets the caller report the wait to the interface, and `spec.aborted` lets a
	-- user cancel during the sleep rather than after it.
	function M.send(spec)
		local attempts = tonumber(spec.attempts) or 1
		if attempts ~= attempts then attempts = 1 end
		attempts = math.floor(math.max(1, math.min(8, attempts)))
		local deadline = budgets.at(spec.timeout, spec.deadlineMs)
		local relayUnlimited = spec.relay and env.require("net/transport").unlimited(spec)
		if relayUnlimited then deadline = math.huge end
		local lastRes, lastErr
		for attempt = 1, attempts do
			if aborted(spec) then return nil, "aborted" end
			local access = accessProblem(spec)
			if access then return nil, access end
			local copy = util.copy(spec)
			copy.attempt, copy.deadlineMs = attempt, deadline
			copy.relayUnlimited = relayUnlimited
			if clock.ms() >= deadline then return nil, "deadline: request budget expired" end
			local res, err, failedMs = M.request(copy)
			lastRes, lastErr = res, err
			-- Asked before the success check, because a 200 can carry the failure in
			-- its body and returning that as a reply is worse than retrying it.
			local retry, why = M.shouldRetry(res, err, {
				elapsed = res and res.ms or failedMs,
				skipStatus = spec.skipStatus,
			})
			if not retry then
				-- A deadline is the one outcome the caller cannot read off the response,
				-- because there is no response to read. The transport's own words for it
				-- stay in the log entry rather than the message: they are usually a raise
				-- from inside the executor ("Argument 1 missing or nil") and say nothing
				-- a reader can act on, where the wait and its cause do.
				if why and not res then
					return nil, "deadline: " .. why .. " -- the transport gave up while the request was still " ..
						"running. A smaller context budget or reply ceiling fits inside it."
				end
				return res, err
			end
			if attempt >= attempts then return res, err end
			local wait, source = retryDelay(res, attempt, spec.backoff)
			if spec.onRetry then
				local callbackOk = pcall(spec.onRetry, {
					attempt = attempt,
					attempts = attempts,
					wait = wait,
					reason = why or source,
					status = res and res.status or 0,
					error = err,
				})
				if not callbackOk then log.warn("http", "retry callback failed safely") end
			end
			-- Slice the sleep so an abort lands promptly instead of after the full
			-- backoff, which at the top of the curve is twenty seconds.
			local slept = 0
			while slept < wait do
				if clock.ms() >= deadline then return nil, "deadline: request budget expired during backoff" end
				if aborted(spec) then return nil, "aborted" end
				local access = accessProblem(spec)
				if access then return nil, access end
				local step = math.min(0.25, wait - slept)
				clock.wait(step)
				slept = slept + step
			end
		end
		return lastRes, lastErr
	end

	function M.json(spec)
		local res, err = M.send(spec)
		if not res then return nil, err, nil end
		local decoded, decodeErr = util.decode(res.body)
		if decoded == nil then return nil, decodeErr or "invalid json", res end
		return decoded, nil, res
	end

	function M.clearHistory()
		M.history = {}
		M.changed:fire(nil)
	end

	M.terminal = terminal
	M.limits = { body = MAX_BODY, workers = MAX_WORKERS, relayWorkers = MAX_RELAY_WORKERS }
	function M.workers() return workers end
	function M.relayWorkers() return relayWorkers end
	env.require("runtime/dispose").add(function() alive = false; M.changed:clear() end, "native HTTP workers")
	M.BROWSER_UA = BROWSER_UA

	return M
end
end)()

-- ==========================================================================
-- net/kilo_status
-- ==========================================================================
__UAI_MODULES["net/kilo_status"] = (function()
-- Normalizes optional helper capabilities from either local transport.
return function(env)
	local capability = env.require("net/capability")
	local M = {}
	local states = { standby = true, disabled = true, starting = true, downloading = true,
		ready = true, rotating = true, limited = true, failed = true }
	function M.read(value)
		return capability.read(value, states, { ready = true, rotating = true })
	end
	return M
end
end)()

-- ==========================================================================
-- net/mcp
-- ==========================================================================
__UAI_MODULES["net/mcp"] = (function()
-- External harnesses use the same dispatcher and permissions as the native agent.
-- Sessions belong to one authenticated bridge connection, never the active chat.
return function(env)
	local sessions = env.require("agent/session")
	local config = env.require("runtime/config")
	local registry = env.require("agent/registry")
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local M = {}
	local owners, closed, closedOrder = {}, {}, {}
	local cancelled, cancelledOrder = {}, {}
	local total = 0
	local function identifier(value)
		return type(value) == "string" and #value > 0 and #value <= 96 and value:match("^[%w_-]+$")
	end
	local function rememberClosed(id)
		if closed[id] then return end
		closed[id] = true
		closedOrder[#closedOrder + 1] = id
		if #closedOrder > 256 then closed[table.remove(closedOrder, 1)] = nil end
	end
	local function ownerFor(id, label)
		if closed[id] then error("MCP session is closed; reconnect your harness", 0) end
		if owners[id] then return owners[id] end
		if total >= 32 then error("Too many MCP sessions; close an unused harness connection", 0) end
		local session, why = sessions.newThread({ title = "MCP · " .. util.ellipsis(tostring(label or "External harness"), 64),
			ephemeral = true, activate = false })
		if not session then error(why, 0) end
		local owner = { session = session, calls = {}, completed = {}, pending = 0, bytes = 0, count = 0 }
		owners[id], total = owner, total + 1
		return owner
	end
	local function cancel(owner, id)
		local call = owner and owner.calls[id]
		if call then call.cancelled = true end
		return call ~= nil
	end
	function M.close(id)
		if not identifier(id) then error("Invalid MCP session identity", 0) end
		rememberClosed(id)
		local owner = owners[id]
		if not owner then return { closed = true } end
		owners[id], total = nil, total - 1
		for _, call in pairs(owner.calls) do call.cancelled = true end
		-- remove() releases pending approvals, descendants, capture and owned inputs.
		sessions.remove(owner.session.id)
		return { closed = true }
	end
	function M.clear()
		local ids = {}
		for id in pairs(owners) do ids[#ids + 1] = id end
		for _, id in ipairs(ids) do M.close(id) end
