			local actual, count
			if not seen[protocol] then
				for _, candidate in ipairs({ "chat", "anthropic", "responses", "gemini" }) do
					if seen[candidate] and (not count or seen[candidate] > count) then actual, count = candidate, seen[candidate] end
				end
