		IOS = "MacOS",
		Android = "Linux",
		Linux = "Linux",
		XBoxOne = "Windows",
		PS4 = "Linux",
		UWP = "Windows",
	}

	local ARCH_BY_PLATFORM = {
		IOS = "arm64",
		Android = "arm64",
		OSX = "arm64",
	}

