			["x-app"] = "cli",
			["X-Stainless-Lang"] = "js",
			["X-Stainless-Package-Version"] = M.SDK_VERSION,
			["X-Stainless-OS"] = M.osName,
			["X-Stainless-Arch"] = M.arch,
			["X-Stainless-Runtime"] = "node",
			["X-Stainless-Runtime-Version"] = M.NODE_VERSION,
