-- provider/free
-- ==========================================================================
__UAI_MODULES["provider/free"] = (function()
-- Explicit installation for the public free provider. The provider-supported
-- `auto` router was verified against live /models and a successful tool call.
-- Startup does not discover models or dispatch inference on the user's behalf.
return function(env)
	local config = env.require("runtime/config")
	local registry = env.require("provider/registry")
	local communityKey = env.require("provider/community_key")
	local dispose = env.require("runtime/dispose")
	local M = {}
	local unsubscribe

	function M.use()
		local access = config.accessProblem()
		if access then return nil, access end
		local vault = config.vaultStatus()
		if vault.locked or vault.busy then return nil, "Unlock the credential vault before changing providers." end
		for _, record in ipairs(registry.list()) do
			if communityKey.isApplied(record) then
				local wasEnabled = record.enabled
				record.enabled = true
				local saved, why = registry.save(record, { force = true })
				if not saved then record.enabled = wasEnabled; return nil, table.concat(why or {}, "; ") end
				if not record.model or record.model == "" then
					local selected, problem = registry.setModel(record.id, "auto")
					if not selected then return nil, problem end
				end
				local selected, problem = registry.setActive(record.id)
				if not selected then return nil, problem end
				return record
			end
		end
		local record = registry.blank("projectuai-free")
		local saved, problems = registry.save(record)
		if not saved then return nil, table.concat(problems or {}, "; ") end
		local selected, problem = registry.setActive(record.id)
		if not selected then return nil, problem end
		return record
	end

	function M.ensure()
		local access = config.accessProblem()
		if access then return registry.active(), access end
		if config.vaultStatus().locked then return registry.active() end
		local list = registry.list()
		if #list == 0 then return nil end
		local selected = config.get("providers.active", "")
		if not registry.get(selected) then
			for _, record in ipairs(list) do
				if record.enabled ~= false then registry.setActive(record.id); return record end
			end
		end
		return registry.active()
	end

	function M.start()
		if unsubscribe then return end
		M.ensure()
		unsubscribe = config.changed:connect(function(path)
			-- Selection repair considers installed providers only. Empty imports,
			-- reset, removal and startup all keep an empty provider list empty.
			if path == nil or path == "providers" then M.ensure() end
		end)
	end

	function M.stop()
		if unsubscribe then unsubscribe(); unsubscribe = nil end
	end

	dispose.add(M.stop, "free provider configuration")
	return M
end
end)()

-- ==========================================================================
-- provider/free_route
-- ==========================================================================
__UAI_MODULES["provider/free_route"] = (function()
-- Background measurements for included Free access. Synthetic probes never carry
-- a conversation or execute a tool. User requests are never raced or replayed.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local registry = env.require("provider/registry")
	local community = env.require("provider/community_key")
	local transport = env.require("net/transport")
	local http = env.require("net/http")
	local sse = env.require("net/sse")
	local traits = env.require("provider/traits")
	local signal = env.require("runtime/signal")
	local M = { changed = signal.new("free route") }
	local states = setmetatable({}, { __mode = "k" })
	local owners = setmetatable({}, { __mode = "k" })
	local alive = true
	local TTL, TARGET, MAX_MODELS = 10 * 60 * 1000, 10000, 32
	local LESSONS = { "maxTokensCap", "toolsCap", "repairs", "repairScope" }

	local function eligibleRecord(record)
		return alive and community.isApplied(record) and record.model == "auto" and record.enabled ~= false
			and (record.api or "openai") == "openai" and util.trim(record.wsUrl) == ""
			and next(record.params or {}) == nil and next(record.query or {}) == nil
	end

	function M.eligible(record)
		return not config.accessProblem() and not config.vaultStatus().locked and config.get("agent.autoFreeRouting", true) ~= false and eligibleRecord(record)
			and community.problem(record) == nil and #registry.requestKeys(record) > 0
	end

	local function same(a, b)
		if type(a) ~= type(b) then return false end
		if type(a) ~= "table" then return a == b end
		for key, value in pairs(a) do if not same(value, b[key]) then return false end end
		for key in pairs(b) do if a[key] == nil then return false end end
		return true
	end

	local function scope(record)
		return { headers = record.headers or {}, claudeUa = record.claudeUa, relay = transport.endpoint() }
	end

	local function matches(record, state)
		-- Preference changes apply to future selection, never accepted requests.
		return eligibleRecord(record) and registry.get(record.id) == record
			and same(state.scope, scope(record))
	end

	local function current(record, state)
		return M.eligible(record) and states[record] == state and matches(record, state)
	end

	local function validState(record)
		local state = states[record]
		if state and current(record, state) and clock.since(state.at) < TTL then return state end
	end

	local function call(record, state, body)
		if not current(record, state) then return nil end
		local start = clock.ms()
		local headers = env.require("provider/chat").headers(record)
		local accounting = env.require("runtime/request_accounting").new(record)
		local key = record.apiKey
		local function aborted() return not current(record, state) or clock.since(start) >= TARGET end
		local response = http.send({ url = registry.endpoint(record, "/chat/completions"), method = "POST",
			requiresAccess = true,
			headers = headers, body = util.encode(body),
			onDispatch = function() accounting.dispatch(key, headers) end,
			identity = registry.identityFor(record), identityRequired = registry.requiresClaude(record),
			relay = state.scope.relay ~= nil, attempts = 1, timeout = TARGET / 1000, deadlineMs = start + TARGET,
			aborted = aborted, silent = true, tag = "free:probe" })
		if aborted() or not response or not response.ok then return nil end
		local parsed
		if sse.looksStreamed(response.body) then parsed = sse.parse(response.body)
		else
			local decoded = util.decode(response.body)
			if type(decoded) ~= "table" or decoded.error then return nil end
			parsed = sse.fromResponse(decoded)
		end
		accounting.attach(parsed)
		if parsed.streamError then return nil end
		return parsed, clock.since(start)
	end

	local function probe(record, state, model)
		local prompt = "Call uai_ping with nonce ok once. After its result, reply PONG."
		local tools = { { type = "function", ["function"] = { name = "uai_ping", description = "Connectivity check only.",
			parameters = { type = "object", properties = { nonce = { type = "string", enum = { "ok" } } },
				required = { "nonce" }, additionalProperties = false } } } }
		local first, firstMs = call(record, state, { model = model, stream = false, max_tokens = 128,
			messages = { { role = "user", content = prompt } }, tools = tools, tool_choice = "auto" })
		local calls = first and first.toolCalls or {}
		local tool = #calls == 1 and calls[1]
		local fn = tool and tool["function"]
		local args = fn and util.decode(fn.arguments or "")
		if not fn or fn.name ~= "uai_ping" or not args or args.nonce ~= "ok" or util.trim(tool.id) == "" then return end
		local assistant = { role = "assistant", content = first.content or "", tool_calls = calls }
		if util.trim(first.reasoning) ~= "" then assistant.reasoning_content = first.reasoning end
		local second, secondMs = call(record, state, { model = model, stream = false, max_tokens = 128,
			messages = { { role = "user", content = prompt },
				assistant,
				{ role = "tool", tool_call_id = tool.id, content = '{"ok":true}' } }, tools = tools, tool_choice = "auto" })
		if not second or util.trim(second.content) == "" or #(second.toolCalls or {}) > 0 then return end
		if current(record, state) then
			state.samples[model] = { model = model, ms = math.max(firstMs, secondMs), at = clock.ms() }
			M.changed:fire(record.id)
		end
	end

	-- Nonblocking, with two bounded probe workers. An expired native HTTP worker
	-- remains owned by net/http until the executor returns; no coroutine is killed.
	function M.refresh(record)
		if not M.eligible(record) then return end
		local state = validState(record)
		if state then return end
		state = { at = clock.ms(), scope = util.deepCopy(scope(record)), samples = {}, running = true }
		states[record] = state
		M.changed:fire(record.id)
		task.spawn(function()
			local ok, found = pcall(env.require("provider/models").discover, record,
				{ timeout = TARGET / 1000, aborted = function() return not current(record, state) end })
			if not ok or not current(record, state) then state.running = false; return end
			local index, workers = 0, 2
			for _ = 1, workers do
				task.spawn(function()
					while current(record, state) do
						index = index + 1
						local model = index <= MAX_MODELS and found[index]
						if not model then break end
						pcall(probe, record, state, model)
					end
					workers = workers - 1
					if workers == 0 then state.running = false; M.changed:fire(record.id) end
				end)
			end
		end)
	end

	local function winner(record, request)
		local state = validState(record)
		if not state then return nil end
		local usage = env.require("agent/usage")
		local input = request and (usage.estimateMessages(request.messages) + usage.estimateText(util.encode(request.tools or {}))) or 0
		local best
		for model, sample in pairs(state.samples) do
			local window = traits.contextWindow(model, record)
			local output = math.min(tonumber(request and request.maxTokens) or env.require("runtime/config").get("agent.maxTokens", 4096),
				traits.maxOutput(model, record) or math.huge)
			-- Unknown windows and images keep the provider's router. A tiny text
			-- probe establishes neither vision support nor arbitrary context size.
			local fits = model == "auto" or (window and input * 1.25 + output + 1024 <= window)
			if fits and sample.ms < TARGET and clock.since(sample.at) < TTL
				and (not best or sample.ms < best.ms or (sample.ms == best.ms and model < best.model)) then best = sample end
		end
		return best
	end

	function M.select(record, request)
		if config.get("agent.autoFreeRouting", true) == false then
			local owner = owners[record]
			return owner and matches(owner.record, owner.state) and owner.record or record
		end
		if not M.eligible(record) then return record end
		M.refresh(record)
		if next(request.extra or {}) ~= nil or env.require("runtime/images").hasReferences(request.messages) then return record end
		for _, message in ipairs(request.messages or {}) do
			for _, block in ipairs(type(message.content) == "table" and message.content or {}) do
				if block.type ~= "text" then return record end
			end
		end
		local best = winner(record, request)
		if not best or best.model == "auto" then return record end
		local snapshot = registry.requestSnapshot(record)
		snapshot.model = best.model
		local baseline = {}
		for _, key in ipairs(LESSONS) do baseline[key] = util.deepCopy(snapshot[key]) end
		owners[snapshot] = { record = record, state = states[record], baseline = baseline }
		return snapshot
	end

	-- A refusal or slow actual response removes that candidate for later requests.
	-- It never causes the current prompt to be resent to another measured model.
	function M.observe(record, result, ms)
		local owner = owners[record]
		if owner and matches(owner.record, owner.state) then
			local changed = false
			for _, key in ipairs(LESSONS) do
				if not same(owner.baseline[key], record[key]) then
					local value, existing = util.deepCopy(record[key]), owner.record[key]
					if (key == "maxTokensCap" or key == "toolsCap") and type(value) == "table" and type(existing) == "table"
						and value.model == existing.model and value.scope == existing.scope then
						local field = key == "maxTokensCap" and "tokens" or "limit"
						value[field] = math.min(tonumber(value[field]) or math.huge, tonumber(existing[field]) or math.huge)
					elseif key == "repairs" and owner.record.repairScope == record.repairScope and type(value) == "table" then
						for _, repair in ipairs(existing or {}) do
							if not util.find(value, function(item) return item == repair end) then value[#value + 1] = repair end
						end
					end
					if key == "repairs" and owner.record.repairScope ~= record.repairScope then
						owner.record.repairScope = record.repairScope; changed = true
					end
					if not same(existing, value) then owner.record[key] = value; changed = true end
				end
			end
			if changed then registry.save(owner.record, { force = true }) end
		else owner = { record = record, state = validState(record) } end
		if owner.state and current(owner.record, owner.state) and (not result or ms >= TARGET) then
			owner.state.samples[record.model] = nil; M.changed:fire(owner.record.id)
		end
	end

	function M.current(record)
		local owner = owners[record]
		-- Expiring latency measurements cannot abort an accepted long request.
		-- Lock clears the saved provider's live fields; the accepted snapshot may
		-- still finish its request while new work remains gated by M.eligible.
		if owner and (config.accessProblem() or config.vaultStatus().locked) then return alive and registry.get(owner.record.id) == owner.record end
		return alive and (not owner or matches(owner.record, owner.state))
	end

	function M.isRouted(record) return owners[record] ~= nil end

	function M.status(record)
		local state = validState(record)
		local best = state and winner(record)
		local availability = community.availability(record)
		local access = config.accessProblem()
		local supported = eligibleRecord(record)
		local locked = config.vaultStatus().locked
		local hasKey = #registry.requestKeys(record) > 0
		local problem = access or (locked and "Unlock credential storage")
			or (not availability.open and availability.message) or (not hasKey and "Resume an API key to use automatic routing")
		return { enabled = config.get("agent.autoFreeRouting", true) ~= false, supported = supported,
			available = supported and not problem, scheduleOpen = availability.open,
			availability = problem or availability.message,
			running = state and state.running or false, model = best and best.model,
			ms = best and best.ms, ready = state ~= nil }
	end

	local dispose = env.require("runtime/dispose")
	dispose.add(config.changed:connect(function(path)
		if path == nil or path == "agent" or path == "agent.autoFreeRouting" then
			if config.get("agent.autoFreeRouting", true) == false then states = setmetatable({}, { __mode = "k" }) end
			M.changed:fire()
		end
	end), "free routing preference")
	dispose.add(function() alive = false; states = {}; owners = {} end, "free model measurements")
	return M
end
end)()

-- ==========================================================================
-- provider/gemini
-- ==========================================================================
__UAI_MODULES["provider/gemini"] = (function()
-- Google's native generateContent protocol. Signed model parts are retained
-- separately from presentation text and replayed unchanged to the same route.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local http = env.require("net/http")
	local sse = env.require("net/sse")
	local registry = env.require("provider/registry")
	local openai = env.require("provider/openai")
	local traits = env.require("provider/traits")
	local sampling = env.require("provider/sampling")
	local headers = env.require("net/headers")
	local M = {}
	local FINISH = { STOP = "stop", MAX_TOKENS = "length", SAFETY = "content_filter",
		RECITATION = "content_filter", BLOCKLIST = "content_filter", PROHIBITED_CONTENT = "content_filter",
		SPII = "content_filter", IMAGE_SAFETY = "content_filter", IMAGE_PROHIBITED_CONTENT = "content_filter" }

	local function modelId(record)
		local id = util.trim(record.model):gsub("^models/", "")
		if #id == 0 or #id > 160 or not id:match("^[%w_.%-]+$") then return nil, "Enter a Gemini model ID from this provider's model list" end
		return id
	end
	function M.endpoint(record, stream)
		local id = modelId(record)
		if not id then return registry.endpoint(record, "/models") end
		local query = util.copy(record.query or {})
		query.alt = stream and "sse" or "json"
		local route = util.copy(record); route.query = query
		return registry.endpoint(route, "/models/" .. util.urlEncode(id) .. (stream and ":streamGenerateContent" or ":generateContent"))
	end
	function M.headers(record, key)
		local auth = record
		if record.authStyle == nil and not registry.isOpencodeGo(record) then
			key = key or registry.nextKey(record) or ""
			auth = util.copy(record); auth.authStyle = "x-goog-api-key"
		end
		return headers.merge({ ["Content-Type"] = "application/json" }, registry.authHeaders(auth, key))
	end
	function M.errorText(response, err) return openai.errorText(response, err) end

	-- Empty tables must stay JSON objects for function arguments and schemas.
	local function object(value)
		if type(value) ~= "table" then return nil end
		if next(value) == nil then return util.emptyObject() end
		if util.isArray(value) then return nil end
		return util.deepCopy(value)
	end
	local function partsCopy(parts)
		if type(parts) ~= "table" or not util.isArray(parts) or #parts > 8192 then return nil, "Invalid Gemini response parts" end
		local out, bytes = {}, 0
		for _, part in ipairs(parts) do
			if type(part) ~= "table" then return nil, "Invalid Gemini response part" end
			local copy = {}
			if part.text ~= nil then
				if type(part.text) ~= "string" then return nil, "Invalid Gemini response text" end
				copy.text = part.text; bytes = bytes + #part.text
			end
			if part.thought ~= nil then copy.thought = part.thought == true end
			if part.thoughtSignature ~= nil then
				if type(part.thoughtSignature) ~= "string" then return nil, "Invalid Gemini thought signature" end
				copy.thoughtSignature = part.thoughtSignature; bytes = bytes + #part.thoughtSignature
			end
			if part.functionCall then
				local call = part.functionCall
				if type(call) ~= "table" or type(call.name) ~= "string" or #call.name == 0 or #call.name > 128
					or call.id ~= nil and (type(call.id) ~= "string" or #call.id == 0 or #call.id > 200) then return nil, "Invalid Gemini function call" end
				local args = object(call.args or {})
				if not args then return nil, "Invalid Gemini function arguments" end
				local encoded = util.encode(args)
				if #encoded > sse.limits.arguments then return nil, "Gemini function arguments exceed the supported limit" end
				copy.functionCall = { name = call.name, args = args, id = call.id }; bytes = bytes + #encoded
			end
			if part.inlineData or part.fileData then return nil, "This Gemini model returned media; select a text model for the agent conversation" end
			if next(copy) then out[#out + 1] = copy end
			if bytes > sse.limits.body then return nil, "Gemini response exceeds the supported size" end
		end
		return out
	end

	local function addText(parts, text)
		if type(text) == "string" and text ~= "" then parts[#parts + 1] = { text = text } end
	end
	local function addImage(parts, uri, mime)
		if type(uri) ~= "string" then error("Invalid Gemini image reference", 0) end
		local media, data = uri:match("^data:(image/[%w+.-]+);base64,(.+)$")
		if media then parts[#parts + 1] = { inlineData = { mimeType = media, data = data } }
		else parts[#parts + 1] = { fileData = { mimeType = mime or "image/png", fileUri = uri } } end
	end
	local function textParts(content)
		local parts = {}
		if type(content) == "table" then
			for _, block in ipairs(content) do
				if type(block) == "table" then
					if block.type == "text" then addText(parts, block.text)
					elseif block.type == "image_url" and type(block.image_url) == "table" then addImage(parts, block.image_url.url)
					end
				end
			end
		else addText(parts, tostring(content or "")) end
		return parts
	end
	function M.wireMessages(record, messages)
		local contents, system, pending = {}, {}, {}
		local scope = registry.compatibilityKey(record)
		local function append(role, parts, combine)
			if #parts == 0 then return end
			local previous = contents[#contents]
			if combine and previous and previous.role == role then
				for _, part in ipairs(parts) do previous.parts[#previous.parts + 1] = part end
			else contents[#contents + 1] = { role = role, parts = parts } end
		end
		for _, message in ipairs(messages or {}) do
			local role = message.role
			if role == "system" or role == "developer" then
				for _, part in ipairs(textParts(message.content)) do if part.text then system[#system + 1] = part end end
			elseif role == "assistant" then
				local calls = message.toolCalls or message.tool_calls or {}
				local parts
				if message.geminiParts and message.geminiScope == scope then
					local why; parts, why = partsCopy(message.geminiParts)
					if not parts then error(why, 0) end
				else
					parts = textParts(message.content)
					for _, call in ipairs(calls) do
						local fn = call["function"] or call
						local args = type(fn.arguments) == "table" and fn.arguments or util.decode(fn.arguments or "{}")
						parts[#parts + 1] = { functionCall = { name = fn.name, args = object(args or {}) or util.emptyObject() } }
					end
				end
				local index = 0
				for _, part in ipairs(parts) do if part.functionCall then
					index = index + 1
					local call = calls[index]
					if call and call.id then pending[call.id] = { name = part.functionCall.name, id = part.functionCall.id } end
				end end
				append("model", parts, false)
			elseif role == "tool" then
				local call = pending[message.tool_call_id] or { name = message.name }
				if not call.name then error("Gemini tool result has no matching function name", 0) end
				append("user", { { functionResponse = { name = call.name, id = call.id,
					response = { result = tostring(message.content or "") } } } }, true)
			else
				local parts = textParts(message.content)
				for _, image in ipairs(message.images or {}) do addImage(parts, image.url, image.mediaType) end
				append("user", parts, true)
			end
		end
		return contents, system
	end
	function M.wireTools(tools)
		local out = {}
		for _, definition in ipairs(tools or {}) do
			local fn = definition["function"] or definition
			if type(fn.name) == "string" then
				local schema = util.deepCopy(fn.parameters or { type = "object" })
				if type(schema.properties) == "table" and next(schema.properties) == nil then schema.properties = util.emptyObject() end
				out[#out + 1] = { name = fn.name, description = fn.description or fn.name, parametersJsonSchema = schema }
			end
		end
		return out
	end
	function M.buildBody(record, request)
		local contents, system = M.wireMessages(record, request.messages)
		local body = { contents = contents, generationConfig = {
			maxOutputTokens = openai.cappedMaxTokens(record, request.maxTokens or config.get("agent.maxTokens", 4096)) or 4096 } }
		if #system > 0 then body.systemInstruction = { parts = system } end
		local tools = M.wireTools(request.tools)
		if #tools > 0 then
			body.tools = { { functionDeclarations = tools } }
			local choice = request.toolChoice
			local mode = choice == "none" and "NONE" or choice == "required" and "ANY" or "AUTO"
			local settings = { mode = mode }
			if type(choice) == "table" and choice["function"] and choice["function"].name then
				settings.mode, settings.allowedFunctionNames = "ANY", { choice["function"].name }
			end
			body.toolConfig = { functionCallingConfig = settings }
		end
		local row = traits.of(record.model, record)
		if row.reasoning or row.thinking == "gemini-level" or row.thinking == "gemini-budget" then
			local thinking = { includeThoughts = config.get("ui.showReasoning", true) ~= false }
			local effort = openai.effortFor(record, request)
			if effort and row.thinking == "gemini-level" then thinking.thinkingLevel = effort:upper()
			elseif effort and row.thinking == "gemini-budget" then
				local budgets = { low = 1024, medium = 8192, high = row.thinkingMax or 24576 }
				thinking.thinkingBudget = budgets[effort]
			end
			body.generationConfig.thinkingConfig = thinking
		end
		body = util.merge(body, record.params or {})
		body = util.merge(body, request.extra or {})
		if type(body.generationConfig) ~= "table" then error("Gemini generationConfig must be an object", 0) end
		local ceiling = tonumber(request.outputCeiling)
		local wanted = tonumber(body.generationConfig.maxOutputTokens)
		if not wanted or wanted ~= wanted or wanted < 1 or wanted == math.huge then wanted = 4096 end
		wanted = openai.cappedMaxTokens(record, wanted) or wanted
		if ceiling and ceiling >= 1 and ceiling < math.huge then wanted = math.min(wanted, ceiling) end
		body.generationConfig.maxOutputTokens = math.max(1, math.floor(wanted))
		local id = modelId(record) or ""
		sampling.apply(record, request, body.generationConfig, { defaultOmit = id:match("^gemini%-[34]") ~= nil })
		return body
	end

	local function count(value)
		return type(value) == "number" and value == value and value >= 0 and value < math.huge and math.floor(value) or 0
	end
	local function usage(value)
		if type(value) ~= "table" or value.promptTokenCount == nil and value.candidatesTokenCount == nil and value.totalTokenCount == nil then return nil end
		local prompt, completion = count(value.promptTokenCount), count(value.candidatesTokenCount) + count(value.thoughtsTokenCount)
		return { prompt_tokens = prompt, completion_tokens = completion,
			total_tokens = count(value.totalTokenCount) > 0 and count(value.totalTokenCount) or prompt + completion,
			prompt_tokens_details = { cached_tokens = count(value.cachedContentTokenCount) },
			completion_tokens_details = { reasoning_tokens = count(value.thoughtsTokenCount) } }
	end
	local function resultFor(parts, finish, metadata, model, id)
		local copied, why = partsCopy(parts)
		if not copied then return nil, why end
		local text, reasoning, calls, seen = {}, {}, {}, {}
		local callPrefix = util.uid("gemini")
		for _, part in ipairs(copied) do
			if part.text then local target = part.thought and reasoning or text; target[#target + 1] = part.text end
			if part.functionCall then
				local call = part.functionCall
				local callId = call.id or (callPrefix .. "_" .. (#calls + 1))
				if seen[callId] or #calls >= sse.limits.calls then return nil, "Invalid or excessive Gemini function calls" end
				seen[callId] = true
				calls[#calls + 1] = { id = callId, type = "function", ["function"] = { name = call.name, arguments = util.encode(call.args) } }
			end
		end
		if not FINISH[finish] then return nil, "Gemini stopped without a complete response (" .. tostring(finish or "missing finish reason") .. ")" end
		if FINISH[finish] == "content_filter" and #calls > 0 then return nil, "Gemini filtered the function-call response" end
		return { role = "assistant", content = table.concat(text), reasoning = table.concat(reasoning), toolCalls = calls,
			finish = FINISH[finish], stopReason = finish, usage = usage(metadata), model = model, id = id, geminiParts = copied }
	end
	function M.fromResponse(decoded)
		if type(decoded) ~= "table" then return nil, "Invalid Gemini response" end
