-- provider/model_info
-- ==========================================================================
__UAI_MODULES["provider/model_info"] = (function()
-- Exact, provider-scoped catalog lookup. Model names are not price aliases.
return function(env)
	local data = env.require("provider/model_data")
	local urls = env.require("net/url")
	local M = { updated = data.updated }
	local HOSTS = {
		["api.openai.com"] = "openai", ["api.anthropic.com"] = "anthropic",
		["generativelanguage.googleapis.com"] = "google", ["api.deepseek.com"] = "deepseek",
		["openrouter.ai"] = "openrouter", ["api.groq.com"] = "groq",
		["api.together.xyz"] = "together", ["api.together.ai"] = "together",
		["api.mistral.ai"] = "mistral", ["api.x.ai"] = "xai",
		["api.fireworks.ai"] = "fireworks", ["api.cerebras.ai"] = "cerebras",
	}
	local PRESETS = {
		["anthropic-messages"] = "anthropic", zen = "opencode", ["fireworks-ai"] = "fireworks",
	}
	local ROUTES = {
		openai = { ["/v1"] = true }, anthropic = { ["/v1"] = true },
		google = { ["/v1"] = true, ["/v1beta"] = true, ["/v1beta/openai"] = true },
		deepseek = { ["/v1"] = true, ["/beta"] = true }, openrouter = { ["/api/v1"] = true },
		groq = { ["/openai/v1"] = true }, together = { ["/v1"] = true },
		mistral = { ["/v1"] = true }, xai = { ["/v1"] = true },
		fireworks = { ["/inference/v1"] = true }, cerebras = { ["/v1"] = true },
	}
	local DIRECT = { "openai", "anthropic", "google", "deepseek", "mistral", "xai" }
	local DEFAULTS = {}
	for _, provider in ipairs(DIRECT) do
		for id, row in pairs(data.providers[provider] or {}) do
			if not DEFAULTS[id] then DEFAULTS[id] = row end
			DEFAULTS[provider .. "/" .. id] = row
		end
	end
	-- Exact reseller ids have meaning only on that reseller, or as a model-only
	-- estimate when the caller has no provider record. Never strip a :free suffix.
	for _, provider in ipairs({ "opencode", "openrouter" }) do
		for id, row in pairs(data.providers[provider] or {}) do
			if not DEFAULTS[id] then DEFAULTS[id] = row end
		end
	end

	function M.provider(record)
		if type(record) ~= "table" then return nil end
		local raw = tostring(record.baseUrl or "")
		if raw ~= "" then
			local parsed = urls.parse(urls.normaliseBase(raw))
			if not parsed then return nil end
			if parsed.scheme ~= "https" or parsed.authority:lower() ~= parsed.host and parsed.authority:lower() ~= parsed.host .. ":443" then return nil end
			if parsed.scheme == "https" and (parsed.host == "api.kilo.ai" or parsed.host == "ai-gateway.kilo.ai") then
				local authority = parsed.authority:lower()
				if authority ~= parsed.host and authority ~= parsed.host .. ":443" then return nil end
				local path = parsed.path:gsub("/+$", "")
				for _, route in ipairs({ "/api/gateway", "/api/gateway/v1", "/api/v1" }) do
					if path == route or path == route .. "/chat/completions" or path == route .. "/responses" or path == route .. "/messages" then return "kilo" end
				end
				return nil
			end
			if env.require("net/tunnel_route").isClineBase(raw) then return "cline" end
			if parsed.host == "opencode.ai" then
				local path = parsed.path:lower():gsub("/+$", "")
				for _, route in ipairs({ "/inference/go/v1", "/zen/go/v1" }) do
					if path == route or path:sub(1, #route + 1) == route .. "/" then return "opencode-go" end
				end
				for _, route in ipairs({ "/zen/v1", "/inference/v1", "/inference/openai/v1" }) do
					if path == route or path:sub(1, #route + 1) == route .. "/" then return "opencode" end
				end
				return nil
			end
			local provider = HOSTS[parsed.host]
			local route = parsed.path:gsub("/+$", "")
			route = route:match("^(.*)/models/[^/]+:generateContent$") or route:match("^(.*)/models/[^/]+:streamGenerateContent$")
				or route:match("^(.*)/chat/completions$") or route:match("^(.*)/messages$")
				or route:match("^(.*)/responses$") or route:match("^(.*)/models$") or route
			return provider and ROUTES[provider] and ROUTES[provider][route] and provider or nil
		end
		local preset = tostring(record.preset or "")
		return PRESETS[preset] or (data.providers[preset] and preset or nil)
	end

	function M.lookup(model, record)
		local id = tostring(model or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
		if record then
			local provider = M.provider(record)
			return provider and (data.providers[provider] or {})[id] or nil
		end
		return DEFAULTS[id]
	end

	-- Capabilities can still use the documented underlying model for a custom
	-- gateway. Pricing deliberately cannot: that gateway sets its own rates.
	function M.capabilities(model, record)
		return M.lookup(model, record) or M.lookup(model)
	end
	return M
end
end)()

-- ==========================================================================
-- provider/model_overrides
-- ==========================================================================
__UAI_MODULES["provider/model_overrides"] = (function()
-- Validated manual capability claims shared by both model surfaces.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local modelId = env.require("provider/model_id")
	local M = { maxContext = 10000000 }
	local function save(model, path, value)
		local id, why = modelId.parse(model)
		if not id then return false, why end
		local problem = config.accessProblem()
		if problem then return false, problem end
		local map = util.copy(config.get(path, {}) or {})
		map[id:lower()] = value
		config.set(path, map)
		return true
	end
	function M.context(model, text)
		if text == nil or util.trim(tostring(text)) == "" then return save(model, "agent.forceContext", nil) end
		local value = tonumber(text)
		if not value or value ~= value or value < 1 or value > M.maxContext then return false, "Enter a token count from 1 to 10,000,000, or leave it empty for the documented value." end
		return save(model, "agent.forceContext", math.floor(value))
	end
	function M.reasoning(model, enabled)
		if type(enabled) ~= "boolean" then return false, "Choose whether reasoning support is enabled." end
		return save(model, "agent.forceReasoning", enabled and true or nil)
	end
	function M.sampling(model, mode)
		if mode ~= "auto" and mode ~= "send" and mode ~= "omit" then return false, "Unknown temperature policy" end
		local value
		if mode ~= "auto" then value = mode == "send" end
		return save(model, "agent.forceSampling", value)
	end
	return M
end
end)()

-- ==========================================================================
-- provider/model_preferences
-- ==========================================================================
__UAI_MODULES["provider/model_preferences"] = (function()
-- Per-connection model shortcuts. Preferences contain IDs, never credentials.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local modelId = env.require("provider/model_id")
	local M = { maxFavorites = 100, maxRecent = 12 }
	local function providerId(record)
		return type(record) == "table" and type(record.id) == "string" and record.id ~= "" and record.id or nil
	end
	local function allValues(path)
		local value = config.get(path, {})
		return type(value) == "table" and value or {}
	end
	local function values(path, record)
		local value = allValues(path)[providerId(record)]
		return type(value) == "table" and value or {}
	end
	function M.favorite(record, model)
		return values("ui.modelFavorites", record)[model] == true
	end
	function M.setFavorite(record, model, wanted)
		if wanted ~= nil and type(wanted) ~= "boolean" then return false, "Choose whether this model is a favorite." end
		local id, clean = providerId(record), modelId.parse(model)
		if not id or not clean then return false, "Save the provider and choose a valid model first." end
		local problem = config.accessProblem()
		if problem then return false, problem end
		local all = util.deepCopy(allValues("ui.modelFavorites"))
		local favorites = util.copy(values("ui.modelFavorites", record))
		if wanted == nil then wanted = favorites[clean] ~= true end
		local count = 0
		for _, value in pairs(favorites) do if value == true then count = count + 1 end end
		if wanted and favorites[clean] ~= true and count >= M.maxFavorites then return false, "Remove a favorite before adding another (100 per provider)." end
		favorites[clean] = wanted and true or nil
		all[id] = next(favorites) and favorites or nil
		config.set("ui.modelFavorites", all)
		return true, wanted == true
	end
	function M.remember(record, model)
		local id, clean = providerId(record), modelId.parse(model)
		if not id or not clean then return end
		local recent = { clean }
		local seen = { [clean] = true }
		for _, value in ipairs(values("ui.recentModels", record)) do
			if type(value) == "string" and not seen[value] and modelId.parse(value) then
				recent[#recent + 1], seen[value] = value, true
				if #recent == M.maxRecent then break end
			end
		end
		local all = util.deepCopy(allValues("ui.recentModels"))
		all[id] = recent
		config.set("ui.recentModels", all)
	end
	function M.ordered(record, models)
		local rank, out = {}, {}
		for index, id in ipairs(values("ui.recentModels", record)) do if not rank[id] then rank[id] = index end end
		for index, id in ipairs(models or {}) do out[#out + 1] = { id = id, index = index } end
		table.sort(out, function(a, b)
			local af, bf = M.favorite(record, a.id), M.favorite(record, b.id)
			if af ~= bf then return af end
			local ar, br = rank[a.id] or math.huge, rank[b.id] or math.huge
			if ar ~= br then return ar < br end
			return a.index < b.index
		end)
		for index, item in ipairs(out) do out[index] = item.id end
		return out
	end
	function M.forget(id)
		for _, path in ipairs({ "ui.modelFavorites", "ui.recentModels" }) do
			local all = config.get(path, {})
			if type(all) == "table" and all[id] ~= nil then
				local copy = util.deepCopy(all); copy[id] = nil; config.set(path, copy)
			end
		end
	end
	return M
end
end)()

