-- runtime/bridge_install
-- ==========================================================================
__UAI_MODULES["runtime/bridge_install"] = (function()
-- Pin a bridge package and save only .txt files, which executor filesystems allow.
-- Node restores the original extensions when the operator runs bridge/start.txt.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local fsx = env.require("runtime/fsx")
	local http = env.require("net/http")
	local M = { busy = false }
	local API = "https://api.github.com/repos/Project-Ptolemy/ProjectUAI/"
	local RAW = "https://raw.githubusercontent.com/Project-Ptolemy/ProjectUAI/"
	function M.download(progress)
		if M.busy then return false, "Bridge download is already running." end
		if not fsx.enabled or not caps.fn.makefolder or not caps.fn.isfile then
			return false, "This executor needs file writing, reading, and folder creation to download the bridge."
		end
		if not caps.has("http") then return false, "This executor has no HTTP transport." end
		M.busy = true
		local function report(text) if progress then pcall(progress, text) end end
		local ok, result = pcall(function()
			report("Finding bridge files…")
			local response, err = http.send({ url = API .. "commits/main", method = "GET", timeout = 15, attempts = 2,
				identity = "none", headers = { Accept = "application/vnd.github+json", ["User-Agent"] = "ProjectUAI" }, tag = "bridge download" })
			if not response or not response.ok then error(err or ("GitHub returned " .. tostring(response and response.status)), 0) end
			local commit = util.decode(response.body)
			local revision = type(commit) == "table" and commit.sha
			local treeId = type(commit) == "table" and util.get(commit, "commit.tree.sha")
			if type(revision) ~= "string" or #revision ~= 40 or not revision:match("^%x+$") or type(treeId) ~= "string" or #treeId ~= 40 or not treeId:match("^%x+$") then
				error("GitHub returned an invalid revision.", 0)
			end
			response, err = http.send({ url = API .. "git/trees/" .. treeId .. "?recursive=1", method = "GET", timeout = 15, attempts = 2,
				identity = "none", headers = { Accept = "application/vnd.github+json", ["User-Agent"] = "ProjectUAI" }, tag = "bridge download" })
			if not response or not response.ok then error(err or ("GitHub returned " .. tostring(response and response.status)), 0) end
			local tree = util.decode(response.body)
			if type(tree) ~= "table" or type(tree.tree) ~= "table" or tree.sha ~= treeId then error("GitHub returned an invalid file list.", 0) end
			if tree.truncated then error("GitHub file list was truncated; download was not started.", 0) end
			local files, total, found = {}, 0, {}
			for _, entry in ipairs(tree.tree) do
				local path = tostring(entry.path or "")
				if path:sub(1, 7) == "bridge/" and entry.type == "blob" then
					local clean = fsx.sanitise(path)
					if clean ~= path or entry.mode == "120000" then error("Invalid bridge file path.", 0) end
					local relative = path:sub(8)
					-- Runtime files only. Tests, plans and development docs do not belong
					-- in the executor installation; web assets retain their subfolders.
					if relative:sub(1, 4) == "web/" or (relative:match("^[^/]+%.js$") and not relative:match("^test%-")) then
						local size = tonumber(entry.size)
						if not size or size < 0 or size ~= math.floor(size) or found[relative] or type(entry.sha) ~= "string" or #entry.sha ~= 40 or not entry.sha:match("^%x+$") then error("Invalid bridge file entry.", 0) end
						total = total + size
						if total > 20 * 1024 * 1024 or #files >= 200 then error("Bridge download exceeds the installation limit.", 0) end
						files[#files + 1] = { path = relative, size = size, sha = entry.sha }
						found[relative] = true
					end
				end
			end
			for _, required in ipairs({ "server.js", "inference.js", "picture-store.js", "launcher.js", "web/index.html" }) do
				if not found[required] then error("The GitHub bridge package is missing " .. required .. ". Try again after updating Project UAI.", 0) end
			end
			table.sort(files, function(a, b) return a.path < b.path end)
			-- Fetch everything before changing the installed version. Pin the commit SHA
			-- so a push halfway through the download cannot mix incompatible files.
			for index, file in ipairs(files) do
				report(string.format("Downloading %d/%d · %s", index, #files, file.path))
				local response2, why = http.send({ url = RAW .. revision .. "/bridge/" .. file.path, method = "GET",
					timeout = 15, attempts = 2, identity = "none", tag = "bridge download" })
				if not response2 or not response2.ok then error("Could not download " .. file.path .. ": " .. tostring(why or (response2 and response2.status)), 0) end
				file.body = response2.body
				if type(file.body) ~= "string" or (file.size and #file.body ~= file.size) then error("Incomplete download: " .. file.path, 0) end
			end
			-- A retry of the same revision gets its own folder as well. A partial
			-- write must not damage the package used by the previous launcher.
			local packageId = revision .. "-" .. env.services.HttpService:GenerateGUID(false)
			local package = "bridge/packages/" .. packageId .. "/"
			local manifest = { revision = revision, files = {} }
			for index, file in ipairs(files) do
				report(string.format("Saving %d/%d · %s", index, #files, file.path))
				local stored = package .. file.path .. ".txt"
				local full = fsx.resolve(stored)
				if not full then error("Bridge package path is too long.", 0) end
				if not fsx.ensure(full:match("^(.*)/[^/]+$")) then error("Could not create the bridge folder.", 0) end
				local wrote, why = fsx.write(stored, file.body)
				if not wrote or fsx.read(stored) ~= file.body then error("Could not save " .. stored .. ": " .. tostring(why), 0) end
				manifest.files[#manifest.files + 1] = { path = file.path, size = file.size, sha = file.sha }
			end
			local launcher = "'use strict';\nrequire('./packages/" .. packageId .. "/launcher.js.txt').launch(" .. util.encode(manifest) .. ");\n"
			local previous = fsx.read("bridge/start.txt")
			local wrote, why = fsx.write("bridge/start.txt", launcher)
			if not wrote or fsx.read("bridge/start.txt") ~= launcher then
				if previous then fsx.write("bridge/start.txt", previous) end
				error("Could not save the bridge launcher: " .. tostring(why) .. ". Download again before starting.", 0)
			end
			return string.format("Ready. Open a terminal in your executor workspace and run: node %s/bridge/start.txt\nThen open the browser link, paste its token below, and turn Enabled on. Keep the terminal and Roblox open.", fsx.root)
		end)
		M.busy = false
		if not ok then return false, tostring(result) end
		return true, result
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/bytefall
-- ==========================================================================
__UAI_MODULES["runtime/bytefall"] = (function()
-- The ByteFall decompile service: the second bundled fallback, after the
-- executor's own decompiler and the compiled-in luacid client.
--
-- It is a plain HTTP call -- base64 bytecode in a small JSON envelope -- so it
-- needs no compiler, only the bytecode reader and HTTP function the client has
-- already probed. That makes it the fallback of last resort on a host whose
-- executor cannot run the compiled luacid loader.
--
-- A successful response is Luau source as text; anything else becomes a comment
-- notice, the shape runtime/script_sources treats as "no source", so a service
-- error can never be cached or shown as script code.
return function(env)
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local limits = env.require("runtime/code_limits")
	local validation = env.require("runtime/decompile_result")
	local M = { URL = "https://decompiler.bytefall.dev/decompile", MAX_BYTECODE = 2 * 1024 * 1024 }
	local function stopped(control)
		if control and control.aborted then
			local ok, value = pcall(control.aborted)
			if not ok or value then return "cancelled" end
		end
		if control and control.deadlineMs and clock.ms() >= control.deadlineMs then return "deadline" end
		return nil
	end

	local ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

	-- Standard base64 with padding, in the portable dialect: the executor's own
	-- encoder is not assumed, and the offline harness compiles this module too.
	function M.encode(data, control)
		local parts, block = {}, {}
		for index = 1, #data, 3 do
			if control and index % 12288 == 1 then
				if index > 1 then clock.wait() end
				local reason = stopped(control); if reason then return nil, reason end
			end
			local first, second, third = data:byte(index), data:byte(index + 1), data:byte(index + 2)
			local value = first * 65536 + (second or 0) * 256 + (third or 0)
			local a = math.floor(value / 262144) % 64 + 1
			local b = math.floor(value / 4096) % 64 + 1
			local c = math.floor(value / 64) % 64 + 1
			local d = value % 64 + 1
			block[#block + 1] = ALPHABET:sub(a, a) .. ALPHABET:sub(b, b)
				.. (second and ALPHABET:sub(c, c) or "=") .. (third and ALPHABET:sub(d, d) or "=")
			if #block == 1024 then parts[#parts + 1] = table.concat(block); block = {} end
		end
		if #block > 0 then parts[#parts + 1] = table.concat(block) end
		return table.concat(parts)
	end

	function M.available()
		return caps.fn.request ~= nil and caps.fn.getscriptbytecode ~= nil
	end

	local function notice(title, detail)
		return "-- " .. title .. "\n-- " .. tostring(detail):gsub("\r\n?", "\n"):gsub("\n", "\n-- ")
	end

	-- Source text, or a comment notice when the bytecode cannot be read or the
	-- service refuses the request. Only a 200 carrying a body is source.
	function M.decompile(object, control)
		control = control or { deadlineMs = clock.ms() + limits.sourceDeadline }
		local cancelled = stopped(control)
		if cancelled then return notice("ByteFall request failed (" .. cancelled .. ")", "source request is no longer active") end
		if caps.fn.getscriptbytecode == nil then
			return notice("Failed to read script bytecode", "the host cannot read script bytecode")
		end
		if caps.fn.request == nil then
			return notice("ByteFall request failed (no transport)", "the host has no executor HTTP function")
		end
		local readable, bytecode = pcall(caps.fn.getscriptbytecode, object)
		if not readable or type(bytecode) ~= "string" or bytecode == "" then
			return notice("Failed to read script bytecode", "the host did not return bytecode for this script")
		end
		if #bytecode > M.MAX_BYTECODE then return notice("Failed to read script bytecode", "bytecode exceeds the 2 MiB request limit") end
		local encoded, why = M.encode(bytecode, control)
		if not encoded then return notice("ByteFall request failed (" .. why .. ")", "source request is no longer active") end
		cancelled = stopped(control)
		if cancelled then return notice("ByteFall request failed (" .. cancelled .. ")", "source request is no longer active") end
		local deadline = math.min(control.deadlineMs or math.huge, clock.ms() + limits.sourceDeadline)
		-- The shared source worker retains its slot until this native request
		-- returns. A waiter timeout never abandons an uncounted HTTP coroutine.
		local sent, response = pcall(caps.fn.request, {
			Url = M.URL, Method = "POST",
			Headers = { ["Content-Type"] = "application/json", ["Accept"] = "text/plain" },
			Body = '{"script":"' .. encoded .. '"}',
			Timeout = math.max(1, math.ceil((deadline - clock.ms()) / 1000)),
		})
		cancelled = stopped(control)
		if cancelled then return notice("ByteFall request failed (" .. cancelled .. ")", "source request is no longer active") end
		local status = sent and type(response) == "table" and tonumber(response.StatusCode or response.Status) or nil
		local body = sent and type(response) == "table" and (response.Body or response.ResponseData) or nil
		if status == 200 then
			local contentType = ""
			for key, value in pairs(type(response.Headers) == "table" and response.Headers or {}) do
				if tostring(key):lower() == "content-type" then contentType = tostring(value):lower() end
			end
			local problem = validation.problem(body)
			if contentType:find("json", 1, true) or contentType:find("html", 1, true) then problem = "response is a service document" end
			if not problem then return body end
			return notice("ByteFall request failed (invalid source)", problem)
		end
		local label = status and ("HTTP " .. tostring(status)) or "no response"
		return notice("ByteFall request failed (" .. label .. ")", "the service did not return usable source; response details were omitted")
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/caps
-- ==========================================================================
__UAI_MODULES["runtime/caps"] = (function()
-- What this host can actually do.
--
-- Every optional capability is probed exactly once, here, and the rest of the
-- project asks this module rather than testing for a global inline. That matters
-- for more than tidiness: the same script has to run under an executor with a
-- full filesystem, under one with only HTTP, and inside a plain client with
-- neither, and each of those has to degrade in a way the interface can explain
-- to the user instead of erroring.
return function(env)
	local M = {}
	-- Capability inspection must survive a deliberately broken host. The capture
	-- guard is optional here; without a loader there is no client traffic to mark.
	local guard = {
		enter = function() end, leave = function() end, active = function() return false end,
		run = function(fn, ...) return fn(...) end,
	}
	if type(env.require) == "function" then
		local ok, module = pcall(env.require, "runtime/capture_guard")
		if ok and type(module) == "table" then guard = module end
	end
	local unpackValues = table.unpack or unpack

	local function pack(...)
		return { n = select("#", ...), ... }
	end

	local function callable(value)
		return type(value) == "function" and value or nil
	end

	-- Executors disagree on where the HTTP function lives. Order matters only in
	-- that the bare global is the modern spelling.
	local function findRequests()
		local candidates = {
			{ name = "request", fn = callable(request) },
			{ name = "http_request", fn = callable(http_request) },
			{ name = "syn.request", fn = type(syn) == "table" and callable(syn.request) or nil },
			{ name = "http.request", fn = type(http) == "table" and callable(http.request) or nil },
			{ name = "fluxus.request", fn = type(fluxus) == "table" and callable(fluxus.request) or nil },
		}
		local found, seen = {}, {}
		for _, candidate in ipairs(candidates) do
			if candidate.fn and not seen[candidate.fn] then
				seen[candidate.fn] = true
				found[#found + 1] = candidate
			end
		end
		return found
	end

	local function findClipboard()
		return callable(setclipboard)
			or callable(toclipboard)
			or (type(syn) == "table" and callable(syn.write_clipboard))
			or nil
	end

	local requestAliases = findRequests()
	local primaryRequest = requestAliases[1]
	local requestFn, requestName = primaryRequest and primaryRequest.fn, primaryRequest and primaryRequest.name
	local compiler = callable(loadstring)
	if not compiler and callable(getgenv) then
		local ok, globals = pcall(getgenv)
		if ok and type(globals) == "table" then
			local readOk, candidate = pcall(function() return globals.loadstring end)
			if readOk then compiler = callable(candidate) end
		end
	end

	M.fn = {
		request = requestFn,
		readfile = callable(readfile),
		writefile = callable(writefile),
		appendfile = callable(appendfile),
		isfile = callable(isfile),
		isfolder = callable(isfolder),
		makefolder = callable(makefolder),
		listfiles = callable(listfiles),
		delfile = callable(delfile),
		delfolder = callable(delfolder),
		loadstring = compiler,
		getgenv = callable(getgenv),
		gethui = callable(gethui),
		clipboard = findClipboard(),
		identify = callable(identifyexecutor) or callable(getexecutorname),
		websocket = (type(WebSocket) == "table" and callable(WebSocket.connect))
			or (type(websocket) == "table" and callable(websocket.connect))
			or (type(syn) == "table" and type(syn.websocket) == "table" and callable(syn.websocket.connect)) or nil,
		getconnections = callable(getconnections),
		hookmetamethod = callable(hookmetamethod),
		getnamecallmethod = callable(getnamecallmethod),
		hookfunction = callable(hookfunction),
		newcclosure = callable(newcclosure),
		checkcaller = callable(checkcaller),
		getidentity = callable(getidentity) or callable(getthreadidentity),
		setidentity = callable(setidentity) or callable(setthreadidentity),
		getcallingscript = callable(getcallingscript),
		firesignal = callable(firesignal),
		fireclickdetector = callable(fireclickdetector),
		firetouchinterest = callable(firetouchinterest),
		getnilinstances = callable(getnilinstances),
		getinstances = callable(getinstances),
		getscripts = callable(getscripts),
		decompile = callable(decompile),
		getscriptbytecode = callable(getscriptbytecode),
		cloneref = callable(cloneref),
		queueTeleport = callable(queue_on_teleport),
		setfflag = callable(setfflag),
		customasset = callable(getcustomasset),
	}

	-- Raw executor functions stay available to capture hooks. The client calls the
	-- guarded wrappers, so its own compiles and requests never enter a capture
	-- record even when a wrapper is installed on the raw function.
	M.raw = { request = requestFn, loadstring = compiler, load = callable(load), require = callable(require), aliases = {} }
	for _, candidate in ipairs(requestAliases) do
		M.raw.aliases[#M.raw.aliases + 1] = { name = candidate.name, fn = candidate.fn }
	end
	local guardedFns = setmetatable({}, { __mode = "k" })
	local function guarded(fn)
		if type(fn) ~= "function" then return nil end
		local cached = guardedFns[fn]
		if cached then return cached end
		local wrapper = function(...)
			local args = pack(...)
			guard.enter()
			local returned = pack(pcall(fn, unpackValues(args, 1, args.n)))
			guard.leave()
			if not returned[1] then error(returned[2], 0) end
			return unpackValues(returned, 2, returned.n)
		end
		guardedFns[fn] = wrapper
		return wrapper
	end
	M.fn.request = guarded(requestFn)
	M.fn.loadstring = guarded(compiler)

	M.requestName = requestName

	-- Discovery may compare distinct native aliases without re-reading globals or
	-- changing the provider transport. Copies keep its captured inventory private.
	-- Guarded wrappers mark the client's own traffic as owned by this runtime.
	function M.requestAliases()
		local out = {}
		for _, candidate in ipairs(requestAliases) do
			out[#out + 1] = { name = candidate.name, fn = guarded(candidate.fn) }
		end
		return out
	end

	-- HTTP -------------------------------------------------------------------
	-- The executor path is preferred for one specific reason: RequestAsync
	-- refuses to send a User-Agent (along with Cookie, Host and Content-Length),
	-- so it physically cannot carry the Claude Code identity. When that is the
	-- only transport available the client says so rather than silently sending
	-- Roblox's own agent string.
	if M.fn.request then
		M.http = "executor"
		M.uaSupported = true
	else
		local ok, available = pcall(function()
			return env.services.HttpService ~= nil
		end)
		M.http = ok and available and "roblox" or "none"
		M.uaSupported = false
	end

	M.fs = (M.fn.writefile ~= nil and M.fn.readfile ~= nil)
	M.exec = M.fn.loadstring ~= nil
	M.ws = M.fn.websocket ~= nil
	M.clipboard = M.fn.clipboard ~= nil
	M.hui = M.fn.gethui ~= nil
	M.hooks = M.fn.getconnections ~= nil
	M.remoteHooks = {
		namecall = { state = M.fn.hookmetamethod and M.fn.getnamecallmethod and "available_unverified" or "unavailable" },
		direct = { state = M.fn.hookfunction and "available_unverified" or "unavailable" },
		invokeOutcomes = { state = "available_unverified", reason = "Requires a yielding native backend fixture" },
	}
	M.sourceRead = M.fn.decompile ~= nil or M.fn.getscripts ~= nil
		or (M.fn.getscriptbytecode ~= nil and M.fn.request ~= nil)

	-- Thread identity ----------------------------------------------------------
	-- The identity of the thread that boots the client. Some executors resume a
	-- thread scheduled by task.delay/task.spawn without it, and a write from such
	-- a thread into the interface -- which lives under gethui/CoreGui -- is then
	-- refused with "lacking capability Plugin". A signal fired from inside a
	-- remote hook arrives on a game-context thread, so anything it defers lands
	-- there; runtime/clock re-applies this identity before a scheduled callback
	-- runs so deferred client work keeps the context the client started with.
	M.identity = nil
	if M.fn.getidentity then
		local ok, value = pcall(M.fn.getidentity)
		if ok and type(value) == "number" then M.identity = value end
	end

	M.executor = "unknown"
	if M.fn.identify then
		local ok, name = pcall(M.fn.identify)
		if ok and type(name) == "string" and name ~= "" then M.executor = name end
	end

	do
		local ok, isStudio = pcall(function() return env.services.RunService:IsStudio() end)
		M.studio = ok and isStudio or false
	end

	do
		local ok, tenFoot = pcall(function() return env.services.GuiService:IsTenFootInterface() end)
		M.console = ok and tenFoot or false
	end

	M.available = {
		http = M.http ~= "none",
		fs = M.fs,
		exec = M.exec,
		ws = M.ws,
		clipboard = M.clipboard,
		hooks = M.hooks,
		capture = M.fn.hookfunction ~= nil,
		["ua"] = M.uaSupported,
	}

	-- Tools declare `needs = { "fs" }`; the registry checks the answer here
	-- before dispatch so an unavailable tool reports a clear reason to the model
	-- instead of erroring somewhere inside a nil call.
	function M.has(key)
		if key == "gravity" then return env.require("runtime/gravity").current() ~= nil end
		return M.available[key] == true
	end

	M.MISSING = {
		http = "no HTTP transport is available in this host",
		fs = "this host has no filesystem functions (writefile/readfile)",
		exec = "this host cannot compile code (loadstring is unavailable)",
		ws = "this host has no WebSocket support",
		clipboard = "this host has no clipboard function",
		hooks = "this host does not expose signal introspection (getconnections)",
		capture = "this host does not expose hookfunction, so network and payload capture cannot install hooks",
		ua = "this host cannot set a custom User-Agent",
		gravity = "Project Gravity is not connected; run the updated Gravity loader and open its PROJECT UAI button",
	}

	function M.reason(key)
		return M.MISSING[key] or ("capability '" .. tostring(key) .. "' is unavailable")
	end

	function M.summary()
		local parts = {
			"transport " .. M.http .. (M.requestName and (" (" .. M.requestName .. ")") or ""),
			"ua " .. (M.uaSupported and "yes" or "no"),
			"fs " .. (M.fs and "yes" or "no"),
			"exec " .. (M.exec and "yes" or "no"),
		}
		if M.executor ~= "unknown" then table.insert(parts, 1, M.executor) end
		return table.concat(parts, " | ")
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/capture_guard
-- ==========================================================================
__UAI_MODULES["runtime/capture_guard"] = (function()
-- Marks work this client owns, so a capture never records its own traffic.
--
-- The marker is per coroutine. A global counter would mark every thread while a
-- yielded UAI request is in flight, and a loader running on another thread would
-- be dropped by the capture wrapper for no reason.
return function(env)
	local M = {}
	local MAIN = {}
	local depth = setmetatable({}, { __mode = "k" })
	local unpackValues = table.unpack or unpack

	local function pack(...)
		return { n = select("#", ...), ... }
	end

	local function current()
		local thread = coroutine.running()
		return thread or MAIN
	end

	function M.enter()
		local thread = current()
		depth[thread] = (depth[thread] or 0) + 1
	end

	function M.leave()
		local thread = current()
		local count = depth[thread]
		if not count then return end
		if count <= 1 then depth[thread] = nil else depth[thread] = count - 1 end
	end

	function M.active()
		return (depth[current()] or 0) > 0
	end

	-- Call a host function with this coroutine marked as client-owned. Errors are
	-- re-raised unchanged so a caller's pcall sees what it always did.
	function M.run(fn, ...)
		M.enter()
		local result = pack(pcall(fn, ...))
		M.leave()
		if not result[1] then error(result[2], 0) end
		return unpackValues(result, 2, result.n)
	end

	return M
end
end)()

