-- runtime/chatloops
-- ==========================================================================
__UAI_MODULES["runtime/chatloops"] = (function()
-- Managed background chat jobs. A serial tick prevents overlapping SendAsync calls.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local dispose = env.require("runtime/dispose")
	local config = env.require("runtime/config")
	local chat = env.require("runtime/gamechat")
	local sessions = env.require("agent/session")
	local permissions = env.require("agent/permissions")
	local chatbot = env.require("runtime/chatagent")
	local M = { jobs = {}, changed = signal.new("chat loops") }
	local alive, sending, nextSend = true, false, 0
	local cursor = 0
	local TOOL = { auto = "auto_chat", quiz = "quiz_bot", reply = "auto_reply", agent = "chat_agent" }
	local function normal(text)
		local clean = util.trim(tostring(text)):lower():gsub("%s+", " "):gsub("[%p]+$", "")
		return util.trim(clean)
	end
	local function publish(job)
		M.changed:fire(job)
	end
	local function finish(job, state, reason)
		if job.state ~= "running" then return end
		job.state, job.reason, job.finishedAt = state, reason, clock.ms()
		job.pending = nil
		if job.agent then
			job.agent.queue = {}
			job.agent.generating = false
			-- The worker is a real session; releasing it here is what stops a reply
			-- that is still being prepared from arriving after the job ended.
			chatbot.close(job)
		end
		publish(job)
	end
	local function active(job)
		if not alive or job.state ~= "running" then return false end
		local disabled = config.get("agent.disabledGroups", {}) or {}
		if sessions.threads[job.session.id] ~= job.session then finish(job, "stopped", "Conversation removed")
		elseif job.session.abortFlag then finish(job, "stopped", "Conversation stopped")
		elseif disabled.chat or permissions.mode() == "readonly" or permissions.ruleFor(TOOL[job.kind]) == "deny"
			or permissions.ruleFor("chat_send") == "deny" then finish(job, "stopped", "Chat disabled")
		elseif clock.ms() >= job.deadline then finish(job, "completed", "Duration reached")
		elseif job.agent and job.agent.inputs >= 2000 then finish(job, "completed", "Chat agent input budget reached") end
		return job.state == "running"
	end
	function M.list(session)
		local out = {}
		for _, job in ipairs(M.jobs) do if not session or job.session == session then out[#out + 1] = job end end
		return out
	end
	function M.running(session)
		local out = {}
		for _, job in ipairs(M.list(session)) do if job.state == "running" then out[#out + 1] = job end end
		return out
	end
	function M.stop(id, session)
		local count = 0
		for _, job in ipairs(M.list(session)) do
			if (not id or id == "all" or id == job.id) and job.state == "running" then
				finish(job, "stopped", "Stopped"); count = count + 1
			end
		end
		return count
	end
	local function number(value, default, low, high)
		value = value == nil and default or tonumber(value)
		if not value or value ~= value or value < low or value > high then return nil end
		return value
	end
	function M.start(kind, args, ctx)
		local session = ctx and ctx.session
		if not alive then return nil, "Chat loops are unloaded." end
		if not session or sessions.threads[session.id] ~= session or (ctx.depth or 0) > 0 then
			return nil, "Start chat loops from a main conversation." end
		if ctx.aborted and ctx.aborted() then return nil, "Conversation was stopped." end
		local disabled = config.get("agent.disabledGroups", {}) or {}
		if disabled.chat or permissions.mode() == "readonly" or permissions.ruleFor("chat_send") == "deny"
			or permissions.ruleFor(TOOL[kind] or "") == "deny" then return nil, "Chat is disabled." end
		if #M.running() >= 3 then return nil, "Three chat loops are already active. Stop one first." end
		local channel = chat.channel(args.channel)
		for _, job in ipairs(M.running()) do
			if job.channel == channel then return nil, "A loop already uses this channel: " .. job.id .. ". Stop it first." end
		end
		local route, reason = chat.route(channel)
		if not route then return nil, reason end
		local interval = number(args.interval, kind == "quiz" and 30 or (kind == "agent" and 5 or 15), 5, 3600)
		local duration = number(args.duration, 600, 10, 3600)
		local count = number(args.count, kind == "quiz" and type(args.questions) == "table" and #args.questions or (kind == "agent" and 20 or 10), 1, 100)
		if not interval or not duration or not count or count % 1 ~= 0 then return nil, "Invalid interval, duration, or count." end
		local job = { id = util.uid("chat"), kind = kind, session = session, channel = channel,
			state = "running", sent = 0, completed = 0, count = count, interval = interval,
			startedAt = clock.ms(), deadline = clock.ms() + duration * 1000, nextAt = clock.ms(), scores = {} }
		if kind == "auto" then
			if type(args.messages) ~= "table" or #args.messages < 1 or #args.messages > 30 then return nil, "Supply 1–30 messages." end
			job.messages = {}
			for _, text in ipairs(args.messages) do
				local clean, err = chat.validate(text)
				if not clean then return nil, err end
				job.messages[#job.messages + 1] = clean
			end
		elseif kind == "quiz" then
			if type(args.questions) ~= "table" or #args.questions < 1 or #args.questions > 30 then return nil, "Supply 1–30 questions." end
			job.questions, job.phase = {}, "question"
			for _, item in ipairs(args.questions) do
				if type(item) ~= "table" then return nil, "Each question needs a question and an answer." end
				local question, err = chat.validate(item.question)
				local answer, answerErr = chat.validate(item.answer)
				if not question or not answer then return nil, err or answerErr end
				if not chat.validate("Quiz 100: " .. question) or not chat.validate("Time's up! Answer: " .. answer) then
					return nil, "Shorten the question or answer to leave room for the quiz prefix." end
				local aliases = { normal(answer) }
				if aliases[1] == "" then return nil, "Answer needs letters or numbers." end
				if item.aliases ~= nil and (type(item.aliases) ~= "table" or #item.aliases > 10) then return nil, "Use at most 10 answer aliases." end
				for _, alias in ipairs(item.aliases or {}) do
					if not chat.validate(alias) then return nil, "Invalid answer alias." end
					if normal(alias) == "" then return nil, "Answer alias cannot be punctuation only." end
					aliases[#aliases + 1] = normal(alias)
				end
				job.questions[#job.questions + 1] = { question = question, answer = answer, aliases = aliases }
			end
		elseif kind == "reply" then
			if type(args.rules) ~= "table" or #args.rules < 1 or #args.rules > 20 then return nil, "Supply 1–20 reply rules." end
			job.rules = {}
			for _, rule in ipairs(args.rules) do
				if type(rule) ~= "table" then return nil, "Each rule needs a trigger and response." end
				local trigger, err = chat.validate(rule.trigger)
				local response, responseErr = chat.validate(rule.response)
				if not trigger or not response then return nil, err or responseErr end
				if normal(trigger) == "" then return nil, "Trigger needs letters or numbers." end
				job.rules[#job.rules + 1] = { trigger = normal(trigger), response = response, exact = rule.exact == true }
			end
		elseif kind == "agent" then
			local ok, err = chatbot.configure(job, args)
			if not ok then return nil, err end
		else return nil, "Unknown loop type." end
		-- Keep only recent finished records; running records are never evicted.
		while #M.jobs >= 20 do
			local removed = false
			for index, entry in ipairs(M.jobs) do
				if entry.state ~= "running" then table.remove(M.jobs, index); removed = true; break end
			end
			if not removed then break end
		end
		M.jobs[#M.jobs + 1] = job
		publish(job)
		return job
	end

	local disconnect = chat.received:connect(function(entry)
		if entry.outgoing or entry.sender == (env.plr and env.plr.Name) or (entry.userId and env.plr and entry.userId == env.plr.UserId)
			or not entry.userId or entry.userId <= 0 then return end
		local text = normal(entry.text)
		for _, job in ipairs(M.running()) do
			if entry.channel == job.channel and entry.at >= job.startedAt and active(job) then
				if job.kind == "agent" then chatbot.receive(job, entry)
				elseif job.kind == "quiz" and job.phase == "answer" and not job.winner and clock.ms() < job.nextAt then
					for _, answer in ipairs(job.current.aliases) do
						if text == answer then
							job.winner = { id = tostring(entry.userId), name = entry.sender }
							job.nextAt = clock.ms(); break
						end
					end
				elseif job.kind == "reply" and not job.pending and clock.ms() >= job.nextAt then
					for _, rule in ipairs(job.rules) do
						if (rule.exact and text == rule.trigger) or (not rule.exact and text:find(rule.trigger, 1, true)) then
							job.pending = rule.response; break
						end
					end
				end
			end
		end
	end)

	local function tick()
		if not alive then return end
		local now = clock.ms()
		for _, job in ipairs(M.running()) do
			if active(job) and job.kind == "agent" then chatbot.step(job, active, finish, publish) end
		end
		if sending or now < nextSend then return end
		-- Round-robin across channels so a five-second loop cannot starve another.
		for offset = 1, #M.jobs do
			local index = (cursor + offset - 1) % #M.jobs + 1
			local job = M.jobs[index]
			if job.state == "running" and now >= job.nextAt then
				local text
				if job.kind == "auto" then text = job.messages[job.completed % #job.messages + 1]
				elseif job.kind == "reply" or job.kind == "agent" then text = job.pending
				elseif job.phase == "question" then
					job.current = job.questions[job.completed % #job.questions + 1]
					text = "Quiz " .. (job.completed + 1) .. ": " .. job.current.question
				elseif job.winner then
					text = job.winner.name .. " got it right!"
				else text = "Time's up! Answer: " .. job.current.answer end
				if text then
					if job.kind == "agent" then
						if chatbot.duplicate(job, text) then
							job.pending = nil; job.agent.skipped = job.agent.skipped + 1
							job.nextAt = clock.ms() + job.interval * 1000
							publish(job); return
						end
						chatbot.reserve(job, text)
					end
					cursor = index
					sending = true
					local callOk, ok, reason = pcall(chat.send, text, job.channel)
					sending = false
					nextSend = clock.ms() + 5000
					if job.state ~= "running" or not alive then return end
					if not callOk or not ok then finish(job, "failed", tostring(callOk and reason or ok)); return end
					job.sent = job.sent + 1
					if job.kind == "quiz" and job.phase == "question" then
						job.phase = "answer"; job.nextAt = clock.ms() + job.interval * 1000
					else
						if job.winner then
							local winner = job.winner
							local score = job.scores[winner.id] or { name = winner.name, points = 0 }
							score.points = score.points + 1; job.scores[winner.id] = score; job.winner = nil
						end
						job.completed = job.completed + 1; job.pending = nil; job.phase = "question"
						job.nextAt = clock.ms() + job.interval * 1000
						if job.completed >= job.count then finish(job, "completed", "Finished") end
					end
					publish(job)
					return
				end
			end
		end
	end
	local stopTick = clock.interval(0.25, tick)
	dispose.add(function() alive = false; stopTick(); disconnect(); M.stop() end, "chat loops")
	local unsubscribe = sessions.anyEvent:connect(function(session, event)
		if event.kind == "cleared" or event.kind == "abort" then M.stop(nil, session) end
	end)
	dispose.add(unsubscribe, "chat loop session events")
	return M
end
end)()

-- ==========================================================================
-- runtime/clipboard
-- ==========================================================================
__UAI_MODULES["runtime/clipboard"] = (function()
-- Executor clipboard writes have no readback API. A false result or exception is
-- failure; nil is the normal success result in several supported executors.
return function(env)
	local caps = env.require("runtime/caps")
	local M = {}
	function M.write(text)
		if type(text) ~= "string" then return false, "Clipboard text must be a string." end
		if not caps.clipboard or type(caps.fn.clipboard) ~= "function" then
			return false, "Clipboard is unavailable in this executor."
		end
		local ok, result = pcall(caps.fn.clipboard, text)
		-- Native exceptions can echo the copied payload; do not display or log them.
		if not ok or result == false then return false, "Could not write to the clipboard." end
		return true
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/clock
-- ==========================================================================
__UAI_MODULES["runtime/clock"] = (function()
-- Time, scheduling and the retry curve.
--
-- os.clock reports processor time, which stops advancing while a thread is
-- yielded, so anything measuring a request or a backoff has to use a wall clock.
-- DateTime supplies the epoch; Roblox time() preserves sub-second deadlines when
-- DateTime is temporarily unavailable. Hosts without either use coarse os.time.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")

	local M = {}

	local epochBase, tickBase = 0, nil
	local function finite(value) return type(value) == "number" and value == value and math.abs(value) < math.huge end
	local function runtimeTime()
		if type(time) ~= "function" then return nil end
		local ok, value = pcall(time)
		return ok and finite(value) and value or nil
	end
	local function wallTime()
		local ok, value = pcall(function() return os.time() end)
		return ok and finite(value) and value * 1000 or epochBase
	end
	do
		local ok, value = pcall(function()
			return DateTime.now().UnixTimestampMillis
		end)
		M.precise = ok and finite(value)
		epochBase, tickBase = M.precise and value or wallTime(), runtimeTime()
	end

	function M.ms()
		-- A transient host failure must not permanently disable the precise clock.
		local ok, value = pcall(function() return DateTime.now().UnixTimestampMillis end)
		M.precise = ok and finite(value)
		if M.precise then
			epochBase, tickBase = value, runtimeTime()
			return value
		end
		local current = runtimeTime()
		if current and tickBase then return epochBase + math.max(0, current - tickBase) * 1000 end
		return wallTime()
	end

	function M.since(startMs)
		return M.ms() - (startMs or 0)
	end

	function M.stamp()
		local seconds = math.floor(M.ms() / 1000)
		local ok, text = pcall(function()
			return DateTime.fromUnixTimestamp(seconds):FormatLocalTime("HH:mm:ss", "en-us")
		end)
		if ok and type(text) == "string" then return text end
		seconds = seconds + M.offsetMinutes() * 60
		return string.format("%02d:%02d:%02d",
			math.floor(seconds / 3600) % 24, math.floor(seconds / 60) % 60, seconds % 60)
	end

	-- Calendar ---------------------------------------------------------------
	--
	-- Activity is counted per day and per hour of the day, so both have to mean the
	-- same thing on every host: the day the person in front of the screen would
	-- name. Roblox's only calendar API is DateTime's pattern formatter, and its
	-- pattern support differs between client versions -- so the conversion is done
	-- here in arithmetic, from the epoch millisecond count plus this host's offset
	-- from UTC, and the formatter is asked for exactly one thing: that offset.
	local MINUTE_MS = 60000
	local DAY_MINUTES = 1440
	-- The widest real offsets are -12:00 (Baker Island) and +14:00 (Kiritimati).
	local OFFSET_LIMIT = 840
	local offsetMinutes = nil

	function M.offsetMinutes()
		if offsetMinutes then return offsetMinutes end
		offsetMinutes = 0
		local seconds = math.floor(M.ms() / 1000)
		local ok, text = pcall(function()
			return DateTime.fromUnixTimestamp(seconds):FormatLocalTime("HH:mm", "en-us")
		end)
		if ok and type(text) == "string" then
			local hour, minute = text:match("^(%d%d?):(%d%d)$")
			if hour then
				local delta = (tonumber(hour) * 60 + tonumber(minute))
					- math.floor((seconds % 86400) / 60)
				if delta > OFFSET_LIMIT then delta = delta - DAY_MINUTES end
				if delta < -OFFSET_LIMIT then delta = delta + DAY_MINUTES end
				-- Quarter-hour zones exist (Nepal is +05:45); minutes of drift between
				-- the two reads do not.
				offsetMinutes = math.floor(delta / 15 + 0.5) * 15
			end
		end
		return offsetMinutes
	end

	-- Howard Hinnant's civil-from-days, which is exact for every date a client can
	-- hold and needs no leap-year table. `days` is days since 1970-01-01.
	function M.civilFromDays(days)
		local shifted = math.floor(days) + 719468
		local era = math.floor(shifted / 146097)
		local dayOfEra = shifted - era * 146097
		local yearOfEra = math.floor((dayOfEra - math.floor(dayOfEra / 1460)
			+ math.floor(dayOfEra / 36524) - math.floor(dayOfEra / 146096)) / 365)
		local year = yearOfEra + era * 400
		local dayOfYear = dayOfEra - (365 * yearOfEra + math.floor(yearOfEra / 4)
			- math.floor(yearOfEra / 100))
		local monthPrime = math.floor((5 * dayOfYear + 2) / 153)
		local day = dayOfYear - math.floor((153 * monthPrime + 2) / 5) + 1
		local month = monthPrime + 3
		if monthPrime >= 10 then month = monthPrime - 9 end
		if month <= 2 then year = year + 1 end
		return year, month, day
	end

	function M.daysFromCivil(year, month, day)
		local y = year
		if month <= 2 then y = y - 1 end
		local era = math.floor(y / 400)
		local yearOfEra = y - era * 400
		local shift = 9
		if month > 2 then shift = -3 end
		local dayOfYear = math.floor((153 * (month + shift) + 2) / 5) + day - 1
		local dayOfEra = yearOfEra * 365 + math.floor(yearOfEra / 4)
			- math.floor(yearOfEra / 100) + dayOfYear
		return era * 146097 + dayOfEra - 719468
	end

	-- Local days since the epoch. The unit every per-day bucket is keyed by.
	function M.dayNumber(ms)
		local shifted = (ms or M.ms()) + M.offsetMinutes() * MINUTE_MS
		return math.floor(shifted / 86400000)
	end

	function M.keyFromDayNumber(days)
		local year, month, day = M.civilFromDays(days)
		return string.format("%04d-%02d-%02d", year, month, day)
	end

	function M.dayKey(ms)
		return M.keyFromDayNumber(M.dayNumber(ms))
	end

	-- Nil rather than a guess for anything that is not a key: these come out of a
	-- stored file, and a corrupt one must not be silently read as 1970.
	function M.dayNumberOfKey(key)
		local year, month, day = tostring(key or ""):match("^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
		if not year then return nil end
		year, month, day = tonumber(year), tonumber(month), tonumber(day)
		if month < 1 or month > 12 or day < 1 or day > 31 then return nil end
		local days = M.daysFromCivil(year, month, day)
		local actualYear, actualMonth, actualDay = M.civilFromDays(days)
		if actualYear ~= year or actualMonth ~= month or actualDay ~= day then return nil end
		return days
	end

	function M.hourOf(ms)
		local shifted = (ms or M.ms()) + M.offsetMinutes() * MINUTE_MS
		return math.floor((shifted % 86400000) / 3600000)
	end

	-- Monday = 1. The epoch itself was a Thursday, which is where the 3 comes from.
	function M.weekdayOfDayNumber(days)
		return ((days + 3) % 7) + 1
	end

	local MONTHS = { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
		"Jul", "Aug", "Sep", "Oct", "Nov", "Dec" }
	local WEEKDAYS = { "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun" }

	function M.monthName(month)
		return MONTHS[month] or "?"
	end

	function M.weekdayName(index)
		return WEEKDAYS[index] or "?"
	end

	-- "Sat 5 Jul 2026", or without the year when it is the current one -- the form a
	-- date is read in rather than the form it is stored in.
	function M.describeDay(key, todayKey)
		local days = M.dayNumberOfKey(key)
		if not days then return tostring(key) end
		local year, month, day = M.civilFromDays(days)
		local thisYear = M.civilFromDays(M.dayNumberOfKey(todayKey) or M.dayNumber())
		local head = string.format("%s %d %s", WEEKDAYS[M.weekdayOfDayNumber(days)], day, MONTHS[month])
		if year == thisYear then return head end
		return head .. " " .. tostring(year)
	end

	-- 12-hour clock with a meridiem, which is how a "peak hour" reads.
	function M.describeHour(hour)
		hour = math.floor(tonumber(hour) or 0) % 24
		local suffix = "AM"
		if hour >= 12 then suffix = "PM" end
		local display = hour % 12
		if display == 0 then display = 12 end
		return string.format("%d %s", display, suffix)
	end

	-- Thread identity ----------------------------------------------------------
	-- Deferred work is still the client's own work, but a callback rescheduled by
	-- the host can lose the identity the client was injected with, and its writes
	-- into the interface are then refused ("lacking capability Plugin"): the
	-- ScreenGui sits under gethui/CoreGui. A signal fired from a remote hook runs
	-- on a game-context thread, so anything that thread defers lands there too.
	-- The identity captured at boot is re-applied before a scheduled callback
	-- runs. A host without the identity functions keeps its previous behaviour.
	local function reclaimIdentity()
		if caps.identity and caps.fn.setidentity then pcall(caps.fn.setidentity, caps.identity) end
	end
	local function scheduled(fn)
		if not (caps.identity and caps.fn.setidentity) then return fn end
		return function(...)
			reclaimIdentity()
			return fn(...)
		end
	end

	function M.wait(seconds)
		return task.wait(seconds)
	end

	function M.spawn(fn, ...)
		return task.spawn(scheduled(fn), ...)
	end

	function M.delay(seconds, fn, ...)
		return task.delay(seconds, scheduled(fn), ...)
	end

	-- Injectable so a test can pin the jitter. Nothing else should reach for
	-- math.random directly, or backoff stops being reproducible.
	function M.random()
		return math.random()
	end

	-- Trailing-edge debounce: the last call within the window wins. Returns the
	-- wrapped function plus a cancel handle, because a debounced relayout has to
	-- be cancellable when the surface it targets is destroyed.
	function M.debounce(fn, seconds)
		local pending, args, due = false, nil, 0
		local wake
		wake = scheduled(function()
			if not args then pending = false; return end
			local remaining = due - M.ms()
			if remaining > 0 then task.delay(remaining / 1000, wake); return end
			local ready = args
			-- Release ownership before calling a handler that may yield or reschedule.
			pending, args = false, nil
			fn((table.unpack or unpack)(ready, 1, ready.n))
		end)
		local function wrapped(...)
			args, due = { n = select("#", ...), ... }, M.ms() + seconds * 1000
			-- One pending wakeup owns only the latest arguments, even during a burst.
			if not pending then pending = true; task.delay(seconds, wake) end
		end
		return wrapped, function() args = nil end
	end

	-- Leading-edge throttle: fires immediately, then swallows calls for the rest
	-- of the window. Right for a resize signal that can arrive every frame.
	function M.throttle(fn, seconds)
		local lastRun = -math.huge
		return function(...)
			local now = M.ms()
			if now - lastRun < seconds * 1000 then return end
			lastRun = now
			return fn(...)
		end
	end

	function M.interval(seconds, fn)
		local alive = true
		task.spawn(function()
			while alive do
				task.wait(seconds)
				if not alive then return end
				reclaimIdentity()
				local ok, err = pcall(fn)
				if not ok then env.require("runtime/log").warn("clock", "interval handler failed", err) end
			end
		end)
		-- Registered centrally as well as returned. A caller that forgets the
		-- canceller -- or one whose owning instance is destroyed without its
		-- Destroying handler running -- would otherwise leave a thread ticking for the
		-- lifetime of the process, and an unload could not stop it. The registry's
		-- closure both cancels and unregisters, so it is the one to hand back.
		return env.require("runtime/dispose").add(function() alive = false end, "interval")
	end

	-- Exponential backoff with full jitter, capped. Full jitter rather than a
	-- fixed multiple because several retrying clients behind one gateway
	-- otherwise re-collide on exactly the same schedule.
	function M.backoff(attempt, opts)
		opts = opts or {}
		local base = opts.base or 0.6
		local cap = opts.cap or 20
		local ceiling = math.min(cap, base * (2 ^ math.max(attempt - 1, 0)))
		local floor = opts.floor or (ceiling * 0.35)
		return util.clamp(floor + M.random() * (ceiling - floor), 0, cap)
	end

	-- Runs fn on its own thread and stops waiting after `seconds` or cancellation.
	--
	-- Deliberately leave the worker alive: an engine or executor call may still
	-- own a continuation for it. Closing it can cause "cannot resume dead coroutine"
	-- when that operation completes. Callers stop managed work cooperatively and
	-- report when other work may still be running. Elapsed time
	-- comes from task.wait's own delta rather than a clock read per frame, and the
	-- first check happens before any yield: task.spawn runs inline until the first
	-- yield, so code that never yields is already finished and must not be billed
	-- a scheduler tick.
	function M.timeout(seconds, fn, aborted)
		if aborted and aborted() then return false, false, nil, "aborted" end
		local done, ok, result = false, false, nil
		task.spawn(scheduled(function()
			ok, result = pcall(fn)
			done = true
		end))
		local cancelled = false
		if not done then
			local elapsed = 0
			repeat
				elapsed = elapsed + (task.wait() or 0)
				cancelled = not done and aborted and aborted() or false
			until done or cancelled or elapsed >= seconds
		end
		if not done then return false, false, nil, cancelled and "aborted" or "timeout" end
		return true, ok, result
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/code_actions
-- ==========================================================================
__UAI_MODULES["runtime/code_actions"] = (function()
-- Action definitions and parameter validation. Values are data, never source.
return function(env)
	local util = env.require("runtime/util")
	local limits = env.require("runtime/code_limits")
	local M = {}
	local function finite(v) return type(v) == "number" and v == v and math.abs(v) < math.huge end
	function M.value(def, value)
		if value == nil then value = def.default end
		if value == nil then
			if def.required then return false, "Missing input: " .. def.key end
			return true, nil
		end
		if def.type == "number" then
			if not finite(value) then return false, def.key .. " must be a finite number" end
			if (def.min and value < def.min) or (def.max and value > def.max) then return false, def.key .. " is outside its allowed range" end
		elseif def.type == "boolean" then
			if type(value) ~= "boolean" then return false, def.key .. " must be a boolean" end
		elseif def.type == "string" or def.type == "choice" then
			if type(value) ~= "string" or #value > limits.inputString or not util.validUtf8(value) then return false, def.key .. " must be valid text (up to 4096 bytes)" end
			if def.type == "choice" then
				local found = false
				for _, choice in ipairs(def.choices) do if choice == value then found = true end end
				if not found then return false, "Choose one of the allowed values for " .. def.key end
			end
		else return false, "Unsupported input type" end
		return true, value
	end
	function M.definitions(input)
		if type(input) ~= "table" or not util.isArray(input) or #input > limits.inputs then return nil, "Use at most 12 input definitions" end
		local result, keys = {}, {}
		for _, item in ipairs(input) do
			if type(item) ~= "table" or type(item.key) ~= "string" or #item.key > 64 or not item.key:match("^[%a_][%w_]*$") or keys[item.key] then return nil, "Input keys must be unique identifiers, up to 64 bytes" end
			if item.type ~= "string" and item.type ~= "number" and item.type ~= "boolean" and item.type ~= "choice" then return nil, "Unsupported input type" end
			local def = { key = item.key, label = util.ellipsis(item.label or item.key, 100), type = item.type, required = item.required == true }
			if item.min ~= nil then if not finite(item.min) then return nil, "Invalid minimum" end; def.min = item.min end
			if item.max ~= nil then if not finite(item.max) then return nil, "Invalid maximum" end; def.max = item.max end
			if def.min and def.max and def.min > def.max then return nil, "Minimum exceeds maximum" end
			if def.type == "choice" then
				if type(item.choices) ~= "table" or not util.isArray(item.choices) or #item.choices < 1 or #item.choices > 32 then return nil, "Choices require 1–32 values" end
				def.choices = {}; local seen = {}
				for _, choice in ipairs(item.choices) do
				if type(choice) ~= "string" or util.trim(choice) == "" or #choice > limits.inputString or seen[choice] or not util.validUtf8(choice) then return nil, "Choices must be nonblank, valid and distinct" end
					seen[choice] = true; def.choices[#def.choices + 1] = choice
				end
			end
			if item.default ~= nil then
				local ok, value = M.value(def, item.default)
				if not ok then return nil, value end
				def.default = value
			end
			keys[def.key] = true; result[#result + 1] = def
		end
		return result
	end
	function M.parameters(definitions, values)
		if type(values) ~= "table" then return nil, "Inputs must be an object" end
		local result, known = {}, {}
		for _, def in ipairs(definitions) do
			local ok, value = M.value(def, values[def.key])
			if not ok then return nil, value end
			result[def.key], known[def.key] = value, true
		end
		for key in pairs(values) do if not known[key] then return nil, "Unknown input: " .. tostring(key) end end
		return result
	end
	return M
end
end)()

