-- runtime/decompile_result
-- ==========================================================================
__UAI_MODULES["runtime/decompile_result"] = (function()
-- Validate decompiler responses without requiring a working host compiler.
return function(env)
	local util = env.require("runtime/util")
	local limits = env.require("runtime/code_limits")
	local M = {}
	function M.problem(source)
		if type(source) ~= "string" then return "returned no source text", "decompiler_failure" end
		if #source > limits.file then return "source exceeds 2 MiB", "oversized_source" end
		if not util.validUtf8(source) then return "source is not valid UTF-8", "invalid_source" end
		-- Strip only leading whitespace/comments. A block-comment diagnostic is
		-- no more source than a line-comment diagnostic; statements after either
		-- remain valid, including native Luau syntax the offline compiler lacks.
		local at = 1
		while at <= #source do
			local whitespace = source:match("^%s+", at)
			if whitespace then at = at + #whitespace
			elseif source:sub(at, at + 1) == "--" then
				local equals = source:match("^%-%-%[(=*)%[", at)
				if equals then
					local close = "]" .. equals .. "]"
					local finish = source:find(close, at + 4 + #equals, true)
					if not finish then return "returned an incomplete comment notice", "decompiler_failure" end
					at = finish + #close
				else
					local newline = source:find("\n", at + 2, true)
					at = newline and newline + 1 or #source + 1
				end
			else break end
		end
		if at > #source then return "returned empty or comment-only text", "decompiler_failure" end
		-- HTML and JSON success/error envelopes are not bare Luau chunks. Never
		-- cache them merely because an edge service returned HTTP 200.
		local first = source:sub(at, at)
		if first == "<" or first == "{" or first == "[" or first == '"' then
			return "returned a service document instead of Luau source", "invalid_source"
		end
		local bare = util.trim(source:sub(at))
		if bare == "true" or bare == "false" or bare == "null" or bare == "nil" or tonumber(bare) then
			return "returned a value instead of a Luau chunk", "invalid_source"
		end
		return nil
	end
	function M.noticeTitle(source)
		if type(source) ~= "string" then return nil end
		local first = (source:match("^%s*([^\n]*)") or ""):gsub("^%-%-%s*", ""):gsub("%s+$", "")
		if first == "Failed to read script bytecode" or first == "Decompiler API request failed" then return first end
		if first:match("^ByteFall request failed %(HTTP %d%d%d%)$") then return first end
		for _, label in ipairs({ "no transport", "no response", "no body", "cancelled", "deadline", "invalid source", "source too large" }) do
			if first == "ByteFall request failed (" .. label .. ")" then return first end
		end
		return nil
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/dispose
-- ==========================================================================
__UAI_MODULES["runtime/dispose"] = (function()
-- The disposer registry.
--
-- Everything this client leaves running outside its own instance tree -- a timer, a
-- repeating tween, a connection to a service that outlives the interface, a
-- subscription to a long-lived signal -- registers its cleanup here. Destroying the
-- ScreenGui is not unloading: a `clock.interval` keeps ticking against a destroyed
-- label, an InputBegan handler keeps firing, and a second boot then has two of
-- everything. Draining this is what makes an unload real.
--
-- Deliberately dependency-free so anything can require it, including runtime/clock.
return function(env)
	local M = { entries = {}, draining = false }

	-- Returns a canceller that also unregisters, so a caller that cleans up early
	-- does not leave a dead entry behind for the drain to trip over.
	function M.add(fn, label)
		if type(fn) ~= "function" then return function() end end
		if M.draining then pcall(fn); return function() end end
		local entry = { fn = fn, label = label or "anonymous", alive = true }
		M.entries[#M.entries + 1] = entry
		return function()
			if not entry.alive then return end
			entry.alive = false
			pcall(entry.fn)
			entry.fn = nil
			for index, candidate in ipairs(M.entries) do if candidate == entry then table.remove(M.entries, index); break end end
		end
	end

	-- An RBXScriptConnection from a signal that outlives the UI.
	function M.connection(connection, label)
		if type(connection) ~= "table" and type(connection) ~= "userdata" then
			return function() end
		end
		return M.add(function()
			pcall(function() connection:Disconnect() end)
		end, label or "connection")
	end

	-- A tween that repeats forever and so never releases its target on its own.
	function M.tween(tween, label)
		if not tween then return function() end end
		return M.add(function()
			pcall(function() tween:Cancel() end)
		end, label or "tween")
	end

	function M.count()
		local alive = 0
		for _, entry in ipairs(M.entries) do
			if entry.alive then alive = alive + 1 end
		end
		return alive
	end

	-- Runs every cleanup once, newest first, and never raises: an unload that stops
	-- halfway because one handler errored is worse than one that reports at the end.
	function M.drain()
		if M.draining then return 0 end
		M.draining = true
		local ran, failed = 0, {}
		local entries = M.entries; M.entries = {}
		for index = #entries, 1, -1 do
			local entry = entries[index]
			if entry.alive then
				entry.alive = false
				local ok, err = pcall(entry.fn)
				entry.fn = nil
				ran = ran + 1
				if not ok then failed[#failed + 1] = entry.label .. ": " .. tostring(err) end
			end
		end
		M.entries = {}
		M.draining = false
		return ran, failed
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/draft_store
-- ==========================================================================
__UAI_MODULES["runtime/draft_store"] = (function()
-- Draft payloads live inside their conversation file, never in a second store.
return function(env)
	local util = env.require("runtime/util")
	local M = { maxBytes = 1024 * 1024, maxAttachments = 16 }
	function M.snapshot(value)
		if type(value) ~= "table" then return nil end
		local text = type(value.text) == "string" and value.text or ""
		if #text > M.maxBytes then return nil, "Draft exceeds the 1 MiB recovery limit. Copy it before closing." end
		local entries, bytes = {}, #text
		for _, entry in ipairs(type(value.attachments) == "table" and value.attachments or {}) do
			if #entries >= M.maxAttachments then return nil, "Draft has too many attachments to recover." end
			if type(entry) ~= "table" then return nil, "Draft contains an invalid attachment." end
			local copy = { label = util.truncate(tostring(entry.label or entry.name or "Attachment"), 160) }
			if entry.file == true then
				if type(entry.path) ~= "string" or #entry.path > 1000 or type(entry.bytes) ~= "number"
					or entry.bytes ~= entry.bytes or entry.bytes < 0 or entry.bytes % 1 ~= 0 or entry.bytes > 10 * 1024 * 1024 then
					return nil, "Draft contains an invalid file reference."
				end
				copy.file, copy.path, copy.bytes = true, entry.path, math.floor(entry.bytes)
				if entry.sha256 ~= nil then
					if not env.require("runtime/attachment_identity").valid(entry.sha256) then return nil, "Draft contains an invalid attachment digest." end
					copy.sha256 = entry.sha256
				end
				local lines = tonumber(entry.lines) or 0
				copy.name, copy.lines = copy.label, lines == lines and math.max(0, math.min(10 * 1024 * 1024, math.floor(lines))) or 0
			else
				if type(entry.text) ~= "string" then return nil, "Draft contains an invalid text attachment." end
				bytes = bytes + #entry.text
				if bytes > M.maxBytes then return nil, "Draft attachments exceed the 1 MiB recovery limit." end
				copy.text = entry.text
			end
			entries[#entries + 1] = copy
		end
		if text == "" and #entries == 0 then return nil end
		return { version = 1, text = text, attachments = entries, expanded = value.expanded == true }
	end
	function M.restore(value)
		if type(value) ~= "table" or value.version ~= 1 then return nil end
		return M.snapshot(value)
	end
	return M
end
end)()

