-- runtime/iy_plugins
-- ==========================================================================
__UAI_MODULES["runtime/iy_plugins"] = (function()
-- Author-owned IY plugins. The on-disk format is the ordinary IY plugin table;
-- top-level globals and shared locals are kept in the live IY environment.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local iy = env.require("runtime/iy")
	local M = {}
	local MAX_BYTES = 256000
	M.template = [=[-- Shared locals or globals may be declared above Plugin.
local count = 0

local Plugin = {
	["PluginName"] = "ExamplePlugin",
	["PluginDescription"] = "Two commands with shared state.",
	["Commands"] = {
		["example"] = {
			["ListName"] = "example / ex",
			["Description"] = "Prints a message to the console",
			["Aliases"] = {"ex"},
			["Function"] = function(args, speaker)
				count = count + 1
				print("Hello from ExamplePlugin!", count)
			end
		},
		["resetexample"] = {
			["ListName"] = "resetexample",
			["Description"] = "Resets the shared counter",
			["Aliases"] = {},
			["Function"] = function(args, speaker)
				count = 0
			end
		}
	}
}

return Plugin
]=]

	function M.filename(value)
		if type(value) ~= "string" then return nil, "plugin must be a plain .iy filename" end
		local name = util.trim(value)
		if name:lower():sub(-3) == ".iy" then name = name:sub(1, -4) end
		if #name < 1 or #name > 80 or not name:match("^[%w_%-]+$") then
			return nil, "use a plugin name containing only letters, numbers, underscores, or hyphens; no paths"
		end
		local lower = name:lower()
		if lower == "iy_fe" or lower == "con" or lower == "prn" or lower == "aux" or lower == "nul"
			or lower:match("^com%d$") or lower:match("^lpt%d$") then return nil, "that filename is reserved" end
		return name .. ".iy"
	end

	local function readExisting(name)
		local read = caps.fn.readfile
		if not read then return nil, "this host cannot read plugin files" end
		local present
		if caps.fn.isfile then
			local ok, result = pcall(caps.fn.isfile, name)
			if not ok then return nil, "could not check whether " .. name .. " exists" end
			present = result
			if not present then return nil end
		end
		local ok, source = pcall(read, name)
		if ok and type(source) == "string" then return source end
		if present then return nil, "could not read existing " .. name .. "; refusing to overwrite it" end
		if not caps.fn.isfile then return nil, "could not establish whether " .. name .. " exists (isfile is unavailable)" end
	end

	function M.read(name)
		local filename, err = M.filename(name)
		if not filename then return nil, err end
		local source, readErr = readExisting(filename)
		if not source then return nil, readErr or (filename .. " does not exist") end
		if #source > MAX_BYTES then return nil, "plugin is larger than 256 KB" end
		return source, nil, filename
	end

	local function validate(plugin)
		if type(plugin) ~= "table" then return nil, "plugin must return a Plugin table" end
		if type(plugin.PluginName) ~= "string" or util.trim(plugin.PluginName) == "" then return nil, "PluginName must be a nonempty string" end
		if type(plugin.PluginDescription) ~= "string" then return nil, "PluginDescription must be a string" end
		if type(plugin.Commands) ~= "table" or next(plugin.Commands) == nil then return nil, "Commands must contain at least one command" end
		local count, names = 0, {}
		for name, command in pairs(plugin.Commands) do
			count = count + 1
			if count > 100 then return nil, "a plugin may contain at most 100 commands" end
			if type(name) ~= "string" or not name:match("^[%w_%-]+$") then return nil, "command names must be single words" end
			if type(command) ~= "table" or type(command.Function) ~= "function" then return nil, name .. " needs a Function(args, speaker)" end
			if type(command.ListName) ~= "string" or type(command.Description) ~= "string" then return nil, name .. " needs ListName and Description strings" end
			if type(command.Aliases) ~= "table" or not util.isArray(command.Aliases) then return nil, name .. " needs an Aliases array (use {} for none)" end
			for _, alias in ipairs(command.Aliases) do
				if type(alias) ~= "string" or not alias:match("^[%w_%-]+$") then return nil, name .. " has an invalid alias" end
			end
			names[#names + 1] = name
		end
		table.sort(names)
		return names
	end
	local function registered(name)
		for _, plugin in ipairs(iy.value("PluginsTable") or {}) do if plugin == name then return true end end
		return false
	end
	local function commands(name)
		local out = {}
		for _, command in ipairs(iy.cmdsTable() or {}) do
			if command.PLUGIN == name then out[#out + 1] = command.NAME end
		end
		table.sort(out)
		return out
	end
	local function cancelled(ctx) return ctx and ctx.aborted and ctx.aborted() end

	local function write(args, ctx)
		local name, err = M.filename(args.plugin)
		if not name then return nil, err end
		if type(args.source) ~= "string" or #args.source == 0 or #args.source > MAX_BYTES then return nil, "source must contain 1–256000 bytes" end
		if not caps.fn.writefile or not caps.fn.loadstring then return nil, "plugin authoring needs writefile and loadstring" end
		local previous, readErr = readExisting(name)
		if readErr then return nil, readErr end
		if previous ~= nil and args.overwrite ~= true then return nil, name .. " exists; read it first and set overwrite=true to update it" end
		local compiled, chunk, compileErr = pcall(caps.fn.loadstring, args.source, "@" .. name)
		if not compiled or not chunk then return nil, "syntax error: " .. tostring(compiled and compileErr or chunk) end
		local load = args.load ~= false
		local add, remove, scope, fallback, wasRegistered
		if load then
			local ready, why = iy.ensure()
			if not ready then return nil, why end
			add, remove = iy.value("addPlugin"), iy.value("deletePlugin")
			if type(add) ~= "function" or type(iy.value("PluginsTable")) ~= "table" or type(iy.cmdsTable()) ~= "table" then
				return nil, "IY's plugin loader and registries must be exposed to verify a load"
			end
			wasRegistered = registered(name)
			if wasRegistered and type(remove) ~= "function" then return nil, "IY's plugin remover is unavailable; cannot reload this plugin" end
			scope = iy.environment()
			fallback = scope.loadfile
			if type(fallback) ~= "function" then return nil, "IY's loadfile is unavailable" end
			if not setfenv then return nil, "this host cannot bind plugin globals to IY (setfenv is unavailable); use load=false to save only" end
			local bound, why = pcall(setfenv, chunk, scope)
			if not bound then return nil, "could not bind plugin globals: " .. tostring(why) end
		end
		if cancelled(ctx) then return nil, "cancelled before writing the plugin" end
		local function restore()
			if previous ~= nil then
				local ok = pcall(caps.fn.writefile, name, previous)
				return ok and "Previous file restored." or "The previous file could not be restored."
			elseif caps.fn.delfile then
				local ok = pcall(caps.fn.delfile, name)
				return ok and "New file removed." or "The new file could not be removed."
			end
			return "The new file remains on disk."
		end
		local written, writeErr = pcall(caps.fn.writefile, name, args.source)
		if not written then return nil, "could not write " .. name .. ": " .. tostring(writeErr) .. ". " .. restore() end
		local verified, saved = pcall(caps.fn.readfile, name)
		if not verified or saved ~= args.source then return nil, "plugin write could not be verified. " .. restore() end
		if not load then return { plugin = name, bytes = #args.source, loaded = false, validation = "syntax checked; source was not executed" } end

		-- Evaluate once before removing existing commands. IY will consume this same
		-- returned table, preserving globals and closures without rerunning setup.
		local ran, plugin = pcall(chunk)
		if not ran then return nil, "plugin setup failed: " .. tostring(plugin) .. ". " .. restore() end
		local expected, invalid = validate(plugin)
		if not expected then return nil, "invalid plugin: " .. invalid .. ". " .. restore() end
		if cancelled(ctx) then return nil, "cancelled before registering the plugin. " .. restore() end
		local original = rawget(scope, "loadfile")
		rawset(scope, "loadfile", function(path, ...)
			if path == name then return function() return plugin end end
			return fallback(path, ...)
		end)
		local ok, loadErr = pcall(function()
			if wasRegistered then remove(name) end
			add(name)
		end)
		rawset(scope, "loadfile", original)
		local live = commands(name)
		if not ok or not registered(name) or #live ~= #expected then
			return nil, name .. " was saved, but IY did not register all commands: " .. tostring(loadErr or "check IY's plugin error")
		end
		return { plugin = name, name = plugin.PluginName, description = plugin.PluginDescription,
			bytes = #args.source, loaded = true, commands = live, validation = "syntax and plugin table checked" }
	end
	local writing = {}
	function M.write(args, ctx)
		local name, err = M.filename(args.plugin)
		if not name then return nil, err end
		local key = name:lower()
		if writing[key] then return nil, name .. " is already being updated; wait for that call to finish" end
		writing[key] = true
		local ok, result, reason = pcall(write, args, ctx)
		writing[key] = nil
		if not ok then return nil, "plugin authoring failed: " .. tostring(result) end
		return result, reason
	end
	return M
end
end)()

-- ==========================================================================
-- runtime/iy_store
-- ==========================================================================
__UAI_MODULES["runtime/iy_store"] = (function()
-- The Infinite Yield plugin store, as a runtime.
--
-- iyplugins.pages.dev publishes a JSON index of community plugins -- several
-- hundred .iy files with names, authors and download paths. This module turns
-- that index into three operations -- search, install, uninstall -- and the
-- tools in tools/iy expose them to the agent. There is deliberately no store
-- UI: the catalog is browsed in conversation, by asking for what is wanted.
--
-- Install mechanics, matching what IY's own `plugin <name>` command does:
--   1. download the .iy source from the store,
--   2. write it into the executor's workspace ROOT by that name -- IY's
--      addPlugin reads `readfile(name)`, an executor-relative path, so the
--      file cannot live in UAI's own folder,
--   3. call IY's addPlugin(name), which loads the file and registers its
--      commands.
-- Uninstall is deletePlugin(name) plus delfile, in that order: unregister
-- first so nothing holds a reference to code that is about to disappear.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local clock = env.require("runtime/clock")
	local log = env.require("runtime/log")
	local iy = env.require("runtime/iy")
	local plugins = env.require("runtime/iy_plugins")

	local API_URL = "https://iyplugins.pages.dev/data/api.json"
	local SITE = "https://iyplugins.pages.dev/"
	local DOWNLOAD_TIMEOUT = 30
	local CATALOG_STALE_MS = 10 * 60 * 1000

	local M = {
		catalog = nil,
		catalogAt = 0,
		catalogError = nil,
	}

	local function httpGet(url, tag)
		local http = env.require("net/http")
		return http.send({
			url = url,
			method = "GET",
			identity = "browser",
			tag = tag,
			timeout = DOWNLOAD_TIMEOUT * 1000,
			attempts = 2,
		})
	end

	-- The index, fetched at most once every ten minutes. A search tool the
	-- model calls repeatedly in one turn must not re-download half a megabyte
	-- each time; a cache with no expiry would hide new plugins for a session.
	function M.fetchCatalog(force)
		if M.catalog and not force and (clock.ms() - M.catalogAt) < CATALOG_STALE_MS then
			return M.catalog, nil
		end
		local res, err = httpGet(API_URL, "iy-store")
		if not res then
			M.catalogError = err
			return nil, "could not reach the store: " .. tostring(err)
		end
		if res.status ~= 200 then
			M.catalogError = "HTTP " .. res.status
			return nil, "the store answered HTTP " .. res.status
		end
		local decoded, decodeErr = util.decode(res.body)
		if type(decoded) ~= "table" or type(decoded.plugins) ~= "table" then
			return nil, "the store's index is not the shape expected: " .. tostring(decodeErr)
		end
		M.catalog = decoded
		M.catalogAt = clock.ms()
		M.catalogError = nil
		return decoded, nil
	end

	-- The .iy entry of a store record. A submission may carry screenshots and
	-- videos alongside the plugin; `is_plugin` is the store's own flag for
	-- which file is the code.
	local function pluginFile(entry)
		for _, file in ipairs(type(entry.files) == "table" and entry.files or {}) do
			if type(file) == "table" and file.is_plugin ~= false then
				local name = tostring(file.filename or "")
				local url = tostring(file.url or "")
				if name ~= "" and url ~= "" then
					return { name = name, url = url, size = tonumber(file.size) }
				end
			end
		end
		return nil
	end

	-- Every entry that matches a query. Matches the name (strongest), the
	-- author, and the filename; a query that is an id matches exactly.
	function M.search(query, limit)
		local catalog, err = M.fetchCatalog()
		if not catalog then return nil, err end

		local needle = util.trim(tostring(query or "")):lower()
		local out = {}
		for _, entry in ipairs(catalog.plugins) do
			if type(entry) == "table" then
				local name = tostring(entry.name or "")
				local author = tostring(entry.author or "")
				local file = pluginFile(entry)
				local matched = false
				local score = 0
				if needle == "" then
					matched = true
				elseif tostring(entry.id or "") == needle then
					matched, score = true, 4
				elseif name:lower():find(needle, 1, true) then
					matched, score = true, 3
				elseif file and file.name:lower():find(needle, 1, true) then
					matched, score = true, 2
				elseif author:lower():find(needle, 1, true) then
					matched, score = true, 1
				end
				if matched then
					out[#out + 1] = {
						id = tostring(entry.id or ""),
						name = name,
						author = author,
						score = score,
						file = file,
					}
				end
			end
		end
		-- Stronger matches first, then alphabetical, so "dex" finds
		-- "dexrecontinued" ahead of "indexviewer".
		table.sort(out, function(a, b)
			if a.score ~= b.score then return a.score > b.score end
			return a.name:lower() < b.name:lower()
		end)
		if limit and limit > 0 then
			while #out > limit do table.remove(out) end
		end
		return out, nil
	end

	-- IY's plugin functions are chunk globals like everything else: present in
	-- the shared table after an ambient load, or in the holder after ours.
	local function iyFunction(name)
		return iy.value(name)
	end

	-- Download, write to the workspace root, register with IY.
	function M.install(plugin, ctx)
		local wanted = util.trim(tostring(plugin or ""))
		if wanted == "" then return false, "no plugin named" end

		local ready, reason = iy.ensure()
		if not ready then return false, reason end

		local results, err = M.search(wanted, 5)
		if not results then return false, err end
		if #results == 0 then
			return false, "nothing on the store matches '" .. wanted .. "'"
		end
		local entry = results[1]
		if #results > 1 and not (entry.name:lower() == wanted:lower()
			or entry.id == wanted
			or (entry.file and entry.file.name:lower() == wanted:lower() .. ".iy")) then
			local names = {}
			for index = 1, math.min(#results, 5) do
				names[#names + 1] = results[index].name
			end
			return false, "several plugins match; name one: " .. table.concat(names, ", ")
		end
		if not entry.file then
			return false, "'" .. entry.name .. "' has no .iy file on the store"
		end

		local write = caps.fn.writefile
		local read = caps.fn.readfile
		if not write or not read then
			return false, "this host has no filesystem functions, so a plugin cannot be saved"
		end

		-- Already on disk and registered: a re-install is a no-op, not an error.
		local registered = iyFunction("addPlugin")
		if type(registered) ~= "function" then
			return false, "IY is loaded but its plugin loader is not reachable"
		end
		local fileName, filenameError = plugins.filename(entry.file.name)
		if not fileName or fileName ~= entry.file.name then return false, filenameError or "the store supplied a noncanonical plugin filename" end
		if not caps.fn.isfile then return false, "isfile is required to avoid overwriting an existing plugin" end
		local checked, present = pcall(caps.fn.isfile, fileName)
		if not checked then return false, "could not check the plugin destination" end
		if present then
			local readable, existing = pcall(read, fileName)
			if not readable or type(existing) ~= "string" then return false, "existing plugin is unreadable; refusing to overwrite it" end
			return true, fileName .. " is already installed; load it with plugin " .. fileName:gsub("%.iy$", "")
		end

		local res, dlErr = httpGet(SITE .. entry.file.url, "iy-plugin")
		if not res then return false, "could not download it: " .. tostring(dlErr) end
		if res.status ~= 200 then
			return false, "the download answered HTTP " .. res.status
		end
		local source = tostring(res.body or "")
		if #source == 0 then return false, "the download was empty" end
		if #source > 2 * 1024 * 1024 then return false, "plugin source exceeds 2 MiB" end
		if ctx and ctx.aborted and ctx.aborted() then return false, "cancelled before writing the plugin" end
		-- A native download can yield long enough for a local editor to create the
		-- destination. Do not overwrite those bytes or register an unverified file.
		local nowChecked, existsNow = pcall(caps.fn.isfile, fileName)
		if not nowChecked or existsNow then return false, "plugin destination changed or became unreadable during download; inspect it before retrying" end

		-- A size sanity check against the index: a body wildly larger than the
		-- catalogue's number is an error page or a redirect, not a plugin.
		if entry.file.size and #source > entry.file.size * 20 and #source > 50000 then
			log.warn("iy-store", "download was " .. #source .. " bytes, the index said " .. entry.file.size)
		end

		local okWrite = pcall(write, fileName, source)
		if not okWrite then return false, "could not write " .. fileName .. " to the workspace" end
		local verified, saved = pcall(read, fileName)
		if not verified or saved ~= source then return false, "plugin write could not be verified; it was not loaded" end
		if ctx and ctx.aborted and ctx.aborted() then return false, "plugin was saved but loading was cancelled" end

		local okLoad, loadErr = pcall(registered, fileName)
		if not okLoad then
			pcall(function()
				if caps.fn.delfile and read(fileName) == source then caps.fn.delfile(fileName) end
			end)
			return false, "saved, but IY could not load it: " .. tostring(loadErr)
		end

		log.info("iy-store", "installed " .. fileName .. " from the store")
		return true, "Saved " .. fileName .. " and requested registration through IY"
	end

	-- Unregister from IY, then remove the file.
	function M.uninstall(plugin)
		if iy.getMode() == "off" then return false, "Infinite Yield integration is off in Settings" end
		local wanted, why = plugins.filename(plugin)
		if not wanted then return false, why end

		local remover = iyFunction("deletePlugin")
		if type(remover) ~= "function" then
			return false, "IY is not loaded, so its plugin registry is not reachable"
		end

		local ok = pcall(remover, wanted)
		if not ok then return false, "IY could not remove " .. wanted end

		if caps.fn.delfile then
			pcall(caps.fn.delfile, wanted)
		end
		return true, wanted
	end

	-- What is on disk and registered right now. The registry side is read
	-- through IY's own PluginsTable when it is visible; otherwise the .iy files
	-- in the workspace root are the honest answer for what could be loaded.
	function M.listInstalled()
		local out = {}
		if iy.isLoaded() then
			local table_ = iyFunction("PluginsTable")
			if type(table_) == "table" then
				for _, name in ipairs(table_) do
					out[#out + 1] = tostring(name)
				end
			end
		end
		if caps.fn.listfiles then
			local ok, files = pcall(caps.fn.listfiles, "")
			if ok and type(files) == "table" then
				local seen = {}
				for _, name in ipairs(out) do seen[name] = true end
				for _, path in ipairs(files) do
					local clean = tostring(path):gsub("^%.?/", "")
					if clean:sub(-3) == ".iy" and not seen[clean] then
						out[#out + 1] = clean
					end
				end
			end
		end
		return out
	end

	return M
end
end)()

-- ==========================================================================
-- runtime/legacy_values
-- ==========================================================================
__UAI_MODULES["runtime/legacy_values"] = (function()
-- Compatibility text codecs. Native snapshots use runtime/values.
return function(env)
	local util = env.require("runtime/util")
	local paths = env.require("runtime/instance_paths")
	local M = { resolve = paths.resolve, pathOf = paths.pathOf }
	-- Values -----------------------------------------------------------------

	-- Roblox value -> compact text a model can read and, importantly, feed back in.
	function M.show(value)
		local kind = typeof(value)
		if value == nil then return "nil" end
		if kind == "Vector3" then
			return string.format("%.2f, %.2f, %.2f", value.X, value.Y, value.Z)
		end
		if kind == "Vector2" then
			return string.format("%.2f, %.2f", value.X, value.Y)
		end
		if kind == "CFrame" then
			local p = value.Position
			return string.format("%.2f, %.2f, %.2f", p.X, p.Y, p.Z)
		end
		if kind == "Color3" then
			return string.format("%d, %d, %d",
				math.floor(value.R * 255 + 0.5), math.floor(value.G * 255 + 0.5), math.floor(value.B * 255 + 0.5))
		end
		if kind == "UDim2" then
			return string.format("%.3g, %d, %.3g, %d", value.X.Scale, value.X.Offset, value.Y.Scale, value.Y.Offset)
		end
		if kind == "UDim" then
			return string.format("%.3g, %d", value.Scale, value.Offset)
		end
		if kind == "NumberRange" then
			return string.format("%.3g..%.3g", value.Min, value.Max)
		end
		if kind == "EnumItem" then
			return "Enum." .. tostring(value.EnumType) .. "." .. tostring(value.Name)
		end
		if kind == "Instance" then
			return M.pathOf(value) .. " [" .. tostring(value.ClassName) .. "]"
		end
		if kind == "BrickColor" then return tostring(value.Name) end
		if kind == "number" then
			if value == math.floor(value) and math.abs(value) < 1e12 then return string.format("%d", value) end
			return string.format("%.4g", value)
		end
		if kind == "boolean" then return value and "true" or "false" end
		if kind == "string" then return value end
		if kind == "table" then return "{table}" end
		return tostring(value)
	end

	local function numbers(text, count, maximum)
		local out = {}
		-- Parse whole numeric tokens so exponents and leading decimal points do
		-- not silently turn into extra coordinates. The range separator is '..'.
		local body = tostring(text):gsub("%.%.", ","):gsub("[%(%)]", " ")
		for piece in body:gmatch("[^,%s]+") do
			local value = tonumber(piece)
			if not value or value ~= value or value == math.huge or value == -math.huge then return nil end
			out[#out + 1] = value
		end
		if #out < count or #out > (maximum or count) then return nil end
		return out
	end

	-- Text (or a JSON object) -> a Roblox value of the same type as `current`.
	--
	-- Typing off the existing value is what makes one set_property tool work for
	-- both a Part's Vector3 Size and a Frame's UDim2 Size without the model having
	-- to know which it is looking at.
	function M.coerce(input, current)
		local wanted = typeof(current)
		if wanted == "string" then return tostring(input) end

		if type(input) == "table" and not (wanted == "table") then
			-- JSON object form: { x = 1, y = 2, z = 3 } or { r = 255, ... }.
			local parts = input
			if wanted == "Vector3" then
				return Vector3.new(tonumber(parts.x or parts.X) or 0, tonumber(parts.y or parts.Y) or 0, tonumber(parts.z or parts.Z) or 0)
			end
			if wanted == "Vector2" then
				return Vector2.new(tonumber(parts.x or parts.X) or 0, tonumber(parts.y or parts.Y) or 0)
			end
			if wanted == "Color3" then
				local r = tonumber(parts.r or parts.R) or 0
				local g = tonumber(parts.g or parts.G) or 0
				local b = tonumber(parts.b or parts.B) or 0
				if r <= 1 and g <= 1 and b <= 1 then return Color3.new(r, g, b) end
				return Color3.fromRGB(r, g, b)
			end
			if wanted == "UDim2" then
				return UDim2.new(
					tonumber(parts.xScale or parts.sx) or 0, tonumber(parts.xOffset or parts.ox) or 0,
					tonumber(parts.yScale or parts.sy) or 0, tonumber(parts.yOffset or parts.oy) or 0)
			end
			return nil, "cannot build a " .. tostring(wanted) .. " from an object"
		end

		local text = util.trim(input)

		if wanted == "number" then
			local value = tonumber(text)
			if not value or value ~= value or value == math.huge or value == -math.huge then
				return nil, "expected a finite number"
			end
			return value
		end
		if wanted == "boolean" then
			local lowered = text:lower()
			if lowered == "true" or lowered == "1" or lowered == "yes" then return true end
			if lowered == "false" or lowered == "0" or lowered == "no" then return false end
			return nil, "expected true or false"
		end
		if wanted == "Vector3" then
			local list = numbers(text, 3)
			if not list then return nil, "expected three numbers, e.g. '0, 10, 0'" end
			return Vector3.new(list[1], list[2], list[3])
		end
		if wanted == "Vector2" then
			local list = numbers(text, 2)
			if not list then return nil, "expected two numbers" end
			return Vector2.new(list[1], list[2])
		end
		if wanted == "CFrame" then
			local list = numbers(text, 3)
			if not list then return nil, "expected three numbers for a position" end
			return CFrame.new(list[1], list[2], list[3])
		end
		if wanted == "Color3" then
			local hex = text:match("^#?(%x%x%x%x%x%x)$")
			if hex then return Color3.fromHex(hex) end
			local list = numbers(text, 3)
			if not list then return nil, "expected 'r, g, b' or a hex colour" end
			if list[1] <= 1 and list[2] <= 1 and list[3] <= 1 then
				return Color3.new(list[1], list[2], list[3])
			end
			return Color3.fromRGB(list[1], list[2], list[3])
		end
		if wanted == "UDim2" then
			local list = numbers(text, 4)
			if not list then return nil, "expected four numbers: xScale, xOffset, yScale, yOffset" end
			return UDim2.new(list[1], list[2], list[3], list[4])
		end
		if wanted == "UDim" then
			local list = numbers(text, 2)
			if not list then return nil, "expected two numbers: scale, offset" end
			return UDim.new(list[1], list[2])
		end
		if wanted == "NumberRange" then
			local list = numbers(text, 1, 2)
			if not list then return nil, "expected one or two numbers" end
			return NumberRange.new(list[1], list[2] or list[1])
		end
		if wanted == "EnumItem" then
			local enumType = tostring(current.EnumType)
			local wantedName = text:match("([%w_]+)$") or text
			local ok, items = pcall(function() return Enum[enumType]:GetEnumItems() end)
			if ok and type(items) == "table" then
				for _, item in ipairs(items) do
					if tostring(item.Name):lower() == wantedName:lower() then return item end
				end
				local names = {}
				for _, item in ipairs(items) do names[#names + 1] = item.Name end
				return nil, "expected one of: " .. table.concat(names, ", ")
			end
			return nil, "unknown enum " .. enumType
		end
		if wanted == "Instance" or current == nil then
			local instance, err = M.resolve(text)
			if instance then return instance end
			if current == nil then return text end
			return nil, err
		end
		if wanted == "BrickColor" then
			local ok, colour = pcall(function() return BrickColor.new(text) end)
			if ok then return colour end
			return nil, "unknown BrickColor"
		end
		return nil, "setting a " .. tostring(wanted) .. " is not supported"
	end

	return M
end
end)()

