			add("game:HttpGetAsync", gameMethod("HttpGetAsync"), "httpget")
			add("game:HttpPost", gameMethod("HttpPost"), "httppost")
			add("game:HttpPostAsync", gameMethod("HttpPostAsync"), "httppost")
