		end
		if mode == "chunks" or mode == "both" then
			local raw = caps.raw or {}
			add("loadstring", raw.loadstring, "loadstring")
			add("loadstring (getgenv)", globals.loadstring, "loadstring")
			add("load", raw.load, "load")
