					if not stamp or value.used < stamp then oldest, stamp = path, value.used end
				end
				if not oldest then break end
				compileBytes, compileCount = compileBytes - #compiled[oldest].source, compileCount - 1
				compiled[oldest] = nil
			end
			sequence = sequence + 1
