	end
	local function idValid(id)
		if type(id) ~= "string" or #id > 100 or not id:match("^[%w_%-/]+$") then return false end
		return id:sub(1, 1) ~= "/" and id:sub(-1) ~= "/" and not id:find("//", 1, true)
