			elseif code:sub(at, at + 1) == "--" then
				at = skipComment(code, at)
			elseif char == "[" and skipLong(code, at) then
				at = skipLong(code, at)
			elseif char == "{" then
				depth = depth + 1
				at = at + 1
			elseif char == "}" then
				depth = depth - 1
				at = at + 1
