			task.wait()
		end
		local pendingOnFailure = failure and (not done or next(children) ~= nil)
		if stopped or failure then execution.stop(stopped or "error") end
		active[execution] = nil

		local output, status = {}, "completed"
		if stopped == "aborted" then
			status = "aborted"
