			if content and #content > W.MAX_BYTES then
				slice = H.fail("this file exceeds the 2 MB batch limit; use file_read")
			elseif content then
				slice = H.readSlice(resolved or request.path, content, request, 6000, budget)
			else
				slice = H.fail(err)
