			elseif #content > W.MAX_BYTES or content:find("\0", 1, true) then
				skipped = skipped + 1
			else
				if bytesRead > 8 * 1024 * 1024 then
					nextCursor, limited = { path = path, line = 1 }, "read budget"
					break
				end
				filesRead = filesRead + 1
