					end
				end

				return H.fail("nothing interactable found at that path, or the host lacks the function to trigger it")
			end,
		},
		{
			name = "highlight",
			risk = "write",
			description = "Outline an instance on screen for a few seconds so the user can see which one you mean.",
			parameters = {
				type = "object",
				properties = {
					path = { type = "string" },
					seconds = { type = "number", description = "1-30. Default 6.", minimum = 1, maximum = 30 },
					colour = { type = "string", description = "Outline colour as 'r, g, b' or '#rrggbb'." },
				},
				required = { "path" },
			},
			run = function(args)
				local instance, err = H.resolve(args.path)
				if not instance then return H.fail(err) end

				local colour = Color3.fromRGB(0, 225, 190)
				if args.colour and util.trim(args.colour) ~= "" then
					local parsed = H.coerce(args.colour, colour)
					if not parsed then return H.fail("colour must be valid RGB or #rrggbb") end
					colour = parsed
				end
				local okNew, highlight = pcall(function() return Instance.new("Highlight") end)
				if not okNew or not highlight then return H.fail("this host has no Highlight class") end
				local release = env.require("runtime/dispose").add(function() highlight:Destroy() end, "tool highlight")

				local configured, problem = pcall(function()
					highlight.Name = "UAI_Highlight"
					highlight.FillColor = colour
					highlight.OutlineColor = colour
					highlight.FillTransparency = 0.65
					highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
					highlight.Adornee = instance
					highlight.Parent = instance
				end)
				if not configured then release(); return H.fail("highlight could not be configured: " .. tostring(problem)) end

				local seconds = util.clamp(tonumber(args.seconds) or 6, 1, 30)
				clock.delay(seconds, release)
				return string.format("Highlighted %s for %.0f seconds", H.pathOf(instance), seconds)
			end,
		},
		{
			name = "notify",
			risk = "read",
			description = "Show a short message to the user as a toast in the agent's own interface. Use it for something worth noticing, not for your reply.",
			parameters = {
				type = "object",
				properties = {
					text = { type = "string", description = "One line, under about 90 characters." },
					tone = { type = "string", enum = { "info", "good", "warn", "bad" } },
				},
				required = { "text" },
			},
			run = function(args)
				local overlay = env.require("ui/overlay")
				local text = util.ellipsis(args.text, 140)
				if not overlay.toast(text, args.tone or "info") then return H.fail("the client interface is not mounted; notification was not shown") end
				return "Shown to the user: " .. text
			end,
		},
		{
			name = "clipboard_set",
			risk = "write",
			needs = { "clipboard" },
			description = "Put text on the user's clipboard.",
			parameters = {
				type = "object",
				properties = { text = { type = "string" } },
				required = { "text" },
			},
			run = function(args)
				local text = tostring(args.text or "")
				if text == "" then return "Nothing to copy." end
				local ok, err = pcall(caps.fn.clipboard, text)
				if not ok or err == false then return H.fail("clipboard write was rejected: " .. tostring(err)) end
				return string.format("Copied %d bytes to the clipboard.", #text)
			end,
		},
	}
end
end)()

-- ==========================================================================
-- tools/helpers
-- ==========================================================================
__UAI_MODULES["tools/helpers"] = (function()
-- Shared machinery for the tool groups: path resolution, value conversion in both
-- directions, and the formatting conventions every tool result follows.
--
-- Two rules drive the design. Model output is untrusted text, so a path or a
-- property value is parsed rather than trusted. And a tool result is read by a
-- model, not a person, so it is dense, labelled, and bounded -- a wall of
-- unlabelled values costs tokens and teaches nothing.
return function(env)
	local util = env.require("runtime/util")

	local H = {}

	-- Paths ------------------------------------------------------------------

	local paths = env.require("runtime/instance_paths")
	H.resolve, H.pathOf, H.ROOT_NAMES = paths.resolve, paths.pathOf, paths.ROOT_NAMES

	local legacy = env.require("runtime/legacy_values")
	H.show, H.coerce = legacy.show, legacy.coerce

	-- Formatting -------------------------------------------------------------

	function H.describe(instance, countChildren)
		if not instance then return "nil" end
		local extra = {}
		local ok = pcall(function()
			if instance:IsA("BasePart") then
				extra[#extra + 1] = "at " .. H.show(instance.Position)
			elseif instance:IsA("GuiObject") then
				extra[#extra + 1] = "size " .. H.show(instance.Size)
			elseif instance:IsA("Humanoid") then
				extra[#extra + 1] = string.format("health %s/%s", H.show(instance.Health), H.show(instance.MaxHealth))
			end
		end)
		local childCount = 0
		if countChildren ~= false then pcall(function() childCount = #instance:GetChildren() end) end
		if childCount > 0 then extra[#extra + 1] = util.pluralise(childCount, "child") end
		return string.format("%s [%s]%s", instance.Name, instance.ClassName,
			(ok and #extra > 0) and (" " .. table.concat(extra, ", ")) or "")
	end

	-- Numbered list with an explicit note when it was cut short, so a model can
	-- tell "that is everything" from "there is more".
	function H.list(items, limit, render)
		local lines = {}
		local shown = math.min(#items, limit or #items)
		for index = 1, shown do
			lines[#lines + 1] = string.format("%d. %s", index, render and render(items[index], index) or tostring(items[index]))
		end
		if #items > shown then
			lines[#lines + 1] = string.format("... %d more (narrow the query to see them)", #items - shown)
		end
		if #lines == 0 then return "(none)" end
		return table.concat(lines, "\n")
	end

	function H.keyValues(pairsList)
		local lines = {}
		for _, entry in ipairs(pairsList) do
			lines[#lines + 1] = entry[1] .. ": " .. tostring(entry[2])
		end
		return table.concat(lines, "\n")
	end

	function H.limit(value, fallback, ceiling)
		local number = tonumber(value) or fallback
		if type(number) ~= "number" or number ~= number or math.abs(number) == math.huge then number = fallback or 1 end
		return math.floor(util.clamp(number, 1, ceiling or 200))
	end

	-- A contiguous, resumable slice. Leave room for its cursor inside the registry's
	-- result budget so a second truncation cannot silently remove the middle.
	function H.resultBudget()
		local value = tonumber(env.require("runtime/config").get("agent.resultCap", 4000))
		if not value or value ~= value or math.abs(value) == math.huge then return 4000 end
		return math.floor(util.clamp(value, 0, 128000))
	end

	-- Page already-collected rows without formatting or copying the omitted tail.
	-- Keep metadata out of the row text so the model sees each payload only once.
	function H.page(items, args, title, render, defaultLimit, maximum)
		args = args or {}
		local offset = H.limit(args.offset, 1, #items + 1)
		if tonumber(args.offset) and tonumber(args.offset) > #items + 1 then return H.fail("offset is past the end of this listing") end
		local budget = H.resultBudget() - 320
		if budget < 128 then return H.fail("increase the tool result budget to at least 448 bytes before listing results") end
		local lines, bytes, nextOffset = {}, #title + 1, nil
		local limit = H.limit(args.limit, defaultLimit or 25, maximum or 100)
		for index = offset, math.min(#items, offset + limit - 1) do
			local line = tostring(render and render(items[index], index) or items[index])
			line = tostring(index) .. ". " .. line
			if bytes + #line + 1 > budget then
				if #lines == 0 then return H.fail("one listing row exceeds the result budget; increase it or narrow the requested fields") end
				nextOffset = index; break
			end
			lines[#lines + 1] = line; bytes = bytes + #line + 1
		end
		if not nextOffset and offset + #lines <= #items then nextOffset = offset + #lines end
		return { text = title .. (#lines > 0 and ("\n" .. table.concat(lines, "\n")) or "\n(none)"),
			data = { offset = offset, count = #lines, total = #items, remaining = math.max(0, #items - offset - #lines + 1), nextOffset = nextOffset, eof = nextOffset == nil } }
	end

	function H.readSlice(name, content, args, defaultLimit, budget)
		args = args or {}
		local cap = math.min(H.resultBudget(), budget or math.huge)
		if cap < 256 then return H.fail("increase the tool result budget to at least 256 bytes before reading files") end
		local requested = tonumber(args.offset) or 1
		if requested ~= requested or math.abs(requested) == math.huge then return H.fail("offset must be a finite byte position") end
		local offset = math.max(1, math.floor(requested))
		if offset > #content + 1 then return H.fail("offset is past the end; this source has " .. #content .. " bytes") end
		while offset > 1 do
			local byte = content:byte(offset)
			if not byte or byte < 128 or byte >= 192 then break end
			offset = offset - 1
		end
		local label = util.ellipsis(name, 100)
		local limit = H.limit(args.limit, defaultLimit or 6000, cap - 220)
		local last = math.min(#content, offset + math.floor(limit) - 1)
		while last >= offset and last < #content do
			local byte = content:byte(last + 1)
			if byte < 128 or byte >= 192 then break end
			last = last - 1
		end
		if last < offset and offset <= #content then
			last = offset
			while last < #content and content:byte(last + 1) >= 128 and content:byte(last + 1) < 192 do last = last + 1 end
		end
		local nextOffset = last < #content and last + 1 or nil
		local header = string.format("%s (bytes %d-%d of %d%s):\n", label, offset, last, #content,
			nextOffset and ("; continue with offset=" .. nextOffset) or "; end of file")
		if #content == 0 then header = label .. " (empty, 0 bytes):\n" end
		return { text = header .. content:sub(offset, last), data = {
			offset = offset, nextOffset = nextOffset, totalBytes = #content, eof = nextOffset == nil,
		} }
	end

	-- A tool that could not do what was asked returns this rather than a bare
	-- string, so the registry can mark the call as failed and the transcript can
	-- colour it. The model sees the same sentence either way.
	function H.fail(message)
		return { ok = false, text = "Failed: " .. tostring(message) }
	end

	-- A tool that changed something says what it changed and where, because the
	-- next turn often needs the path again.
	function H.changed(what, where, detail)
		return string.format("%s on %s%s", what, where, detail and (" -> " .. detail) or "")
	end

	-- Small property batches preflight every read, then report each observed write.
	-- Engine effects are not atomic and are never described as rolled back.
	function H.writeProperties(target, edits, label, ctx)
		if #edits == 0 then return H.fail("pass at least one value to change") end
		for _, edit in ipairs(edits) do
			local ok, value = pcall(function() return target[edit.property] end)
			if not ok or value == nil then return H.fail("could not read " .. edit.property .. " before changing " .. label) end
			edit.before = value
		end
		local rows, results, changed, failed, uncertain = {}, {}, 0, 0, 0
		for _, edit in ipairs(edits) do
			local checked, stopped = true, false
			if ctx and ctx.aborted then checked, stopped = pcall(ctx.aborted) end
			stopped = not checked or stopped
			local ok, problem = false, stopped and "cancelled before write" or nil
			local value
			if not stopped then
				ok, problem = pcall(function()
					if edit.value ~= edit.before then target[edit.property] = edit.value end
				end)
				local readable, observed = pcall(function() return target[edit.property] end)
				if readable then
					value = observed
					if value ~= edit.before then changed = changed + 1 end
					if ok and value ~= edit.value then ok, problem = false, "engine readback differs from requested value: " .. H.show(value) end
				else uncertain = uncertain + 1; ok, problem = false, "readback unavailable after write; effects are uncertain" end
			end
			if ok then
				rows[#rows + 1] = edit.property .. " = " .. H.show(value) .. " (was " .. H.show(edit.before) .. ")"
			else failed = failed + 1; rows[#rows + 1] = edit.property .. " failed: " .. tostring(problem) end
			results[#results + 1] = { property = edit.property, ok = ok, before = H.show(edit.before), observed = value ~= nil and H.show(value) or nil, error = not ok and tostring(problem) or nil }
		end
		return { ok = failed == 0, text = label .. ": " .. table.concat(rows, "; "),
			data = { status = failed == 0 and "applied" or (changed > 0 or uncertain > 0) and "partial" or "failed", changed = changed, uncertain = uncertain, failed = failed, results = results, localObservation = true } }
	end

	-- Temporary signal inspection owns its listener even when a wait fails or the
	-- client unloads. Bound formatting work before game traffic reaches the model.
	function H.watch(signal, count, seconds, ctx, label)
		local clock = env.require("runtime/clock")
		local function aborted()
			if not ctx or not ctx.aborted then return false end
			local ok, value = pcall(ctx.aborted); return not ok or value == true
		end
		if aborted() then return { ok = false, text = "Observation cancelled before listening.", data = { status = "aborted", count = 0 } } end
		local captured, alive, bytes = {}, true, 0
		local budget = math.max(128, H.resultBudget() - 480)
		local ok, connection = pcall(function()
			return signal:Connect(function(...)
				if not alive or #captured >= count or aborted() then return end
				local args, total = {}, select("#", ...)
				for index = 1, math.min(total, 32) do args[index] = select(index, ...) end
				local rendered, value = pcall(function()
					local parts = {}
					for index = 1, math.min(total, 32) do parts[#parts + 1] = index .. ": " .. util.ellipsis(H.show(args[index]), 160) end
					if total > 32 then parts[#parts + 1] = "... " .. (total - 32) .. " more arguments" end
					return #parts > 0 and table.concat(parts, ", ") or "(no arguments)"
				end)
				value = rendered and value or "<unreadable event arguments>"
				local room = math.min(1000, budget - bytes)
				if room < 32 then return end
				value = util.ellipsis(value, room)
				captured[#captured + 1] = value; bytes = bytes + #value + 8
			end)
		end)
		if not ok or not connection then return H.fail("could not connect to " .. label) end
		local stop = env.require("runtime/dispose").add(function() alive = false; connection:Disconnect() end, "tool signal observation")
		local started = clock.ms()
		local waited, problem = pcall(function()
			while alive and #captured < count and bytes < budget - 32 and clock.since(started) < seconds * 1000 and not aborted() do clock.wait(0.05) end
		end)
		local cancelled = not alive or aborted()
		stop()
		if not waited then return H.fail("observation failed: " .. tostring(problem)) end
		local elapsed = clock.since(started) / 1000
		return { ok = not cancelled, text = string.format("%s: %d event(s) in %.2fs%s\n%s", label, #captured, elapsed,
			cancelled and " (cancelled)" or bytes >= budget - 32 and " (result budget reached)" or "", H.list(captured, count)),
			data = { status = cancelled and "aborted" or "observed", count = #captured, elapsedSeconds = elapsed, limited = bytes >= budget - 32 } }
	end

	return H
end
end)()

-- ==========================================================================
-- tools/init
-- ==========================================================================
__UAI_MODULES["tools/init"] = (function()
-- Collects the tool groups.
--
-- Adding a group is one entry in GROUPS. Each group module returns a flat list of
-- tool definitions; the registry above turns them into a name map and the wire
-- format. A group that fails to load is skipped with a warning rather than taking
-- the client down -- a broken tool should cost one capability, not the session.
local GROUPS = {
	"agentself",
	"instance",
	"script",
	"coding",
	"fs",
	"obsidian",
	"net",
	"web",
	"players",
	"character",
	"world",
	"remotes",
	"net_capture",
	"evidence",
	"support_bundle",
	"gui",
	"perf",
	"meta",
	"chat",
	"input",
	"templates",
	"screen",
	"iy",
	"gravity",
	"skills",
}

return function(env)
	local log = env.require("runtime/log")

	local M = { groups = GROUPS }

	function M.all()
		local out = {}
		for _, group in ipairs(GROUPS) do
			local ok, tools = pcall(env.require, "tools/" .. group)
			if not ok then
				log.error("tools", "group '" .. group .. "' failed to load", tools)
			elseif type(tools) ~= "table" then
				log.warn("tools", "group '" .. group .. "' returned no tools")
			else
				for _, tool in ipairs(tools) do
					tool.group = tool.group or group
					out[#out + 1] = tool
				end
			end
		end
		return out
	end

	return M
end
end)()

-- ==========================================================================
-- tools/input
-- ==========================================================================
__UAI_MODULES["tools/input"] = (function()
-- Virtual input: keyboard and mouse simulation.
--
-- Supports VirtualInputManager (standard engine input injector), executor globals
-- (keypress, mouse1click, etc.) and VirtualUser as fallbacks.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")

	local KEY_ALIASES = {
		["0"] = "Zero",
		["1"] = "One",
		["2"] = "Two",
		["3"] = "Three",
		["4"] = "Four",
		["5"] = "Five",
		["6"] = "Six",
		["7"] = "Seven",
		["8"] = "Eight",
		["9"] = "Nine",
		enter = "Return",
		space = "Space",
		esc = "Escape",
		escape = "Escape",
		tab = "Tab",
		backspace = "Backspace",
		shift = "LeftShift",
		lshift = "LeftShift",
		rshift = "RightShift",
		ctrl = "LeftControl",
		control = "LeftControl",
		lctrl = "LeftControl",
		rctrl = "RightControl",
		alt = "LeftAlt",
		lalt = "LeftAlt",
		ralt = "RightAlt",
		up = "Up",
		down = "Down",
		left = "Left",
		right = "Right",
	}

	local validKeyCodes = nil
	local function getValidKeyCodes()
		if validKeyCodes then return validKeyCodes end
		validKeyCodes = {}
		local ok, items = pcall(function() return Enum.KeyCode:GetEnumItems() end)
		if ok and type(items) == "table" then
			for _, item in ipairs(items) do
				validKeyCodes[item.Name:lower()] = item
			end
		end
		return validKeyCodes
	end

	local function resolveKeyCode(rawName)
		local cleaned = util.trim(rawName or "")
		if cleaned == "" then return nil, "no key specified" end

		local lower = cleaned:lower()
		local targetName = KEY_ALIASES[lower] or cleaned

		local codes = getValidKeyCodes()
		if codes[targetName:lower()] then
			return codes[targetName:lower()]
		end

		if #cleaned == 1 then
			local upper = cleaned:upper()
			if codes[upper:lower()] then
				return codes[upper:lower()]
			end
		end

		return nil, "unrecognised KeyCode: '" .. cleaned .. "'"
	end

	local function getVim()
		local ok, vim = pcall(function() return game:GetService("VirtualInputManager") end)
		return (ok and vim) or nil
	end

	local function getVu()
		local ok, vu = pcall(function() return game:GetService("VirtualUser") end)
		return (ok and vu) or nil
	end

	local function getMousePos(customX, customY)
		local x = tonumber(customX)
		local y = tonumber(customY)
		if x and y then return x, y end

		if env.uis and env.uis.GetMouseLocation then
			local ok, loc = pcall(function() return env.uis:GetMouseLocation() end)
			if ok and loc then
				x = x or loc.X
				y = y or loc.Y
			end
		end

		if not x or not y then
			local camera = env.services.Workspace and env.services.Workspace.CurrentCamera
			if camera and camera.ViewportSize then
				x = x or math.floor(camera.ViewportSize.X / 2)
				y = y or math.floor(camera.ViewportSize.Y / 2)
			end
		end

		return x or 0, y or 0
	end

	local held, alive, watching = {}, true, false
	local function stopped(ctx)
		if not alive then return true end
		if not ctx or not ctx.aborted then return false end
		local ok, value = pcall(ctx.aborted)
		return not ok or value == true
	end
	local function release(entry)
		entry.releaseRequested = true
		if entry.released then return true end
		if entry.releasing then return false end
		entry.releasing = true
		while true do
			local beganPending = entry.pendingDown
			local ok, value = pcall(entry.route.up)
			-- Up itself can yield across the late down. Only an up dispatched
			-- after down completed can clear ownership; this repeats at most once.
			if not beganPending or entry.pendingDown then
				entry.releasing = false
				if ok and value ~= false then
					if entry.pendingDown then return true end
					entry.released = true
					if held[entry.id] == entry then held[entry.id] = nil end
					return true
				end
				return false
			end
		end
	end
	local function watch()
		if watching or not alive then return end
		watching = true
		clock.delay(0.1, function()
			if not alive then watching = false; return end
			for _, entry in pairs(held) do
				if not entry.cleanupAttempted then
					if stopped(entry.ctx) then
						entry.cleanupAttempted = true
						local owned = entry
						clock.spawn(function() release(owned) end)
					end
				end
			end
			watching = false
			for _, entry in pairs(held) do if not entry.cleanupAttempted then watch(); break end end
		end)
	end
	local function outcome(ok, text, route, id, status)
		return { ok = ok, text = text, data = { status = status, provider = route and route.name,
			held = held[id] ~= nil } }
	end
	-- A known false return allows another provider. An exception after entering
	-- input injection has an unknown outcome: release through that same provider
	-- and stop, rather than issuing a second key-down or click elsewhere.
	local function inject(id, action, duration, routes, ctx, label)
		if stopped(ctx) then return H.fail("input was cancelled before dispatch") end
		local prior = held[id]
		if prior then
			if prior.ctx and prior.ctx.session ~= (ctx and ctx.session) then return H.fail("this input is held by another conversation") end
			if action ~= "up" then return H.fail("this input is already held; release it before pressing again") end
			local ok = release(prior)
			local pending = ok and prior.pendingDown
			return outcome(ok, pending and (label .. ": release requested; native down is pending and will be released again")
				or (ok and (label .. ": released") or (label .. ": release failed; the input may still be held. Retry only an explicit up action.")),
				prior.route, id, pending and "release_pending" or (ok and "released" or "release_failed"))
		end
		if util.count(held) >= 32 and action ~= "up" then return H.fail("held-input limit reached; release existing inputs first") end
		for _, route in ipairs(routes) do
			if stopped(ctx) then return H.fail("input was cancelled before dispatch") end
			local prepared, accepted = true, true
			if route.prepare then prepared, accepted = pcall(route.prepare) end
			if prepared and accepted ~= false then
				if stopped(ctx) then return H.fail("input was cancelled before dispatch") end
				if held[id] then return H.fail("this input became owned by another pending action; no input was sent") end
				if action == "up" and route.up then
					local ok, value = pcall(route.up)
					if ok and value ~= false then return outcome(true, label .. ": released", route, id, "released") end
				elseif action ~= "up" and route.down and route.up then
					if util.count(held) >= 32 then return H.fail("held-input limit reached; release existing inputs first") end
					local entry = { id = id, route = route, ctx = ctx, pendingDown = true }
					held[id] = entry
					watch()
					local ok, value = pcall(route.down)
					entry.pendingDown = false
					if ok and value == false then
						if entry.releaseRequested then
							local released = release(entry)
							return outcome(false, label .. ": provider refused down after release was requested; "
								.. (released and "cleanup completed" or "cleanup remains pending or failed; retry only an explicit up action"),
								route, id, released and "cancelled" or (entry.releasing and "release_pending" or "release_failed"))
						end
						if held[id] == entry then held[id] = nil end
					elseif not ok then
						release(entry)
						return outcome(false, label .. ": input outcome unknown; release attempted through the same provider. Do not repeat the press or click.",
							route, id, "unknown")
					else
						if action == "down" and not stopped(ctx) and not entry.releaseRequested then return outcome(true, label .. ": held until up, cancellation or unload", route, id, "held") end
						local deadline = clock.ms() + duration * 1000
						while not stopped(ctx) and not entry.releaseRequested and clock.ms() < deadline do clock.wait(math.min(0.05, (deadline - clock.ms()) / 1000)) end
						local cancelled = stopped(ctx) or entry.releaseRequested == true
						local released = release(entry)
						if not released then
							return outcome(false, label .. ": down was sent but release failed; the input may still be held. Retry only an explicit up action.", route, id, "release_failed")
						end
						return outcome(not cancelled, label .. (cancelled and ": cancelled and released" or ": completed"),
							route, id, cancelled and "cancelled" or "completed")
					end
				elseif action ~= "down" and action ~= "up" and route.tap then
					local ok, value = pcall(route.tap)
					if not ok then return outcome(false, label .. ": input outcome unknown; do not repeat this action.", route, id, "unknown") end
					if value ~= false then return outcome(true, label .. ": completed", route, id, "completed") end
				end
			end
		end
		return H.fail("no input provider accepted this action; no accepted down or click was retried")
	end
	env.require("runtime/dispose").add(function()
		alive = false
		for _, entry in pairs(held) do
			local owned = entry
			clock.spawn(function() release(owned) end)
		end
	end, "owned virtual input")

	local function keyRoutes(keyCode)
		local routes, vim, vu = {}, getVim(), getVu()
		if vim and type(vim.SendKeyEvent) == "function" then
			routes[#routes + 1] = { name = "VirtualInputManager",
				down = function() return vim:SendKeyEvent(true, keyCode, false, game) end,
				up = function() return vim:SendKeyEvent(false, keyCode, false, game) end }
		end
		if type(keypress) == "function" and type(keyrelease) == "function" then
			local press, up = keypress, keyrelease
			routes[#routes + 1] = { name = "executor", down = function() return press(keyCode.Value) end, up = function() return up(keyCode.Value) end }
		end
		if vu and type(vu.SetKeyDown) == "function" and type(vu.SetKeyUp) == "function" then
			routes[#routes + 1] = { name = "VirtualUser", prepare = function() return vu:CaptureController() end,
				down = function() return vu:SetKeyDown(keyCode.Name) end, up = function() return vu:SetKeyUp(keyCode.Name) end }
		end
		return routes
	end

	local function mouseRoutes(button, action, x, y, positioned)
		local routes, vim, vu = {}, getVim(), getVu()
		local index = button == "right" and 1 or button == "middle" and 2 or 0
