-- tools/net
-- ==========================================================================
__UAI_MODULES["tools/net"] = (function()
-- HTTP from inside the agent: fetch a URL, call a JSON API.
--
-- These carry the Claude Code identity like every other request, because that is
-- the client's identity and there is no reason for a tool call to present a
-- different one. The web tools next door are the exception, and they say why.
return function(env)
	local util = env.require("runtime/util")
	local http = env.require("net/http")
	local H = env.require("tools/helpers")
	local N = env.require("tools/native_helpers").forGroup("net")

	local BODY_CAP = 5000

	local function headerTable(input)
		local out = {}
		for key, value in pairs(input or {}) do
			if type(key) == "string" and value ~= nil then out[key] = tostring(value) end
		end
		return out
	end
	local function timeout(args)
		return H.limit(args.timeout, 20, 120)
	end
	local function response(res, args)
		local body = tostring(res.body or "")
		local limit = math.min(H.limit(args.limit, BODY_CAP, 64000), math.max(128, H.resultBudget() - 480))
		local last = math.min(#body, limit)
		while last > 0 and body:byte(last + 1) and body:byte(last + 1) >= 128 and body:byte(last + 1) < 192 do last = last - 1 end
		local text, trimmed = body:sub(1, last), last < #body
		local data = { ok = res.ok == true, status = res.status, totalBytes = #body, truncated = trimmed == true }
		if trimmed then
			local key = N.retain({ body = body, status = res.status, ok = res.ok == true }, body, "net")
			data.resultId, data.readTool = key, key and "http_result_read" or nil
			data.detailsUnavailable = not key and "Response exceeded the retained-detail budget" or nil
			data.nextOffset = key and #text + 1 or nil
		end
		return { ok = data.ok, text = string.format("HTTP %s (%d bytes%s)\n%s", tostring(res.status), #body,
			data.resultId and "; use http_result_read section=text for the complete response" or trimmed and "; remaining response exceeded detail retention" or "", text), data = data }
	end

	local tools = {
		{
			name = "http_get",
			examples = { { title = "Read the published UI LIB guide", arguments = { url = "https://raw.githubusercontent.com/Project-Ptolemy/ProjectUAI/main/docs/UI_LIBRARY.md", limit = 4000 },
				note = "The offline ui_library_docs reference is usually faster; this example is an explicit network read." } },
			risk = "read",
			needs = { "http" },
			description = "GET a URL. HTTP errors fail the call. Large bodies retain a five-minute result reference for http_result_read without another request.",
			timeout = function(args) return timeout(args) + 1 end,
			parameters = {
				type = "object",
				properties = {
					url = { type = "string" },
					timeout = { type = "integer", minimum = 1, maximum = 120, description = "Total request deadline in seconds, default 20." },
					headers = { type = "object", description = "Extra request headers." },
					limit = { type = "integer", description = "Maximum UTF-8 body bytes in this page; bounded by result budget. Default 5000.", minimum = 200, maximum = 64000 },
				},
				required = { "url" },
			},
			run = function(args, ctx)
				local res, err = http.send({
					url = args.url,
					method = "GET",
					headers = headerTable(args.headers),
					attempts = 2,
					timeout = timeout(args), aborted = ctx and ctx.aborted,
					tag = "tool:http_get",
				})
				if not res then return H.fail(err) end
				return response(res, args)
			end,
		},
		{
			name = "http_request",
			risk = "write",
			needs = { "http" },
			description = "Send one HTTP request with method and body. Writes are never retried. HTTP errors fail the call; large responses remain readable through http_result_read.",
			timeout = function(args) return timeout(args) + 1 end,
			parameters = {
				type = "object",
				properties = {
					url = { type = "string" },
					method = { type = "string", enum = { "GET", "POST", "PUT", "PATCH", "DELETE", "HEAD" } },
					timeout = { type = "integer", minimum = 1, maximum = 120, description = "Total request deadline in seconds, default 20." },
					headers = { type = "object" },
					body = { type = "string", description = "Request body. JSON should be sent as a string." },
					limit = { type = "integer", minimum = 200, maximum = 64000 },
				},
				required = { "url", "method" },
			},
			run = function(args, ctx)
				local res, err = http.send({
					url = args.url,
					method = args.method,
					headers = headerTable(args.headers),
					body = args.body,
					attempts = 1,
					timeout = timeout(args), aborted = ctx and ctx.aborted,
					tag = "tool:http_request",
				})
				if not res then return H.fail(err) end
				return response(res, args)
			end,
		},
		{
			name = "json_api",
			risk = "read",
			needs = { "http" },
			description = "GET JSON and read a field by dotted path or exact keys (including keys containing dots). Large values retain a reference for http_result_read; false is a valid value and HTTP errors fail.",
			timeout = function(args) return timeout(args) + 1 end,
			parameters = {
				type = "object",
				properties = {
					url = { type = "string" },
					path = { type = "string", description = "Dotted path into the response. Array indexes are 1-based. Omit for the whole document." },
					keys = { type = "array", items = { type = "string" }, maxItems = 32, description = "Exact keys; array indexes as strings. Use instead of path for keys containing dots." },
					timeout = { type = "integer", minimum = 1, maximum = 120, description = "Total request deadline in seconds, default 20." },
					headers = { type = "object" },
				},
				required = { "url" },
			},
			run = function(args, ctx)
				if args.keys and args.path then return H.fail("use either keys or path, not both") end
				local decoded, err, res = http.json({
					url = args.url,
					method = "GET",
					headers = headerTable(args.headers),
					attempts = 2,
					timeout = timeout(args), aborted = ctx and ctx.aborted,
					tag = "tool:json_api",
				})
				if res and not res.ok then return response(res, args) end
				if decoded == nil then
					return H.fail(string.format("%s%s", tostring(err),
						res and (" (status " .. tostring(res.status) .. ")") or ""))
				end

				local target = decoded
				if args.keys or (args.path and util.trim(args.path) ~= "") then
					for _, part in ipairs(args.keys or util.split(args.path, ".")) do
						if type(target) ~= "table" then
							return H.fail("requested path does not exist in the response")
						end
						local value = target[part]
						if value == nil and tonumber(part) then value = target[tonumber(part)] end
						target = value
					end
					if target == nil then
						return H.fail("requested path is not present in the response")
					end
				end

				return N.result({ value = target, status = res and res.status }, "JSON response value")
			end,
		},
	}
	N.addReader(tools, "net")
	return tools
end
end)()

-- ==========================================================================
-- tools/net_capture
-- ==========================================================================
__UAI_MODULES["tools/net_capture"] = (function()
-- Network and payload capture: one lifecycle tool and one read tool.
--
-- The agent starts capture, runs the loader, then reads the recorded stages. It
-- never supplies hook code or a target function; the fixed hook set is chosen by
-- the runtime and reported in coverage.
return function(env)
	local capture = env.require("runtime/net_capture")
	local store = env.require("runtime/net_store")
	local util = env.require("runtime/util")
	local H = env.require("tools/helpers")
	local N = env.require("tools/native_helpers").forGroup("net_capture")
	local tools = {}

	local str = { type = "string" }
	local boolean = { type = "boolean" }
	local integer = { type = "integer", minimum = 1 }
	local hosts = { type = "array", items = str, maxItems = 16 }
	local methods = { type = "array", items = str, maxItems = 8 }
	local ids = { type = "array", items = str, maxItems = 100 }

	local watching
	local function watchRevocation()
		if watching then return end
		watching = true
		local registry = env.require("agent/registry")
		local permissions = env.require("agent/permissions")
		local config = env.require("runtime/config")
		local sessions = env.require("agent/session")
		local clock = env.require("runtime/clock")
		local previous = permissions.check({ name = "net_capture", risk = "write" })
		local alive = true
		local function check()
			local current = permissions.check({ name = "net_capture", risk = "write" })
			local state = capture.state()
			if state.status ~= "running" then previous = current; return end
			if not registry.groupEnabled("net_capture") or current == "deny" or (previous == "allow" and current ~= "allow") then
				capture.revokeAgent()
			else
				local owner = state.ownerSessionId
				if owner then
					local session = sessions.threads[owner]
					if not session or session.removed or session.abortFlag
						or (session.toolGroups and not session.toolGroups.net_capture)
						or (session.toolFilter and not session.toolFilter.net_capture)
						or (session.toolExclude and session.toolExclude.net_capture) then
						capture.revokeAgent(owner)
					end
				end
			end
			previous = current
		end
		local off = config.changed:connect(function(path)
			if path == nil or path == "agent" or path == "agent.disabledGroups" or tostring(path):match("^permissions") then check() end
		end)
		local offSession = sessions.anyEvent:connect(function(session, event) if event.kind == "abort" then capture.revokeAgent(session.id) end end)
		local offPermission = permissions.changed:connect(check)
		local function tick() if not alive then return end; check(); clock.delay(0.5, tick) end
		clock.delay(0.5, tick)
		env.require("runtime/dispose").add(function() alive = false; off(); offSession(); offPermission() end, "network capture authorization")
	end

	local function coverageSummary(state)
		local hooked, failed = 0, {}
		for _, target in ipairs(state.coverage.targets) do
			if target.state == "hooked" then hooked = hooked + 1
			elseif target.state == "failed" then failed[#failed + 1] = target.name .. ": " .. tostring(target.reason or "failed") end
		end
		local text = string.format("Capture %s: %d hook(s) active", state.status, hooked)
		if state.remaining then text = text .. string.format(", %.0fs left", state.remaining) end
		if #failed > 0 then text = text .. ". Failed: " .. table.concat(failed, "; ") end
		return text
	end

	local lifecycle = N.add(tools, "net_capture", "write",
		"Observe executor HTTP requests and executable chunks. Start before the target script runs, then use net_capture_read. Records method, URL (sensitive query values redacted), status, bounded request/response bodies, and loadstring/load/require source. UAI's own traffic is excluded. Stop restores hooks; a hook that cannot be restored is reported as retained and forwards without recording.",
		{
			action = { type = "string", enum = { "start", "stop", "status", "clear", "export" } },
			mode = { type = "string", enum = { "http", "chunks", "both" }, description = "Start only; default both." },
			host = hosts,
			method = methods,
			duration = { type = "number", minimum = 1, maximum = 300, description = "Seconds; default 120. Ignored when persistent=true." },
			persistent = boolean,
			destination = { type = "string", maxLength = 512 },
			record_ids = ids,
			session_id = str,
		}, { "action" }, function(args, ctx)
			if args.action == "start" then
				local data, why = capture.start({ mode = args.mode, host = args.host, method = args.method,
					duration = args.duration, persistent = args.persistent }, ctx)
				if not data then return N.fail(why) end
				watchRevocation()
				return N.result(data, coverageSummary(data) .. ". Run the loader now; UAI's own requests and compiles are not recorded.")
			elseif args.action == "stop" then
				local data, why = capture.stop("requested")
				if not data then return N.fail(why) end
				local retained, restored = 0, 0
				for _, target in ipairs(data.coverage.targets) do
					if target.state == "retained" then retained = retained + 1 end
					if target.state == "restored" then restored = restored + 1 end
				end
				return N.result(data, string.format("Capture stopped. %d record(s) retained; %d hook(s) restored%s.",
					data.retained or 0, restored, retained > 0 and (", " .. retained .. " retained and forwarding without recording") or ""))
			elseif args.action == "status" then
				local state = capture.state()
				return N.result(state, capture.coverageText())
			elseif args.action == "clear" then
				local state = capture.clear()
				return N.result(state, "Capture records cleared. The running capture, if any, continues.")
			elseif args.action == "export" then
				local data, why = capture.export({ record_ids = args.record_ids, destination = args.destination })
				if not data then return N.fail(why) end
				return N.result(data, string.format("Wrote %d capture record(s) to %s (%d bytes).",
					data.records or 0, tostring(data.path or "the workspace"), data.captureBytes or 0))
			end
			return N.fail("unknown action")
		end
	)
	lifecycle.risk = "write"
	lifecycle.needs = { "capture" }

	N.add(tools, "net_capture_read", "read",
		"Read captured network and payload records. list returns summaries with a continuation cursor; read pages one record's summary, URL, request, response, headers, chunk or module source; chain returns the HTTP -> chunk -> nested-request graph. Bodies and chunks are bounded; follow offsets. Payload bytes are never executed by this tool.",
		{
			action = { type = "string", enum = { "list", "read", "chain" } },
			kind = { type = "string", enum = { "http", "chunk", "module" } },
			host = str,
			method = str,
			url = str,
			status = { type = "integer", minimum = 100, maximum = 599 },
			suspected = boolean,
			after_sequence = { type = "integer", minimum = 0 },
			limit = { type = "integer", minimum = 1, maximum = 20 },
			record_id = str,
			section = { type = "string", enum = { "summary", "url", "request", "response", "headers", "chunk", "module" } },
			offset = integer,
			bytes = { type = "integer", minimum = 200, maximum = 64000, description = "Read page size; default 4000." },
			session_id = str,
		}, { "action" }, function(args, ctx)
			if args.action == "list" then
				local data = store.page(args)
				local lines = {}
				for index, item in ipairs(data.items) do
					if item.kind == "http" then
						lines[#lines + 1] = string.format("%d. #%d HTTP %s %s -> %s (%d B)%s [%s]",
							index, item.sequence, tostring(item.method or "GET"), tostring(item.url or ""),
							tostring(item.status or "?"), item.responseBytes or 0,
							item.suspectedCode and " code-like" or "", item.id)
					elseif item.kind == "module" then
						lines[#lines + 1] = string.format("%d. #%d MODULE %s (%s)%s [%s]", index, item.sequence,
							tostring(item.name or ""), tostring(item.sourceStatus or "unknown"),
							item.sourceBytes and (" " .. item.sourceBytes .. " B") or "", item.id)
					else
						lines[#lines + 1] = string.format("%d. #%d CHUNK %s (%d B%s)%s [%s]", index, item.sequence,
							tostring(item.name or "loadstring"), item.sourceBytes or 0,
							item.compileOk and "" or ", not compiled", item.link and (" · " .. item.link) or "", item.id)
					end
				end
				local text = #lines > 0 and table.concat(lines, "\n") or "No matching capture records."
				if data.nextCursor then text = text .. "\nnextCursor=" .. data.nextCursor end
				return N.result(data, text)
			elseif args.action == "read" then
				if not args.record_id then return N.fail("record_id is required for read") end
				local section = args.section or "summary"
				local page, why = store.read(args.record_id, section, args)
				if not page then return N.fail(why) end
				local result = H.readSlice(page.name, page.text, { offset = args.offset, limit = args.bytes }, 4000)
				result.data = result.data or {}
				result.data.recordId, result.data.section = page.id, section
				result.data.totalBytes, result.data.binary, result.data.truncated = page.totalBytes, page.binary, page.truncated
				result.data.record = page.record
				return result
			elseif args.action == "chain" then
				local data = store.chain(args)
				return N.result(data, data.text)
			end
			return N.fail("unknown action")
		end)

	env.require("tools/native_helpers").addReader(tools, "net_capture")
	return tools
end
end)()

-- ==========================================================================
-- tools/obsidian
-- ==========================================================================
__UAI_MODULES["tools/obsidian"] = (function()
-- Vault connections are user-owned; tools can only operate inside those roots.
return function(env)
	local util = env.require("runtime/util")
	local H = env.require("tools/helpers")
	local vault = env.require("runtime/obsidian")
	local transport = env.require("net/obsidian")
	local tools = {}
	local shared = { vault = { type = "string", description = "Stable vault id from obsidian_vaults." },
		path = { type = "string", description = "Exact vault-relative .md path, using forward slashes." },
		offset = { type = "integer", minimum = 1 }, limit = { type = "integer", minimum = 1, maximum = 100 } }
	local function request(input, ctx)
		return transport.request(input, { aborted = ctx and ctx.aborted })
	end
	local function add(name, action, description, properties, required, risk, reader)
		tools[#tools + 1] = { name = name, group = "obsidian", risk = risk or "read", needs = { "http" }, description = description,
			parameters = { type = "object", properties = properties, required = required }, run = function(args, ctx)
				local input = util.copy(args); input.action = action
				if input.path then local clean, why = vault.path(input.path); if not clean then return H.fail(why) end; input.path = clean end
				if input.folder then local clean, why = vault.path(input.folder, true); if not clean then return H.fail(why) end; input.folder = clean end
				if reader then return reader(input, ctx) end
				local value, why = request(input, ctx)
				if not value then return H.fail(why) end
				if value.data then local page, err = vault.page(value, H.resultBudget()); return page or H.fail(err) end
				return { text = util.encode(value), data = value }
			end }
	end
	add("obsidian_vaults", "vaults", "List the user's connected Obsidian vault ids, names, availability and read-only policy. Connect vault folders in Settings > Obsidian. These are files on the UAI Bridge computer, separate from executor workspace files.", { offset = shared.offset, limit = shared.limit }, {}, nil,
		function(input, ctx)
			local value, why = request(input, ctx); if not value then return H.fail(why) end
			if type(value.vaults) ~= "table" then return H.fail("The bridge returned an invalid vault list.") end
			return H.page(value.vaults, input, "Connected vaults", function(row) return util.encode(row) end)
		end)
	add("obsidian_list", "list", "List Markdown notes in a connected vault, optionally below a folder. Results paginate; preserve nextOffset. Hidden settings and linked folders are excluded; incomplete coverage is explicit.",
		{ vault = shared.vault, folder = { type = "string" }, offset = shared.offset, limit = shared.limit }, { "vault" })
	add("obsidian_search", "search", "Search note paths and content with literal case-insensitive text. Returns exact paths, matching line excerpts and revisions; paginate with nextOffset. Search is bounded and incomplete coverage is reported.",
		{ vault = shared.vault, query = { type = "string", minLength = 1, maxLength = 300 }, folder = { type = "string" }, offset = shared.offset, limit = shared.limit }, { "vault", "query" })
	add("obsidian_read", "read", "Read a UTF-8 note page and its SHA-256 revision. Preserve nextOffset and revision for later pages; a changed note rejects continuation. Use obsidian_metadata for headings, tags and frontmatter. Read before updating or appending.",
		{ vault = shared.vault, path = shared.path, offset = shared.offset, limit = { type = "integer", minimum = 4, maximum = 12000 }, revision = { type = "string" } }, { "vault", "path" }, nil,
		function(input, ctx)
			local available = H.resultBudget() - #input.path - 400
			if available < 4 then return H.fail("Increase the tool result budget before reading this note path.") end
			input.metadata = false; input.limit = math.min(input.limit or 6000, available)
			local value, why = request(input, ctx); if not value then return H.fail(why) end
			if type(value.content) ~= "string" or type(value.revision) ~= "string" then return H.fail("The bridge returned an invalid note page.") end
			local content = value.content; value.content = nil
			return { text = input.path .. "\nrevision=" .. value.revision .. "\n" .. content, data = value }
		end)
	add("obsidian_metadata", "read", "Read a note's title, headings, tags, wiki links and frontmatter. Frontmatter raw text is authoritative; parsed properties cover simple scalar values only. Code fences do not count as note links.",
		{ vault = shared.vault, path = shared.path }, { "vault", "path" }, nil,
		function(input, ctx)
			input.limit = 4
			local value, why = request(input, ctx); if not value then return H.fail(why) end
			local metadata = value.metadata or {}
			local entries = {}
			for _, key in ipairs({ "title", "frontmatter", "properties", "headings", "tags", "links", "limited" }) do entries[#entries + 1] = { field = key, value = metadata[key] } end
			local page, err = vault.page({ data = entries, total = #entries, offset = 1 }, H.resultBudget())
			if not page then return H.fail(err) end
			if page.data.nextOffset then return H.fail("This note's metadata exceeds the tool result budget. Read its text pages or increase Tool result limit.") end
			page.data.revision = value.revision; return page
		end)
	for _, operation in ipairs({ { "links", "List outgoing wiki and Markdown links with resolved exact note paths or ambiguity candidates. Resolution favors a note in the source folder, then a vault-relative path, then a unique basename." },
		{ "backlinks", "Find notes linking to this exact note path. Ambiguous basename links are not claimed as backlinks. Coverage and continuations are explicit." } }) do
		add("obsidian_" .. operation[1], operation[1], operation[2], { vault = shared.vault, path = shared.path, offset = shared.offset, limit = shared.limit }, { "vault", "path" })
	end
	local writeFields = { vault = shared.vault, path = shared.path, content = { type = "string", maxLength = vault.MAX_BYTES }, revision = { type = "string", minLength = 64, maxLength = 64 } }
	add("obsidian_create", "create", "Create a new Markdown note with parent folders. Never overwrites an existing note. Editing must be enabled by the user for this vault; content is limited to 1 MiB and verified after saving.", writeFields, { "vault", "path", "content" }, "write")
	add("obsidian_update", "update", "Replace note content using the exact revision returned by obsidian_read. A stale revision fails without changing the note. Preserve frontmatter and unrelated content. Editing must be enabled for the vault.", writeFields, { "vault", "path", "content", "revision" }, "write")
	add("obsidian_append", "append", "Append text using the exact current note revision. Include your own newline. A stale revision fails; maximum final note size is 1 MiB. Read the note before appending.", writeFields, { "vault", "path", "content", "revision" }, "write")
	return tools
end
end)()

-- ==========================================================================
-- tools/perf
-- ==========================================================================
__UAI_MODULES["tools/perf"] = (function()
-- Diagnostics: frame rate, memory, and what the place is actually made of.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local H = env.require("tools/helpers")
	local scan = env.require("runtime/instance_scan")

	return {
		{
			name = "performance",
			examples = { { title = "Sample current performance", arguments = { sample = 1 },
				note = "Compare equivalent samples before and after a change; one sample does not establish a long-term trend." } },
			risk = "read",
			description = "Measure frame rate over a short sample and report memory and network stats.",
			parameters = {
				type = "object",
				properties = {
					sample = { type = "number", description = "Seconds to sample the frame rate, 0.2-3. Default 1.", minimum = 0.2, maximum = 3 },
				},
				required = {},
			},
			run = function(args, ctx)
				local sample = util.clamp(tonumber(args.sample) or 1, 0.2, 3)
				local frames, elapsed, fastest, slowest, alive = 0, 0, math.huge, 0, true
				-- Counting Heartbeat deltas measures real frames rather than dividing
				-- by a clock read, which on a stuttering client reads very differently.
				local connection = env.run.Heartbeat:Connect(function(delta)
					if not alive or type(delta) ~= "number" or delta ~= delta or delta <= 0 or delta == math.huge then return end
					frames = frames + 1
					elapsed = elapsed + delta
					fastest, slowest = math.min(fastest, delta), math.max(slowest, delta)
				end)
				local release = env.require("runtime/dispose").add(function() alive = false; connection:Disconnect() end, "tool performance sample")
				local start = clock.ms()
				local waited, why = pcall(function()
					while alive and clock.since(start) < sample * 1000 and not (ctx and ctx.aborted and ctx.aborted()) do clock.wait(0.05) end
				end)
				local stopped = not alive or (ctx and ctx.aborted and ctx.aborted())
				release()
				if not waited then return H.fail("sampling failed: " .. tostring(why)) end
				if stopped then return { ok = false, text = "Performance sample cancelled; listener released.", data = { status = "aborted", frames = frames } } end

				local rows = {
					{ "FPS", elapsed > 0 and string.format("%.1f", frames / elapsed) or "unknown" },
					{ "Frames sampled", tostring(frames) },
					{ "Sample duration", string.format("%.3fs", elapsed) },
				}
				if frames > 0 then rows[#rows + 1] = { "Frame time", string.format("%.2fms average, %.2fms fastest, %.2fms slowest", elapsed * 1000 / frames, fastest * 1000, slowest * 1000) } end

				local stats = env.services.Stats
				local okMemory, memory = pcall(function() return stats:GetTotalMemoryUsageMb() end)
				if okMemory then rows[#rows + 1] = { "Memory", string.format("%.0f MB", memory) } end
				for _, field in ipairs({ "DataReceiveKbps", "DataSendKbps", "HeartbeatTimeMs", "PhysicsStepTimeMs", "InstanceCount" }) do
					local ok, value = pcall(function() return stats[field] end)
					if ok and type(value) == "number" then
						rows[#rows + 1] = { field, string.format("%.2f", value) }
					end
				end

				local okPing, ping = pcall(function()
					return stats.Network.ServerStatsItem["Data Ping"]:GetValue()
				end)
				if okPing and type(ping) == "number" then
					rows[#rows + 1] = { "Ping", string.format("%.0f ms", ping) }
				end

				return { text = H.keyValues(rows), data = { frames = frames, elapsedSeconds = elapsed, fps = frames > 0 and frames / elapsed or nil, minFrameMs = frames > 0 and fastest * 1000 or nil, maxFrameMs = frames > 0 and slowest * 1000 or nil } }
			end,
		},
		{
			name = "class_counts",
			risk = "read",
			description = "Count instances by class under a subtree. Good for sizing up an unfamiliar place before walking it.",
			parameters = {
				type = "object",
				properties = {
					root = { type = "string", description = "Where to count. Defaults to Workspace." },
					limit = { type = "integer", description = "Classes to list, 1-40. Default 20.", minimum = 1, maximum = 40 },
					offset = { type = "integer", minimum = 1 },
				},
				required = {},
			},
			run = function(args, ctx)
				local root, err = H.resolve(args.root or "Workspace")
				if not root then return H.fail(err) end

				local counts, total = {}, 0
				local scanned = scan.descendants(root, ctx, function(node)
					total = total + 1
					counts[node.ClassName] = (counts[node.ClassName] or 0) + 1
				end, 20000)
				local note = not scanned.complete and ("\nScan incomplete: " .. tostring(scanned.reason or "unreadable objects") .. ". Counts are lower bounds.") or ""

				local rows = {}
				for class, count in pairs(counts) do rows[#rows + 1] = { class = class, count = count } end
				table.sort(rows, function(a, b)
					if a.count ~= b.count then return a.count > b.count end
					return a.class < b.class
				end)

				if total == 0 then return H.pathOf(root) .. (scanned.complete and " is empty." or " has no readable counted descendants.") .. note end
				local result = H.page(rows, args, string.format("%s contains %s across %d classes.%s", H.pathOf(root), util.pluralise(total, "instance"), #rows, note), function(row)
						return string.format("%-28s %s", row.class, util.formatNumber(row.count))
					end, 20, 40)
				if result.data then result.data.complete, result.data.scanned = scanned.complete, scanned.scanned end
				if scanned.reason == "aborted" then result.ok = false end
				return result
			end,
		},
		{
			name = "client_status",
			risk = "read",
			description = "Report the agent's own state: provider, model, token spend this session, context size, host capabilities and how many tools are available.",
