		{ patch_id = str, path = str, section = { type = "string", enum = { "before", "after", "diff" } }, offset = { type = "integer", minimum = 1 }, limit = { type = "integer", minimum = 100, maximum = 6000 } }, { "patch_id" }, function(args, ctx)
