					entry.result = { ok = event.ok, text = event.summary or event.text or "", ms = event.ms,
						error = event.error, denied = event.denied }
					if entry.renderer then entry.renderer.finish(entry.result) end
				end
				lastStatus = string.format("%s %s", tostring(event.name or (entry and entry.event.name) or "Tool"), event.ok == false and "failed" or "complete")
				paint()
				return entry
			end
			function handle.finish(event)
				calls, finished = math.max(calls, tonumber(event.calls) or 0), math.max(finished, tonumber(event.finishedCalls) or 0)
				finalMs = tonumber(event.ms) or clock.since(started)
				if stop then stop(); stop = nil end
				head.state.Text = event.aborted and "Stopped" or (event.ok == false and "Failed" or "Done")
				head.state.TextColor3 = event.aborted and theme.color.warn or (event.ok == false and theme.color.danger or theme.color.success)
				head.tone(event.ok == false and (event.aborted and theme.color.warn or theme.color.dangerBorder) or nil)
				lastStatus = event.aborted and "Stopped before it finished" or (event.ok == false and "Task failed"
					or (failures > 0 and string.format("Reported back · %d failed tools", failures) or "Reported back"))
				for _, entry in pairs(rows) do if entry.renderer and not entry.result then entry.renderer.stale() end end
				local value = util.trim(tostring(event.text or ""))
				if value ~= "" then
					for _, child in ipairs(report:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
					report.Visible = true
					text(report, "ReportLabel", event.ok == false and "Outcome" or "Report", 1, "label", theme.color.textTertiary)
					local excerpt = text(report, "ReportText", util.ellipsis(value, 560), 2, "small", theme.color.text)
					if #value > 560 then
						local expanded = false
						P.button(report, { name = "ExpandReport", text = "Read full report", variant = "ghost", size = "sm", layoutOrder = 3,
							onClick = function(button)
								if opts.beforeToggle then opts.beforeToggle(button.instance) end
								expanded = not expanded
								excerpt.Text = expanded and value or util.ellipsis(value, 560)
								button.setText(expanded and "Show less" or "Read full report")
							end })
					end
				end
				paint()
			end
			function handle.stale()
				if stop then stop(); stop = nil end
				finalMs = finalMs or clock.since(started)
				head.state.Text, lastStatus = "Unavailable", "No report in the stored transcript."
				for _, entry in pairs(rows) do if entry.renderer and not entry.result then entry.renderer.stale() end end
				paint()
			end
			paint()
			return handle
		end
		return A
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/attachment_details
-- ==========================================================================
__UAI_MODULES["ui/chat/attachment_details"] = (function()
-- Inspect and remove draft attachments without opening or executing their files.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local summary = env.require("runtime/attachment_summary")
	local M = {}
	function M.open(entries, remove)
		local modal = overlay.modal({ title = "Draft attachments", description = "Removing an attachment keeps its original file.", width = theme.size.modalWide, scroll = true })
		if not modal then return nil end
		for index, entry in ipairs(entries) do
			local value = summary.describe(entry)
			local card = P.column(modal.content, { auto = "Y", gap = theme.space.xs, padding = theme.space.sm,
				bg = theme.color.surfaceRaised, radius = theme.radius.md, layoutOrder = index })
			P.text(card, { text = value.label, role = "label", wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 1 })
			P.text(card, { text = value.detail, role = "small", color = theme.color.textSecondary, wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 2 })
			if value.path then P.button(card, { text = "Copy path", variant = "ghost", size = "sm", layoutOrder = 3, onClick = function()
				local ok, why = env.require("runtime/clipboard").write(value.path); overlay.toast(ok and "Attachment path copied." or tostring(why), ok and "info" or "warn")
			end }) end
			P.button(card, { name = "RemoveDraftAttachment_" .. tostring(index), text = "Remove attachment", variant = "secondary", size = "sm", layoutOrder = 4,
				onClick = function() if remove(entry) then card:Destroy() end end })
		end
		P.button(modal.footer, { text = "Done", variant = "ghost", size = "sm", onClick = modal.close })
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/composer
-- ==========================================================================
__UAI_MODULES["ui/chat/composer"] = (function()
-- The composer: the scope chips, the prompt field, send/stop, and the meta row.
--
-- Send behaviour differs by platform on purpose. With a keyboard, Enter sends --
-- that is what everyone expects and reaching for a button breaks the typing rhythm.
-- On touch Enter always inserts a newline and only the button sends. Normal
-- typing keeps a compact row; explicit expansion gives a long draft more space.
--
-- Everything on the two rows around the field states something the client knows and
-- changes something when pressed. That is worth saying because it was not true: the
-- chips were a list of invented project and branch names, the permission chip
-- announced "Full Auto" while the agent was actually prompting for every write, and
-- the model name was a literal that no provider had ever reported.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local fsx = env.require("runtime/fsx")
	local attachments = env.require("runtime/attachments")
	local place = env.require("runtime/place")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local sessions = env.require("agent/session")
	local permissions = env.require("agent/permissions")
	local providers = env.require("provider/registry")
	local traits = env.require("provider/traits")

	local M = {}
	-- Live attachment identities survive layout rebuilds; bounded recovery snapshots
	-- are saved by the session alongside its existing conversation history.
	local drafts = {}
	local draftViews = {}
	local pendingSends = {}
	local function copyAttachments(list)
		local out = {}
		for index, entry in ipairs(list or {}) do out[index] = entry end
		return out
	end
	function M.hasDrafts()
		for id, draft in pairs(drafts) do
			if sessions.threads[id] and (util.trim(draft.text or "") ~= "" or #(draft.attachments or {}) > 0) then return true end
		end
		return false
	end

	function M.new(parent, props)
		props = props or {}
		local mobile = responsive.isMobile()
		local chipHeight = math.max(theme.size.chip, responsive.minTarget())

		local controlHeight = math.max(theme.size.control, responsive.minTarget())
		local inset = theme.space.sm
		local sideInset = theme.space.lg
		local topInset = theme.space.xxs
		local bottomInset = theme.space.sm
		local controlGap = theme.space.sm
		local resizeComposer
		local shell = P.frame(parent, {
			name = "Composer", size = UDim2.new(1, 0, 0, controlHeight + inset * 3 + theme.space.xxs),
			zIndex = theme.z.raised,
		})
		local composer = { expanded = false, busy = false, attachments = {} }
		local contextRequested, extraHeight = false, 0
		local draftId
		local restoring = false
		local destroyed = false
		local draftView
		local function alive() return not destroyed and shell.Parent ~= nil end
		composer.isAlive = alive
		local function saveDraft()
			if not destroyed and draftId and sessions.threads[draftId] and composer.field and not restoring then
				local previous = drafts[draftId] or {}
				local text = composer.field.get()
				drafts[draftId] = {
					text = text, attachments = copyAttachments(composer.attachments), expanded = composer.expanded,
					-- Rebuilds retain this version; real edits (even edit-away-and-back)
					-- advance it so a returning send cannot erase a newer question.
					textVersion = (previous.textVersion or 0) + (previous.text ~= text and 1 or 0),
				}
				local saved, why = sessions.threads[draftId].setDraft(drafts[draftId])
				if not saved and why ~= "Conversation is unavailable" and why ~= composer.draftWarning then overlay.toast(why, "warn", 5) end
				composer.draftWarning = why
			end
		end
		local surface = P.frame(shell, {
			name = "ComposerSurface", size = UDim2.new(1, -sideInset * 2, 0, controlHeight + inset * 2),
			position = UDim2.fromOffset(sideInset, topInset),
			bg = theme.color.surface, radius = theme.radius.lg,
		})
		local boxStroke = P.stroke(surface, theme.color.border)
		local sendButton
		local function syncSend()
			if alive() and sendButton then
				sendButton.setEnabled(not pendingSends[draftId] and (#composer.attachments > 0
					or (composer.field and util.trim(composer.field.get()) ~= "")))
			end
		end

		-- Scope chips ---------------------------------------------------------

		local scopeScroll = P.scroll(surface, {
			name = "ContextStrip",
			visible = false,
			horizontal = true,
			size = UDim2.new(1, 0, 0, math.max(theme.size.chip, responsive.minTarget()) + theme.size.scrollbar),
			gap = 0,
			layoutOrder = 1,
		})
		local scopeRow = P.row(scopeScroll.instance, {
			name = "ScopeRow",
			size = UDim2.new(0, 0, 0, math.max(theme.size.chip, responsive.minTarget())),
			auto = "X",
			gap = theme.space.xxs,
			layoutOrder = 2,
		})

		local scopeChips = {}
		local function chip(name, iconName, labelText, order, onClick)
			local handle = P.rowButton(scopeRow, {
				name = "Chip_" .. name,
				auto = "X",
				height = chipHeight,
				size = UDim2.fromOffset(0, chipHeight),
				bg = nil,
				radius = theme.radius.sm,
				gap = theme.space.xxs,
				padding = { x = theme.space.xs },
				layoutOrder = order,
				onClick = onClick,
			})
			handle.iconSlot = handle.icon(iconName, 1, theme.color.textTertiary, theme.size.icon - theme.space.hair)
			if labelText ~= nil then
				handle.text = P.text(handle.row, {
					name = "ChipLabel",
					text = util.ellipsis(labelText, 24),
					role = "caption",
					color = theme.color.textSecondary,
					auto = "X",
					layoutOrder = 2,
				})
			end
			scopeChips[#scopeChips + 1] = handle
			return handle
		end

		-- 1. What this client is running on. Not a choice -- it is the host -- so the
		-- menu is the capability report, which is the thing anyone clicking it wants.
		local runtimeLabel = caps.executor
		if runtimeLabel == "unknown" then
			runtimeLabel = caps.studio and "Studio" or "Client"
		end
		chip("runtime", "terminal", runtimeLabel, 1, function(handle)
			local options = {}
			local function fact(label, value, tone)
				options[#options + 1] = { label = label, value = tostring(value), detail = tostring(value), tone = tone }
			end
			fact("Transport", caps.http .. (caps.requestName and (" (" .. caps.requestName .. ")") or ""))
			fact("Claude Code identity", caps.uaSupported and "can be sent" or "cannot be sent here",
				caps.uaSupported and "good" or "warn")
			fact("Filesystem", caps.fs and "available" or "unavailable", caps.fs and "good" or "warn")
			fact("Code execution", caps.exec and "available" or "unavailable", caps.exec and "good" or "warn")
			fact("WebSocket", caps.ws and "available" or "unavailable")
			fact("Clipboard", caps.clipboard and "available" or "unavailable")
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if caps.clipboard then
						local ok, why = env.require("runtime/clipboard").write(tostring(value))
						overlay.toast(ok and "Copied" or why, ok and "good" or "warn", 1.5)
					else
						overlay.toast(tostring(value), "info", 3)
					end
				end,
			})
		end)

		-- 2. The place, which is this client's project: it is what the work is in and
		-- what the conversation list groups by.
		local placeChip = chip("place", "folder", place.label(), 2, function(handle)
			local options = {}
			for _, group in ipairs(sessions.groups()) do
				options[#options + 1] = {
					label = group.label,
					value = "place:" .. tostring(group.placeId),
					detail = util.pluralise(#group.sessions, "conversation"),
					selected = group.current,
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = { label = "Place details", value = "details", icon = "document", tone = "info" }
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if value == "details" then
						local facts = place.facts()
						overlay.menu({
							target = handle.instance,
							width = theme.size.menuWide,
							options = (function()
								local out = {}
								for _, entry in ipairs(facts) do
									out[#out + 1] = { label = entry.key, value = entry.value, detail = entry.value }
								end
								return out
							end)(),
							onSelect = function(fact)
								if caps.clipboard then
									local ok, why = env.require("runtime/clipboard").write(tostring(fact))
									overlay.toast(ok and "Copied" or why, ok and "good" or "warn", 1.5)
								else
									overlay.toast(tostring(fact), "info", 3)
								end
							end,
						})
					elseif util.startsWith(tostring(value), "place:") then
						local wanted = tostring(value):sub(7)
						for _, group in ipairs(sessions.groups()) do
							if tostring(group.placeId) == wanted and group.sessions[1] then
								env.require("ui/app").openSession(group.sessions[1].id)
							end
						end
					end
				end,
			})
		end)

		-- 3. The place version, which is the closest thing a running client has to a
		-- revision: it is what changes when the game is republished under you.
		if place.version > 0 then
			chip("version", "branch", "v" .. tostring(place.version), 3, function(handle)
				overlay.toast(place.describe(), "info", 3)
			end)
		end

		-- 4. Isolation. A conversation marked this way is never written to disk, which
		-- is the same reason a worktree exists: somewhere to try something without it
		-- becoming part of the history.
		local isolateChip
		local function paintIsolate()
			local session = sessions.current()
			local on = session.ephemeral == true
			isolateChip.instance.BackgroundColor3 = on and theme.color.accentSurface or theme.color.surface
			if isolateChip.text then
				isolateChip.text.Text = on and "isolated" or "worktree"
				isolateChip.text.TextColor3 = on and theme.color.accentHot or theme.color.textSecondary
			end
		end
		isolateChip = chip("isolate", "worktree", "worktree", 4, function()
			local session = sessions.current()
			local now = session.setEphemeral(not session.ephemeral)
			paintIsolate()
			overlay.toast(now
				and "This conversation will not be saved to disk."
				or "This conversation is saved again.", "info", 2.5)
		end)
		paintIsolate()

		-- 5. Attach. Real files from the client's own folder, and the memory it keeps.
		local attachRow, attachmentScroll
		local attachmentHandles = {}
		local function fitAttachments()
			if not alive() then return end
			local measuredWidth = attachmentScroll and attachmentScroll.viewportSize().X or 0
			local width = measuredWidth > 0 and measuredWidth
				or math.max(0, surface.AbsoluteSize.X - inset * 2 - theme.size.scrollbar)
			for _, item in ipairs(attachmentHandles) do
				local reserve = theme.space.xs * 2 + theme.space.xxs * 2
					+ item.leading.Size.X.Offset + item.close.Size.X.Offset
				local wanted = math.ceil(P.measureText(item.label.Text, { role = "caption" }).X) + reserve
				item.button.instance.Size = UDim2.fromOffset(math.min(width, math.max(chipHeight, wanted)), chipHeight)
			end
		end
		local function renderAttachments()
			if not alive() then return end
			for _, child in ipairs(attachRow:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			attachmentHandles = {}
			attachRow.Visible = #composer.attachments > 0
			for index, entry in ipairs(composer.attachments) do
				local handle = P.rowButton(attachRow, {
					name = "Attachment_" .. tostring(index),
					height = chipHeight,
					size = UDim2.fromOffset(chipHeight, chipHeight),
					bg = theme.color.surfaceRaised,
					radius = theme.radius.sm,
					gap = theme.space.xxs,
					padding = { x = theme.space.xs },
					layoutOrder = index,
					onClick = function()
						if not alive() then return end
						for position, attachment in ipairs(composer.attachments) do
							if attachment == entry then
								table.remove(composer.attachments, position)
								renderAttachments()
								break
							end
						end
					end,
				})
				local leading = handle.icon("document", 1, theme.color.accent, theme.size.icon - theme.space.hair)
				local label = P.text(handle.row, {
					text = entry.label,
					role = "caption",
					color = theme.color.textSecondary,
					size = UDim2.new(0, 0, 0, theme.text.caption.height),
					flex = "Fill",
					truncate = true,
					layoutOrder = 2,
				})
				local close = handle.icon("close", 3, theme.color.textTertiary, theme.size.icon - theme.space.xxs)
				-- The whole chip remains the removal target, including the close icon.
				attachmentHandles[#attachmentHandles + 1] = { button = handle, label = label, leading = leading, close = close }
			end
			fitAttachments()
			if resizeComposer then resizeComposer() end
			saveDraft()
			syncSend()
		end

		local function attachMenu(target)
			if not alive() then return end
			local options = {}
			-- The agent's workspace, which is where the model's own files live and where
			-- an attached note is expected to be.
			local files = fsx.enabled and fsx.list("", { scope = "files" }) or {}
			for _, entry in ipairs(files) do
				if not entry.isDir then
					options[#options + 1] = {
						label = entry.name,
						value = "file:" .. entry.path,
						detail = entry.path,
						icon = "document",
					}
				end
			end
			local state = env.require("agent/state")
			for _, entry in ipairs(state.memoryList()) do
				options[#options + 1] = {
					label = entry.key,
					value = "memory:" .. entry.key,
					detail = util.ellipsis(entry.value, 60),
					icon = "book",
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = { label = "A path in " .. fsx.root, value = "path", icon = "folder", tone = "info" }

			overlay.menu({
				target = target,
				width = theme.size.menuWide,
				options = options,
				onSelect = function(value)
					if not alive() then return end
					local function attachFile(path)
						if not alive() then return end
						local target, owner = draftId, sessions.threads[draftId]
						local function cancelled() return not alive() or not owner or owner.removed or draftId ~= target or sessions.threads[target] ~= owner end
						local body, err, resolved = fsx.readUser(path)
						if cancelled() then return end
						if not body then
							overlay.toast(tostring(err), "warn", 3)
							return
						end
						local entry, why = attachments.describe(resolved, body, path, cancelled)
						if cancelled() then return end
						if not entry then overlay.toast(tostring(why), "warn", 3); return end
						if #body <= attachments.INLINE_LIMIT then entry.file, entry.text = nil, body end
						composer.attachments[#composer.attachments + 1] = entry
						renderAttachments()
						syncSend()
					end
					if util.startsWith(tostring(value), "file:") then
						attachFile(tostring(value):sub(6))
					elseif util.startsWith(tostring(value), "memory:") then
						local key = tostring(value):sub(8)
						composer.attachments[#composer.attachments + 1] = {
							label = "memory/" .. key,
							text = tostring(state.recall(key) or ""),
						}
						renderAttachments()
					elseif value == "path" then
						overlay.prompt({
							title = "Attach a file",
							description = "A file inside " .. fsx.root .. "/files or pastes/. Long files are attached by reference.",
							placeholder = "notes/plan.txt",
							confirmText = "Attach",
							onConfirm = function(path)
								if util.trim(path) ~= "" then attachFile(util.trim(path)) end
							end,
						})
					end
				end,
			})
		end

		chip("attach", "document", nil, 5, function(handle)
			attachMenu(handle.instance)
		end)

		attachmentScroll = P.scroll(surface, { name = "AttachmentStrip",
			size = UDim2.new(1, 0, 0, chipHeight), visible = false, gap = 0 })
		attachRow = P.row(attachmentScroll.instance, {
			name = "Attachments",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			wrap = true,
			layoutOrder = 2,
		})
		attachRow.Visible = false

		-- The field ------------------------------------------------------------

		-- Explicit geometry avoids circular AutomaticSize/flex measurements.
		local inputHolder = P.frame(surface, {
			name = "InputHolder", size = UDim2.new(1, -inset * 2, 0, controlHeight),
			position = UDim2.fromOffset(inset, inset),
		})
		local inputRow = P.frame(inputHolder, {
			name = "InputRow", size = UDim2.fromScale(1, 1),
		})

		-- The existing mascot stays in the quiet context row, away from the caret.
		local mascotSize = theme.size.iconLarge
		local mascotSlot = P.frame(scopeRow, {
			name = "Mascot",
			size = UDim2.fromOffset(mascotSize, theme.size.chip),
			layoutOrder = 99,
		})
		local _, mascot = icons.mascot(mascotSlot, mascotSize, theme.color.accent)
		composer.mascot = mascot

		local fieldHolder = P.frame(inputRow, {
			name = "FieldHolder", size = UDim2.new(1, 0, 1, 0),
		})

		-- An attachment is context, so it travels ahead of the question in a block the
		-- model can tell from prose. It is dropped after the send: leaving it attached
		-- would silently re-send the same file with every following message.
		local function compose(text)
			if #composer.attachments == 0 then return text end
			local parts = {}
			for _, entry in ipairs(composer.attachments) do
				if entry.file then parts[#parts + 1] = attachments.reference(entry)
				else
					parts[#parts + 1] = string.format("<attached name=\"%s\">\n%s\n</attached>",
						tostring(entry.label), tostring(entry.text))
				end
			end
			parts[#parts + 1] = text ~= "" and text or "Please read the attached input."
			return table.concat(parts, "\n\n")
		end

		local function submit()
			if not alive() or not draftId or pendingSends[draftId] then return false end
			local id = draftId
			if not sessions.threads[id] or sessions.current().id ~= id then return false end
			local text = composer.field.get()
			if util.trim(text) == "" and #composer.attachments == 0 then return end
			local payload = compose(text)
			if not props.onSend then return false end
			saveDraft()
			local sent = drafts[id]
			pendingSends[id] = true
			syncSend()
			-- The callback may yield, switch conversations, or destroy and replace
			-- this composer before it returns. Settle against the session's draft.
			local files = {}
			for _, entry in ipairs(sent.attachments) do if entry.file then files[#files + 1] = entry end end
			local ok, accepted = pcall(props.onSend, payload, files)
			local live = draftViews[id]
			if live then live.capture() end
			if ok and accepted ~= false and sessions.threads[id] and drafts[id] then
				local current = drafts[id]
				local clearText = current.textVersion == sent.textVersion and current.text == sent.text
				local submitted, kept = {}, {}
				for _, entry in ipairs(sent.attachments) do submitted[entry] = true end
				for _, entry in ipairs(current.attachments) do
					if not submitted[entry] then kept[#kept + 1] = entry end
				end
				drafts[id] = {
					text = clearText and "" or current.text,
					textVersion = current.textVersion + (clearText and 1 or 0),
					attachments = kept,
					expanded = current.expanded and not (clearText and #kept == 0 and current.expanded == sent.expanded),
				}
				sessions.threads[id].setDraft(drafts[id])
				if live then live.restore() end
			end
			pendingSends[id] = nil
			if draftViews[id] then draftViews[id].sync() end
			if not ok then error(accepted, 0) end
			if accepted == false then return false end
			return true
		end

		-- Focus is the box lifting a step and taking the accent on its outline, not just
		-- the outline. On a dark ramp a hairline changing hue is easy to miss, and this is
		-- the one control in the app whose focus state has to be unmistakable -- the
		-- keyboard shortcut that opens quick chat is a printable character, so "is this
		-- focused" decides where the next keystroke goes.
		local function paintFocus(focused)
			if not alive() then return end
			P.animate(boxStroke, "hover", {
				Color = focused and theme.color.accent or theme.color.border,
				Thickness = focused and theme.stroke.focus or theme.stroke.hair,
			})
			P.animate(surface, "hover", {
				BackgroundColor3 = focused and theme.color.surfaceRaised or theme.color.surface,
			})
		end

		local function stackedInput()
			-- Preserve expansion as a preference while a short window or keyboard
			-- temporarily leaves room for only the shared compact row.
			return composer.expanded and parent.AbsoluteSize.Y >= extraHeight + controlHeight * 2
				+ inset * 2 + topInset + bottomInset + theme.space.xs + theme.text.body.height * 2
		end
		local function promptHeight()
			if stackedInput() then
				local wanted = math.max(theme.text.body.height * 2 + theme.space.md,
					math.min(theme.size.composerExpanded, responsive.viewport.Y * 0.25))
				local room = parent.AbsoluteSize.Y - extraHeight - controlHeight - theme.space.xs
					- inset * 2 - topInset - bottomInset - theme.text.body.height * 2
				return math.max(controlHeight, math.min(wanted, room))
			end
			return math.max(theme.size.control, theme.text.body.height, responsive.minTarget())
		end
		local function buildField(carried)
			local previousText = carried or ""
			return P.field(fieldHolder, {
				name = "Prompt",
				bare = true,
				placeholder = props.placeholder or "Message UAI…",
				multiline = mobile or composer.expanded,
				height = promptHeight(),
				text = carried,
				onFocus = function()
					paintFocus(true)
				end,
				onBlur = function()
					paintFocus(false)
				end,
				onChange = function(text)
					if not alive() or type(text) ~= "string" then return end
					syncSend()
					saveDraft()
					if restoring then previousText = text; return end
					local inserted, remainder = attachments.inserted(previousText, text)
					previousText = text
					if not inserted then return end
					local target = draftId
					local owner, version = sessions.threads[target], drafts[target] and drafts[target].textVersion
					local function cancelled()
						return not alive() or not owner or owner.removed or draftId ~= target or sessions.threads[target] ~= owner
							or composer.field.get() ~= text or not drafts[target] or drafts[target].textVersion ~= version
					end
					local entry, err = attachments.save(inserted, nil, cancelled)
					if cancelled() then return end
					if not entry then overlay.toast(tostring(err), "warn", 4); return end
					-- A yielding host must not clear a newer draft or another chat.
					if not alive() or draftId ~= target or composer.field.get() ~= text then return end
					composer.attachments[#composer.attachments + 1] = entry
					composer.field.set(remainder)
					renderAttachments()
					saveDraft()
					syncSend()
					overlay.toast("Attached " .. entry.name .. " · " .. tostring(entry.bytes) .. " bytes", "good", 3)
				end,
				onSubmit = function()
					if not mobile and not composer.expanded then submit() end
				end,
			})
		end
		composer.field = buildField(nil)

		local metaRow = P.frame(inputRow, { name = "Meta", size = UDim2.fromScale(1, 1) })
		sendButton = P.iconButton(metaRow, {
			name = "Send",
			icon = "send",
			variant = "primary",
			diameter = controlHeight,
			radius = theme.radius.lg,
			layoutOrder = 2,
			onClick = submit,
		})
		sendButton.instance.LayoutOrder = 2
		local stopButton = P.iconButton(metaRow, {
			name = "Stop", icon = "stop", variant = "danger", diameter = controlHeight,
			radius = theme.radius.lg,
			onClick = function() if props.onStop then props.onStop() end end,
		})
		stopButton.instance.Visible = false
		-- P.button creates its label from the initial text; queue updates reuse it.
		--
		-- The strip is tinted rather than ghosted because it is the one row above the
		-- prompt that is not part of the draft: it belongs to the running turn. The dot
		-- at the end carries the held state, which used to be a word in the label and
		-- disappeared the moment the count changed.
		local pendingButton = P.button(surface, {
			name = "PendingMessages", text = "Queued messages", variant = "ghost", size = "sm", fill = true,
			fillColor = theme.color.accentSurface, radius = theme.radius.md, align = "Left", padX = theme.space.sm,
			onClick = function()
				local session = sessions.threads[draftId]
				if session then env.require("ui/chat/queue").open(session) end
			end,
		})
		pendingButton.instance.Visible = false
		local pendingContent = pendingButton.instance:FindFirstChild("Content")
		P.spacer(pendingContent, { grow = true, layoutOrder = 3 })
		local pendingDot = P.statusDot(pendingContent, {
			diameter = theme.size.dot, color = theme.color.accent, layoutOrder = 4,
		})
		pendingDot.Name = "QueueState"
		local pendingPreview = P.text(surface, { name = "PendingPreview", text = "", role = "caption",
			color = theme.color.textSecondary, truncate = true, visible = false, size = UDim2.new(1, 0, 0, theme.size.chip) })

		local details = P.frame(shell, { name = "ComposerState", size = UDim2.fromOffset(0, 0), visible = false })
		local permissionLabel = P.text(scopeRow, { name = "PermissionLabel", text = "", role = "caption", auto = "X", layoutOrder = 6 })
		local statusLabel = P.text(details, { name = "Status", text = "", role = "caption", color = theme.color.textTertiary,
			size = UDim2.fromScale(1, 1), truncate = true })
		local plusButton = P.iconButton(metaRow, {
			name = "AddContext", icon = "plus", variant = "ghost", diameter = theme.size.chip,
			onClick = function(handle) attachMenu(handle.instance) end,
		})
		local modelChip = P.rowButton(metaRow, {
			name = "ModelChip", size = UDim2.fromOffset(theme.size.composerModel, chipHeight), height = chipHeight,
			radius = theme.radius.sm, gap = theme.space.xs, padding = { x = theme.space.xs },
			onClick = function(handle) M.providerMenu(handle.instance, composer) end,
		})
		local modelLabel = P.text(modelChip.row, {
			name = "ModelLabel", text = "", role = "caption", color = theme.color.textSecondary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height), flex = "Fill",
			truncate = true, layoutOrder = 2,
		})
		local effortLabel = P.text(scopeRow, { name = "EffortLabel", text = "", role = "caption", auto = "X", layoutOrder = 7 })
		local contextDot = P.statusDot(modelChip.row, {
			diameter = theme.size.dot, color = theme.color.textTertiary, layoutOrder = 1,
		})
		-- A live context-window counter beside the pressure dot: the share of the
		-- budget the next request is expected to spend, coloured like the dot.
		local contextLabel = P.text(modelChip.row, {
			name = "ContextPct", text = "", role = "caption", color = theme.color.textTertiary,
			auto = "X", size = UDim2.new(0, 0, 0, theme.text.caption.height), layoutOrder = 3,
		})
		modelChip.icon("chevron", 4, theme.color.textTertiary, theme.size.icon)
		local function promptMenu(target)
			local options = {}
			for _, entry in ipairs(env.require("ui/chat/prompts").items) do
				options[#options + 1] = { label = entry.label, detail = entry.detail, icon = entry.icon, value = entry.id }
			end
			overlay.menu({ target = target, width = theme.size.menuWide, options = options, onSelect = function(value)
				for _, entry in ipairs(env.require("ui/chat/prompts").items) do
					if entry.id == value then composer.insert(entry.text) end
				end
			end })
		end
		local moreButton = P.iconButton(metaRow, {
			name = "ComposerOptions", icon = "ellipsis", variant = "ghost", diameter = theme.size.chip,
			onClick = function(handle)
				local options = {
					{ label = "Find in conversation", detail = "Search messages, replies and errors", value = "search" },
					{ label = "Draft details", detail = env.require("runtime/text_metrics").label(composer.field.get()), value = "draft" },
					{ label = "Chat loops", detail = "Status, quiz scores, and stop controls", value = "loops", icon = "sliders" },
					{ label = "Prompt library", detail = "Explore, create, or diagnose", value = "prompts", icon = "spark" },
					{ label = "Model and effort", detail = modelLabel.Text, value = "model", icon = "spark" },
					{ label = "Permissions", detail = permissionLabel.Text, value = "permissions", icon = "sliders" },
					{ label = contextRequested and "Hide context details" or "Show context details", value = "context", icon = "folder" },
					{ label = "Context breakdown", detail = "What is filling the window", value = "context_inspect", icon = "folder" },
					{ label = composer.expanded and "Compact input" or "Expand input", value = "expand", icon = "code" },
				}
				if #composer.attachments > 0 then
					options[#options + 1] = { label = "Attachments", detail = util.pluralise(#composer.attachments, "attachment"),
						value = "attachments", icon = "document" }
				end
				if statusLabel.Text ~= "" then
					options[#options + 1] = { label = "Usage and status", detail = statusLabel.Text, value = "status" }
				end
				local convo = sessions.current()
				if props.onRefresh then
					options[#options + 1] = { label = "Refresh conversation", detail = "Redraw messages and live activity", value = "refresh", icon = "document" }
				end
				if convo and #(convo.ctx.messages or {}) > 0 then
					local rec = providers.active()
					local win = math.max(convo.ctx.limitFor(rec and rec.model, rec), 1)
					local pct = math.floor(util.clamp(convo.ctx.pressure(rec) / win, 0, 1) * 100 + 0.5)
					options[#options + 1] = { label = "Compact now",
						detail = string.format("Context about %d%% full -- summarise older turns", pct),
						value = "compact", icon = "sliders" }
				end
				options[#options + 1] = { divider = true }
				options[#options + 1] = { label = "Clear conversation", value = "clear", icon = "trash", tone = "bad" }
				overlay.menu({ target = handle.instance, title = "Message options", options = options, onSelect = function(value)
					if value == "search" then env.require("ui/chat/search").open(sessions.current())
					elseif value == "draft" then env.require("ui/chat/draft").open(composer, sessions.current())
					elseif value == "prompts" then promptMenu(handle.instance)
					elseif value == "attachments" then
						local owner = draftId
						env.require("ui/chat/attachment_details").open(copyAttachments(composer.attachments), function(wanted)
							if not alive() or draftId ~= owner then return false end
							for index, entry in ipairs(composer.attachments) do
								if entry == wanted then table.remove(composer.attachments, index); renderAttachments(); return true end
							end
							return false
						end)
					elseif value == "loops" then env.require("ui/chat/loops").open(handle.instance)
					elseif value == "model" then M.providerMenu(handle.instance, composer)
					elseif value == "permissions" then
						local modes = {}
						for _, mode in ipairs(permissions.MODES) do
							modes[#modes + 1] = { label = permissions.MODE_LABELS[mode] or mode, value = mode,
								detail = permissions.MODE_HINTS[mode], selected = permissions.mode() == mode,
								tone = mode == "full" and "warn" or nil }
						end
						overlay.menu({ target = handle.instance, options = modes, onSelect = function(mode)
							permissions.setMode(mode); composer.syncContext()
						end })
					elseif value == "context" then
						contextRequested = not contextRequested
						resizeComposer()
					elseif value == "context_inspect" then env.require("ui/chat/context").open(sessions.current())
					elseif value == "expand" then composer.setExpanded(not composer.expanded)
					elseif value == "status" then overlay.toast(statusLabel.Text, "info", 5)
					elseif value == "refresh" and props.onRefresh then props.onRefresh()
					elseif value == "compact" then
						local convo = sessions.current()
						local ok, err = convo.compact(function(done, summary, reason)
							if not alive() then return end
							composer.syncContext()
							overlay.toast(done and "Conversation compacted." or (reason or "Nothing to compact yet."),
								done and "info" or "warn", 4)
						end)
						if not ok then overlay.toast(err or "Could not compact right now.", "warn", 4) end
					elseif value == "clear" and props.onClear then props.onClear() end
				end })
			end,
		})
		local function fitLabels()
			if not alive() then return end
			local expanded = stackedInput()
			local width = math.max(surface.AbsoluteSize.X - inset * 2, 0)
			local left = chipHeight + theme.space.xs
			local stopWidth = composer.busy and controlHeight + controlGap or 0
			local right = controlHeight + chipHeight + controlGap * 2 + stopWidth
			-- Size to the actual label, not a permanent 144px slot around 'big-pickle'.
			local measured = math.max(P.measureText(modelLabel.Text, { role = "caption" }).X, modelLabel.TextBounds.X)
			local wanted = math.ceil(measured) + theme.size.dot + theme.size.icon
				+ math.ceil(contextLabel.TextBounds.X) + theme.space.xs * 5
			local available = width - left - right - (expanded and 0 or theme.size.composerFieldMin)
			local modelWidth = math.max(0, math.min(wanted, theme.size.composerModel, available))
			if modelWidth < math.min(wanted, theme.size.composerModelMin) then modelWidth = 0 end
			modelChip.instance.Visible = modelWidth > 0
			modelChip.instance.Size = UDim2.fromOffset(modelWidth, chipHeight)
			modelChip.instance.AnchorPoint = expanded and Vector2.new(0, 0.5) or Vector2.new(1, 0.5)
			modelChip.instance.Position = expanded and UDim2.new(0, left, 0.5, 0) or UDim2.new(1, -right, 0.5, 0)
			plusButton.instance.AnchorPoint = Vector2.new(0, 0.5)
			plusButton.instance.Position = UDim2.fromScale(0, 0.5)
			moreButton.instance.AnchorPoint = Vector2.new(1, 0.5)
			moreButton.instance.Position = UDim2.new(1, -(controlHeight + controlGap + stopWidth), 0.5, 0)
			sendButton.instance.AnchorPoint = Vector2.new(1, 0.5)
			sendButton.instance.Position = UDim2.fromScale(1, 0.5)
			stopButton.instance.AnchorPoint = Vector2.new(1, 0.5)
			stopButton.instance.Position = UDim2.new(1, -(controlHeight + controlGap), 0.5, 0)
			fieldHolder.Position = UDim2.fromOffset(expanded and 0 or left, 0)
			fieldHolder.Size = UDim2.new(1, expanded and 0
				or -(left + right + (modelWidth > 0 and modelWidth + theme.space.sm or 0)), 0, promptHeight())
		end
		local resizing = false
		resizeComposer = function()
			if not alive() or resizing then return end
			resizing = true
			local top = inset
			local room = parent.AbsoluteSize.Y
			if pendingButton.instance.Visible then
				pendingButton.instance.Position = UDim2.fromOffset(inset, top)
				pendingButton.instance.Size = UDim2.new(1, -inset * 2, 0, chipHeight)
				top = top + chipHeight + theme.space.xxs
			end
			pendingPreview.Visible = pendingButton.instance.Visible and room >= controlHeight * 5
			if pendingPreview.Visible then
				local height = theme.text.caption.height + theme.space.xxs
				pendingPreview.Position = UDim2.fromOffset(inset + theme.space.xs, top)
				pendingPreview.Size = UDim2.new(1, -inset * 2 - theme.space.xs * 2, 0, height)
				top = top + height + theme.space.xs
			end
			-- Extra context yields to the typing row when any window is short.
			-- Attachments also remain removable from Message options.
			scopeScroll.instance.Visible = contextRequested and room >= controlHeight * 4 + theme.space.lg
			attachmentScroll.instance.Visible = attachRow.Visible and room >= controlHeight * 3 + theme.space.lg
			if scopeScroll.instance.Visible then
				scopeScroll.instance.Position = UDim2.fromOffset(inset, top)
				scopeScroll.instance.Size = UDim2.new(1, -inset * 2, 0, chipHeight + theme.size.scrollbar)
				top = top + chipHeight + theme.size.scrollbar + inset
			end
			if attachmentScroll.instance.Visible then
				local attachmentHeight = math.min(math.max(attachRow.AbsoluteSize.Y, chipHeight),
					math.max(chipHeight, math.floor(room * 0.25)))
				attachmentScroll.instance.Position = UDim2.fromOffset(inset, top)
				attachmentScroll.instance.Size = UDim2.new(1, -inset * 2, 0, attachmentHeight)
				top = top + attachmentHeight + inset
			end
			extraHeight = top - inset
			local fieldHeight = promptHeight()
			local expanded = stackedInput()
			inputHolder.Position = UDim2.fromOffset(inset, top)
			local inputHeight = fieldHeight + (expanded and controlHeight + theme.space.xs or 0)
			inputHolder.Size = UDim2.new(1, -inset * 2, 0, inputHeight)
			composer.field.shell.Size = UDim2.new(1, 0, 0, fieldHeight)
			metaRow.Position = UDim2.fromOffset(0, expanded and fieldHeight + theme.space.xs or 0)
			metaRow.Size = UDim2.new(1, 0, 0, controlHeight)
			local surfaceHeight = top + inputHeight + inset
			surface.Size = UDim2.new(1, -sideInset * 2, 0, surfaceHeight)
			shell.Size = UDim2.new(1, 0, 0, surfaceHeight + topInset + bottomInset)
			fitLabels()
			fitAttachments()
			resizing = false
		end
		surface:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			fitLabels()
			fitAttachments()
		end)
		modelLabel:GetPropertyChangedSignal("TextBounds"):Connect(fitLabels)
		attachRow:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() resizeComposer() end)
		local parentSizeConnection = parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() resizeComposer() end)

		-- Everything on the meta row, from the real records ---------------------

		function composer.syncContext()
			if not alive() then return end
			local shortModes = { ask = "Ask first", auto = "Auto", full = "Allow everything" }
			permissionLabel.Text = shortModes[permissions.mode()] or permissions.MODE_LABELS[permissions.mode()] or permissions.mode()
			permissionLabel.TextColor3 = permissions.mode() == "full"
				and theme.color.warn or theme.color.textSecondary

			local record = providers.active()
			if not record then
				modelLabel.Text = "Choose provider"
				modelLabel.TextColor3 = theme.color.warn
				effortLabel.Text = ""
			else
				local model = util.trim(tostring(record.model or ""))
				if model == "" then
					modelLabel.Text = "Choose model"
					modelLabel.TextColor3 = theme.color.warn
				else
					modelLabel.Text = model
					modelLabel.TextColor3 = theme.color.textSecondary
				end
				-- The effort actually sent, which is the setting clamped to what this
				-- model offers -- "Max" on a model whose scale stops at high is high, and
				-- saying Max would be reporting the setting rather than the request. A
				-- model marked by hand as a reasoner has no documented scale to clamp
				-- against, so the setting is the request exactly as it stands.
				local wanted = tostring(config.get("agent.effort", "high"))
				local levels = traits.effortLevels(model)
				local sending = wanted
				if levels then sending = traits.nearestEffort(model, wanted) or wanted end
				if levels == nil and model ~= "" and not traits.thinkingStyle(model) then
					effortLabel.Text = ""
				else
					effortLabel.Text = (sending:gsub("^%l", string.upper))
				end
			end

			-- Context pressure, from the conversation the composer is attached to,
			-- measured against the budget compaction actually uses: a fraction of the
			-- model's window when it is known, otherwise the configured cap.
			local session = sessions.current()
			local budget = math.max(session.ctx.limitFor(record and record.model, record), 1)
			local share = util.clamp(session.ctx.pressure(record) / budget, 0, 1)
			composer.contextShare = share
			local tone = theme.color.success
			if share > 0.85 then
				tone = theme.color.danger
			elseif share > 0.6 then
				tone = theme.color.warn
			end
			contextDot.BackgroundColor3 = tone
			local hasModel = record and util.trim(tostring(record.model or "")) ~= ""
			contextLabel.Text = hasModel and (math.floor(share * 100 + 0.5) .. "%") or ""
			contextLabel.TextColor3 = tone
			if not hasModel then
				contextDot.BackgroundColor3 = theme.color.warn
			end
			fitLabels()
		end

		-- Rebuilding the field is the honest way to switch MultiLine: changing the
		-- property on a live TextBox leaves its alignment and height wrong.
		function composer.setExpanded(value, keepFocus)
			if not alive() then return end
			composer.expanded = value == true
			if mobile then
				if keepFocus ~= false then composer.field.focus() end
				resizeComposer(); syncSend(); saveDraft()
				return
			end
			paintFocus(false)
			local carried = composer.field.get()
			pcall(function() composer.field.shell:Destroy() end)
			composer.field = buildField(carried)
			if keepFocus ~= false then composer.field.focus() end
			resizeComposer()
			syncSend()
			saveDraft()
		end

		function composer.insert(text)
			if not alive() then return end
			local previous = composer.field.get()
			composer.field.set(previous == "" and text or (previous .. "\n\n" .. text))
			if previous ~= "" or tostring(text):find("\n") then composer.setExpanded(true) end
			composer.focus()
		end

		local function restoreDraft()
			if not alive() then return end
			restoring = true
			local draft = drafts[draftId] or {}
			composer.attachments = copyAttachments(draft.attachments)
			composer.field.set(draft.text or "")
			if composer.expanded ~= (draft.expanded == true) then composer.setExpanded(draft.expanded == true, false) end
			renderAttachments()
			restoring = false
			syncSend()
		end
		draftView = { capture = saveDraft, restore = restoreDraft, sync = syncSend }
		function composer.attach(session)
			if not alive() or not session or draftId == session.id then return end
			saveDraft()
			if draftId and draftViews[draftId] == draftView then draftViews[draftId] = nil end
			draftId = session.id
			if not drafts[draftId] and session.draft then
				drafts[draftId] = env.require("runtime/draft_store").restore(session.draft)
				if drafts[draftId] then drafts[draftId].textVersion = 0 end
			end
			draftViews[draftId] = draftView
			restoreDraft()
			composer.syncQueue()
		end

		function composer.syncQueue()
			if not alive() then return end
			local session = sessions.threads[draftId]
			local pending = session and session.queueSnapshot()
			local count = pending and pending.count or 0
			pendingButton.instance.Visible = count > 0
			pendingButton.setText(tostring(count) .. (pending and pending.held and " waiting \194\183 Review or resume" or " queued \194\183 Review"))
			pendingDot.BackgroundColor3 = pending and pending.held and theme.color.warn or theme.color.accent
			local first = pending and pending.items and pending.items[1]
			pendingPreview.Text = first and ((first.state == "preparing" and "Preparing: " or "Up next: ")
				.. util.ellipsis((first.text or "Attached input"):gsub("%s+", " "), 220)) or ""
			pendingPreview.TextColor3 = pending and pending.held and theme.color.warn or theme.color.textSecondary
			resizeComposer()
		end

		function composer.setBusy(value)
			if not alive() then return end
			composer.busy = value == true
			if composer.mascot then pcall(composer.mascot.setBusy, composer.busy) end
			stopButton.instance.Visible = composer.busy
			composer.field.instance.PlaceholderText = composer.busy and "Queue a follow-up…"
				or props.placeholder or "Message UAI…"
			resizeComposer()
			syncSend()
		end

		function composer.setStatus(text)
			if not alive() then return end
			statusLabel.Text = tostring(text or "")
			statusLabel.TextColor3 = theme.color.accentHot
		end

		-- The running token line, which is a setting rather than progress: it is the one
		-- thing on this row that is about cost, and not everyone wants it in front of
		-- them. Kept separate from setStatus so turning it off cannot also hide "Working
		-- (step 3)".
		function composer.setUsage(text)
			if not alive() then return end
			statusLabel.TextColor3 = theme.color.textTertiary
			if config.get("ui.showUsage", true) ~= true then
				statusLabel.Text = ""
				return
			end
			statusLabel.Text = tostring(text or "")
		end

		function composer.focus()
			if alive() then composer.field.focus() end
		end

		-- Keep model and permission controls usable when the keyboard reduces height.
		local unsubscribeResponsive = responsive.changed:connect(function()
			if not alive() then return end
			chipHeight = math.max(theme.size.chip, responsive.minTarget())
			controlHeight = math.max(theme.size.control, responsive.minTarget())
			plusButton.instance.Size = UDim2.fromOffset(chipHeight, chipHeight)
			moreButton.instance.Size = UDim2.fromOffset(chipHeight, chipHeight)
			sendButton.instance.Size = UDim2.fromOffset(controlHeight, controlHeight)
			stopButton.instance.Size = UDim2.fromOffset(controlHeight, controlHeight)
			scopeRow.Size = UDim2.fromOffset(0, chipHeight)
			mascotSlot.Size = UDim2.fromOffset(mascotSize, chipHeight)
			for _, handle in ipairs(scopeChips) do
				handle.instance.Size = UDim2.fromOffset(0, chipHeight)
				handle.row.Size = UDim2.fromOffset(0, chipHeight)
			end
			resizeComposer()
		end)
		resizeComposer()

		-- The chips are a view of state that other surfaces change: the permission mode
		-- from a menu, the model from the Providers panel, the place name when it
		-- resolves.
		local unsubscribeProviders = providers.changed:connect(function()
			if not metaRow.Parent then return end
			composer.syncContext()
		end)
		local unsubscribePermissions = permissions.changed:connect(function()
			if not metaRow.Parent then return end
			composer.syncContext()
		end)
		local unsubscribeConfig = config.changed:connect(function(path)
			if path == nil or path == "agent" or path == "agent.effort"
				or path == "agent.forceReasoning" or path == "agent.forceContext"
				or path == "agent.contextTokens" or path == "agent.contextFraction" then
				composer.syncContext()
			end
		end)
		local unsubscribePlace = place.changed:connect(function()
			if not scopeRow.Parent then return end
			if placeChip.text then placeChip.text.Text = util.ellipsis(place.label(), 24) end
		end)
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not scopeRow.Parent then return end
			for id in pairs(drafts) do
				if not sessions.threads[id] then drafts[id] = nil; draftViews[id] = nil end
			end
			paintIsolate()
		end)
		shell.Destroying:Connect(function()
			saveDraft()
			destroyed = true
			parentSizeConnection:Disconnect()
			if draftId and draftViews[draftId] == draftView then draftViews[draftId] = nil end
			pcall(unsubscribeResponsive)
			pcall(unsubscribeProviders)
			pcall(unsubscribePermissions)
			pcall(unsubscribeConfig)
			pcall(unsubscribePlace)
			pcall(unsubscribeSessions)
		end)

		composer.shell = shell
		composer.attach(sessions.current())
		composer.setBusy(false)
		composer.syncContext()
		return composer
	end

	-- Picks the endpoint, the model on it, and the effort it is asked for. All three
	-- live behind the same chip because they are one decision from the user's point of
	-- view -- and behind ui/panels/modelpicker rather than an anchored menu, because a
	-- menu is the right shape for six rows and this list is as long as the endpoint's
	-- catalogue. `target` is unused now and kept in the signature: it is what an
	-- anchored menu needed, and the chip still passes it.
	function M.providerMenu(target, composer)
		return env.require("ui/panels/modelpicker").open(function()
			if composer and composer.isAlive() then composer.syncContext() end
		end)
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/context
-- ==========================================================================
__UAI_MODULES["ui/chat/context"] = (function()
-- A live view of the next request, using the same estimates as compaction.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local providers = env.require("provider/registry")
	local sessions = env.require("agent/session")
	local traits = env.require("provider/traits")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local overlay = env.require("ui/overlay")
	local M = {}

	function M.open(session)
		if not session then return nil end
		local unsubscribes, pending, closed = {}, false, false
		local function cleanup()
			closed = true
			for _, unsubscribe in ipairs(unsubscribes) do unsubscribe() end
			unsubscribes = {}
		end
		local modal = overlay.modal({
			title = "Context usage",
			description = "What the next request will include",
			width = theme.size.modalWide,
			onClose = cleanup,
		})
		if not modal then return nil end
		modal.card.Name = "ContextInspector"
		local total = P.text(modal.content, {
			name = "ContextTotal", text = "", role = "bodyStrong", wrap = true, auto = "Y", layoutOrder = 1,
		})
		local pressure = P.text(modal.content, {
			name = "ContextPressure", text = "", role = "small", wrap = true, auto = "Y", layoutOrder = 2,
		})
		local chart = P.frame(modal.content, {
			name = "ContextBar", size = UDim2.new(1, 0, 0, theme.size.knob),
			bg = theme.color.contextUnused, radius = theme.radius.sm, clip = true, layoutOrder = 3,
		})
		local categories = {
			{ id = "system", label = "System prompt + tool schemas", color = theme.color.contextSystem },
			{ id = "messages", label = "Messages", color = theme.color.contextMessages },
			{ id = "summary", label = "Rolling summary", color = theme.color.contextSummary },
			{ id = "unused", label = "Unused context", color = theme.color.contextUnused },
		}
		local valueWidth = math.max(theme.size.keyColumn, P.measureText("1,000,000 tokens", { role = "caption" }).X)
		for index, category in ipairs(categories) do
			if category.id ~= "unused" then
				category.segment = P.frame(chart, {
					name = "ContextSegment_" .. category.id, size = UDim2.fromScale(0, 1), bg = category.color,
				})
			end
			local row = P.row(modal.content, {
				name = "ContextCategory_" .. category.id, size = UDim2.new(1, 0, 0, 0), auto = "Y",
				gap = theme.space.sm, alignY = "Top", layoutOrder = 4 + index,
			})
			local swatch = P.frame(row, {
				size = UDim2.fromOffset(theme.size.dot, theme.text.small.size), layoutOrder = 1,
			})
			P.statusDot(swatch, { color = category.color, diameter = theme.size.dot,
				anchor = Vector2.new(0.5, 0.5), position = UDim2.fromScale(0.5, 0.5) })
			category.labelNode = P.text(row, {
				name = "ContextLabel_" .. category.id, text = category.label, role = "small", wrap = true, auto = "Y",
				size = UDim2.new(1, -(valueWidth + theme.size.dot + theme.space.sm * 2), 0, 0), layoutOrder = 2,
			})
			category.valueNode = P.text(row, {
				name = "ContextValue_" .. category.id, text = "", role = "caption", color = theme.color.textSecondary,
				align = "Right", wrap = true, auto = "Y", size = UDim2.new(0, valueWidth, 0, 0), layoutOrder = 3,
			})
		end
		local marker = P.frame(chart, {
			name = "CompactionMarker", size = UDim2.new(0, theme.stroke.focus, 1, 0),
			anchor = Vector2.new(1, 0), bg = theme.color.text, zIndex = chart.ZIndex + 1,
		})
		local scaleLabel = P.text(modal.content, {
			name = "ContextScale", text = "", role = "caption", color = theme.color.textSecondary,
			wrap = true, auto = "Y", layoutOrder = 4,
		})
		P.divider(modal.content, { layoutOrder = 9 })
		local limits = P.text(modal.content, {
			name = "ContextLimits", text = "", role = "small", wrap = true, auto = "Y", layoutOrder = 10,
		})
		local estimates = P.text(modal.content, {
			name = "ContextEstimates", text = "", role = "caption", color = theme.color.textSecondary,
			wrap = true, auto = "Y", layoutOrder = 11,
		})
		P.divider(modal.content, { layoutOrder = 12 })
		local requests = P.text(modal.content, {
			name = "ConversationRequestTotal", text = "", role = "label", wrap = true, auto = "Y", layoutOrder = 13,
		})
		P.text(modal.content, { name = "ConversationRequestHint",
			text = "AI calls in this conversation, including retries, tool follow-ups, summaries and subagents. Counted on this device from this update; earlier requests are not reconstructed.",
			role = "caption", color = theme.color.textSecondary, wrap = true, auto = "Y", layoutOrder = 14 })

		local function tokens(value) return util.formatNumber(value) .. " tokens" end
		local function refresh()
			if closed or modal.closed then return end
			if session.removed then modal.close(); return end
			local recorded = sessions.conversationUsage(session)
			requests.Text = "This conversation: " .. util.formatNumber(recorded.requests) .. (recorded.requests == 1 and " AI request" or " AI requests")
			local ctx, record = session.ctx, providers.active()
			local model = record and record.model
			local window = traits.contextWindow(model, record)
			local compactAt = math.max(ctx.limitFor(model, record), 1)
			local scale = math.max(window or compactAt, 1)
			local values = ctx.breakdown(record)
			local used = values.used
			values.unused = math.max(0, scale - used)
			local partial = not values.calibrated and not values.estimatedPrompt
			total.Text = (partial and "Stored context: about " or "Next request: about ") .. tokens(used)
			pressure.Text = string.format("%d%% of the compaction point", math.floor(used / compactAt * 100 + 0.5))
			pressure.TextColor3 = used >= compactAt and theme.color.warn or theme.color.textSecondary
			local offset = 0
			for _, category in ipairs(categories) do
				local count = values[category.id]
				category.valueNode.Text = tokens(count) .. string.format("\n%.1f%%", count / scale * 100)
				if category.id == "system" and partial then
					category.valueNode.Text = "After first request"
				elseif category.id == "unused" then
					category.labelNode.Text = window and "Unused context" or "Until compaction"
				end
				if category.segment then
					local share = math.min(count / scale, math.max(0, 1 - offset))
					category.segment.Position = UDim2.fromScale(offset, 0)
					category.segment.Size = UDim2.fromScale(share, 1)
					category.segment.Visible = share > 0
					offset = offset + share
				end
			end
			marker.Position = UDim2.fromScale(math.min(compactAt / scale, 1), 0)
			scaleLabel.Text = window and "Full bar = model window. White marker = compaction point."
				or "Model window unknown. Full bar = compaction point."
			limits.Text = "Compaction point: " .. tokens(compactAt) .. "\nModel window: "
				.. (window and tokens(window) or "unknown; learned automatically from a context-length error")
			if model and model ~= "" then limits.Text = limits.Text .. "\nModel: " .. util.ellipsis(model, 120) end
			if used > scale then limits.Text = limits.Text .. "\nOver " .. (window and "model window" or "compaction point") .. " by " .. tokens(used - scale) end
			estimates.Text = "Message and summary counts are estimates. "
				.. (values.calibrated and "System prompt and tool schemas are calibrated from this provider's last reply."
					or values.estimatedPrompt and "System prompt and tool schemas are estimated from the last prepared request."
					or "System prompt and tool schemas are counted when the first request is prepared; totals are partial until then.")
		end
		local function queue()
			if pending or closed or modal.closed then return end
			pending = true
			clock.delay(0.1, function() pending = false; refresh() end)
		end
		refresh()
		unsubscribes[#unsubscribes + 1] = session.events:connect(queue)
		unsubscribes[#unsubscribes + 1] = config.changed:connect(queue)
		unsubscribes[#unsubscribes + 1] = providers.changed:connect(queue)
		unsubscribes[#unsubscribes + 1] = sessions.listChanged:connect(queue)
		unsubscribes[#unsubscribes + 1] = sessions.usageChanged:connect(queue)
		modal.scrim.Destroying:Connect(cleanup)
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/draft
-- ==========================================================================
__UAI_MODULES["ui/chat/draft"] = (function()
-- Recovery status and deliberate draft actions, independent of provider requests.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local M = {}
	function M.open(composer, session)
		if not composer or not composer.isAlive() or not session then return nil end
		local text = composer.field.get()
		local label, metrics = env.require("runtime/text_metrics").label(text)
		local modal = overlay.modal({ title = "Draft details", width = theme.size.modal })
		if not modal then return nil end
		P.text(modal.content, { text = label .. " / " .. tostring(metrics.lines) .. " lines", role = "label",
			wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 1 })
		local status = session.ephemeral and "This conversation is not saved. Its draft lasts until the client closes."
			or not env.require("runtime/fsx").enabled and "File storage is unavailable. Copy this draft before closing."
			or session.draftError or "Draft recovery saves with this conversation after typing pauses. Attached files are checked again when sent."
		P.text(modal.content, { name = "DraftRecovery", text = status, role = "small", color = theme.color.textSecondary,
			wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 2 })
		P.button(modal.footer, { text = "Close", variant = "ghost", size = "sm", layoutOrder = 1, onClick = modal.close })
		P.button(modal.footer, { name = "CopyDraft", text = "Copy text", variant = "secondary", size = "sm", layoutOrder = 2,
			onClick = function()
				local ok, why = env.require("runtime/clipboard").write(text)
				overlay.toast(ok and "Draft text copied." or tostring(why), ok and "info" or "warn")
			end })
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/loops
-- ==========================================================================
__UAI_MODULES["ui/chat/loops"] = (function()
-- One compact, global indicator; details and per-job stops live behind its label.
return function(env)
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local overlay = env.require("ui/overlay")
	local loops = env.require("runtime/chatloops")
	local M = {}
	local function kind(job) return job.kind == "agent" and "Chat agent" or job.kind end
	function M.open(target)
		local options = {}
		for _, job in ipairs(loops.list()) do
			local score = {}
			for _, entry in pairs(job.scores) do score[#score + 1] = entry.name .. " " .. entry.points end
			options[#options + 1] = { label = kind(job) .. " · " .. job.channel .. " · " .. job.state, value = job.id,
				detail = string.format("%d/%d · %s%s", job.completed, job.count, job.session.title or "Chat",
					#score > 0 and (" · " .. table.concat(score, ", ")) or (job.reason and (" · " .. job.reason) or "")) }
		end
		if #options == 0 then options[1] = { label = "No chat loops yet", detail = "Ask UAI to start a chat agent, quiz, or auto-chat.", value = "empty" } end
		overlay.menu({ target = target, width = theme.size.menuWide, options = options, onSelect = function(id)
			if id ~= "empty" then
				local stopped = loops.stop(id)
				overlay.toast(stopped > 0 and "Chat loop stopped" or "This loop has already finished", "info", 2)
			end
		end })
	end
	function M.new(parent)
		local height = math.max(theme.size.controlSmall, responsive.minTarget())
		local shell = P.frame(parent, { name = "ChatLoops", size = UDim2.new(1, 0, 0, height), visible = false })
		local label = P.button(shell, { name = "LoopDetails", text = "Chat loops", fill = true, align = "Left", variant = "ghost", size = "sm",
			onClick = function(button) M.open(button.instance) end })
		label.instance.Size = UDim2.new(1, -theme.size.metaColumnWide, 0, height)
		P.button(shell, { name = "StopChatLoops", text = "Stop all", width = theme.size.metaColumnWide,
			position = UDim2.new(1, -theme.size.metaColumnWide, 0, 0), variant = "ghost", size = "sm",
			onClick = function() loops.stop() end })
		local function refresh()
			local active = loops.running()
			shell.Visible = #active > 0
			label.setText(#active == 1 and (kind(active[1]) .. " · " .. active[1].completed .. "/" .. active[1].count .. " · " .. active[1].channel)
				or (#active .. " chat loops running"))
		end
		local unsubscribe = loops.changed:connect(refresh)
		shell.Destroying:Connect(unsubscribe)
		refresh()
		return { shell = shell }
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/message
-- ==========================================================================
__UAI_MODULES["ui/chat/message"] = (function()
-- Transcript message renderers.
--
-- Each kind of thing that can appear in a conversation gets its own builder, and
-- each returns a handle so the view can update it later -- a tool call is created
-- when the model asks for it and completed when the result arrives, which means the
-- row has to be mutable rather than a one-shot render.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local markdown = env.require("ui/markdown")
	local tableBlock = env.require("ui/chat/table")
	local icons = env.require("ui/icons")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local usage = env.require("agent/usage")
	local deadlineHelp = env.require("ui/deadline_help")

	-- How many lines of a block are shown before it folds. Generous, because the point
	-- of showing code at all is that it can be read; the fold is for a thousand-line
	-- file, not for a function.
	--
	-- A tool call's listing gets a much tighter one. Sixty lines of Luau between two
	-- paragraphs is the single largest thing in a transcript, and the model writes one
	-- of those per call: a turn that ran four scripts pushed the answer it was working
	-- towards several screens down. Twelve lines is enough to recognise what the call
	-- is doing, and "Show all N lines" is on the block.
	local CODE_LINES = 24
	local ARG_PREVIEW = 90
	local MOBILE_THOUGHT_BYTES, MOBILE_THOUGHT_RICH_BYTES = 8192, 32768

	-- Average glyph advance for the mono families, as a fraction of the font size.
	-- Used only to size the line-number gutter, which has to be wide enough for the
	-- largest number in the block and is the one width here that cannot come from a
	-- token: it depends on how many lines the block has.
	local MONO_RATIO = 0.62

	local M = {}

	-- Every row spans the reading column.
	--
	-- It used to leave a gutter -- 0.76 of the width for the user, 0.94 for the agent,
	-- the user's turn anchored to the right edge -- which is the chat-app convention of
	-- two speakers facing each other. This is not that: a turn here is a document with
	-- the questions marked in it, so both sides take the full measure and the
	-- difference between them is a fill, not a side. The column itself is what bounds
	-- the line length, and the panel caps that.
	local function wrapper(parent, props)
		return P.frame(parent, {
			name = props.name or "Message",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = props.layoutOrder or 0,
		})
	end

	-- Shared disclosure states keep keyboard, pointer and touch feedback consistent.
	local function disclosure(header, stroke)
		local hovered, focused, pressed = false, false, false
		header.BorderSizePixel = 0
		header.Active = true
		header.BackgroundTransparency = 1
		stroke.Transparency = 1
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		local tone
		local function paint()
			local active = hovered or focused or pressed
			P.animate(header, pressed and "press" or "hover", {
				BackgroundColor3 = pressed and theme.color.surfaceActive or theme.color.surfaceHover,
				BackgroundTransparency = active and 0 or 1,
			})
			P.animate(stroke, "hover", {
				Color = focused and theme.color.accent or tone or theme.color.borderSubtle,
				Transparency = (focused or tone) and 0 or 1,
			})
		end
		header.MouseEnter:Connect(function() hovered = true; paint() end)
		header.MouseLeave:Connect(function() hovered = false; pressed = false; paint() end)
		header.MouseButton1Down:Connect(function() pressed = true; paint() end)
		header.MouseButton1Up:Connect(function() pressed = false; paint() end)
		header.SelectionGained:Connect(function() focused = true; paint() end)
		header.SelectionLost:Connect(function() focused = false; pressed = false; paint() end)
		return function(value) tone = value; paint() end
	end

	-- A left rule beside a column of wrapped text.
	--
	-- The obvious construction is a row holding a 2px frame sized (0, 2, 1, 0) and a
	-- filling label beside it. That is circular and it does not work: the row is
	-- AutomaticSize.Y, so its height comes from its children, and one of those children
	-- asks for one hundred percent of that height. Roblox excludes scale-sized children
	-- from the measurement, but the UIListLayout's flex pass has already run against an
	-- unsettled height -- which inflates the row and can leave the filling label with no
	-- width at all, so a long message renders as a tall empty box with a coral line down
	-- the side of it.
	--
	-- The holder here has no UIListLayout. The rule is positioned rather than laid out,
	-- nothing measures it, and the text sits in an ordinary column with an explicit
	-- width. Callers get the column.
	local function ruled(parent, props)
		local holder = P.frame(parent, {
			name = props.name or "Ruled",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = props.layoutOrder,
			bg = props.bg,
			radius = props.radius,
			clip = props.clip,
		})
		if props.strokeColor then P.stroke(holder, props.strokeColor) end
		local width = props.width or theme.stroke.hair
		local body = P.column(holder, {
			name = "Body",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = props.gap or theme.space.xs,
			padding = {
				left = width + (props.inset or theme.space.md),
				right = props.padRight or 0,
				top = props.padY or 0,
				bottom = props.padY or 0,
			},
		})
		P.frame(holder, {
			name = "Rule",
			size = UDim2.new(0, width, 1, 0),
			position = UDim2.new(0, props.ruleAt or 0, 0, 0),
			bg = props.color or theme.color.borderSubtle,
			radius = props.ruleRadius,
			zIndex = 2,
		})
		return body, holder
	end

	-- Code: monospace below the surface of the page, with the language, a line-number
	-- gutter, a copy control and horizontal scrolling.
	--
	-- Three things changed here and each was a real loss of information. Lines wrapped,
	-- so a Luau line past the reading column folded and the indentation of everything
	-- after it read as wrong; there were no line numbers, so an error naming line 40 had
	-- nothing to point at; and anything past the fold was replaced by a dead sentence
	-- saying how much had been hidden, with no way to see it. Code is now what the model
	-- actually wrote, scrolled rather than reflowed, and the fold opens.
	function M.codeBlock(parent, props)
		local caps = env.require("runtime/caps")
		local lines = util.lines(props.text)
		if #lines == 0 then lines = { "" } end
		local numbered = props.numbers ~= false
		local role = theme.textRole("mono")
		-- Looser than the rest of the mono text, and the one number in here that both
		-- labels and the row height have to agree on: the gutter is a separate label
		-- from the code, so a line height that is not shared puts number 11 beside line
		-- 9. Everything below reads `codeLine`; nothing recomputes it from the role.
		local codeLine = theme.line.code
		local lineHeight = math.ceil(role.size * codeLine)
		-- Air inside the block, on all four sides, and one number per axis.
		--
		-- It used to be neither. The vertical inset was a token here and the horizontal
		-- one was an accident of two other measurements: the left came out of the gutter's
		-- own width, which baked twelve pixels of margin into a column sized for digits,
		-- and the right came from padding on the scroll viewport. So the two edges never
		-- agreed with each other, the language bar above them agreed with neither, and a
		-- block with no gutter -- a result, a raw JSON envelope -- had its first character
		-- sitting on the border. Both axes are one padding on the body row now, the bar
		-- shares the horizontal one, and the gutter is only as wide as its digits plus the
		-- gap to the code.
		local padY = theme.space.md
		local padX = theme.space.lg

		local card = P.column(parent, {
			name = "Code",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			gap = 0,
			layoutOrder = props.layoutOrder,
			clip = true,
		})
		P.stroke(card, theme.color.codeBorder)

		local bar = P.row(card, {
			name = "Bar",
			-- Match the actual copy button height, including the hit-target minimum.
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget())),
			bg = theme.color.codeBar,
			gap = theme.space.xs,
			-- The same left inset the gutter gets, so the language names the column of code
			-- underneath it rather than floating four pixels to the left of it. The right is
			-- tighter because what sits there is a round ghost button with its own padding,
			-- and padX again would push it off the block's corner.
			padding = { left = padX, right = theme.space.xs },
			layoutOrder = 1,
		})
		local language = P.text(bar, {
			name = "Language",
			text = (props.label and (props.label .. " · ") or "")
				.. (props.lang and props.lang:lower() or "code") .. (props.unterminated and " (incomplete)" or ""),
			role = "caption",
			color = theme.color.codeGutter,
			-- Fill the space left by the actual copy button width.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		-- What is in the block, on the right of its own bar. A line count is the one
		-- fact about a block of code that is worth reading before the code itself.
		local meta = P.text(bar, {
			name = "Meta",
			text = props.meta or util.pluralise(#lines, "line"),
			role = "caption",
			color = theme.color.codeGutter,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})

		local copy
		if caps.clipboard then
			copy = P.button(bar, {
				name = "Copy",
				icon = "copy",
				text = "Copy",
				size = "sm",
				tight = true,
				variant = "code",
				iconColor = theme.color.codeGutter,
				layoutOrder = 3,
				onClick = function(handle)
					local ok, copied = pcall(caps.fn.clipboard, props.text)
					ok = ok and copied ~= false
					handle.setText(ok and "Copied" or "Retry")
					if not ok then env.require("ui/overlay").toast("Could not copy this code", "bad", 3) end
					clock.delay(2, function()
						if handle.instance.Parent then handle.setText("Copy") end
					end)
				end,
			})
			copy.instance.LayoutOrder = 3
		end
		local function fitBar()
			local copyWidth = copy and math.max(copy.instance.AbsoluteSize.X, responsive.minTarget()) or 0
			local wanted = math.min(theme.size.keyColumn, P.measureText(language.Text, { role = "caption" }).X)
				+ P.measureText(meta.Text, { role = "caption" }).X + copyWidth + padX + theme.space.xs * 3
			meta.Visible = bar.AbsoluteSize.X >= wanted
		end
		bar:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitBar)
		if copy then copy.instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitBar) end
		fitBar()

		-- Body. The gutter is outside the scroll so it stays put while the code moves,
		-- which is the whole reason a sticky gutter is worth the extra frame.
		local bodyScroll = { instance = P.frame(card, {
			name = "CodeScroll",
			size = UDim2.new(1, 0, 0, 0),
			gap = 0,
			bg = theme.color.codeSurface,
			layoutOrder = 2,
		}) }
		local bodyRow = P.row(bodyScroll.instance, {
			name = "Body",
			size = UDim2.new(1, 0, 0, 0),
			gap = 0,
			alignY = "Top",
			padding = { left = padX, right = padX, top = padY, bottom = padY },
			layoutOrder = 2,
		})

		local gutter, gutterLabel
		local gutterWidth = 0
		if numbered then
			-- Wide enough for the largest number in this block, plus the gap to the code
			-- beside it. It is the one width in here that cannot come from a token, because
			-- it depends on how many lines there are; the ratio is what keeps it in step
			-- with the text scale, and the gap is a token because it is a gap.
			gutterWidth = math.ceil(#tostring(#lines) * role.size * MONO_RATIO) + theme.space.md
			gutter = P.frame(bodyRow, {
				name = "Gutter",
				clip = true,
				size = UDim2.fromOffset(gutterWidth, 0),
				layoutOrder = 1,
			})
			gutterLabel = P.text(gutter, {
				name = "Numbers",
				text = "",
				role = "mono",
				line = codeLine,
				color = theme.color.codeGutter,
				align = "Right",
				alignY = "Top",
				size = UDim2.new(1, -theme.space.md, 1, 0),
			})
		end

		local viewport = P.scroll(bodyRow, {
			name = "Viewport",
			horizontal = true,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			gap = 0,
			bar = theme.size.scrollbar,
		})
		viewport.instance.ScrollingDirection = Enum.ScrollingDirection.XY
		viewport.instance.AutomaticCanvasSize = Enum.AutomaticSize.XY
		viewport.instance.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		viewport.instance:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			if gutterLabel then
				gutterLabel.Position = UDim2.fromOffset(0, -viewport.instance.CanvasPosition.Y)
			end
		end)
		-- Not wrapped, and sized from the text: that is what makes the gutter line up
		-- with the code beside it. A wrapped body puts two visual lines against one
		-- number, and every number below it is then wrong.
		local body = P.text(viewport.instance, {
			name = "Source",
			text = "",
			rich = true,
			role = "mono",
			line = codeLine,
			color = theme.color.codeText,
			alignY = "Top",
			size = UDim2.new(0, 0, 1, 0),
			auto = "X",
		})

		local expanded = props.expanded == true
		local foldRow
		-- Where this block folds. A reply's code gets the generous default; a tool
		-- call's listing passes its own, because there are several of them per turn.
		local foldAt = math.max(tonumber(props.maxLines) or CODE_LINES, 1)

		local function paint()
			local shown = lines
			if not expanded and #lines > foldAt then
				shown = util.slice(lines, 1, foldAt)
			end
			body.Text = markdown.highlight(table.concat(shown, "\n"), props.lang)
			if gutterLabel then
				local numbers = {}
				for index = 1, #shown do numbers[index] = tostring(index) end
				gutterLabel.Text = table.concat(numbers, "\n")
			end
			local height = #shown * lineHeight
			local fullHeight = height + padY * 2 + theme.size.scrollbar
			local mobile = responsive.isMobile()
			local room = mobile and responsive.usableRect(env.root, 0).height or responsive.viewport.Y
			local minHeight = lineHeight * 4
			local capHeight = math.max(minHeight,
				math.min(theme.size.codeViewport, room * 0.45))
			local visibleHeight = math.min(fullHeight, capHeight)
			bodyRow.Size = UDim2.new(1, 0, 0, visibleHeight)
			bodyScroll.instance.Size = UDim2.new(1, 0, 0, visibleHeight)
			viewport.instance.Size = UDim2.new(0, 0, 0, visibleHeight - padY * 2)
			body.Size = UDim2.fromOffset(0, height + theme.size.scrollbar)
			if gutter then
				gutter.Size = UDim2.fromOffset(gutterWidth, visibleHeight - padY * 2 - theme.size.scrollbar)
				gutterLabel.Size = UDim2.new(1, -theme.space.md, 0, height)
			end
			if foldRow then
				foldRow.setText(expanded
					and "Show less"
					or string.format("Show all %s", util.pluralise(#lines, "line")))
			end
		end

		if #lines > foldAt then
			foldRow = P.button(card, {
				name = "Fold",
				-- Given its text up front, because P.button only builds a label when it
				-- has one to put in it -- an empty string leaves setText with nothing to
				-- write to.
				text = string.format("Show all %s", util.pluralise(#lines, "line")),
				variant = "code",
				size = "sm",
				fill = true,
				align = "Left",
				-- Starts where the code above it starts. On the button's own default inset
				-- the control read as belonging to the card's edge rather than to the
				-- listing it opens.
				padX = padX,
				radius = theme.radius.none,
				layoutOrder = 3,
				onClick = function()
					expanded = not expanded
					viewport.instance.CanvasPosition = Vector2.new(0, 0)
					paint()
				end,
			})
			foldRow.instance.LayoutOrder = 3
		end

		paint()
		local disconnect = responsive.changed:connect(paint)
		card.Destroying:Connect(disconnect)
		return card
	end

	-- Renders markdown blocks into an existing column. Returned so a streaming or
	-- edited message can clear and re-render.
	local function renderBlocks(column, text, supplied, first)
		local blocks = supplied or markdown.blocks(text)
		if #blocks == 0 then
			P.text(column, { text = "", role = "body", wrap = true, auto = "Y" })
			return
		end

		for position, block in ipairs(blocks) do
			local index = position + (first or 1) - 1
			if block.kind == "code" then
				-- The Markdown column owns the gap around every block. Extra padding
				-- here doubles up between adjacent fences and leaves blank leading or
				-- trailing space on a reply containing only code.
				local slot = P.column(column, {
					name = "CodeSlot",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = 0,
					layoutOrder = index,
				})
				M.codeBlock(slot, {
					text = block.text,
					lang = block.lang,
					unterminated = block.unterminated,
					layoutOrder = 1,
				})
			elseif block.kind == "table" then
				tableBlock.render(column, { block = block, layoutOrder = index })
			elseif block.kind == "heading" then
				-- A heading belongs to what is under it, so it needs more air above than
				-- the uniform paragraph gap gives it. Without this a section title sits
				-- exactly as far from the paragraph it introduces as from the one it ends,
				-- and a long reply reads as an undifferentiated run of text.
				local head = P.column(column, {
					name = "Heading",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = 0,
					padding = index > 1 and { top = theme.space.sm } or nil,
					layoutOrder = index,
				})
				local label = P.text(head, {
					text = markdown.inline(block.text),
					role = block.level == 1 and "title" or "heading",
					rich = true,
					wrap = true,
					auto = "Y",
				})
				label.Size = UDim2.new(1, 0, 0, 0)
			elseif block.kind == "rule" then
				P.divider(column, { layoutOrder = index })
			elseif block.kind == "quote" then
				local body = ruled(column, {
					name = "Quote",
					layoutOrder = index,
					color = theme.color.accent,
					width = theme.stroke.focus,
					bg = theme.color.surface,
					radius = theme.radius.sm,
					ruleRadius = theme.radius.xs,
					padY = theme.space.xs,
					padRight = theme.space.sm,
					inset = theme.space.sm,
					clip = true,
				})
				local quoted = P.text(body, {
					text = markdown.inline(block.text),
					role = "body",
					color = theme.color.textSecondary,
					rich = true,
					wrap = true,
					auto = "Y",
				})
				quoted.Size = UDim2.new(1, 0, 0, 0)
			elseif block.kind == "bullets" then
				local list = P.column(column, {
					name = "List",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xxs,
					layoutOrder = index,
				})
				-- One marker column for the whole list, wide enough for its longest
				-- marker, so "9." and "10." put their text at the same x.
				local markerWidth = theme.space.md
				for _, item in ipairs(block.items) do
					if item.marker then
						markerWidth = math.max(markerWidth,
							math.ceil(#item.marker * theme.text.body.size * MONO_RATIO))
					end
				end
				-- The marker is text, in the same role and on the same line height as the
				-- item beside it, and both are top-aligned inside boxes of that same
				-- height. That is what makes them line up: two labels with one role, one
				-- line height and one top edge put their first line on one baseline by
				-- construction. It used to be a 4px frame centred in a 23px slot next to a
				-- label centred in its own measured bounds -- two heights computed
				-- separately, agreeing only by luck, and they did not: every bullet in a
				-- reply sat low, near the descender of the line it belonged to.
				local bulletRole = theme.textRole("body")
				for position, item in ipairs(block.items) do
					local row = P.row(list, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						-- Closer to its own text than to the item above it. At sm the gap
						-- was wider than the mark, which reads as a stray dot rather than
						-- as the start of a line.
						gap = theme.space.xs,
						alignY = "Top",
						layoutOrder = position,
					})
					if (item.depth or 0) > 0 then
						P.frame(row, {
							name = "Indent",
							size = UDim2.fromOffset(item.depth * theme.space.lg, bulletRole.height),
							layoutOrder = 1,
						})
					end
					P.text(row, {
						name = "Marker",
						-- The middle dot rather than a bullet: it is Latin-1, so every family
						-- the engine offers has it, and at body size a round bullet next to
						-- 14px text is the loudest thing in the paragraph.
						text = item.marker or "\194\183",
						role = "body",
						line = bulletRole.line,
						color = theme.color.textTertiary,
						align = "Right",
						alignY = "Top",
						size = UDim2.new(0, markerWidth, 0, bulletRole.height),
						layoutOrder = 2,
					})
					P.text(row, {
						text = markdown.inline(item.text),
						role = "body",
						line = bulletRole.line,
						rich = true,
						wrap = true,
						alignY = "Top",
						auto = "Y",
						size = UDim2.new(0, 0, 0, 0),
						flex = "Fill",
						layoutOrder = 3,
					})
				end
			else
				local label = P.text(column, {
					text = markdown.inline(block.text),
					role = "body",
					rich = true,
					wrap = true,
					auto = "Y",
					layoutOrder = index,
				})
				label.Size = UDim2.new(1, 0, 0, 0)
			end
		end
	end

	-- Build a replacement before releasing the current reply/preview. An unusual
	-- Markdown block must not leave a byline above an empty, permanently broken row.
	function M.renderBlocks(column, text, viewport, state)
		local staged = P.column(column, { name = "Blocks", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", gap = theme.space.md, visible = false })
		local ok, err = pcall(function()
			if not viewport then renderBlocks(staged, tostring(text or "")); return end
			local blocks = state and state.text == text and state.blocks or markdown.blocks(tostring(text or ""))
			if state then state.text, state.blocks = text, blocks end
			local order = 0
			for _, source in ipairs(blocks) do
				-- Long lists are several independent drawing chunks. Code and tables
				-- already have bounded, scrollable previews of their own.
				local pieces = { source }
				if source.kind == "bullets" and #source.items > 16 then
					pieces = {}
					for first = 1, #source.items, 16 do
						pieces[#pieces + 1] = { kind = "bullets", items = util.slice(source.items, first, first + 15) }
					end
				end
				for _, block in ipairs(pieces) do
					order = order + 1
					local slot = order
					local plain = block.text or ""
					if block.items then
						local lines = {}; for _, item in ipairs(block.items) do lines[#lines + 1] = item.text end
						plain = table.concat(lines, "\n")
					end
					viewport.add(staged, { order = slot, fallback = plain,
						estimate = function(width)
							if block.kind == "table" then return theme.text.body.height * math.min(12, #(block.rows or {}) + 2) end
							local height = env.require("ui/chat/viewport").estimate(plain, width, theme.space.sm)
							return block.kind == "code" and math.min(height, theme.text.body.height * 14) or height
						end,
						build = function(parent)
							local chunk = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = 0 })
							renderBlocks(chunk, "", { block }, slot)
							return { root = chunk }
						end,
					})
				end
			end
		end)
		if not ok then
			staged:Destroy()
			staged = P.text(column, { name = "PlainTextFallback", text = util.sanitise(tostring(text or "")),
				role = "body", wrap = true, auto = "Y", visible = false })
			env.require("runtime/log").warn("ui", "Markdown displayed as plain text", err)
		end
		for _, child in ipairs(column:GetChildren()) do
			if child ~= staged and not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
		end
		staged.Visible = true
	end

	-- Who said it, above what they said.
	--
	-- One quiet line. It is the piece the transcript was missing: a turn was a tinted box
	-- followed by unmarked prose followed by another tinted box, so scrolling back
	-- through a long conversation meant inferring the speaker from the fill, and the
	-- reply's attribution existed nowhere at all -- a client that can switch model
	-- mid-conversation was rendering four different models' answers identically.
	--
	-- The role stays readable while the model attribution truncates independently.
	local function byline(parent, props)
		local row = P.row(parent, {
			name = "Byline",
			size = UDim2.new(1, 0, 0, math.max(theme.size.iconLarge, theme.text.label.height)),
			gap = theme.space.xs,
			layoutOrder = props.layoutOrder or 1,
		})
		if props.icon then
			local slot = P.frame(row, {
				name = "BylineIcon",
				size = UDim2.fromOffset(theme.size.iconLarge, theme.size.iconLarge),
				layoutOrder = 1,
			})
			icons.draw(props.icon, slot, theme.size.icon, props.iconColor or theme.color.textTertiary)
		end
		-- Fills rather than sizing to its text, so the byline is one full-width row and a
		-- long model id truncates instead of pushing the line past the reading column.
		P.text(row, {
			name = "Speaker",
			text = tostring(props.name or ""),
			role = props.mono and "monoSmall" or "label",
			color = props.color or theme.color.textSecondary,
			size = props.detail and UDim2.fromOffset(0, theme.text.label.height) or UDim2.new(0, 0, 1, 0),
			auto = props.detail and "X" or nil,
			flex = not props.detail and "Fill" or nil,
			truncate = true,
			layoutOrder = 2,
		})
		if props.detail then
			P.text(row, {
				name = "ModelAttribution", text = props.detail, role = "caption",
				color = theme.color.textTertiary, size = UDim2.new(0, 0, 1, 0),
				flex = "Fill", truncate = true, layoutOrder = 3,
			})
		end
		return row
	end

	-- Who the person at this client is, for the byline. The display name, because that
	-- is what they see everywhere else in the game.
	local function localName()
		local okName, display = pcall(function() return env.plr and env.plr.DisplayName end)
		if okName and type(display) == "string" and util.trim(display) ~= "" then
			return display
		end
		if env.plr and type(env.plr.Name) == "string" and env.plr.Name ~= "" then
			return env.plr.Name
		end
		return "You"
	end

	-- Sent prompts keep their byline inside one quiet, bordered surface.
	function M.user(parent, text, order, props)
		if props and props.viewport and not props.mounted then
			local options = util.copy(props); options.mounted, options.messageState = true, {}
			return props.viewport.add(parent, { name = "User", order = order, fallback = tostring(text),
				estimate = function(width) return env.require("ui/chat/viewport").estimate(util.truncate(tostring(text), 1200), width - theme.space.md * 2, theme.text.label.height + theme.space.lg) end,
				build = function(into) return M.user(into, text, 1, options) end })
		end
		local state = props and props.messageState or {}
		local holder = P.column(parent, {
			name = "User",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = order or 0,
		})
		local body = P.column(holder, {
			name = "Bubble", size = UDim2.new(1, 0, 0, 0), auto = "Y",
			bg = theme.color.bubbleUser, radius = theme.radius.md,
			padding = { x = theme.space.md, y = theme.space.sm }, gap = theme.space.xxs, layoutOrder = 1,
		})
		P.stroke(body, theme.color.bubbleUserBorder)
		byline(body, { name = localName(), color = theme.color.textTertiary, layoutOrder = 1 })

		local label = P.text(body, {
			text = state.expanded and tostring(text) or util.truncate(tostring(text), 1200),
			role = "body",
			layoutOrder = 2,
			wrap = true,
			auto = "Y",
		})
		label.Size = UDim2.new(1, 0, 0, 0)
		if #tostring(text) > 1200 then
			P.button(body, {
				name = "ExpandMessage",
				text = state.expanded and "Show less" or "Show full message",
				variant = "ghost",
				size = "sm",
				align = "Left",
				fill = true,
				padX = 0,
				layoutOrder = 3,
				onClick = function(button)
					state.expanded = not state.expanded
					label.Text = state.expanded and tostring(text) or util.truncate(tostring(text), 1200)
					button.setText(state.expanded and "Show less" or "Show full message")
				end,
			})
		end
		return { root = holder, label = label }
	end

	function M.agent(parent, text, order, attribution, props)
		if props and props.viewport and not props.mounted then
			local value, model, partial = text or "", attribution, false
			local options = util.copy(props); options.mounted, options.renderState = true, {}
			local item = props.viewport.add(parent, { name = "Agent", order = order, fallback = tostring(text or ""),
				estimate = function(width) return env.require("ui/chat/viewport").estimate(value, width, theme.text.label.height + theme.space.lg) end,
				build = function(into)
					local handle = M.agent(into, partial and "" or value, 1, model, options)
					if partial then handle.stream(value) end
					return handle
				end })
			function item.setModel(nextModel) model = nextModel or model; item.update("setModel", model) end
			function item.setText(nextText) value, partial = nextText or "", false; item.fallback = value; item.update("setText", value) end
			function item.stream(nextText) value, partial = tostring(nextText or ""), true; item.fallback = value; item.update("stream", value) end
			function item.finish(nextText, nextModel) item.setModel(nextModel); item.setText(nextText or value) end
			return item
		end
		local holder = P.column(parent, {
			name = "Agent",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = order or 0,
		})
		-- Keep response attribution when replaying or completing a live preview.
		local record = env.require("provider/registry").active()
		local model = attribution or (record and util.trim(tostring(record.model or "")) or "")
		if model == "" then model = record and record.label or "no model" end
		local attributionRow = byline(holder, {
			name = "Assistant",
			detail = model,
			icon = "brand",
			iconColor = theme.color.accent,
			color = theme.color.textSecondary,
			layoutOrder = 1,
		})
		local column = P.column(holder, {
			name = "Body",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			-- Paragraphs need more than eight pixels between them or a long reply
			-- arrives as one grey slab with no shape to it.
			gap = theme.space.md,
			layoutOrder = 2,
		})

		local currentText = text or ""
		local streamLabel = nil

		local handle = { root = holder, column = column }
		local modelLabel = attributionRow:FindFirstChild("ModelAttribution")

		function handle.setModel(value)
			local text = util.trim(tostring(value or ""))
			if text ~= "" then modelLabel.Text = text end
		end

		function handle.setText(value)
			currentText = value or ""
			streamLabel = nil
			M.renderBlocks(column, currentText, props and props.viewport, props and props.renderState)
		end

		function handle.stream(partial)
			currentText = tostring(partial or "")
			-- Incomplete tables/code fences stay in one label until the final render.
			if not streamLabel or streamLabel.Parent ~= column then
				for _, child in ipairs(column:GetChildren()) do
					if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
				end
				streamLabel = P.text(column, { name = "StreamText", text = "", role = "body", wrap = true,
					auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 1 })
			end
			streamLabel.Text = currentText .. " ●"
		end

		function handle.finish(finalText, finalModel)
			handle.setModel(finalModel)
			handle.setText(finalText or currentText)
		end

		handle.setText(text or "")
		return handle
	end

	-- Reasoning is a quieter register of the same page, not an object on it: a header
	-- row and muted body text, no card and no outline. It used to be a bordered panel,
	-- which gave a paragraph of thinking the same visual weight as a settings group.
	--
	-- The body now sits behind a rule and an indent. Flush left in the same measure as
	-- the reply, at 13px against the reply's 14 and one step down in colour, thinking
	-- and answer were two paragraphs that looked alike -- so a turn read as the model
	-- saying the same thing twice, which is exactly what it looks like when a model
	-- restates its conclusion in prose.
	function M.reasoning(parent, text, order)
		text = tostring(text or "")
		local truncated = false
		local function mobileThought()
			return responsive.touch and not responsive.pointer and not responsive.console
		end
		local function tokenLabel()
			-- Older transcripts predate explicit truncation metadata.
			local excerpt = truncated or (mobileThought() and #text > MOBILE_THOUGHT_BYTES)
				or text:find("%.%.%. %[%d+ characters omitted") ~= nil
			if excerpt then return "Excerpt" end
			local tokens = usage.estimateText(text)
			return "~" .. util.formatNumber(tokens) .. (tokens == 1 and " token shown" or " tokens shown")
		end
		local holder = wrapper(parent, { name = "Reasoning", layoutOrder = order })
		local card = P.column(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
		})

		local header = Instance.new("TextButton", card)
		header.Name = "ReasoningHeader"
		header.Text = ""
		header.AutoButtonColor = false
		header.BackgroundColor3 = theme.color.surface
		header.BackgroundTransparency = 0.45
		header.Size = UDim2.new(1, 0, 0, math.max(theme.size.rowSmall,
			responsive.minTarget()))
		header.LayoutOrder = 1
		header.Selectable = true
		Instance.new("UICorner", header).CornerRadius = UDim.new(0, theme.radius.sm)
		local thinkStroke = Instance.new("UIStroke", header)
		thinkStroke.Color = theme.color.borderSubtle
		thinkStroke.Thickness = theme.stroke.hair
		thinkStroke.Transparency = 0.4

		local row = P.row(header, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.sm,
			padding = { left = theme.space.sm, right = theme.space.sm },
			alignY = "Center",
		})
		local caret = P.frame(row, {
			name = "Caret",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")

		local sparkBadge = P.frame(row, {
			name = "SparkBadge",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 2,
		})
		icons.spark(sparkBadge, theme.size.icon, theme.color.accent)

		local title = P.text(row, {
			text = "Thinking",
			role = "label",
			color = theme.color.textSecondary,
			auto = "X",
			layoutOrder = 3,
		})

		local tokenPill = P.frame(row, {
			name = "TokenPill",
			size = UDim2.fromOffset(0, theme.text.caption.height),
			padding = { x = theme.space.xxs },
			auto = "X",
			layoutOrder = 4,
		})
		local tokenText = P.text(tokenPill, {
			name = "ReasoningExtent", text = tokenLabel(),
			role = "caption",
			color = theme.color.textTertiary,
			auto = "X",
		})
		local function fitHeader()
			local required = P.measureText(title.Text, { role = "label" }).X
				+ P.measureText(tokenText.Text, { role = "caption" }).X
				+ theme.size.icon * 2 + theme.space.sm * 5 + theme.space.xxs * 2
			tokenPill.Visible = header.AbsoluteSize.X >= required
		end
		header:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitHeader)
		fitHeader()

		local bodyRow = P.frame(card, { name = "Aside", size = UDim2.new(1, 0, 0, 0), layoutOrder = 2, visible = false })
		P.frame(bodyRow, { name = "Rule", size = UDim2.new(0, theme.stroke.hair, 1, 0),
			position = UDim2.fromOffset(theme.space.sm, 0), bg = theme.color.borderSubtle })
		local indent = theme.space.xl
		local viewport = P.scroll(bodyRow, { name = "ThoughtViewport", size = UDim2.new(1, -indent, 0, 0),
			position = UDim2.fromOffset(indent, 0), gap = theme.space.sm,
			padding = { right = theme.space.sm, y = theme.space.xxs } })
		-- Retain folded traces in Lua only. Hidden AutoSize labels still hand their
		-- full text to the engine, so defer that native layout work until opened.
		local body = P.text(viewport.instance, { name = "ThoughtText", text = "", role = "small",
			color = theme.color.textSecondary, rich = false, wrap = true,
			alignY = "Top", size = UDim2.new(1, 0, 0, 0) })
		P.text(viewport.instance, { name = "ReasoningNote",
			text = "Visible reasoning may be summarized or shortened. Its estimated size is not the model's thinking budget or billed token usage.",
			role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y",
			size = UDim2.new(1, 0, 0, 0), layoutOrder = 1 })
		local open = config.get("ui.expandThinking", false) == true
		local formatted, formattedMobile, formattedText, formattedRich, plainText
		local function drawBody()
			local mobile = mobileThought()
			if formatted ~= text or formattedMobile ~= mobile then
				-- A short viewport still lays out the whole native label. Bound the
				-- phone's drawing source before formatting and measurement, retaining
				-- the original trace for context and persistence outside presentation.
				local shown = mobile and util.truncate(text, MOBILE_THOUGHT_BYTES) or text
				local ok, rich = pcall(markdown.inline, shown)
				ok = ok and type(rich) == "string" and (not mobile or #rich <= MOBILE_THOUGHT_RICH_BYTES)
				local plainOk, plain = pcall(markdown.plain, shown)
				plainText = ok and plainOk and type(plain) == "string" and plain or shown
				formatted, formattedMobile = text, mobile
				-- RichText tags can expand a small source. Fall back to its bounded
				-- plain form rather than cutting through generated markup.
				formattedRich, formattedText = ok, ok and rich or shown
			end
			body.RichText = formattedRich
			body.Text = formattedText
		end
		local fitting = false
		local function fit()
			if not open or not bodyRow.Parent or fitting then return end
			fitting = true
			local width = math.max(1, viewport.instance.AbsoluteSize.X - theme.space.sm)
			local measured = math.max(body.TextBounds.Y, body.AbsoluteSize.Y,
				P.measureText(plainText or "", { role = "small", width = width }).Y)
			local room = responsive.isMobile() and responsive.usableRect(env.root, 0).height or responsive.viewport.Y
			local height = math.min(math.max(theme.text.small.height, measured) + theme.space.xxs * 2,
				math.max(theme.text.small.height * 2, math.min(theme.size.thinkingViewport, room * 0.3)))
			bodyRow.Size = UDim2.new(1, 0, 0, height)
			viewport.instance.Size = UDim2.new(1, -indent, 0, height)
			fitting = false
		end
		body:GetPropertyChangedSignal("TextBounds"):Connect(fit)
		body:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
		local lastWidth = 0
		viewport.instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			local width = viewport.instance.AbsoluteSize.X
			if width ~= lastWidth then lastWidth = width; fit() end
		end)
		local unsubscribe = responsive.changed:connect(function()
			if open then drawBody() end
			tokenText.Text = tokenLabel()
			fitHeader()
			fit()
		end)
		holder.Destroying:Connect(unsubscribe)
		local function setOpen(value)
			open = value
			if open then
				drawBody()
				body.AutomaticSize = Enum.AutomaticSize.Y
			else
				body.AutomaticSize = Enum.AutomaticSize.None
				body.Text, body.RichText = "", false
			end
			bodyRow.Visible = open
			P.animate(caret, "hover", { Rotation = open and 90 or 0 })
			if open then fit() end
		end
		header.Activated:Connect(function() setOpen(not open) end)
		setOpen(open)
		disclosure(header, thinkStroke)
		-- The wrapper, not the card: hiding the card alone left its frame in the list
		-- layout, so a hidden reasoning row still pushed the reply down by its padding.
		if config.get("ui.showReasoning", true) == false then holder.Visible = false end

		local handle = { root = holder, body = body }
		function handle.setText(value, isTruncated)
			local nextText = tostring(value or "")
			if text == nextText and truncated == (isTruncated == true) then return end
			if text ~= nextText then formatted, formattedMobile, formattedText, formattedRich, plainText = nil, nil, nil, nil, nil end
			text = nextText
			truncated = isTruncated == true
			if open then drawBody() end
			tokenText.Text = tokenLabel()
			fitHeader()
			if open then fit() end
		end
		function handle.append(value)
			value = tostring(value or "")
			if value ~= "" and value ~= text then handle.setText(text .. "\n\n" .. value, truncated) end
		end
		return handle
	end

	-- Which argument on a call is a listing rather than a value, and what language it
	-- is in.
	--
	-- Ordered, because a call can carry more than one: file_write takes a `path` and a
	-- `content`, run_luau takes only `code`. Anything matched here is drawn as code and
	-- kept out of the key/value list, so the same string is never shown twice.
	local CODE_KEYS = {
		{ key = "code", lang = "lua" },
		{ key = "source", lang = "lua" },
		{ key = "script", lang = "lua" },
		{ key = "expression", lang = "lua" },
		{ key = "patch", lang = "diff" },
		{ key = "diff", lang = "diff" },
		{ key = "old_text", label = "Before" },
		{ key = "new_text", label = "After" },
		-- Language from the path it is being written to, since a file_write is whatever
		-- the extension says it is.
		{ key = "content" },
		{ key = "body" },
		{ key = "text" },
	}

	local EXTENSION_LANGS = {
		lua = "lua", luau = "lua", json = "json", md = "markdown", markdown = "markdown",
		js = "javascript", ts = "typescript", py = "python", html = "html", css = "css",
		yml = "yaml", yaml = "yaml", toml = "toml", sh = "bash", xml = "xml", csv = "csv",
		rbxmx = "xml", rbxlx = "xml",
	}

	-- The fields worth putting on the header line, most identifying first. Raw JSON
	-- used to go here, which at ninety characters shows the shape of the payload and
	-- none of its meaning: `{"path":"notes/plan.txt","content":"# Pl`.
	local SUMMARY_KEYS = {
		"path", "file", "query", "url", "class", "property", "name", "id",
		"command", "task", "question", "key", "value",
	}

	local function langForPath(path)
		local extension = tostring(path or ""):match("%.([%w]+)$")
		if not extension then return nil end
		return EXTENSION_LANGS[extension:lower()]
	end

	-- Splits decoded arguments into the listings and the scalar facts.
	local function splitArguments(args)
		local code, facts = {}, {}
		if type(args) ~= "table" then return code, facts end
		local taken = {}
		local pathHint = args.path or args.file or args.name
		for _, spec in ipairs(CODE_KEYS) do
			local value = args[spec.key]
			if type(value) == "string" and (value ~= "" or spec.label) and not taken[spec.key] then
				-- Only a listing if there is something to look at. A one-line `text` is a
				-- value, and a code card around three words is more chrome than content.
				local multiline = value:find("\n") ~= nil
				if spec.lang or spec.label or multiline then
					code[#code + 1] = {
						key = spec.key,
						text = value,
						lang = spec.lang or langForPath(pathHint),
						label = spec.label,
					}
					taken[spec.key] = true
				end
			end
		end
		for _, key in ipairs(util.keys(args, true)) do
			if not taken[key] then
				local value = args[key]
				local kind = type(value)
				if kind == "string" or kind == "number" or kind == "boolean" then
					facts[#facts + 1] = { key = tostring(key), value = tostring(value) }
				elseif kind == "table" then
					-- A nested structure is still shown verbatim: it is what an
					-- instance_create property map and a remote_fire argument list are, and
					-- both were previously invisible.
					local ok, encoded = pcall(util.encode, value)
					facts[#facts + 1] = { key = tostring(key), value = ok and encoded or "(not encodable)" }
				end
			end
		end
		return code, facts
	end

	local function summarise(args, raw)
		local function preview(value)
			return (util.ellipsis(value == nil and "" or tostring(value), ARG_PREVIEW):gsub("[\n\r]+", " "))
		end
		if type(args) ~= "table" then
			return preview(raw)
		end
		local parts = {}
		for _, key in ipairs(SUMMARY_KEYS) do
			local value = args[key]
			if type(value) == "string" or type(value) == "number" then
				parts[#parts + 1] = preview(value)
			end
		end
		if #parts == 0 then
			for _, key in ipairs(util.keys(args, true)) do
				local value = args[key]
				local kind = type(value)
				if kind == "string" or kind == "number" or kind == "boolean" then
					parts[#parts + 1] = key .. " " .. preview(value)
				end
				if #parts >= 3 then break end
			end
		end
		return util.ellipsis(table.concat(parts, "  \194\183  "), ARG_PREVIEW)
	end

	-- Activity owns compact disclosures and lazy details; message rendering supplies
	-- the same code and argument presentation used by ordinary replies.
	local activity = env.require("ui/chat/activity").new({
		wrapper = wrapper, disclosure = disclosure, codeBlock = M.codeBlock,
		splitArguments = splitArguments, summarise = summarise,
	})
	M.toolRun, M.toolCall, M.subagent = activity.toolRun, activity.toolCall, activity.subagent
	M.splitArguments = splitArguments

	-- An inline note: a retry, a provider switch, a compaction, an error.
	--
	-- Only a bad one gets a fill. The rest are ordinary events in the life of a turn
	-- and were each arriving as a tinted panel, so a conversation that retried twice
	-- and compacted once read as three warnings rather than as three footnotes.
	function M.notice(parent, props, order)
		local tone = props.tone or "info"
		local holder = P.column(parent, { name = "Notice", layoutOrder = order,
			size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		local bad = tone == "bad"
		local row = P.row(holder, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = bad and theme.color.dangerSurface or nil,
			radius = bad and theme.radius.md or nil,
			gap = theme.space.xs,
			-- Padded either way, so a bad notice does not indent its own text eight pixels
			-- further than the plain one above it. The fill is what marks it, not the inset.
			padding = { x = bad and theme.space.sm or 0, y = bad and theme.space.xs or 0 },
			alignY = "Top",
			layoutOrder = 1,
		})
		-- The same slot width the tool and reasoning rows put their caret in, so every
		-- top-level row in the transcript starts its text at one x. This was a bare 4px
		-- dot: a notice's text began twelve pixels left of the tool call above it.
		local dotSlot = P.frame(row, {
			name = "DotSlot",
			size = UDim2.fromOffset(theme.size.icon, theme.text.small.size),
			layoutOrder = 1,
		})
		P.statusDot(dotSlot, {
			color = theme.toneColor(tone),
			diameter = theme.size.dot,
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.5),
		})
		local label = P.text(row, {
			text = tostring(props.text),
			role = "small",
			color = bad and theme.color.danger or theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			size = UDim2.new(0, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		local help = bad and deadlineHelp.matches(props.text) and deadlineHelp.new(holder, 2) or nil
		return { root = holder, label = label, help = help }
	end

	-- The working indicator: one row that reports the current status text, replaced
	-- by the answer when the turn ends. It carries the two signals that separate
	-- "thinking" from "hung" -- a label that moves and a clock that counts up --
	-- because the HTTP call it covers can take a minute and says nothing while it
	-- does.
	function M.working(parent, order, startedAt)
		local holder = wrapper(parent, { name = "Working", layoutOrder = order })
		local rowHeight = math.max(theme.size.row, theme.text.small.height + theme.space.md)
		local row = P.row(holder, {
			name = "WorkingStatus",
			size = UDim2.new(1, 0, 0, rowHeight),
			gap = theme.space.sm, padding = { x = theme.space.md },
		})
		C.spinner(row, { diameter = theme.size.iconLarge, layoutOrder = 1 })
		local label = P.text(row, {
			text = "Thinking",
			truncate = true,
			role = "small",
			color = theme.color.textSecondary,
			-- Fills, rather than subtracting the spinner and the clock by hand. That
			-- remainder was three numbers deep and one of them was a literal 52 that
			-- also appeared, separately, as the clock's own width.
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			layoutOrder = 2,
		})
		local elapsed = P.text(row, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			layoutOrder = 3,
		})
		elapsed.Size = UDim2.fromOffset(theme.size.metaColumn, rowHeight)

		local handle = { root = holder, label = label }
		local started = tonumber(startedAt) or clock.ms()
		-- Elapsed time remains readable even with reduced motion enabled.
		local stop = clock.interval(1, function()
			local waited = clock.since(started)
			if waited >= 1000 then elapsed.Text = util.formatDuration(waited) end
		end)
		holder.Destroying:Connect(function() pcall(stop) end)

		-- Progress updates do not restart the spinner or elapsed timer.
		function handle.set(text)
			label.Text = tostring(text)
		end
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/plan
-- ==========================================================================
__UAI_MODULES["ui/chat/plan"] = (function()
-- Full task details remain reachable when the compact plan strip truncates them.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local snapshots = env.require("runtime/todo_snapshot")
	local M = {}
	function M.open(session)
		if not session then return nil end
		local modal = overlay.modal({ title = "Conversation plan", description = session.title, width = theme.size.modalWide, scroll = true })
		if not modal then return nil end
		local body = P.text(modal.content, { name = "FullPlan", text = "", role = "small", wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0) })
		local function refresh() if not modal.closed then body.Text = snapshots.text(session.todos); if body.Text == "" then body.Text = "No task plan yet." end end end
		local unsubscribe = env.require("agent/state").todosChanged:connect(function(_, owner) if owner == session then refresh() end end)
		modal.scrim.Destroying:Connect(unsubscribe)
		P.button(modal.footer, { text = "Close", variant = "ghost", size = "sm", layoutOrder = 1, onClick = modal.close })
		P.button(modal.footer, { name = "CopyPlan", text = "Copy plan", variant = "secondary", size = "sm", layoutOrder = 2, onClick = function()
			local ok, why = env.require("runtime/clipboard").write(snapshots.text(session.todos))
			overlay.toast(ok and "Task plan copied." or tostring(why), ok and "info" or "warn")
		end })
		refresh()
		return modal
	end
	return M
end
end)()

