-- ==========================================================================
-- ui/chat/queue
-- ==========================================================================
__UAI_MODULES["ui/chat/queue"] = (function()
-- Review pending messages without interrupting the active conversation worker.
--
-- The queue is a list of things the user already decided to send, so the screen is
-- built around the order and the next item rather than around the controls: a numbered
-- medallion per message, the state in the line above it, and the four actions on a
-- quiet row underneath. Nothing here can start, stop or reorder the running turn --
-- that is the point of the surface -- so every control is either a reorder, an edit,
-- or a removal.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local sessions = env.require("agent/session")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local overlay = env.require("ui/overlay")
	local M = {}
	local opened

	function M.open(session)
		if not session or session.removed then return end
		if opened and not opened.closed then opened.close() end
		local unsubscribes, scheduled, closed, editor = {}, false, false, nil
		local entries = {}
		local function cleanup()
			if closed then return end
			closed = true
			if editor and not editor.closed then editor.close() end
			for _, unsubscribe in ipairs(unsubscribes) do unsubscribe() end
		end
		local modal = overlay.modal({ title = "Up next", width = theme.size.modalWide,
			description = "Follow-ups run in this order after the current response or tool batch. Your draft stays in the composer, and the active turn is never interrupted.",
			scroll = true, onClose = cleanup })
		if not modal then return end
		opened = modal
		modal.card.Name = "MessageQueue"

		-- The state of the queue as one sentence, with a dot that carries the same
		-- meaning in colour. The old screen opened with a bare caption, so a held queue
		-- and a flowing one looked identical until the text was read.
		local summary = P.row(modal.content, { name = "QueueSummary", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", gap = theme.space.sm, layoutOrder = 1 })
		local statusDot = P.statusDot(summary, { diameter = theme.size.dot, color = theme.color.accent, layoutOrder = 1 })
		local status = P.text(summary, { name = "QueueStatus", text = "", role = "small",
			wrap = true, auto = "Y", flex = "Fill", layoutOrder = 2 })

		local rows = P.column(modal.content, { name = "QueuedItems", auto = "Y", gap = theme.space.sm,
			size = UDim2.new(1, 0, 0, 0), layoutOrder = 2 })

		-- Shown instead of the list when nothing is waiting. A modal that opens on an
		-- empty column reads as a loading failure, not as an empty queue.
		local empty = P.column(modal.content, { name = "QueueEmpty", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", gap = theme.space.hair, padding = { y = theme.space.lg }, layoutOrder = 3, visible = false })
		P.text(empty, { name = "QueueEmptyTitle", text = "Nothing waiting", role = "bodyStrong",
			color = theme.color.textSecondary, align = "Center", auto = "Y", wrap = true, layoutOrder = 1 })
		P.text(empty, { text = "Send a follow-up while UAI is working and it will wait here, in order.",
			role = "caption", color = theme.color.textTertiary, align = "Center", auto = "Y", wrap = true, layoutOrder = 2 })

		local resume = P.button(modal.footer, { name = "ResumeQueue", text = "Resume queued", variant = "primary", size = "sm",
			onClick = function()
				local ok, why = session.resumeQueue()
				if not ok then overlay.toast(tostring(why), "warn", 4) end
			end })
		local clear = P.button(modal.footer, { name = "ClearQueue", text = "Clear queued", variant = "ghost", size = "sm", layoutOrder = 2,
			onClick = function()
				local ids = {}; for _, item in ipairs(session.queueSnapshot().items) do ids[#ids + 1] = item.id end
				overlay.confirm({ title = "Clear queued messages?", description = "Remove these " .. tostring(#ids) .. " follow-ups. The active response keeps running.",
					confirmText = "Clear queued", danger = true, onConfirm = function()
						local ok, why = session.clearQueued(ids)
						if not ok then overlay.toast(tostring(why), "warn", 3) end
					end })
			end })
		P.button(modal.footer, { name = "QueueDone", text = "Done", variant = "ghost", size = "sm", layoutOrder = 3,
			onClick = function() modal.close() end })

		local function edit(item)
			if editor and not editor.closed then editor.close() end
			editor = overlay.modal({ title = "Edit follow-up", description = "Changes apply to this queued message. Attached images stay attached.", width = theme.size.modalWide })
			if not editor then return end
			local currentEditor = editor
			local field = P.field(editor.content, { name = "QueuedEditField", text = item.text, multiline = true,
				height = theme.size.promptTextarea, layoutOrder = 1 })
			local notice = P.text(editor.content, { name = "QueuedEditNotice", text = "Up to 8,000 bytes.", role = "caption",
				wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 2 })
			-- A live count rather than a fixed limit: the only reason this field has a
			-- limit at all is that the queue stores bytes, so saying how many are used
			-- is more useful than restating the maximum.
			local function count()
				local used = #(field.get() or "")
				notice.Text = tostring(used) .. " of 8,000 bytes"
				notice.TextColor3 = used > 8000 and theme.color.warn or theme.color.textTertiary
			end
			field.instance:GetPropertyChangedSignal("Text"):Connect(count)
			count()
			P.button(editor.footer, { name = "CancelQueuedEdit", text = "Cancel", variant = "ghost", size = "sm",
				onClick = function() currentEditor.close() end })
			P.button(editor.footer, { name = "SaveQueuedEdit", text = "Save changes", variant = "primary", size = "sm", layoutOrder = 2,
				onClick = function()
					local ok, why = session.editQueued(item.id, field.get(), item.text)
					if ok then currentEditor.close() else notice.Text = tostring(why); notice.TextColor3 = theme.color.warn end
				end })
			field.focus()
		end

		local function makeEntry(item)
			local entry = {}
			-- A row, not a column: the medallion, the message and the remove control sit
			-- on one line, and the actions hang under the message rather than under the
			-- whole card. The card stays a single object when the list reorders because
			-- only its LayoutOrder moves.
			entry.frame = P.row(rows, { name = "Queued_" .. item.id, size = UDim2.new(1, 0, 0, 0), auto = "Y",
				gap = theme.space.sm, bg = theme.color.surfaceRaised, radius = theme.radius.lg,
				padding = { x = theme.space.md, y = theme.space.sm }, alignY = "Top" })
			P.stroke(entry.frame, theme.color.borderSubtle)
			entry.chip = P.frame(entry.frame, { name = "QueuedIndexChip", size = UDim2.fromOffset(theme.size.controlSmall, theme.size.controlSmall),
				bg = theme.color.surface, radius = theme.radius.sm, layoutOrder = 1 })
			entry.index = P.text(entry.chip, { name = "QueuedIndex", text = "", role = "caption",
				color = theme.color.textSecondary, align = "Center", size = UDim2.fromScale(1, 1) })
			entry.body = P.column(entry.frame, { name = "QueuedBody", size = UDim2.new(0, 0, 0, 0), auto = "Y",
				flex = "Fill", gap = theme.space.xs, layoutOrder = 2 })
			entry.status = P.text(entry.body, { name = "QueuedPosition", text = "", role = "caption",
				color = theme.color.textSecondary, auto = "Y", wrap = true, layoutOrder = 1 })
			entry.text = P.text(entry.body, { name = "QueuedText", text = "", role = "small", wrap = true,
				auto = "Y", layoutOrder = 2 })
			local actions = P.row(entry.body, { name = "QueuedActions", auto = "Y", wrap = true, gap = theme.space.xxs,
				size = UDim2.new(1, 0, 0, 0), layoutOrder = 3 })
			entry.read = P.button(actions, { name = "ReadQueued_" .. item.id, text = "Show full", variant = "ghost", size = "sm",
				onClick = function()
					entry.expanded = not entry.expanded
					entry.text.Text = entry.expanded and entry.item.text or util.ellipsis(entry.item.text, 320)
					entry.read.setText(entry.expanded and "Show less" or "Show full")
				end })
			entry.edit = P.button(actions, { name = "EditQueued_" .. item.id, text = "Edit", variant = "ghost", size = "sm", layoutOrder = 2,
				onClick = function() edit(entry.item) end })
			local function move(direction)
				local neighbor = direction == -1 and entry.previous or entry.next
				local ok, why = session.moveQueued(entry.item.id, direction, neighbor and neighbor.id)
				if not ok then overlay.toast(tostring(why), "warn", 3) end
			end
			entry.up = P.button(actions, { name = "MoveQueuedUp_" .. item.id, text = "Move up", variant = "ghost", size = "sm", layoutOrder = 3,
				onClick = function() move(-1) end })
			entry.down = P.button(actions, { name = "MoveQueuedDown_" .. item.id, text = "Move down", variant = "ghost", size = "sm", layoutOrder = 4,
				onClick = function() move(1) end })
			P.button(actions, { name = "CopyQueued_" .. item.id, text = "Copy text", variant = "ghost", size = "sm", layoutOrder = 5,
				onClick = function()
					local ok, why = env.require("runtime/clipboard").write(entry.item.text)
					overlay.toast(ok and "Queued message copied." or tostring(why), ok and "info" or "warn")
				end })
			entry.remove = P.iconButton(entry.frame, { name = "RemoveQueued_" .. item.id, icon = "trash", diameter = theme.size.controlSmall,
				variant = "ghost", layoutOrder = 3, onClick = function()
					local ok, why = session.removeQueued(entry.item.id)
					if not ok then overlay.toast(tostring(why), "warn", 3) end
				end })
			return entry
		end

		local function refresh()
			if closed or modal.closed then return end
			local current = sessions.current()
			if session.removed or not current or current.id ~= session.id then modal.close(); return end
			local pending = session.queueSnapshot()
			status.Text = pending.count == 0 and "Nothing is waiting. The active turn keeps running."
				or pending.held and ("Paused: " .. tostring(pending.reason or "work stopped") .. ". Resume when you are ready.")
				or (tostring(pending.count) .. " of " .. tostring(pending.limit) .. " queued. The active agent keeps working.")
			status.TextColor3 = pending.held and theme.color.warn or theme.color.textSecondary
			statusDot.BackgroundColor3 = pending.held and theme.color.warn
				or pending.count > 0 and theme.color.accent or theme.color.textDisabled
			resume.instance.Visible = pending.count > 0 and pending.held == true
			resume.setEnabled(not session.busy and not session.preparing)
			clear.instance.Visible = pending.count > 0
			empty.Visible = pending.count == 0
			local wanted = {}; for _, item in ipairs(pending.items) do wanted[item.id] = true end
			for id, entry in pairs(entries) do if not wanted[id] then entry.frame:Destroy(); entries[id] = nil end end
			for index, item in ipairs(pending.items) do
				local entry = entries[item.id]
				if not entry then
					entry = makeEntry(item)
					entries[item.id] = entry
				end
				entry.item, entry.previous, entry.next = item, pending.items[index - 1], pending.items[index + 1]
				entry.frame.LayoutOrder = index
				local imageCount, fileCount = #(item.images or {}), #(item.files or {})
				entry.index.Text = tostring(index)
				-- The first message is the one the next turn will actually send, so it
				-- carries the accent; everything behind it is neutral until it moves up.
				entry.chip.BackgroundColor3 = index == 1 and theme.color.accentSurface or theme.color.surface
				entry.index.TextColor3 = index == 1 and theme.color.accent or theme.color.textTertiary
				entry.status.Text = tostring(index) .. " of " .. tostring(pending.count) .. " \194\183 "
					.. (item.state == "preparing" and "Preparing attachments" or pending.held and "Paused" or index == 1 and "Up next" or "Waiting")
					.. (fileCount > 0 and (" \194\183 " .. util.pluralise(fileCount, "file")) or "")
					.. (imageCount > 0 and (" \194\183 " .. util.pluralise(imageCount, "image")) or "")
				entry.status.TextColor3 = item.state == "preparing" and theme.color.warn
					or pending.held and theme.color.warn
					or index == 1 and theme.color.accent or theme.color.textTertiary
				entry.text.Text = entry.expanded and item.text or util.ellipsis(item.text or "", 320)
				entry.read.instance.Visible = #(item.text or "") > 320
				entry.edit.instance.Visible = item.state == "queued" and fileCount == 0
				entry.up.instance.Visible = entry.previous ~= nil
				entry.down.instance.Visible = entry.next ~= nil
				entry.up.setEnabled(item.state == "queued" and entry.previous and entry.previous.state == "queued")
				entry.down.setEnabled(item.state == "queued" and entry.next and entry.next.state == "queued")
			end
		end
		local function queue()
			if scheduled or closed or modal.closed then return end
			scheduled = true
			clock.delay(0.05, function() scheduled = false; refresh() end)
		end
		unsubscribes[#unsubscribes + 1] = session.events:connect(function(event)
			if event.kind:sub(1, 8) == "message:" or event.kind == "queue:state" or event.kind == "status" then queue() end
		end)
		unsubscribes[#unsubscribes + 1] = sessions.listChanged:connect(queue)
		modal.scrim.Destroying:Connect(cleanup)
		refresh()
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/search
-- ==========================================================================
__UAI_MODULES["ui/chat/search"] = (function()
-- Search saved transcript events; opening a result navigates by its stable id.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local clock = env.require("runtime/clock")
	local overlay = env.require("ui/overlay")
	local M = {}
	function M.open(session)
		if not session or session.removed then return nil end
		local modal = overlay.modal({ title = "Find in conversation", description = env.require("runtime/search").hint,
			width = theme.size.modalWide, scroll = true })
		if not modal then return nil end
		local query, before, role = "", nil, "all"
		local render, more
		local field = P.field(modal.content, { name = "TranscriptSearch", placeholder = "Search this conversation", layoutOrder = 1,
			onChange = function(value) query, before = value, nil; if render then render() end end })
		local filters = P.row(modal.content, { name = "TranscriptSearchRoles", auto = "Y", wrap = true,
			size = UDim2.new(1, 0, 0, 0), gap = theme.space.xs, layoutOrder = 2 })
		for _, entry in ipairs({ { "All", "all" }, { "Messages", "user" }, { "Replies", "assistant:text" }, { "Errors", "error" } }) do
			P.button(filters, { text = entry[1], variant = "ghost", size = "sm", onClick = function()
				role, before = entry[2], nil; render()
			end })
		end
		local status = P.text(modal.content, { name = "TranscriptSearchStatus", text = "Enter words to search the saved transcript.",
			role = "caption", wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 3 })
		local rows = P.column(modal.content, { name = "TranscriptSearchResults", auto = "Y", size = UDim2.new(1, 0, 0, 0),
			gap = theme.space.xs, layoutOrder = 4 })
		local function refresh()
			if modal.closed then return end
			for _, child in ipairs(rows:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
			local page = session.searchTranscript(query, { before = before, role = role })
			status.Text = tostring(#page.items) .. " matches on this page / " .. (role == "all" and "all messages" or role)
				.. (page.clipped and ". Long messages search their first 16 KiB." or "")
				.. (page.complete and ". Saved history searched." or ". Continue to search older history.")
			for index, hit in ipairs(page.items) do
				local row = P.rowButton(rows, { name = "SearchResult_" .. tostring(hit.id), vertical = true, auto = "Y",
					size = UDim2.new(1, 0, 0, 0), padding = theme.space.sm, gap = theme.space.xxs,
					bg = theme.color.surfaceRaised, radius = theme.radius.md, layoutOrder = index,
					onClick = function()
						local app = env.require("ui/app")
						modal.close(); app.openSession(session.id)
						if app.chatPanel and app.chatPanel.view then app.chatPanel.view.jumpTo(hit.id) end
					end })
				P.text(row.row, { text = hit.label, role = "label", layoutOrder = 1 })
				P.text(row.row, { text = hit.snippet, role = "small", wrap = true, auto = "Y",
					size = UDim2.new(1, 0, 0, 0), color = theme.color.textSecondary, layoutOrder = 2 })
			end
			more.setEnabled(page.nextBefore ~= nil)
			more.nextBefore = page.nextBefore
		end
		local update, cancel = clock.debounce(refresh, 0.15)
		render = update
		P.button(modal.footer, { text = "Close", variant = "ghost", size = "sm", layoutOrder = 1, onClick = modal.close })
		more = P.button(modal.footer, { name = "OlderSearchResults", text = "Search older", variant = "secondary", size = "sm", layoutOrder = 2,
			onClick = function() before = more.nextBefore; refresh() end })
		more.setEnabled(false)
		modal.scrim.Destroying:Connect(cancel)
		field.focus()
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/chat/table
-- ==========================================================================
__UAI_MODULES["ui/chat/table"] = (function()
-- Markdown tables use one measured grid inside a two-axis viewport. Column
-- widths are shared by every row; labels own their wrapped height, never their
-- parent's height. No row or cell is truncated, including malformed wide rows.
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local markdown = env.require("ui/markdown")
	local M = {}

	local ALIGN = { left = "Left", center = "Center", right = "Right" }
	local ENTITIES = { lt = "<", gt = ">", amp = "&", quot = '"', apos = "'" }

	-- Strip only our generated tags, then decode once. In particular, a literal
	-- &lt;b&gt; in the reply is not a tag and must contribute to the measurement.
	local function visibleText(rich)
		return (rich:gsub("<[^>]*>", ""):gsub("&(%a+);", function(name)
			return ENTITIES[name] or ("&" .. name .. ";")
		end))
	end

	local function measure(text, role, width)
		local ok, bounds = pcall(function()
			return env.services.TextService:GetTextSize(text, role.size, role.font,
				Vector2.new(width, theme.size.reading))
		end)
		if ok and bounds then return bounds end
		-- An initial estimate only; engine TextBounds/AutomaticSize replace it.
		-- Count UTF-8 leading bytes rather than charging every byte as a glyph.
		local _, count = text:gsub("[^\128-\191]", "")
		local advance = count * role.size
		return Vector2.new(math.min(advance, width), math.max(1, math.ceil(advance / width)) * role.size)
	end

	-- props: { block = markdown table block, layoutOrder = number, maxHeight? }.
	-- Returning the root matches message.codeBlock; destruction owns all listeners.
	function M.render(parent, props)
		local block = assert(props.block, "table block required")
		local columnCount = math.max(#block.header, block.columns or 0, 1)
		for _, row in ipairs(block.rows) do columnCount = math.max(columnCount, #row) end
		local padX, padY, hair = theme.space.md, theme.space.sm, theme.stroke.hair
		local bar = theme.size.scrollbar
		local minWidth = math.max(theme.size.tableColumnMin or theme.size.keyColumn, padX * 2 + theme.text.body.size)
		local maxWidth = math.max(minWidth, theme.size.tableColumnMax or theme.size.menuWide)
		local root = P.column(parent, {
			name = "MarkdownTable", size = UDim2.new(1, 0, 0, 0), auto = "Y",
			gap = theme.space.xxs, layoutOrder = props.layoutOrder,
		})
		local scroll = P.scroll(root, {
			name = "TableViewport", size = UDim2.new(1, 0, 0, theme.size.row),
			horizontal = true, gap = 0, bg = theme.color.canvas, layoutOrder = 1,
		}).instance
		scroll.ScrollingDirection = Enum.ScrollingDirection.XY
		scroll.AutomaticCanvasSize = Enum.AutomaticSize.None
		-- Stable gutters avoid a resize/rewrap loop when a scrollbar appears.
		scroll.VerticalScrollBarInset = Enum.ScrollBarInset.Always
		scroll.HorizontalScrollBarInset = Enum.ScrollBarInset.Always
		P.corner(scroll, theme.radius.sm)
		P.stroke(scroll, theme.color.borderSubtle)
		local grid = P.frame(scroll, { name = "TableGrid", size = UDim2.fromOffset(0, 0) })
		local hint = P.text(root, {
			name = "TableHint", text = "", role = "caption", color = theme.color.textTertiary,
			wrap = true, auto = "Y", alignY = "Top", layoutOrder = 2, visible = false,
		})
		local connections, rows, preferred = {}, {}, {}
		local destroyed, queued, layingOut = false, false, false
		local layout
		local function requestLayout()
			if destroyed or queued or layingOut then return end
			queued = true
			task.defer(function()
				queued = false
				if not destroyed then layout() end
			end)
		end
		local function watch(node, property, callback)
			connections[#connections + 1] = node:GetPropertyChangedSignal(property):Connect(callback or requestLayout)
		end
		for column = 1, columnCount do preferred[column] = minWidth end
		local function addRow(cells, header)
			local row = { cells = {}, header = header }
			row.frame = P.frame(grid, {
				name = header and "TableHeader" or ("TableRow_" .. tostring(#rows)),
				bg = header and theme.color.surfaceRaised or (#rows % 2 == 0 and theme.color.surface or theme.color.canvas),
				size = UDim2.fromOffset(0, 0),
			})
			local roleName = header and "bodyStrong" or "body"
			local role = theme.textRole(roleName)
			for column = 1, columnCount do
				local rich = markdown.inline(cells[column] or "")
				local text = visibleText(rich)
				local label = P.text(row.frame, {
					name = "Cell_" .. column, text = rich, role = roleName, rich = true,
					wrap = true, auto = "Y", alignY = "Top",
					align = ALIGN[(block.align or {})[column]] or "Left",
					size = UDim2.fromOffset(minWidth - padX * 2, 0),
				})
				row.cells[column] = { label = label, text = text, role = role }
				preferred[column] = math.max(preferred[column], math.min(maxWidth,
					math.ceil(measure(text, role, theme.size.reading).X) + padX * 2))
				watch(label, "AbsoluteSize")
				watch(label, "TextBounds")
			end
			row.rule = P.frame(row.frame, { name = "RowRule", bg = theme.color.borderSubtle })
			rows[#rows + 1] = row
		end
		addRow(block.header, true)
		for _, cells in ipairs(block.rows) do addRow(cells, false) end

		local previousWidth = -1
		layout = function()
			if destroyed then return end
			layingOut = true
			local width = math.floor(root.AbsoluteSize.X)
			if width <= 0 then width = math.min(theme.size.reading, responsive.viewport.X) end
			previousWidth = width
			local available = math.max(1, width - bar)
			local wanted = 0
			for _, value in ipairs(preferred) do wanted = wanted + value end
			local totalWidth = math.max(available, minWidth * columnCount)
			local widths, allocated = {}, 0
			local flex = wanted - minWidth * columnCount
			for column = 1, columnCount do
				local value
				if totalWidth >= wanted then
					value = preferred[column] + (totalWidth - wanted) / columnCount
				else
					value = minWidth + (flex > 0 and ((totalWidth - minWidth * columnCount)
						* (preferred[column] - minWidth) / flex) or 0)
				end
				widths[column] = column == columnCount and (totalWidth - allocated) or math.floor(value)
				allocated = allocated + widths[column]
			end
			local y, resized = 0, false
			for _, row in ipairs(rows) do
				local height, x = 0, 0
				for column, cell in ipairs(row.cells) do
					local label, textWidth = cell.label, widths[column] - padX * 2
					local changedWidth = label.Size.X.Offset ~= textWidth
					if changedWidth then
						label.Size = UDim2.fromOffset(textWidth, 0)
						resized = true
					end
					label.Position = UDim2.fromOffset(x + padX, padY)
					-- Until the engine publishes bounds for this width, use TextService.
					-- The live bounds include RichText fonts, UTF-8 and actual word wrap.
					local measured = not changedWidth and math.max(label.TextBounds.Y, label.AbsoluteSize.Y) or 0
					if measured <= 0 then
						measured = measure(cell.text, cell.role, textWidth).Y * cell.role.line
					end
					height = math.max(height, math.ceil(measured), cell.role.height)
					x = x + widths[column]
				end
				height = height + padY * 2 + hair
				row.frame.Position = UDim2.fromOffset(0, y)
				row.frame.Size = UDim2.fromOffset(totalWidth, height)
				row.rule.Position = UDim2.fromOffset(0, height - hair)
				row.rule.Size = UDim2.fromOffset(totalWidth, hair)
				y = y + height
			end
			local room = responsive.isMobile() and responsive.usableRect(env.root, 0).height or responsive.viewport.Y
			local cap = math.max(theme.size.row + bar, math.min(props.maxHeight
				or theme.size.tableViewport or theme.size.codeViewport, math.floor(room / 2)))
			local height = math.min(y + bar, cap)
			grid.Size = UDim2.fromOffset(totalWidth, y)
			scroll.Size = UDim2.new(1, 0, 0, height)
			scroll.CanvasSize = UDim2.fromOffset(totalWidth, y)
			local horizontal, vertical = totalWidth > available, y > height - bar
			scroll.ScrollingEnabled = horizontal or vertical
			local old = scroll.CanvasPosition
			scroll.CanvasPosition = Vector2.new(math.max(0, math.min(old.X, totalWidth - available)),
				math.max(0, math.min(old.Y, y - (height - bar))))
			hint.Visible = horizontal or vertical
			hint.Text = string.format("%d %s%s", #block.rows, #block.rows == 1 and "row" or "rows",
				horizontal and (vertical and " · Scroll across and down" or " · Scroll across")
				or (vertical and " · Scroll for more" or ""))
			layingOut = false
			-- Some clients publish TextBounds during the size assignment, while the
			-- re-entry guard is active. One coalesced follow-up consumes those bounds.
			if resized then requestLayout() end
		end
		watch(root, "AbsoluteSize", function()
			if math.floor(root.AbsoluteSize.X) ~= previousWidth then requestLayout() end
		end)
		local disconnectResponsive = responsive.changed:connect(requestLayout)
		local destroyConnection
		destroyConnection = root.Destroying:Connect(function()
			destroyed = true
			for _, connection in ipairs(connections) do connection:Disconnect() end
			disconnectResponsive()
			destroyConnection:Disconnect()
		end)
		layout()
		return root
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/todo
-- ==========================================================================
__UAI_MODULES["ui/chat/todo"] = (function()
-- The task-list strip.
--
-- The model keeps a plan; this is where the user can see it. It collapses to a
-- single line when there is nothing active, because a permanent panel for a
-- three-item list wastes the height a phone does not have.
--
-- It shows one conversation's plan: the strip is attached to a session, and a change
-- announced for a different one is ignored. Before, the store held a single list for
-- the whole client, so opening a second conversation replaced what this was showing
-- with that conversation's steps.
return function(env)
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local P = env.require("ui/primitives")
	local state = env.require("agent/state")

	local M = {}

	local MARKS = {
		pending = { colour = "textTertiary", text = "textSecondary" },
		active = { colour = "accent", text = "text" },
		done = { colour = "success", text = "textSecondary", glyph = "check" },
		dropped = { colour = "textDisabled", text = "textTertiary", glyph = "minus" },
	}
	local preferences = setmetatable({}, { __mode = "k" })

	function M.new(parent, props)
		props = props or {}

		local shell = P.column(parent, {
			name = "Todos",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.canvas,
			gap = 0,
			layoutOrder = props.layoutOrder,
			visible = false,
			clip = true,
		})
		-- Last in the stack rather than anchored to the bottom edge: the shell is a
		-- column, and a UIListLayout moves every child it has to its own slot, so an
		-- anchored rule would silently become the first row instead of the last.
		P.frame(shell, {
			name = "Rule",
			size = UDim2.new(1, 0, 0, theme.stroke.hair),
			bg = theme.color.borderSubtle,
			layoutOrder = 4,
		})

		local toggle = P.rowButton(shell, {
			name = "PlanToggle",
			height = math.max(theme.size.control, responsive.minTarget()),
			radius = theme.radius.none,
			gap = theme.space.xs,
			padding = { x = theme.space.xl },
			layoutOrder = 1,
		})
		local header = toggle.instance
		local headerRow = toggle.row
		local caret = P.frame(headerRow, {
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 1,
		})
		icons.chevron(caret, theme.size.icon, theme.color.textTertiary, "right")
		local summary = P.text(headerRow, {
			name = "PlanSummary",
			text = "",
			role = "label",
			color = theme.color.textSecondary,
			truncate = true,
			layoutOrder = 2,
		})
		summary.Size = UDim2.new(0, 0, 1, 0)
		local summaryFlex = Instance.new("UIFlexItem", summary)
		summaryFlex.FlexMode = Enum.UIFlexMode.Fill
		local details = P.button(headerRow, { name = "PlanDetails", text = "Details", variant = "ghost", size = "sm", layoutOrder = 3 })
		local trackHolder = P.frame(shell, {
			name = "PlanProgress", size = UDim2.new(1, 0, 0, theme.size.track + theme.space.sm), layoutOrder = 2,
		})
		local track = P.frame(trackHolder, {
			name = "Track", size = UDim2.new(1, -theme.space.xl * 2, 0, theme.size.track),
			position = UDim2.fromOffset(theme.space.xl, 0), bg = theme.color.surfaceOverlay, radius = theme.radius.pill,
		})
		local progress = P.frame(track, {
			name = "Completed", size = UDim2.fromScale(0, 1), bg = theme.color.accent, radius = theme.radius.pill,
		})

		local planScroll = P.scroll(shell, {
			name = "Items",
			size = UDim2.new(1, 0, 0, 0),
			gap = theme.space.xs,
			padding = { x = theme.space.xl, top = theme.space.xxs, bottom = theme.space.md },
			layoutOrder = 3,
			visible = false,
		})

		local list = planScroll.instance
		list.Visible = false
		local handle = { shell = shell, session = nil }
		details.instance.Activated:Connect(function() if handle.session then env.require("ui/chat/plan").open(handle.session) end end)
		local orphan = {}
		local preference = orphan
		-- A long plan keeps its own scroll area instead of consuming the conversation.
		local function sizePlan()
			if not list.Parent or not planScroll.layout.Parent then return end
			local measured = planScroll.layout.AbsoluteContentSize
			if not measured then return end
			local height = measured.Y + theme.space.xxs + theme.space.md
			local ceiling = math.floor(theme.size.codeViewport * 0.5)
			if parent.AbsoluteSize.Y > 0 then
				ceiling = math.min(ceiling, math.floor(parent.AbsoluteSize.Y / 3))
			end
			list.Size = UDim2.new(1, 0, 0, math.max(0, math.min(height, ceiling)))
		end
		planScroll.layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(sizePlan)
		local resize = parent:GetPropertyChangedSignal("AbsoluteSize"):Connect(sizePlan)

		local open = false
		local function setOpen(value, animate)
			open = value
			list.Visible = open
			if animate then P.animate(caret, "hover", { Rotation = open and 90 or 0 })
			else caret.Rotation = open and 90 or 0 end
			if open then sizePlan() end
		end
		header.Activated:Connect(function()
			preference.open = not open
			setOpen(preference.open, true)
		end)

		local function rebuild(items)
			for _, child in ipairs(list:GetChildren()) do
				if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then child:Destroy() end
			end

			if #items == 0 then
				shell.Visible = false
				preference.open = nil
				setOpen(false)
				list.CanvasPosition = Vector2.new(0, 0)
				return
			end
			shell.Visible = true

			local counts = state.todoCounts(handle.session)
			local total = counts.total - counts.dropped
			trackHolder.Visible = total > 0
			P.animate(progress, "hover", { Size = UDim2.fromScale(counts.done / math.max(total, 1), 1),
				BackgroundColor3 = counts.done == total and theme.color.success or theme.color.accent })
			local activeText
			for _, item in ipairs(items) do
				if item.status == "active" then activeText = item.text; break end
			end
			summary.Text = "Plan"
				.. (total > 0 and string.format("  ·  %d of %d complete", counts.done, total) or "")
				.. (counts.dropped > 0 and string.format("  ·  %d skipped", counts.dropped) or "")
				.. (activeText and ("  ·  " .. activeText) or "")

			for index, item in ipairs(items) do
				local mark = MARKS[item.status] or MARKS.pending
				local row = P.row(list, {
					name = "TodoItem" .. index,
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					alignY = "Top",
					layoutOrder = index,
				})
				local glyphHolder = P.frame(row, {
					name = "TodoMarker",
					size = UDim2.fromOffset(theme.size.icon, theme.text.small.height),
					layoutOrder = 1,
				})
				if mark.glyph then
					icons.draw(mark.glyph, glyphHolder, theme.size.icon - 2, theme.color[mark.colour])
				else
					P.statusDot(glyphHolder, {
						diameter = item.status == "active" and theme.size.dot or theme.size.dotSmall,
						color = theme.color[mark.colour],
						anchor = Vector2.new(0.5, 0.5),
						position = UDim2.fromScale(0.5, 0.5),
					})
				end
				-- The marker and the label share one minimum line box. A zero-height
				-- auto label shrank single-line text below its marker; switching active
				-- items to a larger text role moved their centre again.
				P.text(row, {
					name = "TodoText",
					text = item.text,
					role = "small",
					font = item.status == "active" and theme.text.bodyStrong.font or nil,
					face = item.status == "active" and theme.text.bodyStrong.face or nil,
					color = theme.color[mark.text],
					size = UDim2.new(1, -(theme.size.icon + theme.space.xs), 0, theme.text.small.height),
					wrap = true,
					auto = "Y",
					layoutOrder = 2,
				})
			end

			sizePlan()

			-- Follow progress until the user makes a choice, then preserve that choice
			-- across updates and conversation switches.
			local expanded = preference.open
			if expanded == nil then expanded = activeText ~= nil end
			setOpen(expanded)
		end

		-- A change announced for another conversation is somebody else's plan.
		local unsubscribe = state.todosChanged:connect(function(items, session)
			if session ~= handle.session then return end
			rebuild(items)
		end)

		-- Points the strip at a conversation and paints its plan. Called on every
		-- switch, keeping the disclosure choice with the conversation it belongs to.
		function handle.attach(session)
			local changed = handle.session ~= session
			handle.session = session
			if session then
				preferences[session] = preferences[session] or {}
				preference = preferences[session]
			else preference = orphan end
			if changed then list.CanvasPosition = Vector2.new(0, 0) end
			rebuild(state.todoList(session))
		end

		local function cleanup()
			unsubscribe()
			resize:Disconnect()
		end
		shell.Destroying:Connect(cleanup)
		function handle.destroy()
			cleanup()
			pcall(function() shell:Destroy() end)
		end

		handle.attach(props.session)
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/chat/view
-- ==========================================================================
__UAI_MODULES["ui/chat/view"] = (function()
-- The transcript.
--
-- Subscribe before replay, retain the reader's position, and release rows when
-- their activity leaves bounded history. Layout changes never own conversation data.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local message = env.require("ui/chat/message")

	local M = {}

	function M.new(parent, props)
		props = props or {}

		local scroll = P.scroll(parent, {
			name = "Transcript",
			size = props.size or UDim2.new(1, 0, 1, 0),
			gap = theme.space.lg,
			padding = theme.space.lg,
			fade = false,
		})

		local view = {
			scroll = scroll,
			order = 0,
			tools = {},
			agents = {},
			working = nil,
			-- The open activity block, if the transcript is mid-run. Tool calls, the
			-- thinking between them and the notices they raise all go inside it; prose
			-- from either side closes it.
			run = nil,
			agentHandle = nil,
			session = nil,
			unsubscribe = nil,
			pinned = true,
			rows = {},
			runs = {},
			generation = 0,
			lastRenderedId = 0,
		}
		local destroyed, adjusting, layoutQueued = false, false, false
		local visible = props.visible ~= false
		local reading, chunkReading, disclosureReading
		local previousY = 0
		local unread, unreadFailures = 0, 0
		local viewport = env.require("ui/chat/viewport").new(scroll, { defer = function() return view.replaying end })
		props = util.copy(props); props.viewport = viewport
		view.viewport = viewport
		viewport.setVisible(visible)

		local function track(handle, event)
			if not handle or not handle.root or not event or not event.transcriptId then return handle end
			local id = event.transcriptId
			local previous = view.rows[id]
			if previous == handle then return handle end
			if previous and previous.transcriptIds then previous.transcriptIds[id] = nil end
			-- Several retained events can share a disclosure. One destruction listener
			-- per row avoids keeping a listener for every expired reasoning fragment.
			if not handle.transcriptIds then
				handle.transcriptIds = {}
				handle.root.Destroying:Connect(function()
					for tracked in pairs(handle.transcriptIds) do
						if view.rows[tracked] == handle then view.rows[tracked] = nil end
					end
					handle.transcriptIds, handle.thoughtChunks = {}, nil
				end)
			end
			handle.transcriptIds[id] = true
			view.rows[id] = handle
			return handle
		end
		local function setThoughtChunks(handle, chunks)
			handle.thoughtChunks = chunks
			local text, truncated = {}, false
			for _, chunk in ipairs(chunks) do
				text[#text + 1] = chunk.text
				truncated = truncated or chunk.truncated == true
			end
			handle.setText(table.concat(text, "\n\n"), truncated)
		end
		-- Tracking is local to this view. No shared renderer or other chat is mutated.
		local builders = message
		local message = {}
		for name, builder in pairs(builders) do
			local renderer, rendererName = builder, name
			message[name] = function(...)
				local handle = renderer(...)
				if rendererName == "toolRun" then
					view.runs[handle.root] = handle
					handle.root.Destroying:Connect(function()
						view.runs[handle.root] = nil
						if view.run == handle then view.run = nil end
					end)
				elseif rendererName ~= "working" then track(handle, view.renderingEvent) end
				return handle
			end
		end

		local function remember()
			local state = { pinned = view.pinned, y = scroll.instance.CanvasPosition.Y }
			disclosureReading = nil
			chunkReading = not view.pinned and viewport.anchor() or nil
			if not view.pinned then
				local best, bestRoot, distance, firstTop, varied
				for id, handle in pairs(view.rows) do
					local root = handle.root
					local top = root.AbsolutePosition.Y - scroll.instance.AbsolutePosition.Y
					local visible, ancestor = root.Visible, root.Parent
					while visible and ancestor and ancestor ~= scroll.instance do
						if ancestor:IsA("GuiObject") and not ancestor.Visible then visible = false end
						ancestor = ancestor.Parent
					end
					if visible and ancestor == scroll.instance and root.AbsoluteSize.Y > 0 then
						if firstTop ~= nil and firstTop ~= top then varied = true end
						firstTop = firstTop or top
						local gap = math.max(0, top)
						if top + root.AbsoluteSize.Y > 0 and (not distance or gap < distance
							or (gap == distance and bestRoot and root:IsDescendantOf(bestRoot))) then
							best, bestRoot, distance = { id = id, offset = top }, root, gap
						end
					end
				end
				-- Until native layout has measured distinct rows, retain the pixel offset.
				if best and (varied or best.offset < 0) then state.anchor, state.offset = best.id, best.offset end
			end
			reading = state
			if view.session then view.session.viewState = util.copy(state) end
			return state
		end

		local function move(y)
			local previous = adjusting
			adjusting = true
			y = math.max(0, y)
			if math.abs(scroll.instance.CanvasPosition.Y - y) >= 0.5 then
				scroll.instance.CanvasPosition = Vector2.new(0, y)
			end
			previousY = scroll.instance.CanvasPosition.Y
			adjusting = previous
		end

		-- Opening details is an explicit decision to read here. Keep the clicked
		-- header in place even when the conversation had been following live output.
		local activityOptions = { beforeToggle = function(header)
			view.pinned = false
			remember()
			chunkReading = nil
			disclosureReading = { root = header, offset = header.AbsolutePosition.Y - scroll.instance.AbsolutePosition.Y }
			view.repin()
		end }

		local latest = P.button(parent, {
			name = "Latest",
			text = "Jump to latest",
			variant = "secondary",
			icon = "chevron",
			iconDirection = "down",
			radius = theme.radius.pill,
			size = "sm",
			anchor = Vector2.new(0.5, 1),
			position = UDim2.new(0.5, 0, 1, -theme.space.sm),
			zIndex = theme.z.raised,
			onClick = function()
				view.pinned = true
				reading, chunkReading, disclosureReading = nil, nil, nil
				unread, unreadFailures = 0, 0
				move(math.max(scroll.instance.AbsoluteCanvasSize.Y - scroll.instance.AbsoluteWindowSize.Y, 0))
				view.repin()
			end,
		})
		latest.instance.Visible = false
		local function updateLatest()
			latest.instance.Visible = not view.pinned and not view.welcomeCard
			local counts = {}
			if unread > 0 then counts[#counts + 1] = util.pluralise(unread, "new message") end
			if unreadFailures > 0 then counts[#counts + 1] = util.pluralise(unreadFailures, "failure") end
			latest.setText(#counts > 0 and (table.concat(counts, ", ") .. " - Jump to latest") or "Jump to latest")
		end

		-- Use the layout's measured height rather than a circular automatic canvas
		-- calculation through deeply nested automatic-height activity cards.
		scroll.instance.AutomaticCanvasSize = Enum.AutomaticSize.None
		local function syncLayout()
			if destroyed or not visible or not scroll.instance.Parent then return end
			local previous = adjusting
			adjusting = true
			local height = scroll.layout.AbsoluteContentSize.Y
			local pad = scroll.instance:FindFirstChildOfClass("UIPadding")
			if pad then height = height + pad.PaddingTop.Offset + pad.PaddingBottom.Offset end
			if scroll.layout.AbsoluteContentSize.Y > 0 or view.order == 0 then
				local wanted = math.ceil(math.max(0, height))
				if scroll.instance.CanvasSize.Y.Offset ~= wanted then scroll.instance.CanvasSize = UDim2.fromOffset(0, wanted) end
			end
			if view.pinned then
				move(view.welcomeCard and 0 or math.max(scroll.instance.AbsoluteCanvasSize.Y - scroll.instance.AbsoluteWindowSize.Y, 0))
			elseif reading then
				local y = reading.y or 0
				local handle = reading.anchor and view.rows[reading.anchor]
				local chunkY = chunkReading and viewport.restoreAnchor(chunkReading)
				if disclosureReading and disclosureReading.root:IsDescendantOf(scroll.instance) then
					y = scroll.instance.CanvasPosition.Y + disclosureReading.root.AbsolutePosition.Y
						- scroll.instance.AbsolutePosition.Y - disclosureReading.offset
				elseif chunkY then y = chunkY
				elseif handle and handle.root.Parent then
					y = scroll.instance.CanvasPosition.Y + handle.root.AbsolutePosition.Y
						- scroll.instance.AbsolutePosition.Y - (reading.offset or 0)
				end
				move(y)
			end
			updateLatest()
			adjusting = previous
			viewport.wake()
		end

		local function follow(force)
			if destroyed or not visible then return end
			if force then view.pinned = true; reading, chunkReading, disclosureReading = nil, nil, nil; unread, unreadFailures = 0, 0 end
			if layoutQueued then return end
			layoutQueued = true
			clock.delay(0, function()
				if destroyed then return end
				syncLayout(); layoutQueued = false
			end)
		end
		scroll.layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function() follow() end)
		scroll.instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() follow() end)
		scroll.instance:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(function() follow() end)
		scroll.instance:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(function() follow() end)

		-- Restoring a window preserves whether the reader was following new output.
		function view.repin()
			updateLatest()
			follow()
		end

		scroll.instance:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
			local y = scroll.instance.CanvasPosition.Y
			local upward = y < previousY - 0.5
			previousY = y
			if destroyed or adjusting or not visible then return end
			-- Even a small upward scroll means read here. A generous bottom threshold
			-- otherwise grabs the wheel back and snaps the reader down on the next row.
			-- Replay slices can arrive during a native swipe. Programmatic moves already
			-- carry adjusting; replay must not suppress the reader's changed position.
			-- The welcome card follows its top only until the reader scrolls its content.
			view.pinned = view.welcomeCard and y <= theme.space.hair
				or (not view.welcomeCard and not upward and scroll.atBottom(theme.space.hair))
			if view.pinned then unread, unreadFailures = 0, 0 end
			updateLatest()
			remember()
		end)

		local function nextOrder()
			view.order = view.order + 1
			return view.order
		end

		-- The activity block.
		--
		-- A turn's machinery -- the calls, the thinking between them, a retry notice --
		-- used to be a stack of top-level rows, and the transcript deliberately puts a
		-- paragraph's worth of air between top-level rows. Eight calls therefore read as
		-- eight separate events with the reply lost at the bottom, which is the "too much
		-- tool call" this fixes: one block, one paragraph gap around it, tight lines
		-- inside, and a stable summary that opens only when the reader chooses.
		--
		-- Only prose closes it, because prose is what a run is between. Closing on
		-- reasoning instead would give a step-per-call turn one block per call and change
		-- nothing, and putting a later row above an earlier one is not an option: the
		-- block takes its layout order when it opens, so anything that has to sort after
		-- the rows already in it has to go in it.
		local function openRun(name)
			if not view.run then
				view.run = message.toolRun(scroll.instance, nextOrder(), view.renderingEvent and view.renderingEvent.at, activityOptions)
			end
			-- The run's header names the tools it holds, so the name of the call
			-- about to be added travels with the opening of its row.
			if name then view.run.pendingName = name end
			return view.run
		end

		local function closeRun()
			view.run = nil
		end

		local function appendThought(run, event, previewHandle)
			local handle = previewHandle or run.thought
			if not handle or not handle.root.Parent then handle = message.reasoning(run.rows, "", run.slot()) end
			local chunks = handle.thoughtChunks or {}
			local store = view.session and view.session.transcript
			local retained = event.transcriptId and store and store.get(event.transcriptId)
			local source = retained or event
			chunks[#chunks + 1] = { id = event.transcriptId, text = source.text, truncated = source.textTruncated }
			setThoughtChunks(handle, chunks)
			run.thought = track(handle, event)
		end

		-- Where a row belongs: inside the open block, or in the transcript itself.
		local function target()
			if view.run then return view.run.rows, view.run.slot() end
			return scroll.instance, nextOrder()
		end

		local function agentFor(event)
			if not event.id then return nil end
			if not view.agents[event.id] then
				local into, order = target()
				view.agents[event.id] = message.subagent(into, event, order, activityOptions)
			end
			return view.agents[event.id]
		end

		local function clearWorking()
			if view.working then
				pcall(function() view.working.root:Destroy() end)
				view.working = nil
			end
		end

		-- The working row is transient and always belongs at the end of the
		-- transcript, so it takes an order no real row will reach rather than the next
		-- sequential one. Otherwise a tool row created while it is up sorts below it
		-- and the indicator ends up stranded in the middle of the conversation.
		local WORKING_ORDER = 2147483647

		local function ensureWorking()
			if not view.working then
				local request = view.session and view.session.liveRequest
				view.working = message.working(scroll.instance, WORKING_ORDER, request and request.at)
			end
			return view.working
		end

		local function clearPreview()
			local preview = view.preview; view.preview = nil
			if not preview then return end
			if preview.textHandle then preview.textHandle.root:Destroy() end
			if preview.thoughtHandle then
				preview.thoughtHandle.root:Destroy()
				if preview.ownsRun and preview.run.rows.Parent then
					local populated = false
					for _, child in ipairs(preview.run.rows:GetChildren()) do if child:IsA("GuiObject") then populated = true; break end end
					if not populated then preview.run.root:Destroy(); if view.run == preview.run then view.run = nil end end
				end
			end
		end

		local function showPreview(event)
			if not event.streamId then return end
			if view.preview and view.preview.id ~= event.streamId then clearPreview() end
			if not view.preview then view.preview = { id = event.streamId } end
			local preview = view.preview
			view.model = event.model or view.model
			-- Older preview producers only supplied an aggregate limit flag.
			local reasoningLimited = event.reasoningLimited == true or (event.reasoningLimited == nil and event.limited == true)
			local textLimited = event.textLimited == true or (event.textLimited == nil and event.limited == true)
			if util.trim(event.reasoning or "") ~= "" then
				if not preview.thoughtHandle then
					preview.ownsRun = view.run == nil; preview.run = openRun()
					preview.thoughtHandle = message.reasoning(preview.run.rows, "", preview.run.slot())
				end
				local suffix = reasoningLimited and "\n\n[Reasoning preview shortened.]" or ""
				preview.thoughtHandle.setText(event.reasoning .. suffix, reasoningLimited)
			end
			if util.trim(event.text or "") ~= "" then
				if not preview.textHandle then
					closeRun()
					preview.textHandle = message.agent(scroll.instance, "", nextOrder(), view.model, props)
				end
				preview.textHandle.setModel(view.model)
				local suffix = textLimited and "\n\n[Reply preview shortened; waiting for the completed response.]" or ""
				preview.textHandle.stream(event.text .. suffix)
			end
			ensureWorking().set(util.trim(event.text or "") ~= "" and "Receiving reply" or "Receiving reasoning")
			follow()
		end

		function view.empty()
			view.generation = view.generation + 1
			if view.replay then view.replay.events, view.replay.pending = {}, {} end
			view.replaying, view.replay = false, nil
			clearPreview()
			if view.welcomeCard then
				pcall(function() view.welcomeCard:Destroy() end)
				view.welcomeCard = nil
			end
			scroll.clear()
			view.order = 0
			view.lastRenderedId = 0
			view.tools = {}
			view.agents = {}
			view.working = nil
			view.run = nil
			view.agentHandle = nil
			view.model = nil
			view.pinned = true
			view.rows, view.runs = {}, {}
			view.historyNotice, view.issue, view.retentionRevision = nil, nil, nil
			reading, chunkReading, disclosureReading = nil, nil, nil
			unread, unreadFailures = 0, 0
			adjusting = true
			scroll.instance.CanvasSize = UDim2.fromOffset(0, 0)
			move(0)
			adjusting = false
			latest.instance.Visible = false
		end


		-- What an empty conversation shows: the greeting, the activity card, and -- on a
		-- client with nothing configured yet -- the one thing to do about that. The card
		-- itself lives in ui/panels/home, which reads agent/stats.
		function view.greeting()
			if destroyed or not visible then return end
			local providers = env.require("provider/registry")
			if view.welcomeCard then
				pcall(function() view.welcomeCard:Destroy() end)
				view.welcomeCard = nil
			end
			view.welcomeCard = env.require("ui/panels/home").card(scroll.instance, nextOrder(), props)
			move(0)
			if providers.count() == 0 then
				C.emptyState(view.welcomeCard, {
					title = "No provider configured",
					description = "Add an OpenAI-compatible endpoint to start. Anything that speaks /v1/chat/completions works: a hosted API, a relay, or a local server.",
					action = "Open providers",
					onAction = function()
						env.require("ui/app").show("providers")
					end,
					layoutOrder = 5,
				})
			end
		end

		-- Bound the live instance tree as well as the saved log. A retained child
		-- agent moves out of an expired dispatch row before that row is destroyed.
		local function prune()
			local store = view.session and view.session.transcript
			if not store or view.retentionRevision == store.revision then return end
			view.retentionRevision = store.revision
			local retainedRoots = {}
			for id, handle in pairs(view.rows) do if store.get(id) then retainedRoots[handle.root] = true end end
			for id, handle in pairs(view.rows) do
				local root = handle.root
				if not store.get(id) then
					if root.Parent and not retainedRoots[root] then
						for _, child in pairs(view.rows) do
							if retainedRoots[child.root] and child.root:IsDescendantOf(root) then
								local ancestor, nested = child.root.Parent, false
								while ancestor and ancestor ~= root do
									if retainedRoots[ancestor] then nested = true; break end
									ancestor = ancestor.Parent
								end
								if not nested then child.root.LayoutOrder = root.LayoutOrder; child.root.Parent = root.Parent end
							end
						end
						root:Destroy()
					end
					if handle.transcriptIds then handle.transcriptIds[id] = nil end
					view.rows[id] = nil
				end
			end
			local thoughts = {}
			for _, handle in pairs(view.rows) do
				if handle.thoughtChunks and not thoughts[handle] then
					thoughts[handle] = true
					local kept = {}
					for _, chunk in ipairs(handle.thoughtChunks) do
						if not chunk.id or store.get(chunk.id) then kept[#kept + 1] = chunk end
					end
					if #kept ~= #handle.thoughtChunks then setThoughtChunks(handle, kept) end
				end
			end
			for root, run in pairs(view.runs) do
				local populated = false
				if root.Parent then
					for _, child in ipairs(run.rows:GetChildren()) do if child:IsA("GuiObject") then populated = true; break end end
				end
				if not populated then
					if view.run == run then view.run = nil end
					root:Destroy(); view.runs[root] = nil
				end
			end
			for id, handle in pairs(view.tools) do if not handle.root.Parent then view.tools[id] = nil end end
			for id, handle in pairs(view.agents) do if not handle.root.Parent then view.agents[id] = nil end end
			if view.run and view.run.thought and not view.run.thought.root.Parent then view.run.thought = nil end
			if view.agentHandle and not view.agentHandle.root.Parent then view.agentHandle = nil end
			local notes = {}
			if store.omitted.conversation > 0 then notes[#notes + 1] = "Older messages reached the saved-history limit. Recent messages remain available." end
			if store.omitted.activity + store.omitted.lifecycle > 0 then notes[#notes + 1] = "Older activity details were removed to keep this conversation responsive." end
			if store.recovered > 0 then notes[#notes + 1] = "Some messages were recovered from saved context." end
			if #notes > 0 then
				if not view.historyNotice then
					view.historyNotice = P.text(scroll.instance, { name = "HistoryNotice", role = "caption", wrap = true,
						auto = "Y", color = theme.color.textTertiary, layoutOrder = -2 })
				end
				view.historyNotice.Text = table.concat(notes, " ")
			end
			follow()
		end

		-- One event in, one row out. Anything not listed is deliberately ignored:
		-- the log carries more than a transcript should show.
		function view.render(event)
			if destroyed or not visible then return end
			view.renderingEvent = event
			if event.kind == "user" then
				clearPreview()
				clearWorking()
				closeRun()
				if view.welcomeCard then
					pcall(function() view.welcomeCard:Destroy() end)
					view.welcomeCard = nil
				end
				view.agentHandle = nil
				message.user(scroll.instance, event.text, nextOrder(), props)
				follow(not view.replaying)
			elseif event.kind == "status" then
				if event.text and event.text ~= "Ready" then
					ensureWorking().set(event.text)
					follow()
				elseif event.text == "Ready" then
					clearPreview()
					clearWorking()
				end
			elseif event.kind == "request:start" then
				clearPreview()
				view.model = event.model or event.provider
				-- Buffered HTTP provides no frames while the request is pending.
				ensureWorking().set("Waiting for " .. tostring(event.provider))
				follow()
			elseif event.kind == "assistant:preview" then
				showPreview(event)
			elseif event.kind == "assistant:complete" then
				clearPreview()
			elseif event.kind == "request:done" and event.error then
				clearPreview()
			elseif event.kind == "assistant:reasoning" then
				if util.trim(event.text or "") == "" then return end
				local preview = view.preview
				if preview and preview.id == event.streamId and preview.thoughtHandle then
					appendThought(preview.run, event, preview.thoughtHandle); preview.thoughtHandle = nil
				else
					appendThought(openRun(), event)
				end
				follow()
			elseif event.kind == "assistant:text" then
				local trimmed = util.trim(event.text or "")
				if trimmed ~= "" and trimmed ~= "..." and trimmed ~= "…" then
					clearWorking()
					closeRun()
					view.model = event.model or view.model
					local preview = view.preview
					if preview and preview.id == event.streamId and preview.textHandle then
						preview.textHandle.finish(event.text, view.model); view.agentHandle = track(preview.textHandle, event); preview.textHandle = nil
					else view.agentHandle = message.agent(scroll.instance, event.text, nextOrder(), view.model, props) end
					if not view.replaying and not view.pinned then unread = unread + 1 end
					follow()
				end
			elseif event.kind == "tool:call" then
				-- The working row deliberately survives a tool call: it is the "this
				-- turn is still running" indicator and it sorts last, so it stays put
				-- below the tool rows instead of being destroyed and rebuilt -- which
				-- restarted the spinner's phase and left the following request with no
				-- indicator at all.
				local run = openRun(event.name)
				run.thought = nil
				local handle = message.toolCall(run.rows, event, run.slot(), activityOptions)
				handle.run = run
				run.opened()
				view.tools[event.id or util.uid("tool")] = handle
				follow()
			elseif event.kind == "tool:progress" then
				local handle = event.id and view.tools[event.id]
				-- Older hosts may emit unaddressed progress. It is only unambiguous
				-- when a single call is open; never copy it onto unrelated parallel work.
				if not event.id and util.count(view.tools) == 1 then
					local _, only = next(view.tools)
					handle = only
				end
				if handle and handle.progress then handle.progress(event.text) end
				follow()
			elseif event.kind == "tool:result" or event.kind == "tool:error" then
				local failed = event.kind == "tool:error" or event.ok == false
				local handle = view.tools[event.id]
				if handle then
					handle.finish(event)
					track(handle, event)
					if handle.run then handle.run.closed(not failed, event.at, handle) end
					view.tools[event.id] = nil
				else
					local run = openRun(event.name)
					handle = message.toolCall(run.rows, { name = event.name, arguments = "" }, run.slot(), activityOptions)
					handle.run = run
					run.opened(); handle.finish(event); track(handle, event); run.closed(not failed, event.at, handle)
				end
