		end
		navigate = function(id)
			local known = false; for _, item in ipairs(destinations) do if item.id == id then known = true; break end end
			if not known then return end
			store.preference("destination", id)
			if views["Large source"] and (not store.workspace.sourceId or views["Large source"].sourceId ~= store.workspace.sourceId) then
				views["Large source"].destroy(); containers["Large source"]:Destroy(); views["Large source"], containers["Large source"] = nil, nil
			end
			layout(); sync()
		end
		local offStore = store.changed:connect(function(event)
			if activeDocument ~= store.activeId() or activeDestination ~= store.workspace.destination or activeSource ~= store.workspace.sourceId then
				cancelSource()
				activeDocument, activeDestination, activeSource = store.activeId(), store.workspace.destination, store.workspace.sourceId
			end
			sync(); if event.kind == "large_source" or event.kind == "preference" then layout() end
		end)
		local offStorage = store.storageChanged:connect(sync)
		local offRun = runner.changed:connect(function(event) sync(); if event.kind == "rejected" then common.message(nil, event.text) end end)
		local offCapture = capture.changed:connect(sync)
		local function held(name) local ok, result = pcall(function() return env.uis:IsKeyDown(Enum.KeyCode[name]) end); return ok and result end
		local input = env.uis.InputBegan:Connect(function(key, processed)
			if not panel.visible or not panel.alive or not root.Visible then return end
			local app = env.require("ui/app"); if app.panel ~= "code" or (app.window and not app.window.visible) or #overlay.open > 0 then return end
			local focused = env.uis:GetFocusedTextBox()
			if focused and (not editor() or focused ~= editor().box) then return end
			local modifier = held("LeftControl") or held("RightControl") or held("LeftMeta") or held("RightMeta")
			if modifier then
				local editing = store.workspace.destination == "Editor"
				if key.KeyCode == Enum.KeyCode.Return and store.workspace.destination == "Editor" then run()
				elseif key.KeyCode == Enum.KeyCode.S and editing then save(held("LeftShift") or held("RightShift"))
				elseif key.KeyCode == Enum.KeyCode.F and (held("LeftShift") or held("RightShift")) then workspaceSearch(true)
				elseif key.KeyCode == Enum.KeyCode.F and editing then find()
				elseif key.KeyCode == Enum.KeyCode.P then workspaceSearch(false)
				elseif key.KeyCode == Enum.KeyCode.O then navigate("Files")
				elseif key.KeyCode == Enum.KeyCode.G and editing then position()
				elseif key.KeyCode == Enum.KeyCode.T and (held("LeftShift") or held("RightShift")) then if common.message(store.reopen()) then navigate("Editor") end
				elseif key.KeyCode == Enum.KeyCode.Tab then common.message(store.cycle((held("LeftShift") or held("RightShift")) and -1 or 1)); navigate("Editor")
				elseif key.KeyCode == Enum.KeyCode.Slash and editing then transform("comment")
				elseif key.KeyCode == Enum.KeyCode.N then newDocument()
				elseif key.KeyCode == Enum.KeyCode.Z and editing and not focused and not store.workspace.sourceId then if held("LeftShift") or held("RightShift") then common.message(store.redoSource()) else common.message(store.undoSource()) end end
			elseif focused and key.KeyCode == Enum.KeyCode.Tab then editor().indent(held("LeftShift") or held("RightShift"))
			elseif not focused and not processed then
				local view = views[store.workspace.destination]
				if view and view.list then
					if key.KeyCode == Enum.KeyCode.Up or key.KeyCode == Enum.KeyCode.DPadUp then view.list.move(-1)
					elseif key.KeyCode == Enum.KeyCode.Down or key.KeyCode == Enum.KeyCode.DPadDown then view.list.move(1)
					elseif key.KeyCode == Enum.KeyCode.PageUp then view.list.page(-1)
					elseif key.KeyCode == Enum.KeyCode.PageDown then view.list.page(1)
					elseif key.KeyCode == Enum.KeyCode.Home then view.list.edge(false)
					elseif key.KeyCode == Enum.KeyCode.End then view.list.edge(true)
					elseif key.KeyCode == Enum.KeyCode.Left and view.list.toggle then view.list.toggle(false)
					elseif key.KeyCode == Enum.KeyCode.Right and view.list.toggle then view.list.toggle(true)
					elseif key.KeyCode == Enum.KeyCode.Return then view.list.activate() end
				end
			end
		end)
		root:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout)
		local offResponsive = responsive.changed:connect(layout)
		local rootDestroying = false
		function panel.setVisible(visible) panel.visible = visible; if not visible then cancelSource() end; layout(); sync() end
		function panel.destroy()
			if not panel.alive then return end; panel.alive = false
			input:Disconnect(); offStore(); offStorage(); offRun(); offCapture(); offResponsive(); fileDivider.destroy(); outputDivider.destroy()
			for _, view in pairs(views) do if view.destroy then view.destroy() end end
			cancelSource(); store.saveNow(); if not rootDestroying then surface:Destroy() end
		end
		surface.Destroying:Connect(function() rootDestroying = true; panel.destroy() end)
		panel.navigate, panel.views = navigate, views
		layout(); sync(); return panel
	end
	return M
end
end)()

-- ==========================================================================
-- ui/panels/cowork
-- ==========================================================================
__UAI_MODULES["ui/panels/cowork"] = (function()
-- Cowork: the browser-shared conversation.
--
-- The mode switch in the sidebar offers "Cowork" beside "Code", and in the client
-- this is modelled on that means real-time pairing. There is exactly one thing here
-- that genuinely is two people in one conversation -- the local web bridge -- so that
-- is what this panel is: its live state, its switch, and the two values it needs.
--
-- A Roblox client cannot accept a connection, so both sides dial out to a small
-- process on the same machine. That is why this panel is mostly about whether that
-- process is reachable, and why it says so in those words rather than showing a
-- spinner.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local bridge = env.require("net/bridge")
	local sessions = env.require("agent/session")
	local relayLink = env.require("net/relay_link")

	local M = {}

	function M.new(parent)
		local panel = {}
		local mobile = relayLink.mobile()
		local scroll = P.scroll(parent, {
			name = "Cowork",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.lg,
			padding = theme.space.lg,
		})

		P.sectionHeader(scroll.instance, {
			title = "Cowork",
			description = mobile
				and ("Start UAI Relay on this phone and the script pairs with it automatically, so long replies survive the "
					.. "executor's request limit. Messages, tools, and permissions stay connected to this Roblox session.")
				or ("Open UAI Bridge on this computer and click Start Cowork. The desktop app connects automatically. "
					.. "Messages, tools, and permissions stay connected to this Roblox session."),
			layoutOrder = 1,
		})

		M.rows(scroll.instance, { layoutOrder = 2 })

		panel.scroll = scroll
		return panel
	end

	-- The live state and the two values it needs, as cards a caller drops into its own
	-- column. Both the Cowork panel and the settings dialog's Cowork pane use this, so
	-- there is one description of the bridge rather than two that can disagree.
	function M.rows(container, props)
		props = props or {}
		local order = (props.layoutOrder or 1) - 1
		local function nextOrder()
			order = order + 1
			return order
		end
		local mobile = relayLink.mobile()

		-- The companion relay is the mobile answer to the executor's request limit. It
		-- is independent of the Cowork link, so it gets its own card, its own mode and
		-- its own actions rather than being folded into the manual bridge below.
		local relayCard = P.card(container, { name = "RelayCompanion", layoutOrder = nextOrder(), gap = theme.space.sm })
		P.text(relayCard, { text = "Mobile relay (companion app)", role = "label", layoutOrder = 1 })
		P.text(relayCard, {
			text = "Start UAI Relay on this phone. The script hands long provider requests to it, so the executor's request limit "
				.. "cannot cut them off. Pairing is automatic; no token copying.",
			role = "caption", wrap = true, auto = "Y", layoutOrder = 2 })
		local relayRow = P.row(relayCard, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm, layoutOrder = 3 })
		local relayDot = P.statusDot(relayRow, { diameter = theme.size.dot, color = theme.color.textTertiary, layoutOrder = 1 })
		local relayText = P.text(relayRow, {
			name = "RelayStatusText", text = "", role = "small", color = theme.color.text, wrap = true,
			auto = "Y", size = UDim2.new(0, 0, 0, 0), flex = "Fill", layoutOrder = 2 })
		local relayDetail = P.text(relayCard, {
			name = "RelayStatusDetail", text = "", role = "monoSmall", color = theme.color.textSecondary,
			wrap = true, auto = "Y", layoutOrder = 4 })
		relayDetail.Size = UDim2.new(1, 0, 0, 0)
		local function describeRelay()
			local status = relayLink.status()
			local token = tostring(config.get("relay.token", ""))
			if status.state == "ready" then
				relayDot.BackgroundColor3 = theme.color.success
				relayText.Text = "Companion connected. Long replies are relayed through this phone."
			elseif status.mode == "off" then
				relayDot.BackgroundColor3 = theme.color.textTertiary
				relayText.Text = "Relay mode is off, so the script calls providers directly."
			elseif not caps.has("http") then
				relayDot.BackgroundColor3 = theme.color.warn
				relayText.Text = "This host has no HTTP transport, so the companion cannot be reached."
			else
				relayDot.BackgroundColor3 = theme.color.warn
				relayText.Text = status.state == "searching" and "Looking for the companion app…"
					or "Companion connection failed. Check the details below, then press Scan now."
			end
			local parts = { "port " .. tostring(status.port) }
			if status.server ~= "" then parts[#parts + 1] = "server " .. status.server end
			if #token > 10 then parts[#parts + 1] = "paired ···" .. token:sub(-4) end
			if (status.placeId or 0) > 0 then parts[#parts + 1] = "place " .. tostring(status.placeId) end
			if status.error then parts[#parts + 1] = tostring(status.error) end
			if status.kilo then parts[#parts + 1] = "Kilo: " .. status.kilo.state .. " - " .. status.kilo.message end
			relayDetail.Text = table.concat(parts, "  ·  ")
		end
		local relayMode = C.segmented(relayCard, {
			options = { { label = "Auto", value = "auto" }, { label = "Always", value = "always" }, { label = "Off", value = "off" } },
			value = config.get("relay.mode", "auto"), layoutOrder = 5,
			onChange = function(value) config.set("relay.mode", value) end })
		local relayButtons = P.row(relayCard, { size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true, gap = theme.space.sm, layoutOrder = 6 })
		P.button(relayButtons, {
			name = "RelayScan", text = "Scan now", variant = "secondary", size = "sm", layoutOrder = 1,
			onClick = function(button)
				button.setEnabled(false)
				button.setText("Scanning…")
				local ok, err = relayLink.scan()
				if not relayCard.Parent then return end
				button.setEnabled(true)
				button.setText("Scan now")
				describeRelay()
				if not ok then overlay.toast(tostring(err or "No companion answered on that port"), "warn", 3) end
			end })
		P.button(relayButtons, {
			name = "RelayUnpair", text = "Reset pairing", variant = "ghost", size = "sm", layoutOrder = 2,
			onClick = function()
				relayLink.forget()
				describeRelay()
				overlay.toast("Pairing reset", "good", 2)
			end })

		local desktopCard
		local autoToggle
		if not mobile then
			desktopCard = P.card(container, { name = "DesktopBridge", layoutOrder = nextOrder(), gap = theme.space.sm })
			P.text(desktopCard, { text = "UAI Bridge desktop app", role = "label", layoutOrder = 1 })
			P.text(desktopCard, { text = "Click Start Cowork in UAI Bridge.exe. This script finds it on port 28791 and reconnects when the app restarts. No token copying is needed. Manual connections below take priority when enabled.",
				role = "caption", wrap = true, auto = "Y", layoutOrder = 2 })
			local autoRow = P.row(desktopCard, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm, layoutOrder = 3 })
			P.text(autoRow, { text = "Find desktop app automatically", role = "small", flex = "Fill", layoutOrder = 1 })
			autoToggle = C.switch(autoRow, { value = config.get("bridge.autoDiscover", true) == true,
				onChange = function(value) config.set("bridge.autoDiscover", value) end })
			autoToggle.instance.Name = "AutoDiscoverDesktop"
			autoToggle.instance.LayoutOrder = 2
		end

		local statusCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })

		local statusRow = P.row(statusCard, {
			name = "Status",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		local dot = P.statusDot(statusRow, {
			diameter = theme.size.dot,
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		local statusText = P.text(statusRow, {
			name = "StatusText",
			text = "",
			role = "small",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			size = UDim2.new(0, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 2,
		})

		local detail = P.text(statusCard, {
			name = "StatusDetail",
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		detail.Size = UDim2.new(1, 0, 0, 0)

		-- Everything on this row is a fact about the running bridge rather than a
		-- control, which is why it is text and not a badge: three of the four values are
		-- only interesting when something is wrong.
		local runtimeText
		local function describe()
			local status = bridge.status()
			local shared = sessions.current()
			if runtimeText then runtimeText.Text = status.online and "Web runtime · Connected" or "Game runtime · No bridge connection" end
			if not status.running then
				dot.BackgroundColor3 = theme.color.textTertiary
				statusText.Text = status.searching and "Looking for UAI Bridge. Click Start Cowork in the desktop app."
					or "Not connected. Enable automatic discovery or configure a manual bridge below."
				detail.Text = string.format("%s\nwould share: %s", status.url, shared.title)
				return
			end
			if status.online then
				dot.BackgroundColor3 = theme.color.success
				statusText.Text = status.source == "desktop" and "Desktop app connected automatically. Cowork is ready."
					or "Connected. Open the browser link and start chatting."
				detail.Text = string.format("%s\nsharing: %s\nqueued: %d", status.url, shared.title, status.queued or 0)
				if status.kilo then detail.Text = detail.Text .. "\nKilo: " .. status.kilo.state .. " - " .. status.kilo.message end
				if status.cline then detail.Text = detail.Text .. "\nCline: " .. status.cline.state .. " - " .. status.cline.message end
				return
			end
			dot.BackgroundColor3 = theme.color.warn
			statusText.Text = status.source == "desktop" and "Desktop app found. Connecting to Cowork..."
				or "Waiting for the manual bridge. Check its token and port."
			detail.Text = string.format("%s\n%s", status.url, tostring(status.error or "no answer yet"))
		end

		local switchRow = P.row(statusCard, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 3,
		})
		local switchText = P.column(switchRow, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(switchText, { text = "Manual bridge enabled", role = "small" })
		P.text(switchText, {
			text = "Use this for terminal-based setup. Turn it off to use desktop discovery.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local toggle = C.switch(switchRow, {
			value = config.get("bridge.enabled", false) == true,
			onChange = function(value) config.set("bridge.enabled", value) end,
		})
		toggle.instance.LayoutOrder = 2

		if not caps.has("http") then
			local warning = P.text(statusCard, {
				text = "This host has no HTTP transport, so the bridge cannot be reached from here at all.",
				role = "caption",
				color = theme.color.warn,
				wrap = true,
				auto = "Y",
				layoutOrder = 4,
			})
			warning.Size = UDim2.new(1, 0, 0, 0)
		end

		-- Every row in here states its order.
		--
		-- All six were LayoutOrder 0, so the label above the port field, the field, the
		-- label above the token field, that field, the hint and the button row were sorted
		-- by whatever the tie-break happened to produce -- which is a card whose two
		-- labels can end up over the wrong two fields.
		-- The Node installer is desktop setup; on a phone it is noise.
		if not mobile then
			local installerCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
			P.text(installerCard, { text = "Manual setup: download and start", role = "label", layoutOrder = 1 })
			local installStatus = P.text(installerCard, { name = "BridgeDownloadStatus",
				text = "Install Node.js 18+ on this computer. Download the files, then open a terminal in your executor workspace (the folder containing UAI). Run: node UAI/bridge/start.txt",
				role = "caption", wrap = true, auto = "Y", layoutOrder = 2 })
			P.button(installerCard, { name = "DownloadBridge", text = "Download bridge files", icon = "folder",
				variant = "secondary", size = "sm", fill = true, layoutOrder = 3,
				onClick = function(button)
					button.setEnabled(false)
					button.setText("Downloading…")
					task.spawn(function()
						local ok, message = env.require("runtime/bridge_install").download(function(text)
							if installStatus.Parent then installStatus.Text = text end
						end)
						if not installerCard.Parent then return end
						installStatus.Text = message
						button.setText(ok and "Download again" or "Retry download")
						button.setEnabled(true)
						overlay.toast(ok and "Bridge files downloaded" or message, ok and "good" or "warn", 4)
					end)
				end })
			if caps.clipboard then
				P.button(installerCard, { name = "CopyBridgeStart", text = "Copy start command", variant = "ghost", size = "sm", fill = true, layoutOrder = 4,
					onClick = function()
						local ok = env.require("runtime/clipboard").write("node " .. env.require("runtime/fsx").root .. "/bridge/start.txt")
						overlay.toast(ok and "Start command copied" or "Could not reach the clipboard", ok and "good" or "warn", 2)
					end })
			end
			P.text(installerCard, { text = "No npm install or file renaming needed. Keep the terminal and Roblox open. From a Git checkout, run node bridge/server.js instead.",
				role = "caption", wrap = true, auto = "Y", layoutOrder = 5 })
		end
		local settings = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
		P.text(settings, { text = "Manual connection", role = "label", layoutOrder = 0 })
		local runtimeCard = P.card(container, { layoutOrder = nextOrder(), gap = theme.space.sm })
		P.text(runtimeCard, { text = "Automatic runtime", role = "label", layoutOrder = 1 })
		P.text(runtimeCard, { text = "Connecting to Cowork automatically selects Web for live replies. Disconnecting returns new requests to Game. Tools and permissions stay in Roblox. Open the browser link to start chatting.",
			role = "caption", wrap = true, auto = "Y", layoutOrder = 2 })
		runtimeText = P.text(runtimeCard, { name = "BridgeRuntimeStatus", text = "", role = "small", wrap = true, auto = "Y", layoutOrder = 3 })
		P.text(runtimeCard, { text = "Bridge replies have no time limit. Use Stop to cancel a reply.", role = "caption", wrap = true, auto = "Y", layoutOrder = 4 })
		P.text(settings, { text = "Port", role = "small", layoutOrder = 1 })
		P.field(settings, {
			name = "BridgePort",
			text = tostring(config.get("bridge.port", 8790)),
			placeholder = "8790",
			layoutOrder = 2,
			onBlur = function(text)
				local port = tonumber(util.trim(text))
				config.set("bridge.port", (port and port > 0 and port < 65536) and math.floor(port) or 8790)
			end,
		})
		P.text(settings, { text = "Token", role = "small", layoutOrder = 3 })
		P.field(settings, {
			name = "BridgeToken",
			text = tostring(config.get("bridge.token", "")),
			placeholder = "paste the Token from your terminal",
			layoutOrder = 4,
			onBlur = function(text) config.set("bridge.token", util.trim(text)) end,
		})
		local tokenHint = P.text(settings, {
			text = "Match the port printed in the terminal, paste its Token, then turn Enabled on above. After restarting the bridge, paste the new token and reopen its browser link.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 5,
		})
		tokenHint.Size = UDim2.new(1, 0, 0, 0)

		local buttons = P.row(settings, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.sm,
			layoutOrder = 6,
		})
		if caps.clipboard then
			P.button(buttons, {
				name = "CopyBridgeUrl",
				text = "Copy address",
				variant = "secondary",
				size = "sm",
				layoutOrder = 1,
				onClick = function()
					local ok = env.require("runtime/clipboard").write(bridge.status().url)
					overlay.toast(ok and "Address copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				end,
			})
		end
		P.button(buttons, {
			name = "Reconnect",
			text = "Reconnect",
			variant = "ghost",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				-- Stop then sync: the poller backs off up to ten seconds between
				-- attempts, and after starting the server on the other side nobody wants
				-- to wait out the backoff.
				bridge.stop()
				local ok, why = bridge.sync()
				if not ok and why then overlay.toast(tostring(why), "warn", 3) end
				describe()
			end,
		})

		describe()
		describeRelay()
		local unsubscribeConfig = config.changed:connect(function(path)
			if autoToggle and (path == nil or path == "bridge" or path == "bridge.autoDiscover") then
				autoToggle.set(config.get("bridge.autoDiscover", true) == true, true)
			end
			if path == nil or path == "bridge" or path == "bridge.enabled" then
				toggle.set(config.get("bridge.enabled", false) == true, true)
			end
			if path == nil or path == "relay" or util.startsWith(tostring(path), "relay.") then
				relayMode.set(config.get("relay.mode", "auto"))
				describeRelay()
			end
		end)
		local unsubscribeBridge = bridge.changed:connect(function()
			if not statusCard.Parent then return end
			describe()
		end)
		local unsubscribeRelay = relayLink.changed:connect(function()
			if not relayCard.Parent then return end
			describeRelay()
		end)
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not statusCard.Parent then return end
			describe()
		end)
		statusCard.Destroying:Connect(function()
			pcall(unsubscribeBridge)
			pcall(unsubscribeSessions)
			pcall(unsubscribeConfig)
			pcall(unsubscribeRelay)
		end)

		return statusCard
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/home
-- ==========================================================================
__UAI_MODULES["ui/panels/home"] = (function()
-- The home card: the greeting, the activity summary and the contribution grid.
--
-- Every number on this surface is read from agent/stats, which counts what the
-- client actually observed. There are no placeholders here and no sample data: a
-- figure with nothing behind it is rendered as a zero and the card says why, because
-- an invented number on a dashboard is worse than an empty one -- it cannot be told
-- from a real one.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local stats = env.require("agent/stats")

	local M = {}

	local function levelColour(level)
		if level >= 4 then return theme.color.activityBlueDark end
		if level >= 3 then return theme.color.activityBlue end
		if level >= 2 then return theme.color.activityBlueLight end
		if level >= 1 then return theme.color.accentMuted end
		return theme.color.activityCell
	end

	-- The four sentences a cell can say, all of them about a real day.
	local function describeCell(cell, todayKey)
		local when = clock.describeDay(cell.key, todayKey)
		if not cell.active then
			return when .. " -- nothing recorded", "info"
		end
		local parts = {}
		if cell.messages > 0 then parts[#parts + 1] = util.pluralise(cell.messages, "message") end
		if cell.requests > 0 then parts[#parts + 1] = util.pluralise(cell.requests, "request") end
		if cell.tokens > 0 then parts[#parts + 1] = util.formatCompact(cell.tokens) .. " tokens" end
		return when .. " -- " .. table.concat(parts, ", "), "good"
	end

	-- One metric. The tile shows the short form; the exact figure and what it counts
	-- live in the Usage pane, which is where the click goes.
	local function tile(parent, spec, order)
		local holder = P.rowButton(parent, {
			name = "Metric_" .. tostring(spec.key),
			vertical = true,
			size = UDim2.fromOffset(0, theme.size.statTile),
			height = theme.size.statTile,
			bg = theme.color.surfaceRaised,
			radius = theme.radius.none,
			gap = theme.space.hair,
			padding = { x = theme.space.sm, y = theme.space.xs },
			alignY = "Center",
			layoutOrder = order,
			onClick = function()
				env.require("ui/app").showSettingsDialog("usage")
			end,
		})
		P.text(holder.row, {
			name = "Title",
			text = spec.label,
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			size = UDim2.new(1, 0, 0, theme.text.caption.height),
			layoutOrder = 1,
		})
		P.text(holder.row, {
			name = "Value",
			text = spec.value,
			role = "title",
			color = spec.tone or theme.color.text,
			truncate = true,
			size = UDim2.new(1, 0, 0, theme.text.title.height),
			layoutOrder = 2,
		})
		return holder
	end

	-- A small pill that is either the selected one or not. Used for both the tab pair
	-- and the range triple, because they are the same control with different contents.
	local function pill(parent, label, selected, order, onClick)
		local handle = P.rowButton(parent, {
			name = "Pill_" .. tostring(label),
			auto = "X",
			height = math.max(theme.size.chip, responsive.minTarget()),
			size = UDim2.fromOffset(0, math.max(theme.size.chip, responsive.minTarget())),
			bgSelected = theme.color.surfaceActive,
			radius = theme.radius.sm,
			padding = { x = theme.space.sm },
			selected = selected,
			layoutOrder = order,
			onClick = onClick,
		})
		P.text(handle.row, {
			text = label,
			role = "caption",
			color = selected and theme.color.text or theme.color.textTertiary,
			auto = "X",
			layoutOrder = 1,
		})
		return handle
	end

	-- The eight figures the overview shows, in the order the reference client puts
	-- them in. Each one names the window it was computed over, because "4 active days"
	-- means something different under All than under 7d.
	local function overviewTiles(window)
		local model = window.topModel
		local modelName = "--"
		if model then modelName = model.id end
		local peak = "--"
		if window.peakHour then peak = clock.describeHour(window.peakHour) end
		return {
			{ key = "sessions", label = "Sessions", value = util.formatNumber(window.sessions) },
			{ key = "messages", label = "Messages", value = util.formatNumber(window.messages) },
			{ key = "tokens", label = "Total tokens", value = util.formatCompact(window.tokens) },
			{ key = "days", label = "Active days", value = util.formatNumber(window.activeDays) },
			{ key = "streak", label = "Current streak", value = tostring(window.currentStreak) .. "d" },
			{ key = "longest", label = "Longest streak", value = tostring(window.longestStreak) .. "d" },
			{ key = "peak", label = "Peak hour", value = peak },
			{ key = "model", label = "Favorite model", value = modelName },
		}
	end

	local function buildOverview(parent, window)
		local box = P.frame(parent, {
			name = "MetricsBox",
			size = UDim2.new(1, 0, 0, 0),
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			layoutOrder = 1,
		})
		P.stroke(box, theme.color.borderSubtle)

		local specs = overviewTiles(window)
		local tiles, minWidth = {}, 0
		for index, spec in ipairs(specs) do
			tiles[index] = tile(box, spec, index).instance
			minWidth = math.max(minWidth, P.measureText(spec.label, { role = "caption" }).X + theme.space.sm * 2)
		end
		local function fitTiles()
			local gap = theme.space.hair
			local width = math.max(1, box.AbsoluteSize.X - gap * 2)
			local perRow = width >= minWidth * 4 + gap * 3 and 4 or (width >= minWidth * 2 + gap and 2 or 1)
			local height = math.max(theme.size.statTile, theme.text.caption.height + theme.text.title.height + gap + theme.space.xs * 2)
			local cellWidth = math.max(1, (width - gap * (perRow - 1)) / perRow)
			for index, entry in ipairs(tiles) do
				entry.Size = UDim2.fromOffset(cellWidth, height)
				entry.Position = UDim2.fromOffset(gap + ((index - 1) % perRow) * (cellWidth + gap),
					gap + math.floor((index - 1) / perRow) * (height + gap))
			end
			box.Size = UDim2.new(1, 0, 0, math.ceil(#tiles / perRow) * (height + gap) + gap)
		end
		box:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitTiles)
		fitTiles()
		return box
	end

	local function buildModels(parent, window)
		local box = P.column(parent, {
			name = "ModelsBox",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.hair,
			layoutOrder = 1,
		})
		P.stroke(box, theme.color.borderSubtle)

		if #window.models == 0 then
			local empty = P.text(box, {
				name = "NoModels",
				text = "No requests recorded in this window. A model appears here once it has answered something.",
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				padding = { x = theme.space.sm, y = theme.space.sm },
				layoutOrder = 1,
			})
			empty.Size = UDim2.new(1, 0, 0, 0)
			return box
		end

		for index, row in ipairs(window.models) do
			local entry = P.column(box, {
				name = "Model_" .. tostring(index),
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				bg = theme.color.surfaceRaised,
				gap = theme.space.hair,
				padding = { x = theme.space.sm, y = theme.space.xs },
				layoutOrder = index,
			})
			local head = P.row(entry, {
				size = UDim2.new(1, 0, 0, theme.text.small.height),
				gap = theme.space.xs,
				layoutOrder = 1,
			})
			P.text(head, {
				name = "Id",
				text = row.id,
				role = "small",
				color = theme.color.text,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.small.height),
				flex = "Fill",
				layoutOrder = 1,
			})
			P.text(head, {
				name = "Share",
				text = string.format("%d%%", math.floor((row.share or 0) * 100 + 0.5)),
				role = "monoSmall",
				color = theme.color.accent,
				align = "Right",
				auto = "X",
				layoutOrder = 2,
			})

			local track = P.frame(entry, {
				name = "Bar",
				size = UDim2.new(1, 0, 0, theme.size.track),
				bg = theme.color.surfaceActive,
				radius = theme.radius.pill,
				layoutOrder = 2,
			})
			P.frame(track, {
				name = "Fill",
				size = UDim2.fromScale(util.clamp(row.share or 0, 0, 1), 1),
				bg = theme.color.accent,
				radius = theme.radius.pill,
			})

			local facts = { util.formatCompact(row.tokens) .. " tokens",
				util.pluralise(row.requests, "request") }
			local cost = env.require("agent/usage").formatCost(row.cost)
			if cost ~= "" then facts[#facts + 1] = cost .. " known est." end
			if (row.unpriced or 0) > 0 then facts[#facts + 1] = util.pluralise(row.unpriced, "request") .. " with unknown cost" end
			local detail = P.text(entry, {
				name = "Detail",
				text = table.concat(facts, "  ") .. (window.estimated and "  (some estimated)" or ""),
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true, auto = "Y",
				size = UDim2.new(1, 0, 0, 0),
				layoutOrder = 3,
			})
			detail.Name = "Detail"
		end
		return box
	end

	local function buildHeatmap(parent, order)
		local map = stats.heatmap(26)
		local todayKey = clock.dayKey()
		local holder = P.column(parent, {
			name = "Heatmap",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.surfaceOverlay,
			radius = theme.radius.md,
			padding = theme.space.sm,
			gap = theme.space.hair,
			layoutOrder = order,
		})
		P.stroke(holder, theme.color.borderSubtle)

		-- Rows are weekdays and columns are weeks, which is the arrangement that makes
		-- a habit visible: a column is a week of work, a row is "every Tuesday".
		for weekday = 1, 7 do
			local row = P.row(holder, {
				name = "Week_" .. clock.weekdayName(weekday),
				size = UDim2.new(1, 0, 0, theme.size.cell),
				maxSize = Vector2.new(#map.columns * theme.size.cell + (#map.columns - 1) * theme.space.hair, math.huge),
				gap = theme.space.hair,
				layoutOrder = weekday,
			})
			for column = 1, #map.columns do
				local cell = map.columns[column][weekday]
				local button = P.rowButton(row, {
					name = "Cell_" .. cell.key,
					size = UDim2.fromOffset(theme.size.cell, theme.size.cell),
					height = theme.size.cell,
					bg = cell.future and theme.color.surfaceOverlay or levelColour(cell.level),
					bgHover = theme.color.solid,
					radius = theme.radius.xs,
					padding = theme.space.none,
					layoutOrder = column,
					onClick = function()
						if cell.future then
							overlay.toast(clock.describeDay(cell.key, todayKey) .. " -- not yet", "info", 2)
							return
						end
						local text, tone = describeCell(cell, todayKey)
						overlay.toast(text, tone, 2.5)
					end,
				})
				-- A cell is eleven pixels square: the hit-target floor would make it a
				-- button the size of the whole row, so this one control opts out and the
				-- grid stays a grid.
				button.instance.Size = UDim2.new(1 / #map.columns,
				-theme.space.hair * (#map.columns - 1) / #map.columns, 0, theme.size.cell)
			end
		end
		return holder
	end

	-- The card, and the greeting above it. `order` is the layout order inside whatever
	-- column it is being dropped into -- the transcript, in practice.
	function M.card(parent, order, props)
		props = props or {}
		local name = "there"
		local okName, display = pcall(function()
			return env.plr and env.plr.DisplayName
		end)
		if okName and type(display) == "string" and util.trim(display) ~= "" then
			name = display
		elseif env.plr and type(env.plr.Name) == "string" and env.plr.Name ~= "" then
			name = env.plr.Name
		end

		local holder = P.column(parent, {
			name = "Home",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignX = "Center",
			gap = theme.space.lg,
			padding = { top = theme.space.lg, bottom = theme.space.md },
			layoutOrder = order,
		})

		local greeting = P.column(holder, {
			name = "Greeting",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignX = "Center",
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		env.require("ui/conversation_resume").build(holder, 4)
		local brandSlot = P.frame(greeting, {
			name = "HomeBrand",
			size = UDim2.fromOffset(theme.size.controlLarge, theme.size.controlLarge),
			layoutOrder = 1,
		})
		icons.brand(brandSlot, theme.size.controlLarge)
		P.text(greeting, {
			name = "GreetingText",
			text = string.format("What will we create, %s?", name),
			role = "display",
			color = theme.color.text,
			align = "Center",
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})

		P.text(greeting, {
			name = "GreetingSubtitle", text = "Your ideas. Your game. An agent to help make it happen.",
			role = "small", color = theme.color.textTertiary, align = "Center", wrap = true,
			auto = "Y", size = UDim2.new(1, 0, 0, 0), layoutOrder = 3,
		})
		if props.onInsert then
			local grid = P.frame(holder, {
				name = "PromptStarters", size = UDim2.new(1, 0, 0, 0),
				maxSize = Vector2.new(theme.size.statCard, math.huge), layoutOrder = 2,
			})
			local cards = {}
			local minStarterWidth = 0
			for index, entry in ipairs(env.require("ui/chat/prompts").items) do
				minStarterWidth = math.max(minStarterWidth, P.measureText(entry.label, { role = "label" }).X
					+ theme.size.icon + theme.space.sm + theme.space.md * 2)
				local card = P.rowButton(grid, {
					name = "Starter_" .. entry.id, vertical = true, size = UDim2.fromOffset(0, theme.size.promptCard),
					bg = theme.color.surface, stroke = true,
					radius = theme.radius.lg, gap = theme.space.xs,
					padding = theme.space.md,
					alignX = "Left", alignY = "Top",
					onClick = function() props.onInsert(entry.text) end,
				})
				local head = P.row(card.row, {
					name = "StarterHead", size = UDim2.new(1, 0, 0, math.max(theme.size.icon, theme.text.label.height)),
					gap = theme.space.sm, layoutOrder = 1,
				})
				local icon = P.frame(head, { size = UDim2.fromOffset(theme.size.icon, theme.size.icon), layoutOrder = 1 })
				icons.draw(entry.icon, icon, theme.size.icon, theme.color.accentHot)
				P.text(head, { text = entry.label, role = "label", layoutOrder = 2,
					size = UDim2.new(0, 0, 0, theme.text.label.height), flex = "Fill", truncate = true })
				P.text(card.row, { text = entry.detail, role = "caption", color = theme.color.textTertiary,
					layoutOrder = 2, size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true })
				cards[index] = { instance = card.instance, detail = entry.detail }
			end
			local function fitStarters()
				local gap = theme.space.sm
				local columns = grid.AbsoluteSize.X >= math.max(minStarterWidth * 2 + gap, theme.size.promptColumns) and 2 or 1
				local width = math.max(1, (grid.AbsoluteSize.X - gap * (columns - 1)) / columns - theme.space.md * 2)
				local detailHeight = theme.text.caption.height
				for _, card in ipairs(cards) do
					detailHeight = math.max(detailHeight, P.measureText(card.detail, { role = "caption", width = width }).Y)
				end
				local height = math.max(theme.size.promptCard,
					math.max(theme.size.icon, theme.text.label.height) + detailHeight + theme.space.md * 2 + theme.space.xs)
				for index, card in ipairs(cards) do
					local col = (index - 1) % columns
					local row = math.floor((index - 1) / columns)
					card.instance.Size = UDim2.new(1 / columns, -gap * (columns - 1) / columns, 0, height)
					card.instance.Position = UDim2.new(col / columns, col * gap / columns, 0, row * (height + gap))
				end
				grid.Size = UDim2.new(1, 0, 0, math.ceil(#cards / columns) * (height + gap) - gap)
			end
			grid:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitStarters)
			fitStarters()
		end

		local freeRecord = env.require("provider/registry").active()
		if env.require("provider/community_key").isApplied(freeRecord) then
			local intro = P.column(holder, { name = "FreeIntroduction", size = UDim2.new(1, 0, 0, 0),
				maxSize = Vector2.new(theme.size.statCard, math.huge), auto = "Y", gap = theme.space.xs,
				padding = theme.space.md, bg = theme.color.surface, radius = theme.radius.lg, layoutOrder = 3 })
			P.stroke(intro, theme.color.borderSubtle)
			P.text(intro, { name = "FreeIntroductionTitle", text = "Project UAI Free hours", role = "label",
				size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true, layoutOrder = 1 })
			P.text(intro, { name = "FreeIntroductionText",
				text = "You selected Project UAI Free from the Providers library. Shared access opens daily 20:00-12:00 UTC+8 (Beijing/Singapore), through the following midday. Speed and availability vary. For a personal HCNSEC account, add the separate HCNSEC provider with your own key.",
				role = "caption", color = theme.color.textSecondary, size = UDim2.new(1, 0, 0, 0),
				auto = "Y", wrap = true, layoutOrder = 2 })
			-- The countdown is the one line that has to move: a person deciding whether
			-- to wait wants the remaining time, not a schedule to work out themselves.
			local timer = P.text(intro, { name = "FreeHoursTimer", text = "", role = "caption",
				color = theme.color.text, size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true, layoutOrder = 3 })
			local community = env.require("provider/community_key")
			local stopTimer
			stopTimer = env.require("runtime/clock").interval(1, function()
				if not timer.Parent then stopTimer(); return end
				local countdown = community.countdown(freeRecord)
				timer.Text = countdown and (countdown.text .. "  ·  daily " .. community.shortHours) or ""
			end)
			local countdown = community.countdown(freeRecord)
			timer.Text = countdown and (countdown.text .. "  ·  daily " .. community.shortHours) or ""
			P.text(intro, { name = "FreeCommunityInvite", text = "Updates and help: https://discord.gg/9xYyyYuKap",
				role = "caption", color = theme.color.accent, size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true, layoutOrder = 4 })
			P.button(intro, { name = "FreeCommunity", text = "Join our Discord", variant = "ghost", size = "sm", layoutOrder = 5,
				onClick = function() env.require("ui/community").open() end })
		elseif not freeRecord then
			local setup = P.column(holder, { name = "ProviderIntroduction", size = UDim2.new(1, 0, 0, 0),
				maxSize = Vector2.new(theme.size.statCard, math.huge), auto = "Y", gap = theme.space.sm,
				padding = theme.space.md, bg = theme.color.surface, radius = theme.radius.lg, layoutOrder = 3 })
			P.text(setup, { text = "Choose a provider to start", role = "label", auto = "Y", wrap = true,
				size = UDim2.new(1, 0, 0, 0), layoutOrder = 1 })
			P.text(setup, { text = "Browse free routes, paid services and local servers. Project UAI Free is optional; HCNSEC is a separate personal-key provider.",
				role = "caption", color = theme.color.textSecondary, auto = "Y", wrap = true,
				size = UDim2.new(1, 0, 0, 0), layoutOrder = 2 })
			P.button(setup, { name = "ChooseProvider", text = "Open Providers", variant = "primary", size = "sm", layoutOrder = 3,
				onClick = function() env.require("ui/app").show("providers") end })
		end

		if config.get("ui.showActivity", true) ~= true then return holder end

		local card = P.column(holder, {
			name = "ActivityCard",
			-- Fills the column up to the card's own width, rather than being a fixed
			-- 560 that overflows a phone.
			size = UDim2.new(1, 0, 0, 0),
			maxSize = Vector2.new(theme.size.statCard, math.huge),
			auto = "Y",
			bg = theme.color.surfaceRaised,
			radius = theme.radius.xl,
			gap = theme.space.md,
			padding = theme.space.lg,
			layoutOrder = 5,
		})
		P.stroke(card, theme.color.borderSubtle)
		card.Visible = false
		P.button(holder, {
			name = "ToggleActivity", text = "Your activity", icon = "chevron", iconDirection = "down",
			variant = "ghost", size = "sm", layoutOrder = 4,
			onClick = function(button)
				card.Visible = not card.Visible
				button.setText(card.Visible and "Hide activity" or "Your activity")
			end,
		})

		local state = {
			tab = "overview",
			range = config.get("ui.activityRange", "all"),
		}
		local body = nil

		local function render()
			if body then pcall(function() body:Destroy() end) end
			body = P.column(card, {
				name = "ActivityBody",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = 2,
			})

			local window = stats.window(state.range)
			if state.tab == "models" then
				buildModels(body, window)
			else
				buildOverview(body, window)
			end
			buildHeatmap(body, 2)

			local footer = stats.comparison(window.tokens)
			if not footer then
				if window.messages == 0 and window.requests == 0 then
					footer = "Your activity will appear here as you work. Every figure comes from this client's recorded usage."
				else
					footer = string.format("%s in, %s out across %s.",
						util.formatCompact(window.tokensIn), util.formatCompact(window.tokensOut),
						util.pluralise(window.requests, "request"))
				end
			end
			local note = P.text(body, {
				name = "Comparison",
				text = footer,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 3,
			})
			note.Size = UDim2.new(1, 0, 0, 0)
		end

		local header = P.row(card, {
			name = "CardHeader",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.xs,
			layoutOrder = 1,
		})

		local tabs, ranges = {}, {}

		local function repaint()
			for value, handle in pairs(tabs) do
				handle.setSelected(value == state.tab)
				handle.text.TextColor3 = (value == state.tab) and theme.color.text or theme.color.textTertiary
			end
			for value, handle in pairs(ranges) do
				handle.setSelected(value == state.range)
				handle.text.TextColor3 = (value == state.range) and theme.color.text or theme.color.textTertiary
			end
		end

		local tabRow = P.row(header, {
			name = "Tabs",
			size = UDim2.fromOffset(0, math.max(theme.size.chip, responsive.minTarget())),
			auto = "X",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		for index, entry in ipairs({ { value = "overview", label = "Overview" }, { value = "models", label = "Models" } }) do
			local handle = pill(tabRow, entry.label, entry.value == state.tab, index, function()
				state.tab = entry.value
				repaint()
				render()
			end)
			handle.text = handle.row:FindFirstChildOfClass("TextLabel")
			tabs[entry.value] = handle
		end

		P.spacer(header, { grow = true, layoutOrder = 2 })

		local rangeRow = P.row(header, {
			name = "Ranges",
			size = UDim2.fromOffset(0, math.max(theme.size.chip, responsive.minTarget())),
			auto = "X",
			gap = theme.space.hair,
			layoutOrder = 3,
		})
		for index, entry in ipairs(stats.RANGES) do
			local handle = pill(rangeRow, entry.label, entry.value == state.range, index, function()
				state.range = entry.value
				config.set("ui.activityRange", entry.value, { quiet = true })
				repaint()
				render()
			end)
			handle.text = handle.row:FindFirstChildOfClass("TextLabel")
			ranges[entry.value] = handle
		end

		render()
		repaint()

		-- The card is built once per transcript, and a turn that finishes while it is on
		-- screen changes every number on it. Debounced because a turn records a message,
		-- a request and a tool result within the same few frames, and rebuilding the
		-- grid three times for one turn is three times the work for one result.
		local refresh, cancelRefresh = clock.debounce(function()
			if not card.Parent then return end
			render()
		end, theme.motion.slow)
		local unsubscribe = stats.changed:connect(refresh)
		card.Destroying:Connect(function()
			cancelRefresh()
			pcall(unsubscribe)
		end)

		return holder
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/logs
-- ==========================================================================
__UAI_MODULES["ui/panels/logs"] = (function()
-- Logs panel: the request history and the application log.
--
-- Two views over the same question -- what did this thing just do -- kept separate
-- because they answer different halves of it. Requests explain a provider failure;
-- the log explains everything else.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local http = env.require("net/http")
	local log = env.require("runtime/log")
	local deadlineHelp = env.require("ui/deadline_help")
	local search = env.require("runtime/search")
	local textUtil = env.require("runtime/code_text")

	local M = {}

	local LEVEL_TONE = { debug = "info", info = "info", warn = "warn", error = "bad" }
	local DETAIL_LIMIT = 65536
	local PREVIEW_LIMIT = 480

	local function safe(value, limit)
		if value == nil then return "Not recorded" end
		local kind = type(value)
		if kind ~= "string" and kind ~= "number" and kind ~= "boolean" then return "Not recorded" end
		local text = log.redact(tostring(value))
		limit = limit or 2048
		if #text > limit then return util.truncate(text, limit) .. "\n[Remaining text omitted from this detail view.]" end
		return text
	end

	-- The list is a scan of events; selected details retain the complete snapshot.
	-- Bound both bytes and lines so one stack trace cannot bury the next event.
	local function preview(value)
		local text = safe(value, DETAIL_LIMIT)
		local limit, start = math.min(#text, PREVIEW_LIMIT), 1
		for line = 1, 4 do
			local newline = text:find("\n", start, true)
			if not newline then break end
			if line == 4 then limit = math.min(limit, newline - 1) end
			start = newline + 1
		end
		if limit < #text then return textUtil.slice(text, 1, limit + 1) .. "\nOpen details for more." end
		return text
	end

	local function safeUrl(value)
		local text = tostring(value or "")
		text = text:gsub("(https?://)[^/@]+@", "%1[redacted]@")
		text = text:gsub("([?&])([^=&#]+)=([^&#]*)", function(prefix, key, content)
			local decoded = key:lower():gsub("%%(%x%x)", function(hex) return string.char(tonumber(hex, 16)) end)
			if decoded:find("key", 1, true) or decoded:find("token", 1, true) or decoded:find("secret", 1, true)
				or decoded:find("password", 1, true) or decoded:find("credential", 1, true)
				or decoded:find("signature", 1, true) or decoded == "auth" or decoded == "authorization" or decoded == "sig" then
				content = "[redacted]"
			end
			return prefix .. key .. "=" .. content
		end)
		return safe(text, 8192)
	end

	-- A dialog owns only selected, sanitized fields. Transport response snippets,
	-- headers and request bodies never enter its snapshot or clipboard export.
	local function requestDetails(entry)
		local status = tonumber(entry.status) or 0
		local ms, bytes = tonumber(entry.ms), tonumber(entry.bytes)
		local fields = {
			{ "Time", safe(entry.stamp) }, { "Method", safe(entry.method) }, { "URL", safeUrl(entry.url) },
			{ "HTTP status", status > 0 and tostring(status) or "No HTTP response" },
			{ "Duration", ms and (util.formatDuration(ms) .. " (" .. tostring(ms) .. " ms)") or "Not recorded" },
			{ "Response size", bytes and (util.formatNumber(bytes) .. " bytes") or "Not recorded" },
			{ "Transport", safe(entry.via) }, { "Tag", safe(entry.tag) }, { "Identity", safe(entry.identity) },
		}
		local agent = "Not recorded"
		if entry.uaSent == true then agent = "Sent"
		elseif entry.uaSent == false then agent = entry.identity == "none" and "Not requested" or "Not sent" end
		fields[#fields + 1] = { "User-Agent", agent }
		local dropped = {}
		if type(entry.droppedHeaders) == "table" then
			for index = 1, math.min(32, #entry.droppedHeaders) do dropped[#dropped + 1] = safe(entry.droppedHeaders[index], 128) end
			if #entry.droppedHeaders > 32 then dropped[#dropped + 1] = "Additional names omitted" end
		end
		fields[#fields + 1] = { "Dropped headers", #dropped > 0 and table.concat(dropped, ", ") or "Not recorded" }
		for _, field in ipairs({ { "Attempt", "attempt" }, { "Server", "server" }, { "Trace ID", "trace" }, { "Mitigation", "mitigated" } }) do
			fields[#fields + 1] = { field[1], safe(entry[field[2]]) }
		end
		fields[#fields + 1] = { "Transport error", entry.error and safe(entry.error, DETAIL_LIMIT) or "No transport error recorded" }
		return fields
	end

	local function logDetails(entry)
		return {
			{ "Time", safe(entry.stamp) }, { "Level", safe(entry.level) }, { "Source", safe(entry.source) },
			{ "Message", safe(entry.message, DETAIL_LIMIT) },
			{ "Detail", entry.detail ~= nil and safe(entry.detail, DETAIL_LIMIT) or "No additional detail recorded" },
		}
	end

	-- Copy the same request evidence this panel shows, without including bodies or
	-- credentials from transport records. The application log has a separate export.
	local function requestExport()
		local lines = {}
		for index = #http.history, 1, -1 do
			local entry = http.history[index]
			lines[#lines + 1] = string.format("%s %s %s -> %s (%s)",
				tostring(entry.stamp or ""), tostring(entry.method or "GET"), safeUrl(entry.url),
				tostring(entry.status or 0), util.formatDuration(entry.ms or 0))
			local details = { tostring(entry.tag or "http"), tostring(entry.via or "unknown"),
				util.formatNumber(entry.bytes or 0) .. " bytes",
				"identity: " .. tostring(entry.identity or "none") }
			if entry.identity ~= "none" then
				details[#details + 1] = entry.uaSent and "user-agent sent" or "user-agent dropped"
			end
			if entry.attempt then details[#details + 1] = "attempt " .. tostring(entry.attempt) end
			if entry.server then details[#details + 1] = "server " .. tostring(entry.server) end
			if entry.trace then details[#details + 1] = "trace " .. tostring(entry.trace) end
			if entry.mitigated then details[#details + 1] = "mitigated " .. tostring(entry.mitigated) end
			lines[#lines + 1] = "  " .. table.concat(details, " | ")
			if entry.error then lines[#lines + 1] = "  " .. tostring(entry.error) end
		end
		return log.redact(table.concat(lines, "\n"))
	end

	function M.new(parent)
		local panel = { view = "requests" }
		local filter = ""
		local function inspect(entry, kind)
			if panel.detail and not panel.detail.closed then panel.detail.close() end
			local fields = kind == "requests" and requestDetails(entry) or logDetails(entry)
			local title = kind == "requests" and "Request details" or "Log details"
			local dialog
			dialog = overlay.modal({ title = title, width = theme.size.modalWide,
				onClose = function() if panel.detail == dialog then panel.detail = nil end end })
			if not dialog then return end
			panel.detail = dialog
			dialog.card.Name = kind == "requests" and "RequestDetails" or "LogDetails"
			local deadline = kind == "requests" and deadlineHelp.matches(entry.error)
				or kind ~= "requests" and (entry.level == "warn" or entry.level == "error")
					and (deadlineHelp.matches(entry.message) or deadlineHelp.matches(entry.detail))
			if deadline then deadlineHelp.new(dialog.content, 0) end
			local lines = { title }
			for index, field in ipairs(fields) do
				lines[#lines + 1] = field[1] .. ": " .. field[2]
				local row = P.column(dialog.content, { name = "DetailField" .. tostring(index), size = UDim2.new(1, 0, 0, 0),
					auto = "Y", gap = theme.space.xxs, layoutOrder = index })
				P.text(row, { name = "FieldName", text = field[1], role = "label", color = theme.color.textTertiary,
					size = UDim2.new(1, 0, 0, 0), auto = "Y", layoutOrder = 1 })
				P.text(row, { name = "FieldValue", text = field[2], role = "monoSmall", wrap = true,
					size = UDim2.new(1, 0, 0, 0), auto = "Y", layoutOrder = 2 })
			end
			local exported = table.concat(lines, "\n\n")
			if caps.clipboard then
				P.button(dialog.footer, { name = "CopyDetail", text = "Copy details", variant = "secondary", size = "sm", layoutOrder = 1,
					onClick = function(button)
						local ok, copied = pcall(caps.fn.clipboard, exported)
						ok = ok and copied ~= false
						button.setText(ok and "Copied" or "Retry")
						if not ok then overlay.toast("Could not copy details", "bad", 3) end
						clock.delay(2, function() if not dialog.closed then button.setText("Copy details") end end)
					end })
			end
			P.button(dialog.footer, { name = "CloseDetails", text = "Close", variant = "ghost", size = "sm", layoutOrder = 2,
				onClick = function() dialog.close() end })
		end

		local column = P.column(parent, {
			name = "LogsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.md },
			layoutOrder = 1,
		})

		local scroll
		local function render() end

		P.sectionHeader(head, { title = "Logs & traces", description = "Select a request or log entry to inspect its details.", layoutOrder = 1 })
		C.segmented(head, {
			layoutOrder = 2,
			options = {
				{ value = "requests", label = "Requests" },
				{ value = "log", label = "Log" },
			},
			value = panel.view,
			onChange = function(value)
				panel.view = value
				render()
				scroll.instance.CanvasPosition = Vector2.new(0, 0)
			end,
		})

		P.field(head, { name = "DiagnosticsSearch", placeholder = "Search host, status, tool or message", layoutOrder = 3,
			onChange = function(value)
				filter = util.trim(value); render()
				if scroll then scroll.instance.CanvasPosition = Vector2.new(0, 0) end
			end })
		local actions = P.row(head, { size = UDim2.new(1, 0, 0, 0), auto = "Y", wrap = true, gap = theme.space.xs, layoutOrder = 4 })
		local countLabel = P.text(actions, {
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			layoutOrder = 1,
		})
		countLabel.Size = UDim2.fromOffset(0, theme.text.caption.height + theme.space.hair)
		countLabel.AutomaticSize = Enum.AutomaticSize.X
		-- A growing spacer rather than a hardcoded reserve on the label: the buttons
		-- are auto-width and grow with the text scale, so any fixed number is either
		-- short of the right edge or overlapping them.
		P.spacer(actions, { grow = true, size = UDim2.new(0, 0, 0, 1), layoutOrder = 2 })

		if caps.clipboard then
			local copy = P.button(actions, {
				name = "CopyDiagnostics",
				text = "Copy",
				variant = "ghost",
				size = "sm",
				layoutOrder = 3,
				onClick = function(button)
					local exported = panel.view == "requests" and requestExport() or log.export()
					local ok, copied = pcall(caps.fn.clipboard, exported)
					ok = ok and copied ~= false
					button.setText(ok and "Copied" or "Retry")
					if not ok then overlay.toast("Could not copy diagnostics", "bad", 3) end
					clock.delay(2, function()
						if button.instance.Parent then button.setText("Copy") end
					end)
				end,
			})
			copy.instance.LayoutOrder = 3
		end
		local clear = P.button(actions, {
			name = "ClearDiagnostics",
			text = "Clear",
			variant = "ghost",
			size = "sm",
			layoutOrder = 4,
			onClick = function()
				if panel.view == "requests" then http.clearHistory() else log.clear() end
				render()
			end,
		})
		clear.instance.LayoutOrder = 4

		local listHolder = P.frame(column, { name = "LogListHolder", size = UDim2.new(1, 0, 0, 0),
			flex = "Fill", layoutOrder = 2 })
		scroll = P.scroll(listHolder, {
			name = "LogList",
			size = UDim2.new(1, 0, 1, 0),
			-- Tight, because the rows now carry their own banding and padding; a six
			-- pixel gap between banded rows reads as a gap in the data.
			gap = theme.space.sm,
			padding = { x = theme.space.lg, top = theme.space.sm, bottom = theme.space.xl },
			layoutOrder = 2,
		})

		local function requestRow(entry, order)
			local tone = "good"
			if entry.error then
				tone = "bad"
			elseif entry.status >= 400 then
				tone = entry.status == 429 and "warn" or "bad"
			elseif entry.status == 0 then
				tone = "warn"
			end

			local item = P.rowButton(scroll.instance, {
				name = "RequestEntry", vertical = true, auto = "Y", size = UDim2.new(1, 0, 0, 0),
				bg = theme.color.surfaceRaised, stroke = true,
				layoutOrder = order,
				gap = theme.space.xxs,
				padding = theme.space.sm,
				onClick = function() inspect(entry, "requests") end,
			})
			local card = item.row
			local top = P.row(card, { name = "RequestSummary", size = UDim2.new(1, 0, 0, 0),
				auto = "Y", gap = theme.space.xs, layoutOrder = 1 })
			P.statusDot(top, { color = theme.toneColor(tone), diameter = theme.size.dot, layoutOrder = 1 })
			local title = P.text(top, {
				name = "RequestTitle",
				text = string.format("%s %s", entry.method, entry.tag or ""),
				role = "monoSmall",
				-- Fills rather than reserving 150 for a dot and a 96px meta column,
				-- which left thirty-five pixels stranded on every card.
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				truncate = true,
				layoutOrder = 2,
			})
			local meta = P.text(top, {
				name = "RequestStatus",
				text = string.format("%s %s", entry.status > 0 and tostring(entry.status) or "-",
					util.formatDuration(entry.ms or 0)),
				role = "caption",
				color = theme.toneColor(tone),
				align = "Right",
				auto = "X",
				layoutOrder = 3,
			})

			local url = P.text(card, {
				name = "RequestUrl",
				text = preview(safeUrl(entry.url)),
				role = "caption",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			url.Size = UDim2.new(1, 0, 0, 0)

			local bits = {
				entry.via or "?",
				string.format("%s bytes", util.formatNumber(entry.bytes or 0)),
				entry.identity or "claude",
			}
			if entry.identity ~= "none" and not entry.uaSent then
