			-- response came from an edge rather than from the API, and `cf-mitigated`
			-- says so outright, which is the difference between a key problem and a
			-- filter problem.
			if entry.server then bits[#bits + 1] = "server " .. tostring(entry.server) end
			if entry.mitigated then bits[#bits + 1] = "mitigated " .. tostring(entry.mitigated) end
			if entry.trace then bits[#bits + 1] = tostring(entry.trace) end
			if entry.status >= 400 and (entry.bytes or 0) == 0 then
				bits[#bits + 1] = "empty body"
			end
			local detail = P.text(card, {
				name = "RequestEvidence",
				text = preview(table.concat(bits, "  |  ")),
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 3,
			})
			detail.Size = UDim2.new(1, 0, 0, 0)

			if entry.error then
				local err = P.text(card, {
					name = "RequestError",
					text = preview(entry.error),
					role = "caption",
					color = theme.color.danger,
					wrap = true,
					auto = "Y",
					layoutOrder = 4,
				})
				err.Size = UDim2.new(1, 0, 0, 0)
			end
			return item.instance
		end

		local function logRow(entry, order)
			local tone = LEVEL_TONE[entry.level] or "info"
			local item = P.rowButton(scroll.instance, {
				name = "LogEntry", vertical = true, auto = "Y", size = UDim2.new(1, 0, 0, 0),
				bg = theme.color.surfaceRaised, stroke = true,
				gap = theme.space.xs,
				padding = theme.space.sm,
				layoutOrder = order,
				onClick = function() inspect(entry, "log") end,
			})
			local row = item.row
			local metadata = P.row(row, {
				name = "Metadata",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = 1,
			})
			P.badge(metadata, { text = entry.level or "info", tone = tone, layoutOrder = 1 })
			P.text(metadata, {
				name = "Source", text = safe(entry.source), role = "caption",
				color = theme.color.textSecondary, truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				flex = "Fill", layoutOrder = 2,
			})
			P.text(metadata, {
				name = "Timestamp", text = entry.stamp or "", role = "monoSmall",
				color = theme.color.textTertiary, auto = "X", layoutOrder = 3,
			})
			P.text(row, {
				name = "Message", text = preview(entry.message), role = "small",
				color = entry.level == "error" and theme.color.danger or theme.color.textSecondary,
				wrap = true, auto = "Y", layoutOrder = 2,
			})
			if entry.detail then
				P.text(row, {
					name = "Detail", text = preview(entry.detail), role = "monoSmall",
					color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 3,
				})
			end
			return item.instance
		end

		render = function()
			if not column.Parent then return end
			local position = scroll.instance.CanvasPosition
			scroll.clear()
			if panel.view == "requests" then
				local match, entries = search.compile(filter), {}
				for index = #http.history, 1, -1 do
					local entry = http.history[index]
					if match(safeUrl(entry.url), entry.status, entry.tag, entry.method, entry.via, entry.error) then entries[#entries + 1] = entry end
				end
				countLabel.Text = util.pluralise(#entries, "request") .. (filter ~= "" and (" matched / " .. #http.history .. " kept") or " kept")
				if #entries == 0 then
					C.emptyState(scroll.instance, {
						icon = "document",
						title = filter ~= "" and "No matching requests" or "No requests yet",
						description = filter ~= "" and "Try fewer words, an HTTP status or a provider host." or "Requests appear here with status, duration and transport details after you send a message.",
						layoutOrder = 1,
					})
					return
				end
				for index, entry in ipairs(entries) do requestRow(entry, index) end
			else
				local entries = util.reverse(log.filter(nil, filter))
				countLabel.Text = util.pluralise(#entries, "line") .. (filter ~= "" and (" matched / " .. #log.entries .. " kept") or " kept")
				if #entries == 0 then
					C.emptyState(scroll.instance, { icon = "document", title = filter ~= "" and "No matching log entries" or "All clear",
						description = filter ~= "" and "Try a source, level or a word from the details." or "Application events will appear here as they occur.", layoutOrder = 1 })
					return
				end
				for index, entry in ipairs(entries) do logRow(entry, index) end
			end
			scroll.instance.CanvasPosition = position
		end

		render()
		panel.refresh = render
		-- Coalesce a burst while retaining its final entry. A leading-only throttle
		-- silently left the last requests absent until another event happened.
		local refreshLater, cancelRefresh = clock.debounce(render, 0.2)
		panel.unsubscribeLog = log.changed:connect(function()
			if panel.view == "log" then refreshLater() end
		end)
		panel.unsubscribeHttp = http.changed:connect(function()
			if panel.view == "requests" then refreshLater() end
		end)
		column.Destroying:Connect(function()
			if panel.detail and not panel.detail.closed then panel.detail.close() end
			cancelRefresh()
			pcall(panel.unsubscribeLog)
			pcall(panel.unsubscribeHttp)
		end)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/modelpicker
-- ==========================================================================
__UAI_MODULES["ui/panels/modelpicker"] = (function()
-- Provider context, persistent search, a compact model catalogue, and effort.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local providers = env.require("provider/registry")
	local models = env.require("provider/models")
	local traits = env.require("provider/traits")
	local freeRoute = env.require("provider/free_route")
	local community = env.require("provider/community_key")
	local sampling = env.require("provider/sampling")
	local preferences = env.require("provider/model_preferences")
	local overrides = env.require("provider/model_overrides")
	local searchQuery = env.require("runtime/search")
	local providerPicker = env.require("ui/panels/providerpicker")
	local M = {}
	local opened

	function M.open(onChange)
		if opened and not opened.closed then return opened end
		local modalProps = { title = "Choose a model", width = theme.size.modelPicker,
			height = providerPicker.preferredHeight(), minTarget = providerPicker.target(), scroll = true, pinFooter = true }
		local modal = overlay.modal(modalProps)
		if not modal then return end
		opened = modal
		modal.scroll.instance.ScrollingEnabled = false
		modal.scroll.instance.ScrollBarThickness = 0
		modal.content.AutomaticSize = Enum.AutomaticSize.None
		modal.content.Size = UDim2.fromScale(1, 1)
		local root = P.frame(modal.content, { name = "ModelPicker", size = UDim2.fromScale(1, 1) })
		local control = providerPicker.target()
		local filter, freeOnly, fetching = "", false, false
		local favoritesOnly, toolsOnly = false, false
		local rows, render, filterRows, renderEffort, fit = {}, nil, nil, nil, nil
		local signature, effortSignature, fitting = nil, nil, false
		local autoRow, autoClosed = nil, false
		-- The closed-hours row carries the wait until opening, so it is the one label
		-- that has to change while the modal stays open.
		local function freeHoursMeta(record)
			local countdown = community.countdown(record)
			return "Free | " .. (countdown and countdown.text:lower() or community.shortHours)
		end
		local effortLevels, effortSending, effortHeight, effortLabel = nil, nil, 0, nil
		local function notify() if not modal.closed and onChange then onChange() end end
		local providerHeight = math.max(control, theme.text.label.height + theme.text.caption.height + theme.space.md * 2 + theme.space.hair)
		local selectionHeight = theme.text.caption.height + theme.space.sm

		local providerButton = P.rowButton(root, { name = "Section_Endpoint", height = providerHeight,
			size = UDim2.new(1, 0, 0, providerHeight), padding = { x = theme.space.md }, gap = theme.space.sm,
			bg = theme.color.surface, stroke = true, strokeColor = theme.color.borderSubtle, radius = theme.radius.md,
			onClick = function() providerPicker.open(modal, notify) end })
		local providerText = P.column(providerButton.row, { size = UDim2.new(0, 0, 0, providerHeight - theme.space.md * 2),
			flex = "Fill", gap = theme.space.hair, layoutOrder = 1 })
		local providerLabel = P.text(providerText, { name = "CurrentProvider", text = "Add a provider", role = "label",
			size = UDim2.new(1, 0, 0, theme.text.label.height), truncate = true, layoutOrder = 1 })
		local providerStatus = P.text(providerText, { name = "CurrentProviderStatus", text = "", role = "caption",
			size = UDim2.new(1, 0, 0, theme.text.caption.height), truncate = true, layoutOrder = 2 })
		local providerChange = P.text(providerButton.row, { text = "Change", role = "caption", color = theme.color.textSecondary, auto = "X", layoutOrder = 2 })
		providerButton.icon("chevron", 3, theme.color.textTertiary)
		local selection = P.row(root, { name = "CurrentSelection", position = UDim2.fromOffset(theme.space.xxs, providerHeight + theme.space.xs),
			size = UDim2.new(1, -theme.space.sm, 0, selectionHeight), gap = theme.space.sm })
		P.text(selection, { text = "Selected", role = "caption", color = theme.color.textTertiary, auto = "X", layoutOrder = 1 })
		local selectionLabel = P.text(selection, { name = "CurrentModel", text = "Choose a model below", role = "caption", color = theme.color.textSecondary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height), flex = "Fill", truncate = true, layoutOrder = 2 })
		local searchTop = providerHeight + selectionHeight + theme.space.md
		local filterWidth = math.max(theme.size.metaColumnWide,
			math.ceil(P.measureText("Free only", { role = "small" }).X) + theme.space.md * 2 + theme.space.sm)
		local searchRow = P.frame(root, { name = "FilterRow", position = UDim2.fromOffset(0, searchTop),
			size = UDim2.new(1, 0, 0, control) })
		local search = P.field(searchRow, { name = "ModelFilter", placeholder = "Search models...", role = "small",
			size = UDim2.new(1, -(filterWidth + theme.space.sm), 0, control),
			onChange = function(text) filter = text; if filterRows then filterRows() end end })
		local freeButton = P.button(searchRow, { name = "FreeOnly", text = "Free only", width = filterWidth,
			position = UDim2.new(1, -filterWidth, 0, 0), size = "md", role = "small", variant = "ghost",
			onClick = function(button)
				freeOnly = not freeOnly
				button.setVariant(freeOnly and "secondary" or "ghost")
				filterRows()
			end })
		providerPicker.sizeButton(freeButton, control)
		local count = P.text(root, { name = "ModelCount", text = "", role = "caption", color = theme.color.textTertiary,
			position = UDim2.fromOffset(theme.space.xxs, searchTop + control + theme.space.sm), size = UDim2.new(1, -theme.space.sm, 0, theme.text.caption.height) })
		local listTop = searchTop + control + theme.space.sm * 2 + theme.text.caption.height
		local expandedListTop = listTop
		local rowGap, listPad = theme.space.xs, theme.space.xxs
		local modelHeight = math.max(control, theme.text.small.height + theme.text.caption.height + theme.space.hair + theme.space.sm * 2)
		local list = P.scroll(root, { name = "ModelScroll", position = UDim2.fromOffset(0, listTop),
			size = UDim2.new(1, 0, 1, -listTop), gap = rowGap,
			padding = { left = theme.space.xxs, right = theme.space.sm, top = theme.space.xxs, bottom = theme.space.xxs },
			bg = theme.color.surface })
		P.corner(list.instance, theme.radius.md)
		local empty = P.text(list.instance, { name = "EmptySearch", text = "No models yet. Use Refresh or add a model ID.",
			role = "small", color = theme.color.textTertiary, wrap = true, auto = "Y", size = UDim2.new(1, 0, 0, 0) })
		local effort = P.column(root, { name = "Section_ReasoningEffort", anchor = Vector2.new(0, 1),
			position = UDim2.fromScale(0, 1), size = UDim2.new(1, 0, 0, control + theme.text.caption.height + theme.space.sm),
			gap = theme.space.xs })
		local function temperatureMenu(target, record)
			local id, policy = record.model, sampling.state(record)
			local automatic = policy.source == "learned" and "This provider rejected temperature; Automatic omits it."
				or "Use known model and provider support"
			overlay.menu({ target = target, rowHeight = control, options = {
				{ label = "Automatic", value = "auto", selected = policy.override == "auto", detail = automatic },
				{ label = "Send temperature", value = "send", selected = policy.override == "send" },
				{ label = "Omit temperature", value = "omit", selected = policy.override == "omit" },
				{ divider = true }, { label = "Edit shared temperature value", value = "value", detail = tostring(config.get("agent.temperature", 0.4)) },
			}, onSelect = function(value)
				if value == "value" then
					overlay.prompt({ title = "Temperature", description = "Shared value from 0 to 2. Models set to omit do not send it.", value = tostring(config.get("agent.temperature", 0.4)), confirmText = "Save", onConfirm = function(text)
						local number = tonumber(text)
						if not number or number ~= number or number < 0 or number > 2 then overlay.toast("Enter a temperature from 0 to 2", "warn", 3); return end
						config.set("agent.temperature", number); notify()
					end })
				else local ok, why = sampling.set(id, value); if not ok then overlay.toast(tostring(why), "warn", 3) else notify() end end
			end })
		end
		local function effortMenu(target)
			local options = {}
			for _, level in ipairs(effortLevels or {}) do
				options[#options + 1] = { label = level:gsub("^%l", string.upper), value = level, selected = level == effortSending }
			end
			options[#options + 1] = { label = "Provider default", value = "off", selected = effortSending == "off" }
			overlay.menu({ target = target, rowHeight = control, options = options, onSelect = function(level)
				config.set("agent.effort", level); notify()
			end })
		end

		filterRows = function()
			local visible = 0
			local matchQuery = searchQuery.compile(filter)
			local record = providers.active()
			for _, entry in ipairs(rows) do
				local match = matchQuery(entry.id) ~= nil and (not freeOnly or entry.free)
					and (not favoritesOnly or preferences.favorite(record, entry.id))
					and (not toolsOnly or traits.of(entry.id, record).tools == true)
				entry.button.instance.Visible = match
				if match then visible = visible + 1 end
			end
			count.Text = visible == #rows and util.pluralise(#rows, "model") or string.format("%d of %s", visible, util.pluralise(#rows, "model"))
			empty.Visible = visible == 0
			empty.Text = #rows == 0 and "No models yet. Use Refresh or add a model ID."
				or favoritesOnly and "No favorites match. Add the selected model to favorites in Options, or clear filters."
				or toolsOnly and "No matching models have documented tool support. Clear filters to see all IDs."
				or "No matching models. Try another search or clear filters in Options."
			if fit then fit() end
		end

		renderEffort = function()
			local record = providers.active()
			local levels = record and traits.effortLevels(record.model)
			-- A manual reasoning claim is honored by both request adapters. Offer
			-- the global preferences here too, without inventing documented traits.
			if not levels and record and traits.thinkingStyle(record.model) then levels = { "low", "medium", "high", "xhigh", "max" } end
			local wanted = config.get("agent.effort", "low")
			local sending = wanted == "off" and "off" or (record and traits.nearestEffort(record.model, wanted) or wanted)
			effortLevels, effortSending = levels, sending
			effortHeight = levels and (control + theme.text.caption.height + theme.space.sm) or 0
			local manual = record and (config.get("agent.forceReasoning", {}) or {})[tostring(record.model):lower()] == true
			local nextEffort = table.concat({ record and record.model or "", table.concat(levels or {}, ","),
				tostring(wanted), tostring(sending), tostring(manual), tostring(control) }, "\0")
			if effortSignature == nextEffort then return end
			effortSignature = nextEffort
			for _, child in ipairs(effort:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
			effortLabel = P.text(effort, { text = levels and (manual and "Reasoning effort (global, manual)" or "Reasoning effort (global)") or "No documented effort control", name = levels and "EffortLabel" or "NoEffort",
				role = "caption", color = theme.color.textTertiary, size = UDim2.new(1, 0, 0, theme.text.caption.height), layoutOrder = 1 })
			if levels then
				local strip = P.scroll(effort, { name = "EffortPills", horizontal = true, gap = theme.space.xs,
					size = UDim2.new(1, 0, 0, control), layoutOrder = 2, bar = 0 })
				local choices = util.copy(levels)
				choices[#choices + 1] = "off"
				for index, level in ipairs(choices) do
					providerPicker.sizeButton(P.button(strip.instance, { name = "Effort_" .. level, text = level == "off" and "Provider default" or level:gsub("^%l", string.upper),
						variant = level == sending and "secondary" or "ghost", size = "sm", layoutOrder = index,
						onClick = function() config.set("agent.effort", level); notify() end }), control)
				end
			end
			effort.Visible = levels ~= nil
			effort.Size = UDim2.new(1, 0, 0, effortHeight)
			if fit then fit() end
		end
		fit = function()
			if modal.closed or fitting then return end
			fitting = true
			local room = math.max(0, modal.scroll.viewportSize().Y)
			local function set(instance, property, value)
				if instance[property] ~= value then instance[property] = value end
			end
			local minimumList = modelHeight * 2 + rowGap + listPad * 2
			-- Reserve the level buttons before fitting provider details and the list.
			-- Only extreme keyboard space falls back to the same levels in Options.
			local showEffort = effortHeight > 0 and room >= control * 2 + theme.space.xs * 2 + modelHeight + listPad * 2
			local showEffortLabel = showEffort and room >= expandedListTop + minimumList + effortHeight + theme.space.md
			local shownEffortHeight = showEffort and (showEffortLabel and effortHeight or control) or 0
			local footerSpace = showEffort and shownEffortHeight + (showEffortLabel and theme.space.md or theme.space.xs) or 0
			local catalogueRoom = room - footerSpace
			local compact = catalogueRoom < expandedListTop + minimumList
			local inline = compact and catalogueRoom < control * 2 + theme.space.xs * 2 + modelHeight + listPad * 2
			local endpointHeight = compact and control or providerHeight
			searchTop = compact and (endpointHeight + theme.space.xs) or (providerHeight + selectionHeight + theme.space.md)
			listTop = compact and (searchTop + control + theme.space.xs) or expandedListTop
			if inline then searchTop, listTop = 0, control + theme.space.xs end
			-- The catalogue always owns vertical scrolling. Short views compact the
			-- fixed controls without rebuilding the focused field or moving the list.
			set(providerButton.instance, "Size", inline and UDim2.new(0.36, -theme.space.xs, 0, endpointHeight) or UDim2.new(1, 0, 0, endpointHeight))
			set(providerText, "Size", UDim2.new(0, 0, 0, compact and theme.text.label.height or providerHeight - theme.space.md * 2))
			set(providerStatus, "Visible", not compact)
			set(providerChange, "Visible", not inline)
			set(selection, "Visible", not compact)
			set(selection, "Position", UDim2.fromOffset(theme.space.xxs, providerHeight + theme.space.xs))
			set(searchRow, "Position", inline and UDim2.fromScale(0.36, 0) or UDim2.fromOffset(0, searchTop))
			set(searchRow, "Size", UDim2.new(inline and 0.64 or 1, 0, 0, control))
			set(search.shell, "Size", UDim2.new(1, inline and 0 or -(filterWidth + theme.space.sm), 0, control))
			set(freeButton.instance, "Visible", not inline)
			set(count, "Visible", not compact)
			set(count, "Position", UDim2.fromOffset(theme.space.xxs, searchTop + control + theme.space.sm))
			set(effort, "Visible", showEffort)
			set(effort, "Size", UDim2.new(1, 0, 0, shownEffortHeight))
			if effortLabel then set(effortLabel, "Visible", showEffortLabel) end
			set(modal.content, "Size", UDim2.new(1, 0, 0, room))
			set(modal.scroll.instance, "ScrollingEnabled", false)
			set(list.instance, "ScrollingEnabled", true)
			set(list.instance, "Position", UDim2.fromOffset(0, listTop))
			set(list.instance, "Size", UDim2.new(1, 0, 0, math.max(0, room - listTop - footerSpace)))
			fitting = false
		end
		modal.scroll.instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() if fit then fit() end end)
		modal.scroll.instance:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(function() if fit then fit() end end)

		render = function()
			if modal.closed then return end
			local record = providers.active()
			providerLabel.Text = record and record.label or "Add a provider"
			local providerInfo = providerPicker.describe(record)
			providerStatus.Text, providerStatus.TextColor3 = providerInfo.detail, providerInfo.tone
			selectionLabel.Text = record and util.trim(record.model) ~= "" and record.model or "Choose a model below"
			local catalog = record and models.list(record) or {}
			local known = preferences.ordered(record, catalog)
			local labels, order = {}, {}
			-- Preference changes reorder existing rows without destroying the clicked
			-- control or resetting the user's catalog scroll position.
			for _, id in ipairs(catalog) do labels[#labels + 1] = id .. tostring(models.isFree(record, id)) end
			for index, id in ipairs(known) do order[id] = index end
			local nextSignature = (record and record.id or "") .. "\0" .. table.concat(labels, "\0")
			if signature ~= nextSignature then
				for _, entry in ipairs(rows) do entry.button.instance:Destroy() end
				rows = {}
				list.instance.CanvasPosition = Vector2.new(0, 0)
				for index, id in ipairs(known) do
					local selected = id == record.model
					local free = models.isFree(record, id)
					local button = P.rowButton(list.instance, { name = "Model_" .. id, height = modelHeight,
						selected = selected, bgSelected = theme.color.surfaceActive, radius = theme.radius.sm,
						stroke = free, strokeColor = free and P.freeModelOutline(theme.color.surface) or nil,
						strokeWidth = free and 1 or nil,
						padding = { x = theme.space.sm }, gap = theme.space.sm, layoutOrder = index,
						onClick = function()
							local ok, why = providers.setModel(record.id, id)
							if not ok then overlay.toast(tostring(why or "Unable to select this model"), "warn", 3); return end
							notify()
						end })
					local copy = P.column(button.row, { name = "ModelDetails", size = UDim2.new(0, 0, 0, 0),
						auto = "Y", flex = "Fill", gap = theme.space.hair, layoutOrder = 1 })
					local label = P.text(copy, { name = "ModelName", text = id, role = "small",
						color = selected and theme.color.text or theme.color.textSecondary,
						size = UDim2.new(1, 0, 0, theme.text.small.height), truncate = true, layoutOrder = 1 })
					local badge = traits.badge(id, record)
					local meta = P.text(copy, { name = "ModelMetadata", text = badge or "", role = "caption", color = theme.color.textTertiary,
						size = UDim2.new(1, 0, 0, theme.text.caption.height), truncate = true, layoutOrder = 2 })
					local mark = button.icon("check", 3, theme.color.accentHot)
					mark.Visible = selected
					rows[#rows + 1] = { id = id, free = free, button = button, label = label, mark = mark, meta = meta }
				end
				signature = nextSignature
			end
			for _, entry in ipairs(rows) do
				local selected = record and entry.id == record.model
				entry.button.instance.LayoutOrder = order[entry.id]
				entry.button.setSelected(selected)
				entry.label.TextColor3 = selected and theme.color.text or theme.color.textSecondary
				entry.mark.Visible = selected == true
				local badge = traits.badge(entry.id, record)
				entry.label.Text = entry.id
				entry.meta.Text = entry.free and ("Free" .. (badge and " | " .. badge or "")) or (badge or "")
				entry.meta.TextColor3 = entry.free and theme.color.success or theme.color.textTertiary
				entry.meta.Visible = entry.meta.Text ~= ""
				if entry.id == "auto" then
					local route = freeRoute.status(record)
					if route.supported and route.scheduleOpen == false then
						entry.label.Text, entry.meta.Text = "Auto (outside free hours)", freeHoursMeta(record)
						autoRow, autoClosed = entry, true
					elseif route.supported and route.available == false then
						entry.label.Text, entry.meta.Text = "Auto (unavailable)", "Free | " .. tostring(route.availability or "Check provider setup")
						autoRow, autoClosed = entry, false
					elseif route.supported and route.enabled == false then
						entry.label.Text, entry.meta.Text = "Auto (provider routing)", "Free | Automatic routing off"
						autoRow, autoClosed = entry, false
					elseif freeRoute.eligible(record) then
						entry.label.Text = "Auto (fastest verified)"
						entry.meta.Text = route.ms and string.format("Free | %.1fs probe", route.ms / 1000)
							or (route.running and "Free | Measuring" or "Free")
						autoRow, autoClosed = entry, false
					else
						autoRow, autoClosed = nil, false
					end
				end
				if preferences.favorite(record, entry.id) then
					entry.meta.Text = "Favorite" .. (entry.meta.Text ~= "" and " | " .. entry.meta.Text or "")
					entry.meta.Visible = true
				end
			end
			filterRows()
			renderEffort()
			local chrome = modal.card.Size.Y.Offset - modal.scroll.instance.Size.Y.Offset
			modalProps.height = math.min(providerPicker.preferredHeight(), chrome + expandedListTop
				+ math.min(math.max(#rows, 2), 7) * (modelHeight + rowGap) + theme.space.lg
				+ effortHeight + theme.space.md)
			modal.relayout()
			fit()
		end

		P.button(modal.footer, { name = "FetchModels", text = "Refresh", variant = "ghost", size = "sm", layoutOrder = 1,
			onClick = function(button)
				local record = providers.active()
				if not record or fetching then return end
				fetching = true; button.setEnabled(false); button.setText("Fetching…")
				local superseded = false
				local function aborted() return superseded or modal.closed or providers.active() ~= record end
				local unsubscribe = providers.changed:connect(function()
					if providers.active() ~= record then superseded = true end
				end)
				local closed = modal.scrim.Destroying:Connect(function() superseded = true; unsubscribe() end)
				task.spawn(function()
					local ok, found, note = pcall(models.discover, record, { force = true, aborted = aborted })
					unsubscribe(); closed:Disconnect()
					fetching = false
					if modal.closed then return end
					button.setEnabled(true); button.setText("Refresh")
					if aborted() then return end
					overlay.toast(tostring(ok and note or found), ok and #found > 0 and "good" or "warn", 3)
					render(); notify()
				end)
			end })
		P.button(modal.footer, { name = "ModelOptions", text = "Options", variant = "ghost", size = "sm", layoutOrder = 2,
			onClick = function(button)
				local record = providers.active()
				local id = record and tostring(record.model):lower() or ""
				local forced = (config.get("agent.forceReasoning", {}) or {})[id] == true
				local policy = record and sampling.state(record)
				local mode = policy and (({ auto = "Automatic", send = "Send", omit = "Omit" })[policy.override] or "Automatic")
				local options = {
					{ label = record and preferences.favorite(record, record.model) and "Remove favorite" or "Add favorite", value = "favorite", detail = "Selected model on this provider" },
					{ label = "Favorites only", value = "favorites", selected = favoritesOnly },
					{ label = "Known tool support only", value = "tools", selected = toolsOnly },
					{ label = "Clear model filters", value = "clear", disabled = filter == "" and not freeOnly and not favoritesOnly and not toolsOnly },
					{ label = "Temperature", value = "temperature", detail = policy and (mode .. (policy.allowed and (" · " .. tostring(config.get("agent.temperature", 0.4))) or " · omitted")) or "Choose a provider first" },
					{ label = "Add model ID", value = "add", icon = "plus" },
					{ label = "Reasoning support", value = "reasoning", selected = forced, detail = "Override for the selected model" },
					{ label = "Context window", value = "context", detail = "Override for the selected model" },
					{ label = "Manage providers", value = "manage", icon = "sliders" },
				}
				if effortLevels then
					table.insert(options, 2, { label = "Reasoning effort", value = "effort", detail = effortSending == "off"
						and "Provider default (global)" or (tostring(effortSending):gsub("^%l", string.upper) .. " (global)") })
				end
				if not freeButton.instance.Visible then
					table.insert(options, 1, { label = "Free models only", value = "free", selected = freeOnly })
				end
				overlay.menu({ target = button.instance, rowHeight = control, options = options, onSelect = function(value)
					if value == "manage" then modal.close(); env.require("ui/app").show("providers"); return end
					if value == "free" then
						freeOnly = not freeOnly; freeButton.setVariant(freeOnly and "secondary" or "ghost"); filterRows(); return
					end
					if value == "favorites" then favoritesOnly = not favoritesOnly; filterRows(); return end
					if value == "tools" then toolsOnly = not toolsOnly; filterRows(); return end
					if value == "clear" then
						filter, freeOnly, favoritesOnly, toolsOnly = "", false, false, false
						search.set(""); freeButton.setVariant("ghost"); filterRows(); return
					end
					if not record then overlay.toast("Add a provider first", "info", 2); return end
					if value == "favorite" then
						local ok, why = preferences.setFavorite(record, record.model)
						if not ok then overlay.toast(tostring(why), "warn", 3) end
					elseif value == "temperature" then temperatureMenu(button.instance, record)
					elseif value == "effort" then effortMenu(button.instance)
					elseif value == "add" then
						overlay.prompt({ title = "Add a model ID", placeholder = "Exact model ID", confirmText = "Add", onConfirm = function(text)
							local ok, note = models.add(record, text, { select = true })
							overlay.toast(tostring(note), ok and "good" or "warn", 3); notify()
						end })
					elseif id ~= "" and value == "reasoning" then
						local ok, why = overrides.reasoning(id, not forced)
						if not ok then overlay.toast(tostring(why), "warn", 3) else notify() end
					elseif id ~= "" and value == "context" then
						local claims = config.get("agent.forceContext", {}) or {}
						overlay.prompt({ title = "Context window", description = "Token limit. Leave empty to use the documented value.",
							placeholder = "1000000", value = claims[id] and tostring(claims[id]) or "", confirmText = "Save",
							onConfirm = function(text)
								local ok, why = overrides.context(id, text)
								if not ok then overlay.toast(tostring(why), "warn", 3) else notify() end
							end })
					end
				end })
			end })
		P.button(modal.footer, { name = "PickerDone", text = "Done", variant = "primary", size = "sm", layoutOrder = 3,
			onClick = function() modal.close() end })
		local function sizeFooter()
			for _, button in ipairs(modal.footer:GetChildren()) do
				if button:IsA("GuiButton") then providerPicker.sizeButton({ instance = button }, control) end
			end
		end
		sizeFooter()
		local unsubscribe = providers.changed:connect(function(kind)
			if kind == "health" then
				local info = providerPicker.describe(providers.active())
				providerStatus.Text, providerStatus.TextColor3 = info.detail, info.tone
			end
			if kind ~= "health" then
				render()
				local record = providers.active()
				if record then freeRoute.refresh(record) end
			end
		end)
		local unsubscribeRoute = freeRoute.changed:connect(render)
		local unsubscribeModels = models.changed:connect(render)
		local unsubscribeBridge = env.require("net/bridge").changed:connect(render)
		local unsubscribeConfig = config.changed:connect(function(path)
			if path == nil or path == "agent" or path == "agent.effort" or path == "agent.forceReasoning"
				or path == "agent.forceContext" or path == "agent.forceSampling" or path == "agent.temperature" or path == "agent.autoFreeRouting"
				or path == "ui.modelFavorites" or path == "ui.recentModels" then render() end
		end)
		local unsubscribeResponsive = responsive.changed:connect(function()
			if modal.closed then return end
			local target = providerPicker.target()
			if target == control then fit(); return end
			control = target
			providerHeight = math.max(control, theme.text.label.height + theme.text.caption.height + theme.space.md * 2 + theme.space.hair)
			modelHeight = math.max(control, theme.text.small.height + theme.text.caption.height + theme.space.hair + theme.space.sm * 2)
			expandedListTop = providerHeight + selectionHeight + theme.space.md + control + theme.space.sm * 2 + theme.text.caption.height
			modalProps.minTarget = target
			sizeFooter()
			freeButton.instance.Size = UDim2.fromOffset(math.max(filterWidth, target), control)
			for _, entry in ipairs(rows) do entry.button.instance.Size = UDim2.new(1, 0, 0, modelHeight) end
			render()
		end)
		local tickFreeHours = env.require("runtime/clock").interval(1, function()
			if modal.closed or not autoRow or autoRow.meta.Parent == nil then return end
			local record = providers.active()
			local countdown = record and community.countdown(record)
			local closed = countdown ~= nil and countdown.open == false
			-- Opening or closing rewrites the row's whole label, so the list is
			-- re-rendered once at that boundary; between them only the time moves.
			if closed ~= autoClosed then render(); return end
			if not closed then return end
			local text = freeHoursMeta(record)
			if preferences.favorite(record, autoRow.id) then text = "Favorite | " .. text end
			if autoRow.meta.Text ~= text then autoRow.meta.Text = text end
		end)
		modal.scrim.Destroying:Connect(function() unsubscribe(); unsubscribeRoute(); unsubscribeModels(); unsubscribeBridge(); unsubscribeConfig(); unsubscribeResponsive(); tickFreeHours() end)
		render()
		local record = providers.active()
		if record then freeRoute.refresh(record) end
		modal.render = render
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/panels/permission
-- ==========================================================================
__UAI_MODULES["ui/panels/permission"] = (function()
-- The permission prompt.
--
-- The loop blocks on a thread while this is open, so it has to be reliable: one
-- prompt at a time, queued, and always resolved -- closing it counts as a refusal.
-- An unresolved prompt would park the agent until its own timeout.
--
-- It listens to every conversation rather than to the open one. It used to attach to
-- whichever session the transcript was showing, which meant a second conversation
-- left running in the background asked for permission into a stream nobody was
-- subscribed to: no prompt appeared, its three-minute deadline expired, and every
-- write it had planned came back to the model as a refusal. Since a prompt can now
-- arrive from a conversation that is not on screen, the modal says which one.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local message = env.require("ui/chat/message")

	local M = { queue = {}, showing = false }

	local RISK_TONE = { read = "info", write = "warn", danger = "bad" }

	local RISK_TEXT = {
		read = "This only reads. Nothing changes.",
		write = "This changes something in the game or on disk.",
		danger = "This runs code, deletes data, or reaches the server. It cannot be undone.",
	}

	local function present(request)
		M.showing = true

		local remember = false
		local resolved = false
		local modal

		local function answer(allowed)
			if resolved then return end
			resolved = true
			pcall(request.resolve, allowed, remember)
			if modal then modal.close(true) end
			M.showing = false
			-- Drain the next prompt on the same frame so a batch of tool calls does
			-- not make the user wait between decisions.
			local next_request = table.remove(M.queue, 1)
			if next_request then present(next_request) end
		end

		modal = overlay.modal({
			title = "Allow " .. tostring(request.name) .. "?",
			description = RISK_TEXT[request.risk or "write"] or RISK_TEXT.write,
			width = theme.size.modalWide,
			dismissable = true,
			onClose = function() answer(false) end,
		})
		if not modal then
			answer(false)
			return
		end

		local badgeRow = P.row(modal.content, {
			name = "Asking",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.badge(badgeRow, {
			text = tostring(request.risk or "write"),
			tone = RISK_TONE[request.risk or "write"] or "warn",
			layoutOrder = 1,
		})
		-- Which conversation is asking. With one prompt queue serving every open
		-- conversation, "Allow run_luau?" on its own does not say whose turn it
		-- belongs to -- and answering the wrong one is not recoverable.
		if request.sessionTitle then
			P.text(badgeRow, {
				name = "AskingIn",
				text = "in " .. tostring(request.sessionTitle),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				flex = "Fill",
				layoutOrder = 2,
			})
		end

		if request.description then
			local description = P.text(modal.content, {
				text = tostring(request.description),
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			description.Size = UDim2.new(1, 0, 0, 0)
		end

		-- The arguments are the whole point of the prompt: "allow run_luau" means
		-- nothing without seeing the code.
		local arguments = P.column(modal.content, { name = "PermissionArguments", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm, layoutOrder = 3 })
		local args = request.args or {}
		local parts, facts = message.splitArguments(args)
		local order = 0
		for _, fact in ipairs(facts) do
			order = order + 1
			P.text(arguments, { name = "ArgumentName", text = fact.key, role = "label", layoutOrder = order })
			order = order + 1
			message.codeBlock(arguments, { text = fact.value, lang = "text", numbers = false, maxLines = 12, layoutOrder = order })
		end
		for _, part in ipairs(parts) do
			order = order + 1
			message.codeBlock(arguments, { text = part.text, lang = part.lang or "text", label = part.label or part.key, maxLines = 12, layoutOrder = order })
		end
		if order == 0 then
			P.text(arguments, { name = "NoArguments", text = "No arguments.", role = "small", color = theme.color.textSecondary })
		else
			P.button(arguments, { name = "ReviewPermissionArguments", text = "View full arguments", variant = "ghost", size = "sm", layoutOrder = order + 1,
				onClick = function()
					local ok, encoded = pcall(util.encode, args)
					if ok then overlay.code({ title = tostring(request.name) .. " arguments", code = encoded, language = "json" }) end
				end })
		end

		local rememberRow = P.row(modal.content, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 4,
		})
		local rememberText = P.column(rememberRow, {
			size = UDim2.new(0, 0, 0, 0),
			auto = "Y",
			flex = "Fill",
			gap = 0,
			layoutOrder = 1,
		})
		P.text(rememberText, { text = "Remember this answer", role = "label", wrap = true, auto = "Y" })
		P.text(rememberText, {
			text = "Applies to every future " .. tostring(request.name) .. " call. Change it later in the Tools panel.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		local switch = C.switch(rememberRow, {
			value = false,
			onChange = function(value) remember = value end,
		})
		switch.instance.LayoutOrder = 2

		-- Named, like every other control that decides something. Two buttons both
		-- called "Button" is unreadable from a dump and unreachable from a test, and
		-- this is the one dialog in the client where pressing the wrong one is not
		-- recoverable.
		P.button(modal.footer, {
			name = "PermissionDeny",
			text = "Deny",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			onClick = function()
				answer(false)
			end,
		})
		P.button(modal.footer, {
			name = "PermissionAllow",
			text = "Allow",
			variant = request.risk == "danger" and "danger" or "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				answer(true)
			end,
		})
	end

	-- Watches every conversation in the client.
	--
	-- `attach` is kept because the app calls it whenever the open conversation changes,
	-- but it no longer decides what is heard: the subscription is to the session
	-- module's own fan-out, made once and never dropped, so a prompt from a
	-- conversation nobody is looking at still reaches the screen.
	local function onEvent(session, event)
		if event.kind ~= "permission:ask" then return end
		-- A subagent is headless and its prompts are forwarded onto its parent's
		-- stream by agent/subagent, so the child's own copy would be a second modal
		-- for one decision.
		if session and session.headless then return end
		local request = {
			id = event.id,
			name = event.name,
			risk = event.risk,
			description = event.description,
			args = event.args,
			resolve = event.resolve,
			sessionTitle = session and session.title or nil,
		}
		if M.showing then
			M.queue[#M.queue + 1] = request
		else
			present(request)
		end
	end

	function M.watch()
		if M.watching then return M end
		local sessions = env.require("agent/session")
		M.watching = env.require("runtime/dispose").add(
			sessions.anyEvent:connect(onEvent), "permission.watch")
		return M
	end

	-- Kept for the app, which calls it on every conversation switch. Starting the
	-- global watch is all it has left to do.
	function M.attach()
		return M.watch()
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/providerpicker
-- ==========================================================================
__UAI_MODULES["ui/panels/providerpicker"] = (function()
-- Saved-provider navigation for the model picker. Configuration stays in registry.
return function(env)
	local util = env.require("runtime/util")
	local search = env.require("runtime/search")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local overlay = env.require("ui/overlay")
	local providers = env.require("provider/registry")
	local models = env.require("provider/models")
	local urls = env.require("net/url")
	local bridge = env.require("net/bridge")
	local community = env.require("provider/community_key")
	local M = {}
	local opened

	function M.target()
		return math.max(theme.size.control, responsive.minTarget(), responsive.isMobile() and 40 or 0)
	end

	function M.preferredHeight()
		-- The catalogue can use the screen's height while the app's compact
		-- placement, typography and other windows keep their normal metrics.
		return math.ceil(theme.size.modelPickerHeight / (responsive.isMobile() and theme.metricScale or 1))
	end

	function M.sizeButton(button, height)
		local size = button.instance.Size
		button.instance.Size = UDim2.new(size.X.Scale, size.X.Scale == 0 and math.max(size.X.Offset, height) or size.X.Offset, 0, height)
	end

	function M.describe(record)
		if not record then return { detail = "Add a provider to get started", route = "", tone = theme.color.textTertiary } end
		local known, free = models.list(record), 0
		for _, id in ipairs(known) do if models.isFree(record, id) then free = free + 1 end end
		local detail = util.pluralise(#known, "model") .. (free > 0 and (" / " .. free .. " free") or "")
		local route, tone = urls.display(record.baseUrl), theme.color.textTertiary
		if community.isApplied(record) then
			local availability = community.availability(record)
			local countdown = community.countdown(record)
			detail = "Community access / " .. (countdown and countdown.text or community.shortHours)
			route, tone = community.shortHours, availability.open and theme.color.success or theme.color.warn
		elseif record.preset == "hcnsec" then
			detail = "Personal HCNSEC / " .. detail
			if providers.keyPoolSize(record) == 0 then detail, tone = "API key required / " .. detail, theme.color.warn end
		elseif providers.isCline(record) then
			local state = bridge.clineStatus()
			local labels = { ready = "Desktop connected", ["auth-required"] = "Sign in on desktop", disabled = "Enable in Tunnels",
				missing = "Install Cline on desktop", starting = "Connecting on desktop", failed = "Check desktop connection",
				disconnected = "Connect the desktop bridge", unavailable = "Update the desktop bridge" }
			detail = (labels[state.state] or "Check desktop connection") .. (free > 0 and (" / " .. free .. " free") or "")
			route, tone = "Cline / Text models / Desktop only", state.available and theme.color.success or theme.color.textSecondary
		elseif providers.isOpencodeZen(record) and bridge.opencodeStatus().available then
			detail = "Desktop CLI connected" .. (free > 0 and (" / " .. free .. " free") or "")
		elseif record.authStyle == "none" then
			detail = "No API key / " .. detail
		elseif providers.keyPoolSize(record) == 0 then
			detail, tone = "API key required / " .. detail, theme.color.warn
		end
		if record.enabled == false then detail, tone = "Disabled / " .. detail, theme.color.textDisabled
		elseif providers.keyPoolSize(record) > 0 and #providers.requestKeys(record) == 0 then
			detail, tone = "No active API key / " .. detail, theme.color.warn
		elseif providers.cooling(record) then detail, tone = env.require("provider/health").message(record) .. " / " .. detail, theme.color.warn end
		local admission = env.require("provider/availability").describe(record)
		if not admission.ready and admission.state ~= "disabled" and admission.state ~= "key-required" then
			detail, tone = admission.message, theme.color.warn
		end
		return { detail = detail, route = route, tone = tone }
	end

	function M.open(owner, onChange)
		if opened and not opened.closed then return opened end
		local target = M.target()
		local modal = overlay.modal({ title = "Switch provider", width = theme.size.modelPicker,
			height = M.preferredHeight(), minTarget = target, scroll = true })
		if not modal then return end
		opened = modal
		local rows, filter = {}, ""
		local count
		local function filterRows()
			local matches, visible = search.compile(filter), 0
			for _, entry in ipairs(rows) do
				entry.button.instance.Visible = matches(entry.search) ~= nil
				if entry.button.instance.Visible then visible = visible + 1 end
			end
			if count then
				count.Text = visible == #rows and util.pluralise(#rows, "saved connection")
					or string.format("%d of %d connections", visible, #rows)
			end
			local empty = modal.content:FindFirstChild("NoSavedProviderMatch")
			if empty then empty.Visible = visible == 0 end
		end
		P.field(modal.content, { name = "ProviderSwitchSearch", placeholder = "Search saved providers...", role = "small", height = target,
			layoutOrder = 1, onChange = function(text) filter = text; filterRows() end })
		count = P.text(modal.content, { name = "SavedProviderCount", text = "Your saved connections", role = "caption", color = theme.color.textTertiary, layoutOrder = 2 })
		local function render()
			if modal.closed then return end
			local previous = {}
			for _, entry in ipairs(rows) do previous[entry.id] = entry end
			rows = {}
			local active = providers.active()
			for index, record in ipairs(providers.list()) do
				local info = M.describe(record)
				local entry = previous[record.id]
				previous[record.id] = nil
				if not entry then
					local button = P.rowButton(modal.content, { name = "Option_" .. record.id,
						height = theme.text.small.height + theme.text.caption.height * 2 + theme.space.sm * 2 + theme.space.hair * 2,
						selected = active and active.id == record.id, bgSelected = theme.color.surfaceActive,
						bg = theme.color.surface, radius = theme.radius.md,
						stroke = true, strokeColor = theme.color.borderSubtle, padding = { x = theme.space.md }, gap = theme.space.sm,
						layoutOrder = index + 2, onClick = function()
							local ok, why = providers.setActive(record.id)
							if not ok then overlay.toast(why or "This provider is no longer available.", "warn"); return end
							modal.close(); if onChange then onChange() end
						end })
					local text = P.column(button.row, { name = "ProviderInfo", size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = theme.space.hair })
					local name = P.text(text, { name = "ProviderName", text = record.label, role = "label", truncate = true,
						size = UDim2.new(1, 0, 0, theme.text.small.height), layoutOrder = 1 })
					local status = P.text(text, { name = "ProviderAvailability", text = info.detail, role = "caption", color = info.tone, truncate = true,
						size = UDim2.new(1, 0, 0, theme.text.caption.height), layoutOrder = 2 })
					local route = P.text(text, { name = "ProviderRoute", text = info.route, role = "caption", color = theme.color.textTertiary, truncate = true,
						size = UDim2.new(1, 0, 0, theme.text.caption.height), layoutOrder = 3 })
					local mark = button.icon("check", 3, theme.color.accentHot)
					entry = { id = record.id, button = button, name = name, status = status, route = route, mark = mark }
				end
				entry.name.Text, entry.status.Text, entry.status.TextColor3, entry.route.Text = record.label, info.detail, info.tone, info.route
				entry.mark.Visible = active and active.id == record.id or false
				entry.button.setSelected(entry.mark.Visible)
				entry.button.instance.LayoutOrder = index + 2
				entry.search = (record.label .. " " .. info.route .. " " .. info.detail):lower()
				rows[#rows + 1] = entry
			end
			for _, entry in pairs(previous) do entry.button.instance:Destroy() end
			filterRows()
		end
		P.text(modal.content, { name = "NoSavedProviderMatch", text = "No matching providers. Add a connection in Manage providers.",
			role = "small", color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 10000 })
		M.sizeButton(P.button(modal.footer, { name = "ManageSavedProviders", text = "Manage providers", variant = "secondary", size = "sm",
			onClick = function() modal.close(); owner.close(); env.require("ui/app").show("providers") end }), target)
		local unsubscribe = providers.changed:connect(render)
		local unsubscribeBridge = bridge.changed:connect(render)
		local unsubscribeModels = models.changed:connect(render)
		local ownerClosed = owner.scrim.Destroying:Connect(function() if not modal.closed then modal.close() end end)
		modal.scrim.Destroying:Connect(function() unsubscribe(); unsubscribeBridge(); unsubscribeModels(); ownerClosed:Disconnect() end)
		render()
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/panels/providers
-- ==========================================================================
__UAI_MODULES["ui/panels/providers"] = (function()
-- Providers panel: a list on the left, one provider's whole configuration on the
-- right.
--
-- This is the screen that makes the client universal, so it is deliberately plain: a
-- base URL, a key, an auth style and a model. Anything that speaks
-- /v1/chat/completions is a first-class citizen here, and the presets are only a way
-- to avoid typing a URL.
--
-- It was a list of cards plus one modal holding nine rows of form, and four things
-- were wrong with that beyond the density. The modal was the only way to see any of a
-- record's configuration, and it printed the API key in clear text while the hint
-- underneath said the key was redacted. Picking a different preset inside it rebuilt
-- the record from scratch and threw away whatever had been typed, with no warning. The
-- record's headers, params, query, order and note -- five fields the registry keeps,
-- two of which decide whether Azure and OpenRouter work at all -- had no
-- representation anywhere in the interface. And every completion fired a health event
-- that rebuilt the entire panel mid-turn, scroll position included.
return function(env)
	local util = env.require("runtime/util")
	local keyData = env.require("runtime/provider_keys")
	local clock = env.require("runtime/clock")
	local caps = env.require("runtime/caps")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local R = env.require("ui/settingsrows")
	local overlay = env.require("ui/overlay")
	local catalog = env.require("provider/catalog")
	local registry = env.require("provider/registry")
	local models = env.require("provider/models")
	local chat = env.require("provider/chat")
	local traits = env.require("provider/traits")
	local communityKey = env.require("provider/community_key")
	local icons = env.require("ui/icons")
	local urls = env.require("net/url")
	local connectionActions = env.require("provider/connection_actions")

	local M = {}

	local AUTH_OPTIONS = {
		{ value = "bearer", label = "Bearer" },
		{ value = "x-api-key", label = "x-api-key" },
		{ value = "x-goog-api-key", label = "x-goog-api-key" },
		{ value = "api-key", label = "api-key" },
		{ value = "both", label = "Both" },
		{ value = "none", label = "None" },
	}

	local function labelOf(options, value)
		for _, option in ipairs(options) do
			if option.value == value then return option.label end
		end
		return tostring(value)
	end

	local function keyUsage(record)
		if keyData.mode(record) == "single" then
			local index = keyData.selected(record)
			local entry = keyData.entries(record)[index or 0]
			local name = entry and entry.name ~= "" and entry.name or ("API key " .. tostring(index or 1))
			return "Use one key: " .. name .. (entry and entry.paused and " (paused)" or "")
		end
		local pool, active = keyData.entries(record), 0
		for _, entry in ipairs(pool) do if not entry.paused then active = active + 1 end end
		if active < #pool then return active == 0 and "All API keys are paused" or ("Rotate " .. active .. " active keys / " .. #pool .. " saved") end
		return "Rotate keys automatically"
	end

	local function sameKeyConnection(record, updated)
		if record.apiKey ~= updated.apiKey or keyData.mode(record) ~= keyData.mode(updated)
			or keyData.selected(record) ~= keyData.selected(updated) then return false end
		for index in ipairs(keyData.keys(record)) do
			if keyData.paused(record, index) ~= keyData.paused(updated, index) then return false end
		end
		return true
	end

	local function applyKeys(record, updated)
		local connectionChanged = not sameKeyConnection(record, updated)
		record.apiKey = updated.apiKey
		record.keyNames = util.deepCopy(updated.keyNames)
		record.keyPaused = util.deepCopy(updated.keyPaused)
		record.keyIds = util.deepCopy(updated.keyIds)
		record.keyMode = updated.keyMode
		record.selectedKey = updated.selectedKey
		if connectionChanged then record.keyRotation = nil end
		return connectionChanged
	end

	-- Never the key itself.
	--
	-- The editor rendered record.apiKey into an ordinary field, so opening Edit on any
	-- saved provider printed the whole secret on screen -- while the hint under it said
	-- "redacted in the log", the privacy pane promised only the last four characters
	-- were kept, and the export path reduced it to exactly that.
	local function maskedKey(record)
		local raw = tostring(record.apiKey or "")
		if registry.isCline(record) then return "Sign in to Cline in the desktop app", nil end
		if record.authStyle == "none" then return "No API key required", nil end
		if util.trim(raw) == "" and registry.opencodeKeyOptional(record) then return "Provided by connected OpenCode CLI", nil end
		if util.trim(raw) == "" then return "not set", "warn" end
		local pool = registry.keysOf(record)
		if #pool > 0 and #keyData.requestKeys(record) == 0 then return "No active API key", "warn" end
		if keyData.mode(record) == "single" then
			local key = keyData.requestKeys(record)[1]
			if not key then return "Choose an API key", "warn" end
			return #key <= 4 and "set" or (string.rep("\226\128\162", 4) .. " " .. key:sub(-4)), nil
		end
		if #pool > 1 then
			local last = pool[#pool]
			local suffix = #last <= 4 and "set" or (string.rep("\226\128\162", 4) .. " " .. last:sub(-4))
			return suffix .. "  \194\183  pool of " .. #pool .. " keys", nil
		end
		local key = pool[1] or ""
		if #key <= 4 then return "set", nil end
		return string.rep("\226\128\162", 4) .. " " .. key:sub(-4), nil
	end

	local function modelSource(record)
		if registry.isCline(record) then return "Cline's free catalog through the desktop bridge" end
		if registry.isOpencodeZen(record) and env.require("net/bridge").opencodeStatus().available then return "OpenCode CLI through the desktop bridge" end
		return urls.display(registry.endpoint(record, "/models"))
	end

	local function fetchLabel(record)
		return registry.isCline(record) and "Refresh Cline models" or "Fetch models"
	end

	-- Everything the registry knows about a record and the panel never said.
	--
	-- `chat.endpointOf` and `registry.endpoint` both existed for this and both had zero
	-- call sites; the comment on endpointOf says "for the Providers panel to show".
	local function factsFor(record)
		local health = env.require("provider/health").read(record)
		local key, keyTone = maskedKey(record)
		local streaming = record.stream ~= false and config.get("agent.stream", true)
		if record.params and record.params.stream ~= nil then streaming = record.params.stream == true end
		local transport = streaming and "Buffered SSE over HTTP" or "JSON over HTTP"
		if not chat.supportsSocket(record) and util.trim(record.wsUrl) ~= "" then
			transport = transport .. " (socket unused for this protocol)"
		elseif streaming and util.trim(record.wsUrl) ~= "" then
			transport = caps.ws and "UAI gateway socket, with HTTP fallback before send" or "Buffered SSE over HTTP (socket unavailable)"
		end
		local route = env.require("net/transport").target()
		if route == "cowork" then transport = "Web relay"
		elseif route == "companion" then transport = "Relay (companion)" end
		if registry.isCline(record) then transport = "Cline CLI through the desktop bridge / text only" end
		local out = {
			{ key = "Endpoint", value = registry.isCline(record) and "Cline through Project UAI Bridge" or urls.display(chat.endpointOf(record)) },
			{ key = "Model list", value = modelSource(record) },
			{ key = "Protocol", value = chat.protocolOf(record) == "responses" and "OpenAI Responses" or labelOf(chat.STYLES, chat.styleOf(record)) },
			{ key = "Availability", value = env.require("provider/availability").describe(record).message },
			{ key = "Auth", value = labelOf(AUTH_OPTIONS, record.authStyle or "bearer")
				.. "  \194\183  " .. key, tone = keyTone },
			{ key = "Streaming", value = transport },
		}
		if not registry.isCline(record) and #registry.keysOf(record) > 0 then
			out[#out + 1] = { key = "Key usage", value = keyUsage(record) }
		end
		if (health.ok or 0) + (health.fail or 0) > 0 then
			out[#out + 1] = {
				key = "Health",
				value = string.format("%d ok, %d failed", health.ok or 0, health.fail or 0),
				tone = (health.streak or 0) > 0 and "warn" or "good",
			}
		end
		-- Recorded on every success and shown nowhere until now.
		if (health.lastMs or 0) > 0 then
			out[#out + 1] = { key = "Last reply", value = util.formatDuration(health.lastMs) }
		end
		-- The bench was a red dot with no words: no label, no remaining time, and no
		-- statement of the three-failure rule that put it there.
		if registry.cooling(record) then
			local left = math.max((health.cooldownUntil or 0) - clock.ms(), 0)
			out[#out + 1] = {
				key = "Benched",
				value = string.format("%s left, after 3 failures in a row", util.formatDuration(left)),
				tone = "bad",
			}
		end
		if registry.needsExecutor(record) then
			local have = caps.http == "executor"
			out[#out + 1] = {
				key = "Requires",
				value = have and "an executor HTTP function, which this host has"
					or "an executor HTTP function, which this host does not have",
				tone = have and "good" or "bad",
			}
		end
		return out
	end

	-- Keep an unfinished Add in memory for this client session. Existing records
	-- remain isolated edit copies; their unsaved changes do not become Add drafts.
	local addDraft = nil
	env.require("runtime/dispose").add(config.changed:connect(function(path)
		if (path == nil or path == "security" or path == "security.vault") and config.vaultStatus().locked then addDraft = nil end
	end), "provider draft vault state")

	local function draftDirty(candidate)
		local blank = registry.blank("custom")
		for _, key in ipairs({ "preset", "label", "baseUrl", "apiKey", "api", "authStyle", "model" }) do
			if util.trim(candidate[key]) ~= util.trim(blank[key]) then return true end
		end
		return false
	end

	-- Provider gallery ---------------------------------------------------------
	--
	-- Adding a provider used to start with a form and a preset dropdown, which asked
	-- someone to know a vendor's name and URL before it showed them a single vendor.
	-- The gallery starts from what a person actually has -- a budget -- and puts the
	-- free routes first, paid ones behind a tab, local servers behind another. Search
	-- spans all three, because a name is the one thing someone arriving here usually
	-- does know.
	--
	-- Roomy layouts pin search, tabs and counts. Short layouts keep those same
	-- controls in one scrolling body so the keyboard cannot crowd out the catalog.

	local function highlighted(text, needle)
		local value = tostring(text or "")
		if not needle or needle == "" then return value, false end
		local at = value:find(needle, 1, true)
		if not at then return value, false end
		local function escape(part)
			return (part:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
		end
		return escape(value:sub(1, at - 1))
			.. string.format('<b><font color="#%s">%s</font></b>', theme.color.accent:ToHex(), escape(needle))
			.. escape(value:sub(at + #needle)), true
	end

	local function countText(count, tier, searching)
		if searching then
			return count == 1 and "1 match in all providers" or (tostring(count) .. " matches in all providers")
		end
		if tier == "free" then
			return count == 1 and "1 free route" or (tostring(count) .. " free routes")
		elseif tier == "local" then
			return count == 1 and "1 local server" or (tostring(count) .. " local servers")
		end
		return count == 1 and "1 paid provider" or (tostring(count) .. " paid providers")
	end

	-- `opts.onPick` receives the chosen preset and the gallery closes into whatever
	-- opened it. `opts.onSaved` is the add flow: the gallery closes and the editor
	-- opens, seeded from the preset, so a name and a key are typed in one place.
	function M.picker(opts)
		opts = opts or {}
		local dialog = overlay.dialog({
			name = "ProviderPicker",
			width = responsive.isMobile() and theme.size.providerPicker or (theme.size.providerPicker + theme.size.menuMin),
			height = math.ceil(theme.size.providerPickerTall / (responsive.isMobile() and theme.metricScale or 1)),
		})
		if not dialog then return end

		-- The gallery also opens from inside the editor, where a modal is already on
		-- screen. Both surfaces share the modal layer, so the picker lifts itself and
		-- its dismissal regions one step above the editor instead of leaving the
		-- editor's card to draw over the dimmed backdrop.
		local lift = theme.z.modal + 6
		dialog.scrim.ZIndex = lift
		for _, child in ipairs(dialog.scrim:GetChildren()) do
			if child:IsA("GuiObject") then child.ZIndex = lift + 1 end
		end

		local closed, chosen, pendingSearch = false, false, nil
		local tier = opts.tier
		local known = false
		for _, entry in ipairs(catalog.tiers) do
			if entry.id == tier then known = true end
		end
		if not known then tier = "free" end
		local query = ""

		local viewport = P.scroll(dialog.card, { name = "PickerViewport", size = UDim2.fromScale(1, 1), bar = 0 })
		viewport.instance.ScrollingEnabled = false
		viewport.instance.VerticalScrollBarInset = Enum.ScrollBarInset.None
		local root = P.column(viewport.instance, {
			name = "PickerRoot",
			size = UDim2.new(1, 0, 0, dialog.height),
			gap = theme.space.md,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.md },
		})

		local head = P.column(root, {
			name = "PickerHead",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 1,
			-- The dialog's close button floats over this corner; the title stops
			-- short of it rather than running underneath.
			padding = { right = dialog.closeInset },
		})
		P.text(head, {
			name = "PickerOverline",
			text = opts.onPick and "CONNECTION PRESET" or "INFERENCE PROVIDERS",
			role = "overline",
			color = theme.color.accent,
			size = UDim2.new(1, 0, 0, theme.text.overline.height),
			layoutOrder = 1,
		})
		P.text(head, {
			name = "PickerTitle",
			text = opts.onPick and "Choose a provider" or "Add an inference provider",
			role = "display",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		P.text(head, {
			name = "PickerDescription",
			text = "Choose a hosted API or a local server. You'll review the connection before saving.",
			role = "small",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 3,
		})

		local tabsRow = P.row(root, {
			name = "PickerTabs",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 2,
		})
		local countLabel
		local search
		local gallery
		local cards = {}
		local render
		local resetSearch
		local silent = false

		C.segmented(tabsRow, {
			name = "ProviderTier",
			options = (function()
				local out = {}
				for _, entry in ipairs(catalog.tiers) do
					out[#out + 1] = { value = entry.id, label = entry.id == "free" and "Free & included" or entry.label }
				end
				return out
			end)(),
			value = tier,
			layoutOrder = 1,
			onChange = function(value)
				tier = value
				resetSearch()
			end,
		})

		search = P.field(root, {
			name = "ProviderSearch",
			placeholder = "Search providers or models",
			-- Room for the glyph at the left and the clear control at the right; both
			-- are drawn into the field's own shell, so the text has to start past them.
			padX = theme.size.icon + theme.space.md + theme.space.xs,
			layoutOrder = 3,
			onChange = function(text)
				query = tostring(text or "")
				-- A programmatic reset (tab switch, clear control) already renders; the
				-- change event it fires must not schedule a second pass that rebuilds the
				-- same cards and resets the scroll twice.
				if silent then return end
				if pendingSearch then pcall(task.cancel, pendingSearch); pendingSearch = nil end
				-- One render per keystroke would rebuild every card while someone is
				-- still typing. A short delay coalesces a word into one pass.
				pendingSearch = clock.delay(0.12, function()
					pendingSearch = nil
					render()
				end)
			end,
			onSubmit = function()
				if pendingSearch then pcall(task.cancel, pendingSearch); pendingSearch = nil end
				render()
			end,
		})
		local searchIcon = P.frame(search.shell, {
			name = "SearchGlyph",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			anchor = Vector2.new(0, 0.5),
			position = UDim2.new(0, theme.space.sm, 0.5, 0),
		})
		icons.draw("search", searchIcon, theme.size.icon, theme.color.textTertiary)
		local clearSize = math.max(theme.size.controlSmall, responsive.minTarget())
		local searchPadding = search.instance:FindFirstChildOfClass("UIPadding")
		if searchPadding then searchPadding.PaddingRight = UDim.new(0, clearSize + theme.space.xs) end
		local clearSearch = P.iconButton(search.shell, {
			name = "ClearProviderSearch",
			icon = "close",
			diameter = clearSize,
			anchor = Vector2.new(1, 0.5),
			position = UDim2.new(1, -theme.space.xxs, 0.5, 0),
			visible = false,
			onClick = function()
				resetSearch()
				search.focus()
			end,
		})

		resetSearch = function()
			if pendingSearch then pcall(task.cancel, pendingSearch); pendingSearch = nil end
			query = ""
			if search then
				silent = true
				search.set("")
				silent = false
			end
			render()
		end

		local galleryHolder = P.frame(root, {
			name = "ProviderGalleryHolder",
			size = UDim2.new(1, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 4,
		})
		gallery = P.scroll(galleryHolder, {
			name = "ProviderGallery",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.md,
			-- Keep card outlines clear of every scroll edge, with extra room below
			-- the final row to clear the fade and footer.
			padding = { x = theme.space.sm, top = theme.space.sm, bottom = theme.space.xl },
			fade = true,
			fadeColor = theme.color.surface,
		})
		gallery.layout.FillDirection = Enum.FillDirection.Horizontal
		gallery.layout.Wraps = true
		gallery.layout.ItemLineAlignment = Enum.ItemLineAlignment.Stretch

		local footer = P.row(root, {
			name = "PickerFooter",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = 5,
		})
		-- The result count lives here rather than beside the tabs: a segmented control
		-- is sized by its labels and capped, so a sibling that wants the rest of the row
		-- competes with it for width on a phone. Roomy layouts pin the footer;
		-- short layouts scroll it after the cards with the rest of the original body.
		countLabel = P.text(footer, {
			name = "ProviderCount",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			truncate = true,
			size = UDim2.new(0, 0, 0, theme.text.caption.height),
			flex = "Fill",
			layoutOrder = 1,
		})
		P.button(footer, {
			name = "PickerClose",
			text = "Close",
			variant = "ghost",
			size = "sm",
			layoutOrder = 3,
			onClick = function() dialog.close() end,
		})
		local fittingPicker, compactPicker = false, false
		local galleryFlex = galleryHolder:FindFirstChildOfClass("UIFlexItem")
		local function fitPicker()
			if dialog.closed or fittingPicker then return end
			local height = dialog.card.AbsoluteSize.Y
			if height <= 0 then return end
			fittingPicker = true
			local width = gallery.viewportSize().X -- excludes the gallery insets and scrollbar
			local minimumCard = math.max(theme.size.modalMin, theme.text.small.size * 20)
			local columns = not responsive.isMobile() and width >= minimumCard * 2 + theme.space.md and 2 or 1
			galleryHolder:SetAttribute("Columns", columns)
			for _, card in ipairs(cards) do
				card.instance.Size = UDim2.new(1 / columns, -theme.space.md * (columns - 1) / columns, 0, 0)
			end
			local chrome = math.max(head.AbsoluteSize.Y, theme.text.overline.height + theme.text.title.height + theme.text.small.height * 2 + theme.space.hair * 2)
				+ math.max(tabsRow.AbsoluteSize.Y, theme.size.tab) + math.max(search.shell.AbsoluteSize.Y, theme.size.control)
				+ math.max(footer.AbsoluteSize.Y, theme.size.control) + theme.space.lg + theme.space.md * 5
			local compact = height < chrome + theme.size.control * 3
			-- In short/keyboard space, the original search, tabs, cards and footer
			-- share one scrolling body. No focused field is replaced or hidden.
			viewport.instance.ScrollingEnabled = compact
			viewport.instance.ScrollBarThickness = compact and theme.size.scrollbar or 0
			gallery.instance.ScrollingEnabled = not compact
			galleryFlex.FlexMode = compact and Enum.UIFlexMode.None or Enum.UIFlexMode.Fill
			root.AutomaticSize = compact and Enum.AutomaticSize.Y or Enum.AutomaticSize.None
			root.Size = compact and UDim2.new(1, 0, 0, 0) or UDim2.new(1, 0, 0, height)
			galleryHolder.Size = compact and UDim2.new(1, 0, 0, math.max(theme.size.control,
				gallery.layout.AbsoluteContentSize.Y + theme.space.sm + theme.space.xl)) or UDim2.new(1, 0, 0, 0)
			if compact ~= compactPicker then
				viewport.instance.CanvasPosition = Vector2.new(0, 0)
				gallery.instance.CanvasPosition = Vector2.new(0, 0)
			end
			compactPicker, fittingPicker = compact, false
		end
		dialog.card:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitPicker)
		gallery.instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitPicker)
		for _, instance in ipairs({ head, tabsRow, search.shell, footer }) do
			instance:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitPicker)
		end
		gallery.layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitPicker)
		local unsubscribePickerLayout = responsive.changed:connect(fitPicker)
		fitPicker()

		local function choose(preset)
			if chosen or closed or not preset then return end
			chosen = true
			if pendingSearch then pcall(task.cancel, pendingSearch); pendingSearch = nil end
			dialog.close()
			if opts.onPick then
				opts.onPick(preset)
				return
			end
			M.editor(registry.blank(preset.id), opts.onSaved)
		end
		P.button(footer, {
			name = "CustomProviderShortcut", text = "Custom endpoint", variant = "secondary", size = "sm", layoutOrder = 2,
			onClick = function() choose(catalog.get("custom")) end,
		})

		local function buildCard(parent, preset, index)
			local included = preset.free == true
			local actionHeight = theme.text.label.height + theme.space.xs * 2
			local card = P.rowButton(parent, {
				name = "Choice_" .. tostring(preset.id),
				auto = "Y",
				vertical = true,
				gap = theme.space.sm,
				padding = { x = theme.space.md, top = theme.space.md, bottom = theme.space.md + theme.space.sm + actionHeight },
				radius = theme.radius.lg,
				bg = theme.color.surfaceRaised,
				bgHover = theme.color.surfaceHover,
				stroke = true,
				strokeColor = included and P.freeModelOutline(theme.color.surfaceRaised) or theme.color.borderSubtle,
				strokeWidth = theme.stroke.hair,
				layoutOrder = index,
				onClick = function() choose(preset) end,
			})
			cards[#cards + 1] = card
			local cardHead = P.row(card.row, {
				name = "ChoiceHead",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = 1,
			})
			local textColumn = P.column(cardHead, {
				name = "ChoiceText",
				size = UDim2.new(0, 0, 0, 0),
				auto = "Y",
				flex = "Fill",
				gap = theme.space.hair,
				layoutOrder = 1,
			})
			P.text(textColumn, {
				name = "ChoiceName",
				text = tostring(preset.label),
				role = "heading",
				color = theme.color.text,
				wrap = true,
				auto = "Y",
				layoutOrder = 1,
			})
			-- Keep the introduction brief, but never trim a highlighted access
			-- requirement. Cost and eligibility stay visible before choosing a route.
			local summary = tostring(preset.description or "")
			local stop = summary:find(". ", 1, true)
			if stop then summary = summary:sub(1, stop) end
			local requirement = tostring(preset.noteHighlight or "")
			if not included and requirement ~= "" and not summary:find(requirement, 1, true) then
				if tostring(preset.description):find(requirement, 1, true) then
					summary = preset.description
				else
					summary = summary .. "\n" .. requirement .. "."
				end
			end
			local description, rich = highlighted(summary, preset.noteHighlight)
			P.text(card.row, {
				name = "ChoiceDescription",
				text = description,
				rich = rich,
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
			local badgeText, tone = catalog.badge(preset)
			local _, badgeLabel = P.badge(cardHead, { text = badgeText, tone = tone, layoutOrder = 2 })
			badgeLabel.Name = "ChoiceBadge"

			P.text(card.row, {
				name = "ChoiceCost",
				text = tostring(preset.cost or ""),
				role = "caption",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				size = UDim2.new(1, 0, 0, 0),
				layoutOrder = 3,
			})
			-- The intrinsic content reserves this space; the action follows the outer
			-- card's bottom when a grid line stretches to fit its taller neighbour.
			local footerRow = P.row(card.instance, {
				name = "ChoiceActionRow", size = UDim2.new(1, -theme.space.md * 2, 0, actionHeight),
				anchor = Vector2.new(0, 1), position = UDim2.new(0, theme.space.md, 1, -theme.space.md), alignX = "Right",
			})
			local action = P.row(footerRow, {
				name = "ChoiceOpen", size = UDim2.fromOffset(0, actionHeight), auto = "X", padding = { x = theme.space.sm, y = theme.space.xs },
				bg = theme.color.surfaceActive, radius = theme.radius.sm,
			})
			P.text(action, { name = "ChoiceAction", text = "Set up", role = "label", color = theme.color.text, auto = "X" })
			return card
		end

		local function emptyGallery(message)
			local column = P.column(gallery.instance, {
				name = "NoProviderMatch",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				padding = { x = theme.space.md, y = theme.space.xl },
				layoutOrder = 1,
			})
			P.text(column, {
				name = "NoProviderMatchTitle",
				text = message,
				role = "bodyStrong",
				color = theme.color.text,
				wrap = true,
				auto = "Y",
			})
			P.text(column, {
				text = "Try a company, a model family, or a tier such as free or local.",
				role = "small",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			P.button(column, {
				name = "ClearProviderSearchEmpty",
				text = "Clear search",
				variant = "secondary",
				size = "sm",
				onClick = function() resetSearch() end,
			})
		end

		render = function()
			if closed or dialog.closed then return end
			local searching = util.trim(query) ~= ""
			local list
			if searching then
				list = catalog.search(query) or {}
			else
				list = catalog.byTier(tier)
			end
			clearSearch.instance.Visible = searching
			countLabel.Text = countText(#list, tier, searching)
			cards = {}
			gallery.clear()
			viewport.instance.CanvasPosition = Vector2.new(0, 0)
			if #list == 0 then
				local caption = "No provider matches that search."
				if not searching then
					for _, entry in ipairs(catalog.tiers) do
						if entry.id == tier then caption = entry.empty end
					end
				end
				emptyGallery(caption)
				return
			end
			for index, preset in ipairs(list) do
				buildCard(gallery.instance, preset, index)
			end
			-- The escape hatch belongs to every tier. It is also the one card that has
			-- to survive a search for "custom", which is why it is only appended when
			-- the query is empty: a search result set is whatever matched.
			if not searching then
				local custom = catalog.get("custom")
				if custom then buildCard(gallery.instance, custom, #list + 1) end
			end
			gallery.instance.CanvasPosition = Vector2.new(0, 0)
			fitPicker()
		end

		dialog.scrim.Destroying:Connect(function()
			closed = true
			unsubscribePickerLayout()
			if pendingSearch then pcall(task.cancel, pendingSearch); pendingSearch = nil end
		end)

		render()
	end

	-- The connection modal: preset, name, URL, protocol, auth, key and model.
	-- Everything else a record carries -- its models, its behaviour switches, its extra
	-- headers -- is edited in the detail pane, which is a surface that does not have to
	-- be dismissed to see the rest of the screen. This modal exists for the one moment
	-- when none of that is reachable yet: there is no record to select.
	function M.editor(record, onSaved)
		if config.vaultStatus().locked then return env.require("ui/credentialvault").open("unlock") end
		keyData.ensureIds(record)
		local editing = util.deepCopy(record)
		local adding = util.trim(editing.id) == ""
		local retainDraft = adding
		local keyManager, unsubscribeVault
		local modal = overlay.modal({
			title = adding and "Connect a provider" or "Edit connection",
			description = adding and "Add access, choose a model, and save when you're ready."
				or "Update this provider's connection and model.",
			width = theme.size.providerPicker,
			height = math.ceil(theme.size.providerPickerTall / (responsive.isMobile() and theme.metricScale or 1)),
			-- Six labelled rows, two segmented pickers and a footer do not fit on a phone,
			-- and an unbounded modal is centred -- so what did not fit went off the top and
			-- the bottom at once, taking the title and the Save button with it. Bounded and
			-- scrolled, the header and the footer stay put and the form moves.
			scroll = true,
			-- Scrim, close button and Escape preserve every editable connection
			-- field. Saving and Start over explicitly release the retained draft.
			onClose = function()
				if unsubscribeVault then unsubscribeVault(); unsubscribeVault = nil end
				if keyManager and not keyManager.closed then keyManager.close() end
				if retainDraft and util.trim(editing.id) == "" then
					addDraft = draftDirty(editing) and util.deepCopy(editing) or nil
				end
			end,
		})
		if not modal then return end
		modal.card.BackgroundColor3 = theme.color.surface
		unsubscribeVault = config.changed:connect(function(path)
			if (path == nil or path == "security" or path == "security.vault") and config.vaultStatus().locked then
				retainDraft, addDraft = false, nil
				modal.close()
				for _, child in ipairs(modal.card:GetDescendants()) do
					if child:IsA("TextBox") then child.Text = "" end
				end
				for name in pairs(editing) do editing[name] = nil end
			end
		end)

		local form = P.column(modal.content, {
			name = "Form",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
			layoutOrder = 1,
		})
		if editing.credentialsOmitted == true then
			R.paragraph(form,
				"Provider credentials were omitted from saved settings. Restore your API key and any required custom headers, query parameters, body fields or URL credentials. Saving this connection confirms you reviewed those fields and enables requests.",
				{ name = "RestoreProviderCredentials", color = theme.color.warn, role = "small", layoutOrder = 0 })
		end

		-- What this vendor is, in the same words the gallery used to describe it. The
		-- editor is where a key gets pasted, and pasting one into a screen that no
		-- longer says which service it belongs to is how a key ends up on the wrong
		-- endpoint.
		local introHolder, introBadge, introBadgeLabel, introText
		do
			introHolder = P.card(form, {
				name = "PresetIntro",
				gap = theme.space.sm,
				padding = theme.space.md,
				layoutOrder = 1,
			})
			local badgeText, tone = catalog.badge(catalog.get(editing.preset) or {})
			introBadge, introBadgeLabel = P.badge(introHolder, { text = badgeText, tone = tone, layoutOrder = 1 })
			introText = P.text(introHolder, {
				name = "PresetDescription",
				text = "",
				role = "small",
				color = theme.color.textSecondary,
				wrap = true,
				auto = "Y",
				layoutOrder = 3,
			})
		end
		local connectionSection = R.section(form, {
			name = "ConnectionSetup", title = "Connection details", description = "Name and endpoint. Preset defaults stay editable.", layoutOrder = 30,
		})
		local accessSection = R.section(form, {
			name = "AccessSetup", title = "Access", layoutOrder = 10,
		})
		local modelSection = R.section(form, {
			name = "ModelSetup", title = "Model", layoutOrder = 20,
		})
		local function details(name, title, description, opened, order)
			local group = P.column(form, {
				name = name .. "Group", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm, layoutOrder = order,
			})
			local body, label
			local toggle = P.rowButton(group, {
				name = name .. "Toggle", auto = "Y", vertical = true, padding = { x = theme.space.sm, y = theme.space.sm },
				gap = theme.space.xxs, layoutOrder = 1,
				onClick = function(handle)
					opened = not opened
					body.Visible = opened
					handle.instance:SetAttribute("Expanded", opened)
					label.Text = opened and ("Hide " .. title:lower()) or title
				end,
			})
			label = P.text(toggle.row, { name = name .. "Label", text = opened and ("Hide " .. title:lower()) or title,
				role = "label", color = theme.color.textSecondary, wrap = true, auto = "Y", layoutOrder = 1 })
			P.text(toggle.row, { text = description, role = "caption", color = theme.color.textTertiary,
				wrap = true, auto = "Y", layoutOrder = 2 })
			toggle.instance:SetAttribute("Expanded", opened)
			body = P.card(group, { name = name, gap = theme.space.md, padding = theme.space.md, layoutOrder = 2 })
			body.Visible = opened
			return body
		end
		local guideBody = details("ProviderGuide", "Setup guide", "Key links and provider requirements", true, 40)
		local accessNotice = R.paragraph(accessSection, "", { name = "AccessSummary", color = theme.color.textSecondary, layoutOrder = 1 })

		local problemLabel
		local presetButton, urlField, nameField
		local protocolControl, authControl, keyHintLabel
		local docsRow, docsNoteRow, presetNoteRow
		local proxyNote, communityRow, keyLabel, setKeyButton
		local urlColumn, keyUsageLabel
		local function refreshConnectionInfo()
			local custom = editing.preset == "custom"
			connectionSection.Parent.LayoutOrder = custom and 10 or 30
			accessSection.Parent.LayoutOrder = custom and 20 or 10
			modelSection.Parent.LayoutOrder = custom and 30 or 20
			if proxyNote then
				local target = registry.proxyTarget(editing)
				local usingProxy = registry.proxyProvider(editing)
				proxyNote.Visible = target ~= nil or usingProxy ~= nil
				proxyNote.Text = usingProxy and ("Using the Project UAI proxy: " .. env.require("net/url").display(editing.baseUrl)
					.. ". Requests and API keys pass through puai-proxy.davidzk.tech. Shared limit: 90,000 requests per day. You can edit the Base URL at any time.")
					or target and ("If this endpoint rejects UAI as an unauthorized client, UAI retries through " .. env.require("net/url").display(target)
					.. " and saves that Base URL for this provider. Requests and API keys pass through puai-proxy.davidzk.tech. Shared limit: 90,000 requests per day. The URL stays editable.") or ""
			end
			local included = communityKey.isApplied(editing)
			if communityRow then communityRow.Visible = communityKey.eligible(editing) and not included end
			local preset = catalog.get(editing.preset)
			local requirement = preset and not preset.free and preset.noteHighlight or ""
			if requirement ~= "" and tostring(preset.description):find(requirement, 1, true) then requirement = "" end
			accessNotice.Text = included and "Included access is ready. Shared capacity and response times vary." or requirement
			accessNotice.Visible = accessNotice.Text ~= ""
		end
		-- Any connection edit invalidates fetched choices and in-flight discovery,
		-- including changing away and back before the old response arrives.
		local forgetFetchedModels
		local modelRevision = 0
		local testButton, testRun
		local function invalidateTest()
			testRun = nil
			if testButton and testButton.instance.Parent then
				testButton.setText("Test connection")
				testButton.setEnabled(true)
			end
		end

		local function showProblems()
			refreshConnectionInfo()
			local ok, problems = registry.validate(editing)
			if keyLabel then
				local shown, tone = maskedKey(editing)
				keyLabel.Text, keyLabel.TextColor3 = shown, tone and theme.color.warn or theme.color.textSecondary
			end
			if setKeyButton then
				setKeyButton.instance.Visible = not registry.isCline(editing)
			end
			if keyUsageLabel then
				keyUsageLabel.Text = keyUsage(editing)
				keyUsageLabel.Visible = not registry.isCline(editing)
			end
			if problemLabel then
				problemLabel.Text = ok and "" or (problems[1]:gsub("^%l", string.upper) .. ".")
				problemLabel.Visible = not ok
			end
			return ok
		end

		-- Stable field order is independent of a preset's optional help and links.
		local rowOrder = 0
		local function row(label, hint, build)
			rowOrder = rowOrder + 1
			local parent = label == "Preset" and introHolder
				or (label == "Name" or label == "Base URL") and connectionSection
				or label == "API keys" and accessSection
				or label == "Model" and modelSection or connectionSection
			local column = P.column(parent, {
				name = label:gsub("%s", "") .. "FieldGroup",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = label == "Preset" and 2 or rowOrder * 10,
			})
			if label ~= "Preset" and label ~= "Model" then
				P.text(column, { text = tostring(label), role = "label", color = theme.color.text, layoutOrder = 1 })
			end
			local handle = build(column)
			if type(handle) == "table" then
				local instance = handle.shell or handle.instance
				if instance then instance.LayoutOrder = 2 end
			end
			if hint then
				local note = P.text(column, {
					text = hint,
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					layoutOrder = 9,
				})
				note.Size = UDim2.new(1, 0, 0, 0)
			end
			return handle
		end

		-- Applied in place, not by rebuilding the record.
		--
		-- Choosing a preset used to call registry.blank, replace `editing` wholesale,
		-- close the modal and re-open it -- so a name typed, a key pasted and a URL
		-- corrected were all discarded the moment someone realised they had picked the
		-- wrong vendor. Only the fields the preset actually describes move; the label is
		-- carried over when it still matches the old preset's own name, which is the case
		-- where it was never edited.
		--
		-- Extended help stays in the optional guide. Signup requirements in the
		-- preset summary and the active proxy notice remain in the main form.
		local function refreshDocs()
			refreshConnectionInfo()
			if introHolder then
				local current = catalog.get(editing.preset)
				if current then
					local badgeText, tone = catalog.badge(current)
					introBadgeLabel.Text = badgeText
					introBadgeLabel.TextColor3 = theme.toneColor(tone)
					introBadge.BackgroundColor3 = theme.toneSurface(tone)
					introText.Text = tostring(current.description or "")
					introBadge.Visible = true
				else
					introBadge.Visible = false
					introText.Text = "A custom provider connection."
				end
			end
			if docsRow then docsRow:Destroy() docsRow = nil end
			if docsNoteRow then docsNoteRow:Destroy() docsNoteRow = nil end
			if presetNoteRow then presetNoteRow:Destroy() presetNoteRow = nil end
			local presetRecord = catalog.get(editing.preset)
			if not presetRecord then return end
			if presetRecord.docs then
				-- The full URL, selectable and copyable. Roblox cannot open a browser from
				-- a client GUI, so "get a key here" has to be text a person can select or
				-- one press away from the clipboard -- a "click here" label with the
				-- destination hidden behind it is neither.
				docsRow = P.row(guideBody, {
					name = "KeyLink",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					layoutOrder = 11,
				})
				local linkText = P.text(docsRow, {
					name = "KeyLinkUrl",
					text = tostring(presetRecord.docs),
					role = "small",
					color = theme.color.accent,
					wrap = true,
					auto = "Y",
					size = UDim2.new(0, 0, 0, 0),
					flex = "Fill",
					layoutOrder = 1,
				})
				if caps.clipboard then
					P.iconButton(docsRow, {
						name = "CopyKeyLink",
						icon = "copy",
						diameter = theme.size.controlSmall,
						layoutOrder = 2,
						onClick = function()
							local ok = env.require("runtime/clipboard").write(tostring(presetRecord.docs))
							overlay.toast(ok and "Link copied" or "Could not reach the clipboard",
								ok and "good" or "warn", 2)
						end,
					})
				end
				docsNoteRow = R.paragraph(guideBody,
					presetRecord.free and "Save this library choice to enable community access. Discord has availability notices and help."
						or presetRecord.authStyle == "none"
						and "Server setup and API documentation are at the address above."
						or "Keys for this provider are issued at the address above.",
					{ layoutOrder = 12 })
			end
			if presetRecord.note then
				presetNoteRow = R.paragraph(guideBody, presetRecord.note, { layoutOrder = 13 })
			end
		end

		local function applyPreset(id)
			local preset = catalog.get(id)
			if not preset then return end
			local ok, why = env.require("provider/preset").apply(editing, id)
			if not ok then overlay.toast(why, "warn"); return false end
			if keyLabel then
				local shown, tone = maskedKey(editing)
				keyLabel.Text, keyLabel.TextColor3 = shown, tone and theme.color.warn or theme.color.textSecondary
			end
			if presetButton then presetButton.setText(preset.label) end
			if urlField then urlField.set(editing.baseUrl) end
			-- The name follows when it was never hand-edited -- the same rule the label
			-- above applies -- and every control derived from the preset repaints, because a
			-- preset changes the protocol, the auth header, the key hint and the docs link,
			-- and a form where half the rows still describe the previous vendor reads as
			-- broken rather than as partially updated.
			if nameField then nameField.set(editing.label) end
			if protocolControl then protocolControl.set(chat.styleOf(editing)) end
			if authControl then authControl.set(editing.authStyle) end
			if keyHintLabel then
				keyHintLabel.Text = preset.keyHint
					and ("Key hint: " .. tostring(preset.keyHint))
					or ""
				keyHintLabel.Visible = keyHintLabel.Text ~= ""
			end
			refreshDocs()
			if forgetFetchedModels then forgetFetchedModels() end
			showProblems()
			return true
		end

		row("Preset", nil, function(column)
			presetButton = P.button(column, {
				name = "Preset",
				text = (catalog.get(editing.preset) or {}).label or "Custom endpoint",
				variant = "secondary",
				fill = true,
				align = "Left",
				trailing = "chevron",
				trailingColor = theme.color.textTertiary,
				onClick = function()
					-- The same gallery the add flow uses. A menu of every preset was
					-- workable at nine vendors and is unusable at seventy: it cannot be
					-- searched, it cannot say what a vendor costs, and it scrolls in a
					-- 320-pixel column.
					M.picker({
						tier = catalog.tierOf(catalog.get(editing.preset)),
						onPick = function(preset) applyPreset(preset.id) end,
					})
				end,
			})
			return presetButton
		end)

		row("Name", nil, function(column)
			nameField = P.field(column, {
				name = "ProviderName",
				text = editing.label,
				placeholder = "My provider",
				onChange = function(text) editing.label = text end,
				onBlur = showProblems,
			})
			return nameField
		end)

		local normalisedNote
		row("Base URL", nil, function(column)
			urlColumn = column
			urlField = P.field(column, {
				name = "BaseUrl",
				text = editing.baseUrl,
				placeholder = "https://api.example.com/v1",
				onChange = function(text)
					local changed = editing.baseUrl ~= text
					editing.baseUrl = text
					refreshConnectionInfo()
					if changed and forgetFetchedModels then forgetFetchedModels() end
					-- What will actually be stored, before it is stored.
					--
					-- registry.save normalises the URL *and then* validates, so a rejected
					-- save had already rewritten the value while the field still showed the
					-- old text. Saying what the rule does to the input is better than
					-- describing the rule.
					local normalised = registry.normaliseBaseUrl(text)
					if normalisedNote then
						normalisedNote.Text = (normalised ~= "" and normalised ~= util.trim(text))
							and ("Saved as " .. normalised) or ""
						normalisedNote.Visible = normalisedNote.Text ~= ""
					end
				end,
				onBlur = showProblems,
			})
			normalisedNote = P.text(column, {
				text = "",
				visible = false,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 3,
			})
			normalisedNote.Size = UDim2.new(1, 0, 0, 0)
			return urlField
		end)
		proxyNote = R.paragraph(urlColumn, "", { name = "ProxyFallbackNotice", layoutOrder = 10 })

		row("Protocol", "Choose the API exposed by the server: Chat completions, Anthropic Messages, or Google's native Gemini API.",
			function(column)
				protocolControl = C.segmented(column, {
					name = "Protocol",
					options = chat.STYLES,
					value = chat.styleOf(editing),
					onChange = function(value)
						if editing.api == value then return end
						editing.api = value
						if forgetFetchedModels then forgetFetchedModels() end
						showProblems()
					end,
				})
				return protocolControl
			end)

		row("Auth header", nil, function(column)
			authControl = P.button(column, {
				name = "AuthStyle",
				text = labelOf(AUTH_OPTIONS, editing.authStyle), variant = "secondary", fill = true, align = "Left", trailing = "chevron",
				onClick = function(handle)
					local options = {}
					for _, option in ipairs(AUTH_OPTIONS) do
						options[#options + 1] = { value = option.value, label = option.label, selected = editing.authStyle == option.value }
					end
					overlay.menu({ target = handle.instance, options = options, onSelect = function(value)
						local changed = editing.authStyle ~= value
						editing.authStyle = value
						handle.setText(labelOf(AUTH_OPTIONS, value))
						if changed and forgetFetchedModels then forgetFetchedModels() end
						showProblems()
					end })
				end,
			})
			authControl.set = function(value) authControl.setText(labelOf(AUTH_OPTIONS, value)) end
			return authControl
		end)

		-- Keep connection setup compact. The key manager owns its own draft and
		-- applies names, credentials and routing together, without saving the provider.
		row("API keys", nil, function(column)
			local shown, tone = maskedKey(editing)
			keyLabel = P.text(column, {
				name = "KeyState",
				text = shown,
				role = "monoSmall",
				color = tone and theme.color.warn or theme.color.textSecondary,
				wrap = true, auto = "Y",
				layoutOrder = 2,
			})
			keyUsageLabel = R.paragraph(column, keyUsage(editing), { name = "KeyUsage", layoutOrder = 3 })
			setKeyButton = P.button(column, {
				name = "ManageKeys",
				text = "Manage API keys",
				variant = "secondary",
				size = "sm",
				layoutOrder = 4,
				onClick = function()
					if modal.closed or registry.isCline(editing) or (keyManager and not keyManager.closed) then return end
					keyManager = env.require("ui/providerkeys").open({
						record = editing,
						onClose = function() keyManager = nil end,
						onApply = function(updated)
							if modal.closed or registry.isCline(editing) then return false end
							if applyKeys(editing, updated) and forgetFetchedModels then forgetFetchedModels() end
							if editing.preset == "projectuai-free" and not communityKey.isApplied(editing)
								and util.trim(editing.apiKey) ~= "" then
								if not applyPreset("hcnsec") then return false end
								overlay.toast("Personal keys use the separate HCNSEC provider. This draft now uses HCNSEC.", "info")
							end
							showProblems()
							return true
						end,
					})
				end,
			})
			communityRow = P.column(column, { name = "CommunityKey", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs, layoutOrder = 6 })
			R.paragraph(communityRow, "Restore this provider's community access. Personal keys belong to the separate HCNSEC provider.", { layoutOrder = 1 })
			P.button(communityRow, { name = "UseCommunityKey", text = "Use included free access", variant = "secondary", fill = true, layoutOrder = 2,
				onClick = function()
					local ok, why = communityKey.apply(editing)
					if not ok then overlay.toast(why, "warn"); return end
					if forgetFetchedModels then forgetFetchedModels() end
					local shown = maskedKey(editing)
					keyLabel.Text, keyLabel.TextColor3 = shown, theme.color.textSecondary
					showProblems()
					overlay.toast("Community key added to this draft. Choose a model and save to use it.", "good")
				end })
			return keyLabel
		end)

		-- What a key for this preset looks like, when the preset knows. It is a hint,
		-- not a field: the shape of an OpenAI key is not the shape of a Gemini key, and
		-- the person pasting one wants to know they are pasting the right kind of thing
		-- before the request fails on the far end. The docs link and the preset note sit
		-- together in the optional guide, and update in place with the preset.
		keyHintLabel = P.text(guideBody, {
			name = "KeyHint",
			text = (catalog.get(editing.preset) or {}).keyHint
				and ("Key hint: " .. tostring((catalog.get(editing.preset) or {}).keyHint)) or "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 10,
		})
		keyHintLabel.Size = UDim2.new(1, 0, 0, 0)
		keyHintLabel.Visible = keyHintLabel.Text ~= ""
		R.paragraph(guideBody, "Keys are masked here. Settings / Privacy lets you choose password encryption or unprotected storage. Requests send them to the configured provider, gateway or relay.", { layoutOrder = 14 })

		-- Model.
		--
		-- The one field a record cannot be saved without, and the editor had none. The
		-- picker lives on the detail pane, which you reach by selecting a provider that has
		-- already been saved -- and `registry.validate` refuses to save a record with no
		-- model. So adding a provider ended at "fetch the model list or add a model id"
		-- with nothing on screen that could do either, and Test asked the endpoint for a
		-- completion with no model named, which comes back as the provider's own wording
		-- for that and reads as a broken connection.
		local modelButton, modelNote, fetchButton
		local fetched = {}

		-- What the picker offers: the ids already on the record, plus whatever this
		-- editor's own fetch turned up. Discovery has a connection-scoped cache, but
		-- choices here belong to this editor and expire as its connection is edited.
		local function knownModels()
			local out, seen = {}, {}
			for _, id in ipairs(editing.models or {}) do
				if util.trim(id) ~= "" and not seen[id] then
					seen[id] = true
					out[#out + 1] = id
				end
			end
			for _, id in ipairs(fetched) do
				if not seen[id] then
					seen[id] = true
					out[#out + 1] = id
				end
			end
			return out
		end

		local DEFAULT_MODEL_NOTE = "Model IDs come from your provider. Fetch its catalog or add an ID manually."

		local function setModelNote(text, bad)
			if not modelNote then return end
			modelNote.Text = tostring(text)
			modelNote.TextColor3 = bad and theme.color.warn or theme.color.textTertiary
		end

		local paintedModel
		local function paintModel()
			local current = util.trim(editing.model)
			if current ~= paintedModel then invalidateTest(); paintedModel = current end
			if modelButton then
				modelButton.setText(current ~= "" and current or "Choose a model")
			end
		end

		local openModelMenu
		local function adoptProxy(candidate, revision)
			if revision ~= modelRevision or not registry.proxyProvider(candidate) or candidate.baseUrl == registry.normaliseBaseUrl(editing.baseUrl) then return end
			editing.baseUrl = candidate.baseUrl
			urlField.set(editing.baseUrl)
			if forgetFetchedModels then forgetFetchedModels() end
			refreshConnectionInfo()
		end

		-- Fetches against the record as it would be saved, not as it is typed: the URL is
		-- normalised the same way `save` normalises it, so what is asked for is the
		-- endpoint the provider will actually use.
		local function fetchModels(handle)
			local target = util.deepCopy(editing)
			target.baseUrl = registry.normaliseBaseUrl(target.baseUrl)
			if target.baseUrl == "" then
				setModelNote("Add the base URL first -- there is nothing to ask.", true)
				return
			end
			modelRevision = modelRevision + 1
			local revision = modelRevision
			invalidateTest()
			handle.setEnabled(false)
			if fetchButton then fetchButton.setEnabled(false) end
			setModelNote("Loading " .. modelSource(target) .. "...", false)
			task.spawn(function()
				local found, note = models.discover(target, { force = true,
					aborted = function() return modal.closed or revision ~= modelRevision end })
				if modal.closed or not handle.instance.Parent or revision ~= modelRevision then return end
				adoptProxy(target, revision)
				handle.setEnabled(true)
				if fetchButton then fetchButton.setEnabled(true) end
				fetched = found
				setModelNote(note, #found == 0)
				-- Straight back into the list. Picking one is the reason to fetch, and a
				-- notice that says "42 models" while the menu stays shut makes someone press
				-- the same control twice for one decision.
				if #found > 0 then openModelMenu(handle) end
			end)
		end

		local function typeModel()
			-- A manual entry supersedes a discovery still loading in this form.
			modelRevision = modelRevision + 1
			invalidateTest()
			if modelButton then modelButton.setEnabled(true) end
			if fetchButton then fetchButton.setEnabled(true) end
			overlay.prompt({
				title = "Model id",
				description = "Type it exactly as the provider expects it. It is saved with this "
					.. "provider and selected.",
				placeholder = "model id",
				confirmText = "Use it",
				onConfirm = function(text)
					-- Not persisted: the record is still being edited and may never be saved.
					local ok, result = models.add(editing, text, { persist = false, select = true })
					setModelNote(ok and ("Using " .. tostring(result)) or tostring(result), not ok)
					paintModel()
					showProblems()
				end,
			})
		end

		openModelMenu = function(handle)
			local revision = modelRevision
			local options = {}
			local own = {}
			for _, id in ipairs(editing.models or {}) do own[id] = true end
			for _, id in ipairs(knownModels()) do
				local badge = traits.badge(id, editing)
				local bits = {}
				if models.isFree(editing, id) then bits[#bits + 1] = "Free" end
				if badge then bits[#bits + 1] = badge end
				if not own[id] then bits[#bits + 1] = "from catalog" end
				options[#options + 1] = {
					label = id,
					value = "model:" .. id,
					detail = #bits > 0 and table.concat(bits, "  \194\183  ") or nil,
					selected = id == editing.model,
					free = models.isFree(editing, id),
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = {
				label = fetchLabel(editing),
				value = "fetch",
				detail = modelSource(editing),
				searchable = false,
				tone = "info",
			}
			options[#options + 1] = { label = "Type an id", value = "add", tone = "info", searchable = false }
			overlay.menu({
				target = handle.instance,
				width = theme.size.menuWide,
				options = options,
				searchable = true,
				searchPlaceholder = "Search model IDs...",
				emptyText = "No matching models. Refresh the catalog or type an exact ID.",
				onSelect = function(value)
					if revision ~= modelRevision then return end
					if value == "fetch" then
						fetchModels(handle)
					elseif value == "add" then
						typeModel()
					elseif util.startsWith(tostring(value), "model:") then
						local id = tostring(value):sub(7)
						models.add(editing, id, { persist = false, select = true })
						editing.model = id
						setModelNote(DEFAULT_MODEL_NOTE, false)
						paintModel()
						showProblems()
					end
				end,
			})
		end

		row("Model", nil, function(column)
			modelButton = P.button(column, {
				name = "ActiveModel",
				text = "Choose a model",
				variant = "secondary",
				fill = true,
				align = "Left",
				trailing = "chevron",
				onClick = openModelMenu,
			})
			modelNote = P.text(column, {
				name = "ModelNote",
				text = DEFAULT_MODEL_NOTE,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 4,
			})
			local actions = P.row(column, { name = "SetupModelActions", size = UDim2.new(1, 0, 0, 0), auto = "Y",
				gap = theme.space.xs, wrap = true, layoutOrder = 3 })
			fetchButton = P.button(actions, { name = "FetchSetupModels", text = "Fetch catalog", variant = "secondary", size = "sm", layoutOrder = 1,
				onClick = function() if modelButton.instance.Active then fetchModels(modelButton) end end })
			P.button(actions, { name = "TypeSetupModel", text = "Enter model ID", variant = "ghost", size = "sm", layoutOrder = 2,
				onClick = typeModel })
			modelNote.Size = UDim2.new(1, 0, 0, 0)
			paintModel()
			return modelButton
		end)

		forgetFetchedModels = function()
			modelRevision = modelRevision + 1
			invalidateTest()
			fetched = {}
			if modelButton then modelButton.setEnabled(true) end
			if fetchButton then fetchButton.setEnabled(true) end
			paintModel()
			setModelNote(DEFAULT_MODEL_NOTE, false)
		end

		refreshDocs()

		problemLabel = P.text(modal.content, {
			name = "Problem",
			text = "",
			role = "small",
			color = theme.color.danger,
			wrap = true,
			auto = "Y",
			visible = false,
			layoutOrder = 0,
		})
		problemLabel.Size = UDim2.new(1, 0, 0, 0)

		testButton = P.button(modal.footer, {
			name = "TestConnection",
			text = "Test connection",
			variant = "ghost",
			size = "sm",
			layoutOrder = 1,
			-- Through onClick, not a raw Activated connection: that is what P.button's own
			-- re-entry guard hangs off, and connecting to Activated directly meant a double
			-- tap fired two concurrent completions.
			onClick = function(handle)
				-- A completion needs a model named, so testing without one asks the endpoint
				-- a question it cannot answer -- and what comes back is that provider's own
				-- wording for "no model", which reads as a broken connection rather than as
				-- an empty field one row up.
				if editing.preset ~= "azure" and util.trim(editing.model) == "" then
					problemLabel.Text = "Choose a model first: fetch the list, or type the id."
					problemLabel.Visible = true
					modal.scroll.instance.CanvasPosition = Vector2.new(0, 0)
					return
				end
				handle.setEnabled(false)
				handle.setText("Testing")
				local revision = modelRevision
				local token = {}; testRun = token
				local candidate = registry.shareKeyRotation(editing, util.deepCopy(editing))
				candidate.baseUrl = registry.normaliseBaseUrl(candidate.baseUrl)
				local function aborted()
					return modal.closed or not handle.instance.Parent or testRun ~= token or revision ~= modelRevision
				end
				task.spawn(function()
					local result, err = chat.complete(candidate, {
						messages = { { role = "user", content = "Reply with the single word: ready" } },
						stream = registry.isOpencode(candidate) or false,
						maxTokens = 12,
						attempts = 1,
						aborted = aborted,
					})
					if aborted() then return end
					testRun = nil
					adoptProxy(candidate, revision)
					handle.setText("Test connection")
					handle.setEnabled(true)
					if result then
						overlay.toast(string.format("Reached %s in %s",
							candidate.label, util.formatDuration(result.ms)), "good")
					else
						problemLabel.Text = tostring(err)
						problemLabel.Visible = true
						modal.scroll.instance.CanvasPosition = Vector2.new(0, 0)
					end
				end)
			end,
		})

		if adding then
			P.button(modal.footer, {
				name = "StartOverProvider",
				text = "Start over",
				variant = "ghost",
				size = "sm",
				layoutOrder = 0,
				onClick = function()
					retainDraft = false
					addDraft = nil
					modal.close()
					M.add(onSaved)
				end,
			})
		end

		P.button(modal.footer, {
			name = "SaveProvider",
			text = adding and "Add provider" or "Save changes",
			variant = "primary",
			size = "sm",
			layoutOrder = 2,
			onClick = function()
				local current = not adding and registry.get(editing.id)
				if current and sameKeyConnection(current, editing) then
					-- Requests may advance the live cursor while a connection draft is
					-- open. A label-only edit must not restore its old copied cursor.
					editing.keyRotation = current.keyRotation
				end
				local ok, problems = registry.save(editing, { credentialsRestored = true })
				if not ok then
					-- Sentence-cased and one per line. It was table.concat(problems, ". "),
					-- which turned two lowercase fragments into "give the provider a name.
					-- base URL is required".
					local lines = {}
					for index, problem in ipairs(problems) do
						lines[index] = problem:gsub("^%l", string.upper) .. "."
					end
					problemLabel.Text = table.concat(lines, "\n")
					problemLabel.Visible = true
					modal.scroll.instance.CanvasPosition = Vector2.new(0, 0)
					return
				end
				if adding then addDraft = nil end
				retainDraft = false
				modal.close()
				overlay.toast("Saved " .. editing.label, "good", 2)
				if onSaved then onSaved(editing.id) end
			end,
		})

		showProblems()
		-- Nothing is wrong yet on a brand-new record; it is simply incomplete.
		if adding then problemLabel.Visible = false end
	end

	-- The entry point for adding: the gallery, then the editor.
	--
	-- A retained draft resumes directly. Someone who dismissed the editor mid-setup is
	-- not starting over, and showing them the gallery first would make them choose the
	-- vendor twice for the same unfinished provider.
	function M.add(onSaved)
		if addDraft then
			local draft = addDraft
			addDraft = nil
			M.editor(draft, onSaved)
			return
		end
		M.picker({ onSaved = onSaved })
	end

	local savedKeyManager
	function M.manageKeys(record, onSaved)
		if registry.isCline(record) then return nil end
		if savedKeyManager and not savedKeyManager.closed then return savedKeyManager end
		savedKeyManager = env.require("ui/providerkeys").open({
			record = record,
			applyHint = "Apply changes updates this provider's keys and request preferences using the storage preference shown above.",
			onClose = function() savedKeyManager = nil end,
			onApply = function(updated)
				local current = registry.get(record.id)
				if not current or registry.isCline(current) then
					overlay.toast("This provider is no longer available. Reopen its settings.", "warn")
					return false
				end
				local candidate = util.deepCopy(current)
				candidate.keyRotation, candidate.health = current.keyRotation, current.health
				local connectionChanged = applyKeys(candidate, updated)
				local ok, problems = registry.save(candidate)
				if not ok then
					overlay.toast(problems[1] or "Could not save API keys", "warn")
					return false
				end
				if connectionChanged then models.invalidate(candidate.id) end
				if candidate.credentialsOmitted == true then
					overlay.toast("Keys updated. Open Edit connection to review custom authentication, then save to enable requests.", "info", 5)
				end
				if onSaved then onSaved(candidate.id) end
				return true
			end,
		})
		return savedKeyManager
	end

	-- The empty panel's start card.
	--
	-- One card rather than a stack of five. The gallery is where the full list lives
	-- now, so this surface only has to answer "what do I do first": browse, go custom,
	-- or take one of the first recommendations. Each quick pick opens the editor already
	-- seeded, and included free access still needs one press.
	function M.startCard(parent, onSetup, nextOrder)
		local card = P.card(parent, {
			name = "StartCard",
			gap = theme.space.md,
			padding = theme.space.lg,
			layoutOrder = type(nextOrder) == "function" and nextOrder() or 1,
			strokeColor = theme.color.accentBorder,
		})

		local head = P.column(card, {
			name = "StartHead",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		P.text(head, {
			name = "StartOverline",
			text = "START HERE",
			role = "overline",
			color = theme.color.accent,
			size = UDim2.new(1, 0, 0, theme.text.overline.height),
			layoutOrder = 1,
		})
		P.text(head, {
			name = "StartTitle",
			text = "Add a provider",
			role = "display",
			color = theme.color.text,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		P.text(head, {
			name = "StartDescription",
			text = "Free routes need no card. Paid routes need a key or credit. Local servers run on your machine. Pick any of them and every field stays editable.",
			role = "small",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 3,
		})

		local actions = P.row(card, {
			name = "StartActions",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.sm,
			layoutOrder = 2,
		})
		P.button(actions, {
			name = "StartBrowse",
			text = "Browse providers",
			variant = "primary",
			size = "sm",
			layoutOrder = 1,
			onClick = function() M.picker({ onSaved = onSetup }) end,
		})
		P.button(actions, {
			name = "StartCustom",
			text = "Custom endpoint",
			variant = "secondary",
			size = "sm",
			layoutOrder = 2,
			onClick = function() M.editor(registry.blank("custom"), onSetup) end,
		})

		local picks = P.column(card, {
			name = "StartPicks",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 3,
		})
		for index, preset in ipairs(catalog.featured()) do
			local row = P.rowButton(picks, {
				name = "Start_" .. tostring(preset.id),
				height = theme.size.controlLarge,
				padding = { x = theme.space.sm },
				radius = theme.radius.md,
				layoutOrder = index,
				onClick = function()
					M.editor(registry.blank(preset.id), onSetup)
				end,
			})
			row.label(preset.label, 1, theme.color.text, "small")
			local badgeText, tone = catalog.badge(preset)
			P.badge(row.row, { text = badgeText, tone = tone, layoutOrder = 2 })
			row.icon("chevron", 3, theme.color.textTertiary, theme.size.icon)
		end
		return card
	end

	-- List and detail ---------------------------------------------------------

	function M.new(parent)
		local panel = {}
		local selected = nil
		local selectionRevision = 0

		-- Two columns where there is room for two, stacked where there is not. Same rule
		-- and same threshold as the settings dialog, which solved this first.
		local wide = parent.AbsoluteSize.X >= (theme.size.dialogNav * 3)

		local root, rootLayout = P.row(parent, { name = "ProvidersRoot", size = UDim2.fromScale(1, 1), gap = 0 })
		rootLayout.FillDirection = wide and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
		local railHeight = math.max(theme.size.controlLarge, responsive.minTarget(),
			theme.text.small.height + theme.space.xs * 2)

		local railHolder = P.frame(root, {
			name = "ProviderRail",
			size = wide and UDim2.new(0, theme.size.dialogNav, 1, 0)
				or UDim2.new(1, 0, 0, railHeight + theme.space.xs * 2 + theme.size.scrollbar),
			bg = theme.color.sidebar,
			layoutOrder = 1,
		})
		local rail = P.column(railHolder, {
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = theme.space.xs,
		})
		local railScrollHolder = P.frame(rail, {
			size = UDim2.new(1, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 1,
		})
		local railScroll = P.scroll(railScrollHolder, {
			name = "ProviderList",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.hair,
			horizontal = not wide,
			alignX = "Left",
		})
		railScroll.layout.VerticalAlignment = wide and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Center
		-- Under the list where there is a column to put it under, and at the end of the
		-- strip where there is not -- so there is exactly one of it either way.
		local addButton = P.button(rail, {
			name = "AddProvider",
			text = "Add a provider",
			icon = "plus",
			variant = "secondary",
			size = "sm",
			fill = true,
			layoutOrder = 2,
			onClick = function()
				M.add(function(id) panel.select(id) end)
			end,
		})
		addButton.instance.Visible = wide

		local divider = P.divider(root, {
			vertical = wide,
			color = theme.color.borderSubtle,
			layoutOrder = 2,
		})

		local detailHolder = P.frame(root, {
			name = "ProviderDetail",
			size = wide and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 0, 0),
			flex = "Fill",
			layoutOrder = 3,
		})
		local detail = P.scroll(detailHolder, {
			name = "DetailScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.lg,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.xl },
		})

		-- Rail -----------------------------------------------------------------

		local railRows = {}

		local function dotFor(record, isActive)
			if registry.cooling(record) then return theme.color.danger end
			if record.enabled == false then return theme.color.textDisabled end
			if isActive then return theme.color.accent end
			return theme.color.textTertiary
		end

		function panel.renderRail()
			local position = railScroll.instance.CanvasPosition
			railScroll.clear()
			railRows = {}
			local list = registry.list()
			local active = registry.active()
			for index, record in ipairs(list) do
				local isActive = active and active.id == record.id
				local row = P.rowButton(railScroll.instance, {
					name = "Provider_" .. tostring(record.id),
					size = (not wide) and UDim2.fromOffset(0, railHeight) or nil,
					auto = (not wide) and "X" or nil,
					height = railHeight,
					padding = { x = theme.space.sm },
					radius = theme.radius.md,
					selected = record.id == selected,
					layoutOrder = index,
					onClick = function() panel.select(record.id) end,
				})
				local dotSlot = P.frame(row.row, {
					name = "Health",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				local dot = P.statusDot(dotSlot, {
					diameter = theme.size.dot,
					color = dotFor(record, isActive),
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				local colour = record.id == selected and theme.color.text or theme.color.textSecondary
				if wide then
					row.label(record.label, 2, colour, "small")
				else
					-- Intrinsic tabs: no menu-width reserve and no Fill child in an
					-- auto-width row. Long names stop growing before consuming the strip.
					P.text(row.row, { name = "Label", text = record.label, role = "small",
						color = colour, auto = "X", truncate = true,
						maxSize = Vector2.new(theme.size.menuMin, math.huge), layoutOrder = 2 })
				end
				-- A badge, not text appended to the title. It used to be "  (active)"
				-- concatenated into a truncating label, so on a narrow rail the one fact
				-- that says which endpoint is in use was the first thing cut.
				if isActive then
					local badge = P.badge(row.row, { text = "Active", tone = "accent", layoutOrder = 3 })
					badge.LayoutOrder = 3
				end
				railRows[record.id] = { row = row, dot = dot }
			end
			if #list == 0 then
				local empty = P.text(railScroll.instance, {
					name = "NoProviders",
					text = "Nothing configured yet.",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = theme.space.sm, y = theme.space.xs },
					layoutOrder = 1,
				})
				empty.Size = wide and UDim2.new(1, 0, 0, 0) or UDim2.fromOffset(theme.size.menuMin, theme.text.caption.height)
			end
			if not wide then
				-- With the rail collapsed to a strip there is no room under it for the
				-- button, so it rides at the end of the strip instead.
				local add = P.button(railScroll.instance, {
					name = "AddProvider",
					text = "Add",
					icon = "plus",
					variant = "secondary",
					size = "sm",
					layoutOrder = #list + 1,
					onClick = function(handle)
						M.add(function(id) panel.select(id) end)
					end,
				})
				add.instance.LayoutOrder = #list + 1
			end
			railScroll.instance.CanvasPosition = position
		end

		-- AbsoluteSize may still be zero at construction, and desktop resizing does
		-- not change responsive.mode. Reflow the existing detail rather than replacing
		-- a form somebody is typing into.
		local function reflow()
			local width = root.AbsoluteSize.X
			if width <= 0 then return end
			local nextWide = width >= theme.size.dialogNav * 3
			local changed = nextWide ~= wide
			wide = nextWide
			rootLayout.FillDirection = wide and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
			rootLayout.VerticalAlignment = Enum.VerticalAlignment.Top
			railHolder.Size = wide and UDim2.new(0, theme.size.dialogNav, 1, 0)
				or UDim2.new(1, 0, 0, railHeight + theme.space.xs * 2 + theme.size.scrollbar)
			addButton.instance.Visible = wide
			divider.Size = wide and UDim2.new(0, theme.stroke.hair, 1, 0)
				or UDim2.new(1, 0, 0, theme.stroke.hair)
			detailHolder.Size = wide and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 0, 0)
			railScroll.layout.FillDirection = wide and Enum.FillDirection.Vertical or Enum.FillDirection.Horizontal
			railScroll.layout.VerticalAlignment = wide and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Center
			railScroll.instance.AutomaticCanvasSize = wide and Enum.AutomaticSize.Y or Enum.AutomaticSize.X
			railScroll.instance.ScrollingDirection = wide and Enum.ScrollingDirection.Y or Enum.ScrollingDirection.X
			railScroll.instance.VerticalScrollBarInset = wide and Enum.ScrollBarInset.ScrollBar or Enum.ScrollBarInset.None
			railScroll.instance.HorizontalScrollBarInset = wide and Enum.ScrollBarInset.None or Enum.ScrollBarInset.ScrollBar
			if changed then
				railScroll.instance.CanvasPosition = Vector2.new(0, 0)
				panel.renderRail()
			end
		end
		root:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
		local unsubscribeLayout = responsive.changed:connect(reflow)
		reflow()

		-- Detail ---------------------------------------------------------------

		local statusBox = nil
		local healthError = nil
		local modelQueries = {}
		local modelPositions = {}

		local function order()
			panel.__order = (panel.__order or 0) + 1
			return panel.__order
		end

		local function modelMenu(record, target, onDone)
			local options = {}
			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end
			for _, id in ipairs(models.list(record)) do
				local badge = traits.badge(id, record)
				local bits = {}
				if models.isFree(record, id) then bits[#bits + 1] = "Free" end
				if badge then bits[#bits + 1] = badge end
				if not own[id] then bits[#bits + 1] = "from catalog" end
				options[#options + 1] = {
					label = id,
					value = "model:" .. id,
					detail = #bits > 0 and table.concat(bits, "  \194\183  ") or nil,
					selected = id == record.model,
					free = models.isFree(record, id),
				}
			end
			if #options > 0 then options[#options + 1] = { divider = true } end
			options[#options + 1] = {
				label = fetchLabel(record),
				value = "fetch",
				detail = modelSource(record),
				searchable = false,
				tone = "info",
			}
			options[#options + 1] = { label = "Add a model by id", value = "add", tone = "info", searchable = false }
			overlay.menu({
				target = target,
				width = theme.size.menuWide,
				options = options,
				searchable = true,
				searchPlaceholder = "Search model IDs...",
				emptyText = "No matching models. Refresh the catalog or add an exact ID.",
				onSelect = function(value)
					if value == "fetch" then
						local revision = selectionRevision
						local function aborted()
							return not root.Parent or selected ~= record.id or revision ~= selectionRevision or registry.get(record.id) ~= record
						end
						overlay.toast("Fetching models from " .. record.label, "info", 2)
						task.spawn(function()
							local found, note = models.discover(record, { force = true, aborted = aborted })
							if aborted() then return end
							overlay.toast(tostring(note), #found > 0 and "good" or "warn", 3)
							if onDone then pcall(onDone) end
						end)
					elseif value == "add" then
						overlay.prompt({
							title = "Add a model to " .. record.label,
							description = "Type the id exactly as the provider expects it. "
								.. "It is saved to this provider and selected.",
							placeholder = "model id",
							confirmText = "Add",
							onConfirm = function(text)
								local ok, result = models.add(record, text)
								if ok then registry.setModel(record.id, util.trim(text)) end
								overlay.toast(tostring(result), ok and "good" or "warn", 3)
								if onDone then pcall(onDone) end
							end,
						})
					elseif util.startsWith(tostring(value), "model:") then
						registry.setModel(record.id, tostring(value):sub(7))
						if onDone then pcall(onDone) end
					end
				end,
			})
		end

		function panel.renderDetail()
			detail.clear()
			statusBox = nil
			healthError = nil
			panel.__order = 0
			local record = selected and registry.get(selected) or nil
			if config.vaultStatus().locked then
				local locked = R.section(detail.instance, { name = "ProviderVaultLocked", title = "Credential vault locked",
					description = "Unlock saved credentials before changing providers or making requests.", layoutOrder = order() })
				P.button(locked, { name = "UnlockProviderVault", text = "Unlock credential vault", fill = true,
					onClick = function() env.require("ui/credentialvault").open("unlock") end })
				return
			end
			-- Included free access must not hide the way to anything else.
			local list = registry.list()
			if not record then
				if #list == 0 then
					-- Nothing configured: the start card is the empty state. Two surfaces
					-- saying "add a provider" one above the other is one too many.
					M.startCard(detail.instance, function(id) panel.select(id) end, order)
				else
					C.emptyState(detail.instance, {
						title = "Pick a provider from the list",
						description = "Its endpoint, key, model and health are all edited here.",
						layoutOrder = order(),
					})
				end
				return
			end
			-- A panel holding nothing but the included free route is still a first run:
			-- keep the way to a paid or local provider visible above its detail.
			if #list == 1 and communityKey.isApplied(list[1]) then
				M.startCard(detail.instance, function(id) panel.select(id) end, order)
			end

			local active = registry.active()
			local isActive = active and active.id == record.id

			-- Header. The window chrome already names the panel and the active provider, so
			-- this names the record being edited instead of repeating either.
			local head = P.row(detail.instance, {
				name = "DetailHead",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
				layoutOrder = order(),
			})
			local titleColumn = P.column(head, {
				size = UDim2.new(0, 0, 0, 0),
				auto = "Y",
				flex = "Fill",
				gap = theme.space.hair,
				layoutOrder = 1,
			})
			local title = P.text(titleColumn, {
				name = "ProviderTitle",
				text = record.label,
				role = "display",
				color = theme.color.text,
				wrap = true,
				auto = "Y",
			})
			title.Size = UDim2.new(1, 0, 0, 0)
			-- Which tier this record belongs to, before the address. A panel with a
			-- free route and three paid ones reads as a list of equal things otherwise,
			-- and the one question someone has about a provider is what it costs.
			local subtitleRow = P.row(titleColumn, {
				name = "ProviderMeta",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
			})
			local presetForRecord = catalog.get(record.preset)
			if presetForRecord then
				local badgeText, tone = catalog.badge(presetForRecord)
				P.badge(subtitleRow, { text = badgeText, tone = tone, layoutOrder = 1 })
			end
			local subtitle = P.text(subtitleRow, {
				name = "ProviderEndpoint",
				text = registry.isCline(record) and "Cline through the desktop app" or urls.display(record.baseUrl),
				role = "caption",
				color = theme.color.textTertiary,
				truncate = true,
				size = UDim2.new(0, 0, 0, theme.text.caption.height),
				flex = "Fill",
				layoutOrder = 2,
			})

			-- Status ------------------------------------------------------------
			local modelOrder = order()
			local status = R.section(detail.instance, {
				name = "Status",
				title = "Connection",
				description = "Your endpoint, authentication and recent connection health.",
				layoutOrder = order(),
			})
			statusBox = R.facts(status, factsFor(record), { name = "StatusFacts", layoutOrder = 1 })

			local health = record.health or {}
			healthError = R.paragraph(status, health.lastError or "",
				{ name = "HealthError", color = theme.color.danger, layoutOrder = 2 })
			healthError.Visible = util.trim(health.lastError or "") ~= ""
			-- The preset's own guidance, which the registry copies onto every record and
			-- nothing has ever rendered: Azure's deployment-path rule, Ollama's loopback
			-- warning, DeepSeek's reasoning field.
			local preset = catalog.get(record.preset)
			local note = (preset and (preset.free or registry.isOpencode(record)) and preset.note) or record.note
			if util.trim(note or "") ~= "" then
				R.paragraph(status, note, { name = "ProviderIntroduction", layoutOrder = 3 })
			end
			-- Fallback is a global switch, and the old header claimed the chain was always
			-- in use. Saying which it is beats asserting one of them.
			R.paragraph(status, config.get("agent.fallback", true)
				and "Requests try the active provider first, then every other enabled one."
				or "Fallback is off under Settings, so only the active provider is tried.",
				{ layoutOrder = 4 })

			local actions = {}
			actions[#actions + 1] = {
				name = "ProviderCommunity", text = "Discord community", variant = "ghost",
				onClick = function() env.require("ui/community").open() end,
			}
			if not isActive then
				actions[#actions + 1] = {
					name = "UseProvider",
					text = "Use this provider",
					variant = "primary",
					onClick = function()
						local ok, why = registry.setActive(record.id)
						overlay.toast(ok and (record.label .. " is now the active provider") or tostring(why), ok and "good" or "warn", 2)
					end,
				}
			end
			actions[#actions + 1] = {
				name = "EditConnection",
				text = "Edit connection",
				variant = "secondary",
				onClick = function() M.editor(record, function() panel.select(record.id) end) end,
			}
			if record.preset ~= "projectuai-free" then
				actions[#actions + 1] = { name = "DuplicateConnection", text = "Duplicate setup", variant = "ghost", onClick = function()
					local draft, why = connectionActions.duplicate(record)
					if not draft then overlay.toast(tostring(why), "warn", 3); return end
					M.editor(draft, function(id) panel.select(id) end)
					overlay.toast("Setup copied without keys or custom credential fields. Review and save the new connection.", "info", 4)
				end }
			end
			if connectionActions.hasLearned(record) then
				actions[#actions + 1] = { name = "ResetCompatibility", text = "Reset learned compatibility", variant = "ghost", onClick = function()
					local ok, why = connectionActions.resetLearned(record)
					overlay.toast(ok and "Future requests can relearn this connection's parameter and token limits." or tostring(why), ok and "good" or "warn", 4)
				end }
			end
			if not registry.isCline(record) then
				actions[#actions + 1] = {
					name = "ManageProviderKeys", text = "Manage API keys", variant = "secondary",
					onClick = function() M.manageKeys(record, function() panel.select(record.id) end) end,
				}
			end
			if caps.clipboard then
				actions[#actions + 1] = {
					name = "CopyEndpoint",
					text = "Copy endpoint",
					variant = "ghost",
					onClick = function()
						local ok, why = env.require("runtime/clipboard").write(chat.endpointOf(record))
						overlay.toast(ok and "Copied" or why, ok and "good" or "warn", 1.5)
					end,
				}
			end
			R.actions(status, actions, { name = "StatusActions", layoutOrder = 5 })

			-- Model -------------------------------------------------------------
			local modelSection = R.section(detail.instance, {
				name = "Model",
				title = "Model",
				description = communityKey.isApplied(record)
					and "Auto measures available models in the background and prefers a verified tool-capable route below ten seconds. Speed varies with your prompt and shared capacity. Choose a specific model to keep it fixed."
					or "Models come from the endpoint or your manual entries. Fetch the current list if none are known yet.",
				layoutOrder = modelOrder,
			})
			local known = models.list(record)
			R.select(modelSection, {
				name = "ActiveModel",
				label = "Active model",
				searchable = true,
				searchPlaceholder = "Search model IDs...",
				hint = #known == 0 and "Nothing known yet. Fetch the list, or add an id by hand."
					or (traits.badge(record.model, record) and ("Context window " .. traits.badge(record.model, record))
						or "No published context window for this id."),
				options = (function()
					local out = {}
					for _, id in ipairs(known) do out[#out + 1] = { value = id, label = id, free = models.isFree(record, id) } end
					if #out == 0 then
						out[#out + 1] = { value = record.model, label = record.model ~= "" and record.model or "none" }
					end
					return out
				end)(),
				value = record.model ~= "" and record.model or (known[1] or ""),
				width = theme.size.menu,
				onChange = function(value) registry.setModel(record.id, value) end,
			})
			R.actions(modelSection, {
				{
					name = "ManageModels",
					text = #known == 0 and "Fetch or add a model" or "Manage models",
					variant = "secondary",
					onClick = function(handle)
						modelMenu(record, handle.instance, function() panel.select(record.id) end)
					end,
				},
			}, { name = "ModelActions" })

			local modelRows, modelCount, modelEmpty, modelList = {}, nil, nil, nil
			local modelRowHeight = math.max(theme.size.rowSmall, responsive.minTarget(), theme.text.monoSmall.height + theme.space.xs)
			local function modelListHeight(count)
				local visible = math.min(6, count)
				return visible * modelRowHeight + math.max(0, visible - 1) * theme.space.xs + theme.space.xxs * 2
			end
			local function filterModels(text, preservePosition)
				modelQueries[record.id] = tostring(text or "")
				local matches = env.require("runtime/search").compile(text)
				local visible = 0
				for _, entry in ipairs(modelRows) do
					entry.instance.Visible = matches(entry.id) ~= nil
					if entry.instance.Visible then visible = visible + 1 end
				end
				if modelCount then modelCount.Text = string.format("%d of %d models", visible, #known) end
				if modelEmpty then modelEmpty.Visible = visible == 0 end
				if modelList then
					modelList.instance.Visible = visible > 0
					modelList.instance.Size = UDim2.new(1, 0, 0, modelListHeight(visible))
					if preservePosition ~= true then modelList.instance.CanvasPosition = Vector2.new(0, 0) end
				end
			end
			if #known > 8 then
				P.field(modelSection, { name = "SavedModelSearch", placeholder = "Search this provider's models...",
					text = modelQueries[record.id] or "", layoutOrder = 50, onChange = filterModels })
				modelCount = P.text(modelSection, { name = "SavedModelCount", role = "caption", color = theme.color.textTertiary, layoutOrder = 51 })
				modelEmpty = P.text(modelSection, { name = "NoSavedModelsMatch", text = "No matching models. Clear the search or fetch the latest catalog.",
					role = "small", color = theme.color.textTertiary, wrap = true, auto = "Y", visible = false, layoutOrder = 52 })
			end
			modelList = P.scroll(modelSection, {
				name = "SavedModelList", size = UDim2.new(1, 0, 0, modelListHeight(#known)), gap = theme.space.xs,
				padding = { left = theme.space.xxs, right = theme.space.xs, top = theme.space.xxs, bottom = theme.space.xxs }, layoutOrder = 100,
			})
			modelList.instance.Visible = #known > 0
			local own = {}
			for _, id in ipairs(record.models or {}) do own[id] = true end
			for index, id in ipairs(known) do
				local free = models.isFree(record, id)
				local row = P.rowButton(modelList.instance, {
					name = "Model_" .. tostring(index),
					height = modelRowHeight,
					padding = { x = theme.space.sm },
					radius = theme.radius.sm,
					stroke = free, strokeColor = free and P.freeModelOutline() or nil,
					strokeWidth = free and 1 or nil,
					selected = id == record.model,
					layoutOrder = 100 + index,
					onClick = function()
						registry.setModel(record.id, id)
						panel.select(record.id)
					end,
				})
				local slot = P.frame(row.row, {
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				modelRows[#modelRows + 1] = { instance = row.instance, id = id }
				P.statusDot(slot, {
					diameter = theme.size.dot,
					color = id == record.model and theme.color.accent or theme.color.borderStrong,
					anchor = Vector2.new(0.5, 0.5),
					position = UDim2.fromScale(0.5, 0.5),
				})
				row.label(id, 2, id == record.model and theme.color.text or theme.color.textSecondary,
					"monoSmall")
				if not own[id] then
					local mark = P.badge(row.row, { text = "fetched", layoutOrder = 3 })
					mark.LayoutOrder = 3
				end
				if own[id] and #known > 1 then
					local remove = P.iconButton(row.row, {
						name = "RemoveModel",
						icon = "close",
						diameter = theme.size.rowSmall,
						variant = "ghost",
						layoutOrder = 4,
						onClick = function()
							models.remove(record, id)
							panel.select(record.id)
						end,
					})
					remove.instance.LayoutOrder = 4
				end
			end
			if modelCount then filterModels(modelQueries[record.id] or "", true) end
			modelList.instance.CanvasPosition = modelPositions[record.id] or Vector2.new(0, 0)
			modelList.instance:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
				modelPositions[record.id] = modelList.instance.CanvasPosition
			end)

			-- Behaviour ---------------------------------------------------------
			local behaviour = R.section(detail.instance, {
				name = "Behaviour",
				title = "Behaviour",
				description = "Preferences for this provider. Global settings still apply.",
				layoutOrder = order(),
			})
			R.toggle(behaviour, {
				name = "Enabled",
				label = "Enabled",
				hint = "A disabled provider is skipped by the fallback chain. Disabling the active "
					.. "one leaves it flagged active while requests go elsewhere.",
				value = record.enabled ~= false,
				layoutOrder = 1,
				onChange = function(value)
					record.enabled = value
					registry.save(record, { force = true })
				end,
			})
			R.toggle(behaviour, {
				name = "Stream",
				label = "Streaming responses",
				hint = "Streamed replies carry reasoning text and token counts. Turning this off "
					.. "always takes effect; turning it on only does while Settings has streaming on.",
				value = record.stream ~= false,
				layoutOrder = 2,
				onChange = function(value)
					record.stream = value
					registry.save(record, { force = true })
				end,
			})
			if registry.requiresClaude(record) then
				R.paragraph(behaviour,
					"Claude Code identity is required by AgentRouter and is always sent. It cannot be turned off for this endpoint.",
					{ name = "ClaudeUaRequired", role = "small", color = theme.color.textSecondary, layoutOrder = 3 })
			else
				R.toggle(behaviour, {
					name = "ClaudeUa",
					label = "Send the Claude Code identity",
					hint = "The claude-cli User-Agent and its client headers. Turning this off suppresses "
						.. "the whole set for this endpoint whatever the global switch says, which is the "
						.. "one lever this client has when a CDN in front of an API refuses the request.",
					value = record.claudeUa ~= false,
					layoutOrder = 3,
					onChange = function(value)
						record.claudeUa = value
						registry.save(record, { force = true })
					end,
				})
			end

			-- Transport and the three invisible maps -----------------------------
			local advanced = R.section(detail.instance, {
				name = "Advanced",
				title = "Transport",
				description = "Optional gateway streaming and extra headers, body fields and query parameters. "
					.. "HTTP works without a socket; the provider and host still set request limits.",
				layoutOrder = order(),
			})
			R.field(advanced, {
				name = "SocketUrl",
				label = "Gateway socket URL",
				hint = "Optional, for Chat completions only. Requires a gateway implementing UAI's envelope protocol. "
					.. "Ordinary local servers and OpenAI Responses/Realtime sockets use different protocols. The gateway receives your provider headers.",
				value = record.wsUrl or "",
				placeholder = "wss://your-uai-gateway.example/stream",
				layoutOrder = 1,
				onChange = function(text)
					record.wsUrl = util.trim(text)
					registry.save(record, { force = true })
				end,
			})

			local extras = {}
			for _, group in ipairs({
				{ field = "headers", label = "header" },
				{ field = "params", label = "body field" },
				{ field = "query", label = "query" },
			}) do
				for _, key in ipairs(util.keys(record[group.field] or {}, true)) do
					extras[#extras + 1] = {
						key = group.label .. " " .. tostring(key),
						value = tostring(record[group.field][key]),
					}
				end
			end
			if #extras > 0 then
				R.facts(advanced, extras, { name = "ExtraFacts", layoutOrder = 4 })
			else
				R.paragraph(advanced, "No extra headers, body fields or query parameters.",
					{ layoutOrder = 4 })
			end

			-- Fallback order ----------------------------------------------------
			local list = registry.list()
			if #list > 1 then
				local position = 1
				for index, entry in ipairs(list) do
					if entry.id == record.id then position = index end
				end
				local ordering = R.section(detail.instance, {
					name = "Order",
					title = "Fallback order",
					description = string.format(
						"Position %d of %d. If fallback is enabled and the active provider fails, "
						.. "other enabled providers are tried in this order.", position, #list),
					layoutOrder = order(),
				})
				local moves = {}
				if position > 1 then
					moves[#moves + 1] = {
						name = "MoveUp",
						text = "Move up",
						variant = "secondary",
						onClick = function() registry.reorder(record.id, -1) end,
					}
				end
				if position < #list then
					moves[#moves + 1] = {
						name = "MoveDown",
						text = "Move down",
						variant = "secondary",
						onClick = function() registry.reorder(record.id, 1) end,
					}
				end
				R.actions(ordering, moves, { name = "OrderActions" })
			end

			-- Removal -----------------------------------------------------------
			local danger = R.section(detail.instance, {
				name = "Remove",
				title = "Remove",
				description = "The endpoint and its key are deleted from this device. This cannot "
					.. "be undone.",
				layoutOrder = order(),
			})
			R.actions(danger, {
				{
					name = "RemoveProvider",
					text = "Remove " .. record.label,
					-- The danger variant, which exists for exactly this and which every other
					-- destructive control in the app already uses. This one was a ghost button
					-- sitting between Edit and nothing.
					variant = "danger",
					onClick = function()
						-- Says what happens next. registry.remove silently promotes the first
						-- remaining record when the active one goes, and the old confirmation
						-- did not mention it.
						local successor = nil
						for _, entry in ipairs(registry.list()) do
							if entry.id ~= record.id and not successor then successor = entry end
						end
						local description = "The endpoint and its key are deleted from this device."
						if isActive and successor then
							description = description .. " " .. successor.label
								.. " becomes the active provider."
						elseif isActive then
							description = description .. " No provider will be configured afterwards."
						end
						overlay.confirm({
							title = "Remove " .. record.label .. "?",
							description = description,
							confirmText = "Remove",
							danger = true,
							onConfirm = function()
								local removed, why = registry.remove(record.id)
								if not removed then overlay.toast(why, "warn", 4); return end
								panel.select(successor and successor.id or nil)
							end,
						})
					end,
				},
			}, { name = "DangerActions" })
		end

		-- Wiring ---------------------------------------------------------------

		function panel.select(id)
			if not root.Parent then return end
			local previous = selected
			local position = detail.instance.CanvasPosition
			local list = registry.list()
			if id and registry.get(id) then
				selected = id
			else
				local active = registry.active()
				selected = (active and active.id) or (list[1] and list[1].id) or nil
			end
			if selected ~= previous then selectionRevision = selectionRevision + 1 end
			panel.renderRail()
			panel.renderDetail()
			detail.instance.CanvasPosition = previous == selected and position or Vector2.new(0, 0)
		end

		-- Health arrives on every single completion, and the panel used to rebuild
		-- itself from scratch each time -- header, rail, detail, scroll position, and the
		-- enable switch mid-animation. Only the facts block and the rail dots can change
		-- for a health event, so only those are repainted.
		local function repaintHealth()
			local record = selected and registry.get(selected) or nil
			local active = registry.active()
			for id, entry in pairs(railRows) do
				local candidate = registry.get(id)
				if candidate and entry.dot.Parent then
					entry.dot.BackgroundColor3 = dotFor(candidate, active and active.id == id)
				end
			end
			if record and statusBox and statusBox.Parent then
				local replacement = R.facts(statusBox.Parent, factsFor(record),
					{ name = "StatusFacts", layoutOrder = 1 })
				pcall(function() statusBox:Destroy() end)
				statusBox = replacement
			end
			if record and healthError and healthError.Parent then
				healthError.Text = tostring((record.health or {}).lastError or "")
				healthError.Visible = util.trim(healthError.Text) ~= ""
			end
		end

		panel.select(nil)

		panel.unsubscribe = registry.changed:connect(function(reason)
			if not root.Parent then return end
			if reason == "health" then
				repaintHealth()
			else
				panel.select(selected)
			end
		end)
		local unsubscribeVault = config.changed:connect(function(path)
			if root.Parent and (path == nil or path == "security" or path == "security.vault") then panel.select(selected) end
		end)
		root.Destroying:Connect(function()
			pcall(panel.unsubscribe)
			pcall(unsubscribeLayout)
			pcall(unsubscribeVault)
		end)

		panel.root = root
		panel.scroll = detail
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settings
-- ==========================================================================
__UAI_MODULES["ui/panels/settings"] = (function()
-- The Settings panel: every pane, stacked in one scroll.
--
-- The panes themselves live in ui/settingspanes, because the settings dialog the
-- sidebar opens shows the same ones behind a category list. This surface is the one
-- that shows all of them at once, which is what a panel in a five-panel client is
-- for -- and it means a setting cannot exist in one place and not the other.
return function(env)
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local panes = env.require("ui/settingspanes")
	local responsive = env.require("ui/responsive")
	local searchUI = env.require("ui/settings_search")

	local M = {}

	function M.new(parent)
		local panel = {}
		local searchHeight = math.max(theme.size.control, responsive.minTarget()) + theme.space.sm * 2
		local scroll = P.scroll(parent, {
			name = "Settings",
			size = UDim2.new(1, 0, 1, -searchHeight),
			position = UDim2.fromOffset(0, searchHeight),
			gap = theme.space.lg,
			padding = theme.space.lg,
		})

		local columns = {}
		for index, entry in ipairs(panes.PANES) do
			local column = P.column(scroll.instance, {
				name = "Pane_" .. entry.id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.md,
				layoutOrder = index,
			})
			panes.render(entry.id, column)
			columns[entry.id] = column
		end
		local searching, position = false, Vector2.new(0, 0)
		local search
		function panel.reveal(category, path)
			if not columns[category] then return false end
			search.setQuery("")
			task.defer(function()
				task.wait()
				if scroll.instance.Parent then searchUI.reveal(scroll.instance, columns[category], path) end
			end)
			return true
		end
		search = searchUI.new(parent, scroll.instance, {
			onQuery = function(value)
				if value and not searching then position = scroll.instance.CanvasPosition end
				local changed = searching ~= value
				searching = value
				for _, column in pairs(columns) do column.Visible = not value end
				if changed or value then scroll.instance.CanvasPosition = value and Vector2.new(0, 0) or position end
			end,
			onChoose = function(item) panel.reveal(item.category, item.path) end,
		})

		panel.scroll = scroll
		panel.search = search
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/settingsdialog
-- ==========================================================================
__UAI_MODULES["ui/panels/settingsdialog"] = (function()
-- The settings dialog: a category list on the left, one pane on the right.
--
-- The same panes the Settings panel stacks, shown one at a time -- so this is a
-- different arrangement of the same settings rather than a second set. It opens from
-- the profile menu, from the sidebar's Settings row and from the shortcut, and every
-- entry point lands here on a named category.
return function(env)
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local panes = env.require("ui/settingspanes")
	local config = env.require("runtime/config")
	local searchUI = env.require("ui/settings_search")

	local M = {}

	function M.open(initial)
		local dialog = overlay.dialog({ name = "SettingsDialog" })
		if not dialog then return nil end

		-- Categories become a scrollable strip whenever the dialog is too narrow
		-- for both columns. Resizing only changes geometry, preserving live fields.
		local narrow = dialog.width < (theme.size.dialogNav * 3)
		local navWidth = narrow and dialog.width or theme.size.dialogNav
		-- The height of the collapsed category strip, and therefore the offset of
		-- everything under it. It was this same sum written out four times.
		local tabHeight = math.max(theme.size.controlLarge, responsive.minTarget(), theme.text.small.height + theme.space.xs * 2)
		local stripHeight = tabHeight + theme.space.xs * 2 + theme.size.scrollbar
		-- The corner the dialog's own close button occupies. Reserved rather than drawn
		-- under: with the strip spanning the full width, the button sat on top of the last
		-- category and nothing could reach it.
		local closeInset = dialog.closeInset or theme.space.xxl

		local navHolder = P.frame(dialog.card, {
			name = "DialogNav",
			size = narrow and UDim2.new(1, 0, 0, stripHeight)
				or UDim2.new(0, navWidth, 1, 0),
			bg = theme.color.sidebar,
		})
		-- UICorner rounds a frame's own fill, not its descendants, so the nav bar
		-- has to carry the dialog's radius on the corners it exposes -- the left
		-- pair in the wide layout, the top pair in the collapsed strip. The edge
		-- fill keeps the side it shares with the body straight.
		P.corner(navHolder, theme.radius.xl)
		local navEdge = P.frame(navHolder, {
			name = "DialogNavEdgeFill",
			size = UDim2.new(0, theme.radius.xl, 1, 0),
			position = UDim2.new(1, -theme.radius.xl, 0, 0),
			bg = theme.color.sidebar,
		})
		local nav = P.scroll(navHolder, {
			name = "Categories",
			size = UDim2.new(1, narrow and -closeInset or 0, 1, 0),
			gap = theme.space.hair,
			padding = {
				left = theme.space.xs,
				right = theme.space.xs,
				y = theme.space.xs,
			},
			horizontal = narrow,
			alignX = "Left",
		})

		local divider = P.frame(dialog.card, {
			name = "DialogDivider",
			size = narrow and UDim2.new(1, 0, 0, theme.stroke.hair) or UDim2.new(0, theme.stroke.hair, 1, 0),
			position = narrow and UDim2.new(0, 0, 0, stripHeight)
				or UDim2.new(0, navWidth, 0, 0),
			bg = theme.color.borderSubtle,
		})

		local bodyHolder = P.frame(dialog.card, {
			name = "DialogBody",
			size = narrow and UDim2.new(1, 0, 1, -(stripHeight + theme.stroke.hair))
				or UDim2.new(1, -(navWidth + theme.stroke.hair), 1, 0),
			position = narrow and UDim2.new(0, 0, 0, stripHeight + theme.stroke.hair)
				or UDim2.new(0, navWidth + theme.stroke.hair, 0, 0),
		})
		local searchHeight = math.max(theme.size.control, responsive.minTarget()) + theme.space.sm * 2
		local body = P.scroll(bodyHolder, {
			name = "PaneScroll",
			size = UDim2.new(1, 0, 1, -searchHeight),
			position = UDim2.fromOffset(0, searchHeight),
			gap = theme.space.md,
			padding = {
				left = theme.space.lg,
				-- Wide layouts put the close button over the top of this pane, so the first
				-- row's right edge has to clear it.
				right = narrow and theme.space.lg or closeInset,
				top = theme.space.lg,
				bottom = theme.space.xl,
			},
		})

		local rows = {}
		local active = nil
		local cached = {}
		local search, searching, searchPosition = nil, false, nil
		local function revealCategory()
			local selected = rows[active]
			if dialog.closed or not selected or not selected.instance.Parent then return end
			local axis = narrow and "X" or "Y"
			local viewport = nav.instance.AbsoluteSize[axis]
			local length = selected.instance.AbsoluteSize[axis]
			if viewport <= 0 or length <= 0 then return end
			local position = nav.instance.CanvasPosition[axis]
			local start = selected.instance.AbsolutePosition[axis] - nav.instance.AbsolutePosition[axis]
			local target = position
			if start < theme.space.xs then
				target = position + start - theme.space.xs
			elseif start + length > viewport - theme.space.xs then
				target = position + start + length - viewport + theme.space.xs
			end
			if target ~= position then
				nav.instance.CanvasPosition = narrow and Vector2.new(math.max(0, target), 0)
					or Vector2.new(0, math.max(0, target))
			end
		end
		-- Keep native drafts when switching categories. External changes invalidate
		-- the saved view; only drafts still bound to the same value are restored.
		local function visitFields(column, callback)
			local function walk(parent, path)
				local counts = {}
				for _, child in ipairs(parent:GetChildren()) do
					local name = child.ClassName .. ":" .. child.Name
					counts[name] = (counts[name] or 0) + 1
					local key = path .. "/" .. name .. ":" .. counts[name]
					if child:IsA("TextBox") then callback(child, key) end
					walk(child, key)
				end
			end
			walk(column, "")
		end
		local function captureDrafts(column)
			local drafts = {}
			visitFields(column, function(field, key)
				local path = field:GetAttribute("UAIConfigPath")
				if not path or field:GetAttribute("UAIConfigValue") == tostring(config.get(path, "")) then
					drafts[key] = { text = field.Text, cursor = field.CursorPosition, selection = field.SelectionStart }
				end
			end)
			return drafts
		end
		local unsubscribe = panes.observeChanges(function()
			for _, entry in pairs(cached) do entry.dirty = true end
		end)
		dialog.card.Destroying:Connect(unsubscribe)

		local function select(id)
			if search and searching then search.setQuery("") end
			if dialog.closed or not panes.pane(id) or active == id then return end
			if active and cached[active] then
				cached[active].position = body.instance.CanvasPosition
				cached[active].column.Visible = false
			end
			active = id
			for key, row in pairs(rows) do
				row.setSelected(key == id)
				row.text.TextColor3 = (key == id) and theme.color.text or theme.color.textSecondary
			end
			local drafts, position
			if cached[id] and cached[id].dirty then
				drafts, position = captureDrafts(cached[id].column), cached[id].position
				cached[id].column:Destroy(); cached[id] = nil
			end
			if not cached[id] then
				local column = P.column(body.instance, { name = "Pane_" .. id,
					size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.md, layoutOrder = 1 })
				panes.render(id, column)
				cached[id] = { column = column, position = position or Vector2.new(0, 0) }
				if drafts then visitFields(column, function(field, key)
					local draft = drafts[key]
					if draft then field.Text, field.CursorPosition, field.SelectionStart = draft.text, draft.cursor, draft.selection end
				end) end
			end
			cached[id].column.Visible = true
			body.instance.CanvasPosition = cached[id].position
			task.defer(function()
				if not dialog.closed and active == id then
					body.instance.CanvasPosition = cached[id].position
					revealCategory()
				end
			end)
		end

		local function reveal(category, path)
			if not panes.pane(category) then return false end
			select(category)
			task.defer(function()
				task.wait()
				if dialog.closed or active ~= category or not cached[category] then return end
				searchUI.reveal(body.instance, cached[category].column, path)
			end)
			return true
		end
		search = searchUI.new(bodyHolder, body.instance, {
			onQuery = function(value)
				if value and not searching then searchPosition = body.instance.CanvasPosition end
				local changed = searching ~= value
				searching = value
				if active and cached[active] then cached[active].column.Visible = not value end
				if changed or value then body.instance.CanvasPosition = value and Vector2.new(0, 0) or (searchPosition or Vector2.new(0, 0)) end
			end,
			onChoose = function(item) reveal(item.category, item.path) end,
		})

		local function renderNav()
			nav.clear()
			rows = {}
			local order = 0
			local function nextOrder()
				order = order + 1
				return order
			end

			if not narrow then
				P.text(nav.instance, {
					name = "SettingsTitle", text = "Settings", role = "title",
					size = UDim2.new(1, 0, 0, theme.text.title.height + theme.space.lg),
					padding = { x = theme.space.sm, y = theme.space.sm },
					layoutOrder = nextOrder(),
				})
			end

			for _, section in ipairs(panes.sections()) do
				-- Section headings belong to the vertical list, not the tab strip.
				if not narrow then
					P.text(nav.instance, {
						name = "Section_" .. section.title, text = section.title, role = "caption",
						color = theme.color.textTertiary, truncate = true,
						size = UDim2.new(1, 0, 0, theme.text.caption.height + theme.space.xs),
						padding = { x = theme.space.xs, top = theme.space.xs }, layoutOrder = nextOrder(),
					})
				end
				for _, entry in ipairs(section.panes) do
					local row = P.rowButton(nav.instance, {
						name = "Category_" .. entry.id,
						size = narrow and UDim2.fromOffset(0, tabHeight) or nil,
						auto = narrow and "X" or nil,
						selected = active == entry.id,
						layoutOrder = nextOrder(),
						onClick = function() select(entry.id) end,
					})
					row.icon(entry.icon, 1, theme.color.textSecondary, theme.size.icon)
					if narrow then
						row.text = P.text(row.row, { name = "Label", text = entry.label, role = "small",
							auto = "X", truncate = true, maxSize = Vector2.new(theme.size.menuMin, math.huge),
							color = theme.color.textSecondary, layoutOrder = 2 })
					else
						row.text = row.label(entry.label, 2, theme.color.textSecondary, "small")
					end
					row.text.TextColor3 = active == entry.id and theme.color.text or theme.color.textSecondary
					rows[entry.id] = row
				end
			end
		end

		local function reflow()
			if dialog.closed then return end
			local width = dialog.card.AbsoluteSize.X
			if width <= 0 then width = dialog.width end
			local nextNarrow = width < theme.size.dialogNav * 3
			local changed = narrow ~= nextNarrow
			narrow = nextNarrow
			navWidth = theme.size.dialogNav
			navHolder.Size = narrow and UDim2.new(1, 0, 0, stripHeight) or UDim2.new(0, navWidth, 1, 0)
			nav.instance.Size = UDim2.new(1, narrow and -closeInset or 0, 1, 0)
			nav.layout.FillDirection = narrow and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
			nav.instance.AutomaticCanvasSize = narrow and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
			nav.instance.ScrollingDirection = narrow and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
			nav.instance.VerticalScrollBarInset = narrow and Enum.ScrollBarInset.None or Enum.ScrollBarInset.ScrollBar
			nav.instance.HorizontalScrollBarInset = narrow and Enum.ScrollBarInset.ScrollBar or Enum.ScrollBarInset.None
			divider.Size = narrow and UDim2.new(1, 0, 0, theme.stroke.hair) or UDim2.new(0, theme.stroke.hair, 1, 0)
			divider.Position = narrow and UDim2.new(0, 0, 0, stripHeight) or UDim2.new(0, navWidth, 0, 0)
			-- The nav bar exposes its rounded corners on the card's outer edge only;
			-- this fill squares the side it shares with the body as the layout turns.
			navEdge.Size = narrow and UDim2.new(1, 0, 0, theme.radius.xl) or UDim2.new(0, theme.radius.xl, 1, 0)
			navEdge.Position = narrow and UDim2.new(0, 0, 1, -theme.radius.xl) or UDim2.new(1, -theme.radius.xl, 0, 0)
			bodyHolder.Size = narrow and UDim2.new(1, 0, 1, -(stripHeight + theme.stroke.hair))
				or UDim2.new(1, -(navWidth + theme.stroke.hair), 1, 0)
			bodyHolder.Position = narrow and UDim2.new(0, 0, 0, stripHeight + theme.stroke.hair)
				or UDim2.new(0, navWidth + theme.stroke.hair, 0, 0)
			body.instance:FindFirstChildOfClass("UIPadding").PaddingRight = UDim.new(0, narrow and theme.space.lg or closeInset)
			search.toolbar:FindFirstChildOfClass("UIPadding").PaddingRight = UDim.new(0, narrow and theme.space.sm or closeInset)
			if changed then
				nav.instance.CanvasPosition = Vector2.new(0, 0)
				renderNav()
			end
			task.defer(revealCategory)
		end
		renderNav()
		dialog.card:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
		reflow()

		select(panes.pane(initial) and initial or panes.PANES[1].id)

		dialog.select = select
		dialog.reveal = reveal
		dialog.search = search
		dialog.activeCategory = function() return active end
		return dialog
	end

	return M
end
end)()

-- ==========================================================================
-- ui/panels/tools
-- ==========================================================================
__UAI_MODULES["ui/panels/tools"] = (function()
-- Tools panel: what the agent can do here, and what it is allowed to do.
--
-- Permission rules live next to the tool they govern rather than in a separate
-- list, because "can it delete files" is a question about file_delete, not about a
-- rules table.
return function(env)
	local util = env.require("runtime/util")
	local caps = env.require("runtime/caps")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local registry = env.require("agent/registry")
	local permissions = env.require("agent/permissions")
	local schema = env.require("agent/schema")
	local search = env.require("runtime/search")

	local M = {}

	local RULE_OPTIONS = {
		{ value = "default", label = "Default" },
		{ value = "allow", label = "Allow" },
		{ value = "ask", label = "Ask" },
		{ value = "deny", label = "Deny" },
	}

	local GROUP_LABELS = registry.GROUP_LABELS

	function M.new(parent)
		local panel = {}
		local filter = ""
		local expanded = {}

		local column = P.column(parent, {
			name = "ToolsPanel",
			size = UDim2.new(1, 0, 1, 0),
			gap = 0,
		})

		local head = P.column(column, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			padding = { x = theme.space.lg, top = theme.space.lg, bottom = theme.space.md },
			layoutOrder = 1,
		})

		local stats = registry.stats()
		P.text(head, {
			text = string.format("%d tools in %d groups", stats.total, util.count(stats.byGroup)),
			role = "heading",
			layoutOrder = 1,
		})
		local summary = P.text(head, {
			text = #stats.unavailable > 0
				and string.format("%d unavailable on this host. %s", #stats.unavailable, caps.summary())
				or "All tools are available on this host. Open a tool to review its parameters and permissions.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 2,
		})
		summary.Size = UDim2.new(1, 0, 0, 0)

		local scroll, results

		local function rebuild()
			if not column.Parent or not scroll then return end
			local scrollPosition = scroll.instance.CanvasPosition
			scroll.clear()
			local match = search.compile(filter)
			local grouped = {}
			local matched = 0
			for _, tool in ipairs(registry.list()) do
				if match(tool.name, tool.description, tool.group, GROUP_LABELS[tool.group], tool.risk) then
					matched = matched + 1
					grouped[tool.group] = grouped[tool.group] or {}
					table.insert(grouped[tool.group], tool)
				end
			end
			if results then results.Text = util.pluralise(matched, "matching tool") end

			local order = util.keys(grouped, true)
			if #order == 0 then
				C.emptyState(scroll.instance, {
					icon = "search",
					title = "No matching tools",
					description = "Search by a tool name or what you want it to do.",
					layoutOrder = 1,
				})
				return
			end

			local position = 0
			for _, group in ipairs(order) do
				position = position + 1
				-- The group header carries its own switch: turning a family off removes it
				-- from the list the model is sent, which is a different thing from denying
				-- a call and belongs next to the family rather than in a settings pane.
				local header = P.row(scroll.instance, {
					name = "Group_" .. tostring(group),
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.sm,
					-- The same inset a card gives its own contents, so a group's name lines up
					-- with the tool names under it instead of sitting sixteen pixels to their
					-- left, and its switch lines up with theirs.
					padding = { x = theme.space.md, top = theme.space.sm, bottom = theme.space.xxs },
					layoutOrder = position,
				})
				local headText = P.column(header, {
					size = UDim2.new(0, 0, 0, 0),
					auto = "Y",
					flex = "Fill",
					gap = 0,
					layoutOrder = 1,
				})
				P.text(headText, {
					text = GROUP_LABELS[group] or group,
					role = "label",
					color = theme.color.text,
					auto = "Y",
					wrap = true,
				})
				local groupNote = P.text(headText, {
					text = "",
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				local function describeGroup()
					groupNote.Text = registry.groupEnabled(group)
						and util.pluralise(#grouped[group], "tool")
						or (util.pluralise(#grouped[group], "tool") .. ", not offered to the model")
				end
				describeGroup()
				local groupSwitch = C.switch(header, {
					value = registry.groupEnabled(group),
					onChange = function(value)
						registry.setGroupEnabled(group, value)
						describeGroup()
					end,
				})
				groupSwitch.instance.LayoutOrder = 2

				for _, tool in ipairs(grouped[group]) do
					position = position + 1
					local missing = registry.missingCapability(tool)
					local card = P.card(scroll.instance, {
						name = tool.name,
						layoutOrder = position,
						gap = theme.space.xs,
						padding = theme.space.md,
						bg = theme.color.surface,
						radius = theme.radius.md,
					})

					local top = P.column(card, {
						size = UDim2.new(1, 0, 0, 0),
						auto = "Y",
						gap = theme.space.xs,
						layoutOrder = 1,
					})
					local name = P.text(top, {
						text = tool.name,
						role = "monoSmall",
						color = missing and theme.color.textSecondary or theme.color.text,
						wrap = true,
						auto = "Y",
						layoutOrder = 1,
					})
					local badges = P.row(top, { size = UDim2.new(1, 0, 0, 0), auto = "Y",
						wrap = true, gap = theme.space.xs, layoutOrder = 2 })
					P.badge(badges, {
						text = tool.risk,
						tone = tool.risk == "read" and "info" or (tool.risk == "danger" and "bad" or "warn"),
						layoutOrder = 2,
					})
					if missing then
						P.badge(badges, { text = "unavailable", tone = "warn", layoutOrder = 3 })
					end

					local description = P.text(card, {
						text = tostring(tool.description),
						role = "caption",
						color = theme.color.textSecondary,
						wrap = true,
						auto = "Y",
						layoutOrder = 2,
					})
					description.Size = UDim2.new(1, 0, 0, 0)

					local details = P.column(card, { name = "ToolDetails", size = UDim2.new(1, 0, 0, 0),
						auto = "Y", gap = theme.space.sm, layoutOrder = 4, visible = expanded[tool.name] == true })
					local populateDetails, populated
					P.button(card, { name = "ToolDetailsToggle",
						text = expanded[tool.name] and "Hide details" or "Parameters & permissions", variant = "ghost",
						size = "sm", fill = true, align = "Left", tight = true, layoutOrder = 3, onClick = function(button)
							populateDetails()
							details.Visible = not details.Visible
							expanded[tool.name] = details.Visible
							button.setText(details.Visible and "Hide details" or "Parameters & permissions")
						end })
					populateDetails = function()
						if populated then return end
						populated = true
						P.divider(details, { layoutOrder = 1 })
						P.text(details, { name = "ParametersTitle", text = "Parameters", role = "label", layoutOrder = 2 })
						local parameters = P.column(details, { name = "Parameters", size = UDim2.new(1, 0, 0, 0),
							auto = "Y", bg = theme.color.canvas, radius = theme.radius.sm,
							padding = theme.space.sm, layoutOrder = 3 })
						local params = P.text(parameters, {
							text = schema.describe(tool.parameters),
							role = "caption",
							color = theme.color.textTertiary,
							wrap = true,
							auto = "Y",
							layoutOrder = 3,
						})
						params.Size = UDim2.new(1, 0, 0, 0)
						local examples = registry.examples(tool)
						if examples ~= "" then
							P.text(details, { name = "ToolExamples", text = "Examples\n" .. examples, role = "caption", auto = "Y", wrap = true, size = UDim2.new(1, 0, 0, 0), layoutOrder = 6 })
							P.button(details, { name = "CopyToolExample", text = "Copy examples", size = "sm", variant = "ghost", layoutOrder = 7, onClick = function()
								local ok, why = env.require("runtime/clipboard").write(examples)
								env.require("ui/overlay").toast(ok and "Examples copied" or why, ok and "good" or "warn")
							end })
						end

						if missing then
							local reason = P.text(details, {
								text = caps.reason(missing),
								role = "caption",
								color = theme.color.warn,
								wrap = true,
								auto = "Y",
								layoutOrder = 4,
							})
							reason.Size = UDim2.new(1, 0, 0, 0)
						else
							P.text(details, { name = "PermissionTitle", text = "Permission rule", role = "label", layoutOrder = 4 })
							C.segmented(details, {
								options = RULE_OPTIONS,
								value = permissions.ruleFor(tool.name) or "default",
								layoutOrder = 5,
								onChange = function(value)
									permissions.setRule(tool.name, value)
								end,
							})
						end
					end
					if expanded[tool.name] then populateDetails() end
				end
			end
			scroll.instance.CanvasPosition = scrollPosition
		end

		-- Third in the head block, stated rather than left to the tie-break: the two
		-- labels above it are constructed earlier but neither of them sets an order.
		P.field(head, {
			name = "ToolSearch",
			placeholder = 'Search words, "phrases", or -exclude',
			layoutOrder = 3,
			onChange = function(text)
				filter = util.trim(text)
				rebuild()
				if scroll then scroll.instance.CanvasPosition = Vector2.new(0, 0) end
			end,
		})
		results = P.text(head, { name = "ToolSearchCount", text = "", role = "caption",
			color = theme.color.textTertiary, layoutOrder = 4 })
		P.button(head, { name = "ManageChatLoops", text = "Chat loops & quiz scores", variant = "ghost", size = "sm", fill = true, align = "Left",
			layoutOrder = 5, onClick = function(button) env.require("ui/chat/loops").open(button.instance) end })

		-- Keep the flex item outside the clearable list contents.
		local listHolder = P.frame(column, { name = "ToolListHolder", size = UDim2.new(1, 0, 0, 0),
			flex = "Fill", layoutOrder = 2 })
		scroll = P.scroll(listHolder, {
			name = "ToolList",
			size = UDim2.new(1, 0, 1, 0),
			gap = theme.space.sm,
			-- Top padding as well. Without it the first group header butted against the
			-- head block above it while the bottom of the list had twelve pixels of air.
			padding = { x = theme.space.lg, top = theme.space.md, bottom = theme.space.xl },
			layoutOrder = 2,
		})

		rebuild()
		panel.refresh = rebuild
		panel.unsubscribe = permissions.changed:connect(rebuild)
		column.Destroying:Connect(function() pcall(panel.unsubscribe) end)
		return panel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/primitives
-- ==========================================================================
__UAI_MODULES["ui/primitives"] = (function()
-- Layout and interaction primitives.
--
-- Everything visible is built from these, and they all take the same shape of
-- props table, so a panel reads as a description of what it is rather than a
-- hundred lines of instance plumbing. Three rules are enforced here rather than
-- left to each caller: nothing is positioned by hand-computed offsets, every
-- interactive element has a full state set, and every hit target respects the
-- platform minimum.
return function(env)
	local util = env.require("runtime/util")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")

	local P = {}

	-- Shared helpers ---------------------------------------------------------

	-- One current transition per element. Repeated hover/focus changes retarget from
	-- the rendered value instead of leaving competing tweens behind.
	local transitions = setmetatable({}, { __mode = "k" })

	function P.animate(instance, motion, goals, onComplete)
		local state = transitions[instance]
		if not state then
			state = {}
			transitions[instance] = state
			instance.Destroying:Connect(function()
				state.dead = true
				if state.finished then state.finished:Disconnect() end
				if state.tween then state.tween:Cancel() end
				transitions[instance] = nil
			end)
		end
		if state.finished then state.finished:Disconnect() end
		state.finished = nil
		local previous = state.tween
		state.tween = nil
		if previous then previous:Cancel() end
		if responsive.reduceMotion then
			for property, value in pairs(goals) do instance[property] = value end
			if onComplete then onComplete() end
			return nil
		end
		local tween = env.tween:Create(instance, theme.tween(motion), goals)
		state.tween = tween
		state.finished = tween.Completed:Connect(function(playback)
			if state.dead or state.tween ~= tween then return end
			state.tween = nil
			if state.finished then state.finished:Disconnect() end
			state.finished = nil
			if playback ~= Enum.PlaybackState.Cancelled and onComplete then onComplete() end
		end)
		tween:Play()
		return tween
	end

	function P.corner(instance, radius)
		local corner = Instance.new("UICorner", instance)
		corner.CornerRadius = UDim.new(0, radius == nil and theme.radius.md or radius)
		return corner
	end

	function P.stroke(instance, colour, thickness)
		local stroke = Instance.new("UIStroke", instance)
		stroke.Color = colour or theme.color.borderSubtle
		stroke.Thickness = thickness or theme.stroke.hair
		stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		return stroke
	end

	function P.freeModelOutline(background)
		return (background or theme.color.surface):Lerp(theme.color.success, 0.45)
	end

	function P.pad(instance, spec)
		local padding = Instance.new("UIPadding", instance)
		if type(spec) == "number" then
			padding.PaddingTop = UDim.new(0, spec)
			padding.PaddingBottom = UDim.new(0, spec)
			padding.PaddingLeft = UDim.new(0, spec)
			padding.PaddingRight = UDim.new(0, spec)
		elseif type(spec) == "table" then
			local x = spec.x or spec.horizontal
			local y = spec.y or spec.vertical
			padding.PaddingTop = UDim.new(0, spec.top or y or 0)
			padding.PaddingBottom = UDim.new(0, spec.bottom or y or 0)
			padding.PaddingLeft = UDim.new(0, spec.left or x or 0)
			padding.PaddingRight = UDim.new(0, spec.right or x or 0)
		end
		return padding
	end

	local AUTO = {
		X = Enum.AutomaticSize.X,
		Y = Enum.AutomaticSize.Y,
		XY = Enum.AutomaticSize.XY,
	}

	-- Applies the props every visual element shares. Kept in one place so adding a
	-- shared concern (a token, an accessibility flag) is one edit.
	local function base(instance, props)
		props = props or {}
		if props.name then instance.Name = props.name end
		instance.BorderSizePixel = 0
		if props.size then instance.Size = props.size end
		if props.position then instance.Position = props.position end
		if props.anchor then instance.AnchorPoint = props.anchor end
		if props.auto then instance.AutomaticSize = AUTO[props.auto] or Enum.AutomaticSize.None end
		if props.zIndex then instance.ZIndex = props.zIndex end
		if props.layoutOrder then instance.LayoutOrder = props.layoutOrder end
		if props.clip ~= nil then instance.ClipsDescendants = props.clip == true end
		if props.visible ~= nil then instance.Visible = props.visible == true end
		if props.rotation then instance.Rotation = props.rotation end

		if props.bg then
			instance.BackgroundColor3 = props.bg
			instance.BackgroundTransparency = props.bgTransparency or 0
		else
			instance.BackgroundTransparency = 1
		end
		if props.radius ~= nil then P.corner(instance, props.radius) end
		if props.stroke then P.stroke(instance, props.strokeColor, props.strokeWidth) end
		if props.padding then P.pad(instance, props.padding) end
		if props.minSize or props.maxSize then
			local constraint = Instance.new("UISizeConstraint", instance)
			if props.minSize then constraint.MinSize = props.minSize end
			if props.maxSize then constraint.MaxSize = props.maxSize end
		end
		if props.aspect then
			Instance.new("UIAspectRatioConstraint", instance).AspectRatio = props.aspect
		end
		if props.flex then
			local item = Instance.new("UIFlexItem", instance)
			item.FlexMode = Enum.UIFlexMode[props.flex] or Enum.UIFlexMode.Fill
		end
		return instance
	end

	function P.frame(parent, props)
		local frame = Instance.new("Frame", parent)
		return base(frame, props)
	end

	-- Bounded overlay cards can fade as one surface without scaling their layout.
	-- Keep long-lived windows and transcripts on P.frame.
	function P.group(parent, props)
		return base(Instance.new("CanvasGroup", parent), props)
	end

	local function stack(parent, props, direction)
		props = props or {}
		local frame = P.frame(parent, props)
		local layout = Instance.new("UIListLayout", frame)
		layout.FillDirection = direction
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX or "Left"]
		layout.VerticalAlignment = Enum.VerticalAlignment[props.alignY or "Top"]
		if props.wrap then layout.Wraps = true end
		if props.stretch then layout.ItemLineAlignment = Enum.ItemLineAlignment.Stretch end
		return frame, layout
	end

	function P.column(parent, props)
		return stack(parent, props, Enum.FillDirection.Vertical)
	end

	function P.row(parent, props)
		props = props or {}
		props.alignY = props.alignY or "Center"
		return stack(parent, props, Enum.FillDirection.Horizontal)
	end

	-- A gap, or -- with `grow` -- whatever is left over on the line.
	--
	-- A growing spacer starts at nothing. UIFlexItem.Grow only ever hands out the
	-- space a line has left, and it never shrinks a child below its own size, so a
	-- spacer that began at full width left nothing over and pushed every sibling
	-- after it past the parent's edge. That is how a profile row loses its chevron
	-- and a card header loses its right-hand pills.
	function P.spacer(parent, props)
		props = props or {}
		local size = props.size
		if not size then
			if props.grow then
				size = UDim2.fromOffset(0, 0)
			else
				size = UDim2.new(1, 0, 0, props.height or theme.space.sm)
			end
		end
		local frame = P.frame(parent, {
			name = "Spacer",
			size = size,
			layoutOrder = props.layoutOrder,
		})
		if props.grow then
			local item = Instance.new("UIFlexItem", frame)
			item.FlexMode = Enum.UIFlexMode.Grow
		end
		return frame
	end

	function P.divider(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Divider",
			size = props.vertical and UDim2.new(0, 1, 1, 0) or UDim2.new(1, 0, 0, 1),
			bg = props.color or theme.color.borderSubtle,
			layoutOrder = props.layoutOrder,
		})
	end

	-- Text -------------------------------------------------------------------

	-- `size` is the UDim2 every element shares; the font size comes from the role,
	-- or from `textSize` when one label genuinely has to differ. Overloading `size`
	-- for both would assign a number to Size, which Roblox rejects outright.
	--
	-- Two font properties, applied in order. `Font` is the legacy enum and always
	-- takes; `FontFace` is the modern family-plus-weight pair and is layered over it
	-- only when the theme resolved one, so a client without the newer type stack keeps
	-- rendering rather than being assigned nil. Assigning Font *after* FontFace would
	-- undo it -- the two are the same underlying property with different resolutions --
	-- which is why the order here is not arbitrary.
	local function applyFont(label, role, props)
		label.Font = props.font or role.font
		local face = props.face or (not props.font and role.face)
		if face then pcall(function() label.FontFace = face end) end
	end

	-- Synchronous measurement for control widths. GetTextSize is the legacy fallback;
	-- byte counts overestimate UTF-8 and cannot distinguish a W from an i.
	function P.measureText(text, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local size = props.textSize or role.size
		local value = tostring(text or "")
		local width = props.width and math.max(1, props.width) or math.huge
		local ok, bounds = pcall(function()
			return env.services.TextService:GetTextSize(value, size, props.font or role.font,
				Vector2.new(width, math.huge))
		end)
		if ok and bounds then
			return Vector2.new(bounds.X, math.ceil(bounds.Y * (props.line or role.line or 1)))
		end
		local longest, lines = 0, 0
		for line in (value .. "\n"):gmatch("(.-)\n") do
			local _, characters = line:gsub("[^\128-\191]", "")
			longest = math.max(longest, characters * size)
			lines = lines + math.max(1, math.ceil(characters * size / width))
		end
		return Vector2.new(math.min(width, longest), lines * (role.height or size))
	end

	function P.text(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local label = Instance.new("TextLabel", parent)
		base(label, props)
		label.Text = tostring(props.text or "")
		label.TextColor3 = props.color or theme.color.text
		applyFont(label, role, props)
		label.TextSize = props.textSize or role.size
		label.LineHeight = props.line or role.line
		label.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		label.TextYAlignment = Enum.TextYAlignment[props.alignY or "Center"]
		label.TextWrapped = props.wrap == true
		label.RichText = props.rich == true
		if props.transparency then label.TextTransparency = props.transparency end
		if props.truncate then label.TextTruncate = Enum.TextTruncate.AtEnd end
		-- A label with no explicit size collapses to nothing inside a list layout,
		-- which is the single most common way an interface silently loses text.
		-- `auto` only covers the axes it names, so it does not save us here: with
		-- `auto = "Y"` the width is still ours to set, and a zero-width label does
		-- not vanish so much as wrap to one character per line -- the same bug
		-- wearing a costume that reads as a rendering glitch instead of a layout one.
		-- The caller owns the width only when `auto` includes X.
		if not props.size then
			if props.auto == "XY" then
				label.Size = UDim2.fromOffset(0, 0)
			elseif props.auto == "X" then
				-- Width from the text, height from the role. A zero on both axes is what
				-- `auto = "X"` used to produce, and AutomaticSize.X grows the width only --
				-- so the label came out one rendered line wide and no pixels tall, which
				-- is a label that is not there at all. Twenty-odd call sites papered over
				-- it by assigning Size on the next line; the ones that forgot simply
				-- vanished.
				label.Size = UDim2.fromOffset(0, math.max(role.height or role.size,
					math.ceil((props.textSize or role.size) * (props.line or role.line))))
			elseif props.auto == "Y" then
				label.Size = UDim2.new(1, 0, 0, 0)
			else
				-- One rendered line plus a little slack. Sized from the role's line
				-- height, not its font size: at a 1.5 line height the two differ by
				-- seven pixels and the descenders go missing.
				local single = props.textSize and math.ceil(props.textSize * (props.line or role.line))
					or role.height or (role.size + 4)
				label.Size = UDim2.new(1, 0, 0, single + 4)
			end
		end
		return label
	end

	-- A heading with an optional trailing description, which is the pattern every
	-- settings group uses.
	--
	-- Sentence case, not upper. Small-caps headings were doing the work of separating
	-- groups, and spacing does that better: SHOUTED LABELS every hundred pixels are
	-- what makes an interface read as a control panel rather than as a page.
	function P.sectionHeader(parent, props)
		local holder = P.column(parent, {
			name = "Section",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = props.layoutOrder,
		})
		P.text(holder, {
			text = tostring(props.title or ""),
			role = "label",
			color = theme.color.text,
			auto = "Y",
			wrap = true,
		})
		if props.description then
			P.text(holder, {
				text = props.description,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
		end
		return holder
	end

	-- Interaction ------------------------------------------------------------

	-- Button variants.
	--
	-- `primary` is a cream fill with dark text rather than an accent fill. There is
	-- normally one of them per view -- send, save, confirm -- and making it the
	-- brightest thing on the page rather than the most colourful is what leaves the
	-- accent free to mean something: inline code, a running turn, a risk level. Use
	-- `accent` when the colour itself is the message.
	local VARIANTS = {
		primary = function()
			return {
				bg = theme.color.solid, bgHover = theme.color.solidHover, bgPress = theme.color.solidPress,
				text = theme.color.onSolid, stroke = nil, font = "bodyStrong",
			}
		end,
		accent = function()
			return {
				bg = theme.color.accent, bgHover = theme.color.accentHot, bgPress = theme.color.accent,
				text = theme.color.textOnAccent, stroke = nil, font = "bodyStrong",
			}
		end,
		-- No fill at rest, only a hairline. A dark-grey fill on a dark-grey panel adds
		-- a rectangle without adding contrast; the outline is what says "control".
		secondary = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.text, stroke = theme.color.border, font = "bodyStrong",
			}
		end,
		ghost = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.textSecondary, stroke = nil, font = "body",
			}
		end,
		-- A quiet title/dropdown: no border at rest, full-strength text, hover fill. Used
		-- for the primary picker in a toolbar, where a bordered box would be one too many
		-- rectangles but the label still has to read as the loudest thing on the strip.
		soft = function()
			return {
				bg = nil, bgHover = theme.color.surfaceHover, bgPress = theme.color.surfaceActive,
				text = theme.color.text, stroke = nil, font = "bodyStrong",
			}
		end,
		-- Code actions follow the selected code palette, including its light surface.
		code = function()
			return {
				bg = nil,
				bgHover = theme.mix(theme.color.codeSurface, theme.color.codeText, 0.08),
				bgPress = theme.mix(theme.color.codeSurface, theme.color.codeText, 0.14),
				text = theme.color.codeGutter, textHover = theme.color.codeText,
				textPress = theme.color.codeText, focus = theme.color.codeText,
				stroke = nil, font = "small",
			}
		end,
		-- Text and outline only until it is pressed. A pre-filled danger button reads
		-- as already-dangerous and gets clicked past; the fill arriving on hover is the
		-- moment it is worth noticing.
		danger = function()
			return {
				bg = nil, bgHover = theme.color.dangerSurface, bgPress = theme.color.danger,
				text = theme.color.danger, textHover = theme.color.danger, textPress = theme.color.onSolid,
				stroke = theme.color.dangerBorder, font = "bodyStrong",
			}
		end,
	}

	local HEIGHTS = { sm = "controlSmall", md = "control", lg = "controlLarge" }

	-- One button implementation with a full state set: rest, hover, press, focus,
	-- disabled and loading. Roblox gives none of that, and a project that hand-rolls
	-- it per call site ends up with buttons that behave differently from each other.
	function P.button(parent, props)
		props = props or {}
		local variant = (VARIANTS[props.variant or "secondary"] or VARIANTS.secondary)()
		local height = math.max(theme.size[HEIGHTS[props.size or "md"]], responsive.minTarget())
		-- A button with neither a fixed width nor fill sizes to its label. That means
		-- the content row has to size to its own children too: AutomaticSize ignores
		-- a child whose width is a scale, so a (1, 0) row inside an auto-width button
		-- collapses the button to nothing.
		local autoWidth = not props.width and not props.fill

		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Button",
			size = props.width and UDim2.new(0, props.width, 0, height)
				or (props.fill and UDim2.new(1, 0, 0, height) or UDim2.new(0, 0, 0, height)),
			auto = autoWidth and "X" or nil,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			-- `fillColor` is an explicit resting fill for a variant that normally has
			-- none -- a floating control (the transcript's jump-to-latest pill) has to
			-- read as a solid button over content rather than as transparent text laid
			-- on the reply beneath it. Recomputed in paint so setVariant still tracks
			-- the live variant for callers that do not pass one.
			bg = props.fillColor or variant.bg,
			radius = props.radius or theme.radius.md,
			zIndex = props.zIndex,
		})
		local outline = P.stroke(button, variant.stroke or theme.color.accent)
		outline.Transparency = variant.stroke and 0 or 1
		if not (props.fillColor or variant.bg) then button.BackgroundTransparency = 1 end

		local content, layout = P.row(button, {
			name = "Content",
			size = autoWidth and UDim2.new(0, 0, 1, 0) or UDim2.new(1, 0, 1, 0),
			auto = autoWidth and "X" or nil,
			gap = theme.space.xs,
			alignX = props.align or "Center",
			alignY = "Center",
			-- `padX` for the caller that has to line this button's label up with something
			-- outside it: a full-width ghost row under a block of code has to start where
			-- the code starts, and the default is the button's own inset, not that block's.
			padding = { x = props.padX or (props.tight and theme.space.xs or theme.space.md) },
		})
		layout.SortOrder = Enum.SortOrder.LayoutOrder

		local icons = env.require("ui/icons")
		local iconHolder
		local iconTint = props.iconColor
		if props.icon then
			iconHolder = P.frame(content, {
				name = "IconSlot",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 1,
			})
			icons.draw(props.icon, iconHolder, theme.size.icon, iconTint or variant.text, props.iconDirection)
		end

		local label
		if props.text and props.text ~= "" then
			-- Keep icon and text together at their natural width. Fill stretches the
			-- label alone, pinning the icon to the edge even in a centred button.
			-- Shrink still lets bounded buttons truncate when the pair cannot fit.
			label = P.text(content, {
				text = props.text,
				role = props.role or (props.size == "sm" and "small" or variant.font),
				color = variant.text,
				align = props.align or "Center",
				auto = autoWidth and "XY" or "X",
				size = not autoWidth and UDim2.new(0, 0, 1, 0) or nil,
				flex = not autoWidth and (props.trailing and "Fill" or "Shrink") or nil,
				truncate = not autoWidth,
				layoutOrder = 2,
			})
			if autoWidth then label.Size = UDim2.fromOffset(0, 0) end
		end

		-- A trailing glyph pinned to the button's right edge -- the chevron that marks a
		-- control as a dropdown. The label above takes Fill so this sits flush right.
		local trailingHolder
		if props.trailing then
			trailingHolder = P.frame(content, {
				name = "TrailingSlot",
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 3,
			})
			icons.draw(props.trailing, trailingHolder, theme.size.icon, props.trailingColor or iconTint or variant.text, props.trailingDirection)
		end

		local handle = { instance = button, label = label, enabled = props.enabled ~= false, busy = false }
		local hovered, focused, pressed = false, false, false
		local iconParts = {}
		local function collectIconParts()
			iconParts = {}
			local holders = {}
			if iconHolder then holders[#holders + 1] = iconHolder end
			if trailingHolder then holders[#holders + 1] = trailingHolder end
			for _, holder in ipairs(holders) do
				for _, child in ipairs(holder:GetDescendants()) do
					if child:IsA("ImageLabel") then
						iconParts[#iconParts + 1] = { instance = child, property = "ImageColor3" }
					elseif child:IsA("UIStroke") then
						iconParts[#iconParts + 1] = { instance = child, property = "Color" }
					elseif child:IsA("Frame") and child.BackgroundTransparency < 1 then
						iconParts[#iconParts + 1] = { instance = child, property = "BackgroundColor3" }
					end
				end
			end
		end
		collectIconParts()

		local function paint()
			local restBg = props.fillColor or variant.bg
			local target = restBg
			local textColour = variant.text
			local active = handle.enabled and not handle.busy
			local motion = pressed and "press" or "hover"
			if not handle.enabled then
				target = restBg and theme.color.surfaceRaised or nil
				textColour = theme.color.textDisabled
			elseif active and pressed then
				target = variant.bgPress or variant.bgHover or restBg
				textColour = variant.textPress or variant.textHover or variant.text
			elseif active and (hovered or focused) then
				target = variant.bgHover or restBg
				textColour = variant.textHover or variant.text
			end
			P.animate(button, motion, {
				BackgroundColor3 = target or variant.bgHover or theme.color.surfaceHover,
				BackgroundTransparency = target and 0 or 1,
			})
			P.animate(outline, motion, {
				Color = focused and (variant.focus or theme.color.accent) or (variant.stroke or theme.color.border),
				Transparency = (focused or variant.stroke) and 0 or 1,
			})
			if label then P.animate(label, motion, { TextColor3 = textColour }) end
			for _, part in ipairs(iconParts) do
				P.animate(part.instance, motion, {
					[part.property] = handle.enabled and (iconTint or textColour) or theme.color.textDisabled,
				})
			end
		end

		button.MouseEnter:Connect(function() hovered = true; paint() end)
		button.MouseLeave:Connect(function() hovered = false; pressed = false; paint() end)
		button.MouseButton1Down:Connect(function() pressed = true; paint() end)
		button.MouseButton1Up:Connect(function() pressed = false; paint() end)
		button.SelectionGained:Connect(function() focused = true; paint() end)
		button.SelectionLost:Connect(function() focused = false; pressed = false; paint() end)

		button.Activated:Connect(function()
			if not handle.enabled or handle.busy then return end
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then
					env.require("runtime/log").warn("ui", "button handler failed", err)
				end
			end
		end)

		function handle.setEnabled(value)
			handle.enabled = value ~= false
			button.Active = handle.enabled and not handle.busy
			button.Selectable = handle.enabled and not handle.busy
			if not handle.enabled then focused = false; pressed = false end
			paint()
		end
		function handle.setBusy(value)
			handle.busy = value == true
			button.Active = handle.enabled and not handle.busy
			button.Selectable = handle.enabled and not handle.busy
			if handle.busy then focused, pressed = false, false end
			paint()
		end

		function handle.setText(text)
			if label then label.Text = tostring(text) end
		end

		function handle.setIcon(name, colour)
			iconTint = colour
			if not iconHolder then
				iconHolder = P.frame(content, {
					name = "IconSlot",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
			end
			for _, child in ipairs(iconHolder:GetChildren()) do child:Destroy() end
			iconHolder.Visible = name ~= nil
			if name then icons.draw(name, iconHolder, theme.size.icon, iconTint or variant.text, props.iconDirection) end
			collectIconParts()
			paint()
		end

		function handle.setVariant(name)
			variant = (VARIANTS[name] or VARIANTS.secondary)()
			if label then applyFont(label, theme.textRole(props.role or (props.size == "sm" and "small" or variant.font)), {}) end
			paint()
		end

		handle.setEnabled(handle.enabled)
		return handle
	end

	function P.iconButton(parent, props)
		props = props or {}
		local size = math.max(props.diameter or theme.size.control, responsive.minTarget())
		-- Shallow, deliberately. `util.merge` deep-copies, and a deep copy of a UDim2 or
		-- a Vector2 is a plain table with the same fields and none of the type -- so an
		-- icon button given a position lost it, silently, on the way through.
		local merged = util.copy(props)
		merged.variant = props.variant or "ghost"
		merged.text = nil
		merged.width = size
		merged.tight = true
		merged.radius = props.radius or theme.radius.md
		local handle = P.button(parent, merged)
		handle.instance.Size = UDim2.fromOffset(size, size)
		handle.instance.AutomaticSize = Enum.AutomaticSize.None
		return handle
	end

	-- A whole row that is one hit target, with the row's own layout inside it.
	--
	-- The wrong way to make a row clickable -- and the way most of the rows in the
	-- sidebar, the composer and the settings dialog were built -- is to drop a
	-- transparent full-size TextButton into the row alongside its contents. A
	-- UIListLayout does not layer its children, it lays them out: the button takes a
	-- full-width slot of its own and pushes the icon and the label it was meant to
	-- cover out past the row's right edge, where they are still drawn because nothing
	-- clips them. What that renders as is an empty pill with its contents floating
	-- beside it, and the only part that answers a click is the empty part.
	--
	-- So the button *is* the row: the layout goes inside it. Which is what P.button
	-- has always done, and what the transcript's own rows already did correctly.
	function P.rowButton(parent, props)
		props = props or {}
		local height = math.max(props.height or theme.size.rowSmall, responsive.minTarget())
		-- The content row is as tall as the button actually is, not as tall as the
		-- floored minimum.
		--
		-- A caller that states its own `size` -- every chip in the composer, every pill on
		-- the home card, both segments of the sidebar's mode switch -- takes that size for
		-- the button while the row inside it kept the floored one. A 22px chip therefore
		-- held a 28px content row, 44 on a touch device, top-anchored: the icon and label
		-- centred three pixels below the chip's own centre line and drew through its
		-- bottom border. The hit-target floor still applies to any button that did not
		-- state a size, which is the case it exists for.
		local stated = props.size and props.size.Y.Scale == 0 and props.size.Y.Offset > 0
		local contentHeight = stated and props.size.Y.Offset or height
		local button = Instance.new("TextButton", parent)
		button.Text = ""
		button.AutoButtonColor = false
		button.Active = true
		button.Selectable = true
		base(button, {
			name = props.name or "Row",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			position = props.position,
			anchor = props.anchor,
			layoutOrder = props.layoutOrder,
			zIndex = props.zIndex,
			bg = props.bg,
			radius = props.radius == nil and theme.radius.sm or props.radius,
			clip = props.clip,
			flex = props.flex,
		})
		local outline = P.stroke(button, props.strokeColor or theme.color.borderSubtle, props.strokeWidth)
		outline.Transparency = props.stroke and 0 or 1

		local inner = P.row
		if props.vertical then inner = P.column end
		local autoX = props.auto == "X" or props.auto == "XY"
		local autoY = props.auto == "Y" or props.auto == "XY"
		local row = inner(button, {
			name = "Content",
			size = UDim2.new(autoX and 0 or 1, 0, (autoX or autoY) and 0 or 1,
				(autoX and not autoY) and contentHeight or 0),
			auto = props.auto,
			gap = props.gap or theme.space.xs,
			padding = props.padding or { x = theme.space.xs },
			alignX = props.alignX,
			alignY = props.alignY or "Center",
		})

		local handle = { instance = button, row = row, selected = props.selected == true, enabled = props.enabled ~= false }
		local hovered, focused, pressed = false, false, false

		local function paint()
			local target = props.bg
			if handle.selected then target = props.bgSelected or theme.color.surfaceActive end
			if handle.enabled and (hovered or focused) and not handle.selected then target = props.bgHover or theme.color.surfaceHover end
			if handle.enabled and pressed then target = props.bgPress or theme.color.surfaceActive end
			local motion = pressed and "press" or "hover"
			P.animate(button, motion, {
				BackgroundColor3 = target or props.bgHover or theme.color.surfaceHover,
				BackgroundTransparency = target and 0 or 1,
			})
			P.animate(outline, motion, {
				Color = focused and (props.strokeFocusColor or theme.color.accent) or (props.strokeColor or theme.color.borderSubtle),
				Transparency = (focused or props.stroke) and 0 or 1,
			})
		end

		button.MouseEnter:Connect(function() hovered = true; paint() end)
		button.MouseLeave:Connect(function() hovered = false; pressed = false; paint() end)
		button.MouseButton1Down:Connect(function() pressed = true; paint() end)
		button.MouseButton1Up:Connect(function() pressed = false; paint() end)
		button.SelectionGained:Connect(function() focused = true; paint() end)
		button.SelectionLost:Connect(function() focused = false; pressed = false; paint() end)

		button.Activated:Connect(function()
			if not handle.enabled then return end
			if props.onClick then
				local ok, err = pcall(props.onClick, handle)
				if not ok then env.require("runtime/log").warn("ui", "row handler failed", err) end
			end
		end)

		function handle.setSelected(value)
			handle.selected = value == true
			paint("rest")
		end
		function handle.setEnabled(value)
			handle.enabled = value ~= false
			button.Active, button.Selectable = handle.enabled, handle.enabled
			if not handle.enabled then hovered, focused, pressed = false, false, false end
			paint()
		end

		-- The two things every one of these rows puts in itself, so a caller does not
		-- have to remember that an auto-width label needs a height and that an icon
		-- needs a square to be drawn into.
		function handle.icon(name, order, colour, size)
			local diameter = size or theme.size.icon
			local slot = P.frame(row, {
				name = "IconSlot",
				size = UDim2.fromOffset(diameter, diameter),
				layoutOrder = order or 1,
			})
			local icons = env.require("ui/icons")
			icons.draw(name, slot, diameter, colour or theme.color.textSecondary)
			return slot
		end

		function handle.label(text, order, colour, role)
			return P.text(row, {
				name = "Label",
				text = text,
				role = role or "caption",
				color = colour or theme.color.textSecondary,
				size = UDim2.new(0, 0, 0, theme.textRole(role or "caption").height),
				auto = autoX and "X" or nil,
				flex = not autoX and "Fill" or nil,
				truncate = not autoX,
				layoutOrder = order or 2,
			})
		end

		handle.setEnabled(handle.enabled)
		return handle
	end

	-- Input -----------------------------------------------------------------

	-- A text field with a real focus state. The reference client's prompt box gave
	-- no sign it had focus at all, which on a dark panel means typing into nothing;
	-- the border picking up the accent is the whole fix.
	--
	-- `bare` drops the field's own background, outline and corner so it can sit
	-- inside a container that owns them -- the composer puts the field and the send
	-- button in one bordered box, which is one control to look at rather than two.
	-- In that mode the caller paints focus itself, from onFocus and onBlur.
	function P.field(parent, props)
		props = props or {}
		local role = theme.textRole(props.role or "body")
		local multiline = props.multiline == true
		local bare = props.bare == true
		-- `height` is honoured on a single line too, not only when multiline.
		--
		-- It used to be ignored there, so a caller that wanted a composer rather than a
		-- search box got the 32px control token and had no way to say otherwise -- which
		-- is why the prompt field and the search field were the same height even though
		-- one of them is the primary surface of the app. The platform floor still
		-- applies: it is a minimum, not the value.
		local height = math.max(responsive.minTarget(), multiline
			and (props.height or theme.size.control * 2)
			or (props.height or theme.size.control))

		local shell = P.frame(parent, {
			name = props.name or "Field",
			size = props.size or UDim2.new(1, 0, 0, height),
			auto = props.auto,
			layoutOrder = props.layoutOrder,
			bg = (not bare) and (props.bg or theme.color.surfaceRaised) or nil,
			radius = (not bare) and (props.radius or theme.radius.md) or nil,
			clip = true,
			flex = props.flex,
		})
		local stroke = (not bare) and P.stroke(shell, theme.color.border) or nil

		local box = Instance.new("TextBox", shell)
		box.BackgroundTransparency = 1
		box.BorderSizePixel = 0
		box.Size = UDim2.new(1, 0, 1, 0)
		box.Text = tostring(props.text or "")
		box.PlaceholderText = tostring(props.placeholder or "")
		box.PlaceholderColor3 = theme.color.textTertiary
		box.TextColor3 = theme.color.text
		box.Font = role.font
		if role.face then pcall(function() box.FontFace = role.face end) end
		box.TextSize = role.size
		box.LineHeight = role.line
		box.ClearTextOnFocus = false
		box.TextXAlignment = Enum.TextXAlignment[props.align or "Left"]
		box.TextYAlignment = multiline and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center
		box.MultiLine = multiline
		box.TextWrapped = multiline
		box.ClipsDescendants = true
		box.Selectable = true
		local padding = P.pad(box, {
			x = props.padX or (bare and theme.space.none or theme.space.md),
			y = multiline and theme.space.sm or 0,
		})
		if multiline then
			-- Compact composers keep their native field when the keyboard opens.
			-- Let the inset yield before it clips the first line of the draft.
			local function fitPadding()
				local room = shell.AbsoluteSize.Y
				if room <= 0 then room = height end
				local inset = math.max(0, math.min(theme.space.sm, math.floor((room - role.height) / 2)))
				padding.PaddingTop = UDim.new(0, inset)
				padding.PaddingBottom = UDim.new(0, inset)
			end
			shell:GetPropertyChangedSignal("AbsoluteSize"):Connect(fitPadding)
			fitPadding()
		end

		local handle = { instance = box, shell = shell, stroke = stroke,
			enabled = props.enabled ~= false, readOnly = props.readOnly == true }

		local focused, hovered = false, false
		local function paintField()
			if not stroke then return end
			P.animate(stroke, "hover", {
				Color = focused and theme.color.accent or (hovered and theme.color.borderStrong or theme.color.border),
			})
			P.animate(shell, "hover", {
				BackgroundColor3 = focused and theme.color.surfaceOverlay or (props.bg or theme.color.surfaceRaised),
			})
		end
		shell.MouseEnter:Connect(function() hovered = true; paintField() end)
		shell.MouseLeave:Connect(function() hovered = false; paintField() end)
		box.Focused:Connect(function()
			focused = true
			paintField()
			if props.onFocus then pcall(props.onFocus, handle) end
		end)

		box.FocusLost:Connect(function(enterPressed)
			focused = false
			paintField()
			-- On a multiline box Enter inserts a newline, so submit is the caller's
			-- job there; on a single line it means "go".
			if enterPressed and not multiline and props.onSubmit then
				pcall(props.onSubmit, box.Text, handle)
			end
			if props.onBlur then pcall(props.onBlur, box.Text, handle) end
		end)

		if props.onChange then
			box:GetPropertyChangedSignal("Text"):Connect(function()
				pcall(props.onChange, box.Text, handle)
			end)
		end

		function handle.get() return box.Text end
		function handle.set(value) box.Text = tostring(value or "") end
		function handle.focus()
			if not handle.enabled then return false end
			return pcall(function() box:CaptureFocus() end)
		end
		function handle.clear() box.Text = "" end
		function handle.selectAll()
			if not handle.focus() then return false end
			box.CursorPosition, box.SelectionStart = #box.Text + 1, 1
			return true
		end
		function handle.setEnabled(value)
			handle.enabled = value ~= false
			box.TextEditable = handle.enabled and not handle.readOnly
			box.Active, box.Selectable = handle.enabled, handle.enabled
			box.TextColor3 = handle.enabled and theme.color.text or theme.color.textDisabled
			if not handle.enabled then pcall(function()
				if env.uis:GetFocusedTextBox() == box then box:ReleaseFocus() end
			end) end
		end
		function handle.setReadOnly(value)
			handle.readOnly = value == true
			handle.setEnabled(handle.enabled)
		end
		handle.setEnabled(handle.enabled)
		if multiline and props.role == "mono" and props.syntax ~= false then
			box.TextWrapped = false
			handle.syntax = env.require("ui/code/syntax").attach(box, props.language or "luau")
		end

		return handle
	end

	-- Containers -------------------------------------------------------------

	-- A group of related controls. One step above the surface it sits on plus a
	-- hairline, and nothing else -- no shadow, no heavier fill. `stroke = false`
	-- drops the outline for a card that is only there to hold padding.
	function P.card(parent, props)
		props = props or {}
		local card, layout = P.column(parent, {
			name = props.name or "Card",
			size = props.size or UDim2.new(1, 0, 0, 0),
			auto = props.auto or "Y",
			layoutOrder = props.layoutOrder,
			bg = props.bg or theme.color.surfaceRaised,
			radius = props.radius or theme.radius.lg,
			gap = props.gap or theme.space.md,
			padding = props.padding or theme.space.lg,
			clip = props.clip,
		})
		if props.stroke ~= false then
			P.stroke(card, props.strokeColor or theme.color.borderSubtle)
		end
		return card, layout
	end

	-- A small label for a fact or a status. Neutral unless it is given a tone: most
	-- of these are a model id or an auth style, and colouring those blue because
	-- "info" was the default made a row of plain facts look like a row of warnings.
	function P.badge(parent, props)
		props = props or {}
		local tone = props.tone or "neutral"
		local holder = P.row(parent, {
			name = "Badge",
			size = UDim2.fromOffset(0, math.max(theme.size.controlSmall - theme.space.xs,
				theme.text.caption.height + theme.space.hair * 2)),
			auto = "XY",
			bg = props.bg or theme.toneSurface(tone),
			radius = theme.radius.sm,
			gap = theme.space.xxs,
			padding = { x = theme.space.xs, y = theme.space.hair },
			layoutOrder = props.layoutOrder,
		})
		if props.dot then
			local dot = P.frame(holder, {
				name = "Dot",
				size = UDim2.fromOffset(theme.space.xs, theme.space.xs),
				bg = props.dotColor or theme.toneColor(tone),
				radius = theme.radius.pill,
			})
			dot.LayoutOrder = 1
		end
		local label = P.text(holder, {
			text = tostring(props.text or ""),
			role = "caption",
			color = props.color or theme.toneColor(tone),
			auto = "XY",
			layoutOrder = 2,
		})
		label.Size = UDim2.fromOffset(0, 0)
		return holder, label
	end

	-- A scroll region with the two things Roblox does not give you: a canvas that
	-- sizes itself from its contents, and edge fades so a long list reads as
	-- continuing rather than as ending at a hard line.
	function P.scroll(parent, props)
		props = props or {}
		local scroll = Instance.new("ScrollingFrame", parent)
		base(scroll, {
			name = props.name or "Scroll",
			visible = props.visible,
			zIndex = props.zIndex,
			anchor = props.anchor,
			size = props.size or UDim2.new(1, 0, 1, 0),
			position = props.position,
			layoutOrder = props.layoutOrder,
			bg = props.bg,
			-- Forwarded like every other layout prop. It was not, so a scroll region asked
			-- to fill its line kept whatever size it was given -- which for the intended
			-- `UDim2.new(0, 0, 1, 0)` is no width at all. Three call sites had already
			-- worked around it by attaching a UIFlexItem by hand afterwards.
			flex = props.flex,
			clip = true,
		})
		scroll.ScrollBarThickness = props.bar or theme.size.scrollbar
		scroll.ScrollBarImageColor3 = theme.color.border
		scroll.ScrollBarImageTransparency = theme.opacity.scrollbar
		scroll.BorderSizePixel = 0
		scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
		scroll.AutomaticCanvasSize = props.horizontal and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
		scroll.ScrollingDirection = props.horizontal and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
		scroll.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		scroll.Selectable = false
		scroll.Active = true
		if not props.horizontal then
			scroll.VerticalScrollBarInset = Enum.ScrollBarInset.ScrollBar
		end
		scroll.MouseEnter:Connect(function()
			P.animate(scroll, "hover", { ScrollBarImageTransparency = 0 })
		end)
		scroll.MouseLeave:Connect(function()
			P.animate(scroll, "hover", { ScrollBarImageTransparency = theme.opacity.scrollbar })
		end)

		local layout = Instance.new("UIListLayout", scroll)
		layout.FillDirection = props.horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
		layout.SortOrder = Enum.SortOrder.LayoutOrder
		layout.Padding = UDim.new(0, props.gap or theme.space.sm)
		if props.alignX then layout.HorizontalAlignment = Enum.HorizontalAlignment[props.alignX] end

		local padding = props.padding and P.pad(scroll, props.padding) or nil

		local handle = { instance = scroll, layout = layout }

		-- The room a fixed-height child can actually use. AbsoluteSize includes the
		-- scrollbar and padding, which makes a nested list overflow its outer canvas
		-- when callers use it as the child's height.
		function handle.viewportSize()
			local size = scroll.AbsoluteWindowSize
			if size.X <= 0 or size.Y <= 0 then size = scroll.AbsoluteSize end
			local width, height = size.X, size.Y
			if padding then
				width = width - (padding.PaddingLeft.Scale + padding.PaddingRight.Scale) * size.X
					- padding.PaddingLeft.Offset - padding.PaddingRight.Offset
				height = height - (padding.PaddingTop.Scale + padding.PaddingBottom.Scale) * size.Y
					- padding.PaddingTop.Offset - padding.PaddingBottom.Offset
			end
			return Vector2.new(math.max(0, width), math.max(0, height))
		end

		function handle.toBottom()
			if props.horizontal then
				scroll.CanvasPosition = Vector2.new(math.max(scroll.AbsoluteCanvasSize.X - scroll.AbsoluteWindowSize.X, 0), 0)
			else
				scroll.CanvasPosition = Vector2.new(0, math.max(scroll.AbsoluteCanvasSize.Y - scroll.AbsoluteWindowSize.Y, 0))
			end
		end

		function handle.atBottom(slack)
			local axis = props.horizontal and "X" or "Y"
			local visible = scroll.AbsoluteWindowSize[axis]
			local total = scroll.AbsoluteCanvasSize[axis]
			if total <= visible then return true end
			return (total - visible - scroll.CanvasPosition[axis]) <= (slack or theme.space.huge)
		end

		function handle.clear()
			for _, child in ipairs(scroll:GetChildren()) do
				if not child:IsA("UIComponent") then child:Destroy() end
			end
		end

		if props.fade and not props.horizontal then
			local fades = {}
			for _, spec in ipairs({
				{ name = "FadeTop", anchor = Vector2.new(0, 0), position = UDim2.fromScale(0, 0), rotation = 90 },
				{ name = "FadeBottom", anchor = Vector2.new(0, 1), position = UDim2.fromScale(0, 1), rotation = -90 },
			}) do
				local fade = P.frame(parent, {
					name = spec.name,
					size = UDim2.new(1, 0, 0, theme.space.xl),
					anchor = spec.anchor,
					position = spec.position,
					bg = props.fadeColor or theme.color.surface,
					zIndex = (props.zIndex or 1) + 5,
				})
				fades[spec.name] = fade
				local gradient = Instance.new("UIGradient", fade)
				gradient.Rotation = spec.rotation
				gradient.Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0),
					NumberSequenceKeypoint.new(1, 1),
				})
			end
			local function updateFades()
				fades.FadeTop.Visible = scroll.CanvasPosition.Y > theme.space.hair
				fades.FadeBottom.Visible = not handle.atBottom(theme.space.hair)
			end
			scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(updateFades)
			scroll:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(updateFades)
			scroll:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(updateFades)
			scroll.Destroying:Connect(function()
				for _, fade in pairs(fades) do fade:Destroy() end
			end)
			updateFades()
		end

		return handle
	end

	-- A small coloured dot used for provider health and busy state. Separate from
	-- badge because it is used inline in dense rows where a pill is too heavy.
	function P.statusDot(parent, props)
		props = props or {}
		return P.frame(parent, {
			name = "Status",
			size = UDim2.fromOffset(props.diameter or theme.size.dot, props.diameter or theme.size.dot),
			bg = props.color or theme.color.textTertiary,
			radius = theme.radius.pill,
			layoutOrder = props.layoutOrder,
			anchor = props.anchor,
			position = props.position,
		})
	end

	return P
end
end)()

