-- ==========================================================================
__UAI_MODULES["ui/providerkeys"] = (function()
-- A provider's named credentials and request policy, edited as one local draft.
-- The provider editor owns persistence; this surface applies only key fields.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local fsx = env.require("runtime/fsx")
	local keys = env.require("runtime/provider_keys")
	local sessions = env.require("agent/session")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")
	local overlay = env.require("ui/overlay")
	local search = env.require("runtime/search")
	local M = {}

	local function label(entry, index)
		return entry.name ~= "" and entry.name or ("API key " .. index)
	end

	local function snapshot(record)
		local names, paused = {}, {}
		for index, entry in ipairs(keys.entries(record)) do
			names[index] = entry.name
			paused[index] = entry.paused == true
		end
		-- Retain legacy separators until credentials actually change. Naming a key
		-- does not change authentication or invalidate a provider's model cache.
		return { apiKey = tostring(record.apiKey or ""), keyNames = names, keyPaused = paused,
			keyIds = util.deepCopy(record.keyIds),
			keyMode = keys.mode(record), selectedKey = keys.selected(record) }
	end

	function M.open(props)
		props = props or {}
		if config.vaultStatus().locked then return env.require("ui/credentialvault").open("unlock") end
		local record = props.record or {}
		keys.ensureIds(record)
		local draft = snapshot(record)
		draft.id = record.id
		local prompt, modal, unsubscribeUsage, unsubscribeStorage
		local function cleanup()
			for name in pairs(draft) do draft[name] = nil end
			if unsubscribeUsage then unsubscribeUsage(); unsubscribeUsage = nil end
			if unsubscribeStorage then unsubscribeStorage(); unsubscribeStorage = nil end
			if prompt and not prompt.closed then prompt.close() end
			prompt = nil
			if props.onClose then props.onClose() end
		end
		modal = overlay.modal({ title = "API keys",
			description = tostring(record.label or "Provider") .. ". Name your keys and choose how requests use them.",
			width = theme.size.modalWide, onClose = cleanup })
		if not modal then return nil end
		modal.card.Name = "APIKeyManager"
		local form = P.column(modal.content, { name = "KeyManagerContent", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", gap = theme.space.md, layoutOrder = 1 })
		local storage = P.card(form, { name = "KeyStorageNotice", padding = theme.space.md, gap = theme.space.xs, layoutOrder = 0 })
		local storageText = P.text(storage, { name = "KeyStorageSummary", text = "", role = "small", wrap = true,
			auto = "Y", layoutOrder = 1 })
		P.text(storage, { text = "Change this in Settings / Privacy. Other scripts sharing the executor can still intercept keys while they are in use.",
			role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 2 })
		if record.credentialsOmitted == true then
			P.text(storage, { name = "KeyRestorationRequired",
				text = "Saved credentials were omitted. After applying keys, open Edit connection to review custom authentication and save the full connection before sending requests.",
				role = "small", color = theme.color.warn, wrap = true, auto = "Y", layoutOrder = 3 })
		end
		local function refreshStorage()
			if modal.closed then return end
			local vault = config.vaultStatus()
			if vault.locked then modal.close(); return end
			local remember = fsx.enabled and config.get("security.rememberCredentials", true) == true
			local unverified = type(config.storageError) == "string" and config.storageError ~= ""
			storageText.Text = unverified and "Saved credential storage could not be verified. An earlier plaintext copy may remain. Keep this session open to retain your keys."
				or not fsx.enabled and "Filesystem access is unavailable. These credentials stay in this run; previously saved files cannot be checked or removed."
				or vault.enabled and "These keys and custom provider credentials are encrypted in UAI/config.json. The credential vault is unlocked for this run."
				or remember and "These keys and custom provider credentials are remembered as byte-encoded data in UAI/config.json. Other scripts can decode them; encoding is not encryption."
				or "These keys and custom provider credentials are session-only. Apply keeps them usable now; enter them again after restarting."
			storageText.TextColor3 = (unverified or (remember and not vault.enabled)) and theme.color.warn or theme.color.textSecondary
		end
		refreshStorage()
		unsubscribeStorage = config.changed:connect(function(path)
			if path == nil or path == "security" or path == "security.rememberCredentials" or path == "security.vault" then refreshStorage() end
		end)
		local routing = P.card(form, { name = "KeyRouting", padding = theme.space.md, gap = theme.space.sm, layoutOrder = 1 })
		P.text(routing, { text = "How to use your keys", role = "label", wrap = true, auto = "Y", layoutOrder = 1 })
		local modeControl, refresh
		local notice = P.text(form, { name = "KeyManagerNotice", text = "", role = "small", wrap = true,
			auto = "Y", color = theme.color.warn, layoutOrder = 2 })
		notice.Visible = false
		local function status(text)
			notice.Text = text or ""
			notice.Visible = notice.Text ~= ""
		end
		modeControl = C.segmented(routing, { name = "KeyMode", value = keys.mode(draft), layoutOrder = 2,
			options = { { value = "rotate", label = "Rotate keys" }, { value = "single", label = "Use one key" } },
			onChange = function(value)
				if modal.closed then return end
				local selected = keys.selected(draft)
				if value == "single" and keys.paused(draft, selected) then
					for index, entry in ipairs(keys.entries(draft)) do
						if not entry.paused then selected = index; break end
					end
				end
				local ok, why = keys.setMode(draft, value, value == "single" and selected or nil)
				status(ok and "" or why)
				refresh()
			end })
		local modeHelp = P.text(routing, { name = "KeyModeHelp", text = "", role = "small",
			color = theme.color.textSecondary, wrap = true, auto = "Y", layoutOrder = 3 })
		P.text(routing, { text = "Rotate keys only takes turns between existing keys. Replace keys at the provider and revoke the old ones to rotate credentials securely. Revoke immediately if a key is stolen.",
			role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 4 })
		local listHeader = P.row(form, { name = "KeyListHeader", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", wrap = true, gap = theme.space.sm, alignY = "Center", layoutOrder = 3 })
		local count = P.text(listHeader, { name = "KeyCount", text = "", role = "label",
			size = UDim2.fromOffset(0, theme.text.label.height), auto = "X", layoutOrder = 1 })
		P.spacer(listHeader, { grow = true, size = UDim2.fromOffset(0, 1), layoutOrder = 2 })
		local keyFilter, filterRows, cardRows = "", nil, {}
		P.field(form, { name = "KeyFilter", placeholder = "Search key names or active / paused...", layoutOrder = 4,
			onChange = function(text) keyFilter = text; if filterRows then filterRows() end end })
		local entries = P.column(form, { name = "APIKeyEntries", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", gap = theme.space.sm, layoutOrder = 5 })
		local noMatch = P.text(form, { name = "NoKeyMatch", text = "No matching key names. Clear the search to see all keys.", role = "small",
			wrap = true, auto = "Y", color = theme.color.textTertiary, layoutOrder = 5 })
		noMatch.Visible = false
		filterRows = function()
			local matches, visible = search.compile(keyFilter), 0
			for _, entry in ipairs(cardRows) do
				entry.card.Visible = matches(entry.name, entry.state) ~= nil
				if entry.card.Visible then visible = visible + 1 end
			end
			local summary = keys.summary(draft)
			count.Text = (visible < #cardRows and (visible .. " of ") or "") .. util.pluralise(summary.total, "key")
				.. (summary.active < summary.total and (" / " .. summary.active .. " active") or "")
			noMatch.Visible = #cardRows > 0 and visible == 0
		end
		local usageNodes = {}
		local function refreshUsage()
			if modal.closed then return end
			for index, node in pairs(usageNodes) do
				local used = sessions.keyUsage(draft, index)
				node.Text = util.formatNumber(used.requests) .. (used.requests == 1 and " request" or " requests")
					.. "\n" .. (used.estimated and "About " or "") .. util.formatNumber(used.tokensIn)
					.. " input / " .. util.formatNumber(used.tokensOut) .. " output tokens"
			end
		end
		local function locate(secret)
			for index, entry in ipairs(keys.entries(draft)) do
				if entry.key == secret then return index end
			end
		end
		local function edit(options, callback)
			if modal.closed then return end
			if prompt and not prompt.closed then prompt.close() end
			options.onConfirm = function(value)
				prompt = nil
				if modal.closed then return end
				callback(value)
			end
			prompt = overlay.prompt(options)
		end
		P.button(listHeader, { name = "AddKey", text = "Add API key", variant = "secondary", size = "sm", layoutOrder = 3,
			onClick = function()
				edit({ title = "Add API key", description = "Paste one key per line to add several. Existing keys and names stay in place.",
					placeholder = "Paste API key", multiline = true, confirmText = "Save key" }, function(value)
					local ok, why = keys.add(draft, value)
					status(ok and "" or why)
					refresh()
				end)
			end })
		P.text(form, { name = "KeyDraftHint", text = props.applyHint or "Apply changes returns these keys to provider setup. Save the provider to use them with the storage preference shown above.",
			role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 6 })
		P.text(form, { name = "KeyUsageHint", text = "Usage is recorded on this device from this update. Requests include retries; estimated tokens are marked.",
			role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y", layoutOrder = 7 })
		refresh = function()
			if modal.closed then return end
			local pool, mode, selected = keys.entries(draft), keys.mode(draft), keys.selected(draft)
			modeControl.set(mode)
			local active = 0
			for _, entry in ipairs(pool) do if not entry.paused then active = active + 1 end end
			count.Text = util.pluralise(#pool, "key") .. (active < #pool and (" / " .. active .. " active") or "")
			if mode == "single" then
				modeHelp.Text = pool[selected] and pool[selected].paused and "The selected key is paused. Resume it or choose another active key."
					or pool[selected] and ("Only " .. label(pool[selected], selected)
					.. " will be used. Other keys will not be tried.")
					or "Choose a key below, or turn on rotation. No key is selected for requests."
			else
				modeHelp.Text = #pool > 0 and active == 0 and "All keys are paused. Resume a key to send requests."
					or "New requests take turns using active keys. Paused keys stay in this pool until you resume or remove them."
			end
			usageNodes, cardRows = {}, {}
			for _, child in ipairs(entries:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			if #pool == 0 then
				local empty = P.card(entries, { name = "NoAPIKeys", padding = theme.space.md, gap = theme.space.xs })
				P.text(empty, { text = "No API keys yet", role = "label", auto = "Y", wrap = true, layoutOrder = 1 })
				P.text(empty, { text = "Add a key to get started. You can add more whenever you need them.", role = "small",
					color = theme.color.textSecondary, auto = "Y", wrap = true, layoutOrder = 2 })
			end
			for index, entry in ipairs(pool) do
				local slot, secret, name, paused = index, entry.key, entry.name, entry.paused
				local chosen = mode == "single" and selected == slot
				local card = P.card(entries, { name = "APIKey_" .. slot, padding = theme.space.md, gap = theme.space.sm,
					bg = chosen and theme.color.accentSurface or theme.color.surfaceRaised,
					strokeColor = chosen and theme.color.accent or theme.color.borderSubtle, layoutOrder = slot })
				cardRows[#cardRows + 1] = { card = card, name = label(entry, slot), state = paused and "paused" or "active" }
				local head = P.row(card, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.sm, layoutOrder = 1 })
				local identity = P.column(head, { size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill",
					gap = theme.space.xxs, layoutOrder = 1 })
				P.text(identity, { name = "APIKeyLabel_" .. slot, text = util.ellipsis(label(entry, slot), 120),
					role = "label", wrap = true, auto = "Y", layoutOrder = 1 })
				if name ~= "" or paused then
					P.text(identity, { name = "APIKeyState_" .. slot,
						text = "API key " .. slot .. (paused and " / Paused" or ""), role = "caption", color = theme.color.textTertiary,
						wrap = true, auto = "Y", layoutOrder = 2 })
				end
				P.text(head, { name = "APIKeyMask_" .. slot,
					text = #secret <= 4 and "set" or (string.rep("\226\128\162", 4) .. " " .. secret:sub(-4)),
					role = "monoSmall", color = theme.color.textSecondary, auto = "XY", size = UDim2.fromOffset(0, 0), layoutOrder = 2 })
				usageNodes[slot] = P.text(card, { name = "APIKeyUsage_" .. slot, text = "", role = "caption",
					color = theme.color.textSecondary, wrap = true, auto = "Y", layoutOrder = 2 })
				local actions = P.row(card, { name = "APIKeyActions_" .. slot, size = UDim2.new(1, 0, 0, 0),
					auto = "Y", wrap = true, gap = theme.space.xs, layoutOrder = 3 })
				local use = P.button(actions, { name = "UseKey_" .. slot, text = chosen and "Selected" or "Use this key",
					variant = "secondary", size = "sm", layoutOrder = 1, enabled = not chosen and not paused,
					onClick = function()
						if modal.closed then return end
						local position = locate(secret)
						if not position then return end
						local ok, why = keys.setMode(draft, "single", position)
						status(ok and "" or why); refresh()
					end })
				use.instance.Visible = mode == "single"
				P.button(actions, { name = "PauseKey_" .. slot, text = paused and "Resume" or "Pause",
					variant = "secondary", size = "sm", layoutOrder = 2,
					onClick = function()
						if modal.closed then return end
						local position = locate(secret)
						if not position then return end
						local ok, why = keys.setPaused(draft, position, not keys.paused(draft, position))
						status(ok and "" or why); refresh()
					end })
				P.button(actions, { name = "RenameKey_" .. slot, text = "Rename", variant = "ghost", size = "sm", layoutOrder = 3,
					onClick = function()
						edit({ title = "Name this key", description = "Choose a name you recognize. Leave blank to use its number.",
							value = name, placeholder = "API key " .. slot, confirmText = "Save name" }, function(value)
							local position = locate(secret)
							if not position then return end
							local ok, why = keys.rename(draft, position, value)
							status(ok and "" or why); refresh()
						end)
					end })
				P.button(actions, { name = "ReplaceKey_" .. slot, text = "Replace", variant = "ghost", size = "sm", layoutOrder = 4,
					onClick = function()
						edit({ title = "Replace API key", description = "Paste a replacement for " .. label(entry, slot)
							.. ". Its name and the other keys stay in place.", placeholder = "Paste replacement key", confirmText = "Save key" }, function(value)
							local position = locate(secret)
							if not position or util.trim(value) == "" then return end
							local ok, why = keys.replace(draft, position, value)
							status(ok and "" or why); refresh()
						end)
					end })
				P.button(actions, { name = "RemoveKey_" .. slot, text = "Remove", variant = "ghost", size = "sm", layoutOrder = 5,
					onClick = function()
						if modal.closed then return end
						local position = locate(secret)
						if not position then return end
						local wasSelected = keys.mode(draft) == "single" and keys.selected(draft) == position
						local ok, why = keys.remove(draft, position)
						status(ok and (wasSelected and "The selected key was removed. Rotation is on; choose another key to use just one." or "") or why)
						refresh()
					end })
			end
			refreshUsage()
			filterRows()
		end
		P.button(modal.footer, { name = "CancelKeys", text = "Cancel", variant = "ghost", size = "sm", layoutOrder = 1,
			onClick = function() modal.close() end })
		P.button(modal.footer, { name = "ApplyKeys", text = "Apply changes", variant = "primary", size = "sm", layoutOrder = 2,
			onClick = function()
				if modal.closed then return end
				local candidate = snapshot(draft)
				local valid, why = keys.validate(candidate)
				if not valid then status(why); return end
				if props.onApply then
					local ok, accepted = pcall(props.onApply, candidate)
					if modal.closed then return end
					if not ok or accepted == false then
						status("Changes could not be applied. Review the provider and try again.")
						return
					end
				end
				modal.close()
			end })
		refresh()
		unsubscribeUsage = sessions.usageChanged:connect(refreshUsage)
		return modal
	end

	return M
end
end)()

-- ==========================================================================
-- ui/quickchat
-- ==========================================================================
__UAI_MODULES["ui/quickchat"] = (function()
-- Quick chat: one keypress, one message, gone again.
--
-- The window is the place to read a conversation; this is the place to start one
-- without leaving what you were doing. It floats in the middle of the screen, takes
-- a single line, sends to the same session the Chat panel shows -- so whatever is
-- typed here appears there -- and dismisses itself. Nothing about it is a second
-- transcript.
--
-- The key is captured rather than typed into a field: a user thinks "this key", not
-- "Enum.KeyCode.Semicolon", and capturing it also sidesteps mapping characters to
-- key codes across keyboard layouts.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")
	local sessions = env.require("agent/session")

	local M = { visible = false, mounted = false }
	local visibilityGeneration = 0

	local DEFAULT_KEY = "Semicolon"

	-- The bound key as an EnumItem, or nil when the stored name no longer exists.
	function M.keyCode()
		local name = tostring(config.get("ui.quickKey", DEFAULT_KEY))
		local ok, item = pcall(function() return Enum.KeyCode[name] end)
		if ok and item then return item end
		return Enum.KeyCode.Semicolon
	end

	function M.keyName()
		return tostring(config.get("ui.quickKey", DEFAULT_KEY))
	end

	function M.setKey(keyCode)
		local name = keyCode and keyCode.Name or DEFAULT_KEY
		config.set("ui.quickKey", name)
		return name
	end

	function M.mount(layer)
		if M.mounted and M.root and M.root.Parent then return M.root end
		M.visible = false
		local mobile = responsive.isMobile()
		local pad = theme.space.md
		local gap = theme.space.sm

		M.root = P.frame(layer, {
			name = "QuickChat",
			size = UDim2.fromScale(1, 1),
			zIndex = theme.z.quick,
			visible = false,
		})
		M.root.Active = false

		-- A scrim, so the rest of the screen recedes and a click outside dismisses.
		local scrim = Instance.new("TextButton", M.root)
		scrim.Name = "QuickScrim"
		scrim.Text = ""
		scrim.AutoButtonColor = false
		scrim.BorderSizePixel = 0
		scrim.Size = UDim2.fromScale(1, 1)
		scrim.BackgroundColor3 = theme.color.scrim
		scrim.BackgroundTransparency = 1
		scrim.ZIndex = theme.z.quick
		M.scrim = scrim
		scrim.Activated:Connect(function() M.hide() end)

		local card = P.group(M.root, {
			name = "QuickCard",
			size = UDim2.new(0, math.min(math.max(responsive.viewport.X * 0.5, theme.size.modal), theme.size.reading * 0.6), 0, 0),
			anchor = Vector2.new(0.5, 0.5),
			position = UDim2.fromScale(0.5, 0.42),
			bg = theme.color.surfaceRaised,
			radius = theme.radius.xl,
			clip = true,
			zIndex = theme.z.quick + 1,
		})
		card.Active = true
		card.GroupTransparency = 1
		local outline = P.stroke(card, theme.color.borderStrong)
		M.card = card
		local scroll = P.scroll(card, { name = "QuickBody", size = UDim2.fromScale(1, 1), padding = pad, gap = 0 })
		local content, contentLayout = P.column(scroll.instance, {
			name = "QuickContent", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = gap,
		})

		local head = P.row(content, {
			name = "QuickHeader",
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget())),
			gap = theme.space.sm,
			layoutOrder = 1,
		})
		local mark = P.frame(head, {
			name = "QuickBrand", size = UDim2.fromOffset(theme.size.iconLarge, theme.size.iconLarge), layoutOrder = 0,
		})
		env.require("ui/brand").draw(mark, theme.size.iconLarge)
		P.text(head, {
			text = "A thought? A task?",
			role = "heading",
			size = UDim2.new(0, 0, 0, theme.text.heading.height),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		P.iconButton(head, {
			name = "DismissQuickChat", icon = "close",
			diameter = theme.size.controlSmall, layoutOrder = 2,
			onClick = function() M.hide() end,
		})

		M.field = P.field(content, {
			name = "QuickPrompt",
			placeholder = "Tell your agent what you have in mind…",
			bare = true,
			height = math.max(theme.size.control, responsive.minTarget()),
			multiline = mobile,
			layoutOrder = 2,
			onFocus = function() P.animate(outline, "hover", { Color = theme.color.accent }) end,
			onBlur = function() P.animate(outline, "hover", { Color = theme.color.borderStrong }) end,
			onSubmit = function(text) if not mobile then M.submit(text) end end,
		})

		local footer = P.row(content, {
			name = "QuickFooter",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
			layoutOrder = 3,
		})
		M.hint = P.text(footer, {
			name = "QuickHint",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height),
			truncate = true,
			flex = "Fill",
			layoutOrder = 1,
		})
		P.iconButton(footer, {
			name = "OpenFullChat", icon = "windowMaximize", diameter = theme.size.controlSmall, layoutOrder = 2,
			onClick = function()
				if not M.visible then return end
				local text = M.field.get()
				local app = env.require("ui/app")
				app.show("chat")
				if app.chatPanel and app.chatPanel.composer then
					if text ~= "" then app.chatPanel.composer.insert(text) end
					M.field.clear()
					M.hide()
					app.chatPanel.composer.focus()
				end
			end,
		})
		P.button(footer, {
			name = "SendQuickChat", text = "Send", icon = "send",
			variant = "primary", size = "sm", layoutOrder = 3,
			onClick = function() M.submit(M.field.get()) end,
		})
		local function layoutCard()
			local bounds = responsive.usableRect(layer, theme.space.md)
			local width = math.min(bounds.width,
				math.max(responsive.viewport.X * 0.5, theme.size.modal), theme.size.reading * 0.6)
			local measured = contentLayout.AbsoluteContentSize
			-- Layout initially reports zero, including while hidden. Keep enough room
			-- for the fixed controls until the first measured pass arrives.
			local minimum = head.Size.Y.Offset + M.field.shell.Size.Y.Offset + gap
				+ math.max(theme.size.controlSmall, responsive.minTarget()) + gap
			local wanted = math.max(minimum, measured and measured.Y or 0)
			local height = math.max(1, math.min(bounds.height, wanted + pad * 2))
			card.Size = UDim2.fromOffset(math.max(math.floor(width), 1), math.floor(height))
			local half = height / 2
			local y = util.clamp(bounds.height * 0.42, math.min(half, bounds.height / 2), math.max(bounds.height / 2, bounds.height - half))
			card.Position = UDim2.fromOffset(math.floor(bounds.x + bounds.width / 2), math.floor(bounds.y + y))
		end
		M.layout = layoutCard
		contentLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(layoutCard)
		layoutCard()
		local unsubscribe = dispose.add(responsive.changed:connect(layoutCard), "quick chat layout")
		local root = M.root
		root.Destroying:Connect(function()
			unsubscribe()
			if M.root == root then M.mounted = false; M.visible = false end
		end)
		local function rebuild()
			if M.root ~= root or not M.mounted then return end
			local text, visible = M.field.get(), M.visible
			local cursor, selection = M.field.instance.CursorPosition, M.field.instance.SelectionStart
			root:Destroy()
			M.mount(layer)
			M.field.set(text)
			if visible then M.show({ cursor = cursor, selection = selection }) end
		end
		local queueRebuild, cancelRebuild = clock.debounce(rebuild, theme.duration("fast"))
		local stopTheme = dispose.add(theme.changed:connect(queueRebuild), "quick chat theme")
		local stopMode = dispose.add(responsive.modeChanged:connect(function()
			-- Rotation changes the bounds, not the mobile input. Keeping the native
			-- TextBox preserves selection, composition and the open keyboard.
			if mobile and responsive.isMobile() then return end
			queueRebuild()
		end), "quick chat mode")
		root.Destroying:Connect(function()
			cancelRebuild()
			stopTheme()
			stopMode()
		end)

		M.mounted = true
		return M.root
	end

	local function refreshHint()
		if not M.hint then return end
		local providers = env.require("provider/registry")
		local record = providers.active()
		M.hint.TextColor3 = theme.color.textTertiary
		M.hint.Visible = true
		M.hint.Text = record
			and (responsive.isMobile() and string.format("%s  ·  Tap Send to send", tostring(record.label))
				or string.format("%s  ·  Enter to send  ·  Esc to close", tostring(record.label)))
			or "No provider configured yet -- open the window and add one."
	end

	function M.show(selection)
		local vault = config.vaultStatus()
		if vault.required == true and vault.ready ~= true then return end
		if not M.mounted or M.visible then return end
		M.visible = true
		visibilityGeneration = visibilityGeneration + 1
		refreshHint()
		if M.layout then M.layout() end
		-- Retarget an in-progress exit from its current opacity. Resetting it here
		-- made rapid reopen flash and restarted a scale-driven layout on every key.
		M.root.Visible = true
		M.card.Interactable = true
		local card = M.card
		P.animate(card, "modalEnter", { GroupTransparency = 0 }, function()
			if M.visible and M.card == card then card.GroupTransparency = 0 end
		end)
		P.animate(M.scrim, "modalEnter", { BackgroundTransparency = theme.opacity.scrim })
		-- One frame late: capturing focus in the same frame the surface becomes
		-- visible is unreliable.
		local root = M.root
		local generation = visibilityGeneration
		clock.delay(theme.duration("fast"), function()
			if M.visible and M.root == root and visibilityGeneration == generation then
				M.field.focus()
				if selection then
					M.field.instance.CursorPosition = selection.cursor
					M.field.instance.SelectionStart = selection.selection
				end
			end
		end)
	end

	function M.hide()
		if not M.mounted or not M.visible then return end
		M.visible = false
		visibilityGeneration = visibilityGeneration + 1
		pcall(function() M.field.instance:ReleaseFocus() end)
		M.card.Interactable = false
		if responsive.reduceMotion then
			P.animate(M.card, "instant", { GroupTransparency = 1 })
			P.animate(M.scrim, "instant", { BackgroundTransparency = 1 })
			M.root.Visible = false
			return
		end
		P.animate(M.card, "modalExit", { GroupTransparency = 1 })
		local root = M.root
		P.animate(M.scrim, "modalExit", { BackgroundTransparency = 1 }, function()
			-- Only hide if nothing reopened it while the tween ran.
			if not M.visible and M.root == root then root.Visible = false end
		end)
	end

	function M.toggle()
		if M.visible then M.hide() else M.show() end
	end

	function M.submit(text)
		local vault = config.vaultStatus()
		if vault.required == true and vault.ready ~= true then M.hide(); return end
		if not M.mounted or not M.visible then return end
		local message = util.trim(tostring(text or ""))
		if message == "" then return end
		-- The same session the Chat panel is bound to, so the message and its reply
		-- land in the transcript rather than in a parallel conversation.
		local session = sessions.current()
		local ok, reason
		if session then ok, reason = session.send(message)
		else reason = "Open the full window to create a conversation." end
		if ok then
			M.field.clear()
			M.hide()
		else
			-- Rejection is recoverable: keep the prompt in place for a retry instead of
			-- closing and clearing it on the next open.
			if M.hint then
				M.hint.Text = tostring(reason)
				M.hint.TextColor3 = theme.color.warn
				M.hint.Visible = true
			end
			if M.visible and M.field then M.field.focus() end
		end
	end

	-- Bound once, on the service, because the point of the shortcut is that it works
	-- when nothing of this interface has focus.
	function M.bind()
		if M.bound then return end
		M.bound = true

		dispose.connection(env.uis.InputBegan:Connect(function(input, processed)
			if input.UserInputType ~= Enum.UserInputType.Keyboard then return end

			if M.visible then
				if input.KeyCode == Enum.KeyCode.Escape then M.hide() end
				return
			end

			-- `processed` means the keystroke already went somewhere -- a text box, a
			-- CoreGui field. Opening on it would fire every time the bound character is
			-- typed into the composer, which is the one thing that would make this
			-- feature intolerable.
			if processed then return end
			local focused = nil
			pcall(function() focused = env.uis:GetFocusedTextBox() end)
			if focused then return end

			if M.capture then
				local pending = M.capture
				M.capture = nil
				pending(input.KeyCode)
				return
			end

			if input.KeyCode == M.keyCode() then M.show() end
		end))

	end

	-- Settings asks for the next keypress rather than parsing a typed character.
	function M.captureNext(callback)
		M.capture = function(keyCode)
			local name = M.setKey(keyCode)
			if callback then pcall(callback, name) end
		end
	end

	function M.cancelCapture()
		M.capture = nil
	end

	return M
end
end)()

-- ==========================================================================
-- ui/responsive
-- ==========================================================================
__UAI_MODULES["ui/responsive"] = (function()
-- Responsiveness.
--
-- The reference client decided phone-or-desktop once at boot from
-- TouchEnabled-and-not-KeyboardEnabled, and baked two tables of pixel metrics off
-- that. It gets the common cases right and everything else wrong: a tablet, a
-- phone that rotates, a desktop window resized to half width, a console, a device
-- with both touch and a keyboard.
--
-- This module holds no metrics. It reports what the viewport is right now and
-- republishes when that changes, so a surface either adapts continuously (scale
-- based layout, list layouts, automatic sizing) or rebuilds itself when the layout
-- mode genuinely changes -- and the second is debounced, because a desktop window
-- drag fires viewport changes every frame.
return function(env)
	local util = env.require("runtime/util")
	local clock = env.require("runtime/clock")
	local signal = env.require("runtime/signal")
	local log = env.require("runtime/log")
	local dispose = env.require("runtime/dispose")

	local BREAKPOINTS = {
		{ name = "xs", max = 520 },
		{ name = "sm", max = 900 },
		{ name = "md", max = 1280 },
		{ name = "lg", max = 1700 },
		{ name = "xl", max = math.huge },
	}

	local M = {
		viewport = Vector2.new(1280, 720),
		breakpoint = "md",
		mode = "window",
		orientation = "landscape",
		touch = false,
		pointer = true,
		gamepad = false,
		console = false,
		reduceMotion = false,
		transparency = 1,
		keyboardHeight = 0,
		keyboardTop = nil,
		inset = Vector2.new(0, 0),
		bottomInset = 0,
		changed = signal.new("responsive"),
		modeChanged = signal.new("responsive:mode"),
		ready = false,
	}

	local function breakpointFor(width)
		for _, entry in ipairs(BREAKPOINTS) do
			if width < entry.max then return entry.name end
		end
		return "xl"
	end

	-- Layout mode is the only thing surfaces branch on, and it is derived rather
	-- than configured: a console is gamepad-first regardless of resolution, a
	-- narrow viewport is a sheet whether it is a phone or a small window, and the
	-- user can still pin it by hand in settings.
	--
	-- Orientation matters as much as width. A tablet held portrait is 834 points
	-- wide and 1112 tall; a floating window in that space is a tall thin box, while
	-- a full-height dock reads properly.
	local function modeFor(breakpoint, forced)
		if forced and forced ~= "auto" then return forced end
		if M.console then return "tv" end
		if breakpoint == "xs" then return "sheet" end
		if M.touch and not M.pointer then return "panel" end
		if breakpoint == "sm" then return "panel" end
		if M.orientation == "portrait" then return "panel" end
		return "window"
	end

	local function sample()
		local width, height = 1280, 720

		-- The camera's viewport is the honest number: a ScreenGui's AbsoluteSize is
		-- zero until it renders, and IgnoreGuiInset changes it underneath you.
		local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
		if okCamera and camera and camera.ViewportSize and camera.ViewportSize.Y > 0 then
			width, height = camera.ViewportSize.X, camera.ViewportSize.Y
		elseif M.screen and M.screen.AbsoluteSize and M.screen.AbsoluteSize.Y > 0 then
			width, height = M.screen.AbsoluteSize.X, M.screen.AbsoluteSize.Y
		end

		M.viewport = Vector2.new(width, height)
		M.orientation = (height > width) and "portrait" or "landscape"

		local okInput = pcall(function()
			M.touch = env.uis.TouchEnabled == true
			M.pointer = env.uis.MouseEnabled == true
			M.gamepad = env.uis.GamepadEnabled == true
		end)
		if not okInput then M.touch, M.pointer = false, true end
		-- Mobile GUI coordinates can differ from the camera's render resolution.
		-- Use the same measured space for breakpoints, placement and keyboard bounds.
		if M.touch and not M.pointer and M.screenFrame then
			local size = M.screenFrame.AbsoluteSize
			if size.X > 0 and size.Y > 0 then
				width, height = size.X, size.Y
				M.viewport = Vector2.new(width, height)
				M.orientation = height > width and "portrait" or "landscape"
			end
		end

		pcall(function()
			M.console = env.guisvc:IsTenFootInterface() == true
		end)
		-- Application motion is permanently enabled; older saved preferences and
		-- platform changes cannot turn off the client's owned transitions.
		M.reduceMotion = false
		pcall(function()
			local value = tonumber(env.guisvc.PreferredTransparency)
			M.transparency = value and util.clamp(value, 0, 1) or 1
		end)

		-- The topbar overlaps the top of the screen; GetGuiInset reports by how much.
		local platformBottom = 0
		pcall(function()
			local top, bottom = env.guisvc:GetGuiInset()
			if top then M.inset = Vector2.new(top.X, top.Y) end
			if bottom then platformBottom = math.max(0, bottom.Y) end
		end)

		-- Mobile chat and the jump button sit at the bottom on a touch device.
		M.bottomInset = math.max(platformBottom, M.touch and 24 or 0)

		M.keyboardHeight, M.keyboardTop = 0, nil
		pcall(function()
			if env.uis.OnScreenKeyboardVisible then
				local size = env.uis.OnScreenKeyboardSize
				M.keyboardHeight = math.max(0, math.min(height, size and size.Y or 0))
				-- A keyboard can sit above the bottom edge (floating keyboards and
				-- accessory bars). Its reported top is the actual obstruction.
				if M.touch then
					local position = env.uis.OnScreenKeyboardPosition
					if position and position.Y > 0 and size and size.Y > 0 then
						M.keyboardTop = position.Y
					end
				end
			end
		end)

		local config = env.require("runtime/config")
		local previousBreakpoint, previousMode = M.breakpoint, M.mode
		M.breakpoint = breakpointFor(width)
		M.mode = modeFor(M.breakpoint, config.get("ui.layout", "auto"))

		return previousBreakpoint ~= M.breakpoint or previousMode ~= M.mode
	end

	local generation = 0
	local revealScheduled = false
	local function queueReveal()
		if revealScheduled then return end
		revealScheduled = true
		local mine = generation
		clock.delay(0.05, function()
			if mine ~= generation then return end
			revealScheduled = false
			if M.ready then M.revealFocused() end
		end)
	end

	-- Continuous changes fire `changed`; a real mode switch also fires
	-- `modeChanged`, which is the only one that triggers a rebuild.
	local function refresh(reason)
		local wasMobile = M.isMobile()
		local switched = sample()
		switched = switched or wasMobile ~= M.isMobile()
		M.changed:fire({ reason = reason, mode = M.mode, breakpoint = M.breakpoint, viewport = M.viewport })
		if switched then
			log.debug("responsive", string.format("%s -> %s at %dx%d (%s)",
				M.breakpoint, M.mode, M.viewport.X, M.viewport.Y, tostring(reason)))
			M.modeChanged:fire({ mode = M.mode, breakpoint = M.breakpoint })
		end
		if M.isMobile() and M.keyboardHeight > 0 then
			queueReveal()
		end
	end

	local debouncedRefresh
	local releases = {}
	local cameraRelease

	function M.destroy()
		generation = generation + 1
		revealScheduled = false
		for _, release in ipairs(releases) do release() end
		releases = {}
		if cameraRelease then cameraRelease(); cameraRelease = nil end
		if M.screenFrame then M.screenFrame:Destroy(); M.screenFrame = nil end
		M.ready = false
		M.screen = nil
	end

	function M.init(screenGui)
		M.destroy()
		M.screen = screenGui
		-- Measure the coordinate space children actually occupy. ScreenGui's own
		-- origin is not a reliable stand-in for its device-safe content origin.
		local frame = Instance.new("Frame")
		frame.Name = "Viewport"
		frame.BackgroundTransparency = 1
		frame.BorderSizePixel = 0
		frame.Size = UDim2.fromScale(1, 1)
		frame.Active = false
		frame.Parent = screenGui
		M.screenFrame = frame
		sample()
		M.ready = true

		local mine = generation
		debouncedRefresh = clock.debounce(function()
			if mine == generation then refresh("viewport") end
		end, 0.12)
		local function watch(connection)
			releases[#releases + 1] = dispose.connection(connection, "responsive")
		end
		local function bindCamera()
			if cameraRelease then cameraRelease(); cameraRelease = nil end
			local okCamera, camera = pcall(function() return env.services.Workspace.CurrentCamera end)
			if okCamera and camera then
				cameraRelease = dispose.connection(camera:GetPropertyChangedSignal("ViewportSize"):Connect(debouncedRefresh), "viewport")
			end
		end

		bindCamera()
		for _, property in ipairs({ "AbsoluteSize", "AbsolutePosition" }) do
			watch(frame:GetPropertyChangedSignal(property):Connect(debouncedRefresh))
		end
		-- The camera instance itself is replaced on respawn in some games, so the
		-- workspace is watched too.
		pcall(function()
			watch(env.services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
				bindCamera()
				refresh("camera")
			end))
		end)

		-- The on-screen keyboard is not a resize: the viewport does not change, so
		-- it has to be watched separately or the composer ends up behind it.
		for _, property in ipairs({ "OnScreenKeyboardVisible", "OnScreenKeyboardSize", "OnScreenKeyboardPosition" }) do
			pcall(function()
				watch(env.uis:GetPropertyChangedSignal(property):Connect(function() refresh("keyboard") end))
			end)
		end
		pcall(function()
			watch(env.uis.TextBoxFocused:Connect(function()
				if M.isMobile() then queueReveal() end
			end))
		end)
		-- A trackpad or keyboard can be attached after mounting. Re-sample input
		-- capability changes so layout and touch targets reflect the current host.
		for _, property in ipairs({ "TouchEnabled", "MouseEnabled", "GamepadEnabled" }) do
			pcall(function()
				watch(env.uis:GetPropertyChangedSignal(property):Connect(function() refresh("input") end))
			end)
		end

		for _, property in ipairs({ "PreferredTransparency" }) do
			pcall(function()
				watch(env.guisvc:GetPropertyChangedSignal(property):Connect(function() refresh(property) end))
			end)
		end

		pcall(function()
			watch(env.uis.LastInputTypeChanged:Connect(function(inputType)
				local name = tostring(inputType and inputType.Name or "")
				local wasGamepad = M.gamepad
				if name:find("Gamepad") then M.gamepad = true end
				if wasGamepad ~= M.gamepad then refresh("input") end
			end))
		end)

		local config = env.require("runtime/config")
		releases[#releases + 1] = dispose.add(config.changed:connect(function(path)
			if path == "ui.layout" then refresh("setting") end
		end), "responsive settings")
		watch(screenGui.Destroying:Connect(function()
			if M.screen == screenGui then M.destroy() end
		end))
		releases[#releases + 1] = dispose.add(function()
			generation = generation + 1
			M.ready = false
			M.screen = nil
			M.screenFrame = nil
		end, "responsive lifetime")

		log.info("responsive", string.format("%s / %s at %dx%d, touch %s, gamepad %s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "yes" or "no", M.gamepad and "yes" or "no"))
		return M
	end

	function M.refresh(reason)
		refresh(reason or "manual")
	end

	-- The shared compact interface uses native control metrics on handhelds.
	-- Touch capability still governs gestures and keyboard behavior, not an
	-- oversized alternate presentation. Individual fields also fit their text.
	function M.minTarget()
		if M.console then return 48 end
		if M.isMobile() then return 15 end
		return M.touch and 44 or 28
	end

	function M.isNarrow()
		return M.mode == "sheet"
	end

	function M.isMobile()
		return M.touch and not M.console
			and (not M.pointer or M.mode == "sheet" or M.mode == "panel")
	end

	function M.isCompactHeight()
		return M.viewport.Y < 520 or M.keyboardHeight > 0
	end

	-- Default geometry per mode, in pixels, clamped to the viewport so the window
	-- can never open larger than the screen it is on.
	function M.geometry()
		local width, height = M.viewport.X, M.viewport.Y
		if M.isMobile() then
			local theme = env.require("ui/theme")
			local scale = theme.metricScale
			local portrait = M.orientation == "portrait"
			local minimumWidth = theme.size.sidebar + theme.size.modalMin + theme.space.xl * 2
			local automatic = env.require("runtime/config").get("ui.layout", "auto") == "auto"
			-- Auto retains the compact rectangle. Explicit modes change the same
			-- desktop surface's dimensions and placement without changing its controls.
			if not automatic and M.mode == "sheet" then
				return { width = width, height = math.floor(height * (portrait and 0.72 or 0.9)), anchored = "bottom" }
			elseif not automatic and M.mode == "panel" then
				return {
					width = math.floor(math.max(minimumWidth, util.clamp(width / scale * 0.52, 320, 460) * scale)),
					height = math.floor(height - M.inset.Y - 24 * scale),
					anchored = "right",
				}
			end
			return {
				width = math.floor(math.max(minimumWidth,
					util.clamp(width / scale * 0.44, 460, 780) * scale)),
				height = math.floor(util.clamp(height / scale * 0.68, 360, 620) * scale),
				anchored = automatic and (portrait and "bottom" or "right") or "center",
			}
		end
		if M.mode == "sheet" then
			return {
				width = width,
				height = math.floor(height * (M.orientation == "portrait" and 0.72 or 0.9)),
				anchored = "bottom",
			}
		end
		if M.mode == "panel" then
			return {
				width = math.floor(util.clamp(width * 0.52, 320, 460)),
				height = math.floor(height - M.inset.Y - 24),
				anchored = "right",
			}
		end
		if M.mode == "tv" then
			return {
				width = math.floor(util.clamp(width * 0.62, 720, 1200)),
				height = math.floor(util.clamp(height * 0.7, 420, 760)),
				anchored = "center",
			}
		end
		return {
			width = math.floor(util.clamp(width * 0.44, 460, 780)),
			height = math.floor(util.clamp(height * 0.68, 360, 620)),
			anchored = "center",
		}
	end

	-- How much of the bottom of the screen is unusable: the on-screen keyboard when
	-- it is up, otherwise the platform's own bottom furniture.
	function M.bottomObstruction()
		return math.max(M.keyboardHeight, M.bottomInset)
	end

	function M.parentGeometry(relative)
		if relative == M.screen and M.screenFrame then relative = M.screenFrame end
		local origin = relative and relative.AbsolutePosition or Vector2.new(0, 0)
		local size = relative and relative.AbsoluteSize or M.viewport
		if size.X <= 0 or size.Y <= 0 then size = M.viewport end
		return origin, size
	end

	-- Default placement avoids the top bar. Moving a surface can use the entire
	-- device-safe parent: GetGuiInset describes CoreGui's reserved band, not a
	-- physical obstruction across the whole screen. Treating it as a drag limit
	-- strands both the window and launcher far below the top on some clients.
	function M.usableRect(relative, margin, avoidTopbar)
		margin = margin or 0
		if avoidTopbar == nil and M.isMobile() then avoidTopbar = false end
		local origin, size = M.parentGeometry(relative)
		margin = math.max(0, math.min(margin, (math.min(size.X, size.Y) - 1) / 2))
		local left = (avoidTopbar == false and 0 or math.max(0, M.inset.X - origin.X)) + margin
		local top = (avoidTopbar == false and 0 or math.max(0, M.inset.Y - origin.Y)) + margin
		-- Camera.ViewportSize and GUI pixels can differ under client/display scaling.
		-- Mixing them caps movement at a fraction of the visible screen. Use the
		-- measured GUI extent for both axes, keeping the camera as a boot fallback.
		local screenOrigin, screenSize = M.parentGeometry(M.screen)
		local right = math.min(size.X, screenOrigin.X + screenSize.X - origin.X) - margin
		local bottom = math.min(size.Y, screenOrigin.Y + screenSize.Y - M.bottomObstruction() - origin.Y) - margin
		if M.isMobile() and M.keyboardTop then
			bottom = math.min(size.Y - margin, screenOrigin.Y + screenSize.Y - M.bottomInset - origin.Y - margin,
				M.keyboardTop - origin.Y - margin)
		end
		return { x = left, y = top, width = math.max(1, right - left), height = math.max(1, bottom - top) }
	end

	function M.describe()
		return string.format("%s / %s  %dx%d  %s%s%s",
			M.breakpoint, M.mode, M.viewport.X, M.viewport.Y,
			M.touch and "touch " or "",
			M.gamepad and "gamepad " or "",
			M.reduceMotion and "reduced-motion" or "")
	end

	-- Reveal one result without stealing text focus or changing other panels.
	-- A tall row aligns its beginning so the label remains visible.
	function M.reveal(target, scroll, margin)
		if not target or not scroll or not target.Parent or not scroll.Parent
			or not target:IsDescendantOf(scroll) then return false end
		local node = target
		while node and node ~= scroll do
			if node:IsA("GuiObject") and not node.Visible then return false end
			node = node.Parent
		end
		local height = scroll.AbsoluteWindowSize.Y
		if height <= 0 then height = scroll.AbsoluteSize.Y end
		if height <= 0 then return false end
		margin = math.max(0, math.min(tonumber(margin) or 0, height / 4))
		local top = target.AbsolutePosition.Y - scroll.AbsolutePosition.Y
		local bottom = top + target.AbsoluteSize.Y
		local delta = top < margin and top - margin
			or (bottom > height - margin and math.min(top - margin, bottom - height + margin) or 0)
		local maximum = math.max(0, scroll.AbsoluteCanvasSize.Y - height)
		scroll.CanvasPosition = Vector2.new(scroll.CanvasPosition.X, util.clamp(scroll.CanvasPosition.Y + delta, 0, maximum))
		return true
	end

	-- Reveal the active mobile field after the keyboard and its ancestors finish
	-- resizing. Only its scrolling ancestors move; reading another panel stays put.
	function M.revealFocused()
		if not M.isMobile() then return end
		local ok, field = pcall(function() return env.uis:GetFocusedTextBox() end)
		if not ok or not field or not field.Parent or not M.screen or not field:IsDescendantOf(M.screen) then return end
		local ancestor = field
		while ancestor and ancestor ~= M.screen do
			if ancestor:IsA("GuiObject") and not ancestor.Visible then return end
			ancestor = ancestor.Parent
		end
		local bounds = M.usableRect(M.screen, 0, false)
		local origin = M.parentGeometry(M.screen)
		local safeTop, safeBottom = origin.Y + bounds.y, origin.Y + bounds.y + bounds.height
		-- Track the requested movement ourselves: AbsolutePosition can be updated
		-- one layout pass later, causing an outer scroller to repeat the inner move.
		local y, height = field.AbsolutePosition.Y, field.AbsoluteSize.Y
		local node = field.Parent
		while node and node ~= M.screen do
			if node:IsA("ScrollingFrame") and node.ScrollingEnabled
				and node.ScrollingDirection ~= Enum.ScrollingDirection.X then
				local visible = node.AbsoluteWindowSize.Y
				if visible <= 0 then visible = node.AbsoluteSize.Y end
				local top, bottom = node.AbsolutePosition.Y, node.AbsolutePosition.Y + visible
				if math.min(safeBottom, bottom) > math.max(safeTop, top) then
					top, bottom = math.max(safeTop, top), math.min(safeBottom, bottom)
				end
				ancestor = node.Parent
				while ancestor and ancestor ~= M.screen do
					if ancestor:IsA("GuiObject") and ancestor.ClipsDescendants then
						local clipHeight = ancestor:IsA("ScrollingFrame") and ancestor.AbsoluteWindowSize.Y or 0
						if clipHeight <= 0 then clipHeight = ancestor.AbsoluteSize.Y end
						local clipTop = math.max(top, ancestor.AbsolutePosition.Y)
						local clipBottom = math.min(bottom, ancestor.AbsolutePosition.Y + clipHeight)
						-- An entirely offscreen inner scroller first reveals its own field;
						-- the outer scroller can then bring that region into view.
						if clipBottom > clipTop then top, bottom = clipTop, clipBottom end
					end
					ancestor = ancestor.Parent
				end
				if visible > 0 and bottom > top then
					local margin = math.min(M.minTarget() / 4, math.max(0, (bottom - top - math.min(height, M.minTarget())) / 2))
					top, bottom = top + margin, bottom - margin
					local delta = y < top and y - top or (y + height > bottom and math.min(y - top, y + height - bottom) or 0)
					local maximum = math.max(0, node.AbsoluteCanvasSize.Y - visible)
					local previous = node.CanvasPosition.Y
					local nextY = util.clamp(previous + delta, 0, maximum)
					if nextY ~= previous then
						node.CanvasPosition = Vector2.new(node.CanvasPosition.X, nextY)
						y = y - (nextY - previous)
					end
				end
			end
			node = node.Parent
		end
	end

	return M
end
end)()

