			if path == nil or path == "security" or path == "security.vault" then refreshStorage() end
		end)
		storage.Destroying:Connect(unsubscribeStorage)

		local vaultSection = build.section("Master-password vault",
			"Encrypted storage requires unlocking each run. There is no password recovery: forgotten-password reset removes saved vault credentials. You can also choose unprotected storage after unlocking.")
		local vaultStatus = R.paragraph(vaultSection, "", { name = "CredentialVaultStatus", layoutOrder = 1 })
		local vaultButton = P.button(vaultSection, { name = "ManageCredentialVault", text = "Set master password", fill = true, layoutOrder = 2,
			onClick = function() env.require("ui/credentialvault").open() end })
		local function refreshVault()
			if not vaultSection.Parent then return end
			local vault = config.vaultStatus()
			vaultStatus.Text = vault.busy and "A vault operation is in progress."
				or vault.error or (vault.enabled and (vault.locked and "Locked. Your encrypted credentials need your master password."
					or "Unlocked for this run. Lock the vault or change the master password below.")
				or vault.protection == "unprotected" and "Unprotected storage is active. Set a master password to encrypt your saved credentials."
				or "Choose password protection or continue without encryption before using UAI.")
			vaultStatus.TextColor3 = (vault.error or vault.protection == "unprotected") and theme.color.warn or theme.color.textSecondary
			vaultButton.setText(vault.enabled and (vault.locked and "Unlock credential vault" or "Manage credential vault") or "Set master password")
			vaultButton.setEnabled(not vault.busy)
		end
		refreshVault()
		local unsubscribeVault = config.changed:connect(function(path)
			if path == nil or path == "security" or path == "security.vault" then refreshVault() end
		end)
		vaultSection.Destroying:Connect(unsubscribeVault)

		local secrets = build.section("Logs and exports",
			"Request logs mask recognised credentials. Configuration and diagnostic exports exclude credential fields by default. "
			.. "Only the explicitly labelled private configuration copy includes credentials; keep it private.")
		R.toggle(secrets, {
			label = "Mirror the log to the console",
			hint = "Also print every entry with print/warn, which a developer console can read.",
			path = "logs.mirror",
			onChange = function(value) log.mirror = value == true end,
		})
		P.text(secrets, { text = "Level", role = "small" })
		C.segmented(secrets, {
			options = {
				{ value = "debug", label = "Debug" },
				{ value = "info", label = "Info" },
				{ value = "warn", label = "Warn" },
				{ value = "error", label = "Error" },
			},
			value = config.get("logs.level", "info"),
			onChange = function(value)
				config.set("logs.level", value)
				log.setLevel(value)
			end,
		})

		local clear = build.section("Clear what is stored",
			"Each of these is immediate and cannot be undone.")
		R.actions(clear, {
			{
				name = "ClearRequests",
				text = "Request history",
				variant = "ghost",
				onClick = function()
					http.clearHistory()
					overlay.toast("Request history cleared", "good", 2)
				end,
			},
			{
				name = "ClearLog",
				text = "Log",
				variant = "ghost",
				onClick = function()
					log.clear()
					overlay.toast("Log cleared", "good", 2)
				end,
			},
			{
				name = "ClearConversations",
				text = "All conversations",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Delete every conversation?",
						description = "Every transcript on disk is removed. The activity counters are kept.",
						confirmText = "Delete",
						danger = true,
						onConfirm = function()
							for _, session in ipairs(sessions.list()) do
								sessions.remove(session.id)
							end
							overlay.toast("Conversations deleted", "good", 2)
						end,
					})
				end,
			},
			{
				name = "ClearActivity",
				text = "Activity history",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Reset the activity history?",
						description = "Every day, model and token count this client has recorded is discarded. "
							.. "The conversations themselves are kept.",
						confirmText = "Reset",
						danger = true,
						onConfirm = function()
							stats.reset()
							overlay.toast("Activity history reset", "good", 2)
						end,
					})
				end,
			},
		})
	end

	-- Usage -------------------------------------------------------------------

	local function paneUsage(container)
		local build = builder(container)

		local live = build.section("This session",
			"What the client has spent since it started, as the provider reported it.")
		local liveText = P.text(live, {
			name = "UsageLine",
			text = usage.line(),
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		liveText.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = usage.changed:connect(function()
			if not liveText.Parent then return end
			liveText.Text = usage.line()
		end)
		liveText.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(live, { {
			name = "ResetCounters",
			text = "Reset counters",
			variant = "ghost",
			onClick = function() usage.reset() end,
		} })

		local window = stats.window("all")
		local totals = build.section("Everything recorded",
			"Counted from what this client observed and kept on disk, so it survives a restart.")
		local facts = {
			{ key = "Conversations", value = util.formatNumber(window.sessions) },
			{ key = "Messages", value = util.formatNumber(window.messages) },
			{ key = "Requests", value = util.formatNumber(window.requests) },
			{ key = "Tokens in", value = util.formatNumber(window.tokensIn) },
			{ key = "Tokens out", value = util.formatNumber(window.tokensOut) },
			{ key = "Tool calls", value = util.formatNumber(window.toolCalls) },
			{ key = "Active days", value = util.formatNumber(window.activeDays) },
		}
		local cost = usage.formatCost(window.cost)
		if cost ~= "" then
			facts[#facts + 1] = { key = "Known cost estimate", value = cost }
		end
		if window.tokensFrom then
			facts[#facts + 1] = { key = "Tokens since", value = clock.describeDay(clock.dayKey(window.tokensFrom)) }
		end
		R.facts(totals, facts, { name = "Totals" })
		if not window.tokensFrom then
			R.paragraph(totals,
				"No request has been recorded yet, so there are no token counts. Messages and "
				.. "conversations from before counting began were read back out of the transcripts "
				.. "already on disk; tokens could not be, because nothing recorded them.")
		end

		if #window.models > 0 then
			local models = build.section("By model", "Which model spent what.")
			for index, row in ipairs(window.models) do
				C.keyValue(models, {
					key = row.id,
					value = string.format("%s tokens  %s  %d%%",
						util.formatCompact(row.tokens), util.pluralise(row.requests, "request"),
						math.floor((row.share or 0) * 100 + 0.5)),
					layoutOrder = index,
				})
			end
		end

		local tools = stats.topTools(8)
		if #tools > 0 then
			local toolCard = build.section("Most used tools", "Across every conversation.")
			for index, entry in ipairs(tools) do
				C.keyValue(toolCard, {
					key = entry.name,
					value = util.formatNumber(entry.count),
					layoutOrder = index,
				})
			end
		end
	end

	-- Claude Code -------------------------------------------------------------

	-- A live sample of one code palette, drawn in that palette's own colours rather
	-- than the active one -- which is what lets both be shown side by side and picked
	-- by pressing the one you want, the way the reference client does it.
	local function codePreview(parent, name, order, onPick)
		local palette = theme.CODE_THEMES[name] or theme.CODE_THEMES.dark
		local selected = theme.codeThemeName == name
		local lineHeight = theme.text.monoSmall.height + theme.space.hair
		-- Four sample lines, a bar, and the two hair-thin paddings around them. Stated
		-- once and passed as the card's own size: P.rowButton takes `size` when it is
		-- given one and ignores `height` unless the button is auto-sizing, so passing
		-- both -- with a zero height in the size -- gave the card no height at all and
		-- spilled a hundred pixels of preview over the control below it.
		local cardHeight = lineHeight * 4 + theme.size.rowTight + theme.space.hair * 2
		local card = P.rowButton(parent, {
			name = "CodePreview_" .. name,
			vertical = true,
			size = UDim2.new(0.5, -theme.space.sm, 0, cardHeight),
			height = cardHeight,
			bg = palette.surface,
			radius = theme.radius.md,
			gap = 0,
			padding = theme.space.hair,
			alignY = "Top",
			clip = true,
			stroke = true,
			strokeColor = selected and theme.color.accent or palette.border,
			bgHover = palette.surface,
			bgPress = palette.surface,
			bgSelected = palette.surface,
			selected = selected,
			layoutOrder = order,
			onClick = function()
				config.set("ui.codeTheme", name)
				if onPick then pcall(onPick, name) end
			end,
		})

		local head = P.row(card.row, {
			name = "PreviewBar",
			size = UDim2.new(1, 0, 0, theme.size.rowTight),
			bg = palette.bar,
			padding = { x = theme.space.xs },
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		P.text(head, {
			text = palette.label,
			role = "caption",
			color = palette.gutter,
			size = UDim2.new(0, 0, 1, 0),
			flex = "Fill",
			truncate = true,
			layoutOrder = 1,
		})
		if selected then
			local mark = P.frame(head, {
				size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
				layoutOrder = 2,
			})
			icons.check(mark, theme.size.icon, theme.color.accent)
		end

		local lines = {
			{ number = 1, prefix = " ", text = "local function greet(name)" },
			{ number = 2, prefix = "-", text = 'return "Hello, " .. name', tone = "remove" },
			{ number = 2, prefix = "+", text = 'return string.format("Hi %s!", name)', tone = "add" },
			{ number = 3, prefix = " ", text = "end" },
		}
		for index, line in ipairs(lines) do
			local fill, ink = nil, palette.text
			if line.tone == "add" then
				fill, ink = palette.addSurface, palette.addText
			elseif line.tone == "remove" then
				fill, ink = palette.removeSurface, palette.removeText
			end
			local row = P.row(card.row, {
				name = "Line" .. tostring(index),
				size = UDim2.new(1, 0, 0, lineHeight),
				bg = fill,
				gap = theme.space.xs,
				padding = { x = theme.space.xs },
				layoutOrder = index + 1,
			})
			P.text(row, {
				text = tostring(line.number),
				role = "monoSmall",
				color = palette.gutter,
				align = "Right",
				size = UDim2.fromOffset(theme.space.md, theme.text.monoSmall.height),
				layoutOrder = 1,
			})
			P.text(row, {
				text = line.prefix,
				role = "monoSmall",
				color = ink,
				size = UDim2.fromOffset(theme.space.sm, theme.text.monoSmall.height),
				layoutOrder = 2,
			})
			P.text(row, {
				text = line.text,
				role = "monoSmall",
				color = ink,
				size = UDim2.new(0, 0, 0, theme.text.monoSmall.height),
				flex = "Fill",
				truncate = true,
				layoutOrder = 3,
			})
		end
		return card
	end

	local function paneClaudeCode(container)
		local build = builder(container)

		local appearance = build.section("Code appearance",
			"How a fenced code block is drawn, in the transcript and everywhere else. "
			.. "Press one to use it.")
		local row = P.row(appearance, {
			name = "CodeThemes",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
			alignY = "Top",
		})
		for index, key in ipairs(theme.CODE_THEME_ORDER) do
			codePreview(row, key, index)
		end

		local fontOptions = {}
		for _, key in ipairs(theme.CODE_ORDER) do
			fontOptions[#fontOptions + 1] = { value = key, label = theme.CODE_FONTS[key].label }
		end
		R.segmented(appearance, {
			name = "CodeFont",
			label = "Code font",
			hint = "Monospace fonts available on this device. Used for code and diagnostic details.",
			path = "ui.codeFont",
			options = fontOptions,
		})

		local interface = build.section("Appearance",
			"The type the interface itself is set in.")
		local interfaceOptions = {}
		for _, key in ipairs(theme.INTERFACE_ORDER) do
			interfaceOptions[#interfaceOptions + 1] = { value = key, label = theme.INTERFACE_FONTS[key].label }
		end
		R.select(interface, {
			name = "InterfaceFont",
			label = "Interface font",
			hint = "The font for menus, navigation and messages. Shows the families available on this device.",
			path = "ui.interfaceFont",
			options = interfaceOptions,
		})
		-- What is being rendered, as opposed to what is selected. Two clients can resolve
		-- the same setting differently: the weight axis needs the modern type stack, and
		-- without it every "medium" role falls back to whichever legacy member pairs that
		-- family with a heavier weight. Saying so is cheaper than someone wondering why
		-- their headings look the same as their body text.
		R.paragraph(interface, string.format("Now: %s, %s.",
			theme.interfaceFontName,
			theme.hasFontFace and "with the regular/medium/semibold weight axis"
				or "weights from the legacy font set on this client"))

		-- Text size is the same setting as the scale slider under General, expressed the
		-- way the reference client expresses it. One value, two controls: the segmented
		-- one reads the scale back rather than keeping a second copy of it.
		local scale = tonumber(config.get("ui.fontScale", 1)) or 1
		local currentSize = "medium"
		if scale < 0.95 then currentSize = "small" end
		if scale > 1.08 then currentSize = "large" end
		R.segmented(interface, {
			name = "TranscriptSize",
			label = "Transcript text size",
			hint = "The same value as the text scale under General.",
			value = currentSize,
			options = {
				{ value = "small", label = "Small" },
				{ value = "medium", label = "Medium" },
				{ value = "large", label = "Large" },
			},
			onChange = function(value)
				local scales = { small = 0.9, medium = 1, large = 1.15 }
				config.set("ui.fontScale", scales[value] or 1)
			end,
		})

		R.segmented(interface, {
			name = "TranscriptWidth",
			label = "Transcript width",
			hint = "The widest the transcript and the composer will grow on a large screen.",
			path = "ui.transcriptWidth",
			options = {
				{ value = "narrow", label = "Narrow" },
				{ value = "medium", label = "Medium" },
				{ value = "wide", label = "Wide" },
			},
		})
	end

	-- Cowork ------------------------------------------------------------------

	local function paneCowork(container)
		local build = builder(container)
		build.section("Cowork",
			"A browser on this machine can join the conversation that is open here. Both sides "
			.. "dial out to a small local process, because a Roblox client cannot accept a "
			.. "connection.")
		env.require("ui/panels/cowork").rows(container, { layoutOrder = build.order() })
		build.order()
	end

	-- Import and export -------------------------------------------------------

	local EXPORT_DIR = "export"

	-- What an export contains, and what it deliberately does not.
	local function exportPayload()
		local settings = credentials.sanitise(config.data)
		return {
			exportedAt = clock.ms(),
			version = env.info and env.info.version or "",
			place = place.facts(),
			settings = settings,
			activity = stats.data,
		}
	end

	local function fullConfigImport()
		local modal = overlay.modal({
			title = "Import configuration",
			description = "Paste a configuration copy and review it before replacing your settings. Private copies can contain credentials.",
			width = theme.size.modalWide,
			height = theme.size.dialogTall,
			scroll = true,
		})
		if not modal then return end
		local candidate, applyButton, passwordModal
		local sourceRevision = 0
		modal.scrim.Destroying:Connect(function()
			candidate = nil
			if passwordModal and not passwordModal.closed then passwordModal.close() end
		end)
		local status = P.text(modal.content, {
			name = "ConfigImportStatus",
			text = "Paste your JSON below, then select Review.",
			role = "small",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
			layoutOrder = 1,
		})
		local field = P.field(modal.content, {
			name = "ConfigImportJSON",
			placeholder = '{"format":"project-uai-config","version":1,...}',
			role = "monoSmall",
			multiline = true,
			height = theme.text.monoSmall.height * 8 + theme.space.md * 2,
			layoutOrder = 2,
			onChange = function()
				sourceRevision = sourceRevision + 1
				candidate = nil
				if passwordModal and not passwordModal.closed then passwordModal.close() end
				if applyButton then applyButton.setEnabled(false) end
				status.Text = "Select Review to validate this configuration."
				status.TextColor3 = theme.color.textSecondary
			end,
		})
		P.text(modal.content, {
			text = "Applying replaces providers, credentials, permissions and preferences. Copies that exclude credentials require you to enter them again. This device keeps its storage choice and any vault password. Conversations, activity history, workspace files and skill files stay on this device.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = 3,
		})
		P.button(modal.footer, {
			text = "Cancel", variant = "ghost", size = "sm", layoutOrder = 1,
			onClick = function() modal.close() end,
		})
		local function displayPreview(preview, err)
			if modal.closed then return end
			candidate = preview
			applyButton.setEnabled(preview ~= nil)
			if not preview then
				status.Text = tostring(err)
				status.TextColor3 = theme.color.warn
				return
			end
			local summary = preview.summary
			status.Text = string.format("Ready to import\n%s · %s\nActive provider: %s\nPermission mode: %s · %s\n%s · Bridge %s",
				util.pluralise(summary.providers, "provider"), util.pluralise(summary.keys, "API key"),
				util.ellipsis(summary.active, 64), permissions.MODE_LABELS[summary.permissionMode] or summary.permissionMode,
				util.pluralise(summary.rules, "rule"), util.pluralise(summary.memory, "memory entry"),
				summary.bridgeEnabled and "enabled" or "disabled")
			status.Text = status.Text .. (summary.credentialsIncluded == false
				and "\nCredentials excluded: enter your credentials again after import."
				or "\nThis copy can include private credentials.")
			status.Text = status.Text .. (config.vaultStatus().enabled
				and "\nThis device keeps its own master-password vault."
				or summary.rememberCredentials == true and "\nThis device remembers provider credentials using reversible byte encoding."
				or "\nProvider credentials will stay in this run only.")
			status.TextColor3 = theme.color.text
		end
		P.button(modal.footer, {
			name = "ReviewConfigImport", text = "Review", size = "sm", layoutOrder = 2,
			onClick = function()
				if passwordModal and not passwordModal.closed then return end
				local source, revision = field.get(), sourceRevision
				local preview, err, reason = configTransfer.preview(source)
				if reason == "password" then
					candidate = nil; applyButton.setEnabled(false)
					status.Text, status.TextColor3 = "Enter the source master password to review this encrypted copy.", theme.color.textSecondary
					passwordModal = env.require("ui/credentialvault").open("import", {
						cancelled = function() return modal.closed or sourceRevision ~= revision end,
						submit = function(password, options)
							local unlocked, why = configTransfer.preview(source, { password = password, progress = options.progress, cancelled = options.cancelled })
							return unlocked ~= nil, unlocked or why
						end,
						onSuccess = function(unlocked) if not modal.closed and sourceRevision == revision then displayPreview(unlocked) end end,
					})
				else
					displayPreview(preview, err)
				end
			end,
		})
		applyButton = P.button(modal.footer, {
			name = "ApplyConfigImport", text = "Apply", variant = "primary", size = "sm", layoutOrder = 3,
			enabled = false,
			onClick = function()
				if not candidate then return end
				local ok, persisted = configTransfer.apply(candidate)
				if not ok then
					status.Text = tostring(persisted)
					status.TextColor3 = theme.color.warn
					return
				end
				log.setLevel(config.get("logs.level", "info"))
				log.mirror = config.get("logs.mirror", false) == true
				providers.changed:fire("import")
				permissions.changed:fire("import")
				state.memoryChanged:fire(config.get("memory.entries", {}))
				env.require("runtime/skills").changed:fire(nil, nil)
				modal.close(true)
				-- The Settings dialog survives app rebuilds, so close its stale controls.
				for index = #overlay.open, 1, -1 do
					local entry = overlay.open[index]
					if entry.card and entry.card.Name == "SettingsDialog" then entry.close() end
				end
				overlay.toast(persisted and "Configuration imported with this device's credential storage preference"
					or "Configuration imported for this session", "good", 4)
			end,
		})
		clock.delay(theme.duration("fast"), function()
			if not modal.closed then field.focus() end
		end)
	end

	local function paneImportExport(container)
		local build = builder(container)

		local transfer = build.section("Configuration transfer",
			"Copy provider records, permissions and preferences to another device. The default copy excludes credential fields, custom headers, query parameters and body overrides. Enter those again after import.")
		R.paragraph(transfer,
			"Saved memory and skill preferences are included. Review other text before sharing it. Conversations, activity history, workspace files and skill files are not included.")
		local copyButton = P.button(transfer, {
			name = "CopyFullConfig",
			text = "Copy config without credentials",
			variant = "secondary",
			fill = true,
			enabled = caps.clipboard,
			onClick = function()
				local copied, err = configTransfer.copyToClipboard(caps.fn.clipboard)
				overlay.toast(copied and "Configuration copied with credential fields excluded" or tostring(err), copied and "good" or "warn", 4)
			end,
		})
		copyButton.setEnabled(caps.clipboard)
		local privateCopyButton = P.button(transfer, {
			name = "CopyPrivateConfig", text = "Copy private config including credentials", variant = "ghost", fill = true,
			enabled = caps.clipboard,
			onClick = function()
				local copied, err = configTransfer.copyToClipboard(caps.fn.clipboard, { includeCredentials = true })
				local message = config.vaultStatus().enabled and "Private configuration copied with encrypted provider credentials. Import requires its master password. Other settings and connection tokens remain readable; keep it private."
					or "Private configuration copied with recoverable provider credentials and connection tokens. Do not share it."
				overlay.toast(copied and message
					or tostring(err), copied and "good" or "warn", 5)
			end,
		})
		privateCopyButton.setEnabled(caps.clipboard)
		R.paragraph(transfer,
			"Private copies retain your storage mode. Encrypted copies require the source vault's password; unprotected copies contain recoverable credentials. Other settings and bridge/relay tokens remain readable. Clipboard managers may retain either copy.")
		if not caps.clipboard then
			R.paragraph(transfer, "This host cannot write to the clipboard. You can still paste an export to import it.")
		end
		P.button(transfer, {
			name = "PasteFullConfig", text = "Paste configuration to import", fill = true,
			onClick = fullConfigImport,
		})

		local out = build.section("Diagnostic export",
			"Writes a copy of your settings and the activity history into the client's own "
			.. "folder. Credential fields, custom headers, query parameters, body overrides and connection tokens "
			.. "are excluded. Review remaining text before sharing.")
		local outPath = EXPORT_DIR .. "/uai-export.json"
		local result = P.text(out, {
			name = "ExportResult",
			text = fsx.enabled and ("Will write " .. fsx.root .. "/" .. outPath)
				or "This host has no filesystem, so an export can only go to the clipboard.",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		result.Size = UDim2.new(1, 0, 0, 0)

		local actions = {}
		if fsx.enabled then
			actions[#actions + 1] = {
				name = "ExportFile",
				text = "Export to a file",
				variant = "secondary",
				onClick = function()
					local ok, err = fsx.writeJson(outPath, exportPayload())
					result.Text = ok and ("Written to " .. fsx.root .. "/" .. outPath)
						or ("Could not write it: " .. tostring(err))
					overlay.toast(ok and "Exported" or "Export failed", ok and "good" or "warn", 2)
				end,
			}
		end
		if caps.clipboard then
			actions[#actions + 1] = {
				name = "ExportClipboard",
				text = "Copy to clipboard",
				variant = "ghost",
				onClick = function()
					local okEncode, body = pcall(util.encode, exportPayload())
					if not okEncode then
						overlay.toast("Could not encode the export", "warn", 2)
						return
					end
					local ok = env.require("runtime/clipboard").write(body)
					overlay.toast(ok and "Copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				end,
			}
		end
		if #actions > 0 then R.actions(out, actions) end

		local inbound = build.section("Import",
			"Reads a file from the client's folder and applies the settings in it. Providers, "
			-- Being explicit about this: an import that silently replaced a working key
			-- with "...abcd" from an export would break the client in a way that looks
			-- like the provider rejecting you.
			.. "keys and the bridge token are never imported, because an export does not "
			.. "contain them.")
		local importResult = P.text(inbound, {
			name = "ImportResult",
			text = "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		importResult.Size = UDim2.new(1, 0, 0, 0)
		R.actions(inbound, { {
			name = "ImportFile",
			text = "Import from a file",
			variant = "secondary",
			onClick = function()
				overlay.prompt({
					title = "Import settings",
					description = "A path inside " .. fsx.root .. ", as it appears in the folder.",
					placeholder = EXPORT_DIR .. "/uai-export.json",
					value = outPath,
					confirmText = "Import",
					onConfirm = function(path)
						local data = fsx.readJson(path, nil)
						local incoming = type(data) == "table" and (data.settings or data) or nil
						if type(incoming) ~= "table" then
							importResult.Text = "Nothing readable at " .. tostring(path)
							return
						end
						local applied = 0
						for _, section in ipairs({ "ui", "agent", "logs", "identity" }) do
							if type(incoming[section]) == "table" then
								config.set(section, util.merge(config.get(section, {}), incoming[section]))
								applied = applied + 1
							end
						end
						importResult.Text = applied > 0
							and (util.pluralise(applied, "section") .. " imported")
							or "That file had no settings in it"
						overlay.toast(importResult.Text, applied > 0 and "good" or "warn", 2)
					end,
				})
			end,
		} })
	end

	-- Desktop app -------------------------------------------------------------

	local function paneDesktop(container)
		local build = builder(container)

		local shell = build.section("Window",
			"Where the interface opens and how much of the screen it takes.")
		R.segmented(shell, {
			name = "OpenPanel",
			label = "Open on",
			hint = "Which surface the interface shows when it is opened.",
			path = "ui.panel",
			options = {
				{ value = "chat", label = "Chat" },
				{ value = "cowork", label = "Cowork" },
				{ value = "providers", label = "Providers" },
				{ value = "tools", label = "Tools" },
				{ value = "logs", label = "Logs" },
			},
		})
		R.toggle(shell, {
			label = "Start with the sidebar collapsed",
			hint = "The conversation list can always be brought back with the toggle in the header.",
			path = "ui.sidebarCollapsed",
		})
		R.toggle(shell, {
			label = "Keep the panel list open",
			hint = "Whether the sidebar's More section starts expanded.",
			path = "ui.sidebarExpanded",
		})
		R.actions(shell, {
			{
				name = "ResetWindow",
				text = "Reset window position",
				variant = "ghost",
				onClick = function()
					config.set("ui.window", util.deepCopy(util.get(config.defaults, "ui.window")))
					overlay.toast("Window position reset", "good", 2)
				end,
			},
			{
				name = "ResetLauncher",
				text = "Reset the launcher",
				variant = "ghost",
				onClick = function()
					config.set("ui.launcher", util.deepCopy(util.get(config.defaults, "ui.launcher")))
					overlay.toast("Launcher reset", "good", 2)
				end,
			},
		})

		local host = build.section("This host",
			"What the client found when it started. None of it is configurable; all of it "
			.. "decides what works.")
		local facts = {
			{ key = "Client", value = tostring(env.info and env.info.version or "") },
			{ key = "Transport", value = caps.http .. (caps.requestName and (" (" .. caps.requestName .. ")") or "") },
			{ key = "Identity", value = caps.uaSupported and "can be sent" or "cannot be sent here", tone = caps.uaSupported and "good" or "warn" },
			{ key = "Filesystem", value = caps.fs and "yes" or "no", tone = caps.fs and "good" or "warn" },
			{ key = "Executor", value = caps.executor },
			{ key = "Viewport", value = responsive.describe() },
		}
		if caps.studio then facts[#facts + 1] = { key = "Studio", value = "yes" } end
		for _, entry in ipairs(place.facts()) do facts[#facts + 1] = entry end
		R.facts(host, facts, { name = "HostFacts" })
	end

	-- Developer ---------------------------------------------------------------

	local function paneDeveloper(container)
		local build = builder(container)

		local logs = build.section("Diagnostics",
			"Every request and every log line the client has kept, and what it keeps them for.")
		local counts = P.text(logs, {
			name = "LogCounts",
			text = "",
			role = "monoSmall",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		counts.Size = UDim2.new(1, 0, 0, 0)
		local function describeCounts()
			counts.Text = string.format("%s in the request history\n%s in the log\n%s registered for cleanup",
				util.pluralise(#http.history, "entry"),
				util.pluralise(#log.entries, "line"),
				util.pluralise(env.require("runtime/dispose").count(), "handle"))
		end
		describeCounts()
		R.actions(logs, {
			{
				name = "OpenLogs",
				text = "Open the log",
				variant = "secondary",
				onClick = function()
					env.require("ui/app").show("logs")
				end,
			},
			{
				name = "RefreshCounts",
				text = "Refresh",
				variant = "ghost",
				onClick = describeCounts,
			},
			{
				name = "CreateSupportBundle",
				text = "Create support bundle",
				variant = "ghost",
				onClick = function()
					local result, why = env.require("runtime/support_bundle").write()
					if result then
						overlay.toast("Support bundle written to " .. tostring(result.path or "the workspace"), "good", 4)
					else
						overlay.toast("Could not write the support bundle: " .. tostring(why), "warn", 4)
					end
				end,
			},
			{
				name = "ClearEvidence",
				text = "Clear evidence",
				variant = "ghost",
				onClick = function()
					local current = sessions.activeId and sessions.get(sessions.activeId)
					if not current then overlay.toast("No active conversation", "warn", 3); return end
					local evidence = env.require("runtime/evidence")
					local before = evidence.state(current)
					evidence.clear(current)
					overlay.toast(string.format("Cleared %d evidence record(s), %.1f KiB",
						before.records or 0, (before.bytes or 0) / 1024), "good", 3)
				end,
			},
			{
				name = "CopyDiagnostics",
				text = "Copy diagnostics",
				variant = "ghost",
				onClick = function()
					local report = table.concat({
						"UAI " .. tostring(env.info and env.info.version or ""),
						caps.summary(),
						responsive.describe(),
						place.describe(),
						ua.describe(),
						usage.line(),
						log.export(),
					}, "\n")
					if caps.clipboard then
						local ok = env.require("runtime/clipboard").write(report)
						overlay.toast(ok and "Diagnostics copied" or "Could not reach the clipboard",
							ok and "good" or "warn", 2)
					else
						log.info("diagnostics", report)
						overlay.toast("No clipboard here, so it went to the log", "info", 3)
					end
				end,
			},
		})

		local identity = build.section("Client identity",
			"Requests are sent as the Claude Code CLI. Gateways that gate on it accept them; "
			.. "others ignore the extra headers.")
		R.toggle(identity, {
			label = "Send the Claude Code identity",
			hint = "Applies to every inference request.",
			path = "identity.claudeUa",
		})
		R.field(identity, {
			name = "IdentityVersion",
			path = "identity.version",
			placeholder = ua.DEFAULT_VERSION,
			transform = function(text)
				if util.trim(text) == "" then return ua.DEFAULT_VERSION end
				return util.trim(text)
			end,
		})
		local identityBox = P.frame(identity, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.codeSurface,
			radius = theme.radius.md,
			padding = theme.space.sm,
		})
		P.stroke(identityBox, theme.color.codeBorder)
		local identityText = P.text(identityBox, {
			text = ua.describe(),
			role = "monoSmall",
			color = theme.color.codeText,
			wrap = true,
			auto = "Y",
		})
		identityText.Size = UDim2.new(1, 0, 0, 0)
		local unsubscribe = config.changed:connect(function(path)
			if not identityText.Parent then return end
			if path == nil or util.startsWith(tostring(path), "identity.") then
				identityText.Text = ua.describe()
			end
		end)
		identityText.Destroying:Connect(function() pcall(unsubscribe) end)
		if not caps.uaSupported then
			R.paragraph(identity,
				"This host has no executor HTTP function, so Roblox sends its own User-Agent and "
				.. "drops ours. Everything else still works.", { color = theme.color.warn })
		end

		local danger = build.section("Reset",
			"Providers, permission rules and memory are kept unless you say otherwise.")
		R.actions(danger, {
			{
				name = "ResetSettings",
				text = "Reset all settings",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Reset every setting?",
						description = "Appearance and agent settings go back to defaults. Providers, rules and memory are kept.",
						confirmText = "Reset",
						danger = true,
						onConfirm = function()
							config.reset("ui")
							config.reset("agent")
							overlay.toast("Settings reset", "good")
						end,
					})
				end,
			},
			{
				name = "UnloadUai",
				text = "Unload UAI",
				variant = "danger",
				onClick = function()
					overlay.confirm({
						title = "Unload UAI?",
						description = "Stops the current turn, drains every timer and input handler, saves your settings and removes the interface. Run the loader again to come back.",
						confirmText = "Unload",
						danger = true,
						onConfirm = function()
							-- The handle the bootstrap published, which is the only thing
							-- holding the disposer registry and the ScreenGui together.
							local globals = (type(getgenv) == "function") and getgenv() or nil
							local live = globals and globals.UAI
							if live and live.destroy then
								local finished, why = live.destroy()
								if finished == false then overlay.toast(why or "UAI could not finish unloading. Try again.", "warn", 5) end
							else
								if config.vaultStatus().busy then overlay.toast("Finish or cancel credential storage before unloading UAI.", "warn", 5); return end
								env.require("runtime/dispose").drain()
								pcall(function() env.require("ui/app").screen:Destroy() end)
							end
						end,
					})
				end,
			},
		})
	end

	-- Agent -------------------------------------------------------------------

	local function paneAgent(container)
		local build = builder(container)

		local agent = build.section("Tools & execution", "Control how much work the agent can do in one turn.")
		R.number(agent, "Step limit", "Tool rounds allowed in one turn, unless the switch below removes it.",
			"agent.maxTurns", 4, 60, 1)
		R.toggle(agent, {
			label = "Unlimited tool calls",
			hint = "Ignore the step limit and the fifteen-minute turn deadline, and keep calling tools until the answer is written. The repeat breaker, each tool's own timeout and Stop still apply, and subagents keep their own budgets.",
			path = "agent.unlimitedTurns",
		})
		R.number(agent, "Parallel tools", "Tool calls run at once within one step.",
			"agent.toolConcurrency", 1, 8, 1)
		R.select(agent, {
			label = "Tool profile",
			hint = "All keeps every tool declared. Other profiles declare a smaller core; hidden tools remain callable through tool_search with their normal permissions and scope.",
			path = "agent.toolProfile",
			options = env.require("agent/tool_profiles").options(),
		})
		R.select(agent, {
			label = "Tool evidence",
			hint = "Large keeps only results at or above 8 KiB for later recovery; source and file tools are already durable. All keeps every result; Off writes nothing.",
			path = "agent.evidence",
			options = {
				{ value = "large", label = "Large results (8 KiB+)" },
				{ value = "all", label = "All results" },
				{ value = "off", label = "Off" },
			},
		})
		R.number(agent, "Tool timeout",
			"Seconds before a tool is abandoned. Subagents are exempt: they run to their own budget below.",
			"agent.toolTimeout", 5, 60, 1)
		R.number(agent, "Tool result cap",
			"Maximum bytes kept from one tool result. A tool's own page limit can be smaller. Roughly four bytes per token for English text; code and Unicode vary.",
			"agent.resultCap", RESULT_STOPS)

		local requests = build.section("Model requests", "Routing, wait time and recovery when contacting your provider.")
		R.toggle(requests, {
			name = "AutomaticFreeRouting", label = "Automatic free routing",
			hint = "Choose a recently verified free model for included HCNSEC access when its model is Auto. Off keeps provider Auto and stops new local routing probes; an active request continues.",
			path = "agent.autoFreeRouting", value = config.get("agent.autoFreeRouting", true) ~= false,
		})
		R.number(requests, "Request timeout",
			"Wait for a direct or companion model call. Direct native requests cap at 300 seconds; hosts and providers may stop sooner. Cowork bridge requests always wait until completion, failure or Stop.",
			"agent.requestTimeout", REQUEST_STOPS)
		R.toggle(requests, {
			label = "Maximum request wait",
			hint = "Use the direct transport's maximum wait instead of a shorter timeout, up to 300 seconds. Cowork bridge requests already have no time limit. Stop remains available.",
			path = "agent.requestUnlimited",
		})
		R.number(requests, "Retries", "Attempts per provider before moving to the next.",
			"agent.retries", 1, 6, 1)
		R.toggle(requests, {
			label = "Ask for streams",
			hint = "Streamed replies carry reasoning text and usage counts.",
			path = "agent.stream",
		})
		R.toggle(requests, {
			label = "Provider fallback",
			hint = "Try the next enabled provider when one fails.",
			path = "agent.fallback",
		})

		local delegation = build.section("Subagents", "Set the capacity and limits for delegated work.")
		R.number(delegation, "Subagent budget",
			"Seconds one subagent may work before it wraps up. The main agent can continue its own work and check progress while the child runs. Ignored while the switch below is on.",
			"agent.subagentBudget", 30, 900, 30)
		-- The switch the step-limit message asks for. A subagent that stops mid-job and
		-- says "I reached this session's step limit" has spent the whole dispatch and
		-- answered nothing, and until this existed the only way past it was to edit
		-- config.json -- `Unlimited tool calls` deliberately stops at the conversation the
		-- user is watching.
		R.toggle(delegation, {
			label = "Unlimited subagents",
			hint = "Let a dispatched subagent run with no step limit or clock while its parent continues working. The repeat breaker, each tool's timeout, the ceilings below and Stop still apply. The Subagents panel can stop one child, and ending the parent turn stops unfinished children.",
			path = "agent.subagentUnlimited",
		})
		R.number(delegation, "Parallel subagents",
			"Subagents alive at once across the whole tree. Several dispatched in one step run together; this is the ceiling on how many, including the ones a subagent starts itself. Anything over it waits for a slot.",
			"agent.subagentConcurrency", 1, 12, 1)
		-- Two ceilings that had no control anywhere: the only way to change either was
		-- to edit config.json, which for the depth cap means the only switch that can
		-- turn delegation off entirely was unreachable.
		R.number(delegation, "Subagent steps",
			"Tool rounds one subagent may take before it has to answer the parent with what it has. Ignored while Unlimited subagents is on.",
			"agent.subagentTurns", 1, 30, 1)
		R.number(delegation, "Delegation depth",
			"How many levels of subagent are allowed. A subagent given the full tool set can dispatch its own; at 0 the agent cannot dispatch at all and does the work in the conversation instead. The Subagents panel lists what is running under these limits.",
			"agent.subagentDepth", 0, 4, 1)

		local context = build.section("Conversation memory", "Keep long conversations within the model's context window.")
		R.number(context, "Context budget",
			"Hard ceiling on tokens kept before older turns are summarised. When the model's context window is known, compaction begins at the Compact-at fraction of it, so this mainly caps models with very large or unknown windows.",
			"agent.contextTokens", BUDGET_STOPS)
		R.number(context, "Compact at",
			"Share of the model's context window at which older turns are summarised, when the window is known. Lower compacts sooner and cheaper; higher keeps more history in view. The Context budget above is still a hard ceiling.",
			"agent.contextFraction", 0.5, 0.95, 0.05)
		R.toggle(context, {
			label = "Summarise old turns",
			hint = "Keeps a long conversation inside the context budget.",
			path = "agent.compaction",
		})

		local response = build.section("Responses", "Adjust response length, effort and language.")
		R.number(response, "Reply ceiling",
			"Maximum generated tokens per request, including reasoning where the provider counts it. Model limits, available context and learned provider caps may lower it. This does not require the model to use the whole allowance.",
			"agent.maxTokens", REPLY_STOPS)
		R.choice(response, "Effort",
			"Low is the faster default; raise it for difficult tasks. Existing saved choices are kept. "
			.. "Sent as the provider's effort level where supported; raw provider parameters can override it. Provider default omits the effort field and may still think extensively. The Thinking row shows visible text, not a 5,999-token limit.",
			"agent.effort",
			{ "low", "medium", "high", "xhigh", "max", "off" },
			{ "Low", "Medium", "High", "Very high", "Max", "Provider default" },
			{ "Faster", "Provider default" })
		R.number(response, "Temperature",
			"Lower is steadier; 0 is as deterministic as the provider allows. The current Claude models reject it, and it is not sent to them.",
			"agent.temperature", 0, 1.5, 0.05)
		-- One field, and the only half of the old language picker that was ever wired to
		-- anything. That control was a grid of eleven tiles behind a modal behind a menu
		-- entry, and it advertised two effects: the language the agent answers in, which
		-- src/agent/prompt.lua does read, and the locale dates are formatted with, which
		-- nothing reads at all. What survives is the effect that exists.
		R.field(response, {
			name = "ReplyLanguage",
			label = "Reply language",
			hint = "Added to the system prompt as one line: answer in this language, leaving code "
				.. "and identifiers alone. Empty means whatever the conversation is already in, "
				.. "which is what a model does by default.",
			path = "agent.replyLanguage",
			placeholder = "Japanese",
		})

		-- The user's own standing instructions. This is the personal half of the prompt;
		-- the built-in half is fixed on purpose, and the copy action below is how it is
		-- inspected -- read-only, on the record, diffable between versions.
		local custom = build.section("Custom instructions",
			"Added to the system prompt every turn, after the built-in rules, so they win "
			.. "when the two disagree. The rest of the prompt is not editable: it is this "
			.. "client's own behaviour, and what is yours is kept separate from it so you "
			.. "can always tell which is which.")
		R.textarea(custom, {
			name = "CustomInstructions",
			path = "agent.customInstructions",
			height = theme.size.formTextarea,
			placeholder = "e.g. Reply short. I build obby games. My alt account is DaveAlt99 -- ignore it when counting players.",
			hint = "Written when the box loses focus. Applies from the next turn, including "
				.. "subagents, which inherit it with the rest of the brief.",
		})
		R.actions(custom, { {
			name = "CopySystemPrompt",
			text = "Copy system prompt",
			variant = "ghost",
			onClick = function()
				-- The assembled thing rather than the module's constants, so what is on
				-- the clipboard is what the next request will carry: the environment
				-- block, the permission line, this pane's own instructions included.
				local providers = env.require("provider/registry")
				local prompt = env.require("agent/prompt")
				local record = providers.active()
				local body = prompt.build({
					model = record and record.model or nil,
					provider = record and record.label or nil,
				})
				if caps.clipboard then
					local ok = env.require("runtime/clipboard").write(body)
					overlay.toast(ok and "System prompt copied" or "Could not reach the clipboard",
						ok and "good" or "warn", 2)
				else
					log.info("prompt", body)
					overlay.toast("No clipboard here, so it went to the log", "info", 3)
				end
			end,
		} })
	end

	-- Permissions -------------------------------------------------------------

	local function panePermissions(container)
		local build = builder(container)
		local card = build.section("Permissions", "Choose when tools can run and review saved exceptions.")

		local modeOptions = {}
		for _, mode in ipairs(permissions.MODES) do
			modeOptions[#modeOptions + 1] = { value = mode, label = permissions.MODE_LABELS[mode] or mode }
		end
		local modeHint
		C.segmented(card, {
			options = modeOptions,
			value = permissions.mode(),
			onChange = function(value)
				permissions.setMode(value)
				if modeHint then modeHint.Text = permissions.MODE_HINTS[value] or "" end
			end,
		})
		modeHint = P.text(card, {
			text = permissions.MODE_HINTS[permissions.mode()] or "",
			role = "caption",
			color = theme.color.textTertiary,
			wrap = true,
			auto = "Y",
		})
		modeHint.Size = UDim2.new(1, 0, 0, 0)

		R.toggle(card, {
			label = "Offer to remember",
			hint = "Show the remember switch on each prompt.",
			path = "permissions.remember",
		})

		local rulesLabel = P.text(card, {
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			wrap = true,
			auto = "Y",
		})
		rulesLabel.Size = UDim2.new(1, 0, 0, 0)
		local function refreshRules()
			local rules = permissions.listRules()
			if #rules == 0 then
				rulesLabel.Text = "No per-tool rules saved."
				return
			end
			local parts = {}
			for _, rule in ipairs(rules) do
				parts[#parts + 1] = rule.pattern .. " = " .. rule.verdict
			end
			rulesLabel.Text = util.pluralise(#rules, "saved rule") .. ": " .. table.concat(parts, ", ")
		end
		refreshRules()
		local unsubscribe = permissions.changed:connect(function()
			if not rulesLabel.Parent then return end
			refreshRules()
		end)
		rulesLabel.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(card, { {
			name = "ClearRules",
			text = "Clear saved rules",
			variant = "ghost",
			onClick = function()
				permissions.clearRules()
				refreshRules()
			end,
		} })
	end

	-- Skills ------------------------------------------------------------------

	local function paneSkills(container)
		local build = builder(container)

		-- Skills (playbooks) ------------------------------------------------
		--
		-- .md files under skills/, each a frontmatter description and a body of
		-- instructions. The list is files on disk rather than config state, so
		-- the honest subtitle is where they come from: dropped in by hand,
		-- written by the agent, or installed from GitHub. The toggle is the one
		-- bit of state kept, and it is stored per filename.
		local skillsCard = build.section("Playbooks",
			"Agents read enabled skills when relevant or explicitly requested, and reuse "
			.. "unchanged bodies still in context. Drop a .md playbook into skills/, or ask "
			.. "the agent to install one from GitHub. Turn off a skill to exclude it.")
		local skillsEngine = env.require("runtime/skills")

		local skillsList = P.column(skillsCard, {
			name = "SkillsList",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
		})
		local function refreshSkills()
			-- Keep the layout: clearing it stacked every installed skill at (0, 0).
			for _, child in ipairs(skillsList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local list = skillsEngine.list()
			if #list == 0 then
				R.paragraph(skillsList, "No skills installed yet.",
					{ layoutOrder = 1 })
				return
			end
			for index, skill in ipairs(list) do
				local row = P.row(skillsList, {
					name = "Skill_" .. skill.file,
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.sm,
					layoutOrder = index,
				})
				local text = P.column(row, {
					size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
				})
				P.text(text, { text = skill.name, role = "small", wrap = true, auto = "Y" })
				local detail = skill.description ~= "" and util.ellipsis(skill.description, 140)
					or (skill.unreadable and "could not be read") or "no description"
				P.text(text, {
					text = detail,
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
				})
				local switch = C.switch(row, {
					value = skill.enabled,
					onChange = function(value)
						skillsEngine.setEnabled(skill.file, value)
					end,
				})
				switch.instance.LayoutOrder = 2
			end
		end
		refreshSkills()
		local unsubscribeSkills = skillsEngine.changed:connect(function()
			if not skillsList.Parent then return end
			refreshSkills()
		end)
		skillsList.Destroying:Connect(function() pcall(unsubscribeSkills) end)

		local memory = build.section("Memory",
			"Facts the agent has chosen to keep between sessions. It writes these itself, with "
			.. "the memory tool; this is where they can be read and removed.")
		R.toggle(memory, {
			label = "Enabled",
			hint = "When off, nothing new is stored and nothing is injected.",
			path = "memory.enabled",
		})
		local memoryList = P.column(memory, {
			name = "MemoryEntries", size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs,
		})
		local function refreshMemory()
			for _, child in ipairs(memoryList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local list = state.memoryList()
			if #list == 0 then
				P.text(memoryList, { text = "Nothing stored.", role = "caption", color = theme.color.textTertiary,
					auto = "Y", wrap = true })
				return
			end
			for index, entry in ipairs(list) do
				local row = P.row(memoryList, {
					name = "MemoryEntry_" .. entry.key, size = UDim2.new(1, 0, 0, 0), auto = "Y",
					gap = theme.space.sm, alignY = "Top", layoutOrder = index,
				})
				P.text(row, {
					text = entry.key .. ": " .. util.ellipsis(entry.value, 120),
					role = "caption", color = theme.color.textSecondary, wrap = true, auto = "Y",
					size = UDim2.new(0, 0, 0, 0), flex = "Fill", layoutOrder = 1,
				})
				local key = entry.key
				P.iconButton(row, {
					name = "ForgetOne", icon = "trash", variant = "ghost", diameter = theme.size.controlSmall,
					layoutOrder = 2,
					onClick = function() state.forget(key) end,
				})
			end
		end
		refreshMemory()
		local unsubscribe = state.memoryChanged:connect(function()
			if not memoryList.Parent then return end
			refreshMemory()
		end)
		memoryList.Destroying:Connect(function() pcall(unsubscribe) end)
		R.actions(memory, { {
			name = "ForgetEverything",
			text = "Forget everything",
			variant = "ghost",
			onClick = function()
				overlay.confirm({
					title = "Clear memory?",
					description = "Every stored fact is deleted.",
					confirmText = "Clear",
					danger = true,
					onConfirm = function()
						state.clearMemory()
						refreshMemory()
					end,
				})
			end,
		} })

		local host = build.section("Host instructions",
			"A script that embeds this client can add its own instructions and hooks. This is "
			.. "what the current host provided.")
		local hostPrompt = env.context and env.context.prompt
		local hooks = env.require("agent/hooks")
		local hookCounts = {}
		for kind in pairs(hooks.KINDS) do
			local count = hooks.count(kind)
			if count > 0 then hookCounts[#hookCounts + 1] = { key = kind, value = tostring(count) } end
		end
		if type(hostPrompt) == "string" and util.trim(hostPrompt) ~= "" then
			R.paragraph(host, util.ellipsis(hostPrompt, 600), { role = "small", color = theme.color.text })
		else
			R.paragraph(host, "No host instructions: this client was loaded on its own.")
		end
		if #hookCounts > 0 then
			table.sort(hookCounts, function(a, b) return a.key < b.key end)
			R.facts(host, hookCounts, { name = "Hooks" })
		end
	end

	-- Connectors --------------------------------------------------------------

	local function paneConnectors(container)
		local build = builder(container)

		local card = build.section("Inference providers",
			"Your configured providers and models. Add a service or edit its connection details in Providers.")
		local list = providers.list()
		if #list == 0 then
			R.paragraph(card, "Nothing configured yet.")
		else
			local facts = {}
			for _, record in ipairs(list) do
				local detail = record.baseUrl
				if util.trim(tostring(record.model or "")) ~= "" then
					detail = record.model .. "  " .. record.baseUrl
				end
				facts[#facts + 1] = {
					key = record.label,
					value = detail,
					tone = (providers.active() or {}).id == record.id and "good" or nil,
				}
			end
			R.facts(card, facts, { name = "Providers" })
		end
		R.actions(card, { {
			name = "OpenInference",
			text = "Manage providers",
			variant = "secondary",
			onClick = function()
				env.require("ui/app").show("providers")
			end,
		} })

		local bridgeCard = build.section("Web bridge",
			"The one connector that is not a model: a browser on this machine sharing the "
			.. "conversation.")
		local status = bridgeModule.status()
		R.facts(bridgeCard, {
			{ key = "State", value = status.running and (status.online and "connected" or "polling") or "off",
				tone = status.running and (status.online and "good" or "warn") or nil },
			{ key = "Address", value = status.url },
		}, { name = "BridgeFacts" })
		R.actions(bridgeCard, { {
			name = "OpenCowork",
			text = "Open Cowork",
			variant = "ghost",
			onClick = function()
				env.require("ui/app").show("cowork")
			end,
		} })
	end

	-- Infinite Yield ------------------------------------------------------------

	-- The mode picker is a segmented control rather than a toggle because there
	-- are three honest states, not two: off, hidden (IY's engine, no IY pixels)
	-- and visible (IY exactly as it draws itself). A toggle would have to fold
	-- "off" and "hidden" into one position, and they are different decisions --
	-- one withholds the commands from the agent, the other only the interface.
	--
	-- Changing the mode does not load anything here. Loading is a megabyte
	-- fetch, a compile and a GUI; a settings row is not where that should spend
	-- itself. The next iy_cmd call picks the new mode up, and the status lines
	-- below say which state it will find.
	local function paneInfiniteYield(container)
		local build = builder(container)
		local card = build.section("Infinite Yield",
			"Run Infinite Yield inside this client and give the agent every one of its "
			.. "commands through the iy tools.")

		local iy = env.require("runtime/iy")
		local facts = P.column(card, {
			name = "IyStatus",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xxs,
		})
		local function refresh()
			for _, child in ipairs(facts:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local status = iy.status()
			for index, row in ipairs(status) do
				P.text(facts, {
					text = row[1] .. ": " .. tostring(row[2]),
					role = "caption",
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					layoutOrder = index,
				}).Size = UDim2.new(1, 0, 0, 0)
			end
		end
		refresh()

		C.segmented(card, {
			options = {
				{ value = "off", label = "Off" },
				{ value = "hidden", label = "Hidden" },
				{ value = "visible", label = "With GUI" },
			},
			value = config.get("iy.mode", "hidden"),
			onChange = function(value)
				iy.setMode(value)
				refresh()
			end,
		})

		R.paragraph(card,
			"Hidden loads Infinite Yield with its interface parked, so the agent has "
			.. "every command and you keep the screen. With GUI loads it untouched. "
			.. "Either way the agent reaches everything through the same dispatcher, and "
			.. "iy_cmd calls still pass the permission prompt. If Infinite Yield is "
			.. "already running when a command is sent, that copy is used as-is.",
			{ layoutOrder = 4 })

		if not caps.exec then
			R.paragraph(card,
				"This host cannot compile code, so an internal load is unavailable here. "
				.. "An Infinite Yield you start yourself still works.",
				{ color = theme.color.warn })
		end
	end

	-- Plugins -----------------------------------------------------------------

	local function panePlugins(container)
		local build = builder(container)
		local card = build.section("Tool groups",
			"A family of tools can be withheld from the model entirely. That is a different "
			.. "thing from denying a call: a tool that is not offered is one the model will not "
			.. "spend a turn discovering it cannot use.")

		for _, group in ipairs(registry.groups()) do
			local row = P.row(card, {
				name = "Group_" .. group.id,
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.sm,
			})
			local text = P.column(row, {
				size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = 0, layoutOrder = 1,
			})
			P.text(text, { text = group.label, role = "label", wrap = true, auto = "Y" })
			local detail = util.pluralise(group.total, "tool")
			if group.unavailable > 0 then
				detail = detail .. ", " .. tostring(group.unavailable) .. " unavailable on this host"
			end
			P.text(text, {
				text = detail,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
			local switch = C.switch(row, {
				value = group.enabled,
				onChange = function(value)
					registry.setGroupEnabled(group.id, value)
				end,
			})
			switch.instance.LayoutOrder = 2
		end

		R.actions(card, { {
			name = "OpenTools",
			text = "See every tool",
			variant = "secondary",
			onClick = function()
				env.require("ui/app").show("tools")
			end,
		} })
	end

	-- The list -----------------------------------------------------------------

	-- Grouped the way the reference client groups them. "Agent" is the one section it
	-- does not have, and it is not optional here: the step limit, the context budget
	-- and the permission mode are the settings this client is actually about, and
	-- filing them under Developer to preserve a menu shape would hide them.
	M.PANES = {
		{ id = "general", section = "Settings", label = "General", icon = "gear", build = paneGeneral },
		{ id = "privacy", section = "Settings", label = "Privacy", icon = "worktree", build = paneprivacy },
		{ id = "usage", section = "Settings", label = "Usage", icon = "sliders", build = paneUsage },
		{ id = "claude_code", section = "Settings", label = "Project UAI", icon = "code", build = paneClaudeCode },
		{ id = "cowork", section = "Settings", label = "Cowork", icon = "terminal", build = paneCowork },
		{ id = "import_export", section = "Settings", label = "Import & export", icon = "document", build = paneImportExport },
		{ id = "agent", section = "Agent", label = "Behaviour", icon = "spark", build = paneAgent },
		{ id = "permissions", section = "Agent", label = "Permissions", icon = "check", build = panePermissions },
		{ id = "desktop_general", section = "Desktop app", label = "General", icon = "windowMaximize", build = paneDesktop },
		{ id = "developer", section = "Desktop app", label = "Developer", icon = "terminal", build = paneDeveloper },
		{ id = "skills", section = "Customize", label = "Skills", icon = "book", build = paneSkills },
		{ id = "connectors", section = "Customize", label = "Connectors", icon = "branch", build = paneConnectors },
		{ id = "obsidian", section = "Customize", label = "Obsidian", icon = "book", build = function(container) env.require("ui/obsidian").build(container) end },
		{ id = "infinite_yield", section = "Customize", label = "Infinite Yield", icon = "terminal", build = paneInfiniteYield },
		{ id = "plugins", section = "Customize", label = "Plugins", icon = "worktree", build = panePlugins },
	}

	function M.pane(id)
		for _, entry in ipairs(M.PANES) do
			if entry.id == id then return entry end
		end
		return nil
	end

	-- The dialog's nav, in declaration order, with the section headings kept.
	function M.sections()
		local out, seen = {}, {}
		for _, entry in ipairs(M.PANES) do
			if not seen[entry.section] then
				seen[entry.section] = { title = entry.section, panes = {} }
				out[#out + 1] = seen[entry.section]
			end
			local group = seen[entry.section]
			group.panes[#group.panes + 1] = entry
		end
		return out
	end

	-- One pane into a container of its own. Used by the dialog when a category is
	-- chosen, and by the Settings panel for every pane in turn.
	function M.render(id, container)
		local entry = M.pane(id)
		if not entry then return false end
		local heading = P.column(container, { name = "SettingsPaneHeading", size = UDim2.new(1, 0, 0, 0),
			auto = "Y", gap = theme.space.xxs, layoutOrder = -1 })
		P.text(heading, { name = "SettingsPaneSection", text = entry.section, role = "caption",
			color = theme.color.textTertiary, auto = "Y", wrap = true, layoutOrder = 1 })
		P.text(heading, { name = "SettingsPaneTitle", text = entry.label, role = "title",
			auto = "Y", wrap = true, layoutOrder = 2 })
		local ok, err = pcall(entry.build, container)
		if not ok then
			log.warn("settings", "the " .. tostring(id) .. " pane failed to build", err)
			R.paragraph(container, "This pane could not be built: " .. tostring(err),
				{ color = theme.color.danger })
		end
		return ok
	end

	return M
end
end)()

-- ==========================================================================
-- ui/settingsrows
-- ==========================================================================
__UAI_MODULES["ui/settingsrows"] = (function()
-- The rows a settings surface is made of.
--
-- There are two of those surfaces now -- the Settings panel and the settings dialog
-- the sidebar opens -- and they have to agree about what a toggle looks like, how a
-- token budget is expressed as a track, and which config path a control writes. So
-- the rows live here and both surfaces call them, rather than the dialog growing a
-- second, subtly different set.
--
-- Every builder takes the config path it writes and nothing else about where the
-- value goes: the row reads the current value itself and writes it back itself, which
-- is why none of these return a handle to be wired up afterwards.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local P = env.require("ui/primitives")
	local C = env.require("ui/controls")

	local R = {}
	local function identify(row, path, label)
		if path then row:SetAttribute("UAISettingPath", path) end
		if label then row:SetAttribute("UAISettingLabel", label) end
		return row
	end

	-- A heading with an optional description, followed by the card its rows go in.
	--
	-- Both go inside one wrapper with a tight gap between them, so the heading is
	-- visibly closer to the card it labels than to whatever is above it. As two loose
	-- siblings the two distances were the same number -- the parent's gap -- and a
	-- column of sections read as an alternating stack with no grouping in it.
	function R.section(parent, props)
		props = props or {}
		local group = P.column(parent, {
			name = props.name and (props.name .. "Group") or "Group",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = props.layoutOrder,
		})
		P.sectionHeader(group, {
			title = props.title,
			description = props.description,
			layoutOrder = 1,
		})
		return P.card(group, {
			name = props.name,
			layoutOrder = 2,
			gap = theme.space.md,
			padding = theme.space.md,
		})
	end

	function R.paragraph(parent, text, props)
		props = props or {}
		local label = P.text(parent, {
			name = props.name,
			text = tostring(text or ""),
			role = props.role or "caption",
			color = props.color or theme.color.textTertiary,
			wrap = true,
			auto = "Y",
			layoutOrder = props.layoutOrder,
		})
		label.Size = UDim2.new(1, 0, 0, 0)
		return label
	end

	function R.toggle(parent, props)
		local initial = props.value
		if initial == nil then initial = config.get(props.path, false) == true end
		local row = P.row(parent, {
			name = props.name,
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		local text = P.column(row, {
			size = UDim2.new(0, 0, 0, 0), auto = "Y", flex = "Fill", gap = theme.space.xxs, layoutOrder = 1,
		})
		identify(row, props.path, props.label)
		P.text(text, { text = props.label, role = "label", wrap = true, auto = "Y" })
		if props.hint then
			P.text(text, {
				text = props.hint,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
			})
		end
		local switch = C.switch(row, {
			value = initial,
			onChange = function(value)
				if props.path then config.set(props.path, value) end
				if props.onChange then pcall(props.onChange, value) end
			end,
		})
		switch.instance.LayoutOrder = 2
		return switch
	end

	-- A million in a 66px monospace field is a wall of zeroes, and the exact digit
	-- is never what the reader is checking at that size.
	local function formatCount(number)
		number = math.floor(number)
		if number >= 1000000 and number % 100000 == 0 then
			local millions = number / 1000000
			return (millions % 1 == 0) and string.format("%dM", millions) or string.format("%.1fM", millions)
		end
		if number >= 1000 and number % 1000 == 0 then return string.format("%dk", number / 1000) end
		return tostring(number)
	end

	R.formatCount = formatCount

	-- `min` may be a list of allowed values rather than a bound. Every row that
	-- counts tokens uses one: the range those rows have to cover is three orders of
	-- magnitude, and a linear track across it cannot resolve the low end where the
	-- useful settings are.
	function R.number(parent, label, hint, path, min, max, step)
		local stops
		if type(min) == "table" then
			stops, min, max, step = min, min[1], min[#min], nil
		end
		local function display(number)
			return (step and step < 1) and string.format("%.2f", number) or formatCount(number)
		end
		local column = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xxs })
		identify(column, path, label)
		local head = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(head, {
			text = label,
			role = "small",
			-- Fills rather than reserving 70 for a 66px value plus a 6px gap, which
			-- overlapped it by two pixels.
			size = UDim2.new(0, 0, 0, 0),
			wrap = true,
			auto = "Y",
			flex = "Fill",
			layoutOrder = 1,
		})
		local value = P.text(head, {
			text = display(tonumber(config.get(path, min)) or min),
			role = "monoSmall",
			color = theme.color.accent,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})
		C.slider(column, {
			-- Named after the setting it writes, so the tree says which slider is
			-- which -- eight of them called "Slider" is unreadable from a dump and
			-- unreachable from a test.
			name = "Slider_" .. tostring(path),
			min = min,
			max = max,
			step = step,
			stops = stops,
			value = tonumber(config.get(path, min)) or min,
			onChange = function(number)
				value.Text = display(number)
			end,
			onCommit = function(number)
				config.set(path, (step and step < 1) and util.round(number, 2) or math.floor(number))
			end,
		})
		if hint then
			P.text(column, { text = hint, role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y" })
		end
		return column
	end

	-- A row whose stops are words rather than numbers.
	--
	-- A track is still the right control when the values are not numeric: the stops
	-- are ordered and the reader is picking a position on a scale, which a row of
	-- buttons states less clearly. The value reads in the label's own type rather
	-- than numberRow's monospace, because a word set in code font looks like an
	-- identifier, and both ends are named above the track -- what the scale *means*
	-- is the part neither the numbers nor the level names carry.
	function R.choice(parent, label, hint, path, values, labels, ends)
		local index, stored = 1, tostring(config.get(path, values[1]))
		for position, value in ipairs(values) do
			if value == stored then index = position end
		end
		local stops = {}
		for position = 1, #values do stops[position] = position end

		local column = P.column(parent, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xxs })
		identify(column, path, label)
		local head = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(head, {
			text = label,
			role = "small",
			size = UDim2.new(0, 0, 0, 0),
			wrap = true,
			auto = "Y",
			flex = "Fill",
			layoutOrder = 1,
		})
		local value = P.text(head, {
			text = labels[index],
			role = "label",
			color = theme.color.accent,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})

		local feet = P.row(column, { size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs })
		P.text(feet, {
			text = ends[1],
			role = "caption",
			color = theme.color.textTertiary,
			size = UDim2.new(0, 0, 0, theme.text.caption.height),
			flex = "Fill",
			layoutOrder = 1,
		})
		P.text(feet, {
			text = ends[2],
			role = "caption",
			color = theme.color.textTertiary,
			align = "Right",
			auto = "X",
			layoutOrder = 2,
		})
		C.slider(column, {
			name = "Slider_" .. tostring(path),
			stops = stops,
			value = index,
			onChange = function(number)
				value.Text = labels[math.floor(number)] or value.Text
			end,
			onCommit = function(number)
				local position = math.max(math.min(math.floor(number), #values), 1)
				value.Text = labels[position]
				config.set(path, values[position])
			end,
		})
		if hint then
			P.text(column, { text = hint, role = "caption", color = theme.color.textTertiary, wrap = true, auto = "Y" })
		end
		return column
	end

	-- Label and description on the left, one control on the right. The dialog's
	-- appearance pane is a column of these.
	--
	-- The right-hand slot states a width. It used to size itself to its contents,
	-- which for a segmented control -- whose own width is a scale when it is not given
	-- one -- resolved to zero: three controls in that pane were invisible and
	-- unclickable, and nothing about the props said so.
	function R.setting(parent, props)
		local row, layout = P.row(parent, {
			name = props.name,
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			alignY = "Center",
			gap = theme.space.md,
			layoutOrder = props.layoutOrder,
		})
		local left = P.column(row, {
			size = UDim2.new(1, -(props.width or theme.size.menu) - theme.space.md, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 1,
		})
		identify(row, props.path, props.label)
		P.text(left, {
			text = props.label,
			role = "bodyStrong",
			color = theme.color.text,
			auto = "Y",
			wrap = true,
			layoutOrder = 1,
		})
		if props.hint then
			P.text(left, {
				text = props.hint,
				role = "caption",
				color = theme.color.textTertiary,
				wrap = true,
				auto = "Y",
				layoutOrder = 2,
			})
		end
		local right = P.frame(row, {
			name = "Control",
			size = UDim2.fromOffset(props.width or theme.size.menu, 0),
			auto = "Y",
			layoutOrder = 2,
		})
		-- Reflow from the actual pane width, including a resized desktop window.
		-- Controls keep their preferred width until the label needs its own line.
		local controlWidth = props.width or theme.size.menu
		local function reflow()
			local width = row.AbsoluteSize.X
			if width <= 0 then return end
			local stacked = width < controlWidth + theme.size.menuMin + theme.space.md
			layout.FillDirection = stacked and Enum.FillDirection.Vertical or Enum.FillDirection.Horizontal
			layout.VerticalAlignment = stacked and Enum.VerticalAlignment.Top or Enum.VerticalAlignment.Center
			layout.Padding = UDim.new(0, stacked and theme.space.xs or theme.space.md)
			left.Size = UDim2.new(1, stacked and 0 or -(controlWidth + theme.space.md), 0, 0)
			right.Size = UDim2.new(stacked and 1 or 0, stacked and 0 or math.min(controlWidth, width), 0, 0)
		end
		row:GetPropertyChangedSignal("AbsoluteSize"):Connect(reflow)
		reflow()
		return right, row
	end

	-- A setting row whose control is a segmented picker over a config path.
	function R.segmented(parent, props)
		local width = C.segmentedWidth(props.options)
		local slot = R.setting(parent, {
			name = props.name,
			path = props.path,
			label = props.label,
			hint = props.hint,
			width = width,
			layoutOrder = props.layoutOrder,
		})
		local control = C.segmented(slot, {
			name = props.name and ("Segmented_" .. props.name) or nil,
			options = props.options,
			value = (props.value ~= nil) and props.value or config.get(props.path, props.options[1].value),
			onChange = function(value)
				if props.path then config.set(props.path, value) end
				if props.onChange then pcall(props.onChange, value) end
			end,
		})
		return control
	end

	-- A setting row whose control is a menu rather than a row of segments.
	--
	-- Segments stop working somewhere around four options. The interface font list is
	-- eight families wide, and eight segments in a 530px pane give each label sixty
	-- pixels -- which "Titillium Web" does not fit into, and C.segmented neither
	-- truncates nor clips, so the labels would simply run into each other. Same
	-- decision, a control that does not have to show every option at once.
	function R.select(parent, props)
		local options = props.options or {}
		local current = (props.value ~= nil) and props.value
			or config.get(props.path, options[1] and options[1].value)

		local function labelFor(value)
			for _, option in ipairs(options) do
				if option.value == value then return option.label or tostring(value) end
			end
			return tostring(value)
		end

		local slot = R.setting(parent, {
			name = props.name,
			path = props.path,
			label = props.label,
			hint = props.hint,
			width = props.width or theme.size.menu,
			layoutOrder = props.layoutOrder,
		})

		local control
		control = P.rowButton(slot, {
			name = props.name and ("Select_" .. props.name) or "Select",
			height = math.max(theme.size.control, responsive.minTarget()),
			radius = theme.radius.md,
			stroke = true,
			strokeColor = theme.color.border,
			padding = { x = theme.space.sm },
			onClick = function(handle)
				local menuOptions = {}
				for _, option in ipairs(options) do
					menuOptions[#menuOptions + 1] = {
						label = option.label or tostring(option.value),
						value = option.value,
						detail = option.detail,
						selected = option.value == current,
						free = option.free,
					}
				end
				env.require("ui/overlay").menu({
					target = handle.instance,
					width = math.max(props.menuWidth or theme.size.menuWide,
						math.floor(handle.instance.AbsoluteSize.X)),
					options = menuOptions,
					searchable = props.searchable,
					searchPlaceholder = props.searchPlaceholder,
					onSelect = function(value)
						current = value
						control.text.Text = labelFor(value)
						if props.path then config.set(props.path, value) end
						if props.onChange then pcall(props.onChange, value) end
					end,
				})
			end,
		})
		control.text = control.label(labelFor(current), 1, theme.color.text, "small")
		local caret = P.frame(control.row, {
			name = "Caret",
			size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
			layoutOrder = 2,
		})
		env.require("ui/icons").chevron(caret, theme.size.icon, theme.color.textTertiary, "down")
		return control
	end

	-- Keep a field's label and help together inside the surrounding row rhythm.
	local function fieldGroup(parent, props)
		local group = P.column(parent, {
			name = props.name and (props.name .. "Group") or "FieldGroup",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = props.layoutOrder,
		})
		if props.label then
			P.text(group, { text = props.label, role = "small", wrap = true, auto = "Y", layoutOrder = 1 })
		end
		identify(group, props.path, props.label)
		return group
	end

	-- Write on blur: typing a port should not restart the bridge per keystroke.
	function R.field(parent, props)
		local group = fieldGroup(parent, props)
		local field
		field = P.field(group, {
			name = props.name,
			text = tostring(props.value ~= nil and props.value or config.get(props.path, "")),
			placeholder = props.placeholder,
			size = props.size,
			layoutOrder = 2,
			onBlur = function(text)
				local clean = util.trim(text)
				if props.transform then clean = props.transform(clean) end
				if props.path then
					config.set(props.path, clean)
					field.instance:SetAttribute("UAIConfigValue", tostring(config.get(props.path, "")))
				end
				if props.onChange then pcall(props.onChange, clean) end
			end,
		})
		if props.path then
			field.instance:SetAttribute("UAIConfigPath", props.path)
			field.instance:SetAttribute("UAIConfigValue", tostring(config.get(props.path, "")))
		end
		if props.hint then R.paragraph(group, props.hint, { layoutOrder = 3 }) end
		return field
	end

	-- A multiline field bound to a config path, written on blur. Not folded into
	-- R.field behind a `multiline` prop: a textarea is a different control -- taller,
	-- top-aligned, Enter inserts a newline -- and every caller so far wants exactly
	-- one of the two. The custom instructions box is the first textarea in the client.
	function R.textarea(parent, props)
		local group = fieldGroup(parent, props)
		local field
		field = P.field(group, {
			name = props.name,
			multiline = true,
			height = props.height or theme.size.controlLarge * 2,
			text = tostring(props.value ~= nil and props.value or config.get(props.path, "")),
			placeholder = props.placeholder,
			layoutOrder = 2,
			-- Written on blur rather than per keystroke, same as R.field: the value is
			-- read by the next request, not this frame.
			onBlur = function(text)
				if props.path then
					config.set(props.path, tostring(text or ""))
					field.instance:SetAttribute("UAIConfigValue", tostring(config.get(props.path, "")))
				end
				if props.onChange then pcall(props.onChange, tostring(text or "")) end
			end,
		})
		if props.path then
			field.instance:SetAttribute("UAIConfigPath", props.path)
			field.instance:SetAttribute("UAIConfigValue", tostring(config.get(props.path, "")))
		end
		if props.hint then R.paragraph(group, props.hint, { layoutOrder = 3 }) end
		return field
	end

	-- A row of buttons. Actions rather than settings: a reset, a clear, an unload.
	function R.actions(parent, list, props)
		props = props or {}
		local row = P.row(parent, {
			name = props.name or "Actions",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		local limits = {}
		for index, entry in ipairs(list) do
			local button = P.button(row, {
				name = entry.name,
				text = entry.text,
				variant = entry.variant or "secondary",
				size = "sm",
				layoutOrder = index,
				onClick = entry.onClick,
			})
			button.instance.LayoutOrder = index
			-- Wrapping moves a whole button; it cannot make one long action fit.
			-- Bound the intrinsic label itself so its button shrinks with the pane.
			if button.label then
				button.label.TextTruncate = Enum.TextTruncate.AtEnd
				limits[#limits + 1] = Instance.new("UISizeConstraint", button.label)
			end
		end
		local function fit()
			local width = row.AbsoluteSize.X
			if width <= 0 then return end
			for _, limit in ipairs(limits) do
				limit.MaxSize = Vector2.new(math.max(width - theme.space.md * 2, 0), math.huge)
			end
		end
		row:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
		fit()
		return row
	end

	-- Key/value facts. Read-only by definition: these are things the client observed,
	-- not things it can be told.
	function R.facts(parent, list, props)
		props = props or {}
		local box = P.frame(parent, {
			name = props.name or "Facts",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			bg = theme.color.canvas,
			radius = theme.radius.md,
			padding = theme.space.sm,
			layoutOrder = props.layoutOrder,
		})
		P.stroke(box, theme.color.borderSubtle)
		local column = P.column(box, {
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
		})
		for index, entry in ipairs(list) do
			C.keyValue(column, {
				key = entry.key,
				value = entry.value,
				layoutOrder = index,
				color = entry.tone and theme.toneColor(entry.tone) or theme.color.text,
			})
		end
		return box
	end

	return R
end
end)()

-- ==========================================================================
-- ui/shortcuts
-- ==========================================================================
__UAI_MODULES["ui/shortcuts"] = (function()
return function(env)
	local P = env.require("ui/primitives")
	local theme = env.require("ui/theme")
	local overlay = env.require("ui/overlay")
	local M = {}
	function M.open()
		local modal = overlay.modal({ title = "Keyboard shortcuts", width = theme.size.modal,
			description = "Available with the UAI window open and no text field or dialog focused." })
		if not modal then return nil end
		for index, entry in ipairs(env.require("runtime/shortcuts").items) do
			P.text(modal.content, { name = "Shortcut_" .. entry.id, text = entry.display .. "  —  " .. entry.label,
				role = "small", auto = "Y", wrap = true, size = UDim2.new(1, 0, 0, 0), layoutOrder = index })
		end
		P.text(modal.content, { text = "In command search, use Up/Down to choose and Enter to open. On touch devices, tap a result.",
			role = "caption", auto = "Y", wrap = true, color = theme.color.textSecondary,
			size = UDim2.new(1, 0, 0, 0), layoutOrder = 20 })
		P.button(modal.footer, { text = "Close", variant = "ghost", size = "sm", onClick = modal.close })
		return modal
	end
	return M
end
end)()

-- ==========================================================================
-- ui/sidebar
-- ==========================================================================
__UAI_MODULES["ui/sidebar"] = (function()
-- The sidebar: navigation, the mode switch, and the real conversation list.
--
-- Everything in here reads from `agent/session`. The list used to be three hardcoded
-- project names with eleven invented titles under them, copied from a screenshot --
-- which looked exactly right and told you nothing, and whose rows typed their own
-- label into the composer instead of opening anything. What is here now is the
-- threads the client actually has, grouped by their game or chosen folder, and
-- clicking one switches to it.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local icons = env.require("ui/icons")
	local overlay = env.require("ui/overlay")
	local P = env.require("ui/primitives")
	local profileUI = env.require("ui/profile")
	local C = env.require("ui/controls")
	local sessions = env.require("agent/session")
	local subagent = env.require("agent/subagent")
	local providers = env.require("provider/registry")
	local place = env.require("runtime/place")

	local M = {}

	-- The panels the "More" row reveals. Chat is not in it: the mode switch above is
	-- what selects between the conversation and the shared session.
	local MORE_PANELS = {
		{ id = "agents", label = "Subagents", icon = "spark" },
		{ id = "providers", label = "Providers", icon = "sliders" },
		{ id = "tools", label = "Tools", icon = "worktree" },
		{ id = "logs", label = "Logs & traces", icon = "document" },
	}

	function M.new(parent, host)
		local handle = {}

		-- One inset and one icon size for every row in here.
		--
		-- There were six of each. Row padding ran xxs, xs and md depending on which row
		-- it was, and the icon slot -- whose width is what decides where the label starts
		-- -- was written three different ways as `icon`, `icon - hair` and `icon - xxs`.
		-- The result was six different left text edges down one 240px column, two of them
		-- two pixels apart on adjacent rows. Both are also dimensionally wrong to
		-- subtract from each other: `space` scales by 0.78 under compact density and
		-- `size` by 0.86, so the gaps drifted rather than holding.
		local ROW_INSET = theme.space.sm
		local ROW_ICON = theme.size.icon
		local ROW_ROLE = theme.handheld and "sidebar" or "caption"
		local STRONG_ROLE = theme.handheld and "sidebarStrong" or "label"
		local GROUP_ROLE = theme.handheld and "sidebarStrong" or "overline"
		local PROFILE_ROLE = theme.handheld and "sidebarStrong" or "heading"

		local sidebar = P.column(parent, {
			name = "Sidebar",
			size = UDim2.fromScale(1, 1),
			-- One step of air between groups rather than the same six pixels used inside
			-- them: the nav strip, the mode switch, the new-conversation button, the action
			-- rows and the history are five separate things, and at a uniform xs they read
			-- as one undifferentiated stack.
			gap = theme.space.sm,
			padding = { x = theme.space.sm, y = theme.space.md },
		})

		-- Top row: the app menu, the collapse toggle, search, and the two history
		-- arrows. Every one of them does something; the pair that used to announce
		-- "Navigated to previous session" in a toast now actually goes there.
		--
		-- Wrap only when the selected density leaves too little room for the row.
		local topNav = P.row(sidebar, {
			name = "TopNav",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			wrap = true,
			gap = theme.space.xxs,
			layoutOrder = 1,
		})

		local function navButton(name, icon, order, onClick, enabled)
			local button = P.iconButton(topNav, {
				name = name,
				icon = icon,
				diameter = theme.size.controlSmall,
				layoutOrder = order,
				onClick = onClick,
			})
			button.instance.LayoutOrder = order
			if enabled == false then button.setEnabled(false) end
			return button
		end

		navButton("Nav_menu", "bars", 1, function()
			host.showAppMenu(topNav)
		end)
		navButton("Nav_sidebar", "sidebarToggle", 2, function()
			host.toggleSidebar()
		end)
		navButton("Nav_search", "search", 3, function()
			host.showSearch()
		end)
		handle.back = navButton("Nav_back", "arrowLeft", 4, function()
			host.back()
		end, host.canBack())
		handle.forward = navButton("Nav_forward", "arrowRight", 5, function()
			host.forward()
		end, host.canForward())

		-- Shared conversation and Code workspace destinations.
		local modeRow = P.row(sidebar, {
			name = "ModeSwitcher",
			size = UDim2.new(1, 0, 0, math.max(theme.size.controlSmall, responsive.minTarget(),
				theme.text[ROW_ROLE].height) + theme.space.hair * 2),
			bg = theme.color.surface,
			radius = theme.radius.lg,
			padding = theme.space.hair,
			gap = theme.space.hair,
			layoutOrder = 2,
			stretch = true,
		})

		local modes = {}
		local function modeButton(id, label, icon, order)
			local selected = host.panel == id
			local button = P.rowButton(modeRow, {
				name = "Segment_" .. id,
				size = UDim2.new(0, 0, 1, 0),
				flex = "Fill",
				height = theme.size.controlSmall,
				radius = theme.radius.md,
				bgSelected = theme.color.surfaceActive,
				selected = selected,
				alignX = "Center",
				gap = theme.space.xxs,
				padding = theme.space.none,
				layoutOrder = order,
				onClick = function()
					host.show(id)
				end,
			})
			button.icon(icon, 1, selected and theme.color.text or theme.color.textTertiary,
				theme.size.icon - theme.space.xxs)
			local label2 = P.text(button.row, {
				text = label,
				role = ROW_ROLE,
				color = selected and theme.color.text or theme.color.textTertiary,
				size = UDim2.new(0, 0, 0, theme.text[ROW_ROLE].height),
				auto = "X",
				flex = "Shrink",
				truncate = true,
				layoutOrder = 2,
			})
			modes[id] = { button = button, label = label2 }
			return button
		end
		modeButton("cowork", "Cowork", "terminal", 1)
		modeButton("chat", "Chat", "spark", 2)
		modeButton("code", "Code", "terminal", 3)

		-- New conversation. A real thread rather than a wipe of the current one: the
		-- list below is what makes the difference visible, and clearing in place is what
		-- the composer's own clear control is for.
		local newButton = P.button(sidebar, {
			name = "NewChat",
			text = "New conversation",
			role = theme.handheld and STRONG_ROLE or nil,
			icon = "plus",
			variant = "secondary",
			size = "md",
			fill = true,
			layoutOrder = 3,
			onClick = function()
				host.newConversation()
			end,
		})
		newButton.instance.LayoutOrder = 3

		local actions = P.column(sidebar, {
			name = "ActionRows",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 4,
		})

		-- Settings is the modal, not the stacked panel: the panel is a page you have to
		-- navigate back from, and the same categories are already arranged for a dialog
		-- with a category list. The old label here was "Customize", which named one
		-- section of the same surface.
		local settings = P.rowButton(actions, {
			name = "Settings",
			bg = nil,
			padding = { x = ROW_INSET },
			layoutOrder = 1,
			onClick = function()
				host.showSettingsDialog("general")
			end,
		})
		settings.icon("gear", 1, theme.color.textSecondary, ROW_ICON)
		settings.label("Settings", 2, theme.color.textSecondary, ROW_ROLE)

		local expanded = config.get("ui.sidebarExpanded", false) == true
		local more = P.rowButton(actions, {
			name = "More",
			padding = { x = ROW_INSET },
			layoutOrder = 2,
			onClick = function()
				expanded = not expanded
				config.set("ui.sidebarExpanded", expanded, { quiet = true })
				handle.renderMore()
			end,
		})
		local moreIcon = more.icon("chevron", 1, theme.color.textSecondary, ROW_ICON)
		more.label("More", 2, theme.color.textSecondary, ROW_ROLE)

		local moreList = P.column(actions, {
			name = "MorePanels",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.hair,
			layoutOrder = 3,
		})
		local foldersButton = P.rowButton(actions, { name = "ConversationFolders", padding = { x = ROW_INSET },
			layoutOrder = 4, onClick = function() host.manageFolders() end })
		foldersButton.icon("folder", 1, theme.color.textSecondary, ROW_ICON)
		foldersButton.label("Conversation folders", 2, theme.color.textSecondary, ROW_ROLE)

		function handle.renderMore()
			moreList.Visible = expanded
			for _, child in ipairs(moreList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			-- The chevron points at what pressing it will do.
			for _, child in ipairs(moreIcon:GetChildren()) do child:Destroy() end
			icons.chevron(moreIcon, ROW_ICON, theme.color.textSecondary,
				expanded and "up" or "down")
			if not expanded then return end
			for index, entry in ipairs(MORE_PANELS) do
				local selected = host.panel == entry.id
				local row = P.rowButton(moreList, {
					name = "NavRow_" .. entry.id,
					padding = { x = ROW_INSET },
					selected = selected,
					layoutOrder = index,
					onClick = function()
						host.show(entry.id)
					end,
				})
				row.icon(entry.icon, 1, selected and theme.color.text or theme.color.textTertiary, ROW_ICON)
				-- How many subagents are working, on the row that leads to them. A
				-- dispatch runs for minutes with nothing on screen once its card has
				-- scrolled away, so the count is the only standing sign of it.
				local label = entry.label
				if entry.id == "agents" then
					local running = #subagent.running()
					if running > 0 then label = label .. "  " .. tostring(running) end
				end
				row.label(label, 2, selected and theme.color.text or theme.color.textSecondary, ROW_ROLE)
			end
		end

		-- Same guard as the history, for the same reason: this rebuilds five rows and it
		-- is called from refresh, which runs on every status event of every turn. The
		-- three things it can show are which panel is selected, whether it is open, and
		-- how many subagents are running.
		local function moreSignature()
			return string.format("%s|%s|%d", tostring(host.panel),
				expanded and "+" or "-", #subagent.running())
		end

		function handle.syncMore(force)
			local signature = moreSignature()
			if not force and signature == handle.moreSignature then return false end
			handle.moreSignature = signature
			handle.renderMore()
			return true
		end

		handle.renderMore()
		handle.moreSignature = moreSignature()

		-- The conversation list, which takes whatever height is left rather than a
		-- hand-summed remainder: the stack above it changes height with density, with
		-- the platform's hit-target floor and with whether More is open, and a fixed
		-- offset was wrong in all three directions at once.
		local historyHolder = P.frame(sidebar, {
			name = "HistoryHolder",
			size = UDim2.new(1, 0, 0, 0),
			layoutOrder = 5,
		})
		local historyFlex = Instance.new("UIFlexItem", historyHolder)
		historyFlex.FlexMode = Enum.UIFlexMode.Fill

		local history = P.scroll(historyHolder, {
			name = "HistoryScroll",
			size = UDim2.fromScale(1, 1),
			gap = theme.space.xs,
			padding = { top = theme.space.xs, bottom = theme.space.sm },
		})
		-- Expanded navigation can exceed a short window by itself. It shares the
		-- scroll viewport with history so the profile remains reachable below it.
		actions.Parent = history.instance
		actions.LayoutOrder = 1
		local historyList = P.column(history.instance, { name = "HistoryList",
			size = UDim2.new(1, 0, 0, 0), auto = "Y", gap = theme.space.xs, layoutOrder = 3 })
		P.button(history.instance, { name = "BrowseConversations", text = "Browse conversations", variant = "ghost", size = "sm", layoutOrder = 2,
			onClick = function() env.require("ui/conversations").browse(host) end })

		-- Which place groups are folded, by placeId.
		--
		-- Stored rather than kept in a local: the list is rebuilt from scratch on every
		-- new thread, rename, delete, place change and busy transition, so a local would
		-- unfold everything several times a minute. Quiet writes, because this is a
		-- record of what the user folded and not a token anything derives from -- a noisy
		-- one would reach the theme's subscription and rebuild the whole interface.
		local function collapsedKey(group)
			return group.kind == "game" and ("ui.placeCollapsed." .. tostring(group.placeId))
				or ("ui.folderCollapsed." .. group.id)
		end

		local function isCollapsed(group)
			return config.get(collapsedKey(group), false) == true
		end

		local function setCollapsed(group, value)
			config.set(collapsedKey(group), value == true, { quiet = true })
		end

		local function sessionMenu(session, target)
			overlay.menu({
				target = target,
				width = theme.size.menu,
				options = {
					{ isHeader = true, title = session.title, subtitle = sessions.folderLabel(session) },
					{ label = "Open", value = "open", icon = "arrowRight" },
					{ label = session.metadata.pinned and "Unpin conversation" or "Pin conversation", value = "pin" },
					{ label = "Mark read", value = "read" },
					{ label = "Conversation details", value = "details" },
					{ label = "Rename", value = "rename", icon = "document" },
					{ label = "Move to folder", value = "move" },
					{ label = "Export Markdown", value = "export" },
					{ label = "Delete", value = "delete", icon = "trash", tone = "bad" },
				},
				onSelect = function(value)
					if value == "open" then
						host.openSession(session.id)
					elseif value == "pin" then session.setPinned(not session.metadata.pinned)
					elseif value == "read" then session.markRead(); session.persist()
					elseif value == "details" then env.require("ui/conversation_details").open(session)
					elseif value == "rename" then
						overlay.prompt({
							title = "Rename this conversation",
							description = "The transcript is untouched; only what the list calls it changes.",
							placeholder = "a short title",
							value = session.title,
							confirmText = "Rename",
							onConfirm = function(text)
								local ok, why = session.rename(text)
								if not ok then overlay.toast(tostring(why), "warn", 2) end
							end,
						})
					elseif value == "move" then
						host.moveConversation(session)
					elseif value == "export" then
						host.exportConversation(session)
					elseif value == "delete" then
						overlay.confirm({
							title = "Delete this conversation?",
							description = "The transcript and its file are both removed. This cannot be undone.",
							confirmText = "Delete",
							danger = true,
							onConfirm = function()
								sessions.remove(session.id)
								host.openSession(sessions.current().id)
							end,
						})
					end
				end,
			})
		end

		function handle.renderHistory()
			for _, child in ipairs(historyList:GetChildren()) do
				if child:IsA("GuiObject") then child:Destroy() end
			end
			local active = sessions.current()
			local groups = sessions.groups()
			local order = 0

			for _, group in ipairs(groups) do
				order = order + 1
				local column = P.column(historyList, {
					name = group.kind == "game" and ("Place_" .. tostring(group.placeId)) or ("Folder_" .. group.id),
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.hair,
					layoutOrder = order,
				})

				-- The group header is the fold control, so the whole line answers a click
				-- rather than a chevron nobody can hit. The count rides on it because a
				-- folded group has to say how much it is hiding -- otherwise folding one
				-- loses the only sign those conversations exist.
				local collapsed = isCollapsed(group)
				local head = P.rowButton(column, {
					name = "PlaceHead",
					height = theme.size.rowTight,
					-- The same inset as the rows it heads. It was xxs against their xs, so
					-- a group's name sat two pixels left of every conversation under it.
					padding = { x = ROW_INSET },
					gap = theme.space.xs,
					layoutOrder = 1,
					onClick = function()
						setCollapsed(group, not isCollapsed(group))
						-- Through the signature, so the fold state it just wrote becomes the
						-- baseline the next change is compared against.
						handle.syncHistory()
					end,
				})
				-- Points at what pressing it will do, like the More row above.
				local caret = P.frame(head.row, {
					name = "PlaceCaret",
					size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
					layoutOrder = 1,
				})
				icons.chevron(caret, theme.size.icon, theme.color.textTertiary,
					collapsed and "right" or "down")
				P.text(head.row, {
					name = "PlaceName",
					text = group.label,
					role = GROUP_ROLE,
					color = theme.color.textTertiary,
					size = UDim2.new(0, 0, 0, theme.text[GROUP_ROLE].height),
					flex = "Fill",
					truncate = true,
					layoutOrder = 2,
				})
				-- How many are in there, and how many of those are working. The second
				-- number is the reason a fold is safe to leave shut: a group with a turn
				-- running in it still says so from the header.
				local busyCount = 0
				for _, session in ipairs(group.sessions) do
					if session.busy then busyCount = busyCount + 1 end
				end
				if busyCount > 0 then
					local slot = P.frame(head.row, {
						name = "PlaceBusy",
						size = UDim2.fromOffset(theme.size.icon, theme.size.icon),
						layoutOrder = 3,
					})
					C.spinner(slot, {
						diameter = theme.size.icon,
						anchor = Vector2.new(0.5, 0.5),
						position = UDim2.fromScale(0.5, 0.5),
					})
				end
				local countLabel = P.text(head.row, {
					name = "PlaceCount",
					text = tostring(#group.sessions),
					role = ROW_ROLE,
					color = theme.color.textTertiary,
					align = "Right",
					auto = "X",
					layoutOrder = 4,
				})
				countLabel.Size = UDim2.fromOffset(0, theme.text[ROW_ROLE].height)
				-- Custom folders and Universal are available in every game.
				if group.current or group.kind ~= "game" then
					local plus = P.iconButton(head.row, {
						name = group.kind == "game" and "NewInPlace" or "NewInFolder",
						icon = "plus",
						diameter = theme.size.rowTight,
						layoutOrder = 5,
						onClick = function()
							host.newConversation(group.id)
						end,
					})
					plus.instance.LayoutOrder = 5
				end

				-- The rows go in a holder of their own so folding hides one frame rather
				-- than each row: a hidden child still takes its slot in a list layout only
				-- if the layout can see it, and hiding thirty of them one at a time is
				-- thirty writes where one will do.
				local body = P.column(column, {
					name = "PlaceSessions",
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.hair,
					layoutOrder = 2,
					visible = not collapsed,
				})

				for index, session in ipairs(group.sessions) do
					local selected = session.id == active.id
					local row = P.rowButton(body, {
						name = "SessionRow",
						height = theme.size.rowSmall,
						padding = { x = ROW_INSET },
						selected = selected,
						layoutOrder = index,
						onClick = function()
							host.openSession(session.id)
						end,
					})
					-- The leading slot is always there and usually empty.
					--
					-- It used to hold a hollow circle per row and a filled dot on the active
					-- one: a column of bullets down a 240px list whose only job was to say
					-- which row was selected, which the row's own highlight already says and
					-- says better. The slot itself stays, at the icon's width, because it is
					-- what puts every title on the same left edge as the group name above it
					-- -- and because a spinner has to be able to appear in a row without
					-- moving that row's text.
					--
					-- The spinner is the one thing here that survived: a conversation you are
					-- not looking at can still be working, leaving one does not stop it, and
					-- that is the one fact a row cannot state any other way. It is also the
					-- reason the list refreshes on every busy transition.
					local slot = P.frame(row.row, {
						name = "IconSlot",
						size = UDim2.fromOffset(ROW_ICON, ROW_ICON),
						layoutOrder = 1,
					})
					if session.busy then
						C.spinner(slot, {
							diameter = ROW_ICON,
							anchor = Vector2.new(0.5, 0.5),
							position = UDim2.fromScale(0.5, 0.5),
						})
					end
					local titleText = session.title
					local detail = env.require("runtime/conversation_metadata").label(session.metadata)
					if detail ~= "" then titleText = titleText .. "  (" .. detail .. ")" end
					if session.ephemeral then titleText = titleText .. "  (not saved)" end
					row.label(titleText, 2,
						selected and theme.color.text or (session.metadata.failures > 0 and theme.color.warn or theme.color.textSecondary),
						selected and STRONG_ROLE or ROW_ROLE)
					local menuButton = P.iconButton(row.row, {
						name = "SessionMenu",
						icon = "ellipsis",
						diameter = theme.size.rowTight,
						layoutOrder = 3,
						onClick = function(button)
							sessionMenu(session, button.instance)
						end,
					})
					menuButton.instance.LayoutOrder = 3
				end
			end

			if order == 0 then
				local empty = P.text(historyList, {
					name = "NoHistory",
					text = "Your conversations will appear here, organized by folder.",
					role = ROW_ROLE,
					color = theme.color.textTertiary,
					wrap = true,
					auto = "Y",
					padding = { x = ROW_INSET },
					layoutOrder = 1,
				})
				empty.Size = UDim2.new(1, 0, 0, 0)
			end
		end

		handle.renderHistory()

		P.divider(sidebar, { color = theme.color.borderSubtle, layoutOrder = 6 })

		-- A distinct identity control, with room for a headshot and two readable lines.
		local identity = profileUI.identity()
		local identityHeight = theme.text[PROFILE_ROLE].height + theme.text[ROW_ROLE].height
		local profile, profileMenu, chevron
		profile = P.rowButton(sidebar, {
			name = "ProfileBar",
			-- Matched to the chat composer's *visible* box, not its shell. The composer
			-- shell is taller (control + sm*3 + xxs) but its bordered surface is inset
			-- within it at control + sm*2; the profile bar is a bordered box that fills
			-- its whole height. Sizing to the surface is what makes the two read as the
			-- same height where they dock side by side at the bottom of the window.
			height = math.max(math.max(theme.size.control, responsive.minTarget()) + theme.space.sm * 2,
				identityHeight + theme.space.hair * 2),
			bg = theme.color.surface,
			radius = theme.radius.lg,
			stroke = true,
			gap = theme.space.md,
			padding = { x = ROW_INSET },
			layoutOrder = 7,
			onClick = function()
				if profileMenu and not profileMenu.closed then profileMenu.close(); return end
				profileMenu = host.showProfileMenu(profile.instance, function()
					if not profile.instance.Parent then return end
					profile.setSelected(false)
					chevron.Rotation = 0
				end)
				if profileMenu and not profileMenu.closed then
					profile.setSelected(true)
					chevron.Rotation = 180
				end
			end,
		})
		profileUI.avatar(profile.row, identity, theme.size.profileAvatar, 1)
		local profileText = P.column(profile.row, {
			name = "ProfileIdentity",
			size = UDim2.new(0, 0, 0, identityHeight),
			flex = "Fill",
			gap = theme.space.none,
			alignY = "Center",
			layoutOrder = 2,
		})
		P.text(profileText, {
			name = "ProfileName",
			text = identity.name,
			role = PROFILE_ROLE,
			size = UDim2.new(1, 0, 0, theme.text[PROFILE_ROLE].height),
			alignY = "Bottom",
			color = theme.color.text,
			truncate = true,
			layoutOrder = 1,
		})
		local profileDetail = P.text(profileText, {
			name = "ProfileProvider",
			text = profileUI.providerLabel(),
			role = ROW_ROLE,
			size = UDim2.new(1, 0, 0, theme.text[ROW_ROLE].height),
			alignY = "Top",
			color = theme.color.textTertiary,
			truncate = true,
			layoutOrder = 2,
		})
		chevron = P.frame(profile.row, {
			name = "ProfileChevron",
			size = UDim2.fromOffset(ROW_ICON, ROW_ICON),
			layoutOrder = 3,
		})
		icons.chevron(chevron, ROW_ICON, theme.color.textTertiary, "up")

		-- What the list currently shows, as a string.
		--
		-- The list is rebuilt from destroyed instances, and everything that can change it
		-- -- a new thread, a rename, a delete, a switch, a busy transition, a place
		-- resolving -- arrives as the same signal with no description of what moved. So
		-- the cheap thing is to ask whether the answer would differ before spending
		-- thirty instances per row finding out that it would not.
		--
		-- This is the stutter. `session.emit` fires listChanged on send, and app.syncNav
		-- runs on every status event -- of which a turn emits one per step plus one per
		-- request -- and each of those was tearing down and rebuilding every row in the
		-- sidebar. A twelve-conversation client spent about 1800 instance constructions
		-- per turn redrawing a list whose contents had not changed since the first one.
		local function listSignature()
			local parts = { tostring(sessions.activeId) }
			for _, group in ipairs(sessions.groups()) do
				parts[#parts + 1] = string.format("%s|%s|%s",
					tostring(group.id), tostring(group.label),
					isCollapsed(group) and "-" or "+")
				for _, session in ipairs(group.sessions) do
					parts[#parts + 1] = string.format("%s\1%s\1%s\1%s\1%s",
						tostring(session.id), tostring(session.title),
						session.busy and "b" or "-", session.ephemeral and "e" or "-", env.require("runtime/conversation_metadata").label(session.metadata))
				end
			end
			return table.concat(parts, "\2")
		end

		-- The list, only if it would look different. `force` is for the paths that know
		-- it changed for a reason the signature cannot see -- a fold, a theme rebuild.
		local function refreshHistory(force)
			if not sidebar.Parent then return false end
			local signature = listSignature()
			if not force and signature == handle.signature then return false end
			handle.signature = signature
			handle.renderHistory()
			return true
		end
		-- Host scripts can create many background conversations in one turn. Keep
		-- one pending layout instead of rebuilding the full list for each signal.
		local updateHistory, cancelHistory = clock.debounce(function() refreshHistory(false) end, 0)
		function handle.syncHistory(force)
			if force then cancelHistory(); return refreshHistory(true) end
			if not sidebar.Parent or listSignature() == handle.signature then return false end
			updateHistory(); return true
		end

		function handle.refresh()
			profileDetail.Text = profileUI.providerLabel()
			for id, entry in pairs(modes) do
				local selected = host.panel == id
				entry.button.setSelected(selected)
				entry.label.TextColor3 = selected and theme.color.text or theme.color.textTertiary
			end
			handle.back.setEnabled(host.canBack())
			handle.forward.setEnabled(host.canForward())
			handle.syncMore()
			handle.syncHistory()
		end

		handle.signature = listSignature()

		-- The list is the app's own state: a new thread, a rename, a delete or a switch
		-- all have to show up here without the panel knowing this exists.
		local unsubscribeSessions = sessions.listChanged:connect(function()
			if not sidebar.Parent then return end
			handle.syncHistory()
		end)
		local unsubscribeProviders = providers.changed:connect(function()
			if not sidebar.Parent then return end
			profileDetail.Text = profileUI.providerLabel()
		end)
		local unsubscribePlace = place.changed:connect(function()
			if not sidebar.Parent then return end
			-- The place decides a group's label, which the signature covers.
			handle.syncHistory()
		end)
		-- Only count changes affect navigation. Streaming text and tool progress must
		-- not schedule a new delayed task or postpone the count indefinitely.
		local agentCount = #subagent.running()
		local refreshAgents, cancelAgents = clock.debounce(function()
			if not sidebar.Parent then return end
			handle.syncMore()
		end, 0.3)
		local unsubscribeAgents = subagent.changed:connect(function()
			local count = #subagent.running()
			if count == agentCount then return end
			agentCount = count
			refreshAgents()
		end)

		sidebar.Destroying:Connect(function()
			pcall(unsubscribeSessions)
			pcall(unsubscribeProviders)
			pcall(unsubscribePlace)
			pcall(unsubscribeAgents)
			cancelAgents()
			cancelHistory()
		end)

		handle.instance = sidebar
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- ui/theme
-- ==========================================================================
__UAI_MODULES["ui/theme"] = (function()
-- Design tokens.
--
-- Every colour, size, radius, weight and duration in the interface comes from
-- here. No use site writes a literal, which is the only way a project this size
-- stays coherent -- and it is what lets density, accent and text scale change at
-- runtime without hunting through forty files.
--
-- The palette is a warm neutral, not a cool one, and not pure black. Warm because
-- the whole ramp is one hue family with the accent -- a coral -- so a page of prose
-- with two inline code spans in it reads as one material rather than as grey with
-- orange stuck on. Not pure black because on an OLED phone pure black next to a 1px
-- hairline reads as a seam, and a slight lift keeps the surface hierarchy legible at
-- low brightness.
--
-- The lightness steps are deliberately close together at the dark end. The interface
-- it is modelled on separates a sidebar from a canvas from a card by two or three
-- percent of lightness and a hairline, never by a shadow or a heavy fill, and that is
-- what makes it read as flat rather than as a stack of boxes.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local signal = env.require("runtime/signal")
	local seasonal = env.require("runtime/seasonal_theme")
	local clock = env.require("runtime/clock")
	local dispose = env.require("runtime/dispose")

	local M = { changed = signal.new("theme") }

	local function rgb(r, g, b)
		return Color3.fromRGB(r, g, b)
	end

	-- Roblox has no alpha on Color3, so anything that would be a translucent
	-- overlay is pre-blended against the surface it sits on.
	function M.mix(from, to, alpha)
		return from:Lerp(to, util.clamp(alpha, 0, 1))
	end

	local NEUTRAL = {
		[0] = rgb(23, 23, 22),
		[1] = rgb(30, 30, 28),
		[2] = rgb(35, 35, 33),
		[3] = rgb(42, 42, 39),
		[4] = rgb(50, 50, 46),
		[5] = rgb(62, 62, 57),
		[6] = rgb(74, 74, 71),
		[7] = rgb(92, 91, 86),
		[8] = rgb(108, 107, 102),
		[9] = rgb(163, 161, 152),
		[10] = rgb(194, 191, 181),
		[11] = rgb(245, 244, 238),
	}

	-- Accents, all landing in the same lightness band so switching one does not
	-- change how loud the interface feels. The coral is the default and the one the
	-- rest of the palette is tuned around; the others are kept because someone who
	-- picked teal a version ago should not have it silently taken away.
	local ACCENTS = {
		claude = { base = rgb(217, 119, 87), hot = rgb(232, 146, 117), label = "Coral" },
		aurora = { base = rgb(58, 205, 186), hot = rgb(96, 226, 208), label = "Aurora" },
		indigo = { base = rgb(122, 136, 255), hot = rgb(153, 165, 255), label = "Indigo" },
		amber = { base = rgb(226, 160, 74), hot = rgb(243, 184, 108), label = "Amber" },
		rose = { base = rgb(240, 108, 138), hot = rgb(249, 142, 166), label = "Rose" },
	}

	M.ACCENTS = ACCENTS

	-- Seasonal ramps retain the same surface hierarchy and readable text roles.
	-- The saved standard accent remains separate from the effective holiday accent.
	local SEASONAL = {
		valentine = {
			art = "Valentine",
			accent = { base = rgb(246, 144, 168), hot = rgb(255, 178, 194) },
			neutral = {
				[0] = rgb(28, 18, 24), rgb(35, 24, 30), rgb(42, 29, 36), rgb(49, 35, 43),
				rgb(57, 42, 51), rgb(70, 53, 63), rgb(83, 66, 77), rgb(102, 84, 96),
				rgb(120, 103, 115), rgb(185, 163, 175), rgb(221, 197, 207), rgb(253, 239, 235),
			},
		},
		earthday = {
			art = "EarthDay",
			accent = { base = rgb(147, 205, 118), hot = rgb(180, 228, 155) },
			neutral = {
				[0] = rgb(16, 25, 27), rgb(22, 32, 34), rgb(28, 38, 40), rgb(34, 45, 47),
				rgb(41, 53, 55), rgb(52, 66, 68), rgb(64, 79, 81), rgb(81, 97, 99),
				rgb(99, 116, 117), rgb(163, 184, 179), rgb(195, 216, 205), rgb(243, 247, 230),
			},
		},
		pride = {
			art = "Pride",
			accent = { base = rgb(231, 142, 216), hot = rgb(248, 182, 237) },
			activityBlue = rgb(83, 204, 232), activityBlueLight = rgb(133, 231, 250), activityBlueDark = rgb(59, 155, 178),
			neutral = {
				[0] = rgb(23, 18, 33), rgb(30, 24, 42), rgb(37, 29, 50), rgb(44, 35, 58),
				rgb(52, 43, 67), rgb(65, 54, 80), rgb(77, 66, 93), rgb(96, 83, 112),
				rgb(114, 102, 129), rgb(183, 166, 199), rgb(218, 201, 232), rgb(250, 240, 254),
			},
		},
		peace = {
			art = "Peace",
			accent = { base = rgb(129, 196, 232), hot = rgb(169, 223, 250) },
			neutral = {
				[0] = rgb(19, 26, 29), rgb(26, 33, 37), rgb(32, 40, 44), rgb(39, 47, 52),
				rgb(46, 55, 60), rgb(58, 68, 74), rgb(70, 82, 88), rgb(88, 100, 106),
				rgb(105, 118, 124), rgb(170, 187, 195), rgb(203, 222, 226), rgb(239, 247, 246),
			},
		},
		halloween = {
			art = "Halloween",
			accent = { base = rgb(242, 153, 74), hot = rgb(255, 184, 112) },
			neutral = {
				[0] = rgb(23, 17, 28), rgb(30, 22, 35), rgb(35, 27, 40), rgb(43, 32, 47),
				rgb(50, 39, 55), rgb(64, 50, 68), rgb(77, 63, 82), rgb(96, 81, 99),
				rgb(115, 100, 115), rgb(181, 161, 178), rgb(217, 196, 210), rgb(250, 241, 226),
			},
		},
		christmas = {
			art = "Christmas",
			accent = { base = rgb(242, 124, 134), hot = rgb(255, 156, 158) },
			neutral = {
				[0] = rgb(17, 25, 23), rgb(24, 32, 28), rgb(29, 38, 33), rgb(36, 45, 39),
				rgb(43, 53, 46), rgb(55, 66, 57), rgb(67, 78, 69), rgb(85, 95, 84),
				rgb(102, 113, 102), rgb(163, 181, 165), rgb(196, 212, 194), rgb(246, 244, 226),
			},
		},
		newyear = {
			art = "NewYear",
			accent = { base = rgb(235, 191, 87), hot = rgb(250, 212, 124) },
			neutral = {
				[0] = rgb(18, 22, 32), rgb(25, 29, 41), rgb(31, 35, 48), rgb(38, 42, 56),
				rgb(46, 50, 64), rgb(58, 62, 76), rgb(70, 75, 90), rgb(88, 92, 109),
				rgb(105, 110, 128), rgb(170, 178, 199), rgb(204, 211, 227), rgb(245, 243, 230),
			},
		},
	}

	-- Type resolution, in two layers.
	--
	-- `Enum.Font` is the legacy pairing of a family with one baked-in weight --
	-- BuilderSansMedium is a member, and there is no way to ask that family for
	-- anything else. `FontFace` is the modern one: a family asset plus an independent
	-- weight axis, so a single family yields Regular, Medium and SemiBold rather than
	-- whichever pairs somebody happened to enumerate. Having the weight axis is most
	-- of the difference between type that reads as an application and type that reads
	-- as a 2016 forum: hierarchy comes from 400/500/600 at one or two sizes, not from
	-- jumping the size every level because only two weights exist.
	--
	-- The family string is never written here. It is read back off the engine with
	-- Font.fromEnum, so a family this client cannot load can never be named. A
	-- hardcoded rbxasset path has the opposite failure mode: it constructs fine and
	-- renders nothing, and there is no way to detect that from Lua.
	local function enumFont(name)
		local ok, item = pcall(function() return Enum.Font[name] end)
		if ok and item then return item end
		return nil
	end

	local function fontOr(name, fallback)
		return enumFont(name) or fallback
	end

	local function familyOf(name)
		local item = enumFont(name)
		if not item then return nil end
		local ok, face = pcall(function() return Font.fromEnum(item) end)
		if ok and face and type(face.Family) == "string" and face.Family ~= "" then
			return face.Family
		end
		return nil
	end

	-- Which point on the weight axis each role asks for. `strong` is SemiBold rather
	-- than Bold: at 15 and 16 pixels Bold on a dark ground blooms and reads as shouting,
	-- and 600 is what the interface this follows uses for a title.
	local WEIGHTS = { regular = "Regular", medium = "Medium", strong = "SemiBold" }

	local function faceFor(family, weight)
		if not family then return nil end
		local ok, face = pcall(function()
			return Font.new(family,
				Enum.FontWeight[WEIGHTS[weight] or "Regular"],
				Enum.FontStyle.Normal)
		end)
		if ok and face then return face end
		return nil
	end

	local SANS = fontOr("BuilderSans", Enum.Font.Gotham)
	local SANS_MEDIUM = fontOr("BuilderSansMedium", Enum.Font.GothamMedium)

	-- The interface and code families a person can actually pick from.
	--
	-- A free-text font field is the one control in the reference client that cannot be
	-- honest here: Roblox renders from a fixed set of families and cannot load a name it
	-- was handed, so naming JetBrains Mono in a box would change nothing. What is
	-- offered instead is the set that exists *on this client*, discovered rather than
	-- declared -- every candidate below is probed against the engine and dropped if it
	-- does not resolve, so an older client shows a shorter list instead of a list with
	-- dead entries in it.
	--
	-- Every name here is a real member of Enum.Font. That is not a stylistic point: an
	-- invented one would be silently dropped by the probe on a real client and silently
	-- *accepted* by the test harness, whose Enum proxy resolves anything asked of it --
	-- so a typo would surface as a font option that exists only in the tests.
	local INTERFACE_CANDIDATES = {
		-- Montserrat leads: a contemporary geometric sans with a full weight axis,
		-- which reads as a modern interface face at the sizes this project uses.
		-- The order below is the fallback chain, so a client missing a family gets
		-- the next most contemporary one rather than the last.
		{ id = "montserrat", label = "Montserrat", regular = "Montserrat", medium = "MontserratMedium" },
		{ id = "builder", label = "Builder Sans", regular = "BuilderSans", medium = "BuilderSansMedium" },
		{ id = "arimo", label = "Arimo", regular = "Arimo", medium = "ArimoBold" },
		{ id = "roboto", label = "Roboto", regular = "Roboto", medium = "Roboto" },
		{ id = "nunito", label = "Nunito", regular = "Nunito", medium = "Nunito" },
		{ id = "titillium", label = "Titillium Web", regular = "TitilliumWeb", medium = "TitilliumWeb" },
		{ id = "ubuntu", label = "Ubuntu", regular = "Ubuntu", medium = "Ubuntu" },
		{ id = "source", label = "Source Sans", regular = "SourceSans", medium = "SourceSansSemibold" },
		{ id = "gotham", label = "Gotham", regular = "Gotham", medium = "GothamMedium" },
	}

	-- Two, because Enum.Font has two monospace families and no more. Anything else a
	-- code editor would reach for -- JetBrains Mono, Inconsolata, Fira -- is not in the
	-- engine, and offering it would be offering nothing.
	local CODE_CANDIDATES = {
		{ id = "code", label = "Source Code Pro", regular = "Code" },
		{ id = "roboto", label = "Roboto Mono", regular = "RobotoMono" },
	}

	-- Resolution happens once, at load. Probing is a dozen pcalls; doing it per rebuild
	-- would repeat them on every accent change.
	local function resolveFamilies(candidates, fallbackEnum)
		local byId, order = {}, {}
		for _, entry in ipairs(candidates) do
			local regular = enumFont(entry.regular)
			local family = familyOf(entry.regular)
			-- Kept when either layer works: the family gives the weight axis, the enum
			-- alone still renders. Dropped only when the client has neither.
			if regular or family then
				byId[entry.id] = {
					id = entry.id,
					label = entry.label,
					family = family,
					enumName = entry.regular,
					regular = regular or fallbackEnum,
					medium = fontOr(entry.medium or entry.regular, regular or fallbackEnum),
					faces = {
						regular = faceFor(family, "regular"),
						medium = faceFor(family, "medium"),
						strong = faceFor(family, "strong"),
					},
				}
				order[#order + 1] = entry.id
			end
		end
		return byId, order
	end

	local INTERFACE_FONTS, INTERFACE_ORDER = resolveFamilies(INTERFACE_CANDIDATES, SANS)
	local CODE_FONTS, CODE_ORDER = resolveFamilies(CODE_CANDIDATES, Enum.Font.Code)

	M.INTERFACE_FONTS = INTERFACE_FONTS
	M.INTERFACE_ORDER = INTERFACE_ORDER
	M.CODE_FONTS = CODE_FONTS
	M.CODE_ORDER = CODE_ORDER

	-- The first candidate that resolved, which is the most contemporary family this
	-- client has. Named rather than assumed: on a client old enough to be missing
	-- Builder Sans the default has to move, and a stored setting naming a family that
	-- is not here has to fall back to something rather than to nil.
	M.defaultInterfaceFont = INTERFACE_ORDER[1] or "gotham"
	M.defaultCodeFont = CODE_ORDER[1] or "code"

	-- The two code palettes the appearance pane previews and the transcript uses.
	--
	-- Light is a real option rather than a swatch: a code block on a light card in a
	-- dark interface is what the reference client does, and the setting has to change
	-- what a fenced block in the transcript looks like or it is decoration.
	local CODE_THEMES = {
		dark = {
			label = "Claude Dark",
			surface = NEUTRAL[0],
			border = NEUTRAL[4],
			bar = NEUTRAL[2],
			text = NEUTRAL[11],
			-- Line numbers and the language label. It has to clear 3:1 on the bar it
			-- sits on: a gutter nobody can read is a column of noise down the left.
			gutter = NEUTRAL[9],
			addSurface = rgb(24, 54, 34),
			addText = rgb(126, 217, 148),
			removeSurface = rgb(64, 28, 32),
			removeText = rgb(240, 138, 132),
			keyword = rgb(201, 171, 235),
			string = rgb(165, 201, 148),
			number = rgb(227, 184, 134),
			comment = NEUTRAL[9],
			call = rgb(149, 193, 225),
		},
		light = {
			label = "Claude Light",
			surface = rgb(250, 249, 245),
			border = rgb(214, 211, 202),
			bar = rgb(237, 235, 228),
			text = rgb(38, 38, 36),
			gutter = rgb(104, 102, 95),
			addSurface = rgb(219, 245, 226),
			addText = rgb(21, 105, 55),
			removeSurface = rgb(252, 226, 226),
			removeText = rgb(163, 32, 32),
			keyword = rgb(116, 63, 156),
			string = rgb(53, 106, 43),
			number = rgb(144, 81, 23),
			comment = rgb(103, 104, 94),
			call = rgb(31, 96, 147),
		},
	}
	local CODE_THEME_ORDER = { "dark", "light" }

	M.CODE_THEMES = CODE_THEMES
	M.CODE_THEME_ORDER = CODE_THEME_ORDER

	-- Line heights, named. Four of them were loose numbers inside the type table and
	-- three more were repeated at use sites that needed a label to sit on a control's
	-- centre line -- a title at the reading measure of 1.6 is 40px of box around 16px
	-- of glyph, which is why the window header's two lines had one pixel of air above
	-- and below them.
	-- `code` is the loosest of them on purpose. A block of output is read one line at
	-- a time, looking for the one that matters, and at the 1.5 the rest of the mono
	-- text uses, eleven lines of `key: value` arrive as a solid slab -- the gaps
	-- between the lines are what the eye scans down.
	M.line = { tight = 1.2, snug = 1.35, normal = 1.5, reading = 1.6, code = 1.65 }

	-- Body text is the one thing in here a person actually reads, so it gets the
	-- room: 15 on a 1.6 line, which is a reading measure rather than a UI measure.
	-- Everything that is not prose is quieter and tighter than it used to be --
	-- headings a step down, labels one weight rather than bold-and-uppercase --
	-- because the interface this follows gets its hierarchy from spacing and colour,
	-- not from size. A 22px bold display over 13px body is a dashboard; this is a
	-- document with controls at the edges.
	--
	-- `weight` names a point on the family's weight axis rather than a font, because
	-- the family is a setting: the interface font and the code font are both pickable,
	-- and a resolved Enum.Font baked in here could not follow them.
	local BASE_TEXT = {
		display = { size = 22, weight = "strong", line = M.line.tight },
		title = { size = 17, weight = "strong", line = M.line.tight },
		heading = { size = 15, weight = "medium", line = M.line.snug },
		body = { size = 15, weight = "regular", line = M.line.reading },
		bodyStrong = { size = 15, weight = "medium", line = M.line.reading },
		small = { size = 13, weight = "regular", line = M.line.normal },
		label = { size = 12, weight = "medium", line = M.line.tight },
		caption = { size = 12, weight = "regular", line = M.line.snug },
		-- Navigation has less room than conversation text on the handheld sidebar.
		sidebar = { size = 12, mobileSize = 9, weight = "regular", line = M.line.snug },
		sidebarStrong = { size = 12, mobileSize = 9, weight = "medium", line = M.line.tight },
		overline = { size = 11, weight = "medium", line = M.line.tight },
		mono = { size = 13, weight = "mono", line = M.line.normal },
		monoSmall = { size = 12, weight = "mono", line = M.line.normal },
	}

	local BASE_SPACE = {
		none = 0, hair = 2, xxs = 4, xs = 6, sm = 8, md = 12, lg = 16, xl = 20, xxl = 28, huge = 40,
	}

	local BASE_SIZE = {
		codeToolbar = 38,
		codeStatus = 22,
		codeWide = 800,
		codeOutput = 170,
		codeGutter = 44,
		codeOverscan = 8,
		control = 34,      -- default button / field height
		controlSmall = 28,
		controlLarge = 42,
		icon = 16,
		iconLarge = 20,
		row = 36,
		-- Tall enough for two lines of chrome plus air. At 42 the window header's title
		-- and subtitle -- 40px of type between them at the reading measure -- had a
		-- single pixel above and below, so the title touched the window's top edge.
		header = 56,
		seasonalArt = 72,
		seasonalArtMinContent = 160,
		rail = 52,
		tab = 30,
		launcher = 44,
		scrollbar = 4,
		avatar = 26,
		profileAvatar = 40,
		profileAvatarLarge = 48,
		-- The switch. `switchWide` is the width, kept as a token because it was a
		-- hardcoded 38 that four panels each reserved a hand-summed 46 for -- every one
		-- of which would have gone wrong the moment either number moved. Those rows now
		-- fill instead of reserving, but the size still belongs here.
		switch = 20,
		switchWide = 34,
		-- Slider and progress geometry.
		track = 3,
		knob = 12,
		-- The label column in a key/value list, wide enough for the longest key any
		-- panel in here uses.
		keyColumn = 104,
		-- Status dots, and the right-hand column a transcript row puts a duration or a
		-- progress count in. Both were literals repeated at five and three sites
		-- respectively, with two of the dot sizes disagreeing by a pixel.
		dot = 6,
		dotSmall = 4,
		metaColumn = 52,
		metaColumnWide = 88,
		-- Overlay widths. Twelve independent literals between 160 and 420 used to
		-- decide how wide a menu, a dropdown or a dialog was, which is why no two
		-- dialogs in here were the same width.
		menu = 200,
		menuMin = 160,
		menuWide = 320,
		menuMax = 320,
		modal = 380,
		modalWide = 480,
		modalMin = 260,
		modalTall = 620,
		-- The provider gallery is the first screen of the add flow: a wide card list
		-- needs room for a name, a sentence and an access line without wrapping every
		-- card onto three lines.
		providerPicker = 640,
		providerPickerTall = 640,
		modalHistory = 580,
		modalCode = 420,
		formTextarea = 108,
		promptTextarea = 120,
		-- The reading column. Past roughly this width a line of prose becomes a single
		-- sentence a foot long, which is unreadable however correct the layout is.
		-- Overridden by the transcript-width setting, which is why the three widths it
		-- offers are tokens too rather than numbers in a panel.
		codeViewport = 380,
		reading = 1000,
		readingNarrow = 720,
		readingMedium = 860,
		sidebar = 248,
		-- Dense list furniture: a session row in the sidebar, a group header above it,
		-- the pinned profile bar at the bottom, a chip in the composer.
		rowSmall = 30,
		rowTight = 22,
		bar = 36,
		chip = 26,
		-- Chat-only geometry: a full-width prompt above an independent toolbar.
		composerPrompt = 44,
		composerExpanded = 144,
		composerModel = 144,
		composerModelMin = 76,
		composerFieldMin = 240,
		promptCard = 88,
		promptColumns = 480,
		modelPicker = 540,
		modelPickerHeight = 560,
		thinkingViewport = 180,
		tableColumnMin = 104,
		tableColumnMax = 320,
		tableViewport = 380,
		-- The home card: its column, one metric tile, and one cell of the activity
		-- grid. All three were literals in the surface that drew them.
		statCard = 560,
		statTile = 56,
		cell = 11,
		-- The settings dialog, which is a window of its own rather than a modal card.
		dialog = 760,
		dialogTall = 520,
		dialogNav = 190,
	}

	-- Corners are tighter than they were. A 16px radius on a card reads as a mobile
	-- widget; 6 to 10 reads as a document panel, which is what this is.
	local BASE_RADIUS = { none = 0, xs = 2, sm = 6, md = 8, lg = 12, xl = 16, pill = 999 }
	M.radius = {}
	M.stroke = { hair = 1, focus = 2 }

	-- The visual constants that are neither a colour nor a size. They were literals
	-- at half a dozen use sites, which is how the modal scrim ended up at 0.45 and the
	-- quick-chat scrim -- the same effect, one layer up -- at 0.5.
	M.opacity = { scrollbar = 0.4, scrim = 0.5, dim = 0.6 }

	-- How far a surface is scaled down as it enters. Small on purpose: a panel that
	-- springs in from 0.9 is a phone app, and three surfaces here were each doing it
	-- by a slightly different amount.
	M.scale = { enter = 0.98 }

	M.motion = {
		-- Durations, in seconds, for a caller that needs a number rather than a tween.
		fast = 0.12,
		base = 0.18,
		slow = 0.3,
		-- Tweens. `instant` is a real TweenInfo rather than a zero, because the thing
		-- callers actually want from it is "apply this now" through the same
		-- TweenService path as every other paint -- a bare 0 is not a TweenInfo and
		-- cannot be passed to Create at all.
		instant = TweenInfo.new(0.01, Enum.EasingStyle.Linear),
		enter = TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		exit = TweenInfo.new(0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
		-- Bounded overlays fade as a unit at their final geometry. A short,
		-- non-overshooting curve keeps repeated prompts calm and responsive.
		modalEnter = TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		modalExit = TweenInfo.new(0.10, Enum.EasingStyle.Quad, Enum.EasingDirection.In),
		hover = TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		press = TweenInfo.new(0.08, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		slide = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
		-- The repeating pair. These are the only tweens here with a negative repeat
		-- count, and they deliberately do not go through M.tween: collapsing the
		-- duration to 0.01s for reduced motion would spin them at a hundred hertz
		-- rather than stop them. Callers check responsive.reduceMotion themselves and
		-- skip the tween entirely.
		spin = TweenInfo.new(0.9, Enum.EasingStyle.Linear, Enum.EasingDirection.InOut, -1),
		pulse = TweenInfo.new(0.85, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut, -1, true),
	}

	-- A dropdown is always opened from something, so it has to sit above whatever
	-- opened it -- including a modal. It used to rank below one, which is why the
	-- preset menu in the Add provider dialog opened behind the dialog.
	M.z = { base = 1, raised = 10, header = 20, overlay = 100, modal = 160, dropdown = 200, quick = 210, toast = 240 }

	-- Recomputed whenever density, accent or text scale changes.
	function M.rebuild()
		local accentName = config.get("ui.accent", "claude")
		local accent = ACCENTS[accentName] or ACCENTS.claude
		M.themeName = seasonal.resolve(config.get("ui.theme", "default"), config.get("ui.seasonalThemes", true))
		local holiday = SEASONAL[M.themeName]
		M.seasonalArtName = holiday and holiday.art or nil
		local neutral = holiday and holiday.neutral or NEUTRAL
		if holiday then accent = holiday.accent end
		local density = config.get("ui.density", "comfortable")
		local compact = density == "compact"
		local textScale = util.clamp(tonumber(config.get("ui.fontScale", 1)) or 1, 0.85, 1.4)
		local spaceScale = compact and 0.78 or 1
		local sizeScale = compact and 0.86 or 1
		-- One interface, rendered with smaller native metrics on handheld devices.
		-- Keep this independent of orientation and keyboard height: rotating must
		-- relayout the existing fields, not rebuild them or resample their text.
		M.handheld = env.require("ui/responsive").isMobile()
		M.metricScale = M.handheld and 0.55 or 1
		spaceScale = spaceScale * M.metricScale
		sizeScale = sizeScale * M.metricScale
		for name, value in pairs(BASE_RADIUS) do
			M.radius[name] = name == "pill" and value or math.floor(value * M.metricScale + 0.5)
		end

		M.accentName = accentName
		M.density = density

		-- Families. Both layers resolve here: `enum` is what gets assigned to Font and
		-- always works, `face` is the FontFace that carries the weight axis and is
		-- applied over the top when the client has one. A stored id naming a family this
		-- client does not have falls back to the first that resolved rather than to nil.
		local family = INTERFACE_FONTS[config.get("ui.interfaceFont", M.defaultInterfaceFont)]
			or INTERFACE_FONTS[M.defaultInterfaceFont]
			or INTERFACE_FONTS[INTERFACE_ORDER[1]]
		local monoFamily = CODE_FONTS[config.get("ui.codeFont", M.defaultCodeFont)]
			or CODE_FONTS[M.defaultCodeFont]
			or CODE_FONTS[CODE_ORDER[1]]

		local enums = {
			regular = (family and family.regular) or SANS,
			medium = (family and family.medium) or SANS_MEDIUM,
			-- No legacy member is a semibold of anything except Source Sans, so `strong`
			-- degrades to medium rather than to bold: one step too heavy is louder than
			-- one step too light, and this is the fallback path.
			strong = (family and family.medium) or SANS_MEDIUM,
			mono = (monoFamily and monoFamily.regular) or Enum.Font.Code,
		}
		local faces = {
			regular = family and family.faces.regular or nil,
			medium = family and family.faces.medium or nil,
			strong = family and family.faces.strong or nil,
			mono = monoFamily and monoFamily.faces.regular or nil,
		}

		M.interfaceFontName = (family and family.label) or "Gotham"
		M.codeFontName = (monoFamily and monoFamily.label) or "Source Code Pro"
		-- The legacy enum name, for RichText's `face` attribute -- which takes an
		-- Enum.Font name string and knows nothing about FontFace. Inline code in a reply
		-- goes through it, so it has to follow the code-font setting rather than saying
		-- "Code" forever.
		M.codeFontEnumName = (monoFamily and monoFamily.enumName) or "Code"
		-- Whether the weight axis is live, so the appearance pane can say so instead of
		-- claiming a weight the client is not rendering.
		M.hasFontFace = faces.regular ~= nil

		local codeThemeName = config.get("ui.codeTheme", "dark")
		local code = CODE_THEMES[codeThemeName] or CODE_THEMES.dark
		M.codeThemeName = CODE_THEMES[codeThemeName] and codeThemeName or "dark"
		if holiday and M.codeThemeName == "dark" then
			local copy = {}
			for key, value in pairs(code) do copy[key] = value end
			copy.surface, copy.border, copy.bar = neutral[0], neutral[4], neutral[2]
			copy.text, copy.gutter, copy.comment = neutral[11], neutral[9], neutral[9]
			code = copy
		end
		M.code = code

		M.color = {
			-- Surfaces, darkest to lightest. The canvas sits one step above the
			-- deepest tone rather than on it, so a code block can go *below* the page
			-- it is on -- which is how the interface this follows separates verbatim
			-- text from prose, and it needs a step in hand to do it.
			canvas = neutral[1],
			sidebar = neutral[0],
			sidebarActive = neutral[2],
			surface = neutral[2],
			surfaceRaised = neutral[3],
			surfaceOverlay = neutral[4],
			surfaceHover = neutral[4],
			surfaceActive = neutral[5],
			-- Selected list rows. A few percent toward the accent rather than a plain
			-- grey step, so a selection reads as chosen rather than merely hovered -- the
			-- one place a list earns a touch of colour.
			surfaceSelected = M.mix(neutral[4], accent.base, 0.20),
			scrim = neutral[0],

			activityBlue = holiday and holiday.activityBlue or rgb(59, 130, 246),
			activityBlueLight = holiday and holiday.activityBlueLight or rgb(96, 165, 250),
			activityBlueDark = holiday and holiday.activityBlueDark or rgb(37, 99, 235),
			activityCell = neutral[2],

			-- Lines.
			-- Outlines sit three to five steps above the surface they are drawn on.
			-- borderSubtle used to be neutral[3], one step above surfaceRaised, which
			-- is a contrast ratio of about 1.05 to 1 -- every card edge, every
			-- segmented outline and the header rule were all invisible, and the
			-- interface read as untitled blocks of near-black rather than as panels.
			borderSubtle = neutral[5],
			border = neutral[6],
			borderStrong = neutral[7],

			-- Type. Secondary and tertiary each moved a step brighter: on a warm dark
			-- ramp the old pair sat at 3.1 and 2.4 to 1 against the canvas, and a
			-- caption nobody can read is a caption that may as well not be there.
			text = neutral[11],
			textSecondary = neutral[10],
			textTertiary = neutral[9],
			textDisabled = neutral[8],
			textOnAccent = neutral[0],

			-- The one loud action. A cream fill with dark text, which is what the
			-- interface this follows uses for its single primary control per view --
			-- and it is deliberately not the accent: reserving colour for meaning
			-- (inline code, a running turn, a risk) is what keeps the accent readable
			-- as meaning rather than as decoration.
			solid = neutral[11],
			solidHover = M.mix(neutral[11], rgb(255, 255, 255), 0.5),
			solidPress = neutral[10],
			onSolid = neutral[0],

			-- Accent and its quiet variants.
			accent = accent.base,
			accentHot = accent.hot,
			accentMuted = M.mix(neutral[2], accent.base, 0.4),
			accentSurface = M.mix(neutral[3], accent.base, 0.14),
			accentBorder = M.mix(neutral[5], accent.base, 0.5),

			-- Status. Saturated enough to read at caption size against a warm dark
			-- ramp, and pulled away from the coral in hue so a danger row and an
			-- accented row are not the same colour with a different label on it.
			success = rgb(94, 200, 124),
			successSurface = M.mix(neutral[3], rgb(94, 200, 124), 0.13),
			warn = rgb(226, 170, 78),
			warnSurface = M.mix(neutral[3], rgb(226, 170, 78), 0.13),
			danger = rgb(240, 132, 124),
			dangerSurface = M.mix(neutral[3], rgb(240, 132, 124), 0.13),
			dangerBorder = M.mix(neutral[5], rgb(240, 132, 124), 0.45),
			info = rgb(120, 162, 226),
			infoSurface = M.mix(neutral[3], rgb(120, 162, 226), 0.13),

			-- Context categories keep their colors independently of pressure/status.
			contextSystem = rgb(180, 157, 232),
			contextMessages = rgb(120, 162, 226),
			contextSummary = rgb(226, 170, 78),
			contextUnused = neutral[6],

			-- The one message surface. The agent's turn is the canvas itself -- a reply
			-- is the page, not an object on it -- and tool rows, subagent cards and
			-- reasoning are all flat now too, so the only fill left in a transcript is
			-- the user's own turn.
			--
			-- Tinted a few percent toward the accent rather than left on surfaceRaised.
			-- surfaceRaised is what a text field is filled with, so the user's own turn
			-- and the composer below it were the same colour with the same corner radius
			-- -- which is why a sent question read as an input box someone had typed into
			-- and not submitted.
			bubbleUser = M.mix(neutral[3], accent.base, 0.045),
			bubbleUserBorder = M.mix(neutral[5], accent.base, 0.18),
			-- The code palette, which is a setting: a fenced block in the transcript,
			-- the diff preview in the appearance pane and the identity readout all draw
			-- from these, so switching the code theme changes what code looks like
			-- rather than only what the preview looks like.
			codeSurface = code.surface,
			codeBorder = code.border,
			codeBar = code.bar,
			codeText = code.text,
			-- Keeps every syntax foreground above 4.5:1 in both code palettes.
			codeSelection = M.mix(code.surface, accent.base, 0.16),
			codeGutter = code.gutter,
			codeAddSurface = code.addSurface,
			codeAddText = code.addText,
			codeRemoveSurface = code.removeSurface,
			codeRemoveText = code.removeText,
		}

		M.text = {}
		for role, spec in pairs(BASE_TEXT) do
			-- Six-to-eight-pixel glyphs lose their strokes at the handheld scale.
			-- Keep the compact layout, but give text a native reading floor before
			-- applying the user's text setting so that setting remains effective.
			local baseSize = spec.size * M.metricScale
			if M.handheld then baseSize = spec.mobileSize or math.max(10, baseSize) end
			local size = math.max(math.floor(baseSize * textScale + 0.5), M.handheld and 9 or 8)
			M.text[role] = {
				size = size,
				font = enums[spec.weight] or enums.regular,
				-- May be nil, and a nil FontFace is never assigned -- P.text applies the
				-- enum first and only layers the face over it when there is one.
				face = faces[spec.weight],
				weight = spec.weight,
				line = spec.line,
				-- One rendered line, rounded up. A fixed-height label sized from `size`
				-- alone clips its descenders the moment the line height goes past 1.3,
				-- so the height a caller needs is published rather than recomputed.
				height = math.ceil(size * spec.line),
			}
		end

		M.space = {}
		for name, value in pairs(BASE_SPACE) do
			M.space[name] = (value == 0) and 0 or math.max(math.floor(value * spaceScale + 0.5), 1)
		end

		M.size = {}
		for name, value in pairs(BASE_SIZE) do
			-- Floored at one, not at eight. The old floor predated the small tokens and
			-- silently clamped every one of them: a 3px slider track, a 4px scrollbar and
			-- a 6px status dot all came out as 8, which is why the scrollbar had never
			-- been the width it said it was.
			M.size[name] = math.max(math.floor(value * sizeScale + 0.5), 1)
		end
		-- Density shrinks chrome independently of type. Reserve the actual line
		-- box before callers budget their toolbars, fields and navigation rows;
		-- enlarging only the label lets it spill out of an otherwise compact control.
		M.size.controlSmall = math.max(M.size.controlSmall, M.text.small.height + M.space.hair * 2)
		M.size.control = math.max(M.size.control, M.text.body.height + M.space.hair * 2)
		M.size.controlLarge = math.max(M.size.controlLarge, M.size.control)
		M.size.rowSmall = math.max(M.size.rowSmall, M.size.controlSmall)
		M.size.row = math.max(M.size.row, M.size.control)
		M.size.chip = math.max(M.size.chip, M.text.caption.height + M.space.hair * 2)
		M.size.tab = math.max(M.size.tab, M.size.controlSmall)
		M.size.codeStatus = math.max(M.size.codeStatus, M.text.caption.height + M.space.hair * 2)
		if M.handheld then
			-- The existing icon artwork has a one-pixel stroke at twelve pixels.
			M.size.icon = math.max(12, M.size.icon)
			M.size.iconLarge = math.max(12, M.size.iconLarge)
			M.size.seasonalArt = math.max(36, M.size.seasonalArt)
		end

		-- The transcript column is the one size a setting names directly. Resolved after
		-- the ramp so the chosen width is the chosen width rather than the chosen width
		-- times the density scale.
		local widths = {
			narrow = M.size.readingNarrow,
			medium = M.size.readingMedium,
			wide = M.size.reading,
		}
		M.readingName = config.get("ui.transcriptWidth", "wide")
		if not widths[M.readingName] then M.readingName = "wide" end
		M.size.reading = widths[M.readingName]

		M.changed:fire(M)
		return M
	end

	-- Convenience accessors so a use site reads as prose.
	function M.textRole(role)
		return M.text[role] or M.text.body
	end

	function M.riskColor(risk)
		if risk == "read" then return M.color.textSecondary end
		if risk == "danger" then return M.color.danger end
		return M.color.warn
	end

	function M.toneColor(tone)
		if tone == "good" then return M.color.success end
		if tone == "warn" then return M.color.warn end
		if tone == "bad" then return M.color.danger end
		if tone == "accent" then return M.color.accent end
		-- "neutral" is a fact rather than a status -- a model id, an auth style -- and
		-- it is the default, because most chips in here are labels that happened to be
		-- given a colour by a tone system that had no way to say "no tone".
		if tone == "neutral" then return M.color.textSecondary end
		return M.color.info
	end

	function M.toneSurface(tone)
		if tone == "good" then return M.color.successSurface end
		if tone == "warn" then return M.color.warnSurface end
		if tone == "bad" then return M.color.dangerSurface end
		if tone == "accent" then return M.color.accentSurface end
		if tone == "neutral" then return M.color.surfaceOverlay end
		return M.color.infoSurface
	end

	-- Motion respects the platform preference: GuiService.ReducedMotionEnabled is
	-- a real accessibility setting, and an interface that ignores it is the sort of
	-- thing that makes people close it.
	function M.tween(name)
		local responsive = env.require("ui/responsive")
		if responsive.reduceMotion then
			return M.motion.instant
		end
		local info = M.motion[name]
		-- Only a TweenInfo may come back. The table also holds plain durations, and
		-- returning 0.18 to a caller about to pass it to TweenService is a crash a
		-- typo away.
		if typeof(info) == "TweenInfo" then return info end
		return M.motion.hover
	end

	function M.duration(name)
		local responsive = env.require("ui/responsive")
		if responsive.reduceMotion then return 0.01 end
		local value = M.motion[name]
		if type(value) == "number" then return value end
		return M.motion.base
	end

	M.rebuild()

	-- Density, accent and scale live in config, so the theme rebuilds itself when any
	-- of them is written rather than every panel having to remember to.
	--
	-- Only the keys that decide a token, though. A rebuild fires theme.changed, which
	-- the app answers by destroying and reconstructing every panel, the window and the
	-- launcher -- so accepting the whole `ui.` namespace meant that maximising the
	-- window, moving the launcher, switching panel or pinning the layout each tore the
	-- interface down and built it again. Anything not in this table cannot change a
	-- token, and so has no business rebuilding anything.
	local TOKEN_KEYS = {
		["ui.accent"] = true,
		["ui.theme"] = true,
		["ui.seasonalThemes"] = true,
		["ui.density"] = true,
		["ui.fontScale"] = true,
		["ui.interfaceFont"] = true,
		["ui.codeFont"] = true,
		["ui.codeTheme"] = true,
		["ui.transcriptWidth"] = true,
	}

	dispose.add(config.changed:connect(function(path)
		-- nil is a whole-file load; "ui" is a namespace reset, which startsWith("ui.")
		-- does not match and which used to leave the interface on the old tokens.
		if path == nil or path == "ui" or TOKEN_KEYS[tostring(path)] then
			M.rebuild()
		end
	end), "theme.configChanged")

	-- Mounted applications own this watcher. A calendar check only rebuilds when
	-- the effective palette changes, leaving ordinary minutes and manual themes idle.
	function M.watchSeasonal(screen)
		local stop = clock.interval(60, function()
			local name = seasonal.resolve(config.get("ui.theme", "default"), config.get("ui.seasonalThemes", true))
			if name ~= M.themeName then M.rebuild() end
		end)
		screen.Destroying:Connect(stop)
		return stop
	end

	return M
end
end)()

-- ==========================================================================
-- ui/tutorial
-- ==========================================================================
__UAI_MODULES["ui/tutorial"] = (function()
-- First-run introduction and the profile menu's repeatable Tutorial.
-- The shared overlay owns fitting, focus, dismissal and surface animation.
-- This module owns page content, navigation and deferred first-run display.
return function(env)
	local config = env.require("runtime/config")
	local clock = env.require("runtime/clock")
	local theme = env.require("ui/theme")
	local P = env.require("ui/primitives")
	local overlay = env.require("ui/overlay")
	local icons = env.require("ui/icons")

	-- Mark on display, including manual opens, so dismissal is respected.
	local SEEN = "ui.tutorial.seen"

	-- Leave room for the boot indicator before offering the introduction.
	local OPEN_DELAY = 1.2

	-- UTF-8 middle dot, shared with the release-note list style.
	local MARKER = "\194\183"

	-- Follow the same density and device scale as the surrounding controls.
	local TILE = theme.size.control
	local MARK_SIZE = theme.size.iconLarge

	-- Actions navigate to existing panels/dialogs without submitting work.
	local PAGES = {
		{
			icon = "brand",
			title = "Welcome to Project UAI",
			body = "Ask questions, explore this place, or build a script. UAI connects "
				.. "a model to tools inside Roblox.",
			items = {
				"Choose a provider in the Providers library before your first message. Project UAI Free is an optional preset; HCNSEC uses your own API key.",
				"Try: Explain what is in this place before making any changes.",
				"Your messages and relevant tool results are sent to your selected provider.",
			},
			action = { label = "Start chatting", value = "chat" },
		},
		{
			icon = "search",
			title = "Find your way around",
			body = "Use the sidebar to move between conversations and tools.",
			items = {
				"Chat holds your conversations. Code is your script workspace.",
				"Cowork connects the browser workspace through a local bridge.",
				"Find a command in the app menu searches panels, settings and conversation titles. Ctrl+K opens it when you are not typing.",
			},
		},
		{
			icon = "sliders",
			title = "Connect a model",
			body = "Open the Providers library and choose a service, local server or custom endpoint.",
			items = {
				"Project UAI Free offers scheduled shared access. The separate HCNSEC preset always requires your personal key.",
				"Fetch the model list from that provider, or enter its exact model ID, then Save.",
				"Choose the provider and model above your message before sending.",
			},
			action = { label = "Open Providers", value = "providers" },
		},
		{
			icon = "check",
			title = "Decide what runs",
			body = "New installs start in Allow everything. Use the chip under the "
				.. "composer to choose how tools get permission.",
			items = {
				"Ask first lets you review changes and code before they run.",
				"Read only limits tools to reads, unless you have saved an explicit tool rule.",
				"Stop cancels further work. Changes already made are not undone.",
			},
		},
		{
			icon = "globe",
			title = "Join the community",
			body = "Provider help, executor quirks and release news live in the Discord.",
			items = {
				"The invite is also in the profile menu; reminders stop once copied.",
			},
			action = { label = "Open Discord invite", value = "discord" },
		},
		{
			icon = "spark",
			title = "Support the project",
			body = "UAI is free to use. Optional donations help keep the project and "
				.. "shared free access running. Thank you for using it.",
			items = {
				"Ko-fi copies a browser link; Robux goes to the donation place.",
			},
			action = { label = "Donation options", value = "donate" },
		},
	}

	local M = {}
	-- The open tour, so the menu entry cannot open a second one over the first.
	local current
	local cancelFirstRun

	-- One page out, the next in, in a single motion: the new page slides a few
	-- pixels from the travel direction while fading in. The old two-phase blink
	-- (out, swap, in) read as a flicker; there is no old page worth showing.
	-- The inner frame translates because the page group itself is a child of the
	-- body's UIListLayout, and a layout owns its children's positions; the inner
	-- frame is a plain child of the group, which owns nothing.
	local function showPage(tour, index, forward)
		if tour.modal.closed or tour.swapping then return end
		if index < 1 or index > #PAGES then return end

		tour.swapping = true
		tour.render(index)
		if tour.modal.closed then return end
		local inner = tour.inner
		inner.Position = UDim2.fromOffset(0, forward and theme.space.sm or -theme.space.sm)
		tour.page.GroupTransparency = 1
		P.animate(tour.page, "enter", { GroupTransparency = 0 })
		P.animate(inner, "enter", { Position = UDim2.fromOffset(0, 0) }, function()
			tour.swapping = false
		end)
	end

	-- Paints the dotted trail: the current step stretches into an accent pill,
	-- the rest stay dimmed dots. Tweened, so the pill glides along the trail
	-- instead of snapping between steps.
	local DOT, PILL = theme.size.dot, theme.size.dot * 3
	local function paintDots(tour)
		for position, dot in ipairs(tour.dots) do
			local active = position == tour.index
			P.animate(dot, "hover", {
				Size = UDim2.fromOffset(active and PILL or DOT, DOT),
				BackgroundColor3 = active and theme.color.accent or theme.color.textDisabled,
			})
		end
	end

	-- Builds the current page inside the group. The body scroll returns to the top
	-- with each page: arriving part-way down a page nobody has read yet reads as a
	-- rendering fault rather than as a position.
	local function render(tour, index)
		local page = PAGES[index]
		local inner = tour.inner
		tour.index = index
		tour.modal.scroll.instance.CanvasPosition = Vector2.new(0, 0)
		for _, child in ipairs(inner:GetChildren()) do
			if child:IsA("GuiObject") then child:Destroy() end
		end

		local order = 0
		local function nextOrder()
			order = order + 1
			return order
		end

		-- The page mark and heading: the icon on a soft coral tile, the way a
		-- starter card pairs its accent-hot icon with its label, with a tint
		-- behind it so the page opens on colour rather than on grey prose.
		local head = P.row(inner, {
			name = "TourHead",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.sm,
			alignY = "Center",
			layoutOrder = nextOrder(),
		})
		local mark = P.frame(head, {
			name = "TourMark",
			size = UDim2.fromOffset(TILE, TILE),
			bg = theme.color.accentSurface,
			radius = theme.radius.sm,
			layoutOrder = 1,
		})
		if page.icon == "brand" then
			icons.brand(mark, MARK_SIZE)
		else
			icons.draw(page.icon, mark, MARK_SIZE, theme.color.accentHot)
		end
		P.text(head, {
			name = "TourTitle",
			text = page.title,
			role = "heading",
			wrap = true,
			auto = "Y",
			size = UDim2.new(1, -(TILE + theme.space.sm), 0, 0),
			layoutOrder = 2,
		})

		if page.body then
			-- The lead stays full-bright while the bullets below dim: the eye
			-- lands on the sentence first, the list second.
			P.text(inner, {
				name = "TourBody",
				text = page.body,
				role = "body",
				wrap = true,
				auto = "Y",
				size = UDim2.new(1, 0, 0, 0),
				layoutOrder = nextOrder(),
			})
		end
		if page.items then
			local role = theme.textRole("small")
			local markerWidth = theme.space.sm
			local list = P.column(inner, {
				name = "TourItems",
				size = UDim2.new(1, 0, 0, 0),
				auto = "Y",
				gap = theme.space.xs,
				layoutOrder = nextOrder(),
			})
			for index, item in ipairs(page.items) do
				local row = P.row(list, {
					size = UDim2.new(1, 0, 0, 0),
					auto = "Y",
					gap = theme.space.xs,
					alignY = "Top",
					layoutOrder = index,
				})
				P.text(row, {
					name = "Marker",
					text = MARKER,
					role = "small",
					line = role.line,
					color = theme.color.accentHot,
					align = "Right",
					alignY = "Top",
					size = UDim2.new(0, markerWidth, 0, role.height),
					layoutOrder = 1,
				})
				P.text(row, {
					text = item,
					role = "small",
					line = role.line,
					color = theme.color.textSecondary,
					wrap = true,
					auto = "Y",
					alignY = "Top",
					size = UDim2.new(1, -(markerWidth + theme.space.xs), 0, 0),
					layoutOrder = 2,
				})
			end
		end
		if page.action then
			-- Sized to its label, not the card: a full-width slab reads as a
			-- second Next button competing with the footer.
			P.button(inner, {
				name = "TourAction",
				text = page.action.label,
				variant = "secondary",
				size = "sm",
				layoutOrder = nextOrder(),
				onClick = function()
					-- Close first: the invitation and the donation dialog are
					-- modals of their own, and two live scrims on one screen is
					-- how a dialog ends up dismissed by a click at its edge.
					tour.modal.close()
					if page.action.value == "chat" or page.action.value == "providers" then
						env.require("ui/app").show(page.action.value)
					elseif page.action.value == "discord" then
						env.require("ui/community").open()
					elseif page.action.value == "donate" then
						-- Required here rather than at the top of the file: app
						-- requires this module from its mount, and a load-time
						-- cycle between the two would be a load error.
						env.require("ui/app").donate()
					end
				end,
			})
		end

		paintDots(tour)
		tour.step.Text = string.format("Step %d of %d", index, #PAGES)
		tour.back.setEnabled(index > 1)
		tour.next.setText(index == #PAGES and "Finish" or "Next")
	end

	function M.seen()
		return config.get(SEEN, false) == true
	end

	function M.markSeen()
		-- Menu-driven opens call this too. Skipping the write when the flag is
		-- already set keeps a repeat visit from dirtying the settings and
		-- scheduling a persist for nothing.
		if M.seen() then return end
		config.set(SEEN, true)
	end

	-- Returns the open tour, or a new one. The pages always start at the first:
	-- the tour is a walkthrough, and a menu entry that resumed in the middle would
	-- have nothing to say about where the middle is.
	function M.open()
		if current and not current.modal.closed then return current end

		-- No fixed height: the card fits each page. Reserving the tallest page's
		-- height left short pages floating in an empty card.
		local modal = overlay.modal({
			title = "Getting started",
			description = "Six short steps. Close any time and reopen from your profile menu.",
			width = theme.size.modalWide,
			onClose = function() current = nil end,
		})
		if not modal then return nil end

		-- Shown once is the whole promise of the first-run gate, so the flag is set
		-- when the tour appears rather than when it is finished: a user who reads
		-- one page and closes it has been told what the client is.
		M.markSeen()

		local page = P.group(modal.content, {
			name = "TourPage",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			layoutOrder = 1,
		})
		local inner = P.column(page, {
			name = "TourPageInner",
			size = UDim2.new(1, 0, 0, 0),
			auto = "Y",
			gap = theme.space.md,
		})

		local tour = { modal = modal, page = page, inner = inner, index = 0, swapping = false, dots = {} }
		tour.render = function(index) render(tour, index) end

		-- Sized for the widest state: one pill plus the rest dots. The layout
		-- reflows inside it as the pill moves.
		local progress = P.column(modal.footer, {
			name = "TourProgress",
			size = UDim2.fromOffset(PILL + (#PAGES - 1) * (DOT + theme.space.xs), 0),
			auto = "Y",
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		local dots = P.row(progress, {
			name = "TourDots",
			size = UDim2.new(0, PILL + (#PAGES - 1) * (DOT + theme.space.xs), 0, DOT),
			gap = theme.space.xs,
			layoutOrder = 1,
		})
		for position = 1, #PAGES do
			local dot = P.frame(dots, {
				name = "TourDot",
				size = UDim2.fromOffset(position == 1 and PILL or DOT, DOT),
				bg = position == 1 and theme.color.accent or theme.color.textDisabled,
				layoutOrder = position,
			})
			P.corner(dot, theme.radius.pill)
			tour.dots[position] = dot
		end

		tour.step = P.text(progress, {
			name = "TourStep",
			text = "",
			role = "caption",
			color = theme.color.textSecondary,
			auto = "X",
			layoutOrder = 2,
		})
		tour.back = P.button(modal.footer, {
			name = "TourBack",
			text = "Back",
			variant = "ghost",
			size = "sm",
			layoutOrder = 3,
			onClick = function() showPage(tour, tour.index - 1, false) end,
		})
		tour.next = P.button(modal.footer, {
			name = "TourNext",
			text = "Next",
			variant = "primary",
			size = "sm",
			layoutOrder = 4,
			onClick = function()
				if tour.index >= #PAGES then
					modal.close()
				else
					showPage(tour, tour.index + 1, true)
				end
			end,
		})

		current = tour
		render(tour, 1)
		return tour
	end

	-- The once-per-install open, scheduled by ui/app's mount. Returns its
	-- canceller, so a client that unloads during the delay does not get a tour
	-- over nothing.
	function M.firstRun(app)
		if cancelFirstRun then cancelFirstRun() end
		if M.seen() or not app or not app.screen then return function() end end
		local alive, pending, destroyed = true, nil, nil
		local function cancel()
			alive = false
			if pending then pcall(task.cancel, pending); pending = nil end
			if destroyed then destroyed:Disconnect(); destroyed = nil end
			if cancelFirstRun == cancel then cancelFirstRun = nil end
		end
		local attempt
		attempt = function()
			pending = nil
			if not alive then return end
			if M.seen() or not app.screen.Parent then cancel(); return end
			local ok, focused = pcall(function() return env.uis:GetFocusedTextBox() end)
			local sessions = env.require("agent/session")
			-- Defer while the user is working; never replace a form, interrupt a
			-- request, or consume the first-run gate behind a hidden window.
			if app.screen.Enabled == false or not app.window or not app.window.visible
				or #overlay.open > 0 or not ok or focused or sessions.busyCount() > 0 then
				pending = clock.delay(OPEN_DELAY, attempt)
				return
			end
			cancel()
			M.open()
		end
		cancelFirstRun = cancel
		destroyed = app.screen.Destroying:Connect(cancel)
		pending = clock.delay(OPEN_DELAY, attempt)
		return cancel
	end

	return M
end
end)()

-- ==========================================================================
-- ui/window
-- ==========================================================================
__UAI_MODULES["ui/window"] = (function()
-- The window shell: chrome, drag, resize, snap, maximise, and the three layout
-- modes it has to be able to become.
--
-- On a phone it is a movable sheet that lifts above the on-screen keyboard. On a
-- small viewport it is a compact panel. On a desktop it is a
-- floating window whose geometry is remembered. On a console it is a large centred
-- panel with no drag, because there is no pointer to drag with.
return function(env)
	local util = env.require("runtime/util")
	local config = env.require("runtime/config")
	local log = env.require("runtime/log")
	local theme = env.require("ui/theme")
	local responsive = env.require("ui/responsive")
	local dispose = env.require("runtime/dispose")
	local P = env.require("ui/primitives")

	local DRAG_SLOP = 6
	local SNAP_MARGIN = 18
	local RESIZE_GRIP = 18

	local M = {}

	function M.new(parent, props)
		props = props or {}
		local mobile = responsive.isMobile()
		local minWidth = props.minWidth or 320
		local minHeight = mobile and math.min(props.minHeight or 280, 200) or (props.minHeight or 280)
		local function geometryKey()
			-- Auto keeps its orientation-specific placement. Explicit handheld modes
			-- remember their own geometry without replacing Auto or desktop settings.
			if mobile then
				local key = responsive.orientation == "portrait" and "ui.mobileSheet" or "ui.mobilePanel"
				if config.get("ui.layout", "auto") ~= "auto" then key = key .. ".layouts." .. responsive.mode end
				return key
			end
			if responsive.mode == "sheet" then return "ui.mobileSheet" end
			if responsive.mode == "panel" then return "ui.mobilePanel" end
			return "ui.window"
		end

		-- Draw the transcript directly on every device. A large CanvasGroup must
		-- reallocate an offscreen texture during resize; its failure/quality limits
		-- should never decide whether a long conversation remains readable.
		local root = Instance.new("Frame", parent)
		root.Name = props.name or "Window"
		root.BackgroundColor3 = theme.color.canvas
		root.BorderSizePixel = 0
		root.Visible = false
		root.Active = true
		root.ZIndex = theme.z.raised
		root.ClipsDescendants = true
		P.corner(root, theme.radius.xl)
		local outline = P.stroke(root, theme.color.border)

		-- No entrance scale or delayed group fade: rapid hide/show is synchronous,
		-- and native text, selection and input geometry stay at their actual size.

		local handle = {
			root = root,
			mobile = mobile,
			visible = false,
			maximised = config.get(geometryKey() .. ".maximised", false) == true,
		}
		local layoutMode = responsive.mode
		local layoutKey = geometryKey()

		-- Everything this window leaves running outside its own instance tree, released
		-- together by handle.destroy.
		--
		-- A rebuild destroys the window and builds another, and the app now rebuilds for a
		-- sidebar toggle as well as for a mode or token change. Each of the three
		-- subscriptions below used to outlive its window: two InputChanged handlers
		-- registered with the global disposer and never unregistered, and a
		-- responsive.changed handler whose unsubscribe was discarded outright -- so after
		-- five rebuilds five dead handlers were still laying out five destroyed windows on
		-- every viewport change.
		local releases = {}
		local destroyed = false
		local dragConnection, resizeConnection
		local stopGestures = function() end

		-- Geometry ------------------------------------------------------------

		local function saveGeometry()
			if destroyed or not handle.visible or handle.maximised or responsive.mode == "tv"
				or responsive.keyboardHeight > 0 then return end
			local key = geometryKey()
			config.set(key .. ".width", math.floor(root.Size.X.Offset), { quiet = true })
			config.set(key .. ".height", math.floor(root.Size.Y.Offset), { quiet = true })
			config.set(key .. ".x", math.floor(root.Position.X.Offset), { quiet = true })
			config.set(key .. ".y", math.floor(root.Position.Y.Offset), { quiet = true })
			config.set(key .. ".placed", true, { quiet = true })
		end
		-- Config already debounces disk writes. Record the release now so a keyboard
		-- or viewport event cannot restore stale geometry before a second timer fires.
		local persistGeometry = saveGeometry

		-- A size that leaves the window on whole pixels when it is centred.
		--
		-- The same texture problem as the scale, from the other direction: this window is
		-- centred with a 0.5 anchor, so its left edge lands at (available - width) / 2 --
		-- a half pixel whenever that difference is odd. Roblox then draws the group's
		-- texture at a half-pixel offset and resamples it, and the whole interface goes
		-- soft. Nothing about the window changed to cause it, which is what makes it
		-- baffling from the outside: one pixel of viewport, one drag of the resize grip
		-- or a restored size with the wrong parity is enough, and it stays that way.
		--
		-- So a centred dimension is nudged by one pixel to keep the space around it even.
		-- Nobody can see the pixel; everybody can see the blur.
		local function centred(available, wanted, floor)
			local value = math.floor(wanted)
			if (math.floor(available) - value) % 2 ~= 0 then
				if value - 1 >= (floor or 1) then value = value - 1 else value = value + 1 end
			end
			return value
		end
		handle.centred = centred

		-- Applies the layout for the current mode. Called on open, on a mode change,
		-- and when the on-screen keyboard appears.
		function handle.layout(reason)
			if destroyed then return end
			stopGestures()
			local geometry = responsive.geometry()
			local mode = responsive.mode
			if layoutMode ~= mode or layoutKey ~= geometryKey() then
				layoutMode = mode
				layoutKey = geometryKey()
				handle.maximised = config.get(geometryKey() .. ".maximised", false) == true
			end
			local viewport = responsive.viewport
			local bounds = responsive.usableRect(parent, theme.space.sm, not responsive.isMobile())
			local _, parentSize = responsive.parentGeometry(parent)
			local availableY = parentSize.Y > 0 and parentSize.Y or viewport.Y
			local availableX = parentSize.X > 0 and parentSize.X or viewport.X

			if (mobile or mode == "sheet" or mode == "panel") and handle.maximised then
				root.AnchorPoint = Vector2.new(0, 0)
				root.Size = UDim2.fromOffset(math.floor(bounds.width), math.floor(bounds.height))
				root.Position = UDim2.fromOffset(math.floor(bounds.x), math.floor(bounds.y))
			elseif mobile or mode == "sheet" or mode == "panel" then
				local key = geometryKey()
				local placed = config.get(key .. ".placed", false)
				local maxPanelWidth = bounds.width
				local maxPanelHeight = bounds.height
				local defaultWidth = math.min(geometry.width, maxPanelWidth)
				local defaultHeight = math.min(geometry.height, maxPanelHeight)
				if mobile and config.get("ui.layout", "auto") == "auto" and responsive.keyboardHeight == 0 then
					defaultHeight = math.min(defaultHeight, math.floor(maxPanelHeight * 0.92))
				end
				local width = defaultWidth
				local height = defaultHeight
				if placed then
					width = util.clamp(config.get(key .. ".width", defaultWidth), math.min(minWidth, maxPanelWidth), maxPanelWidth)
					height = util.clamp(config.get(key .. ".height", defaultHeight), math.min(minHeight, maxPanelHeight), maxPanelHeight)
				end
				root.AnchorPoint = Vector2.new(0, 0)
				root.Size = UDim2.fromOffset(math.floor(width), math.floor(height))
				local defaultX = bounds.x + bounds.width - width
				local defaultY = bounds.y
				if geometry.anchored == "bottom" then
					defaultX = bounds.x + (bounds.width - width) / 2
					defaultY = bounds.y + bounds.height - height
				elseif geometry.anchored == "center" then
					defaultX = bounds.x + (bounds.width - width) / 2
					defaultY = bounds.y + (bounds.height - height) / 2
				elseif responsive.isMobile() then defaultY = bounds.y + (bounds.height - height) / 2 end
				if placed then
					root.Position = UDim2.fromOffset(
						math.floor(config.get(key .. ".x", defaultX)),
						math.floor(config.get(key .. ".y", defaultY)))
					handle.clampIntoView()
				else
					root.Position = UDim2.fromOffset(math.floor(defaultX), math.floor(defaultY))
				end
			elseif mode == "tv" then
				root.AnchorPoint = Vector2.new(0.5, 0.5)
				root.Size = UDim2.fromOffset(
					centred(availableX, math.min(geometry.width, bounds.width)),
					centred(availableY, math.min(geometry.height, bounds.height)))
				root.Position = UDim2.new(0.5, math.floor(bounds.x + bounds.width / 2 - availableX / 2),
					0.5, math.floor(bounds.y + bounds.height / 2 - availableY / 2))
			elseif handle.maximised then
				root.AnchorPoint = Vector2.new(0, 0)
				root.Size = UDim2.fromOffset(math.floor(bounds.width), math.floor(bounds.height))
				root.Position = UDim2.fromOffset(math.floor(bounds.x), math.floor(bounds.y))
			else
				local width = util.clamp(config.get("ui.window.width", 0), 0, viewport.X - theme.space.md * 2)
				local height = util.clamp(config.get("ui.window.height", 0), 0, viewport.Y - theme.space.md * 2)
				if width < minWidth then width = geometry.width end
				if height < minHeight then height = geometry.height end
				root.AnchorPoint = Vector2.new(0.5, 0.5)
				root.Size = UDim2.fromOffset(
					centred(availableX, math.min(width, bounds.width)),
					centred(availableY, math.min(height, bounds.height)))
				if config.get("ui.window.placed", false) then
					root.Position = UDim2.new(0.5, config.get("ui.window.x", 0), 0.5, config.get("ui.window.y", 0))
					handle.clampIntoView()
				else
					root.Position = UDim2.new(0.5, math.floor(bounds.x + bounds.width / 2 - availableX / 2),
						0.5, math.floor(bounds.y + bounds.height / 2 - availableY / 2))
				end
			end

			if handle.onLayout then pcall(handle.onLayout, mode, reason) end
		end

		-- Keep the complete surface reachable, including its composer and footer,
		-- after moving between viewports or opening the on-screen keyboard.
		function handle.clampIntoView()
			if responsive.mode == "tv" then return end
			local size = root.Size
			local bounds = responsive.usableRect(parent, theme.space.xs, false)
			local _, parentSize = responsive.parentGeometry(parent)
			-- Clamp the top-left edge in parent coordinates, then preserve the existing
			-- anchor/scale. A sheet, panel and centred desktop window use different anchors.
			local baseX = root.Position.X.Scale * parentSize.X - size.X.Offset * root.AnchorPoint.X
			local baseY = root.Position.Y.Scale * parentSize.Y - size.Y.Offset * root.AnchorPoint.Y
			local minX, minY = bounds.x - baseX, bounds.y - baseY
			local maxX = math.max(minX, bounds.x + bounds.width - size.X.Offset - baseX)
			local maxY = math.max(minY, bounds.y + bounds.height - size.Y.Offset - baseY)
			root.Position = UDim2.new(
				root.Position.X.Scale, math.floor(util.clamp(root.Position.X.Offset, minX, maxX)),
				root.Position.Y.Scale, math.floor(util.clamp(root.Position.Y.Offset, minY, maxY)))
		end

		function handle.setMinWidth(width)
			minWidth = width
			local bounds = responsive.usableRect(parent, theme.space.sm, false)
			local wanted = math.min(minWidth, bounds.width)
			if root.Size.X.Offset < wanted then
				root.Size = UDim2.fromOffset(math.floor(wanted), root.Size.Y.Offset)
				handle.clampIntoView()
				saveGeometry()
			end
		end

		-- Chrome --------------------------------------------------------------

		-- Both title lines and the ordinary window controls share the same header.
		local headerHeight = math.max(theme.size.header, responsive.minTarget() + theme.space.sm,
			math.ceil(theme.text.bodyStrong.size * theme.line.tight)
				+ math.ceil(theme.text.caption.size * theme.line.tight) + theme.space.hair + theme.space.xxs * 2)
		handle.headerHeight = headerHeight

		-- The header is a transparent top bar across the active pane that provides
		-- the drag handle and holds window controls.
		handle.header = P.row(root, {
			name = "Header",
			size = UDim2.new(1, 0, 0, headerHeight),
			gap = theme.space.sm,
			padding = { x = theme.space.md },
			zIndex = theme.z.header,
		})
		handle.header.BackgroundTransparency = 1
		handle.header.Active = true

		handle.body = P.frame(root, {
			name = "Body",
			size = UDim2.fromScale(1, 1),
			position = UDim2.new(0, 0, 0, 0),
		})

		-- Drag ----------------------------------------------------------------

		-- Bound to the header only. Making the whole surface a drag handle -- which
		-- Frame.Draggable did -- means the transcript cannot be dragged to scroll and
		-- text cannot be swiped to select, because both gestures move the window.
		local dragging, moved, origin, startPosition = false, false, nil, nil
		local dragInput, resizeInput

		local function draggableNow()
			return (responsive.mode == "window" or responsive.mode == "panel" or responsive.mode == "sheet") and not handle.maximised
		end

		local function overHeaderControl(input)
			for _, child in ipairs(handle.header:GetDescendants()) do
				if child:IsA("GuiButton") or child:IsA("TextBox") then
					local shown, ancestor = true, child
					while ancestor and ancestor ~= handle.header do
						if ancestor:IsA("GuiObject") and not ancestor.Visible then shown = false; break end
						ancestor = ancestor.Parent
					end
					local point, size = child.AbsolutePosition, child.AbsoluteSize
					if shown and input.Position.X >= point.X and input.Position.X < point.X + size.X
						and input.Position.Y >= point.Y and input.Position.Y < point.Y + size.Y then return true end
				end
			end
			return false
		end

		handle.header.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			if not draggableNow() or dragging or resizeInput or not handle.visible then return end
			if overHeaderControl(input) then return end
			dragging, moved = true, false
			dragInput = input
			origin = input.Position
			startPosition = root.Position
			dragConnection = input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End or input.UserInputState == Enum.UserInputState.Cancel then
					dragging = false
					dragInput = nil
					if dragConnection then dragConnection:Disconnect(); dragConnection = nil end
					if moved and input.UserInputState == Enum.UserInputState.End then
						handle.snap()
						persistGeometry()
					end
				end
			end)
		end)

		releases[#releases + 1] = dispose.connection(env.uis.InputChanged:Connect(function(input)
			if not dragging or not startPosition then return end
			local kind = input.UserInputType
			if dragInput and dragInput.UserInputType == Enum.UserInputType.Touch then
				if input ~= dragInput then return end
			elseif kind ~= Enum.UserInputType.MouseMovement then return end
			local delta = input.Position - origin
			if math.abs(delta.X) > DRAG_SLOP or math.abs(delta.Y) > DRAG_SLOP then moved = true end
			if not moved then return end
			root.Position = UDim2.new(
				startPosition.X.Scale, math.floor(startPosition.X.Offset + delta.X),
				startPosition.Y.Scale, math.floor(startPosition.Y.Offset + delta.Y))
			handle.clampIntoView()
		end))

		-- Snapping to an edge is what makes a floating window feel placed rather than
		-- dropped. Only the near edge snaps, and only within a small margin.
		function handle.snap()
			if not draggableNow() then return end
			local _, viewport = responsive.parentGeometry(parent)
			local bounds = responsive.usableRect(parent, theme.space.sm, false)
			local size = root.AbsoluteSize
			if mobile or responsive.mode == "panel" or responsive.mode == "sheet" then
				local x, y = root.Position.X.Offset, root.Position.Y.Offset
				local leftGap = x - bounds.x
				local rightGap = bounds.x + bounds.width - (x + size.X)
				local topGap = y - bounds.y
				local bottomGap = bounds.y + bounds.height - (y + size.Y)

				if leftGap < SNAP_MARGIN then x = bounds.x end
				if rightGap < SNAP_MARGIN then x = bounds.x + bounds.width - size.X end
				if topGap < SNAP_MARGIN then y = bounds.y end
				if bottomGap < SNAP_MARGIN then y = bounds.y + bounds.height - size.Y end

				root.Position = UDim2.fromOffset(math.floor(x), math.floor(y))
				return
			end
			local x, y = root.Position.X.Offset, root.Position.Y.Offset
			local halfViewportX, halfViewportY = viewport.X * 0.5, viewport.Y * 0.5
			local leftGap = (x - size.X * 0.5) + halfViewportX - bounds.x
			local rightGap = bounds.x + bounds.width - halfViewportX - (x + size.X * 0.5)
			local topGap = (y - size.Y * 0.5) + halfViewportY - bounds.y
			local bottomGap = bounds.y + bounds.height - halfViewportY - (y + size.Y * 0.5)

			if leftGap < SNAP_MARGIN then x = x - leftGap end
			if rightGap < SNAP_MARGIN then x = x + rightGap end
			if topGap < SNAP_MARGIN then y = y - topGap end
			if bottomGap < SNAP_MARGIN then y = y + bottomGap end

			-- Keep the snapped position on whole pixels throughout the move.
			root.Position = UDim2.new(0.5, math.floor(x), 0.5, math.floor(y))
		end

		-- Resize --------------------------------------------------------------

		local grip = Instance.new("TextButton", root)
		grip.Name = "ResizeGrip"
		grip.Text = ""
		grip.AutoButtonColor = false
		grip.BackgroundTransparency = 1
		grip.AnchorPoint = Vector2.new(1, 1)
		grip.Position = UDim2.fromScale(1, 1)
		local scaledGrip = math.max(1, math.floor(RESIZE_GRIP * theme.metricScale + 0.5))
		local gripSize = responsive.touch and math.max(scaledGrip, responsive.minTarget()) or scaledGrip
		grip.Size = UDim2.fromOffset(gripSize, gripSize)
		grip.ZIndex = theme.z.header + 2
		grip.Selectable = false
		handle.resizeGrip = grip

		local function updateGrip()
			local currentGripSize = responsive.touch and math.max(scaledGrip, responsive.minTarget()) or scaledGrip
			grip.Size = UDim2.fromOffset(currentGripSize, currentGripSize)
			grip.Visible = draggableNow()
		end

		-- A corner hatch at the bottom-right, on every device: resize is a corner
		-- grip on the panel exactly as it is on the desktop window.
		for index = 1, 2 do
			local line = P.frame(grip, {
				name = "Grip" .. index,
				size = UDim2.fromOffset(math.floor((index * 5 + 1) * theme.metricScale + 0.5), theme.stroke.hair),
				anchor = Vector2.new(1, 1),
				position = UDim2.new(1, -theme.space.xxs, 1, -index * theme.space.xxs),
				bg = theme.color.borderStrong,
				radius = theme.radius.pill,
			})
			line.Rotation = -45
		end

		local resizing, resizeOrigin, startSize = false, nil, nil
		stopGestures = function()
			dragging, resizing = false, false
			dragInput, resizeInput = nil, nil
			if dragConnection then dragConnection:Disconnect(); dragConnection = nil end
			if resizeConnection then resizeConnection:Disconnect(); resizeConnection = nil end
		end
		releases[#releases + 1] = dispose.connection(env.uis.WindowFocusReleased:Connect(stopGestures), "window focus")

		grip.InputBegan:Connect(function(input)
			local kind = input.UserInputType
			if kind ~= Enum.UserInputType.MouseButton1 and kind ~= Enum.UserInputType.Touch then return end
			if not draggableNow() or resizing or dragging or not handle.visible then return end
			resizing = true
			resizeInput = input
			resizeOrigin = input.Position
			startSize = root.AbsoluteSize
			resizeConnection = input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End or input.UserInputState == Enum.UserInputState.Cancel then
					resizing = false
					resizeInput = nil
					if resizeConnection then resizeConnection:Disconnect(); resizeConnection = nil end
					if input.UserInputState == Enum.UserInputState.End then persistGeometry() end
					if handle.onLayout then pcall(handle.onLayout, responsive.mode, "resize") end
				end
			end)
		end)

		releases[#releases + 1] = dispose.connection(env.uis.InputChanged:Connect(function(input)
			if not resizing or not startSize then return end
			local kind = input.UserInputType
			if resizeInput and resizeInput.UserInputType == Enum.UserInputType.Touch then
				if input ~= resizeInput then return end
			elseif kind ~= Enum.UserInputType.MouseMovement then return end
			local delta = input.Position - resizeOrigin
			local _, viewport = responsive.parentGeometry(parent)
			local bounds = responsive.usableRect(parent, theme.space.sm, false)
			if mobile or responsive.mode == "panel" or responsive.mode == "sheet" then
				local maxWidth = bounds.width
				local maxHeight = bounds.height
				root.Size = UDim2.fromOffset(
					math.floor(util.clamp(startSize.X + delta.X, math.min(minWidth, maxWidth), maxWidth)),
					math.floor(util.clamp(startSize.Y + delta.Y, math.min(minHeight, maxHeight), maxHeight)))
				handle.clampIntoView()
			else
				-- Through `centred` for the same reason the layout is: the window is centred
				-- while it is being resized, so a width one pixel out of parity puts the
				-- group's texture on a half pixel and softens every glyph in it. Dragging the
				-- grip was the easiest way to land there.
				root.Size = UDim2.fromOffset(
					centred(viewport.X,
						util.clamp(startSize.X + delta.X * 2, math.min(minWidth, bounds.width), bounds.width)),
					centred(viewport.Y,
						util.clamp(startSize.Y + delta.Y * 2, math.min(minHeight, bounds.height), bounds.height)))
				handle.clampIntoView()
			end
		end))

		function handle.setMaximised(value)
			if value == true and not handle.maximised then saveGeometry() end
			handle.maximised = value == true
			-- Quiet, like every other geometry write here: this is a record of where
			-- the window is, not a setting anything else derives from, and a noisy
			-- write used to reach the theme's config subscription and rebuild the
			-- entire interface a fifth of a second after the maximise animation.
			config.set(geometryKey() .. ".maximised", handle.maximised, { quiet = true })
			updateGrip()
			handle.layout("maximise")
		end

		function handle.toggleMaximised()
			handle.setMaximised(not handle.maximised)
		end

		-- Visibility ----------------------------------------------------------

		function handle.show()
			if destroyed or handle.visible then return end
			handle.visible = true
			handle.layout("show")
			root.Visible = true
			if handle.onShow then pcall(handle.onShow) end
		end

		function handle.hide()
			if not handle.visible then return end
			handle.visible = false
			stopGestures()
			-- Hidden editors must stop receiving native typing and gamepad actions.
			local focused = env.uis:GetFocusedTextBox()
			if focused and focused:IsDescendantOf(root) then focused:ReleaseFocus() end
			local selected = env.guisvc.SelectedObject
			if selected and selected:IsDescendantOf(root) then env.guisvc.SelectedObject = nil end
			root.Visible = false
			if handle.onHide then pcall(handle.onHide) end
		end

		function handle.toggle()
			if handle.visible then handle.hide() else handle.show() end
		end

		-- Everything this window leaves running outside its own tree, released together.
		local function cleanup()
			if destroyed then return end
			destroyed = true
			stopGestures()
			for _, release in ipairs(releases) do pcall(release) end
			releases = {}
			handle.visible = false
		end
		root.Destroying:Connect(cleanup)
		function handle.destroy()
			cleanup()
			pcall(function() root:Destroy() end)
		end

		-- Re-layout on every viewport change. Continuous changes only move and
		-- resize; a mode change is what asks the contents to rebuild, and that is
		-- signalled separately by responsive.modeChanged.
		releases[#releases + 1] = responsive.changed:connect(function(info)
			if not handle.visible then return end
			updateGrip()
			handle.layout(info and info.reason or "viewport")
		end)

		updateGrip()
		handle.outline = outline
		return handle
	end

	return M
end
end)()

-- ==========================================================================
-- bootstrap
-- ==========================================================================
--!globals __UAI_MODULES __UAI_BUILD
-- Bootstrap.
--
-- Everything above this file is a factory of the form `return function(env)`. This
-- is the one chunk that is not: it builds the env, wires the module loader, and
-- mounts the interface. The bundler emits it last, after the module table, so
-- `__UAI_MODULES` is a local in the finished artifact.
--
-- Run it as:
--     loadstring(game:HttpGet("<url>/dist/uai.lua"))()
-- or, when embedding it in a host script, pass a context table:
--     loadstring(...)({ prompt = "You also control X", hooks = { preTool = fn } })

local MODULES = __UAI_MODULES
if type(MODULES) ~= "table" then
	warn("[uai] no module table -- run the bundled dist/uai.lua, not src/init.lua")
	return nil
end

local hostContext = ...
local replacementConfig, replacementVault

local VERSION = "3.8.0"
local FOLDER = "UAI"
local BUILD = type(__UAI_BUILD) == "string" and __UAI_BUILD or VERSION

-- Re-running the same build reopens it; a changed build replaces an idle client.
-- Never tear down active work or mount over a cleanup that did not finish.
local globalTable = (type(getgenv) == "function") and getgenv() or nil
if globalTable and type(globalTable.UAI) == "table" then
	local existing = globalTable.UAI
	if existing.alive or existing.reloadBlocked then
		local function notice(message)
			local shown, toast = pcall(function()
				local overlay = existing.env.loadedModules and existing.env.loadedModules["ui/overlay"]
				if overlay and existing.app and existing.app.screen then return overlay.toast(message, "warn", 7) end
			end)
			if not shown or not toast or not existing.alive then warn("[uai] " .. message) end
		end
		if existing.reloadBlocked then
			notice("The previous client did not finish unloading. Rejoin before loading the update.")
			return existing
		end
		-- Reuse and replacement both begin a fresh password challenge. Retaining
		-- the live key permits safe saves and accepted replies, never new work.
		if existing.config and existing.config.requireVault then
			existing.config.requireVault()
			if existing.app and existing.app.syncCredentialAccess then existing.app.syncCredentialAccess() end
		end
		if existing.build == BUILD then
			local options = type(hostContext) == "table" and hostContext
				or (type(globalTable.UAI_CONTEXT) == "table" and globalTable.UAI_CONTEXT) or {}
			if options.reuse ~= true and type(existing.toggle) == "function" then pcall(existing.toggle) end
			return existing
		end
		existing.pendingBuild = BUILD
		local inspected, busy = pcall(function()
			if existing.config.vaultStatus and existing.config.vaultStatus().busy then return true end
			local runner = existing.env.loadedModules and existing.env.loadedModules["tools/code_runner"]
			if runner and runner.busy and runner.busy() then return true end
			for _, session in ipairs(existing.sessions.list()) do
				if session.busy then return true end
			end
			local child = existing.env.loadedModules and existing.env.loadedModules["agent/subagent"]
			return child ~= nil and #child.running() > 0
		end)
		if not inspected then
			notice("Update ready. Could not check active work; reopen the client after your work finishes.")
			return existing
		end
		if busy then
			notice("Update ready. Let the current work finish or stop it, then run the loader again.")
			return existing
		end
		local checkedDrafts, pending = pcall(function()
			local workspace = existing.env.loadedModules and existing.env.loadedModules["runtime/code_store"]
			if workspace and workspace.preflightReplacement then
				local preserved, why = workspace.preflightReplacement()
				if not preserved then return "Update ready. " .. tostring(why) end
			end
			for _, session in ipairs(existing.sessions.list()) do
				local ctx = session.ctx or {}
				if session.ephemeral and (#(session.log or {}) > 0 or #(ctx.messages or {}) > 0
					or (type(ctx.summary) == "string" and ctx.summary ~= "") or session.named or (session.turns or 0) > 0) then
					return "Update ready. Save or remove your isolated conversations before running the loader again."
				end
			end
			local composer = existing.app and existing.app.chatPanel and existing.app.chatPanel.composer
			local chatLoops = existing.env.loadedModules and existing.env.loadedModules["runtime/chatloops"]
			if chatLoops and #chatLoops.running() > 0 then
				return "Update ready. Stop your chat loops before running the loader again."
			end
			local composerModule = existing.env.loadedModules and existing.env.loadedModules["ui/chat/composer"]
			local quick = existing.env.loadedModules and existing.env.loadedModules["ui/quickchat"]
			local function hasText(field)
				return field and type(field.get) == "function" and tostring(field.get()):find("%S") ~= nil
			end
			if (composer and (hasText(composer.field) or #(composer.attachments or {}) > 0))
				or (composerModule and composerModule.hasDrafts and composerModule.hasDrafts()) then
				return "Update ready. Send or clear your draft and attachments before running the loader again."
			end
			if quick and hasText(quick.field) then
				return "Update ready. Send or clear your Quick Chat draft before running the loader again."
			end
		end)
		if not checkedDrafts or pending then
			notice(pending or "Update ready. Could not check unsaved drafts, so this client is staying open.")
			return existing
		end
		local saved, complete = pcall(function()
			local fsx = existing.env.require("runtime/fsx")
			if not fsx.enabled then return false end
			if not existing.config.saveNow() then return false end
			for _, session in ipairs(existing.sessions.list()) do
				if not session.headless and not session.ephemeral and (session.depth or 0) == 0 then
					if not existing.sessions.persist(session) then return false end
				end
			end
			replacementConfig = existing.env.require("runtime/util").deepCopy(existing.config.data)
			local vault = existing.env.loadedModules and existing.env.loadedModules["runtime/credential_vault"]
			if vault then replacementVault = vault.handoff(replacementConfig.credentialVault) end
			return true
		end)
		if not saved or not complete then
			notice("Update ready. Settings and conversations could not be saved, so this client is staying open.")
			return existing
		end
		if hostContext == nil and existing.env and type(existing.env.context) == "table" then
			hostContext = existing.env.context
		end
		local unloaded, result = pcall(function() return existing.destroy() end)
		local checked, detached = pcall(function()
			return not existing.app or not existing.app.screen or existing.app.screen.Parent == nil
		end)
		if not unloaded or result == false or existing.alive or existing.cleanupFailed or not checked or not detached then
			existing.reloadBlocked = true
			globalTable.UAI = existing
			notice("The previous client did not finish unloading. Rejoin before loading the update.")
			return existing
		end
	end
end

-- Services are resolved lazily and memoised. GetService is the correct accessor
-- even for Workspace and Players: a game may have renamed the instance, and
-- indexing `game.Workspace` would then miss.
local services = setmetatable({}, {
	__index = function(cache, name)
		local ok, service = pcall(function() return game:GetService(name) end)
		if not ok or not service then return nil end
		cache[name] = service
		return service
	end,
})

local env = {
	info = { name = "UAI", version = VERSION, build = BUILD, folder = FOLDER },
	services = services,
	context = (type(hostContext) == "table" and hostContext)
		or (globalTable and type(globalTable.UAI_CONTEXT) == "table" and globalTable.UAI_CONTEXT)
		or {},
}

env.hs = services.HttpService
env.uis = services.UserInputService
env.tween = services.TweenService
env.run = services.RunService
env.guisvc = services.GuiService
env.players = services.Players
env.plr = env.players and env.players.LocalPlayer or nil

-- The loader. Cycles are an error rather than a hang: a module that is already
-- loading has been reached again, and returning a half-built table would fail
-- somewhere far away from the cause.
local loaded, loading = {}, {}

-- How many modules this artifact carries, counted rather than written down: the
-- bundler decides it, and a literal here would go stale on the next build. It is the
-- only denominator available to the boot indicator, and it is deliberately *not*
-- treated as a target -- a normal boot loads about four fifths of it and never
-- reaches the rest, because a panel's module is loaded the first time that panel is
-- opened.
env.moduleTotal = 0
for _ in pairs(MODULES) do env.moduleTotal = env.moduleTotal + 1 end
env.moduleCount = 0

function env.require(id)
	local cached = loaded[id]
	if cached ~= nil then return cached end
	if loading[id] then
		error("[uai] circular require: " .. tostring(id), 2)
	end
	local factory = MODULES[id]
	if type(factory) ~= "function" then
		error("[uai] no module '" .. tostring(id) .. "'", 2)
	end
	loading[id] = true
	local ok, result = pcall(factory, env)
	loading[id] = nil
	if not ok then
		error("[uai] module '" .. tostring(id) .. "' failed to load: " .. tostring(result), 2)
	end
	if result == nil then
		error("[uai] module '" .. tostring(id) .. "' returned nothing", 2)
	end
	loaded[id] = result
	env.moduleCount = env.moduleCount + 1
	-- The one hook in the loader, and it exists for the boot indicator: the count is
	-- real work finishing, which is the only progress this client can honestly report
	-- before the interface is up. pcall because a watcher must never be able to stop a
	-- module from loading.
	if env.onModuleLoaded then pcall(env.onModuleLoaded, id, env.moduleCount, env.moduleTotal) end
	return result
end

env.loadedModules = loaded

local function start()
	local mountAtBoot = env.context.ui ~= false
	-- The boot indicator first, before a single other module loads.
	--
	-- It is dependency free on purpose, so it can paint within a frame of execution
	-- rather than after the theme and the control set are built -- the seconds those
	-- take are exactly what it exists to cover, and it used to appear only once three
	-- quarters of them were already spent. It is only a pcall deep because a client
	-- that cannot draw it must still boot: a progress bar is not worth failing a
	-- start over.
	local boot
	if mountAtBoot then pcall(function() boot = env.require("ui/boot").show() end) end

	-- The loader reports real work finishing -- the only honest progress there is
	-- before the interface is up -- and yields on a budget while it does, so the
	-- indicator animates instead of freezing until the mount is done. A Roblox GUI
	-- does not paint until the thread building it yields, and the whole boot used to
	-- run start-to-finish without one; the throttle keeps a fast client from paying
	-- for yields it does not need while still repainting a slow one a few times a
	-- second. pcall on step because a watcher must never stop a module loading.
	local lastYield = os.clock()
	env.onModuleLoaded = function(id, count, total)
		if boot then pcall(boot.step, id, count, total) end
		if os.clock() - lastYield >= 0.03 then
			task.wait()
			lastYield = os.clock()
		end
	end

	-- The interface build is the tail of the boot that module counting cannot see:
	-- once every module is loaded the counter sits still while the window, the
	-- transcript and the composer are constructed -- the single largest synchronous
	-- chunk of the whole start, and where the bar used to jump to four fifths and then
	-- freeze. app.mount calls this at those construction boundaries, so the indicator
	-- yields across them and keeps animating. Set only for the first mount and cleared
	-- with the loader below, so a later rebuild never pays for it.
	if mountAtBoot then
		env.onMountPhase = function(text)
			if boot then pcall(boot.phase, text) end
			task.wait()
		end
	end

	-- Force the first paint before the heavy loading begins, so the indicator is on
	-- screen for the whole of it rather than appearing at the end.
	if boot then task.wait() end

	-- Startup order matters in exactly one place: config has to be read before
	-- anything derives from it, because the theme and the provider list are both
	-- built from stored values.
	if boot then boot.stage("prepare", "Checking capabilities and loading preferences.") end
	local caps = env.require("runtime/caps")
	local log = env.require("runtime/log")
	local config = env.require("runtime/config")

	config.requireVault()
	config.load(replacementConfig, replacementVault)
	replacementConfig, replacementVault = nil, nil
	log.mirror = config.get("logs.mirror", false) == true
	log.info("boot", string.format("UAI %s starting -- %s", VERSION, caps.summary()))

	-- Asked for early and answered in the background: the place name is what the
	-- conversation list groups by, and it is a web call.
	env.require("runtime/place").resolve()

	env.require("agent/hooks").adoptContext()
	env.require("agent/registry").load()

	-- Before anything reads the provider list: saved records keep the attribution
	-- headers they were created with, so the repository move has to be carried into
	-- existing installs here rather than only into records created from now on.
	env.require("provider/registry").migrate()
	env.require("provider/free").start()

	-- The workspace migration, before anything that reads files/: the file tools,
	-- the paste fallbacks, the attach menu. For a returning user with older files
	-- this is the step between "it used to see my notes" and the tidy layout, so it
	-- is reported through the boot indicator while it happens rather than logged
	-- where nobody looks. A fresh install sweeps an empty root and reports nothing.
	if boot then boot.stage("restore", "Restoring your workspace and conversations.") end
	pcall(function()
		local fsx = env.require("runtime/fsx")
		local alreadyMigrated = config.get("fs.migrated", false) == true
		local hasDisplacedSkills = fsx.isDir("skills", { scope = "files" })
		if alreadyMigrated and not hasDisplacedSkills then return end

		local swept = fsx.list("")
		local pending = 0
		for _, entry in ipairs(swept) do
			if not tostring(entry.path or ""):find("/", 1, true) then
				local name = tostring(entry.name or "")
				local clientOwns = name == "files" or name == "pastes" or name == "skills"
					or name == "sessions" or name == "export" or name == "icons"
					or name == "config.json" or name == "config.vault.pending.json" or name == "stats.json"
				if not clientOwns then pending = pending + 1 end
			end
		end
		if (pending > 0 or hasDisplacedSkills) and boot then
			boot.phase("Updating your workspace layout.")
		end
		local moved = fsx.migrate(function(count, name)
			if boot then boot.phase(string.format("Moved %d: %s", count, name)) end
		end)
		if moved and moved > 0 and boot then
			boot.phase(string.format("Moved %d file(s) into files/", moved))
		end
		config.set("fs.migrated", true)
		config.save()
		fsx.ensure("skills")
		fsx.ensure("files")
	end)

	local sessions = env.require("agent/session")
	sessions.restore()
	local workflow = env.require("runtime/script_workflow")
	env.require("runtime/dispose").add(env.require("runtime/code_store").changed:connect(function(event)
		if event.kind == "source" or event.kind == "create" or event.kind == "delete" then
			for _, session in ipairs(sessions.list()) do workflow.invalidate(session) end
		end
	end), "Script goal source revisions")

	-- After the restore, because the first run recovers the real message history out
	-- of whatever transcripts are already on disk, and before the interface, because
	-- the home card reads it as soon as it builds.
	env.require("agent/stats").init()

	local app, handle
	local mounting, mountFailure = false, nil
	local function mountApp()
		if handle and not handle.alive then return nil, "client is unloaded" end
		if mounting then return nil, "interface is already mounting" end
		if mountFailure then return nil, mountFailure end
		mounting = true
		local ok, why = pcall(function()
			app = env.require("ui/app")
			if handle then handle.app = app end
			app.mount()
			if not app.screen or not app.screen.Parent then error("nowhere to parent the interface", 0) end
		end)
		mounting = false
		if not ok then
			mountFailure = tostring(why)
			log.error("app", "could not mount interface", mountFailure)
			return nil, mountFailure
		end
		if handle then handle.uiMounted = true end
		return app
	end
	-- Even an embedding that hides the application must present its password
	-- prompt. The app keeps its normal window hidden after UI-free authentication.
	if boot then boot.stage("interface", "Preparing your workspace controls.") end
	local mounted, mountWhy = mountApp()
	if not mounted then error(mountWhy, 0) end
	if mountAtBoot then
		app.show(config.get("ui.panel", "chat"))
	else
		-- A hidden client still has a selected conversation for the bridge and ask().
		sessions.current()
	end

	-- Mount callbacks are only needed during initial construction.
	env.onMountPhase = nil

	-- After the interface, because the bridge attaches to whichever thread is
	-- active and the interface is what establishes that on a fresh install. A
	-- manual bridge is opt-in; the desktop app is discovered on its own local port.
	local bridge = env.require("net/bridge")

	-- The handle a host script (or the user, from a console) can drive.
	-- Declared before it is populated: `local handle = { ... }` does not put `handle`
	-- in scope inside its own initialiser, so every closure below that reaches for
	-- `handle` would have captured a nil global instead. `destroy` did exactly that,
	-- which is why unloading raised rather than unloading.
	handle = {
		alive = true,
		uiMounted = app ~= nil and app.screen ~= nil and app.screen.Parent ~= nil,
		version = VERSION,
		build = BUILD,
		env = env,
		app = app,
		sessions = sessions,
		config = config,
		log = log,
		caps = caps,
		bridge = bridge,
		hooks = env.require("agent/hooks"),
		permissions = env.require("agent/permissions"),
		providers = env.require("provider/registry"),
		tools = env.require("agent/registry"),
		toggle = function()
			local mounted, why = mountApp()
			if not mounted then return false, why end
			mounted.toggle()
			return true
		end,
		show = function(panel)
			local mounted, why = mountApp()
			if not mounted then return false, why end
			mounted.show(panel)
			return true
		end,
		hide = function()
			if not handle.alive then return false, "client is unloaded" end
			if app then app.hide() end
			return true
		end,
		openSession = function(id)
			if not handle.alive then return false, "client is unloaded" end
			if id ~= nil and not sessions.threads[id] then return false, "conversation no longer exists" end
			local mounted, why = mountApp()
			if not mounted then return false, why end
			return mounted.openSession(id)
		end,
		ask = function(text)
			if not handle.alive then return false, "client is unloaded" end
			local session = sessions.current()
			return session.send(text)
		end,
		-- The kill switch. Destroying the ScreenGui is not unloading: timers keep
		-- ticking, input handlers keep firing on the service, and a config write
		-- would rebuild an interface that is no longer on screen. Everything that
		-- outlives the instance tree registers a cleanup in runtime/dispose, and
		-- this is what drains it.
		--
		--     getgenv().UAI.destroy()
		destroy = function()
			if not handle.alive then return 0 end
			if config.vaultStatus().busy then
				return false, "Finish or cancel credential storage before unloading UAI."
			end
			handle.alive = false
			-- Invalidate all turns immediately. The disposer owns cancellation and
			-- final dirty saves once; aborting here used to rewrite every history and
			-- refresh the sidebar, then repeat the same work during disposal.
			sessions.beginShutdown()
			local ran, failed = env.require("runtime/dispose").drain()
			local screenOk = pcall(function() if app and app.screen then app.screen:Destroy() end end)
			handle.uiMounted = false
			handle.cleanupFailed = not screenOk or #(failed or {}) > 0
			pcall(function() config.saveNow() end)
			if globalTable and globalTable.UAI == handle then globalTable.UAI = nil end
			log.info("boot", string.format("unloaded -- %d cleanups run", ran or 0))
			for _, problem in ipairs(failed or {}) do
				log.warn("boot", "cleanup failed", problem)
			end
			return ran
		end,
		unload = function() return handle.destroy() end,
	}
	env.exitClient = function() return handle.destroy() end
	handle.sdk = env.require("embedding/sdk").attach(handle)
	-- Pairing and discovery wait until setup/unlock succeeds. Warm challenges
	-- retain accepted transport ownership; those modules gate new admissions.
	local linksStarted = false
	local function startLinks()
		if linksStarted or not handle.alive or config.accessProblem() or config.vaultStatus().busy then return end
		linksStarted = true
		handle.providers.migrate()
		local bridgeOk, bridgeWhy = bridge.sync()
		if not bridgeOk and bridgeWhy then log.warn("bridge", "not started", bridgeWhy) end
		env.require("net/relay_link").ensure()
	end
	env.require("runtime/dispose").add(config.changed:connect(function(path)
		if path == "security.vault" then startLinks() end
	end), "password-gated connections")
	app.syncCredentialAccess()
	startLinks()

	if globalTable then globalTable.UAI = handle end
	env.onModuleLoaded = nil
	if boot then
		pcall(boot.done, "Your workspace is ready.")
		env.require("runtime/dispose").add(boot.destroy, "Startup card")
	end
	log.info("boot", "ready")
	return handle
end

local ok, result = pcall(start)
if not ok then
	warn("[uai] failed to start: " .. tostring(result))
	-- A visible failure beats a silent one: the log module may not even have
	-- loaded, so this goes to the console directly.
	--
	-- And on screen too, where the indicator already is: a boot that dies at module
	-- forty leaves a bar stopped at forty and no explanation, which is worse than
	-- never having drawn one. Both the flag and the notice are cleared here, so a
	-- half-loaded client leaves nothing of itself behind.
	env.onModuleLoaded = nil
	env.onMountPhase = nil
	local disposer = loaded["runtime/dispose"]
	if disposer then pcall(disposer.drain) end
	local app = loaded["ui/app"]
	pcall(function() if app and app.screen then app.screen:Destroy() end end)
	local boot = loaded["ui/boot"]
	if boot then pcall(boot.fail, result) end
	return nil
end
return result
